function property_first_deposit_sets_fair_share_price() public {
    // Setup: fresh vault state (before initial deposit in setup)
    // We check that after first deposit, the share price is reasonable
    // i.e., a second depositor with same amounts gets proportional shares

    uint256 shares1 = vault.balanceOf(user);
    uint256 totalShares = vault.totalSupply();

    // A second depositor with identical amounts should get identical shares (minus fees)
    uint256 amt0 = ONE_TOKEN0;   // 1 WBTC
    uint256 amt1 = 100_000 * ONE_TOKEN1; // 100,000 USDC

    (uint256 shares2,,) = _dealAndDeposit(depositor, amt0, amt1);

    // Property: shares2 should be within 1% of shares1 (same deposit, proportional)
    // If the initial share price is biased by decimal mismatch, shares2 will be wrong
    uint256 ratio = shares2 * 100 / shares1;
    // For truly proportional minting with same amounts, ratio should be near 100
    // (accounting for the 1000 burn shares on first deposit)
    t(ratio >= 90 && ratio <= 110, "second depositor receives disproportionate shares vs first depositor");
}

function property_vesting_fees_collected_with_correct_ticks() public {
    // If there's a vesting position, the ticks stored in vestPosition
    // should NOT diverge from the ticks collectFees() actually uses.
    // collectFees uses vestPosition.tickLower but mainPosition.tickUpper.
    // After any rebalance these differ, revealing the bug.
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // The bug: collectFees calls collectPositionFees(vp.tickLower, mp.tickUpper)
    // The fix: should call collectPositionFees(vp.tickLower, vp.tickUpper)
    t(vp.tickUpper == mp.tickUpper,
      "vesting tickUpper diverged from mainPosition tickUpper — collectFees uses wrong ticks");
}

function property_checkPoolActivity_does_not_revert() public view {
    // checkPoolActivity must not revert under normal pool conditions.
    // The off-by-one in the loop index can hit timestamp==0 or div-by-zero.
    bool active = strategy.checkPoolActivity();
    t(active || !active, "checkPoolActivity reverted unexpectedly");
}

function property_secondary_position_valid_ticks() public view {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity > 0) {
        t(sp.tickLower < sp.tickUpper,
          "secondary position tickLower must be strictly less than tickUpper");
    }
}

function property_vesting_position_fees_not_stuck() public {
    if (!strategy.ongoingVestingPosition()) return;
    // After collecting fees, the strategy's idle balance should have increased
    // if the vesting position has accrued any fees. We check the tick ranges match.
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // If these diverge, collectFees is silently skipping the vesting position fees.
    t(
        vp.tickUpper == mp.tickUpper,
        "vesting position tickUpper must equal mainPosition tickUpper for collectFees to work correctly"
    );
}

function property_pullFunds_underlyingBalance_sync() public {
    // Baseline: record underlyingBalance before pullFunds
    // We need to check that after pullFunds + pushFunds round trip, accounting is correct
    // More directly: after pullFunds, the actual token balance in yToken should match
    // what availableLiquidity() reports (they are supposed to represent the same thing)
    address asset = address(token0);
    address yt = yToken0;

    // Get current state
    uint256 actualBalance = token0.balanceOf(yt);
    // availableLiquidity = underlyingBalance (from storage)
    // We can read it via totalLiquidityOfReserve - totalBorrowsOfReserve
    uint256 reportedLiquidity = _getTotalLiquidity(asset) - _getTotalBorrows(asset);

    // After no pullFunds, these should match (assuming no direct donations)
    // The invariant: the actual ERC20 balance in yToken >= underlyingBalance
    // because pullFunds moves tokens but doesn't update underlyingBalance
    // So actual < reported is the BUG
    t(actualBalance >= reportedLiquidity, "underlyingBalance exceeds actual yToken ERC20 balance — accounting desynced");
}

function property_pushFunds_underlyingBalance_sync() public {
    address asset = address(token1);
    address yt = yToken1;

    uint256 pushAmount = 1000 * ONE_TOKEN1;
    // Push funds as leverager (address(this) is leverager)
    _pushFundsAsLeverager(asset, pushAmount);

    uint256 actualBalance = token1.balanceOf(yt);
    // reportedLiquidity = underlyingBalance (storage)
    // totalLiquidityOfReserve includes totalBorrows (which are separate)
    // actual balance in yToken = underlyingBalance + pushAmount (due to bug)
    // but reported uses old underlyingBalance
    // We check: the protocol's exchange rate properly reflects all tokens in yToken
    uint256 totalLiq = _getTotalLiquidity(asset);
    uint256 totalBorrows = _getTotalBorrows(asset);
    uint256 reportedAvailable = totalLiq - totalBorrows;

    // After pushFunds the actual ERC20 balance in yToken should equal reportedAvailable
    // If pushFunds doesn't update underlyingBalance, actual > reported (tokens stranded)
    t(actualBalance <= reportedAvailable + 1, "pushFunds stranded tokens — actual balance exceeds reported available liquidity");
}

function property_pullFunds_no_liquidity_check() public {
    address asset = address(token0);
    // Verify: pullFunds has no check that amount <= availableLiquidity
    // If leverager calls pullFunds with amount > underlyingBalance,
    // the only protection is the ERC20 transfer reverting.
    // But if amount <= actual ERC20 balance (which can differ from underlyingBalance),
    // the call succeeds while underlyingBalance becomes negative (impossible in uint — would underflow).
    // The invariant: underlyingBalance should always reflect actual token holdings.
    uint256 before = _getTotalLiquidity(asset) - _getTotalBorrows(asset);
    uint256 actualBefore = token0.balanceOf(yToken0);
    // These should be equal if accounting is correct
    t(before == actualBefore, "underlyingBalance does not match actual ERC20 balance in yToken before pullFunds");
}

function property_capacity_check_consistent() public {
    address asset = address(token0);
    // After time passes and interest accrues, verify the capacity check doesn't
    // become more restrictive than intended (i.e., blocks deposits when real
    // available capacity exists in terms of principal)
    _skipTime(365 days);
    // Get current total liquidity (includes accrued interest)
    uint256 totalLiqWithInterest = _getTotalLiquidity(asset);
    // Get reserve capacity
    // We can check: if totalLiquidity already > reserveCapacity due to interest,
    // new deposits should still be allowed up to the original cap
    // The property: deposit of 1 wei should not revert purely due to interest inflation
    // We test by trying a tiny deposit and verifying it either succeeds or fails for a real reason
    uint256 tinyAmount = 1;
    token0.mint(depositor, tinyAmount);
    vm.startPrank(depositor);
    token0.approve(address(lendingPool), tinyAmount);
    // This may revert with "dust amount" but should NOT revert with capacity exceeded
    // if real available space exists
    uint256 availableSpace = 0;
    // reserveCapacity is type(uint256).max in setup, so this specific check won't trigger
    // but in production with finite cap this is a real issue
    t(totalLiqWithInterest >= _getTotalBorrows(asset), "total liquidity cannot be less than total borrows");
    vm.stopPrank();
}

function property_redeem_exchange_rate_stable() public {
    address asset = address(token1);
    // The exchange rate should not increase between the start of a redeem and after it completes
    // (i.e., no window where totalSupply is down but underlyingBalance is still up)
    uint256 rateBefore = _getExchangeRate(asset);
    uint256 yBal = _getYTokenBalance(asset, lender);
    if (yBal == 0) return;
    uint256 redeemAmount = yBal / 2;
    if (redeemAmount == 0) return;

    vm.startPrank(lender);
    IERC20(yToken1).approve(address(lendingPool), redeemAmount);
    lendingPool.redeem(asset, redeemAmount, lender);
    vm.stopPrank();

    uint256 rateAfter = _getExchangeRate(asset);
    // Exchange rate should remain stable or slightly increase (due to interest) — never drop
    // A drop would mean accounting went wrong during redeem
    t(rateAfter >= rateBefore, "exchange rate dropped after redeem — accounting error during burn");
}

function property_pause_stops_pullFunds() public {
    // When paused, pullFunds should not be callable
    // Currently pullFunds lacks notPaused modifier
    address asset = address(token0);
    uint256 availBefore = token0.balanceOf(yToken0);

    // Pause the system
    vm.prank(owner);
    lendingPool.emergencyPauseAll();

    // Attempt pullFunds while paused — this should revert but currently doesn't
    uint256 pullAmount = availBefore / 2;
    if (pullAmount == 0) return;

    bool paused = lendingPool.paused();
    t(paused, "system should be paused");

    // After pause, the actual ERC20 balance should be unchanged
    // (pullFunds should have been blocked)
    // We verify the invariant holds: paused system blocks fund movement
    // (This property will FAIL if pullFunds lacks notPaused — demonstrating the bug)
    uint256 availAfter = token0.balanceOf(yToken0);
    t(availAfter == availBefore, "pullFunds bypassed pause — tokens moved during emergency pause");
}

function property_first_depositor_gets_fair_ytokens() public {
    // Deploy fresh pool to test first-deposit scenario
    vm.startPrank(owner);
    LendingPool freshPool = new LendingPool();
    freshPool.initReserve(address(token0));
    vm.stopPrank();

    address freshYToken = freshPool.getYTokenAddress(address(token0));

    // First deposit: 1001 units (just above MINIMUM_YTOKEN_AMOUNT = 1000)
    uint256 depositAmt = MINIMUM_YTOKEN_AMOUNT + 1; // 1001
    token0.mint(lender, depositAmt);
    vm.startPrank(lender);
    token0.approve(address(freshPool), depositAmt);
    freshPool.deposit(address(token0), depositAmt, lender);
    vm.stopPrank();

    uint256 lenderBal = IERC20(freshYToken).balanceOf(lender);
    // Lender deposited 1001, burned 1000 to dead, gets 1 yToken
    // The invariant: first depositor should get yTokens proportional to their deposit
    // minus the burn amount. Getting only 1 yToken for 1001 tokens deposited is unfair.
    // This test shows the dust check doesn't protect the first depositor.
    t(lenderBal > 1, "first depositor received only 1 yToken despite depositing meaningful amount — dust check is pre-burn");
}

function property_repay_accounting_matches_transfer() public {
    address asset = address(token1);
    address yt = yToken1;

    // Borrow some tokens
    uint256 borrowAmt = 10_000 * ONE_TOKEN1;
    _borrowAsLeverager(asset, borrowAmt);

    uint256 actualBefore = token1.balanceOf(yt);
    uint256 reportedBefore = _getTotalLiquidity(asset) - _getTotalBorrows(asset);

    // Repay
    _repayAsLeverager(asset, borrowAmt);

    uint256 actualAfter = token1.balanceOf(yt);
    uint256 reportedAfter = _getTotalLiquidity(asset) - _getTotalBorrows(asset);

    // The change in actual balance should equal the change in reported available liquidity
    uint256 actualIncrease = actualAfter - actualBefore;
    uint256 reportedIncrease = reportedAfter - reportedBefore;

    // With fee-on-transfer tokens, actualIncrease < reportedIncrease
    // With standard ERC20, these should be equal
    t(actualIncrease == reportedIncrease, "repay: actual token received differs from accounting credit — fee-on-transfer tokens break accounting");
}

function property_feeRecipient_is_set() public {
    // If a liquidation fee is configured, feeRecipient must be non-zero.
    // Otherwise fees are sent to address(0) and burned.
    // We just check the invariant: feeRecipient address is always set.
    address fr = leverager.feeRecipient();
    t(fr != address(0), "feeRecipient is address(0): fees will be burned");
}

function property_withdraw_repay_token1_correct() public {
    // Open a USDC-denominated position
    uint256 posId = _openPositionBorrowUsdc(user, ONE_WBTC / 10, 5_000e6, 3_000e6);

    // Get borrowed amount before withdraw
    ILeverager.Position memory posBefore = _getPosition(posId);
    uint256 borrowedBefore = posBefore.borrowedAmount;
    t(borrowedBefore > 0, "position should have borrow");

    // Perform full withdraw
    uint256 usdcBefore = usdc.balanceOf(user);
    _withdrawPositionFull(user, posId);
    uint256 usdcAfter = usdc.balanceOf(user);

    // After full withdrawal, position must not exist
    t(!_positionExists(posId), "position should be deleted after full withdraw");

    // The USDC net balance of user should be non-negative
    // (they may pay some due to interest but should not pay drastically more
    //  than the borrowed amount)
    // If the wrong variable bug fires, the user pays amountOut0 (WBTC-scaled)
    // which would be an absurdly large number causing revert or wrong accounting
    t(true, "withdraw completed without revert - basic sanity");
}

function property_liquidation_fee_collected() public {
    // Set up a liquidateable position
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC / 10, 5_000e6, ONE_WBTC / 20);

    // Set liquidation fee
    vm.prank(owner);
    leverager.setLiquidationFee(500); // 5%

    // Drop price to make position liquidateable
    vm.prank(owner);
    wbtcOracle.setPrice(INIT_WBTC_PRICE / 4); // 75% price drop

    t(leverager.isLiquidateable(posId), "position should be liquidateable");

    // Record feeRecipient balance before (would need feeRecipient set)
    // This property checks the borrowedValue computation is correct
    // If bug exists, totalValueUSD <= inflated borrowedValue, fee never paid.
    // We can only test this indirectly by checking liquidation completes.
    _liquidatePosition(liquidator, posId);
    t(!_positionExists(posId), "position should be deleted after liquidation");
}

function property_no_residual_drain_via_open() public {
    // If attacker opens a position, they should not gain more tokens
    // than they put in (minus fees/slippage).
    uint256 attackerWbtcBefore = wbtc.balanceOf(attacker);
    uint256 attackerUsdcBefore = usdc.balanceOf(attacker);

    // Seed some residual tokens into the leverager (simulating dust)
    deal(address(wbtc), address(leverager), ONE_WBTC / 100);
    uint256 residual = wbtc.balanceOf(address(leverager));

    // Attacker opens position - sweepTokens will give them the residual
    uint256 posId = _openPositionBorrowUsdc(attacker, ONE_WBTC / 10, 5_000e6, 3_000e6);

    uint256 attackerWbtcAfter = wbtc.balanceOf(attacker);
    // Attacker should not gain the residual WBTC
    lte(attackerWbtcAfter, attackerWbtcBefore, "attacker should not gain residual wbtc via sweep");
}

function property_initVault_not_reinitializable() public {
    // Check that initVault cannot be called twice on same vault
    // (even after toggling leverage off)
    bool leverageEnabled = _getVaultLeverageEnabled();
    t(leverageEnabled, "leverage should be enabled after setUp");

    // Toggle off - this makes leverageEnabled = false
    vm.prank(owner);
    leverager.toggleVaultLeverage(address(vault));

    bool afterToggle = _getVaultLeverageEnabled();
    t(!afterToggle, "leverage should be disabled after toggle");

    // Now initVault can be called again (bypassing the "already enabled" guard)
    // This is the bug: should revert but won't
    vm.prank(owner);
    try leverager.initVault(address(vault), 999e18, 10e18, 0.5e18, 1e27) {
        // If we get here, re-initialization succeeded — that's the vulnerability
        t(false, "initVault should not be callable after toggle-disable");
    } catch {
        // Expected: should revert
        t(true, "initVault correctly reverted on re-init attempt");
    }
}

function property_collectFees_no_reentrant_before_lock() public {
    // This property validates that the modifier ordering does not allow
    // double-execution of liquidation for same position.
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC / 10, 5_000e6, ONE_WBTC / 20);

    vm.prank(owner);
    wbtcOracle.setPrice(INIT_WBTC_PRICE / 4);

    t(leverager.isLiquidateable(posId), "position should be liquidateable");

    _liquidatePosition(liquidator, posId);

    // Position must not exist after single liquidation
    t(!_positionExists(posId), "position should not exist after liquidation");

    // Attempting to liquidate again must revert
    vm.prank(liquidator);
    ILeverager.LiquidateParams memory liqParams;
    liqParams.id = posId;
    try leverager.liquidatePosition(liqParams) {
        t(false, "second liquidation of same position should revert");
    } catch {
        t(true, "second liquidation correctly reverted");
    }
}

function property_vesting_fees_collected_from_correct_position() public {
    // Only meaningful if there is an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The collectFees() call uses mainPosition.tickUpper for the vesting position's upper tick.
    // After a rebalance this can diverge from vestPosition.tickUpper.
    // Property: the ticks used to collect vesting fees must match the vesting position ticks.
    // We check that mainPosition.tickUpper == vestPosition.tickUpper; if not, collectFees is broken.
    t(
        mp.tickUpper == vp.tickUpper,
        "mainPosition.tickUpper != vestPosition.tickUpper: collectFees uses wrong position key"
    );
}

function property_vesting_liquidity_conservation() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // remainingLiquidity should always be <= initialLiquidity
    lte(
        uint256(vp.remainingLiquidity),
        uint256(vp.initialLiquidity),
        "remainingLiquidity exceeds initialLiquidity"
    );

    // If vesting has ended, ongoingVestingPosition should be false
    if (block.timestamp >= vp.endTs) {
        t(!strategy.ongoingVestingPosition(), "vesting should have ended");
    }
}

function property_checkPoolActivity_does_not_revert() public view returns (bool) {
    // If this reverts, the property fails implicitly via forge's revert detection.
    // We just call it and assert it returns a bool without reverting.
    bool result = strategy.checkPoolActivity();
    // result can be true or false — we only care it doesn't revert
    t(true, "checkPoolActivity should not revert");
    return result;
}

function property_callback_cannot_be_called_externally() public {
    uint256 bal0Before = token0.balanceOf(address(strategy));
    uint256 bal1Before = token1.balanceOf(address(strategy));

    // attacker tries to call the callback directly
    vm.prank(attacker);
    (bool success,) = address(strategy).call(
        abi.encodeWithSignature("uniswapV3MintCallback(uint256,uint256,bytes)", bal0Before, bal1Before, "")
    );

    // Should revert because attacker is not the pool
    t(!success, "uniswapV3MintCallback should not be callable by attacker");
}

function property_secondary_ticks_valid() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    // Secondary position must have tickLower < tickUpper for a valid Uniswap position
    if (sp.liquidity > 0 || sp.tickLower != 0 || sp.tickUpper != 0) {
        t(
            sp.tickLower < sp.tickUpper,
            "secondary position has tickLower >= tickUpper: invalid Uniswap position"
        );
    }
}

function property_strategy_approval_bounded() public view {
    uint256 approval0 = token0.allowance(address(strategy), address(vault));
    uint256 approval1 = token1.allowance(address(strategy), address(vault));

    // The infinite approval means the vault can drain everything at any time.
    // This property documents the risk: if vault is malicious, strategy is drained.
    // We check current token balances are still intact (not actively being drained).
    (uint256 bal0, uint256 bal1) = strategy.balances();
    // If approval equals max uint256, the vault has unrestricted access
    t(
        approval0 == type(uint256).max || approval0 >= bal0,
        "token0 approval less than balance: unexpected approval state"
    );
    t(
        approval1 == type(uint256).max || approval1 >= bal1,
        "token1 approval less than balance: unexpected approval state"
    );
}

function property_lh01_vesting_fees_collected() public {
    // Setup: vesting position exists. After collectFees, vault's token balance should
    // equal or exceed what balances() reports (fees absorbed into idle).
    // If wrong tick is used, vesting fees never flow into idle balances.
    // We verify that calling collectFees does not silently discard non-zero vesting fees.
    bool hasVesting = strategy.ongoingVestingPosition();
    if (!hasVesting) return;

    // Record idle balances before and after collectFees
    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // If vestingPosition has liquidity that has accrued fees, collectFees should increase idle.
    // We can't directly assert fees > 0 without knowing the fee state, but we can
    // assert that the balances() view is consistent with the actual idle + positions.
    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    // balances() does not include vesting position, so idle0 <= bal0 and idle1 <= bal1
    lte(idle0, bal0 + 1, "idle0 exceeds reported balances");
    lte(idle1, bal1 + 1, "idle1 exceeds reported balances");

    // The key invariant: idle balances should not decrease after collectFees
    gte(idle0After, idle0Before, "idle0 decreased after collectFees");
    gte(idle1After, idle1Before, "idle1 decreased after collectFees");
}

function property_lh02_first_deposit_share_symmetry() public {
    // If two users deposit the same economic value (same token0 and token1 amounts),
    // they should receive the same number of shares, regardless of deposit order
    // on a freshly deployed vault. This property checks that the initial share
    // formula does not create an asymmetric share price.
    //
    // After the setup, user has already deposited. We verify that
    // a subsequent depositor with proportional amounts gets proportional shares.
    uint256 totalSupplyBefore = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = vault.balances();

    // Deposit proportional amounts
    uint256 amt0 = ONE_TOKEN0; // 1 WBTC
    uint256 amt1 = ONE_TOKEN1 * 60000; // 60000 USDC

    deal(address(wbtc), depositor, amt0);
    deal(address(usdc), depositor, amt1);
    vm.startPrank(depositor);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    (uint256 shares,,) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    // Shares should be proportional to the vault's existing balance
    // shares / totalSupply = min(amt0/bal0, amt1/bal1)
    // Verify shares > 0
    t(shares > 0, "depositor received 0 shares");

    // Verify depositor can withdraw their shares for at least some tokens
    vm.prank(depositor);
    (uint256 w0, uint256 w1) = vault.withdraw(shares, 0, 0);
    t(w0 > 0 || w1 > 0, "depositor withdrew nothing");
}

function property_lh03_balances_includes_all_assets() public {
    // If there is an ongoing vesting position, the sum of tokens that could be
    // withdrawn by ALL shareholders should not exceed what balances() reports
    // by more than the vesting position size. Specifically, total withdrawable
    // should be >= balances() (the vesting position is extra, not missing).
    bool hasVesting = strategy.ongoingVestingPosition();
    if (!hasVesting) return;

    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 totalShares = vault.totalSupply();

    // Try to compute what a full withdrawal of all shares would yield
    // by checking: shares * bal0 / totalShares <= actual token0 in strategy
    uint256 actualToken0 = wbtc.balanceOf(address(strategy));
    uint256 actualToken1 = usdc.balanceOf(address(strategy));

    // reported balances should not exceed actual holdings
    // (vesting pos is in pool, not in strategy balance, so this won't catch it directly)
    // The real test: balances() < true total assets when vesting position exists
    // We proxy this by checking that depositing now and immediately withdrawing
    // returns at least 99% of deposit value.
    uint256 depositAmt0 = ONE_TOKEN0;
    uint256 depositAmt1 = ONE_TOKEN1 * 60000;
    deal(address(wbtc), attacker, depositAmt0);
    deal(address(usdc), attacker, depositAmt1);
    vm.startPrank(attacker);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    (uint256 shares,,) = vault.deposit(depositAmt0, depositAmt1, 0, 0);
    (uint256 w0, uint256 w1) = vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    // With a large vesting position, attacker would get back MORE than deposited
    // because balances() underreports total assets, giving too many shares
    // This property asserts attacker does not extract more than deposited + 1%
    lte(w0, depositAmt0 * 101 / 100, "attacker extracted excess token0 via inflated shares");
    lte(w1, depositAmt1 * 101 / 100, "attacker extracted excess token1 via inflated shares");
}

function property_lh07_no_permanent_fee_loss() public {
    // After the vesting position fully expires and ongoingVestingPosition becomes false,
    // the vault's total balances should not be less than what was deposited originally
    // (accounting for fees going to feeRecipient). This checks no value is permanently lost.
    bool hasVesting = strategy.ongoingVestingPosition();
    if (hasVesting) return; // only check after vesting ends

    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 totalSupply = vault.totalSupply();

    // Every share should still be redeemable for tokens
    t(totalSupply == 0 || (bal0 > 0 || bal1 > 0), "vault has shares but no assets after vesting ended");

    // The burn address (1337) has BURN_SEED_SHARES (1000) shares, verify they are backed
    uint256 burnShares = vault.balanceOf(BURN_ADDRESS);
    if (burnShares > 0 && totalSupply > 0) {
        uint256 expectedBal0 = bal0 * burnShares / totalSupply;
        uint256 expectedBal1 = bal1 * burnShares / totalSupply;
        // BURN address shares should be backed by real assets
        t(expectedBal0 > 0 || expectedBal1 > 0, "burn address shares not backed by assets");
    }
}

function property_withdraw_token1_repay_uses_correct_balance() public {
    // Open a position borrowing USDC (token1)
    uint256 posId = _openPositionBorrowUsdc(user, 1e8, 100_000e6, 50_000e6);

    // Record user USDC balance before withdraw
    uint256 userUsdcBefore = usdc.balanceOf(user);

    // Partial withdraw 50%
    _withdrawPositionPartial(user, posId, 0.5e18);

    uint256 userUsdcAfter = usdc.balanceOf(user);

    // The user's USDC should have INCREASED (net withdrawal after repay),
    // not decreased (which would happen if amountOut0 was used incorrectly).
    // If the bug triggers and amountOut0 == 0, user loses USDC paying the full owed amount
    // from wallet while also losing their amountOut1 proceeds to the contract.
    // This property checks user ends up net positive on USDC after partial withdraw.
    t(userUsdcAfter >= userUsdcBefore, "user USDC decreased on partial withdraw of token1 position");
}

function property_liquidation_fee_collected_when_solvent() public {
