function property_wc01_underlying_balance_matches_yttoken_actual() public {
    // After a pullFunds+pushFunds cycle, underlyingBalance should not exceed
    // the actual token balance held by the yToken contract.
    // If underlyingBalance > actual yToken balance, lenders cannot redeem in full.
    address asset = address(token0);
    uint256 underlyingBal = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    // availableLiquidity = underlyingBalance = totalLiquidity - totalBorrows
    // We check that actual token balance in yToken >= reported availableLiquidity
    uint256 reportedAvail = underlyingBal > totalBorrows ? underlyingBal - totalBorrows : 0;
    uint256 actualBal = token0.balanceOf(yToken0);
    gte(actualBal, reportedAvail, "WC-01: yToken actual balance < reported available liquidity");
}

function property_wc02_push_funds_updates_accounting() public {
