function property_wc03_borrow_then_repay_same_block_accrues_interest() public {
    address asset = address(token2);
    uint256 borrowAmt = 10 * ONE_TOKEN2;
    // Record borrowing index before
    uint256 indexBefore = lendingPool.getCurrentBorrowingIndex(asset);
    // Borrow then repay in same block (no skip)
    lendingPool.borrow(asset, borrowAmt);
    // Repay immediately in same block
    lendingPool.repay(asset, borrowAmt);
    // After repay, get the current index; it should have increased if interest was accrued.
    // With same-block borrow+repay, index stays the same -> zero interest paid.
    // The property: if borrow>0 happened, repay in same block should still accrue SOME interest.
    // We can check via total liquidity: lenders should not lose value.
    uint256 totalLiqAfter = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalLiqBefore = 100 * ONE_TOKEN2; // seeded in setup
    // After borrow+repay same block, total liquidity should be >= before (interest earned)
    // but with same-block accrual bug it is EXACTLY equal, no interest earned
    gte(totalLiqAfter, totalLiqBefore, "WC-03: lenders lost value from same-block borrow+repay");
}

function property_wc04_pull_funds_updates_interest_rate() public {
    address asset = address(token1);
    uint256 pullAmt = 50_000 * ONE_TOKEN1;
    // Borrow to set non-zero utilization rate first
    uint256 borrowAmt = 80_000 * ONE_TOKEN1;
    lendingPool.borrow(asset, borrowAmt);
    // Capture rate after borrow (already reflects 80% utilization)
    uint256 rateAfterBorrow = lendingPool.borrowingRateOfReserve(asset);
    // Now pullFunds takes the remaining available liquidity
    lendingPool.pullFunds(asset, pullAmt);
    // After pulling ALL remaining liquidity, utilization should be effectively 100%
    // and rate should be maxBorrowingRate (150% APY = 1.5e27)
    uint256 rateAfterPull = lendingPool.borrowingRateOfReserve(asset);
    // Because pullFunds does not update interest rates, rateAfterPull == rateAfterBorrow
    // (stale). The property: pulling all remaining liquidity should increase the rate.
    gte(rateAfterPull, rateAfterBorrow, "WC-04: borrowing rate not updated after pullFunds");
}

function property_wc05_leverager_cannot_drain_pool() public {
    address asset = address(token0);
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(asset);
    // Leverager (this contract in setup) pulls ALL available liquidity
    uint256 availAmt = token0.balanceOf(yToken0);
    if (availAmt == 0) return;
    lendingPool.pullFunds(asset, availAmt);
    // After pulling all funds, actual yToken balance is 0
    // but underlyingBalance was NOT decremented
    uint256 actualBal = token0.balanceOf(yToken0);
    // A lender should still be able to redeem their share
    // (this will revert in practice due to WC-01 bug)
    uint256 lenderYBal = IERC20(yToken0).balanceOf(lender);
    if (lenderYBal > 0) {
        uint256 exchangeRate = lendingPool.exchangeRateOfReserve(asset);
        uint256 expectedUnderlying = exchangeRate * lenderYBal / PRECISION;
        // After drain, lender should NOT be able to withdraw (no tokens in yToken)
        // The pool invariant: actual balance >= what lenders can claim
        gte(actualBal, expectedUnderlying, "WC-05: pool drained, lender cannot redeem");
    }
}

function property_wc07_no_phantom_liquidity() public {
