    // Measure what the pool CLAIMS is available vs what is actually in yToken
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrow = lendingPool.totalBorrowsOfReserve(asset);
    uint256 claimedAvail = totalLiq > totalBorrow ? totalLiq - totalBorrow : 0;
    uint256 actualInYToken = token0.balanceOf(yToken0);
    // The actual balance in yToken should be >= claimed available (not less)
    // If someone donated tokens directly, actualInYToken > claimedAvail (fine, undercount)
    // If pullFunds was called without pushFunds, actualInYToken < claimedAvail (DANGEROUS)
    gte(actualInYToken, claimedAvail, "WC-07: underlyingBalance overstates actual yToken holdings");
}

function property_liquidation_fee_recipient_not_zero() public {
    // If a liquidation fee is set, feeRecipient must be initialized,
    // otherwise safeTransfer to address(0) bricks all profitable liquidations.
    // Open a position and try to liquidate it.
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC, 0, 0);

    // Owner sets fee but never sets feeRecipient (it stays address(0))
    vm.prank(owner);
    leverager.setLiquidationFee(500);

    // Drop WBTC price to make position liquidatable
    wbtcOracle.setPrice(1_000e18); // crash price
    usdcOracle.setPrice(INIT_USDC_PRICE);

    bool liq = leverager.isLiquidateable(posId);
    if (!liq) return; // position not liquidatable yet, skip

    // Liquidation should succeed — if feeRecipient is address(0), it will revert
    vm.startPrank(liquidator);
    deal(address(wbtc), liquidator, 20e8);
    deal(address(usdc), liquidator, 2_000_000e6);
    wbtc.approve(address(leverager), type(uint256).max);
    usdc.approve(address(leverager), type(uint256).max);

    ILeverager.LiquidateParams memory liqParams;
    liqParams.id = posId;

    bool success;
    try leverager.liquidatePosition(liqParams) {
        success = true;
    } catch {
        success = false;
    }
    vm.stopPrank();

    // Property: liquidation must not revert due to zero feeRecipient
    address fr = leverager.feeRecipient();
    t(fr != address(0) || success, "liquidation bricked: feeRecipient is address(0) with non-zero fee");
}

