function property_liquidation_fee_collected_when_profitable() public {
    // Open a position, make it liquidatable, liquidate, verify protocol received fees.
    vm.prank(owner);
    leverager.setLiquidationFee(500); // 5% fee

    // Set a valid feeRecipient first
    // (workaround: the feeRecipient state var is public, but setter doesn't exist in interface)
    // We check: after liquidation, feeRecipient balance should increase if profitable.

    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC / 5, 20_000e6, 2_000e6);
    if (!_positionExists(posId)) return;

    // Crash WBTC price slightly to trigger liquidation
    wbtcOracle.setPrice(10_000e18);

    bool liq = leverager.isLiquidateable(posId);
    if (!liq) return;

    address fr = leverager.feeRecipient();
    if (fr == address(0)) return; // skip if fee recipient not set

    uint256 frBalBefore = wbtc.balanceOf(fr) + usdc.balanceOf(fr);

    vm.startPrank(liquidator);
    deal(address(wbtc), liquidator, 20e8);
    deal(address(usdc), liquidator, 2_000_000e6);
    wbtc.approve(address(leverager), type(uint256).max);
    usdc.approve(address(leverager), type(uint256).max);

    ILeverager.LiquidateParams memory liqParams;
    liqParams.id = posId;
    leverager.liquidatePosition(liqParams);
    vm.stopPrank();

    uint256 frBalAfter = wbtc.balanceOf(fr) + usdc.balanceOf(fr);

    // Fee recipient should have received tokens (borrowedValue calculation is wrong otherwise)
    t(frBalAfter > frBalBefore, "protocol earned zero fees despite profitable liquidation — decimals bug in borrowedValue");
}

