function property_underlying_balance_equals_actual_balance() public {
    address asset = address(token1);
    address yt = lendingPool.getYTokenAddress(asset);

    // Trigger a pull and push cycle
    uint256 pullAmt = ONE_TOKEN1 * 1000;
    _pullFundsAsLeverager(asset, pullAmt);
    _pushFundsAsLeverager(asset, pullAmt);

    // After round-trip, tracked underlyingBalance should equal actual balance
    uint256 actualBal = token1.balanceOf(yt);
    (,,,,,,,, uint256 ub,,) = lendingPool.reserves(asset);

    // Allow small tolerance for interest accrual rounding but not large gaps
    // underlyingBalance should not exceed actual balance by more than 1 wei
    // (tracked accounting should be conservative — never overclaim)
    lte(ub, actualBal + 1, "underlyingBalance must not exceed actual yToken balance");
}

/// @notice Solvency invariant: actual token balance in yToken must equal
///         reserve.underlyingBalance (== totalLiquidity - totalBorrows).
///         pullFunds() breaks this: actual < underlyingBalance (phantom liquidity).
///         The subtraction totalLiquidity - totalBorrows cancels the interest terms
///         exactly, giving underlyingBalance, so this check is rounding-exact.
function prop_001_solvency_underlying_eq_accounted_token0() public view returns (bool) {
    uint256 actual      = _getUnderlyingInYToken(address(token0));
    uint256 totalLiq    = _getTotalLiquidity(address(token0));
    uint256 totalBorrow = _getTotalBorrows(address(token0));
    // totalLiq - totalBorrow == underlyingBalance (exact, interest terms cancel)
    // actual should equal underlyingBalance; pullFunds makes actual < underlyingBalance
    return actual + totalBorrow == totalLiq;
}

function prop_002_solvency_all_three_reserves() public view returns (bool) {
    address[3] memory assets = [address(token0), address(token1), address(token2)];
    for (uint256 i = 0; i < 3; i++) {
        address asset   = assets[i];
        uint256 actual  = _getUnderlyingInYToken(asset);
        uint256 liq     = _getTotalLiquidity(asset);
        uint256 borrows = _getTotalBorrows(asset);
        // actual + borrows must equal totalLiquidity exactly
        if (actual + borrows != liq) return false;
    }
    return true;
}

/// @notice Mirror of H001: actual balance must not EXCEED underlyingBalance.
///         pushFunds makes actual > underlyingBalance, locking tokens permanently.
///         Combined with H001 (>=), this tight equality catches both directions.
function prop_003_no_excess_tokens_in_ytoken_token1() public view returns (bool) {
    uint256 actual  = _getUnderlyingInYToken(address(token1));
    uint256 liq     = _getTotalLiquidity(address(token1));
    uint256 borrows = _getTotalBorrows(address(token1));
    // actual must not exceed underlyingBalance either
    // (pushFunds makes actual > underlyingBalance → actual + borrows > liq)
    return actual + borrows == liq;
}

/// @notice When the protocol is paused, pullFunds should revert.
///         This property demonstrates the missing notPaused modifier.
///         Returns false (violation) if pullFunds succeeds while paused.
function prop_004_pullFunds_reverts_when_paused() public returns (bool) {
    // Ensure there is something to pull
    uint256 bal = _getUnderlyingInYToken(address(token0));
    if (bal == 0) return true; // nothing to test

    // Pause the protocol as owner
    vm.prank(owner);
    lendingPool.emergencyPauseAll();

    bool succeeded = false;
    try lendingPool.pullFunds(address(token0), 1) {
        succeeded = true;
    } catch {}

    // Restore state regardless
    vm.prank(owner);
    lendingPool.unPauseAll();

    // pullFunds should have reverted (succeeded == false means correct behaviour)
    // returning false means the invariant IS violated (pullFunds worked while paused)
    return !succeeded;
}

/// @notice When paused, pushFunds should revert (no notPaused guard means it won't).
///         Returns false if pushFunds succeeds while paused.
function prop_005_pushFunds_reverts_when_paused() public returns (bool) {
    vm.prank(owner);
    lendingPool.emergencyPauseAll();

    bool succeeded = false;
    token0.mint(address(this), 1);
    try lendingPool.pushFunds(address(token0), 1) {
        succeeded = true;
    } catch {}

    vm.prank(owner);
    lendingPool.unPauseAll();

    return !succeeded;
}

/// @notice pullFunds should revert on a frozen reserve.
///         Returns false if pullFunds succeeds on a frozen reserve (bug present).
function prop_006_pullFunds_reverts_when_frozen() public returns (bool) {
    uint256 bal = _getUnderlyingInYToken(address(token1));
    if (bal == 0) return true;

    vm.prank(owner);
    lendingPool.freezeReserve(address(token1));

    bool succeeded = false;
    try lendingPool.pullFunds(address(token1), 1) {
        succeeded = true;
    } catch {}

    vm.prank(owner);
    lendingPool.unFreezeReserve(address(token1));

    // succeeded == true means the frozen check was bypassed (invariant violated)
    return !succeeded;
}

/// @notice After any sequence of operations, the tokens that have left the yToken
///         vault without being tracked as borrows must be zero.
///         Formally: actual_balance + totalBorrows == totalLiquidity.
///         pullFunds violates this by extracting without incrementing totalBorrows.
function prop_007_no_untracked_token_extraction_token2() public view returns (bool) {
    uint256 actual  = _getUnderlyingInYToken(address(token2));
    uint256 liq     = _getTotalLiquidity(address(token2));
    uint256 borrows = _getTotalBorrows(address(token2));
    // If tokens left via pullFunds: actual < liq - borrows == underlyingBalance
    // If tokens entered via pushFunds: actual > liq - borrows
    // Both violations caught by equality
    return actual + borrows == liq;
}

/// @notice Total redemption obligations (totalYTokenSupply * exchangeRate / PRECISION)
///         must not exceed the sum of actual vault balance + totalBorrows.
///         After pullFunds, exchangeRate is inflated so obligations > actual backing.
function prop_008_exchange_rate_fully_backed_token0() public view returns (bool) {
    uint256 totalYTokens = _getYTokenTotalSupply(address(token0));
    if (totalYTokens == 0) return true;

    uint256 exchangeRate = _getExchangeRate(address(token0)); // yToken → underlying
    // Total underlying owed to all yToken holders
    uint256 totalObligations = totalYTokens * exchangeRate / PRECISION;

    // Total underlying actually available (vault balance + outstanding borrows)
    uint256 actualVault  = _getUnderlyingInYToken(address(token0));
    uint256 totalBorrows = _getTotalBorrows(address(token0));
    uint256 totalBacking = actualVault + totalBorrows;

    // Obligations should not exceed backing (allow 1 wei rounding tolerance)
    return totalObligations <= totalBacking + 1;
}

/// @notice The original lender must always be able to redeem their full yToken balance.
///         If the vault was drained (pullFunds bug), this will fail.
function prop_009_lender_can_redeem_full_balance_token0() public returns (bool) {
    uint256 lenderYBal = _getYTokenBalance(address(token0), lender);
    if (lenderYBal == 0) return true;

    uint256 exchangeRate = _getExchangeRate(address(token0));
    uint256 owedUnderlying = lenderYBal * exchangeRate / PRECISION;

    // The vault must hold at least the owed amount
    uint256 vaultBalance = _getUnderlyingInYToken(address(token0));

    // If vault < owed, lender's redeem would revert (not enough liquidity)
    return vaultBalance >= owedUnderlying;
}

/// @notice underlyingBalance must equal the actual vault token balance.
///         Any divergence (from pullFunds or pushFunds) corrupts ALL reserve metrics.
///         Directly checks the stale-oracle condition for token1.
function prop_010_underlyingBalance_not_stale_token1() public view returns (bool) {
    uint256 actualVault  = _getUnderlyingInYToken(address(token1));
    uint256 totalLiq     = _getTotalLiquidity(address(token1));
    uint256 totalBorrows = _getTotalBorrows(address(token1));
    // totalLiq - totalBorrows == underlyingBalance (interest cancels exactly)
    uint256 accountedBalance = totalLiq - totalBorrows;
    // If pullFunds ran: actualVault < accountedBalance
    // If pushFunds ran: actualVault > accountedBalance
    return actualVault == accountedBalance;
}

/// @notice After pullFunds, the reduction in yToken vault balance must be
///         reflected in either increased totalBorrows OR decreased totalLiquidity.
///         Equivalently: vault_balance_change + borrow_change must be zero.
///         pullFunds breaks both: vault decreases but neither metric changes.
function prop_011_token_flow_conservation_token0() public view returns (bool) {
    // Conservation: tokens_in_vault + tokens_borrowed = constant (modulo interest)
    // total liquidity = underlyingBalance + totalBorrows_with_interest
    // actual_vault + totalBorrows_with_interest should equal totalLiquidity
    uint256 actual  = _getUnderlyingInYToken(address(token0));
    uint256 liq     = _getTotalLiquidity(address(token0));
    uint256 borrows = _getTotalBorrows(address(token0));
    return actual + borrows == liq;
}

/// @notice repay() with no active borrows must not change any meaningful state.
///         totalLiquidity, totalBorrows, and vault balance must be unchanged.
function prop_012_repay_no_op_when_no_borrows_token2() public returns (bool) {
    uint256 borrows = _getTotalBorrows(address(token2));
    if (borrows > 0) return true; // only test when no borrows outstanding

    uint256 liqBefore   = _getTotalLiquidity(address(token2));
    uint256 vaultBefore = _getUnderlyingInYToken(address(token2));

    // repay with large amount — should be clamped to totalBorrows (0)
    lendingPool.repay(address(token2), type(uint256).max / 2);

    uint256 liqAfter   = _getTotalLiquidity(address(token2));
    uint256 vaultAfter = _getUnderlyingInYToken(address(token2));

    return liqBefore == liqAfter && vaultBefore == vaultAfter;
}

function property_fullmath_mulDiv_correct() public {
    // Test the 512-bit path (prod1 != 0):
    // Choose a = type(uint128).max, b = type(uint128).max + 1
    // so that a*b > 2^256, triggering prod1 != 0
    // The expected result of mulDiv(a, b, b) should equal a.
    uint256 a = type(uint128).max; // 2^128 - 1
    uint256 b = type(uint128).max; // 2^128 - 1
    uint256 denom = type(uint128).max; // same as b

    // mulDiv(a, b, denom) should equal a when denom == b
    // i.e. (a * b) / b == a
    // but with the XOR bug, the 512-bit path returns garbage
    // This will NOT overflow since a*b = (2^128-1)^2 < 2^256, just barely.
    // To force prod1 != 0 we need a bigger product.

    // Use values where a*b causes prod1 != 0:
    uint256 bigA = 2 ** 200;
    uint256 bigB = 2 ** 200;
    uint256 bigDenom = 2 ** 100; // result = 2^300 / 2^100 = 2^200 = bigA

    // If mulDiv is correct, result should be bigA
    // With the XOR bug in the 512-bit path, result is wrong
    // We can't call FullMath directly from Setup, but we can observe
    // that the price() function calls mulDiv. Check price is nonzero and
    // consistent with twapPrice (both use the same mulDiv).
    uint256 spotPrice = vault.price();
    uint256 twap = vault.twapPrice();
    // prices should be in the same order of magnitude (within 10x)
    // if mulDiv is broken for these inputs, prices would be wildly off
    t(spotPrice > 0, "spot price should be nonzero");
    t(twap > 0, "twap price should be nonzero");
    // If XOR bug corrupts mulDiv, these could be very different:
    // (this is a weak check; a direct unit test is more definitive)
    uint256 ratio = spotPrice > twap ? spotPrice / twap : twap / spotPrice;
    lte(ratio, 10, "spot and twap price should be within 10x of each other");
}

function property_balances_include_all_positions() public {
    // If there's an ongoing vesting position, total balances reported by
    // vault.balances() should account for the vesting position tokens too.
    // In the current code, balances() in Strategy omits vestingPosition.
    // We test: after addVestingPosition is called, reported balances
    // should be >= balances before (since more tokens were added).
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();

    // owner adds vesting position with fresh tokens
    deal(address(wbtc), owner, ONE_TOKEN0 * 10);
    deal(address(usdc), owner, ONE_TOKEN1 * 100_000);
    vm.startPrank(owner);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    vault.addVestingPosition(ONE_TOKEN0 * 10, ONE_TOKEN1 * 100_000, 30 days);
    vm.stopPrank();

    (uint256 bal0After, uint256 bal1After) = vault.balances();

    // After adding vesting position with extra tokens, reported balances
    // should have increased. If they didn't, the vesting position is hidden
    // from balances(), proving the accounting gap.
    t(
        bal0After >= bal0Before || bal1After >= bal1Before,
        "Balances should increase after addVestingPosition"
    );
}

function property_deposit_amounts_not_exceed_desired() public {
    // A depositor who specifies desired amounts should never have more
    // than the desired amounts pulled from them.
    uint256 desiredAmt0 = ONE_TOKEN0;
    uint256 desiredAmt1 = ONE_TOKEN1 * 1000;
    deal(address(wbtc), depositor, desiredAmt0 + 10);
    deal(address(usdc), depositor, desiredAmt1 + 10);

    uint256 pre0 = wbtc.balanceOf(depositor);
    uint256 pre1 = usdc.balanceOf(depositor);

    vm.prank(depositor);
    (, uint256 d0, uint256 d1) = vault.deposit(desiredAmt0, desiredAmt1, 0, 0);

    uint256 post0 = wbtc.balanceOf(depositor);
    uint256 post1 = usdc.balanceOf(depositor);

    uint256 actual0 = pre0 - post0;
    uint256 actual1 = pre1 - post1;

    // depositor should never pay more than desired
    lte(actual0, desiredAmt0, "token0 taken exceeds desired");
    lte(actual1, desiredAmt1, "token1 taken exceeds desired");
    // deposited amounts returned should match actually taken
    eq(actual0, d0, "reported d0 must match actual token0 taken");
    eq(actual1, d1, "reported d1 must match actual token1 taken");
}

function property_withdraw_atomic() public {
    // After a successful withdraw, user's shares decrease AND
    // token balance increases. If withdrawal fails mid-way,
    // shares should be restored (i.e., no net change in either).
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 sharesToWithdraw = userShares / 2;
    if (sharesToWithdraw == 0) return;

    uint256 pre0 = wbtc.balanceOf(user);
    uint256 pre1 = usdc.balanceOf(user);
    uint256 preShares = vault.balanceOf(user);

    vm.prank(user);
    (uint256 w0, uint256 w1) = vault.withdraw(sharesToWithdraw, 0, 0);

    uint256 post0 = wbtc.balanceOf(user);
    uint256 post1 = usdc.balanceOf(user);
    uint256 postShares = vault.balanceOf(user);

    // shares should have decreased by exactly sharesToWithdraw
    eq(preShares - postShares, sharesToWithdraw, "shares burned must equal requested");
    // tokens received should match what withdraw reported
    eq(post0 - pre0, w0, "token0 balance increase must match withdraw return");
    eq(post1 - pre1, w1, "token1 balance increase must match withdraw return");
    // no tokens should be left in vault (vault is just a router)
    eq(wbtc.balanceOf(address(vault)), 0, "vault should hold no wbtc after withdraw");
    eq(usdc.balanceOf(address(vault)), 0, "vault should hold no usdc after withdraw");
}

function property_vesting_position_fully_unwinds() public {
    // After vesting period ends and collectFees is called,
    // the vesting position should have zero remaining liquidity.
    // We test: after endTs, any call to collectFees clears it.

    // Get current vesting state
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.endTs == 0 || vp.remainingLiquidity == 0) return;

    // Warp past vesting end
    vm.warp(vp.endTs + 1);

    // Trigger collectFees (deposit is simplest way)
    deal(address(wbtc), depositor, ONE_TOKEN0);
    deal(address(usdc), depositor, ONE_TOKEN1 * 1000);
    vm.prank(depositor);
    vault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 1000, 0, 0);

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(vpAfter.remainingLiquidity, 0, "Vesting position should be fully withdrawn after endTs");
}

function property_first_deposit_shares_proportional() public {
    // Shares minted on first deposit should be nonzero and meaningful.
    // The specific check: depositing 1 wei of token0 and large token1
    // should not give wildly more shares than depositing equal value.

    // This property checks that after the first deposit, totalSupply > 0
    // and that the share/token ratios are internally consistent.
    uint256 totalShares = vault.totalSupply();
    t(totalShares > 0, "totalSupply should be nonzero after setup deposit");

    (uint256 bal0, uint256 bal1) = vault.balances();
    t(bal0 > 0 || bal1 > 0, "vault should have nonzero balances after setup");

    // Test that a subsequent deposit gets positive shares
    deal(address(wbtc), attacker, ONE_TOKEN0);
    deal(address(usdc), attacker, ONE_TOKEN1 * 1000);
    vm.prank(attacker);
    (uint256 shares,,) = vault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 1000, 0, 0);
    t(shares > 0, "second depositor should get nonzero shares");

    // The exchange rate should be consistent:
    // attacker's share of total should be proportional to their value contributed
    uint256 newTotal = vault.totalSupply();
    uint256 attackerFraction = shares * 10000 / newTotal; // in bps
    // attacker deposited roughly half of what user deposited (1 WBTC vs 1 WBTC + 100k USDC)
    // so fraction should be reasonable, not 0 or 99%
    t(attackerFraction > 0, "attacker fraction should be nonzero");
    lte(attackerFraction, 9900, "attacker fraction should not be near 100%");
}

function property_getTokenIn_singleHop_correctness() public {
    // For a single-pool exactOutput path: WETH (tokenIn) -> fee -> WBTC (tokenOut)
    // Encoded as: tokenOut (WBTC, 20 bytes) + fee (3 bytes) + tokenIn (WETH, 20 bytes)
    bytes memory path = abi.encodePacked(address(wbtc), uint24(3000), address(weth));
    // _getTokenIn is internal; test indirectly via openLeveragedPosition attempt
    // The denomination is weth; swapParams encodes weth->wbtc.
    // If _getTokenIn works correctly it should return weth.
    // Bug: decodeFirstPool returns (tokenA=wbtc, tokenB=weth) -> it picks tokenB=weth at index 1.
    // Actually for 1-hop path: while loop doesn't run; decodeFirstPool(path) gives
    //   tokenA = path[0:20] = wbtc, tokenB = path[23:43] = weth
    // Then caller does `(, address tokenIn,) = path.decodeFirstPool()` -> tokenIn = weth (correct for 1-hop)
    // For multi-hop, the return of skipToken is ignored -> path never advances -> infinite loop
    // We verify multi-hop causes OOG by checking a simple invariant:
    // After any valid openLeveragedPosition call, the position must exist
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC, 100_000 * ONE_USDC, ONE_WBTC / 2);
    t(leverager.getPosition(posId).vault != address(0), "position should exist after open");
}

