function property_pullpush_balance_consistency() public {
    // Record underlyingBalance before pull
    uint256 balBefore = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 pullAmt = 1 * ONE_TOKEN0;

    // pull and push back the same amount — balance must be unchanged
    _pullFundsAsLeverager(address(token0), pullAmt);
    _pushFundsAsLeverager(address(token0), pullAmt);

    uint256 balAfter = lendingPool.totalLiquidityOfReserve(address(token0));

    // After a round-trip pull+push, underlyingBalance must be identical
    // to the actual token balance held by yToken
    uint256 actualBalance = token0.balanceOf(yToken0);
    // reserve.underlyingBalance is reflected via availableLiquidity
    // which is called inside totalLiquidityOfReserve
    // The accounting should match reality
    DataTypes.ReserveData memory r = DataTypes.ReserveData({
        borrowingIndex: 0, currentBorrowingRate: 0, totalBorrows: 0,
        yTokenAddress: address(0), stakingAddress: address(0),
        reserveCapacity: 0,
        borrowingRateConfig: DataTypes.InterestRateConfig({
            utilizationA: 0, borrowingRateA: 0,
            utilizationB: 0, borrowingRateB: 0, maxBorrowingRate: 0
        }),
        leverageParams: DataTypes.LeverageParams({
            maxIndividualBorrow: 0, maxLeverage: 0
        }),
        underlyingBalance: 0, lastUpdateTimestamp: 0,
        flags: DataTypes.Flags({isActive: false, frozen: false, borrowingEnabled: false})
    });
    // Simpler: just check pull without push causes underlyingBalance mismatch
    // Pull without push: underlyingBalance unchanged but actual balance reduced
    uint256 ubBefore = lendingPool.totalLiquidityOfReserve(address(token1));
    _pullFundsAsLeverager(address(token1), 1 * ONE_TOKEN1);
    uint256 ubAfter = lendingPool.totalLiquidityOfReserve(address(token1));
    // underlyingBalance is NOT decremented, so totalLiquidity is unchanged
    // but actual token balance DID decrease — this is the mismatch
    // The invariant: after pullFunds without pushFunds,
    // lendingPool.totalLiquidityOfReserve should equal token.balanceOf(yToken) + borrows
    // Instead underlyingBalance > actual balance
    uint256 actualToken1Bal = token1.balanceOf(yToken1);
    // totalLiquidityOfReserve = underlyingBalance + borrowedLiquidity
    // underlyingBalance should equal actualToken1Bal
    // but after pullFunds, underlyingBalance is still old value
    t(ubBefore > ubAfter || ubBefore == ubAfter, "pullFunds does not decrement underlyingBalance");
    // Push funds back to restore state
    _pushFundsAsLeverager(address(token1), 1 * ONE_TOKEN1);
}

function property_deposit_always_possible_above_min() public {
    // After interest accrual the exchange rate drops.
    // A "reasonable" deposit (e.g. 1 token0) should always succeed.
    uint256 depositAmt = ONE_TOKEN0; // 1e8 units

    // Borrow most liquidity and skip time to accrue interest
    uint256 availLiq = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 borrowAmt = availLiq * 95 / 100;
    if (borrowAmt > 0) {
        _borrowAsLeverager(address(token0), borrowAmt);
    }
    _skipTime(365 days * 10); // 10 years

    // Now try to deposit; if exchange rate is tiny this will revert with dust error
    token0.mint(depositor, depositAmt);
