    } catch {
        t(false, "deposit of 1 full token0 reverted after interest accrual");
    }
    vm.stopPrank();

    // Repay to restore state
    if (borrowAmt > 0) {
        _repayAsLeverager(address(token0), borrowAmt);
    }
}

