function property_redeem_possible_when_paused() public {
    // Pause the contract
    vm.startPrank(owner);
    lendingPool.emergencyPauseAll();
    vm.stopPrank();

    uint256 yBal = IERC20(yToken1).balanceOf(lender);
    if (yBal == 0) {
        // No yTokens to redeem; unpause and return
        vm.startPrank(owner);
        lendingPool.unPauseAll();
        vm.stopPrank();
        return;
    }

    bool redeemSucceeded = false;
    vm.startPrank(lender);
    IERC20(yToken1).approve(address(lendingPool), yBal);
    try lendingPool.redeem(address(token1), yBal / 2 + 1, lender) returns (uint256) {
        redeemSucceeded = true;
    } catch {
        redeemSucceeded = false;
    }
    vm.stopPrank();

    // Unpause
    vm.startPrank(owner);
    lendingPool.unPauseAll();
    vm.stopPrank();

    // Depositors should be able to exit even when paused
    t(redeemSucceeded, "redeem blocked while contract is paused");
}

