function property_borrowed_amount_matches_lendingpool_debt() public {
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC, 100_000 * ONE_USDC, ONE_WBTC / 4);

    ILeverager.Position memory pos = leverager.getPosition(posId);

    // The borrowedAmount * bIndex / borrowedIndex should equal what lending pool expects
    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(address(wbtc));
    uint256 currentOwed = pos.borrowedAmount * bIndex / pos.borrowedIndex;

    // The leverager should hold zero balance of borrowed token after opening
    uint256 leveragerWbtcBal = wbtc.balanceOf(address(leverager));
    eq(leveragerWbtcBal, 0, "leverager should have zero wbtc balance after position open");

    // Borrowed amount should be positive
    t(pos.borrowedAmount > 0, "borrowed amount should be positive");
