function property_liquidateable_does_not_revert_at_boundary_leverage() public {
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC, 100_000 * ONE_USDC, ONE_WBTC / 4);

    // Owner sets maxTimesLeverage to exactly 1e18 (1x) — edge case
    // This will cause division by zero in isLiquidateable
    vm.prank(owner);
    leverager.changeVaultMaxLeverage(address(vault), 1e18);

    // Drop price to make position clearly insolvent
    vm.prank(owner);
    wbtcOracle.setPrice(100e18);

    // isLiquidateable should not revert
    bool liq = leverager.isLiquidateable(posId);
    t(liq, "underwater position should be liquidateable even at boundary maxTimesLeverage");
}

function property_partial_withdraw_updates_collateral_usd() public {
    uint256 posId = _openPositionBorrowWbtc(user, ONE_WBTC, 100_000 * ONE_USDC, ONE_WBTC / 4);

    ILeverager.Position memory posBefore = leverager.getPosition(posId);
    uint256 initCollatUsdBefore = posBefore.initCollateralUsd;

    // Partial withdraw 50%
    _withdrawPositionPartial(user, posId, 0.5e18);

    ILeverager.Position memory posAfter = leverager.getPosition(posId);
    uint256 initCollatUsdAfter = posAfter.initCollateralUsd;

    // After 50% withdrawal, initCollateralUsd should be approximately halved
    // Allow 1% tolerance for rounding
    uint256 expected = initCollatUsdBefore / 2;
    uint256 tolerance = expected / 100;
    t(
        initCollatUsdAfter >= expected - tolerance && initCollatUsdAfter <= expected + tolerance,
        "initCollateralUsd should be halved after 50% withdrawal"
    );
}

function property_withdraw_proportional_amount() public {
    // Setup: depositor has shares, idle is 0 (all in positions after rebalance)
    uint256 depositorShares = _getShares(depositor);
    if (depositorShares == 0) return;

    (uint256 totalBal0Before, uint256 totalBal1Before) = _getVaultBalances();
    uint256 totalSupplyBefore = _getTotalSupply();

    // Expected proportional amounts
    uint256 expected0 = totalBal0Before * depositorShares / totalSupplyBefore;
    uint256 expected1 = totalBal1Before * depositorShares / totalSupplyBefore;

    uint256 wbtcBefore = wbtc.balanceOf(depositor);
    uint256 usdcBefore = usdc.balanceOf(depositor);

    (uint256 got0, uint256 got1) = _withdrawAs(depositor, depositorShares);

    // User should receive at least their proportional share (allow 1 wei rounding)
    gte(got0 + 1, expected0, "user got less token0 than proportional share");
    gte(got1 + 1, expected1, "user got less token1 than proportional share");
}

function property_vesting_not_dilutive_to_new_depositors() public {
    // If there's an ongoing vesting position, a new depositor should not
    // receive fewer shares than the value they put in implies.
    // (Compare share value before vs after new deposit.)
    (uint256 bal0Before, uint256 bal1Before) = _getVaultBalances();
    uint256 supplyBefore = _getTotalSupply();
    if (supplyBefore == 0) return;

    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = ONE_TOKEN1 * 60000; // ~1 BTC worth of USDC

    deal(address(wbtc), attacker, amt0);
    deal(address(usdc), attacker, amt1);

    (uint256 shares,,) = _dealAndDeposit(attacker, amt0, amt1);
    if (shares == 0) return;

    (uint256 w0, uint256 w1) = _withdrawAs(attacker, shares);

    // attacker should get back at least what they put in (within 1% tolerance for fees)
    uint256 minBack0 = amt0 * 99 / 100;
    uint256 minBack1 = amt1 * 99 / 100;
    // This checks the depositor is not systematically robbed due to vesting exclusion
    gte(w0 + w1 / 60000, minBack0, "new depositor lost significant value due to vesting dilution");
}

function property_fullmath_muldiv_correctness() public pure {
    // Test a known case where prod1 != 0 (intermediate overflow)
    // mulDiv(2^200, 2^200, 2^200 + 1) should equal 2^200 - 1 approximately
    // Use simpler test: mulDiv(type(uint256).max, 2, 3) should be correct
    uint256 a = type(uint128).max; // 2^128 - 1
    uint256 b = type(uint128).max; // 2^128 - 1
    uint256 denom = type(uint128).max + 1; // 2^128
    // a*b = (2^128-1)^2 = 2^256 - 2^129 + 1 (overflows uint256)
    // floor(a*b / denom) = floor((2^256 - 2^129 + 1) / 2^128)
    //                    = 2^128 - 2 + floor(1/2^128) = 2^128 - 2
    uint256 expected = type(uint128).max - 1; // 2^128 - 2
    uint256 result = FullMath.mulDiv(a, b, denom);
    eq(result, expected, "FullMath.mulDiv returns wrong result for overflow case");
}

function property_first_deposit_share_integrity() public {
    // After first deposit and immediate withdraw, user should get back
    // at least 99% of deposited funds (excluding the 1000 burned shares cost)
    uint256 initialSupply = _getTotalSupply();
    if (initialSupply != 0) return; // Only test first deposit scenario

    uint256 amt0 = ONE_TOKEN0; // 1 WBTC
    uint256 amt1 = ONE_TOKEN1 * 60000; // 60000 USDC

    deal(address(wbtc), attacker, amt0);
    deal(address(usdc), attacker, amt1);
    vm.startPrank(attacker);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    (uint256 shares,,) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    uint256 wbtcBefore = wbtc.balanceOf(attacker);
    uint256 usdcBefore = usdc.balanceOf(attacker);

    (uint256 w0, uint256 w1) = _withdrawAs(attacker, shares);

    // Should get back close to what was put in (minus the burned 1000 shares worth)
    gte(w0 * 100, amt0 * 98, "first depositor lost too much token0");
    gte(w1 * 100, amt1 * 98, "first depositor lost too much token1");
