function property_OH01_spot_price_deposit_no_shares_inflation() public {
    // Record state before deposit
    uint256 totalSupplyBefore = vault.totalSupply();
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();

    // Depositor deposits a known amount
    uint256 dep0 = 1e7; // 0.1 WBTC
    uint256 dep1 = 5_000e6; // 5000 USDC
    deal(address(wbtc), depositor, dep0);
    deal(address(usdc), depositor, dep1);
    vm.prank(depositor);
    (uint256 shares,,) = vault.deposit(dep0, dep1, 0, 0);

    // The shares received should be proportional to deposited value
    // shares / totalSupplyAfter <= (dep0/bal0 or dep1/bal1) * (1 + epsilon)
    uint256 totalSupplyAfter = vault.totalSupply();
    // shares * bal0Before <= dep0 * totalSupplyBefore  (with rounding tolerance)
    // i.e. depositor should not get more than their proportional share
    if (bal0Before > 0 && totalSupplyBefore > 0) {
        // shares / totalSupplyAfter should be <= dep0 / bal0Before + epsilon
        // cross-multiply to avoid division: shares * bal0Before <= dep0 * totalSupplyBefore * (1+1%)
        lte(
            shares * bal0Before,
            dep0 * totalSupplyBefore * 101 / 100,
            "OH-01: deposit minted too many shares relative to bal0 (spot price manipulable)"
        );
    }
}

function property_OH02_secondary_position_always_out_of_range() public {
    // After any rebalance, the secondary position must be OOR (out-of-range)
    // meaning current tick must be < tickLower OR > tickUpper
    (, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    IStrategy.Position memory secPos = strategy.getSecondaryPosition();

    if (secPos.liquidity > 0) {
        bool isOOR = currentTick < secPos.tickLower || currentTick >= secPos.tickUpper;
        t(isOOR, "OH-02: secondary position is in-range after rebalance (should always be OOR)");
    }
}

function property_OH03_main_position_centered_near_twap() public {
    // After rebalance, mainPosition should be centered within tickTwapDeviation
    // of the TWAP tick (since rebalance used spot which could deviate by up to
    // tickTwapDeviation ticks from TWAP).
    int24 _twapTick = strategy.twapTick();
    IStrategy.Position memory mainPos = strategy.getMainPosition();
    int24 posCenter = (mainPos.tickLower + mainPos.tickUpper) / 2;

    int24 deviation = posCenter - _twapTick;
    if (deviation < 0) deviation = -deviation;

    // The center should be within tickTwapDeviation + half tick spacing of TWAP
    int24 allowed = strategy.tickTwapDeviation() + strategy.tickSpacing();
    t(
        deviation <= allowed,
        "OH-03: main position center deviates too far from TWAP (spot price used for ticks)"
    );
}

function property_OH04_balances_includes_vesting_position() public {
    // If there's an ongoing vesting position with liquidity, balances() should
    // account for it (or at a minimum the share price should not decrease when
    // a vesting position is added).
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();
    uint256 priceBefore = bal0Before > 0 ? (bal0Before * PRECISION / vault.totalSupply()) : 0;

    // Check: if ongoingVestingPosition, vestPosition contributes real tokens
    // Verify balances() is at least as large as idle + main + secondary
    // (we can't call vestPosition directly as it's a struct public variable,
    // but we can check that the sum makes sense)
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();
    (uint256 bal0, uint256 bal1) = vault.balances();

    // balances must be >= idleBalances (positions contribute non-negatively)
    gte(bal0, idle0, "OH-04: balances() reports less than idle token0 balance");
    gte(bal1, idle1, "OH-04: balances() reports less than idle token1 balance");
}

function property_OH05_twap_price_close_to_spot() public {
    // The TWAP price and spot price should be within expected deviation bounds.
    // If they diverge more than tickTwapDeviation, checkPoolActivity should have
    // caught it and _priceWithinRange() should return false.
    uint256 spotP = vault.price();
    uint256 twapP = vault.twapPrice();

    // Allow up to 3% relative difference (approximate for tickTwapDeviation=200 ticks)
    uint256 maxDeviation = twapP * 3 / 100;
    uint256 diff = spotP > twapP ? spotP - twapP : twapP - spotP;

    // This property checks the invariant — if violated, manipulation window is exploitable
    lte(diff, maxDeviation, "OH-05: spot and TWAP price diverge beyond acceptable range");
}

function property_OH06_price_no_overflow() public {
    // Both price() and twapPrice() should return non-zero, plausible values
    // and must not overflow (revert would be a secondary indicator).
    uint256 spotP = vault.price();
    uint256 twapP = vault.twapPrice();

    // Both prices should be > 0
    t(spotP > 0, "OH-06: spot price returned 0 (possible overflow/underflow)");
    t(twapP > 0, "OH-06: TWAP price returned 0 (possible overflow/underflow)");

    // Prices should be within 10x of each other under normal conditions
    // (WBTC/USDC ~60000-100000 in PRECISION 1e30 terms)
    uint256 maxRatio = 10;
    if (spotP > twapP) {
        lte(spotP, twapP * maxRatio, "OH-06: spot price is 10x TWAP (suspicious overflow or extreme manipulation)");
    } else {
        lte(twapP, spotP * maxRatio, "OH-06: TWAP price is 10x spot (suspicious overflow or extreme manipulation)");
    }
}

function property_OH07_pool_activity_check_includes_current_price() public {
    // The current slot0 tick should be checked against the last observation
    // not just observation-to-observation comparisons.
    (, int24 currentTick, uint16 currentIndex,,,,,) = IUniswapV3Pool(address(pool)).slot0();
    (uint32 lastObsTimestamp,,,) = IUniswapV3Pool(address(pool)).observations(currentIndex);

    // If significant time has passed since last observation, the gap is unmonitored.
    // This property checks that the gap is small enough to be safe.
    uint256 gap = block.timestamp - lastObsTimestamp;

    // A gap > twap seconds means checkPoolActivity covers zero time back from now
    lte(gap, uint256(strategy.twap()), "OH-07: time gap since last observation exceeds TWAP window — manipulation undetectable");
}

