function property_pullFunds_reduces_underlying_balance() public {
    address asset = address(token2);
    uint256 balBefore = _getUnderlyingInYToken(asset);
    uint256 ubBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 pullAmt = balBefore / 2;
    if (pullAmt == 0) return;
    // leverager pulls funds (address(this) is the leverager in Setup)
    lendingPool.pullFunds(asset, pullAmt);
    uint256 balAfter = _getUnderlyingInYToken(asset);
    uint256 ubAfter = lendingPool.totalLiquidityOfReserve(asset);
    // Invariant: if actual token balance dropped, accounting must also drop
    // (or at minimum, accounting must not exceed actual balance + borrowed)
    int256 balDelta = int256(balAfter) - int256(balBefore);
    int256 ubDelta  = int256(ubAfter)  - int256(ubBefore);
    // The pullFunds took tokens out: balDelta should be negative
    // accounting delta (available portion) should also be negative
    // We check the simpler invariant: after pull, reported available <= actual token balance
    uint256 totalBorrows = _getTotalBorrows(asset);
    // availableLiquidity = underlyingBalance; it should equal actual balance
    // since no borrow happened
    t(
        lendingPool.totalLiquidityOfReserve(asset) - totalBorrows <= _getUnderlyingInYToken(asset),
        "AH-LP-01: underlyingBalance exceeds actual yToken balance after pullFunds"
    );
}

function property_pushFunds_increases_underlying_balance() public {
    address asset = address(token2);
    // First pull some funds to create deficit
    uint256 avail = _getUnderlyingInYToken(asset);
    if (avail < 2) return;
    uint256 pullAmt = avail / 2;
    lendingPool.pullFunds(asset, pullAmt);
    // Now push back the same amount
    lendingPool.pushFunds(asset, pullAmt);
    // Invariant: after a matching pull+push, accounting should match actual balance
    uint256 totalBorrows = _getTotalBorrows(asset);
    uint256 reported = lendingPool.totalLiquidityOfReserve(asset);
    uint256 actualAvail = _getUnderlyingInYToken(asset);
    t(
        reported - totalBorrows <= actualAvail,
        "AH-LP-02: after pull+push, underlyingBalance exceeds actual yToken balance"
    );
}

function property_pullFunds_respects_available_liquidity() public {
    address asset = address(token2);
    uint256 avail = _getUnderlyingInYToken(asset);
    if (avail == 0) return;
    // Try to pull more than available
    uint256 overPull = avail + 1;
    // If the yToken doesn't have it, this should revert
    // If it doesn't revert, check the invariant
    try lendingPool.pullFunds(asset, overPull) {
        // If it succeeded, underlyingBalance should not go below 0
        // (underlyingBalance is uint, so it would underflow if decremented)
        // Since pullFunds doesn't decrement underlyingBalance, it just succeeds
        // This is the bug: no revert even when pulling more than available
        t(false, "AH-LP-03: pullFunds succeeded with amount > actual token balance");
    } catch {
        // Expected: should revert
    }
}

function property_redeem_never_reverts_if_accounting_says_ok() public {
    address asset = address(token0);
    address yt = yToken0;
    uint256 lenderBal = IERC20(yt).balanceOf(lender);
    if (lenderBal == 0) return;
    uint256 expectedUnderlying = lendingPool.exchangeRateOfReserve(asset) * lenderBal / PRECISION;
    if (expectedUnderlying == 0) return;
    uint256 avail = lendingPool.totalLiquidityOfReserve(asset) - _getTotalBorrows(asset);
    if (expectedUnderlying > avail) return; // can't redeem more than available
    // If accounting says redeem should work, the actual transfer must also succeed
    // i.e., actual yToken balance >= expectedUnderlying
    uint256 actualTokenBal = _getUnderlyingInYToken(asset);
    t(
        actualTokenBal >= expectedUnderlying,
        "AH-LP-05: accounting says redeem ok but actual yToken balance is insufficient"
    );
}

function property_pullFunds_blocked_when_paused() public {
    // pullFunds should not be callable (or at minimum, should not drain funds)
    // when the contract is paused, to prevent the repay+pullFunds drain
    address asset = address(token2);
    uint256 ubBefore = _getUnderlyingInYToken(asset);
    if (ubBefore == 0) return;
    // Simulate pause scenario
    vm.prank(owner);
    lendingPool.emergencyPauseAll();
    uint256 pullAmt = ubBefore / 2;
    // pullFunds lacks notPaused — it will succeed even when paused
    try lendingPool.pullFunds(asset, pullAmt) {
        t(false, "AH-LP-06: pullFunds succeeded when contract is paused");
    } catch {
        // Expected: should revert
    }
    // Cleanup
    vm.prank(owner);
    lendingPool.unPauseAll();
}

function property_underlying_balance_matches_actual() public {
    address asset = address(token2);
    address yt = yToken2;
    // underlyingBalance (available portion) + totalBorrows (lent portion) = total reported
    // actual yToken balance = what was deposited minus what was borrowed (via borrow path)
    // They should match EXACTLY if only deposit/redeem/borrow/repay were used.
    // If pullFunds/pushFunds were used they may diverge — this property catches that.
    uint256 actualBal = IERC20(asset).balanceOf(yt);
    uint256 totalBorrows = _getTotalBorrows(asset);
    uint256 totalLiquidity = _getTotalLiquidity(asset);
    // totalLiquidity = underlyingBalance + borrowedLiquidity(accrued)
    // actualBal = underlyingBalance (only the non-borrowed portion is in yToken)
    // So: actualBal should equal totalLiquidity - totalBorrows
    uint256 expectedActual = totalLiquidity > totalBorrows ? totalLiquidity - totalBorrows : 0;
    // Allow small rounding (1 wei)
    t(
        actualBal >= expectedActual || expectedActual - actualBal <= 1,
        "AH-LP-07: yToken actual balance is less than expected (phantom liquidity in accounting)"
    );
}

function property_rebalance_uses_twap_tick_not_spot() public {
    // After rebalance, the main position center should be within
    // tickSpacing of the TWAP tick, not the spot tick.
    // If spot drifts from TWAP and rebalance is triggered, check
    // that position center is closer to TWAP than to spot.
    int24 twapT = strategy.twapTick();
    IStrategy.Position memory main = strategy.getMainPosition();
    int24 center = (main.tickLower + main.tickUpper) / 2;
    int24 deviation = twapT - center;
    if (deviation < 0) deviation = -deviation;
    // center should be within positionWidth/2 of the TWAP tick
    t(deviation <= int24(uint24(strategy.positionWidth())),
      "OH-01: main position center too far from TWAP tick");
}

function property_secondary_position_oor() public {
    // Secondary position must always be OOR (one-sided).
    // The spot tick should not fall inside secondaryPosition ticks.
    (, int24 spotTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    if (sec.liquidity > 0) {
        bool spotInRange = spotTick >= sec.tickLower && spotTick < sec.tickUpper;
        t(!spotInRange,
          "OH-02: secondary position is in-range (should always be OOR)");
    }
}

function property_balances_not_manipulable_by_spot() public {
    // Spot-derived balances should be within 2% of TWAP-derived balances.
    uint256 spotPrice = strategy.price();
    uint256 twapP    = strategy.twapPrice();
    // Allow 3% slack (tickTwapDeviation is 200 ticks ~ 2%)
    uint256 ratio = spotPrice > twapP
        ? (spotPrice * 10_000) / twapP
        : (twapP    * 10_000) / spotPrice;
    lte(ratio, 10_300,
        "OH-03: spot and TWAP prices diverge >3%, balances() is manipulable");
}

function property_collect_fees_uses_vesting_position_ticks() public {
    // Verify that after collectFees, the vesting position's tick range
    // is correctly used (not mainPosition.tickUpper).
    // We check indirectly: if vestPosition ticks != mainPosition ticks,
    // the two tick upper values should differ after a rebalance, and
    // the protocol should still be able to collect fees.
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory main = strategy.getMainPosition();
    // The vestPosition.tickUpper should still be tracked independently.
    // After rebalance diverges them, protocol fees from vesting should
    // still be > 0 if the pool has generated fees.
    if (strategy.ongoingVestingPosition() && vp.tickUpper != main.tickUpper) {
        // collectFees would use wrong tick — this state is itself the bug.
        t(false,
          "OH-04: vesting position ticks diverged from mainPosition; collectFees will use wrong tickUpper");
    }
}

function property_twap_window_sufficient() public {
    // The TWAP window should be large enough to resist sustained manipulation.
    // 5 minutes (300 seconds) is borderline; check it's at least 10 minutes.
    uint32 twapWindow = strategy.twap();
    gte(uint256(twapWindow), 600,
        "OH-05: TWAP window is only 5 minutes, too short for manipulation resistance");
}

function property_check_pool_activity_no_revert() public {
    // _requirePriceWithinRange() (which calls checkPoolActivity) should
    // not revert under normal pool conditions. We call it and assert it
    // returns a bool without reverting.
    bool withinRange;
    try strategy.checkPoolActivity() returns (bool result) {
        withinRange = result;
        t(true, "OH-06: checkPoolActivity returned without revert");
    } catch {
        t(false, "OH-06: checkPoolActivity reverted (possibly timestamp==0 in observations)");
    }
}

function property_secondary_position_side_determined_by_balance() public {
    // After rebalance (when balances are non-zero), verify the secondary
    // position side matches the actual token surplus.
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();
    uint256 spotPrice = strategy.price();
    uint256 idle0in1 = idle0 * spotPrice / 1e30;
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    IStrategy.Position memory main = strategy.getMainPosition();
    if (idle0in1 < idle1) {
        // token1 surplus — secondary should be below main (token1 side)
        t(sec.tickUpper <= main.tickLower || sec.tickLower <= main.tickLower,
          "OH-07: secondary position on wrong side for token1 surplus");
    } else if (idle0in1 > idle1) {
        // token0 surplus — secondary should be above main (token0 side)
        t(sec.tickLower >= main.tickUpper || sec.tickUpper >= main.tickUpper,
          "OH-07: secondary position on wrong side for token0 surplus");
    }
}

function property_pullFunds_underlyingBalance_decremented() public {
    address asset = address(token0);
    uint256 pullAmt = ONE_TOKEN0;

    // Record underlyingBalance equivalent: total liquidity before pull
    uint256 liquidityBefore = _getTotalLiquidity(asset);
    uint256 availBefore = lendingPool.totalBorrowsOfReserve(asset);
    // underlyingBalance is not directly exposed; use availableLiquidity
    // proxy: totalLiquidity - totalBorrows = underlyingBalance
    uint256 underlyingBefore = liquidityBefore > availBefore ? liquidityBefore - availBefore : 0;

    // Pull funds (leverager == address(this) per Setup)
    _pullFundsAsLeverager(asset, pullAmt);

    uint256 liquidityAfter = _getTotalLiquidity(asset);
    uint256 underlyingAfter = liquidityAfter > lendingPool.totalBorrowsOfReserve(asset)
        ? liquidityAfter - lendingPool.totalBorrowsOfReserve(asset)
        : 0;

    // After pull, tracked underlying balance should decrease by pullAmt
    // Bug: underlyingBalance is NOT decremented, so underlyingAfter == underlyingBefore
    lte(underlyingAfter, underlyingBefore, "underlyingBalance should decrease after pullFunds");

    // Restore state
    _pushFundsAsLeverager(asset, pullAmt);
}

function property_pushFunds_underlyingBalance_incremented() public {
    address asset = address(token1);
    uint256 extraAmt = ONE_TOKEN1 * 100;

    uint256 liquidityBefore = _getTotalLiquidity(asset);

    // Push funds WITHOUT a prior pullFunds (simulates profit injection)
    _pushFundsAsLeverager(asset, extraAmt);

    uint256 liquidityAfter = _getTotalLiquidity(asset);

    // After push, totalLiquidity (which reads underlyingBalance + borrows)
    // should increase by extraAmt. Bug: it does NOT because underlyingBalance
    // is not updated.
    gte(liquidityAfter, liquidityBefore + extraAmt, "pushFunds must increase tracked liquidity");
}

function property_pullFunds_uses_memory_not_storage() public {
    // This test verifies that pullFunds' memory reserve copy does not persist changes.
    // We verify that calling pullFunds followed by pushFunds returns to exact original state.
    address asset = address(token2);
    uint256 amt = ONE_TOKEN2;

    uint256 borrowRateBefore = _getBorrowingRate(asset);
    uint256 liquidityBefore = _getTotalLiquidity(asset);

    _pullFundsAsLeverager(asset, amt);
    _pushFundsAsLeverager(asset, amt);

    uint256 liquidityAfter = _getTotalLiquidity(asset);
    uint256 borrowRateAfter = _getBorrowingRate(asset);

    // If memory vs storage causes double-counting bugs, these would differ
    eq(liquidityAfter, liquidityBefore, "liquidity should be unchanged after pull+push cycle");
    eq(borrowRateAfter, borrowRateBefore, "borrow rate should be unchanged after pull+push cycle");
}

function property_compounded_interest_approximation_monotone() public {
    address asset = address(token0);

    // Borrow some funds to activate interest accrual
    _borrowAsLeverager(asset, ONE_TOKEN0);

    uint256 indexBefore = _getCurrentBorrowingIndex(asset);

    // Advance time by 365 days
    _skipTime(365 days);

    uint256 indexAfter = _getCurrentBorrowingIndex(asset);

    // Index should increase after time passes (monotone property)
    gte(indexAfter, indexBefore, "borrowing index must be non-decreasing over time");

    // Repay to restore state
    _repayAsLeverager(asset, ONE_TOKEN0 * 2);
}

function property_exchange_rate_increases_with_borrows() public {
    address asset = address(token1);

    uint256 rateBefore = _getExchangeRate(asset);

    // Borrow maximum available to spike utilization
    uint256 available = _getTotalLiquidity(asset) - _getTotalBorrows(asset);
    if (available > 0) {
        _borrowAsLeverager(asset, available / 2);
    }

    _skipTime(7 days);

    // After time passes with borrows, exchange rate (yToken -> underlying)
    // should be >= original (interest accrues to lenders)
    uint256 rateAfter = _getExchangeRate(asset);

    gte(rateAfter, rateBefore, "exchange rate must be non-decreasing when borrows exist");

    // Cleanup
    _repayAsLeverager(asset, available);
}

function property_minimum_deposit_check_consistent() public {
    address asset = address(token1);

    // Simulate significant interest accrual
    _borrowAsLeverager(asset, 50_000 * ONE_TOKEN1);
    _skipTime(365 days * 5);

    uint256 exchangeRate = _getExchangeRate(asset);
    uint256 testDeposit = 2000 * ONE_TOKEN1; // 2000 USDC, should not be "dust"

    uint256 expectedYTokens = testDeposit * PRECISION / exchangeRate;

    // A deposit of 2000 USDC should always yield > MINIMUM_YTOKEN_AMOUNT yTokens
    // Bug: as exchangeRate grows (totalLiquidity >> totalYTokens in reserve-to-yToken direction),
    // small but economically meaningful deposits can revert as "dust"
    gte(expectedYTokens, MINIMUM_YTOKEN_AMOUNT, "2000 USDC deposit should never be dust");

    // Cleanup
    _repayAsLeverager(asset, 50_000 * ONE_TOKEN1 * 2);
}

function property_index_monotone_across_state_updates() public {
    address asset = address(token2);

    _borrowAsLeverager(asset, 50 * ONE_TOKEN2);

    uint256 idx1 = _getCurrentBorrowingIndex(asset);
    _skipTime(12); // 1 block

    uint256 idx2 = _getCurrentBorrowingIndex(asset);
    gte(idx2, idx1, "borrowing index must be non-decreasing across blocks");

    _skipTime(12);
    uint256 idx3 = _getCurrentBorrowingIndex(asset);
    gte(idx3, idx2, "borrowing index must be non-decreasing across blocks (2)");

    _repayAsLeverager(asset, 100 * ONE_TOKEN2);
}

function property_collectFees_uses_correct_vest_ticks() public {
    // If there is an ongoing vesting position, collectFees should collect
    // fees using vestPosition's own tickUpper, not mainPosition.tickUpper.
    // We verify that after collectFees, calling burn(0) on the ACTUAL
    // vest position ticks does NOT produce any new tokens0/1 owed
    // (i.e., fees were actually collected from the correct range).
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper, not vestPosition.tickUpper
    // If they differ, the vest fees are never collected
    t(
        vp.tickUpper == mp.tickUpper,
        "collectFees uses wrong tickUpper for vesting position"
    );
}

function property_vesting_liquidity_fully_distributed() public {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    // After vesting ends, ongoingVestingPosition should be false
    // and remainingLiquidity should be 0
    if (block.timestamp >= vp.endTs && vp.endTs > 0) {
        // Trigger collection to flush vested liquidity
        strategy.collectFees();
        IStrategy.VestingPosition memory vp2 = strategy.getVestingPosition();
        // If vesting has ended and collectFees was called, ongoing should be false
        t(!strategy.ongoingVestingPosition(), "vesting position should be completed");
    }
}

function property_withdraw_amount_bounded_by_share_fraction() public {
    uint256 totalSupply = vault.totalSupply();
    if (totalSupply == 0) return;

    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();

    uint256 expectedMax0 = bal0Before * userShares / totalSupply + 1; // +1 for rounding
    uint256 expectedMax1 = bal1Before * userShares / totalSupply + 1;

    vm.prank(user);
    (uint256 got0, uint256 got1) = vault.withdraw(userShares, 0, 0);

    // User should not get more than their proportional share (+ small rounding buffer)
    lte(got0, expectedMax0 + 10, "user got more token0 than share fraction");
    lte(got1, expectedMax1 + 10, "user got more token1 than share fraction");
}

function property_secondary_position_valid_ticks() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    // Secondary position must have tickLower < tickUpper if liquidity > 0
    if (sp.liquidity > 0) {
        t(sp.tickLower < sp.tickUpper, "secondary position has invalid tick range");
    }
    // Even with 0 liquidity, the stored ticks should be valid
    t(sp.tickLower < sp.tickUpper || (sp.tickLower == 0 && sp.tickUpper == 0),
      "secondary position ticks invalid");
}

function property_withdraw_does_not_over_distribute() public {
    uint256 totalSupply = vault.totalSupply();
    if (totalSupply < 2) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0 || userShares >= totalSupply) return;

    // Calculate what user SHOULD get (proportional to pre-withdrawal supply)
    uint256 expected0 = bal0 * userShares / totalSupply;
    uint256 expected1 = bal1 * userShares / totalSupply;

    uint256 userBal0Before = token0.balanceOf(user);
    uint256 userBal1Before = token1.balanceOf(user);

    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    uint256 received0 = token0.balanceOf(user) - userBal0Before;
    uint256 received1 = token1.balanceOf(user) - userBal1Before;

    // Allow small rounding tolerance of 2 wei
    lte(received0, expected0 + 2, "user received more token0 than entitled");
    lte(received1, expected1 + 2, "user received more token1 than entitled");
}

function property_collect_fees_uses_vest_ticks() public {
    // After a rebalance the vestPosition ticks and main ticks may differ.
    // Calling collectFees() must not revert due to mismatched tick range.
    // We snapshot balances before and after to verify the call succeeds.
    vm.prank(rebalancer);
    strategy.compound(); // ensure fees have accrued

    // Record balances before
    (uint256 pre0, uint256 pre1) = strategy.idleBalances();

    // collectFees must succeed without revert
    strategy.collectFees();

    (uint256 post0, uint256 post1) = strategy.idleBalances();
    // After collecting fees protocol takes its cut; idle can only go up or stay same
    // (net of protocol fee transfer). The key assertion is that it does not revert.
    t(post0 + post1 >= 0, "collectFees reverted or corrupted idle balances");
}

function property_vesting_no_over_release() public {
    // If there is an ongoing vesting position, withdrawing a large partial slice
    // must not result in remainingLiquidity going below 0 (checked arithmetic would revert).
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    uint128 before = vp.remainingLiquidity;

    // Trigger vesting withdrawal
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    // remainingLiquidity must never exceed initial (no negative wrapping)
    lte(vpAfter.remainingLiquidity, vp.initialLiquidity, "remainingLiquidity exceeded initial");
    lte(vpAfter.remainingLiquidity, before, "remainingLiquidity increased after withdrawal");
}

function property_secondary_ticks_valid() public {
    // After any rebalance the secondary position ticks must be ordered correctly.
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    t(sec.tickLower < sec.tickUpper, "secondary position ticks inverted or equal");
}

function property_check_pool_activity_no_revert() public view returns (bool) {
    // checkPoolActivity should not revert under normal operation.
    // We call it and expect a boolean return, not a revert.
    try strategy.checkPoolActivity() returns (bool result) {
        t(true, "checkPoolActivity returned successfully");
        return result;
    } catch {
        t(false, "checkPoolActivity reverted unexpectedly");
        return false;
    }
}

function property_vesting_flag_cleared_after_completion() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    // Skip past the vesting end
    vm.warp(vp.endTs + 1);

    // collectFees should clear the flag
    strategy.collectFees();

    t(!strategy.ongoingVestingPosition(), "ongoingVestingPosition not cleared after vesting ended");
}

function property_vesting_not_counted_in_balances() public {
    // Checks: if there is an ongoing vesting position,
    // balances() should still reflect total assets under management
    // (including vesting liquidity). If it doesn't, a deposit will
    // grant excess shares.
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return; // property only relevant when vesting is active

    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 totalSup = vault.totalSupply();
    if (totalSup == 0) return;

    // Deposit a known amount and check the share price
    uint256 depositAmt0 = ONE_TOKEN0; // 1 WBTC
    uint256 depositAmt1 = ONE_TOKEN1 * 100_000; // 100k USDC

    deal(address(wbtc), attacker, depositAmt0);
    deal(address(usdc), attacker, depositAmt1);
    vm.startPrank(attacker);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    (uint256 sharesBefore,,) = vault.deposit(depositAmt0, depositAmt1, 0, 0);
    vm.stopPrank();

    // Now vesting releases some liquidity (simulate time passing)
    skip(1 days);
    vm.prank(rebalancer);
    strategy.compound(); // triggers collectFees -> _withdrawPartOfVestingPosition

    // Attacker withdraws
    vm.prank(attacker);
    (uint256 w0, uint256 w1) = vault.withdraw(sharesBefore, 0, 0);

    // Attacker should NOT receive more than they put in (in token0 terms)
    // Approximate: w0 + w1/price should be <= depositAmt0 + depositAmt1/price
    // Use price() for conversion
    uint256 _price = vault.price(); // token0/token1 in PRECISION
    uint256 inValue = depositAmt0 + depositAmt1 * PRECISION / _price;
    uint256 outValue = w0 + w1 * PRECISION / _price;

    // Property: attacker should not profit purely from vesting position dilution
    // (allowing small rounding tolerance of 0.1%)
    t(outValue <= inValue * 10001 / 10000, "vesting position dilution: attacker gained from vesting");
}

function property_first_deposit_share_price_sane() public {
    // After the initial deposit (done in setup), the share price
    // should reflect a reasonable ratio of tokens to shares.
    // Setup deposits: 1e8 WBTC and 100_000e6 USDC.
    // shares = max(1e8, 100_000e6) - 1000 = 100_000e6 - 1000 (USDC units dominate).
    // That means 1e8 WBTC worth is priced at ~1e-2 shares per wei of WBTC.
    // A second depositor depositing only WBTC should get fair shares.

    uint256 totalSup = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();
    if (totalSup == 0 || bal0 == 0 || bal1 == 0) return;

    // Compute implied price per share in token0 terms
    uint256 token0PerShare = bal0 * 1e18 / totalSup;
    uint256 token1PerShare = bal1 * 1e18 / totalSup;

    // In a WBTC/USDC pool, 1 WBTC ~ 60000 USDC (rough).
    // Convert to common unit using vault.price() (token0/token1 in PRECISION)
    uint256 _price = vault.price();
    // token1PerShare in token0 terms:
    uint256 token1PerShareIn0 = token1PerShare * PRECISION / _price;

    // They should be within 10x of each other (sanity check for extreme mispricing)
    // If shares are minted in USDC units but WBTC has fewer decimals,
    // token0PerShare and token1PerShareIn0 may be wildly different
    t(token0PerShare > 0 && token1PerShareIn0 > 0, "zero per-share value");
    // Allow 100x range max — extreme beyond this indicates mispriced first deposit
    bool reasonable = (token0PerShare <= token1PerShareIn0 * 100) &&
                      (token1PerShareIn0 <= token0PerShare * 100);
    t(reasonable, "first deposit creates severely mispriced shares across decimal difference");
}

function property_withdraw_receives_fair_share() public {
    // A user withdrawing ALL shares should receive all underlying assets
    // (excluding protocol fees and deposit fees, but including vesting position value).
    // This test checks: after user withdraws all shares, remaining assets in strategy
    // should be approximately proportional to remaining shares (burn address shares).

    uint256 burnShares = vault.balanceOf(BURN_ADDRESS);
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 totalSup = vault.totalSupply();
    (uint256 totalBal0, uint256 totalBal1) = strategy.balances();

    // Expected withdrawal for user (based on balances() which excludes vesting)
    uint256 expectedW0 = totalBal0 * userShares / totalSup;
    uint256 expectedW1 = totalBal1 * userShares / totalSup;

    vm.prank(user);
    (uint256 w0, uint256 w1) = vault.withdraw(userShares, 0, 0);

    // After withdrawal, burn address holds burnShares/totalSup of remaining assets.
    // The total assets should have decreased by approximately w0/w1.
    (uint256 newBal0, uint256 newBal1) = strategy.balances();
    uint256 newTotalSup = vault.totalSupply();

    // If there's an ongoing vesting position, withdraw only gave user
    // their share of non-vesting assets. The burn address still has claims
    // on the vesting position.
    bool ongoing = strategy.ongoingVestingPosition();
    if (ongoing) {
        // w0 should approximately equal expectedW0 (within 1% for rounding)
        // But the NAV per share after withdrawal should not INCREASE
        // (remaining holders should not gain at withdrawer's expense).
        // NAV per share before: totalBal0/totalSup
        // NAV per share after: newBal0/newTotalSup
        // If vesting position exists, newBal0/newTotalSup may exceed totalBal0/totalSup
        // because vesting assets weren't included in totalBal0
        if (newTotalSup > 0 && totalSup > 0 && totalBal0 > 0) {
            uint256 navBefore = totalBal0 * 1e18 / totalSup;
            uint256 navAfter = newBal0 * 1e18 / newTotalSup;
            // If navAfter significantly exceeds navBefore, remaining holders
            // benefited from the withdrawer's loss of vesting position claim
            t(navAfter <= navBefore * 1001 / 1000,
              "remaining holders unfairly gained NAV when vesting position excluded from withdrawal");
        }
    }
}

function property_collectFees_vesting_uses_correct_ticks() public {
    // If there is an ongoing vesting position, record the tick bounds
    // then call collectFees() and verify the vesting position ticks
    // haven't changed in an unexpected way.
    if (!_isOngoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = _getVestingPosition();
    IStrategy.Position memory mp = _getMainPosition();

    // The critical assertion: vesting tickUpper must differ from main tickUpper
    // when the positions were set up at different widths/times.
    // Here we document the structural invariant that collectFees should
    // collect from vestPosition ticks, not mainPosition ticks.
    // If tickUpper values diverge, the current code collects from the wrong range.
    t(
        vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
        "vesting and main positions share ticks — masked bug"
    );
}

function property_secondary_ticks_valid() public {
    IStrategy.Position memory sp = _getSecondaryPosition();
    // A valid Uniswap V3 position must have tickLower strictly less than tickUpper
    t(
        sp.liquidity == 0 || sp.tickLower < sp.tickUpper,
        "secondary position has tickLower >= tickUpper"
    );
}

function property_balances_includes_vesting() public {
    if (!_isOngoingVestingPosition()) return;

    (uint256 bal0, uint256 bal1) = _getStrategyBalances();
    (uint256 idle0, uint256 idle1) = _getIdleBalances();

    IStrategy.VestingPosition memory vp = _getVestingPosition();

    // balances() must be >= idle balances (always true if vesting is included)
    // If vesting position has remaining liquidity, total strategy value > idle only
    if (vp.remainingLiquidity > 0) {
        // The difference should account for at least some of the vesting position
        // A strict lower bound: bal0 should exceed idle0 if vesting has token0 component
        // This property detects the undercount when remainingLiquidity is non-zero
        t(
            bal0 >= idle0 && bal1 >= idle1,
            "balances() should be >= idle balances"
        );
    }
}

function property_vesting_total_release() public {
    if (!_isOngoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = _getVestingPosition();

    // The remaining liquidity should never exceed initialLiquidity
    t(
        vp.remainingLiquidity <= vp.initialLiquidity,
        "remainingLiquidity exceeds initialLiquidity"
    );

    // If we are past endTs, vesting should be complete (ongoingVestingPosition == false)
    if (block.timestamp >= vp.endTs) {
        t(
            !_isOngoingVestingPosition(),
            "vesting should be complete after endTs"
        );
    }
}

function property_secondary_position_oor() public {
    IStrategy.Position memory sp = _getSecondaryPosition();
    if (sp.liquidity == 0) return;

    (, int24 currentTick,,,,,) = pool.slot0();

    // The secondary position should be Out-Of-Range:
    // either entirely above (tickLower > currentTick) or below (tickUpper <= currentTick)
    bool isAbove = sp.tickLower > currentTick;
    bool isBelow = sp.tickUpper <= currentTick;
    t(
        isAbove || isBelow,
        "secondary position should be out-of-range"
    );
}

function property_pullFunds_updates_underlyingBalance() public {
    address asset = address(token0);
