    lendingPool.pullFunds(asset, pullAmt);

    // After pullFunds, availableLiquidity must decrease by pullAmt
    // (underlyingBalance must have been updated)
    uint256 balAfter = lendingPool.totalLiquidityOfReserve(asset);
