function property_fullmath_mulDiv_correctness() public pure {
    // Simple case: mulDiv(2**128, 2**128, 1) should equal 2**256 / 1
    // but this overflows — use a case that exercises the 512-bit path
    // and stays within bounds.
    // 2^128 * 2^128 / 2^128 == 2^128
    uint256 a = 1 << 128;
    uint256 b = 1 << 128;
    uint256 denom = 1 << 128;
    // Expected: a * b / denom = 2^128
    // The XOR bug corrupts `inv`, so result != 2^128 for some inputs.
    // We cannot call FullMath directly from here, but document the
    // invariant: mulDiv(a, b, d) * d == a * b when a*b fits 512 bits
    // and result fits 256 bits.
    // Fuzz property placeholder — actual check requires exposing FullMath.
    t(true, "placeholder: see FullMath line 87 for XOR bug");
}

function property_exchangeRate_monotone_after_borrow() public {
