    _skipTime(365 days);

    uint256 rateAfter = lendingPool.exchangeRateOfReserve(asset);

    // exchange rate (yToken -> underlying) must be >= before (interest accrues to lenders)
    gte(rateAfter, rateBefore, "exchange rate must not decrease after interest accrual");
