function property_pullFunds_cannot_exceed_available() public {
    address asset = address(token1);

    uint256 avail = lendingPool.totalLiquidityOfReserve(asset);
    // Try to pull more than available — should revert OR
    // at minimum: underlyingBalance must stay consistent afterwards
    try lendingPool.pullFunds(asset, avail + 1) {
        // If it didn't revert, underlyingBalance must have been checked
        // i.e. the actual ERC20 balance of yToken1 must be >= 0 (always true)
        // but availableLiquidity must not become negative
        uint256 availAfter = lendingPool.totalLiquidityOfReserve(asset);
        gte(availAfter, 0, "available liquidity must not underflow");
        // The real invariant: yToken ERC20 balance >= reserve.underlyingBalance
        uint256 actualBal = token1.balanceOf(yToken1);
        (uint256 totalLiq,) = (lendingPool.totalLiquidityOfReserve(asset), uint256(0));
        // totalLiquidity includes borrows; available portion <= actualBal
        lte(lendingPool.totalLiquidityOfReserve(asset) - lendingPool.totalBorrowsOfReserve(asset),
            actualBal + 1, // +1 for rounding
            "underlyingBalance must not exceed actual yToken ERC20 balance");
    } catch {
        // revert is acceptable
        t(true, "pull exceeding available correctly reverted");
    }
}

