function property_exchange_rate_reflects_actual_balance() public {
    address asset = address(token2);
    // After any sequence of pullFunds/pushFunds, the exchange rate should
    // correspond to the actual token balance held by yToken
    uint256 actualBalance = token2.balanceOf(yToken2);
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    uint256 totalSupply = IERC20(yToken2).totalSupply();
    if (totalSupply == 0) return;
    // totalLiquidity as seen by the pool
    uint256 reportedLiquidity = lendingPool.totalLiquidityOfReserve(asset);
    // actualBalance + totalBorrows should equal reportedLiquidity
    // (borrows are out, balance is what's in yToken)
    gte(actualBalance + totalBorrows, reportedLiquidity > 1 ? reportedLiquidity - 1 : 0,
        "actual yToken balance + borrows must >= reported liquidity");
    lte(actualBalance + totalBorrows, reportedLiquidity + 1,
        "actual yToken balance + borrows must <= reported liquidity");
}

