function property_no_cross_function_reentrancy_withdraw_deposit() public {
    // Give attacker initial tokens and deposit
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = ONE_TOKEN1 * 50000;
    (uint256 shares,,) = _dealAndDeposit(attacker, amt0, amt1);

    uint256 totalSupplyBefore = _getTotalSupply();
    (uint256 bal0Before, uint256 bal1Before) = _getVaultBalances();

    // Withdraw all attacker shares
    (uint256 w0, uint256 w1) = _withdrawAs(attacker, shares);

    uint256 totalSupplyAfter = _getTotalSupply();

    // Invariant: totalSupply should decrease by exactly the shares burned
    // (1000 burn shares remain from initial deposit)
    t(totalSupplyAfter == totalSupplyBefore - shares, "total supply accounting error after withdraw");

    // Vault balances should decrease proportionally
    (uint256 bal0After, uint256 bal1After) = _getVaultBalances();
    // withdrawn amounts should not exceed what was in the vault
    t(w0 <= bal0Before, "withdrew more token0 than vault had");
    t(w1 <= bal1Before, "withdrew more token1 than vault had");
}

function property_deposit_shares_proportional() public {
