function property_withdraw_idle_check_consistency() public {
    // After withdraw, total balances should decrease by approximately what was withdrawn
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = ONE_TOKEN1 * 50000;
    (uint256 shares,,) = _dealAndDeposit(user, amt0, amt1);

    (uint256 bal0Before, uint256 bal1Before) = _getVaultBalances();
    uint256 supplyBefore = _getTotalSupply();

    (uint256 w0, uint256 w1) = _withdrawAs(user, shares);

    (uint256 bal0After, uint256 bal1After) = _getVaultBalances();

    // Expected: bal decreased by w0/w1
    uint256 expected0 = bal0Before * shares / supplyBefore;
    uint256 expected1 = bal1Before * shares / supplyBefore;

    // Allow 2 wei tolerance for rounding
    uint256 diff0 = w0 > expected0 ? w0 - expected0 : expected0 - w0;
    uint256 diff1 = w1 > expected1 ? w1 - expected1 : expected1 - w1;
    t(diff0 <= 2, "withdraw token0 amount deviates from share proportion");
    t(diff1 <= 2, "withdraw token1 amount deviates from share proportion");
}

function property_deposit_no_spot_price_manipulation() public {
    // Capture fair share price before and after deposit
    // Check that a user cannot gain more value than they put in
    uint256 totalSupplyBefore = vault.totalSupply();
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();

    uint256 dep0 = ONE_TOKEN0;
    uint256 dep1 = 0;
    deal(address(wbtc), attacker, dep0);
    vm.startPrank(attacker);
    wbtc.approve(address(vault), type(uint256).max);
    (uint256 shares,,) = vault.deposit(dep0, dep1, 0, 0);
    vm.stopPrank();

    uint256 totalSupplyAfter = vault.totalSupply();
    (uint256 bal0After, uint256 bal1After) = vault.balances();

    // attacker's share of value should not exceed what they deposited
    // shares/totalSupply fraction of total balances should <= deposit input value
    uint256 attackerBal0 = bal0After * shares / totalSupplyAfter;
    uint256 attackerBal1 = bal1After * shares / totalSupplyAfter;

    // Attacker deposited dep0 of token0, should not receive more token0-equivalent back
    // (using a very loose check: attacker's token0 share <= 2x deposit)
    t(attackerBal0 <= dep0 * 2, "attacker extracted excess token0 via spot price manipulation");
}

