    uint256 available = lendingPool.totalLiquidityOfReserve(asset)
        - lendingPool.totalBorrowsOfReserve(asset);

    if (available == 0) return;

    // Attempt to pull MORE than available — should revert or fail
    // If it doesn't revert, property is violated
    uint256 excessAmt = available + 1;

    // We cannot easily test a revert in a property, but we can check
    // that after any sequence of pullFunds, the yToken balance is >= 0
    // and underlyingBalance equals actual balance
    uint256 actualBal = token2.balanceOf(yToken2);
    (,,,,,,,,uint256 underlyingBalance,,) = lendingPool.reserves(asset);

    // underlyingBalance must always match actual token balance held
    // (when no active borrows via borrow(), only pullFunds/pushFunds)
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    gte(actualBal + totalBorrows, underlyingBalance,
        "yToken holds fewer tokens than underlyingBalance claims");
