function property_deposit_redeem_roundtrip() public {
    address asset = address(token0);

    uint256 depositAmt = 10 * ONE_TOKEN0;
    token0.mint(depositor, depositAmt);

    vm.startPrank(depositor);
    token0.approve(address(lendingPool), depositAmt);
    uint256 yAmt = lendingPool.deposit(asset, depositAmt, depositor);
    vm.stopPrank();

    uint256 underlyingBefore = token0.balanceOf(depositor);

    vm.startPrank(depositor);
    IERC20(yToken0).approve(address(lendingPool), yAmt);
    uint256 returnedAmt = lendingPool.redeem(asset, yAmt, depositor);
    vm.stopPrank();

    uint256 underlyingAfter = token0.balanceOf(depositor);

    // After deposit then immediate redeem, should get back ~= depositAmt
    // (allow 1 wei rounding loss but no gain)
    lte(underlyingAfter - underlyingBefore, depositAmt,
        "deposit-redeem roundtrip: got back more than deposited");
    gte(underlyingAfter - underlyingBefore + 2, depositAmt,
        "deposit-redeem roundtrip: lost more than 1 wei");
}

