function property_global_solvency() public {
    // For each reserve, sum of redeemable value <= actual holdings + borrows
    address[3] memory assets = [address(token0), address(token1), address(token2)];
    address[3] memory yTokens = [yToken0, yToken1, yToken2];

    for (uint256 i = 0; i < 3; i++) {
        address asset = assets[i];
        address yt = yTokens[i];

        uint256 ySupply = IERC20(yt).totalSupply();
        if (ySupply == 0) continue;

        uint256 exchangeRate = lendingPool.exchangeRateOfReserve(asset);
        uint256 redeemableTotal = ySupply * exchangeRate / PRECISION;

        uint256 actualHoldings = IERC20(asset).balanceOf(yt);
        uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);

        // All claims must be backed by actual assets + legitimately borrowed funds
        lte(redeemableTotal, actualHoldings + totalBorrows,
            "solvency: total redeemable exceeds actual assets + borrows");
    }
}

function property_pullFunds_updates_underlyingBalance() public {
    address asset = address(token2);
    uint256 pullAmount = ONE_TOKEN2 * 10;

    // record underlyingBalance before pull
    (uint256 totalLiqBefore,) = lendingPool.totalLiquidityOfReserve(asset) == 0
        ? (0, 0)
        : (lendingPool.totalLiquidityOfReserve(asset), 0);
    uint256 actualBalBefore = token2.balanceOf(yToken2);

    // pull funds as leverager (address(this) is set as leverager in setup)
    uint256 safePull = actualBalBefore < pullAmount ? actualBalBefore : pullAmount;
    if (safePull == 0) return;
    lendingPool.pullFunds(asset, safePull);

    uint256 actualBalAfter = token2.balanceOf(yToken2);
    uint256 reportedAvail = lendingPool.totalLiquidityOfReserve(asset);

    // underlyingBalance should have decreased by safePull; reported available
    // liquidity must not exceed actual token balance in yToken contract
    lte(reportedAvail, actualBalBefore, "pullFunds: reported liquidity exceeds pre-pull actual balance");

    // push back to restore
    token2.approve(address(lendingPool), safePull);
    lendingPool.pushFunds(asset, safePull);
}

function property_exchange_rate_reflects_actual_balance() public {
