    // Setup already seeded with lender deposit. Check that after any deposit
    // sequence the exchange rate cannot be manipulated to round a subsequent
    // depositor's yTokens to 0.
    address asset = address(token0);

    uint256 normalDeposit = ONE_TOKEN0; // 1 WBTC
    uint256 yTokensBefore = IERC20(yToken0).totalSupply();

    MockERC20(asset).mint(depositor, normalDeposit);
    vm.startPrank(depositor);
    IERC20(asset).approve(address(lendingPool), normalDeposit);
    uint256 yMinted = lendingPool.deposit(asset, normalDeposit, depositor);
    vm.stopPrank();

    // Depositor should receive a proportional share of yTokens
    // (not 0 due to rounding from inflated exchange rate)
    gte(yMinted, 1, "normal deposit must yield at least 1 yToken");

    // Exchange rate should be close to fair: yMinted / normalDeposit ≈ totalSupply / totalLiquidity
    uint256 exchangeRate = lendingPool.exchangeRateOfReserve(asset);
    // exchangeRate is underlying per yToken scaled by PRECISION
    // implied underlying for yMinted tokens
    uint256 impliedUnderlying = exchangeRate * yMinted / PRECISION;
    // must be within 1 unit of normalDeposit (tight rounding)
    gte(impliedUnderlying + 2, normalDeposit, "yTokens received imply far less underlying than deposited");
