function property_rebalance_not_blocked_by_insufficient_history() public {
    // If the pool has sufficient observation cardinality and the twap window
    // has passed since deployment, rebalance should be callable.
    // We skip the required interval and verify rebalance does not revert
    // just because of the observation history check.
    skip(strategy.rebalanceInterval() + 1);
    try strategy.checkPoolActivity() returns (bool active) {
        // If checkPoolActivity returns false and we have sufficient
        // cardinality, that is the DoS condition.
        // On a mainnet fork with real history this should return true.
        t(active, "DOS-002: checkPoolActivity returns false — rebalance blocked");
    } catch Error(string memory reason) {
        t(false, reason);
    }
}

function property_collectFees_uses_correct_vesting_ticks() public {
    // After adding a vesting position and then rebalancing (which shifts main ticks),
    // collectFees should still use vestPosition.tickUpper for the vesting position.
    // We verify that after collectFees, the vesting position's fees were actually
    // collected (i.e., the position's owed fees in the pool are zero).

    // Record idle balances before
    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();

    // Collect fees
    strategy.collectFees();

    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // If ongoingVestingPosition exists and vesting position has non-zero liquidity,
    // a correct implementation would increase idle balances by the fees.
    // We can at least assert collectFees does not revert.
    // The real check: vesting position fees should use vestPosition.tickUpper
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    if (strategy.ongoingVestingPosition()) {
        // If ticks differ (post-rebalance), the wrong tick is being used
        t(
            vp.tickUpper == mp.tickUpper,
            "DOS-003: vesting tickUpper != main tickUpper — collectFees uses wrong ticks"
        );
    }
}

function property_vesting_position_eventually_completes() public {
    // If a vesting position exists and sufficient time has passed (endTs elapsed),
    // after calling collectFees() the ongoingVestingPosition should be false.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (block.timestamp < vp.endTs) return; // not yet ended

    // endTs has passed — call collectFees to trigger _withdrawPartOfVestingPosition
    strategy.collectFees();

    // After collecting, vesting should be marked as finished
    t(!strategy.ongoingVestingPosition(), "DOS-004: vesting position not cleared after endTs passed");
}

function property_checkPoolActivity_gas_bounded() public {
