function property_collectFees_uses_vesting_ticks() public {
    // Only meaningful when there is an active vesting position
    if (!strategy.ongoingVestingPosition()) return;

    // Capture vesting position ticks before rebalance
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    int24 vestTickLower = vp.tickLower;
    int24 vestTickUpper = vp.tickUpper;

    // After rebalance, main ticks may have changed
    IStrategy.Position memory main = strategy.getMainPosition();

    // If mainPosition.tickUpper has diverged from vestPosition.tickUpper,
    // collectFees will use the wrong tick range.
    // The invariant: if there's an ongoing vesting position, the ticks used in
    // collectPositionFees for the vesting position should equal vestPosition ticks, not main ticks.
    // We can only observe the indirect effect: fees that should have been collected are not.
    // Property: after collectFees, idle balance should not decrease vs. what it was
    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();
    // If ticks mismatch, no fees collected from vesting position => idle won't increase from that source
    // We assert that if tickUpper differs, idle gained should still be >= 0 (no loss from wrong call)
    t(idle0After >= idle0Before || idle1After >= idle1Before, "collectFees reduced idle balances");
}

function property_secondary_position_out_of_range() public {
    // The secondary position must always be out-of-range (OOR).
    // If the pool's current tick is within [secondaryPosition.tickLower, secondaryPosition.tickUpper),
    // then the secondary position is in-range, violating the invariant.
    (, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    if (sec.liquidity == 0) return; // no secondary position active, skip

    bool isOOR = (currentTick < sec.tickLower) || (currentTick >= sec.tickUpper);
    t(isOOR, "secondary position is in-range, should always be OOR");
}

