function property_secondary_ticks_valid_range() public {
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    // tickLower must be strictly less than tickUpper for any minted position
    if (sec.liquidity > 0) {
        t(sec.tickLower < sec.tickUpper, "secondary position has tickLower >= tickUpper");
    }
