    IStrategy.Position memory main = strategy.getMainPosition();
    t(main.tickLower < main.tickUpper, "main position has tickLower >= tickUpper");
}

function property_shares_rounding_consistent() public {
    // Two identical deposits should produce the same shares.
    // If they diverge, precision loss is state-dependent (exploitable).
    (uint256 bal0, uint256 bal1) = strategy.balances();
    if (bal0 == 0 || bal1 == 0) return;
    uint256 totalSupply = vault.totalSupply();
    if (totalSupply == 0) return;

    uint256 deposit0 = ONE_TOKEN0;
    uint256 deposit1 = ONE_TOKEN1 * 60000; // ~$60k USDC per BTC

    // Simulate share calculation for two sequential equal depositors
    uint256 cross0a = deposit0 * bal1;
    uint256 cross1a = deposit1 * bal0;
    uint256 crossa = cross0a > cross1a ? cross1a : cross0a;
    uint256 sharesA = crossa * totalSupply / bal0 / bal1;

    // After first deposit, balances grow
    uint256 newBal0 = bal0 + deposit0;
    uint256 newBal1 = bal1 + deposit1;
    uint256 newSupply = totalSupply + sharesA;

    uint256 cross0b = deposit0 * newBal1;
    uint256 cross1b = deposit1 * newBal0;
    uint256 crossb = cross0b > cross1b ? cross1b : cross0b;
    uint256 sharesB = crossb * newSupply / newBal0 / newBal1;

    // sharesB should be approximately sharesA (within 1 unit rounding)
    uint256 diff = sharesA > sharesB ? sharesA - sharesB : sharesB - sharesA;
    t(diff <= 2, "shares diverge more than rounding allows between equal deposits");
}

