function property_withdraw_no_excess() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;
    uint256 totalSupply = vault.totalSupply();

    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();

    // Withdraw half of user shares
    uint256 sharesToWithdraw = userShares / 2;
    if (sharesToWithdraw == 0) return;

    vm.prank(user);
    (uint256 out0, uint256 out1) = vault.withdraw(sharesToWithdraw, 0, 0);

    // Expected proportional amounts (using pre-withdrawal supply)
    uint256 expected0 = bal0Before * sharesToWithdraw / totalSupply;
    uint256 expected1 = bal1Before * sharesToWithdraw / totalSupply;

    // Actual should not significantly exceed expected (allow 1% tolerance for price movement)
    // If withdrawPartial uses wrong totalSupply (post-burn), out will exceed expected
    uint256 tolerance0 = expected0 / 100 + 1;
    uint256 tolerance1 = expected1 / 100 + 1;
    t(out0 <= expected0 + tolerance0, "withdrew more token0 than fair share");
    t(out1 <= expected1 + tolerance1, "withdrew more token1 than fair share");
}

function property_shares_double_division_no_loss() public {
    // Simulate a deposit and ensure shares computed by double division
    // are no less than shares computed by single division.
    (uint256 bal0, uint256 bal1) = vault.balances();
    if (bal0 == 0 || bal1 == 0) return;
    uint256 totalSup = vault.totalSupply();
    if (totalSup == 0) return;

    uint256 amt0 = 1e6; // 0.01 WBTC
    uint256 amt1 = 1e9; // 1000 USDC

    uint256 cross0 = amt0 * bal1;
    uint256 cross1 = amt1 * bal0;
    uint256 cross = cross0 > cross1 ? cross1 : cross0;
    if (cross == 0) return;

    // Double division (what the code does)
    uint256 sharesDouble = cross * totalSup / bal0 / bal1;
    // Single division (mathematically correct)
    uint256 sharesSingle = cross * totalSup / (bal0 * bal1);

    // Double division must not give fewer shares than single division
    gte(sharesDouble, sharesSingle, "double division under-mints shares");
}

function property_first_deposit_shares_not_token_raw() public {
    // After first deposit, the share price in token0 units should
    // equal the share price in token1 units (at market price).
    // We can only check the simple invariant: first depositor's
    // shares equal max(amt0, amt1) - 1000, regardless of token value.
    // Flag if someone deposits only 1 unit of one token but gets
    // shares proportional to the large token.
    uint256 totalSup = vault.totalSupply();
    if (totalSup != 0) return; // only check first deposit scenario

    uint256 smallAmt0 = 1;         // 1 wei WBTC
    uint256 largeAmt1 = 1e11;      // 100,000 USDC

    // Compute what shares would be
    uint256 expectedShares = (smallAmt0 > largeAmt1 ? smallAmt0 : largeAmt1) - 1000;
    // expectedShares = 1e11 - 1000 based purely on USDC raw amount

    // The burn address gets 1000, first depositor gets 1e11 - 1000
    // 1 wei WBTC is economically ~$0.0001 but grants control of share ratio
    t(expectedShares > 0, "first deposit shares must be positive");
    // Assert the max-based formula is used — this property documents the risk
    // that the formula is purely raw-unit-based, not value-normalized
    t(true, "first deposit formula uses raw max(amount0,amount1) - invariant documented");
}

function property_deposit_transfers_before_shares_check() public {
    // Verify that a deposit that would produce 0 shares does NOT consume tokens.
    // We simulate: if shares would be 0, the revert should NOT transfer tokens.
    (uint256 bal0, uint256 bal1) = vault.balances();
    if (bal0 == 0 || bal1 == 0) return;
    uint256 totalSup = vault.totalSupply();
    if (totalSup == 0) return;

    // Compute dust deposit that would yield 0 shares
    // cross = 1 * bal1, shares = bal1 * totalSup / bal0 / bal1
    // = totalSup / bal0  -- if bal0 > totalSup, this rounds to 0
    if (bal0 <= totalSup) return; // won't produce 0 shares

    uint256 amt0 = 1;
    uint256 amt1 = 1;

    uint256 wbtcBefore = wbtc.balanceOf(user);
    uint256 usdcBefore = usdc.balanceOf(user);

    // Deal user exactly 1 wei each
    deal(address(wbtc), user, 1);
    deal(address(usdc), user, 1);

    vm.prank(user);
    try vault.deposit(amt0, amt1, 0, 0) {
        // If deposit succeeded, user must have received shares
        t(vault.balanceOf(user) > 0, "deposit succeeded but 0 shares minted");
    } catch {
        // deposit reverted — verify user still has their tokens
        // (whole tx reverted, so they should)
        eq(wbtc.balanceOf(user), 1, "wbtc not returned on revert");
        eq(usdc.balanceOf(user), 1, "usdc not returned on revert");
    }
}

function property_withdraw_amount_gte_proportional_entitlement() public {
