function property_rounded_deposit_amounts_match_shares() public {
    (uint256 bal0, uint256 bal1) = vault.balances();
    if (bal0 == 0 || bal1 == 0) return;
    uint256 totalSup = vault.totalSupply();
    if (totalSup == 0) return;

    uint256 amt0In = 2e8;
    uint256 amt1In = 5e6;

    uint256 wbtcBefore = wbtc.balanceOf(depositor);
    uint256 usdcBefore = usdc.balanceOf(depositor);

    deal(address(wbtc), depositor, amt0In);
    deal(address(usdc), depositor, amt1In);

    vm.prank(depositor);
    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amt0In, amt1In, 0, 0);

    uint256 wbtcSpent = amt0In - wbtc.balanceOf(depositor);
    uint256 usdcSpent = amt1In - usdc.balanceOf(depositor);

    // The depositor should only have spent dep0 and dep1
    eq(wbtcSpent, dep0, "wbtc spent != depositAmount0");
    eq(usdcSpent, dep1, "usdc spent != depositAmount1");

    // Shares should reflect the actual deposited amounts, not less
    // i.e. dep0/dep1 ratio should match bal0/bal1 ratio (within 1 wei rounding)
    // dep0 * bal1 should approximately equal dep1 * bal0
    uint256 ratio0 = dep0 * bal1;
    uint256 ratio1 = dep1 * bal0;
    // Allow 1 wei per token rounding: diff <= bal0 + bal1
    uint256 diff = ratio0 > ratio1 ? ratio0 - ratio1 : ratio1 - ratio0;
    lte(diff, bal0 + bal1, "deposit amounts deviate from pool ratio by more than rounding");
}

function property_withdraw_totalSupply_consistency() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;
    uint256 totalSupBefore = vault.totalSupply();

    (uint256 bal0Before, uint256 bal1Before) = vault.balances();

    vm.prank(user);
    (uint256 w0, uint256 w1) = vault.withdraw(userShares, 0, 0);

    uint256 totalSupAfter = vault.totalSupply();

    // totalSupply must decrease by exactly userShares
    eq(totalSupBefore - userShares, totalSupAfter, "totalSupply not decreased by burned shares");

    // Withdrawn amounts must not exceed proportional entitlement
    // Allow 1 wei rounding
    uint256 ent0 = bal0Before * userShares / totalSupBefore;
    uint256 ent1 = bal1Before * userShares / totalSupBefore;
    lte(w0, ent0 + 1, "withdrew more than entitlement for token0");
    lte(w1, ent1 + 1, "withdrew more than entitlement for token1");
}

