function property_spot_price_balances_consistent_with_twap() public {
    // Record vault share price before any manipulation
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();
    uint256 supply = vault.totalSupply();

    // Perform a large swap to move spot price (simulating manipulation)
    _swapWbtcForUsdc(attacker, 5 * ONE_WBTC);

    // Check that balances() reflects a consistent value after swap
    (uint256 bal0After, uint256 bal1After) = vault.balances();

    // The USD value of balances should not change dramatically from a
    // swap alone (conservation of value minus fees).
    // If spot price is used, bal0After + bal1After (in USD terms) will
    // diverge significantly from before the swap.
    uint256 valueBefore = bal0Before * INIT_WBTC_PRICE / ONE_WBTC + bal1Before * INIT_USDC_PRICE / ONE_USDC;
    uint256 valueAfter = bal0After * INIT_WBTC_PRICE / ONE_WBTC + bal1After * INIT_USDC_PRICE / ONE_USDC;

    // Allow 5% deviation
    uint256 deviation = valueBefore > valueAfter ? valueBefore - valueAfter : valueAfter - valueBefore;
    t(deviation * 100 / valueBefore < 5, "ORA-03: balances() using spot price deviates >5% after swap");
}

function property_twap_window_not_manipulable_in_5_minutes() public {
    // This is a documentation property showing the short window risk.
    // We verify that the TWAP price is close to Chainlink oracle price.
    uint256 twap = vault.twapPrice(); // price in 1e30 precision

    // Convert TWAP price (token0/token1 in 1e30) to USD value per WBTC
    // twapPrice = (token0 per token1) in 1e30 precision
    // For WBTC/USDC: price = USDC per WBTC * 1e30 / (1e6 / 1e8) = USDC * 1e32
    // Chainlink WBTC price is in 1e18 (from MockOracle setup: 100_000e18)
    uint256 wbtcChainlinkPrice = priceFeed.getPrice(address(wbtc)); // 1e18 scale

    // twap is in 1e30 precision representing token0/token1
    // For WBTC(8dec)/USDC(6dec): price = WBTC_in_USDC * 10**(30+6-8) = WBTC_in_USDC * 1e28
    // At 100k USDC/WBTC: twap ~ 100_000 * 1e28 = 1e33
    // Chainlink: 100_000e18
    // Ratio: twap / 1e15 should be close to wbtcChainlinkPrice in some scale
    // The key check: TWAP-derived price should be within 2% of Chainlink
    // If TWAP is manipulated, this diverges.

    // Skip time to get past TWAP period and induce manipulated observations
    skip(1 minutes);
    _swapWbtcForUsdc(attacker, 2 * ONE_WBTC); // push price
    skip(1 minutes);
    _swapWbtcForUsdc(attacker, 2 * ONE_WBTC);
    skip(4 minutes);

    uint256 twapAfter = vault.twapPrice();
    // If TWAP window is short, twapAfter will have shifted significantly
    uint256 deviation = twapAfter > twap ? twapAfter - twap : twap - twapAfter;
    // deviation should be < 2% of original twap
    t(deviation * 100 / twap < 2, "ORA-04: TWAP moved >2% in 5 minutes — window too short");
}

