    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity > 0) {
        // Vesting liquidity is NOT counted in balances(), so bal0+bal1 < true total.
        // This property documents the missing accounting:
        t(bal0 > idle0 || bal1 > idle1, "when vesting active, position value should exceed idle");
    }
}

