    uint256 remaining = uint256(vp.remainingLiquidity);
    if (remaining == 0) return;

    uint256 feeRecipientBal0Before = token0.balanceOf(feeRecipient);
    uint256 feeRecipientBal1Before = token1.balanceOf(feeRecipient);

    // Trigger collectFees which will also run _withdrawPartOfVestingPosition
    skip(100);
    strategy.collectFees();

    uint256 feeRecipientBal0After = token0.balanceOf(feeRecipient);
    uint256 feeRecipientBal1After = token1.balanceOf(feeRecipient);

    // Fee recipient should not receive more than protocolFee% of non-vesting income.
    // This is hard to assert precisely, but at minimum the total strategy balance
    // should not decrease by more than the protocol fee on non-vesting sources.
    // As a proxy: fee recipient gains should be 0 if only vesting position exists.
    IStrategy.Position memory mp = strategy.getMainPosition();
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (mp.liquidity == 0 && sp.liquidity == 0) {
        // Only vesting position active - no non-vesting fees should be collected
        // so feeRecipient should receive nothing (vesting fees shouldn't be taxed)
        t(
            feeRecipientBal0After == feeRecipientBal0Before &&
            feeRecipientBal1After == feeRecipientBal1Before,
            "FH-004: protocol fee taken from vesting-only position fees"
        );
    }
}

