}

function property_withdraw_only_owner_receives_funds() public {
    // Only the NFT owner should be able to withdraw funds to themselves.
    // An approved operator calling withdraw should NOT redirect funds to themselves.
    // This property checks: after any withdraw, the position owner still controls
    // their collateral (i.e., withdrawals send to msg.sender, not position owner).
    for (uint256 i = 0; i < openPositionIds.length; i++) {
        uint256 posId = openPositionIds[i];
        // The position must be owned by someone tracked in positionOwner
        address expectedOwner = positionOwner[posId];
        if (expectedOwner == address(0)) continue;
        address nftOwner = leverager.ownerOf(posId);
        eq(nftOwner, expectedOwner, "NFT owner must match tracked position owner");
