function property_liquidation_fee_accounting_correct() public {
    // Verify that borrowedValue calculation uses correct decimal scaling.
    // We check this by comparing the formula used in liquidatePosition vs the correct one.
    // Since we can't call the internal function directly, we reproduce the calculation
    // and assert the correct version gives a sane result.
    uint256 owedAmount = 1e18; // 1 WETH
    uint256 bPrice = PRICE_WETH; // 2500e18
    uint8 decimals = 18;

    // Wrong (as in the code):
    uint256 wrongBorrowedValue = owedAmount * bPrice / decimals;
    // Correct:
    uint256 correctBorrowedValue = owedAmount * bPrice / (10 ** uint256(decimals));

    // The correct value should be ~2500e18; the wrong value should be ~1.39e38
    t(correctBorrowedValue < 1e28, "correct borrowedValue should be in USD range (1e18-1e25)");
    t(wrongBorrowedValue > 1e30, "wrong borrowedValue is astronomically inflated");
    // They should differ by a factor of 10**decimals / decimals = 1e18/18 ~ 5.5e16
    t(wrongBorrowedValue / correctBorrowedValue > 1e15, "wrong value inflated by >1e15x");
}

function property_fee_recipient_initialized() public {
    address fr = leverager.feeRecipient();
    t(fr != address(0), "feeRecipient must not be address(0)");
