function property_withdraw_repay_covers_owed() public {
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.borrowedAmount == 0) return;

    // Invariant: borrowedAmount in position should decrease after a partial withdraw
    // proportional to pctWithdraw
    uint256 borrowedBefore = pos.borrowedAmount;
    uint256 sharesBefore = pos.shares;

    // The ratio borrowed/shares should stay approximately constant after partial withdraw
    if (sharesBefore == 0) return;
    uint256 currentPos_borrowed = leverager.getPosition(posId).borrowedAmount;
    uint256 currentPos_shares = leverager.getPosition(posId).shares;
    if (currentPos_shares == 0) return;

    // ratio should be within 0.1% of original (allow for interest accrual)
    uint256 ratioBefore = borrowedBefore * 1e18 / sharesBefore;
    uint256 ratioAfter = currentPos_borrowed * 1e18 / currentPos_shares;
    uint256 delta = ratioBefore > ratioAfter ? ratioBefore - ratioAfter : ratioAfter - ratioBefore;
    t(delta <= ratioBefore / 100, "borrowed/shares ratio deviated >1% after partial withdraw");
}

function property_flashloan_always_repaid() public {
