function property_token_value_calculation_symmetric() public {
    // If both tokens have pricefeeds, the total USD value should be
    // sum of individual values — no TWAP conversion needed.
    // We verify that having both pricefeeds gives a result independent of TWAP.
    // This is a sanity check: the USD value of 1 WBTC should be ~100000e18.
    uint256 price = vault.twapPrice();
    t(price > 0, "twapPrice must be non-zero");
    // The TWAP price convention: price represents how many token1 per token0 (scaled by 1e30)
    // For WBTC/USDC: ~100000 USDC per WBTC, so price ~ 100000e6 * 1e30 / 1e8 = 100000e28
