function property_withdraw_token1_denom_no_underflow() public {
    // If there are open positions with token1 as denomination, withdraw must not revert with underflow.
    // We test by checking: for a known position where denom == token1 and amountOut0 > amountOut1,
    // the subtraction amountOut1 - repayFromWithdraw >= 0 must hold.
    // Property: for any position with denomination == token1, after withdrawal calculation,
    // shares * vaultBal1 / totalSupply >= repayFromWithdraw used
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.denomination != address(usdc)) return; // only check token1 denom positions
    if (pos.shares == 0) return;

    uint256 totalSupply = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 userBal0 = pos.shares * bal0 / totalSupply;
    uint256 userBal1 = pos.shares * bal1 / totalSupply;

    // The bug: repayFromWithdraw = userBal0 when userBal1 < owedAmount
    // Check that userBal1 >= userBal0 would be needed to avoid underflow
    // Actually the invariant is: userBal1 should not underflow when subtracting userBal0
    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;
    if (userBal1 < owedAmount) {
        // This is the buggy branch: repayFromWithdraw = userBal0
        // Safe only if userBal1 >= userBal0
        gte(userBal1, userBal0, "DOS-LEV-02: withdraw underflow when token1==denom and amountOut0 > amountOut1");
    }
}

function property_liquidation_borrowedValue_correct_scaling() public {
    // The borrowedValue must be computed with 10**decimals, not raw decimals.
    // Invariant: for any open position, the decimals divisor must be >= 1e6 (not 6).
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.shares == 0) return;

    // Check that denomination decimals when used as divisor gives correct USD value
    // For USDC (6 decimals): 1e6 USDC * 1e18 price / 1e6 = 1e18 USD (correct)
    //                         1e6 USDC * 1e18 price / 6 = 1.67e23 USD (wrong)
    uint256 rawDecimals = ERC20(pos.denomination).decimals();    // e.g. 6
    uint256 scaledDecimals = 10 ** rawDecimals;                  // e.g. 1e6
    uint256 bPrice = priceFeed.getPrice(pos.denomination);
    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;

    uint256 correctBorrowedValue = owedAmount * bPrice / scaledDecimals;
    uint256 buggyBorrowedValue   = owedAmount * bPrice / rawDecimals;

    // They must be equal — if they differ, the bug is confirmed
    eq(correctBorrowedValue, buggyBorrowedValue,
       "DOS-LEV-03: borrowedValue uses raw decimals (e.g. 6) not scaled (e.g. 1e6)");
}

