function property_withdraw_token1_denom_accounting_correct() public {
    // Invariant: after withdraw(), if denomination is token1, amountOut1 accounting must use
    // amountOut1 not amountOut0 in the repayFromWithdraw calculation.
    // We verify the bug by checking: for positions with denom=token1,
    // the repayment deduction from amountOut1 must not exceed amountOut1 itself.
    if (openPositionIds.length == 0) return;
    for (uint256 i = 0; i < openPositionIds.length; i++) {
        uint256 posId = openPositionIds[i];
        ILeverager.Position memory pos = leverager.getPosition(posId);
        if (pos.denomination != address(usdc)) continue;
        if (pos.shares == 0) continue;

        uint256 totalSupply = vault.totalSupply();
        if (totalSupply == 0) continue;

        (uint256 bal0, uint256 bal1) = vault.balances();
        uint256 pctWithdraw = 1e18; // 100% withdrawal
        uint256 sharesToWithdraw = pos.shares * pctWithdraw / 1e18;
        uint256 amountOut0 = bal0 * sharesToWithdraw / totalSupply;
        uint256 amountOut1 = bal1 * sharesToWithdraw / totalSupply;

        uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
        uint256 totalOwed = pos.borrowedAmount * bIndex / pos.borrowedIndex;
        uint256 owedAmount = totalOwed * pctWithdraw / 1e18;

        if (amountOut1 < owedAmount) {
            // Buggy code uses amountOut0 here. repayFromWithdraw should be amountOut1.
            // Then amountOut1 -= amountOut0 -- if amountOut0 > amountOut1, this underflows.
            // Even without underflow, the accounting is wrong: we subtract token0 units from token1.
            t(
                amountOut1 >= amountOut0,
                "DOS-LEV-06: withdraw bug: amountOut1 - amountOut0 would underflow (denom=token1)"
            );
        }
    }
}

