// Direct code audit check: verify the bug line
function property_withdraw_repayFromWithdraw_uses_correct_token() public pure {
    // The bug is at Leverager.sol line ~232:
    // `uint256 repayFromWithdraw = amountOut1 < owedAmount ? amountOut0 : owedAmount;`
    // should be:
    // `uint256 repayFromWithdraw = amountOut1 < owedAmount ? amountOut1 : owedAmount;`
