function property_initCollateralValue_decimal_consistency() public {
    // Verify PriceFeed returns prices in expected scale
    // MockOracle is set to PRICE_USDC = 1e18 in Setup.sol
    // So with the mock, bPrice = 1e18 (correct 1e18 scaling)
    // The formula: initCollateralUsd * 10^decimals / bPrice
    // = value_1e18 * 1e6 / 1e18 = value / 1e12
    // For $1 = 1e18, result = 1e18 * 1e6 / 1e18 = 1e6 ✓ (1 USDC)
    // This works correctly WITH the mock oracle (1e18 scaled)
    // but would break with real Chainlink (1e8 scaled)
    uint256 bPrice = priceFeed.getPrice(USDC_ADDR); // MockOracle returns 1e18
    uint256 usdValue = 1e18; // $1 in 1e18 scaling
    uint256 denomDecimals = 10 ** ERC20(USDC_ADDR).decimals(); // 1e6
    uint256 collateralValue = usdValue * denomDecimals / bPrice;
    // With mock: 1e18 * 1e6 / 1e18 = 1e6 = 1 USDC ✓
    // With real Chainlink 8-dec: 1e18 * 1e6 / 1e8 = 1e16 ✗ (off by 1e10)
    // Property: collateralValue should be denomDecimals (1 unit of denomination per $1)
    t(collateralValue == denomDecimals, "MATH-05: initCollateralValue uses wrong price scale for denomination");
}

function property_liquidation_fee_accounting_correct() public {
    // If borrowedValue formula is wrong, the fee block is always skipped.
    // We verify the formula produces a value comparable in scale to totalValueUSD.
    // totalValueUSD is in 1e18. borrowedValue should also be in 1e18.
    // Formula: owedAmount * bPrice / ERC20(denomination).decimals()
    // With USDC: owedAmount_1e6 * bPrice_1e18 / 6 -- NOT 1e18 scale!
    // Correct: owedAmount_1e6 * bPrice_1e18 / 1e6 = USD value in 1e18 ✓

    // Test: 100 USDC owed * $1 price = $100 USD
    uint256 owedAmount = 100e6; // 100 USDC
    uint256 bPrice = 1e18;      // $1 per USDC (1e18 scaled)

    // Buggy: divide by raw decimals() = 6
    uint256 buggyBorrowedValue = owedAmount * bPrice / 6;
    // Correct: divide by 10**decimals() = 1e6
    uint256 correctBorrowedValue = owedAmount * bPrice / 1e6;

    // borrowedValue should equal $100 in 1e18 = 100e18
    // Buggy gives: 100e6 * 1e18 / 6 ≈ 1.67e25 (not 100e18)
    // Correct gives: 100e6 * 1e18 / 1e6 = 100e18 ✓

    t(buggyBorrowedValue == correctBorrowedValue,
      "MATH-06: borrowedValue in liquidation uses raw decimals() instead of 10**decimals()");
}

