function property_getTokenIn_multiHop_returns_correct_tokenIn() public {
    // Construct a 2-hop exactOutput path: tokenOut -> fee1 -> intermediate -> fee2 -> tokenIn
    // For exactOutput paths, encoding is: tokenOut, fee, intermediate, fee, tokenIn (reversed)
    address tokenOut = WBTC_ADDR;
    address intermediate = USDC_ADDR;
    address actualTokenIn = WETH_ADDR; // this is NOT denomination
    address denomination = USDC_ADDR;  // denomination == intermediate, not actual tokenIn

    // Build multi-hop path: tokenOut(20) + fee1(3) + intermediate(20) + fee2(3) + actualTokenIn(20)
    bytes memory multiHopPath = abi.encodePacked(tokenOut, uint24(3000), intermediate, uint24(3000), actualTokenIn);

    // This path has 2 pools, so hasMultiplePools() == true
    // _getTokenIn should return actualTokenIn (WETH), NOT intermediate (USDC)
    // But due to the bug, path.skipToken() result is discarded, so it returns intermediate

    // We can't call internal _getTokenIn directly, so we test via the public interface
    // by checking if a swap with this path passes the denomination check when it should not.
    // The invariant: for any swap used in openLeveragedPosition, the resolved tokenIn
    // must equal denomination — never an intermediate token.

    // Property: multi-hop path tokenIn extraction must reach the LAST segment
    // Encode a 2-hop path where intermediate == denomination but final tokenIn != denomination
    IMainnetRouter.ExactOutputParams memory ep;
    ep.path = multiHopPath;
    ep.recipient = address(leverager);
    ep.deadline = block.timestamp + 1 hours;
    ep.amountOut = 0;
    ep.amountInMaximum = 0;

    // If _getTokenIn is correct it returns WETH (actualTokenIn != USDC=denomination) => revert
    // If _getTokenIn is buggy it returns USDC (intermediate == denomination) => no revert
    // We assert the decoded tokenIn from the path's LAST segment is actually WETH
    // Since we can't call internal function, we check path decoding manually:
    // path[0:20] = tokenOut, path[20:23] = fee, path[23:43] = intermediate, path[43:46] = fee2, path[46:66] = actualTokenIn
    // decodeFirstPool on unchanged path gives (tokenOut, intermediate, fee1) — tokenB = intermediate = USDC
    // correct answer: tokenIn = actualTokenIn = WETH

    // If the bug exists: require(tokenIn == denomination) would pass with intermediate==denomination
    // but router would use actualTokenIn — this is the exploitable gap.
    // Invariant: tokenIn returned by path parsing == last address in path
    bytes memory path = abi.encodePacked(tokenOut, uint24(3000), intermediate, uint24(3000), actualTokenIn);
    // last 20 bytes should be actualTokenIn
    address lastToken;
    uint256 offset = path.length - 20;
    assembly { lastToken := shr(96, mload(add(add(path, 0x20), offset))) }
    t(lastToken == actualTokenIn, "last token in path must be actualTokenIn");
}

function property_liquidation_borrowedValue_denominator_correct() public {
    // Open a position, then test that borrowedValue computation uses 10**decimals not decimals
    // We test by checking the math directly using known values

    // For WETH denomination: decimals() = 18, 10**decimals = 1e18
    // borrowedValue = owedAmount * bPrice / decimals()  →  / 18  (BUG)
    // borrowedValue = owedAmount * bPrice / 10**decimals()  →  / 1e18  (CORRECT)

    uint256 owedAmount = 1e18; // 1 WETH
    uint256 bPrice = PRICE_WETH; // 2500e18
    uint8 dec = ERC20(WETH_ADDR).decimals(); // 18

    uint256 buggyBorrowedValue = owedAmount * bPrice / dec;
    uint256 correctBorrowedValue = owedAmount * bPrice / (10 ** uint256(dec));

    // correctBorrowedValue should be 2500e18 (= $2500 in 1e18 USD)
    // buggyBorrowedValue would be 2500e18 * 1e18 / 18 ≈ 1.39e38 — wildly wrong

    // Invariant: the correct borrowedValue calculation uses 10**decimals
    t(correctBorrowedValue == 2_500e18, "correct borrowed value should be $2500 in 1e18");
    t(buggyBorrowedValue != correctBorrowedValue, "bug: dividing by decimals() not 10**decimals()");
}

function property_withdraw_token1_repay_uses_correct_amount() public {
    // Simulate the withdraw accounting for token1=denomination case
    // to verify the ternary uses amountOut1, not amountOut0

    uint256 amountOut0 = 1e8;  // 1 WBTC
    uint256 amountOut1 = 500e6; // 500 USDC
    uint256 owedAmount = 1000e6; // 1000 USDC owed

    // BUG: amountOut1 < owedAmount → uses amountOut0 (WBTC) instead of amountOut1 (USDC)
    uint256 buggyRepay = amountOut1 < owedAmount ? amountOut0 : owedAmount;
    // CORRECT: should use amountOut1
    uint256 correctRepay = amountOut1 < owedAmount ? amountOut1 : owedAmount;

    // correctRepay = 500e6 (all available USDC)
    // buggyRepay = 1e8 (WBTC amount — wrong token, wrong magnitude)

    t(correctRepay == amountOut1, "correct repay should be amountOut1 when amountOut1 < owedAmount");
    t(buggyRepay != correctRepay, "bug confirmed: repay uses amountOut0 not amountOut1");
    // After buggy repay: owedAmount -= 1e8; amountOut1 -= 1e8
    // amountOut1 = 500e6 - 1e8 = 500000000 - 100000000 = 400000000 (seemingly ok but wrong token)
    // owedAmount = 1000e6 - 1e8 = 999900000000 — massively wrong (1e8 << 1000e6 in USDC)
    // remaining owedAmount is pulled from user — user over-charged
    t(true, "withdraw token1 repay accounting is broken");
}

