function property_oracle_staleness_enforced() public {
    // Verify that PriceFeed enforces a heartbeat by checking that
    // the oracle's updatedAt is recent enough.
    // If the mock oracle's updatedAt is more than heartbeat seconds ago,
    // getPrice should revert. In the current code it does NOT revert.
    // This property documents the missing check.
    (,,,uint256 heartbeat) = priceFeed.pricefeeds(WBTC_ADDR);
    // wbtcOracle is a MockOracle; set a stale timestamp
    // The real invariant: after heartbeat elapses without an oracle update,
    // any call to leverager that reads prices should revert.
    // We verify the price is still returned (i.e., the bug exists).
    uint256 priceNow = priceFeed.getPrice(WBTC_ADDR);
    // Advance time beyond heartbeat (604800 seconds)
    vm.warp(block.timestamp + heartbeat + 1);
    // Should revert but does NOT — this is the bug
    uint256 priceStale = priceFeed.getPrice(WBTC_ADDR);
    // Both calls return the same value: staleness is not enforced
    eq(priceNow, priceStale, "stale price returned without revert");
}

function property_liquidation_fee_decimal_bug() public {
    // Demonstrates the decimal bug by showing the division uses
    // raw decimals() instead of 10**decimals().
    // USDC has 6 decimals. The bug divides by 6, not 1e6.
    uint256 decimalsRaw = ERC20(USDC_ADDR).decimals(); // = 6
    uint256 decimalsCorrect = 10 ** decimalsRaw;       // = 1e6
    // With bPrice = PRICE_USDC = 1e18 and owedAmount = 1000e6:
    uint256 owedAmount = 1000 * ONE_USDC;
    uint256 bPrice = PRICE_USDC; // 1e18
    uint256 borrowedValueBuggy  = owedAmount * bPrice / decimalsRaw;
    uint256 borrowedValueCorrect = owedAmount * bPrice / decimalsCorrect;
    // borrowedValueBuggy ~= 1.67e26, borrowedValueCorrect = 1000e18
    // The invariant: borrowedValue should equal owedAmount in USD (1e18-scaled)
    // i.e., borrowedValueCorrect == owedAmount (since USDC price = $1)
    eq(borrowedValueCorrect, owedAmount * PRICE_USDC / ONE_USDC, "correct USD value");
    // The bug: borrowedValueBuggy >> totalValueUSD always, so fee never charged
    t(borrowedValueBuggy > borrowedValueCorrect * 100_000, "bug: divisor is raw decimals not 10**decimals");
}

