function property_liquidation_borrowed_value_correct() public {
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.shares == 0) return;
    if (!leverager.isLiquidateable(posId)) return;

    // Pre-liquidation: compute what borrowedValue SHOULD be
    uint256 bPrice = priceFeed.getPrice(pos.denomination);
    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;
    uint256 decimalsScaled = 10 ** ERC20(pos.denomination).decimals();
    uint256 correctBorrowedValue = owedAmount * bPrice / decimalsScaled;

    // The buggy computation in the contract divides by .decimals() (uint8)
    uint256 buggyBorrowedValue = owedAmount * bPrice / uint256(ERC20(pos.denomination).decimals());

    // These must be equal for the liquidation accounting to be correct
    // If they differ, the protocol fee and surplus calc are broken
    eq(correctBorrowedValue, buggyBorrowedValue, "borrowedValue decimals wrong");
}

