function property_withdraw_token1_denomination_correct_repay() public {
    // Configurar una posición donde denomination = token1 (USDC)
    // y amountOut1 < owedAmount para triggear el bug
    // Esta propiedad verifica que despues de withdraw parcial,
    // el total owed disminuye correctamente
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.denomination != address(usdc)) return;
    if (pos.shares == 0) return;

    uint256 bIndexBefore = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedBefore = pos.borrowedAmount * bIndexBefore / pos.borrowedIndex;

    // El balance del contrato Leverager en token1 no deberia aumentar
    // despues de withdraw (tokens deberian ir al usuario o al pool)
    uint256 leveragerUsdcBefore = usdc.balanceOf(address(leverager));

    // Invariante: si hay posicion abierta con denomination=token1,
    // el contrato Leverager no debe acumular token1
    t(leveragerUsdcBefore == 0, "Leverager should not hold USDC between txs");
}

function property_liquidation_fee_calc_uses_correct_decimals() public {
    // Verificar que borrowedValue se calcula correctamente.
    // Abrimos posicion y verificamos que si hay profit, el calculo es sensato.
    // El bug hace que borrowedValue sea ~166666x mayor de lo correcto.
    // Invariante: para USDC (6 decimals), no deberia poder ocurrir que
    // borrowedValue > totalSupply() de USDC multiplicado por su precio.
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.denomination != address(usdc)) return;

    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;
    uint256 bPrice = priceFeed.getPrice(address(usdc)); // 1e18

    // Calculo correcto (lo que deberia ser):
    uint256 correctBorrowedValue = owedAmount * bPrice / (10 ** 6);
    // Calculo buggy (lo que hace el codigo):
    uint256 buggyBorrowedValue = owedAmount * bPrice / 6;

    // El valor buggy es ~166,666x mayor que el correcto
    // Si esto es cierto, las fees de liquidacion nunca se cobran
    t(buggyBorrowedValue / correctBorrowedValue < 2, "borrowedValue inflated: decimals() used instead of 10**decimals()");
}

