function property_token_value_calculation_no_precision_loss() public {
    // Para tokens sin pricefeed, el calculo de conversion debe preservar precision
    // Invariante: el valor USD total de una posicion no deberia truncar a 0
    // para cantidades razonables de tokens
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.shares == 0) return;

    // Si la posicion tiene shares, su valor USD deberia ser positivo
    // (asumiendo precios no-zero)
    (uint256 vaultBal0, uint256 vaultBal1) = vault.balances();
    uint256 totalSupply = vault.totalSupply();
    if (totalSupply == 0) return;

    uint256 userBal0 = pos.shares * vaultBal0 / totalSupply;
    uint256 userBal1 = pos.shares * vaultBal1 / totalSupply;

    // Si el usuario tiene balance, deberia tener valor USD positivo
    if (userBal0 > 0 || userBal1 > 0) {
        uint256 price = vault.twapPrice();
        // Verificar que el calculo no produce 0 para valores razonables
        // (propiedad de sanidad del calculo)
        t(price > 0, "TWAP price should be positive for value calculation");
    }
}

function property_collectFees_uses_vest_tickUpper() public {
    // Ensure an ongoing vesting position exists
    if (!strategy.ongoingVestingPosition()) return;

    // Read vesting position
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // The correct range for vesting fee collection must use vestPosition.tickUpper
    // The bug is in collectFees: it uses mainPosition.tickUpper instead
    IStrategy.Position memory main = strategy.getMainPosition();

    // After a rebalance that moves main ticks, vestPosition.tickUpper
    // should differ from mainPosition.tickUpper
    // This property checks that the stored vesting tickUpper equals
    // the tickUpper the contract SHOULD be using for fee collection
    // (i.e., it should equal the main tickUpper at the time the vesting
    //  position was created, not the current main tickUpper)

    // We trigger fee collection
    strategy.collectFees();

    // The vesting position's tickUpper is unchanged (no rebalance of vesting pos)
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(vp.tickUpper, vpAfter.tickUpper, "vesting tickUpper should not change on collectFees");
}

