function property_getTokenIn_multiHop_does_not_infinite_loop() public {
    // Build a two-hop exactOutput path: USDC -> WETH -> WBTC
    // encoding: tokenOut (wbtc,20) | fee(3) | tokenMid(weth,20) | fee(3) | tokenIn(usdc,20)
    bytes memory multiHopPath = abi.encodePacked(
        address(wbtc), uint24(3000),
        address(weth), uint24(3000),
        address(usdc)
    );
    // If the infinite-loop bug exists, this call will OOG revert.
    // We wrap it so the property catches the revert rather than propagating it.
    // The property asserts the call returns (i.e. does NOT loop forever).
    // We call openLeveragedPosition with a multi-hop swapParams to exercise _getTokenIn.
    // Using a simple direct call to a public wrapper is the cleanest approach:
    // Since _getTokenIn is internal, we trigger it indirectly via openLeveragedPosition.
    // We just verify that a properly constructed multi-hop open call doesn't OOG.
    // For fuzzing purposes, we note the bug is demonstrated if gas_left drops to 0.
    uint256 gasBefore = gasleft();
    // Construct a minimal LeverageParams that reaches the _getTokenIn branch:
    // denomination = weth (neither token0 nor token1 of vault), vault0In > amount0In
    ILeverager.LeverageParams memory lp;
    lp.amount0In    = 0;
    lp.amount1In    = 0;
    lp.vault0In     = ONE_WBTC / 10;
    lp.vault1In     = 0;
    lp.min0in       = 0;
    lp.min1in       = 0;
    lp.vault        = address(mockVault);
    lp.denomination = address(weth);
    lp.maxBorrowAmount = ONE_WETH / 10;

    IMainnetRouter.ExactOutputParams memory ep;
    ep.path            = multiHopPath;
    ep.recipient       = address(leverager);
    ep.deadline        = block.timestamp + 1 hours;
    ep.amountInMaximum = type(uint256).max;
    lp.swapParams1 = abi.encode(ep);

    wbtc.mint(address(this), ONE_WBTC);
    weth.mint(address(this), ONE_WETH);
    wbtc.approve(address(leverager), type(uint256).max);
    weth.approve(address(leverager), type(uint256).max);
    weth.mint(address(lendingPool), 10 * ONE_WETH);

    try leverager.openLeveragedPosition(lp) {
        // call returned — no infinite loop
    } catch {
        // any revert other than OOG is acceptable; the bug manifests as OOG
    }
    // If we consumed all gas the test harness would itself revert; surviving here proves no OOG loop
    uint256 gasAfter = gasleft();
    t(gasBefore - gasAfter < 2_000_000, "consumed suspiciously large gas — possible infinite loop");
}

