function property_liquidation_fee_reaches_recipient_on_profitable_liq() public returns (bool) {
    // Configure non-zero liquidation fee
    vm.prank(owner);
    leverager.setLiquidationFee(500); // 5%

    // Open a well-collateralised WBTC-denominated position
    // User provides 2 WBTC, borrows 1 WBTC → 3 WBTC total deposited
    uint256 collateral = 2 * ONE_WBTC;
    uint256 borrowed   = 1 * ONE_WBTC;
    wbtc.mint(user1, collateral);

    ILeverager.LeverageParams memory lp = _buildSimpleWBTCParams(
        collateral, // amount0In
        0,          // amount1In
        borrowed,   // delta0
        0           // borrowExtra
    );
    vm.prank(user1);
    uint256 posId = leverager.openLeveragedPosition(lp);

    // Make position liquidatable: crash WBTC price 90 %
    _setWBTCPrice(10_000e18); // $10k per WBTC

    // Verify position is now liquidatable
    if (!leverager.isLiquidateable(posId)) return true; // not liquidatable, skip

    // Record feeRecipient balance (address(0) due to HYP-DD-001)
    address recipient = leverager.feeRecipient();
    uint256 recipientBefore = wbtc.balanceOf(recipient);

    // Liquidator executes liquidation
    wbtc.mint(liquidator, 5 * ONE_WBTC);
    vm.startPrank(liquidator);
    wbtc.approve(address(leverager), type(uint256).max);
    ILeverager.LiquidateParams memory liqP;
    liqP.id        = posId;
    liqP.hasToSwap = false;
    liqP.minAmount0 = 0;
    liqP.minAmount1 = 0;
    leverager.liquidatePosition(liqP);
    vm.stopPrank();

    uint256 recipientAfter = wbtc.balanceOf(recipient);

    // Property: if liquidationFee > 0 and position had surplus,
    // feeRecipient MUST have received tokens.
    // This FAILS because:
    //   a) borrowedValue is overstated → fee never computed (HYP-DD-002)
    //   b) feeRecipient == address(0) → transfer would revert (HYP-DD-001)
    return recipientAfter > recipientBefore;
}

function property_withdraw_token1_denom_no_underflow() public returns (bool) {
    // Open a USDC-denominated position (token1 = usdc = denomination)
    // No swaps needed because denomination == token1
    uint256 amt1    = 100_000 * ONE_USDC;
