    usdc.mint(user1, amt1);

    ILeverager.LeverageParams memory lp = _buildSimpleUSDCParams(
        0,      // amount0In
        amt1,   // amount1In
        delta1, // delta1
        0       // borrowExtra
    );
    vm.prank(user1);
    uint256 posId = leverager.openLeveragedPosition(lp);

    // Snapshot state before partial withdrawal
    ILeverager.Position memory posBefore = _getPosition(posId);

    // Build WithdrawParams for 50 % withdrawal (no swaps — denomination == token1)
    ILeverager.WithdrawParams memory wp;
    wp.id          = posId;
    wp.pctWithdraw = 0.5e18;
    wp.minAmount0  = 0;
    wp.minAmount1  = 0;
    wp.hasToSwap   = false;

