function property_withdraw_lendingpool_borrows_decrease_correctly() public returns (bool) {
    // Open USDC-denominated position
    uint256 amt1   = 200_000 * ONE_USDC;
    uint256 delta1 =  50_000 * ONE_USDC;
    usdc.mint(user1, amt1);

    ILeverager.LeverageParams memory lp = _buildSimpleUSDCParams(0, amt1, delta1, 0);
    vm.prank(user1);
    uint256 posId = leverager.openLeveragedPosition(lp);

    uint256 totalBorrowsBefore = _getTotalBorrows(address(usdc));

    // Compute expected repayment for 50 % withdrawal
    ILeverager.Position memory pos = _getPosition(posId);
    uint256 bIndex       = _getBorrowingIndex(address(usdc));
    uint256 totalOwed    = pos.borrowedAmount * bIndex / pos.borrowedIndex;
    uint256 expectedRepay = totalOwed / 2; // 50 % pctWithdraw

    ILeverager.WithdrawParams memory wp;
    wp.id          = posId;
    wp.pctWithdraw = 0.5e18;
    wp.minAmount0  = 0;
    wp.minAmount1  = 0;
    wp.hasToSwap   = false;

    usdc.mint(user1, expectedRepay * 2);
    vm.startPrank(user1);
    usdc.approve(address(leverager), type(uint256).max);

    try leverager.withdraw(wp) {
        vm.stopPrank();
        uint256 totalBorrowsAfter = _getTotalBorrows(address(usdc));
        // Lending pool borrows should have decreased by at least expectedRepay
        // Property FAILS if borrows didn't decrease (incorrect accounting)
        return totalBorrowsAfter <= totalBorrowsBefore - expectedRepay;
    } catch {
        vm.stopPrank();
        return false; // underflow DoS bug (HYP-DD-003) also violates this property
    }
}

