function property_leverager_balance_not_drained_by_opener() public returns (bool) {
    // Donate WBTC directly to Leverager (simulating stuck tokens)
    uint256 donated = ONE_WBTC; // 1 WBTC = $100k
    wbtc.mint(address(leverager), donated);

    uint256 user2BalBefore = wbtc.balanceOf(user2);

