function property_price_feed_rejects_stale_data() public returns (bool) {
    // Advance time past the oracle heartbeat (604800 seconds = 1 week)
    vm.warp(block.timestamp + 604_801);

    // If the heartbeat check is active, getPrice should revert for WBTC
    // (oracle was last updated at deployment, now stale)
    try priceFeed.getPrice(address(wbtc)) returns (uint256) {
        // Returned a price despite staleness — heartbeat check is inactive
        return false; // BUG: stale price accepted
    } catch {
        // Reverted as expected — staleness check is enforced
        return true;
    }
}

