function property_collect_fees_uses_vest_upper_tick() public {
    // If there is an ongoing vesting position, collectFees should operate
    // on vestPosition.tickUpper, not mainPosition.tickUpper.
    // We verify this indirectly: after addVestingPosition, if the vesting
    // ticks differ from main ticks (after a rebalance changes main ticks),
    // collectFees must not silently drop fees.

    // Record state before
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: line 167 uses mainPosition.tickUpper instead of vestPosition.tickUpper
    // This property asserts the two tick uppers must match for collectFees to be correct
    // when there is an ongoing vesting position:
    if (strategy.ongoingVestingPosition()) {
        // If they diverge, collectFees operates on wrong position
        // We assert they are equal as the invariant the code assumes but doesn't enforce
        t(
            vp.tickUpper == mp.tickUpper,
            "vestPosition.tickUpper != mainPosition.tickUpper: collectFees uses wrong ticks"
        );
    }
}

function property_only_owner_changes_position_width() public {
    // changePositionWidth should require onlyOwner, not be open to rebalancer.
    // We verify that after a non-owner, non-rebalancer call attempt, positionWidth is unchanged.
    uint24 widthBefore = strategy.positionWidth();

    // Attempt by attacker (not owner, not rebalancer) — should revert at rebalance()
    // Attempt by rebalancer — succeeds, which is the bug (rebalancer should not control width)
    // This property documents the missing onlyOwner check.
    // If attacker could change width, it would be a critical bug:
    vm.prank(attacker);
    try strategy.changePositionWidth(uint24(strategy.tickSpacing()) * 4) {
        // If this succeeds, attacker changed positionWidth — critical
        t(false, "attacker should not be able to changePositionWidth");
    } catch {
        // Expected — reverts because onlyRebalancer in rebalance()
    }

    uint24 widthAfter = strategy.positionWidth();
    eq(uint256(widthBefore), uint256(widthAfter), "positionWidth changed by non-authorized caller");
}

function property_secondary_position_is_out_of_range() public {
    // The secondary position should always be Out-Of-Range (OOR).
    // i.e., the current tick should NOT be inside [secondaryPosition.tickLower, secondaryPosition.tickUpper).
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return; // nothing to check

    (, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    bool inRange = (currentTick >= sp.tickLower && currentTick < sp.tickUpper);
    t(!inRange, "secondary position is in-range, should always be OOR after rebalance");
}

function property_vesting_duration_nonzero() public {
    // A vesting position with duration 0 should not be allowed.
    // If one is created, it immediately fully vests on the next collectFees call.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    // endTs must be strictly greater than startTs for meaningful vesting
    t(vp.endTs > vp.startTs, "vesting position endTs <= startTs: zero-duration vest");
}

function property_collect_fees_idempotent_within_block() public {
    // collectFees called twice in the same block should not change balances twice.
    // _withdrawPartOfVestingPosition has a guard: if (vestPosition.lastUpdate == block.timestamp) return;
    // so the second call should be a no-op for the vesting logic.
    (uint256 bal0Before, uint256 bal1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 bal0Mid, uint256 bal1Mid) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 bal0After, uint256 bal1After) = strategy.idleBalances();

    // The second collectFees should not transfer more fees than the first
    // (idle balances should not decrease further due to protocol fee on zero delta)
    gte(bal0After, bal0Mid, "second collectFees reduced idle0 further");
    gte(bal1After, bal1Mid, "second collectFees reduced idle1 further");
}

function property_vesting_fees_collected_correctly() public {
    // After a rebalance that changes main ticks, vesting position fees must still
    // be collected using vestPosition's own tick range, not mainPosition's ticks.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // After rebalance, main ticks may differ from vest ticks.
    // The bug manifests when tickUpper values diverge.
    // This property asserts that any divergence exposes the bug:
    if (vp.tickUpper != mp.tickUpper || vp.tickLower != mp.tickLower) {
        // At this point, collectFees is BROKEN for the vesting position.
        // We record that the positions have diverged — this is the vulnerable state.
        t(
            false,
            "vest ticks diverged from main ticks: collectFees line 167 uses wrong tickUpper"
        );
    }
}

