    // Build WETH params where we attempt to set wrong recipient
    ILeverager.LeverageParams memory lp = _buildWETHParams(amt0, amt1, 1 * ONE_WBTC, 0, maxBorrow);

    // Decode swapParams1 and change recipient to user2 (adversarial)
    IMainnetRouter.ExactOutputParams memory ep = abi.decode(lp.swapParams1, (IMainnetRouter.ExactOutputParams));
    ep.recipient = user2; // attacker redirects output
