    // A tiny amount of WBTC should still compute a non-zero USD value via TWAP.
    // We can't easily remove wbtc oracle, but we can test the math directly
    // by checking isLiquidateable uses consistent valuation.
    uint256 amt0 = 1; // 1 satoshi = 0.00000001 WBTC
    uint256 amt1 = 1 * ONE_USDC;
    uint256 price = INIT_TWAP_PRICE; // 100_000 * 1e28

    // price * amt0 = 100_000 * 1e28 * 1 = 1e33
    // 1e33 / PRECISION(1e30) = 1000 (non-zero for this case)
    // But if amt0 = 0 and amt1 has value, no issue.
    // Verify that _calculateTokenValues does not truncate for 1 satoshi:
    // expected USD = 1 satoshi * 100000 USD/BTC = $0.001 = 1e15 in 1e18 terms
    // Actual: (1 * 1e33) / 1e30 * 1e18 / 1e6 = 1000 * 1e12 = 1e15 ✓
    // Edge: if price were 1e18 (< PRECISION): (1 * 1e18) / 1e30 = 0 → BUG
    // This property checks no active position can have 0 collateral value
    // when it has non-zero shares and non-zero vault balances.
    uint256 posAmt0 = 1 * ONE_WBTC;
