    ILeverager.LeverageParams memory lp = _buildSimpleWBTCParams(posAmt0, posAmt1, delta0, 0);
    uint256 posId = leverager.openLeveragedPosition(lp);
    vm.stopPrank();

    ILeverager.Position memory pos = leverager.getPosition(posId);
    t(pos.initCollateralUsd > 0, "collateral USD value should not be zero");
