function property_collectFees_vestingTickConsistency() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;
    IStrategy.VestingPosition memory vp = _getVestingPosition();
    IStrategy.Position memory mp = _getMainPosition();
    // collectFees calls: collectPositionFees(vestPosition.tickLower, mainPosition.tickUpper)
    // For fee collection to target the correct vesting position, mainPosition.tickUpper
    // must equal vestPosition.tickUpper at all times while vesting is active.
    // After a rebalance (which changes mainPosition ticks but not vestPosition ticks),
    // this invariant breaks — revealing the wrong-tick bug in collectFees.
    return vp.tickUpper == mp.tickUpper;
}

function property_balancesIncludesVestingLiquidity() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;
    IStrategy.VestingPosition memory vp = _getVestingPosition();
    if (vp.remainingLiquidity == 0) return true;

    (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    (uint256 v0, uint256 v1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    // If vesting position is entirely out-of-range at current price, skip
    if (v0 == 0 && v1 == 0) return true;

    (uint256 idle0, uint256 idle1) = _getIdleBalances();
    IStrategy.Position memory mp = _getMainPosition();
    IStrategy.Position memory sp = _getSecondaryPosition();

    (uint256 m0, uint256 m1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(mp.tickLower),
        TickMath.getSqrtRatioAtTick(mp.tickUpper),
        mp.liquidity
    );
    (uint256 s0, uint256 s1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(sp.tickLower),
        TickMath.getSqrtRatioAtTick(sp.tickUpper),
        sp.liquidity
    );

    // Manually compute what balances() returns (idle + main + secondary, without vesting)
    uint256 computedBal0 = idle0 + m0 + s0;
    uint256 computedBal1 = idle1 + m1 + s1;
    (uint256 reportedBal0, uint256 reportedBal1) = _getStrategyBalances();

    // balances() should include vesting: reportedBal == computedBal + vesting
    // Since it does NOT include vesting, this invariant is violated when v > 0
    return reportedBal0 == computedBal0 + v0 && reportedBal1 == computedBal1 + v1;
}

function property_positionWidthOnlyOwnerCanChange() public returns (bool) {
    uint24 widthBefore = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();

    // Compute a valid alternative width: (width/2) % tickSpacing == 0
    uint24 newWidth = uint24(uint24(ts) * 8);
    if (newWidth == widthBefore) newWidth = uint24(uint24(ts) * 12);

    // Ensure rebalanceInterval has passed so rebalance() inside won't revert on time
    skip(strategy.rebalanceInterval() + 1);

    // Rebalancer (not owner) attempts to change positionWidth via changePositionWidth
    vm.prank(rebalancer);
    try strategy.changePositionWidth(newWidth) {
        // Rebalancer succeeded — positionWidth changed without owner authorization
        // Property: positionWidth must remain unchanged when caller is not owner
        return strategy.positionWidth() == widthBefore;
    } catch {
        return true; // Correctly rejected
    }
}

function property_secondaryPositionValidTickRange() public returns (bool) {
    IStrategy.Position memory sp = _getSecondaryPosition();
    // Uniswap V3 requires tickLower < tickUpper for every position.
    // If secondaryPosition has tickLower >= tickUpper, the next call to
    // _addLiquidityToSecondaryPosition (inside rebalance or compound) will
    // revert at the pool level, bricking the strategy.
    return sp.tickLower < sp.tickUpper;
}

function property_collectFeesDoesNotAdvanceVestingExternally() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;
    IStrategy.VestingPosition memory vpBefore = _getVestingPosition();

    // Skip one block so the lastUpdate guard (lastUpdate == block.timestamp) does
    // not short-circuit _withdrawPartOfVestingPosition
    skip(1);

    // Non-privileged attacker calls collectFees directly
    vm.prank(attacker);
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = _getVestingPosition();

    // Expected invariant: only rebalancer/vault-initiated calls should advance vesting.
    // If the attacker advanced vesting state (reduced remainingLiquidity or moved
    // lastUpdate forward), the property is violated.
    return vpAfter.remainingLiquidity == vpBefore.remainingLiquidity &&
           vpAfter.lastUpdate == vpBefore.lastUpdate;
}

function property_secondaryPositionFullyOutOfRange() public returns (bool) {
    IStrategy.Position memory mp = _getMainPosition();
    IStrategy.Position memory sp = _getSecondaryPosition();
    (, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    // Secondary position must be fully out-of-range at current tick:
    //   entirely above (sp.tickLower >= currentTick, all token0), OR
    //   entirely below (sp.tickUpper <= currentTick, all token1).
    // Additionally, secondary must not share boundary ticks with main position
    // (shared boundary indicates an overlapping range, not a distinct OOR position).
    bool secondaryAbove = sp.tickLower >= currentTick;
    bool secondaryBelow = sp.tickUpper <= currentTick;
    bool fullyOOR = secondaryAbove || secondaryBelow;

    bool sharedUpperBound = (sp.tickUpper == mp.tickUpper);
    bool sharedLowerBound = (sp.tickLower == mp.tickLower);

    return fullyOOR && !sharedUpperBound && !sharedLowerBound;
}

function property_vestingWithdrawalNeverExceedsRemaining() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;
    IStrategy.VestingPosition memory vp = _getVestingPosition();
    if (vp.remainingLiquidity == 0) return true;
    if (vp.lastUpdate == block.timestamp) return true;

    uint256 lastValid = block.timestamp < vp.endTs ? block.timestamp : vp.endTs;

    uint128 liquidityToRemove;
    if (lastValid == vp.endTs) {
        liquidityToRemove = vp.remainingLiquidity;
    } else {
        liquidityToRemove = uint128(
            vp.initialLiquidity * (lastValid - vp.lastUpdate) / (vp.endTs - vp.startTs)
        );
    }

    // The computed withdrawal amount must never exceed remaining liquidity.
    // If it does, the pool's burn call will revert (can't remove more than exists).
    // This property surfaces cases where rounding accumulation leads to overclaim.
    return liquidityToRemove <= vp.remainingLiquidity;
}

