    uint256 delta0 = ONE_WBTC / 10;
    wbtc.mint(user1, amt0);

    ILeverager.LeverageParams memory lp = _buildSimpleWBTCParams(amt0, amt1, delta0, 0);
    vm.startPrank(user1);
    wbtc.approve(address(leverager), type(uint256).max);
    uint256 posId = leverager.openLeveragedPosition(lp);
    vm.stopPrank();

    // Build withdraw with swap amountIn larger than what vault returns
    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.5e18;
    wp.minAmount0 = 0;
    wp.minAmount1 = 0;
    wp.hasToSwap = true;

    IMainnetRouter.ExactInputParams memory sp1;
    // amountIn deliberately much larger than expected amountOut0
    sp1.amountIn = 1000 * ONE_WBTC;
    sp1.amountOutMinimum = 0;
    sp1.deadline = block.timestamp + 1 hours;
    sp1.path = _buildExactInputPath(address(wbtc), address(usdc));
    sp1.recipient = user1;
    wp.swapParams1 = abi.encode(sp1);

    IMainnetRouter.ExactInputParams memory sp2;
    sp2.amountIn = 0;
    sp2.path = _buildExactInputPath(address(usdc), address(wbtc));
    sp2.recipient = user1;
    wp.swapParams2 = abi.encode(sp2);

    wbtc.mint(user1, 10 * ONE_WBTC);
    vm.startPrank(user1);
    wbtc.approve(address(leverager), type(uint256).max);
    (bool ok,) = address(leverager).call(abi.encodeWithSelector(leverager.withdraw.selector, wp));
    // With the bug: reverts with underflow OR drains extra tokens
    // The property: an oversized amountIn should not silently succeed
    // while draining more than the withdrawn share
    t(!ok || wbtc.balanceOf(address(leverager)) == 0, "oversized swap drains leverager balance");
    vm.stopPrank();
}

function property_partial_withdraw_not_blocked_by_stale_minborrow() public {
    // Open a position with initBorrowedUsd just above 20 * minBorrow
    uint256 amt0 = ONE_WBTC;
    uint256 amt1 = 0;
    // borrow enough to have initBorrowedUsd around $200 (10x minBorrow)
    // delta0 = 200e18 / 100_000e18 * 1e8 = 200_000 (0.002 WBTC at $100k)
    uint256 delta0 = 200_000; // 0.002 WBTC
    wbtc.mint(user1, amt0);

    ILeverager.LeverageParams memory lp = _buildSimpleWBTCParams(amt0, amt1, delta0, 0);
    vm.startPrank(user1);
    wbtc.approve(address(leverager), type(uint256).max);
    uint256 posId = leverager.openLeveragedPosition(lp);
    vm.stopPrank();

    // Drop price massively — real debt in USD is now tiny
    _setWBTCPrice(1e18); // $1 per WBTC (from $100k)

    // Try to withdraw 95% — initBorrowedUsd * 0.05 < minBorrow triggers revert
    // even though actual remaining debt at new price >> minBorrow (in token terms)
    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.95e18;
    wp.minAmount0 = 0;
    wp.minAmount1 = 0;
    wp.hasToSwap = false;

    wbtc.mint(user1, 10 * ONE_WBTC);
    vm.startPrank(user1);
    wbtc.approve(address(leverager), type(uint256).max);
    (bool ok,) = address(leverager).call(abi.encodeWithSelector(leverager.withdraw.selector, wp));
    // Property: if actual remaining debt in tokens > minBorrow-equivalent,
    // the withdrawal should succeed regardless of stale initBorrowedUsd
    // With the bug: reverts due to stale USD check
    t(ok, "partial withdraw blocked by stale initBorrowedUsd minBorrow check");
    vm.stopPrank();
}

function property_sweep_only_returns_user_tokens() public {
    // Simulate stuck token0 in leverager (e.g., from prior operation)
    wbtc.mint(address(leverager), ONE_WBTC);

    uint256 attackerBal0Before = wbtc.balanceOf(user2);

    uint256 amt0 = ONE_WBTC / 10;
    uint256 amt1 = 0;
    uint256 delta0 = 20_000; // minimum borrow
    wbtc.mint(user2, amt0);

    ILeverager.LeverageParams memory lp = _buildSimpleWBTCParams(amt0, amt1, delta0, 0);
    vm.startPrank(user2);
    wbtc.approve(address(leverager), type(uint256).max);
    (bool ok,) = address(leverager).call(abi.encodeWithSelector(leverager.openLeveragedPosition.selector, lp));
    vm.stopPrank();

    if (!ok) return;

    uint256 attackerBal0After = wbtc.balanceOf(user2);
    // user2 should not receive more token0 than they put in (amt0)
    // If they received the stuck WBTC, that's theft
    t(
        attackerBal0After <= attackerBal0Before + amt0,
        "sweep sends stuck tokens from prior users to current caller"
    );
}

function property_collectFees_vesting_not_accelerated_by_anyone() public {
    // Record vesting state before
    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return; // nothing to test

    uint128 remainBefore = vpBefore.remainingLiquidity;
    uint256 lastUpdateBefore = vpBefore.lastUpdate;

    // Attacker calls collectFees
    vm.prank(attacker);
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();

    // lastUpdate should only advance by actual time elapsed, not more
    t(vpAfter.lastUpdate <= block.timestamp, "lastUpdate in future");
    // remainingLiquidity should not decrease more than proportional to time
    t(vpAfter.remainingLiquidity <= remainBefore, "remaining liquidity increased?");
}

function property_collectFees_uses_vest_tickUpper_not_main() public {
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If mainPosition.tickUpper != vestPosition.tickUpper after a rebalance,
    // collectFees will use the wrong tick for the vesting position.
    // The property: after calling collectFees, the vesting position's
    // remainingLiquidity should still decrease (fees collected from right range).
    // If it stays the same AND time has passed, bug is triggered.
    uint256 lastUpdateBefore = vp.lastUpdate;
    skip(1 hours);

    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    // If time passed and vesting is ongoing but lastUpdate didn't advance,
    // the wrong tick caused a failure in _withdrawPartOfVestingPosition path
    if (mp.tickUpper != vp.tickUpper) {
        // ticks diverged — collectFees used wrong tick
        t(vpAfter.lastUpdate > lastUpdateBefore, "vesting position not updated: wrong tick used in collectFees");
    }
}

function property_only_authorized_can_trigger_vest_withdrawal() public {
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    skip(1 days);

    // Attacker (not owner, not rebalancer, not vault) calls collectFees
    vm.prank(attacker);
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();

    // If vesting position liquidity decreased due to attacker's call,
    // that's unauthorized vesting withdrawal
    // The property FAILS (bug confirmed) if remainingLiquidity decreased
    t(
        vpAfter.remainingLiquidity == vpBefore.remainingLiquidity,
        "attacker triggered unauthorized vesting withdrawal via public collectFees"
    );
}

function property_position_width_only_changeable_by_owner() public {
    uint24 oldWidth = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();
    uint24 newWidth = uint24(uint24(ts) * 8); // different valid width

    // Only owner should be able to change position width
    // Rebalancer calling changePositionWidth should NOT be allowed
    // (or at minimum it should require onlyOwner authorization)
    t(rebalancer != owner, "test assumes rebalancer != owner");

    skip(10 minutes); // ensure rebalance interval passed
    vm.prank(rebalancer);
    bool succeeded = false;
    try strategy.changePositionWidth(newWidth) {
        succeeded = true;
    } catch {}

    // If rebalancer succeeded in changing width, that's excess privilege
    if (succeeded) {
        t(strategy.positionWidth() == oldWidth,
          "rebalancer changed positionWidth without owner authorization");
    }
}

function property_secondary_position_fully_out_of_range() public {
    IStrategy.Position memory main = strategy.getMainPosition();
    IStrategy.Position memory sec = strategy.getSecondaryPosition();

    // Secondary position should not overlap with main position range
    // i.e., secondary ticks should be completely outside main ticks
    bool secAboveMain = sec.tickLower >= main.tickUpper;
    bool secBelowMain = sec.tickUpper <= main.tickLower;

    t(
        secAboveMain || secBelowMain,
        "secondary position overlaps with main position range"
    );
}

function property_secondary_ticks_not_manipulable_by_spot() public {
    // Record secondary ticks before manipulation
    IStrategy.Position memory secBefore = strategy.getSecondaryPosition();

    // Simulate spot price divergence from TWAP by directly moving pool tick
    // In a real exploit the attacker flash-swaps; here we move tick and observe
    int24 mainLower = strategy.getMainPosition().tickLower;
    int24 mainUpper = strategy.getMainPosition().tickUpper;

    // After rebalance the secondary position must be OOR (either fully below mainLower or fully above mainUpper)
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    bool oobLow  = sec.tickUpper <= mainLower;
    bool oobHigh = sec.tickLower >= mainUpper;
    t(oobLow || oobHigh, "secondary position must be out-of-range after rebalance");

    // The secondary ticks must be consistent with TWAP-derived price, not spot
    uint256 spotP = strategy.price();
    uint256 twapP = strategy.twapPrice();
    // If spot and twap diverge significantly, secondary position direction should follow twap
    if (spotP > twapP * 110 / 100 || spotP < twapP * 90 / 100) {
        // spot is >10% away from twap — secondary position should still be valid OOR
        t(oobLow || oobHigh, "secondary ticks inconsistent under spot manipulation");
    }
}

function property_constructor_positions_match_twap() public {
    // After initial setup (which calls rebalance after 10 min skip),
    // the main position should be centered near the TWAP tick
    int24 twapT = strategy.twapTick();
    IStrategy.Position memory main = strategy.getMainPosition();
    int24 center = (main.tickLower + main.tickUpper) / 2;
    int24 diff = center - twapT;
    if (diff < 0) diff = -diff;
    // center should be within 2*tickSpacing of TWAP tick
    t(diff <= 2 * int24(strategy.tickSpacing()), "main position center far from TWAP tick");
}

function property_twap_window_sufficient() public {
    // TWAP window must be at least 15 minutes to be manipulation-resistant
    t(strategy.twap() >= 900, "TWAP window too short for manipulation resistance");
}

function property_vesting_fees_collected_from_correct_ticks() public {
    // After collecting fees, if there's an ongoing vesting position,
    // the tickUpper used for collection must equal vestPosition.tickUpper
    // We can't directly observe this; instead test that collecting fees
    // for a vesting position at different ticks from mainPosition doesn't silently succeed
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory main = strategy.getMainPosition();

    // If vesting position ticks differ from main position ticks,
    // the bug causes collection from wrong ticks
    // The vesting tickUpper should equal the main tickUpper at time of creation
    // but mainPosition may have been rebalanced since
    // Either way, the code uses mainPosition.tickUpper NOT vestPosition.tickUpper
    t(
        vp.tickUpper == main.tickUpper,
        "vesting tickUpper differs from main tickUpper: fees collected from wrong position"
    );
}

function property_vesting_full_liquidity_removed_by_endTs() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // If we are past endTs, remainingLiquidity should be 0
    if (block.timestamp >= vp.endTs) {
        eq(vp.remainingLiquidity, 0, "vesting position should be fully withdrawn by endTs");
    }
}

function property_rebalance_tick_consistent_with_twap() public {
    // After rebalance, the main position center tick should be near TWAP tick
    int24 twapT = strategy.twapTick();
    IStrategy.Position memory main = strategy.getMainPosition();
    int24 center = (main.tickLower + main.tickUpper) / 2;
    int24 diff = center - twapT;
    if (diff < 0) diff = -diff;
    // center must be within tickTwapDeviation of TWAP tick
    t(diff <= int24(strategy.tickTwapDeviation()) + int24(strategy.tickSpacing()),
      "main position center tick diverges from TWAP after rebalance");
}

function property_secondary_ticks_always_valid_range() public {
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    t(sec.tickLower < sec.tickUpper, "secondary position has invalid tick range (lower >= upper)");
    // Also verify secondary position is OOR
    IStrategy.Position memory main = strategy.getMainPosition();
    bool oobLow  = sec.tickUpper <= main.tickLower;
    bool oobHigh = sec.tickLower >= main.tickUpper;
    t(oobLow || oobHigh || (sec.tickLower == 0 && sec.tickUpper == 0),
      "secondary position is not out-of-range");
}

function property_collectFees_uses_correct_vesting_ticks() public {
    // Set up: after a rebalance the mainPosition ticks change,
    // vesting position keeps its original ticks.
    // Verify that collectFees does NOT silently operate on wrong range
    // by checking that the idle balances increase after collect when
    // the vesting position has accrued fees.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If ticks diverged (post-rebalance), collectFees should still work
    // correctly on the vesting position's actual ticks.
    // The bug: collectFees uses mp.tickUpper instead of vp.tickUpper
    t(
        vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
        "vesting ticks diverged from main: collectFees will use wrong tickUpper"
    );
}

function property_balances_includes_vesting_position() public {
    if (!strategy.ongoingVestingPosition()) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // If there's an ongoing vesting position with remaining liquidity,
    // total balances must exceed idle + main + secondary alone.
    // We assert balances are > 0 as a proxy; the real invariant is that
    // the vesting position value is included.
    t(vp.remainingLiquidity == 0 || (bal0 > idle0 || bal1 > idle1),
      "balances underreports when vesting position has remaining liquidity");
}

function property_secondary_ticks_valid() public {
