function property_vesting_fees_collected_from_correct_ticks() public {
    // Setup: add a vesting position, then rebalance to shift main ticks
    deal(address(wbtc), owner, 1 * ONE_TOKEN0);
    deal(address(usdc), owner, 60_000 * ONE_TOKEN1);
    vm.startPrank(owner);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    vault.addVestingPosition(1 * ONE_TOKEN0, 60_000 * ONE_TOKEN1, 7 days);
    vm.stopPrank();

    // Record vesting position ticks
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    int24 vestLower = vp.tickLower;
    int24 vestUpper = vp.tickUpper;

    // Force pool tick shift and rebalance to change main position ticks
    pool.setTick(pool.tick() + 120);
    skip(10 minutes);
    vm.prank(rebalancer);
    strategy.rebalance();

    // After rebalance, main upper tick may differ from vest upper tick
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: if mainPosition.tickUpper != vestPosition.tickUpper,
    // collectFees will use the wrong upper tick for the vesting position.
    // We assert that they are the same only when the vesting position
    // was created with those exact main ticks — i.e., no shift occurred.
    // If they diverged, the property detects potential miscollection.
    t(
        mp.tickUpper == vestUpper || !strategy.ongoingVestingPosition(),
        "WC-01: vesting upper tick diverged from main after rebalance, collectFees uses wrong ticks"
    );
}

function property_position_width_has_max_bound() public {
    // positionWidth should have a maximum sensible bound
    // The contract allows any value divisible by tickSpacing*2
    // A very wide position means the secondary position range could be invalid
    uint24 w = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();
    // positionWidth should not exceed e.g. 100 * tickSpacing (reasonable max)
    lte(uint256(w), uint256(uint24(ts) * 100), "WC-02: positionWidth has no upper cap, rebalancer can set arbitrarily large width");
}

function property_secondary_ticks_always_valid() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    t(
        sp.tickLower < sp.tickUpper,
        "WC-04: secondary position has tickLower >= tickUpper (invalid range)"
    );
}

function property_secondary_position_direction_uses_twap() public {
    // The secondary position direction should be deterministic from TWAP
    // not spot price. We check that after rebalance, the secondary position
    // is placed correctly relative to current tick.
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    (, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    // Secondary position should be entirely out-of-range:
    // either fully above current tick (token0 only) or fully below (token1 only)
    bool fullyAbove = sp.tickLower > currentTick;
    bool fullyBelow = sp.tickUpper <= currentTick;
    t(
        fullyAbove || fullyBelow,
        "WC-05: secondary position is not fully out-of-range after rebalance"
    );
}

function property_LH001_vesting_fees_collected_from_correct_range() public {
    // Setup: ensure an ongoing vesting position exists then trigger a rebalance
    // to diverge mainPosition.tickUpper from vestPosition.tickUpper
    if (!strategy.ongoingVestingPosition()) return;

    // Read the stored ticks
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper for the vesting position
    // After a rebalance they can differ. Property: when ongoing vesting position exists,
    // collectFees should reference vestPosition.tickUpper, not mainPosition.tickUpper.
    // We assert they must be equal for the current code to be correct — if they diverge,
    // the code is wrong.
    // (This property catches the state where the bug would manifest.)
    if (strategy.ongoingVestingPosition()) {
        t(
            vp.tickUpper == mp.tickUpper,
            "LH-001: vestPosition.tickUpper diverged from mainPosition.tickUpper; collectFees uses wrong tick"
        );
    }
}

function property_LH002_secondary_position_is_OOR() public {
    IStrategy.Position memory mp = strategy.getMainPosition();
    IStrategy.Position memory sp = strategy.getSecondaryPosition();

    if (sp.liquidity == 0) return;

    // Secondary position should be OOR: its range should NOT overlap with main position
    // OOR-below: sp.tickUpper <= mp.tickLower (entirely below main)
    // OOR-above: sp.tickLower >= mp.tickUpper (entirely above main)
    bool oorBelow = sp.tickUpper <= mp.tickLower;
    bool oorAbove = sp.tickLower >= mp.tickUpper;

    t(
        oorBelow || oorAbove,
        "LH-002: secondary position overlaps with main position; not truly OOR"
    );
}

function property_LH004_vesting_position_fully_withdrawn_after_end() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (block.timestamp < vp.endTs) return;

    // After endTs, calling collectFees should set ongoingVestingPosition = false
    strategy.collectFees();

    t(
        !strategy.ongoingVestingPosition(),
        "LH-004: vesting position should be fully withdrawn after endTs"
    );

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(
        uint256(vpAfter.remainingLiquidity),
        0,
        "LH-004: remainingLiquidity should be 0 after full vesting"
    );
}

function property_LH005_balances_includes_all_positions() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();

    // Compute what vesting position contributes
    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
    uint160 sqrtA = TickMath.getSqrtRatioAtTick(vp.tickLower);
    uint160 sqrtB = TickMath.getSqrtRatioAtTick(vp.tickUpper);
    (uint256 v0, uint256 v1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96, sqrtA, sqrtB, vp.remainingLiquidity
    );

    // If vesting position has non-zero liquidity, balances() should report more
    // than what it would without vesting position
    t(
        v0 == 0 && v1 == 0,
        "LH-005: balances() omits vesting position value; share price understated"
    );
}

function property_LH006_secondary_does_not_share_bound_with_main() public {
    IStrategy.Position memory mp = strategy.getMainPosition();
    IStrategy.Position memory sp = strategy.getSecondaryPosition();

    if (sp.liquidity == 0) return;

    // Secondary should not share tickUpper with main (OOR-above case)
    // and should not share tickLower with main (OOR-below case)
    bool sharesUpper = sp.tickUpper == mp.tickUpper;
    bool sharesLower = sp.tickLower == mp.tickLower;

    t(
        !sharesUpper && !sharesLower,
        "LH-006: secondary position shares a tick boundary with main position"
    );
}

function property_LH007_withdrawPartial_accounts_for_vesting() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    if (vpBefore.remainingLiquidity == 0) return;

    uint256 userSharesBefore = vault.balanceOf(user);
    if (userSharesBefore == 0) return;

    uint256 totalSupplyBefore = vault.totalSupply();

    // Full balances including vesting position (what user SHOULD get)
    (uint256 stratBal0, uint256 stratBal1) = strategy.balances();
    (uint160 sqrtP,,,,,,) = pool.slot0();
    uint160 sqrtA = TickMath.getSqrtRatioAtTick(vpBefore.tickLower);
    uint160 sqrtB = TickMath.getSqrtRatioAtTick(vpBefore.tickUpper);
    (uint256 vp0, uint256 vp1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtP, sqrtA, sqrtB, vpBefore.remainingLiquidity
    );
    uint256 trueBal0 = stratBal0 + vp0;
    uint256 trueBal1 = stratBal1 + vp1;

    uint256 expectedOut0 = trueBal0 * userSharesBefore / totalSupplyBefore;
    uint256 expectedOut1 = trueBal1 * userSharesBefore / totalSupplyBefore;

    vm.prank(user);
    (uint256 actualOut0, uint256 actualOut1) = vault.withdraw(userSharesBefore, 0, 0);

    // User should have received at least their true proportional share
    // (allowing 1 wei rounding tolerance)
    gte(actualOut0 + 1, expectedOut0, "LH-007: user received less token0 than true proportional share");
    gte(actualOut1 + 1, expectedOut1, "LH-007: user received less token1 than true proportional share");
}

function property_checkPoolActivity_bounded_iterations() public {
    // After a fresh setup where cardinality is still small (default=1),
    // the call should succeed. This property verifies the current cardinality
    // is within a safe bound for gas; if observationCardinality grows, it fails.
    (, , uint16 currentIndex, uint16 observationCardinality,,,) = pool.slot0();
    // At default cardinality=1, checkPoolActivity should complete without OOG.
    // We bound: if cardinality > 500 the iteration count is dangerous.
    // The property documents the gas-unbounded nature of the loop.
    t(observationCardinality <= 500, "observationCardinality too large: checkPoolActivity will OOG");
}

function property_rebalance_not_permanently_blocked() public {
    // After initial setup, the rebalancer should always be able to rebalance
    // once the interval has passed, without hitting an unexpected revert
    // from timestamp==0 slots in the observation ring buffer.
    _skipTime(rebalanceInterval + 1);
    // This should not revert; if it does, rebalance is DoS'd
    try strategy.rebalance() {
        // success: no DoS
    } catch Error(string memory reason) {
        // "timestamp 0" revert means checkPoolActivity hit uninitialized observation
        t(
            keccak256(bytes(reason)) != keccak256(bytes("timestamp 0")),
            "checkPoolActivity reverted on timestamp 0: rebalance permanently blocked"
        );
    }
}

function property_collectFees_uses_correct_vesting_ticks() public {
    // Setup a vesting position
    _addVestingPosition(1 * ONE_TOKEN0, 60_000 * ONE_TOKEN1, 7 days);

    // Record vest position ticks BEFORE rebalance
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    int24 vestTickLower = vp.tickLower;
    int24 vestTickUpper = vp.tickUpper;

    // Trigger a rebalance to shift mainPosition ticks
    _skipTime(rebalanceInterval + 1);
    _setPoolTick(strategy.getMainPosition().tickLower - 120); // shift tick out
    _rebalance();

    // Main position ticks have shifted
    int24 newMainTickUpper = strategy.getMainPosition().tickUpper;

    // The vesting position ticks must be unchanged
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();

    // The bug: collectFees uses mainPosition.tickUpper for vesting position
    // This property documents the incorrect tick used in collectFees
    t(
        vpAfter.tickUpper == vestTickUpper,
        "vestPosition.tickUpper should not change after rebalance"
    );
    // If mainPosition.tickUpper != vestPosition.tickUpper, collectFees is using wrong ticks
    t(
        newMainTickUpper == vestTickUpper || !strategy.ongoingVestingPosition(),
        "collectFees will use wrong ticks for vesting position fee collection"
    );
}

