function property_rebalance_callable_after_interval() public {
    // After the rebalance interval passes, rebalance should succeed
    // provided the pool mock has sufficient observation history.
    // This property checks that the price-range check does not cause
    // a permanent DoS when the pool has limited observation history.
    _skipTime(strategy.rebalanceInterval() + 1);
    bool succeeded = false;
    try strategy.rebalance() {
        succeeded = true;
    } catch Error(string memory reason) {
        // "price out of range" with insufficient observation history = DoS
        t(
            keccak256(bytes(reason)) != keccak256(bytes("price out of range")),
            "rebalance permanently blocked by price-range check: insufficient pool observation history"
        );
    }
    t(succeeded, "rebalance should succeed after interval");
}

