function property_collectFees_vesting_uses_correct_ticks() public {
    // Ensure vesting position exists
    _addVestingPosition(1 * ONE_TOKEN0, 60_000 * ONE_TOKEN1, 7 days);

    // Rebalance to change main position ticks away from vesting position ticks
    _skipTime(strategy.rebalanceInterval() + 1);
    _rebalance();

    // After rebalance, mainPosition.tickUpper may differ from vestPosition.tickUpper
    IStrategy.Position memory mainPos = strategy.getMainPosition();
    IStrategy.VestingPosition memory vestPos = strategy.getVestingPosition();

    // The bug: collectFees uses mainPosition.tickUpper for the vesting position
    // If they differ, fees are collected from the wrong position
    // Property: vestPos.tickUpper should equal what collectFees uses
    t(
        mainPos.tickUpper == vestPos.tickUpper,
        "MATH-01: after rebalance, main tickUpper != vest tickUpper; collectFees collects wrong position"
    );
}

function property_secondary_position_is_out_of_range() public {
    // After rebalance, secondary position must be out-of-range
    // (i.e., current tick is outside [tickLower, tickUpper))
    _skipTime(strategy.rebalanceInterval() + 1);
    _rebalance();

    IStrategy.Position memory secPos = strategy.getSecondaryPosition();
    (, int24 currentTick,,,,,) = pool.slot0();

    // Secondary should be OOR: either entirely above or entirely below current tick
    bool aboveRange = currentTick >= secPos.tickUpper;
    bool belowRange = currentTick < secPos.tickLower;
    t(
        aboveRange || belowRange,
        "MATH-02: secondary position is in-range, should always be out-of-range"
    );
}

function property_deposit_shares_precision() public {
    // After initial deposit state (set up in setup()), depositor deposits proportionally
    (uint256 bal0, uint256 bal1) = strategy.balances();
    if (bal0 == 0 || bal1 == 0) return;

    // Deposit exact ratio to minimize slippage
    uint256 dep0 = bal0 / 100;
    uint256 dep1 = bal1 / 100;
    if (dep0 == 0 || dep1 == 0) return;

    uint256 supplyBefore = vault.totalSupply();
    uint256 sharesBefore = vault.balanceOf(depositor);

    (uint256 shares,,) = _depositAs(depositor, dep0, dep1);

    // Shares received should be >= 1% of total supply (proportional deposit)
    // The expected shares = totalSupply * dep0 / bal0 (approximately)
    uint256 expectedShares = supplyBefore * dep0 / bal0;

    // Allow 1 wei tolerance; shares should not be less than expected - 1
    gte(shares + 1, expectedShares, "MATH-03: shares received less than proportional share");
}

function property_oracle_price_not_stale() public {
    // This property checks that the pricefeed returns a fresh price.
    // With the staleness check commented out, we can simulate a stale oracle
    // and verify the leverager still accepts it — demonstrating the vulnerability.

    // Advance time by 8 days (beyond any reasonable heartbeat of 604800s = 7 days)
    vm.warp(block.timestamp + 8 days);

    // Price should now be stale, but PriceFeed.getPrice() will still return it.
    // Property: after staleness, getPrice should revert or return 0 — but it doesn't.
    uint256 price = priceFeed.getPrice(address(wbtc));

    // The vulnerability: price is returned without staleness check.
    // A correct implementation would revert here. We assert it should revert
    // by checking that the returned price is 0 (indicating feed correctly rejected stale data).
    // Since the check is commented out, this assertion FAILS — demonstrating the bug.
    t(price == 0, "stale oracle price accepted: staleness check is commented out");
}

