    ILeverager.LeverageParams memory lp = _buildSimpleWBTCParams(
        amt, 0, amt / 2, 0
    );
    vm.prank(user2);
    uint256 posId = leverager.openLeveragedPosition(lp);

    uint256 user2WbtcAfter = wbtc.balanceOf(user2);
    // user2 should NOT receive user1's stuck tokens
    // If sweep sends all balances, user2 receives the stuck amt
    t(user2WbtcAfter <= user2WbtcBefore, "user2 should not receive stuck tokens from other users");
}

function property_vesting_fees_collected_from_correct_ticks() public {
    // Only meaningful when there is an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If main ticks have changed since vesting position was created,
    // tickUpper mismatch causes incorrect fee collection.
    // The invariant: the vesting position's ticks must match what collectFees uses.
    // collectFees calls collectPositionFees(vestPosition.tickLower, mainPosition.tickUpper)
    // so if they diverged, the property is violated.
    t(
        vp.tickUpper == mp.tickUpper,
        "vesting tickUpper != mainPosition tickUpper: collectFees uses wrong range"
    );
}

function property_vesting_full_distribution_over_duration() public {
