    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (block.timestamp < vp.endTs) return;

    // After end of vesting, remaining liquidity should be 0
    // (either released by final call or the last incremental call)
    eq(
        uint256(vp.remainingLiquidity),
        0,
        "vesting position has remaining liquidity after endTs"
    );
}

function property_no_protocol_fee_on_vesting_position_fees() public {
    if (!strategy.ongoingVestingPosition()) return;

    uint256 feeRecipientBal0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1Before = usdc.balanceOf(feeRecipient);

    // If only vesting position fees exist (main + secondary have 0 liquidity)
    // then collectFees should transfer 0 to feeRecipient
    // This is hard to isolate, so we test the weaker property:
    // protocol fee should only be taken on non-vesting fees
    // As a proxy: after collectFees, feeRecipient should not gain
    // more than protocolFee% of (main + secondary) fees
    strategy.collectFees();

    // Property: this is difficult to express without isolating sources;
    // we instead verify that ongoingVestingPosition fees collection
    // did not inflate protocol fee beyond what main+secondary positions earned
    uint256 feeRecipientGain0 = wbtc.balanceOf(feeRecipient) - feeRecipientBal0Before;
    uint256 feeRecipientGain1 = usdc.balanceOf(feeRecipient) - feeRecipientBal1Before;

    // feeRecipient gain must be <= MAX_PROTOCOL_FEE / BPS * (main+secondary fees)
    // Since we can't easily separate fees, we verify fee is not 100% of collected
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();
    t(feeRecipientGain0 <= idle0After || idle0After == 0, "protocol fee exceeds collected token0");
    t(feeRecipientGain1 <= idle1After || idle1After == 0, "protocol fee exceeds collected token1");
}

function property_balances_includes_vesting_position() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    // Get the vesting position value
    (uint256 vest0, uint256 vest1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    (uint256 bal0, uint256 bal1) = strategy.balances();

    // If vesting position has value, balances() should include it
    // (otherwise shares are mispriced)
    if (vest0 > 0) {
        t(bal0 > vest0, "balances() token0 does not include vesting position");
    }
    if (vest1 > 0) {
        t(bal1 > vest1, "balances() token1 does not include vesting position");
    }
}

function property_secondary_position_valid_ticks() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // Secondary position must have tickLower < tickUpper
    t(sp.tickLower < sp.tickUpper, "secondary position: tickLower >= tickUpper");

    // Secondary position must not overlap with main position completely
    // (it should be out-of-range for one side)
    // tickLower >= mainPosition.tickLower && tickUpper <= mainPosition.tickUpper would mean
    // secondary is subset of main, not out-of-range
    bool isSubset = (sp.tickLower >= mp.tickLower && sp.tickUpper <= mp.tickUpper);
    t(!isSubset, "secondary position is subset of main position (not out-of-range)");
}

