function property_collectfees_uses_vest_tick_upper() public {
    // Set up: add a vesting position (uses main ticks at that moment)
    deal(address(wbtc), owner, ONE_TOKEN0);
    deal(address(usdc), owner, 100_000 * ONE_TOKEN1);
    vm.startPrank(owner);
    wbtc.approve(address(vault), type(uint256).max);
    usdc.approve(address(vault), type(uint256).max);
    vault.addVestingPosition(ONE_TOKEN0, 100_000 * ONE_TOKEN1, 30 days);
    vm.stopPrank();

    // Capture vesting position ticks
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    int24 vestTickUpper = vp.tickUpper;

    // Trigger rebalance to shift main position ticks
    _skipTime(10 minutes);
    _setPoolTick(strategy.getMainPosition().tickUpper + 120);
    _skipTime(10 minutes);
    _rebalance();

    // Main position tick upper should now differ from vest tick upper
    int24 newMainTickUpper = strategy.getMainPosition().tickUpper;

    // The property: if vesting is ongoing and main ticks moved,
    // collectFees must not silently operate on the wrong range.
    // We assert they are equal — if this fails, the bug is present:
    // collectFees will use the wrong tickUpper for the vest position.
    if (strategy.ongoingVestingPosition()) {
        t(vestTickUpper == newMainTickUpper, "vest tickUpper diverged from main tickUpper: collectFees uses wrong range");
    }
}

