function property_secondary_no_overlap_with_main() public {
    IStrategy.Position memory mp = strategy.getMainPosition();
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return;
    // Secondary should NOT overlap with main position
    bool overlaps = sp.tickLower < mp.tickUpper && sp.tickUpper > mp.tickLower;
    // Some overlap at boundaries is expected by design (secondary.tickLower == main.tickLower or secondary.tickUpper == main.tickUpper)
    // But full containment is wrong
    if (overlaps) {
        bool fullyContained = sp.tickLower >= mp.tickLower && sp.tickUpper <= mp.tickUpper;
        t(!fullyContained, "LIB-01: secondary position fully contained within main - wrong placement");
    }
}

