    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 wa0 = bal0 * shares / ts;
    uint256 wa1 = bal1 * shares / ts;
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();
