function property_liquidation_always_repays_full_debt() public {
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (!leverager.isLiquidateable(posId)) return;
    if (pos.denomination == address(0)) return;

    uint256 lpBalBefore = IERC20(pos.denomination).balanceOf(address(lendingPool));
    uint256 currBIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * currBIndex / pos.borrowedIndex;

    ILeverager.LiquidateParams memory lp;
    lp.id = posId;
    lp.minAmount0 = 0;
    lp.minAmount1 = 0;
    lp.hasToSwap = false;

    deal(pos.denomination, liquidator, owedAmount * 2);
    vm.startPrank(liquidator);
    IERC20(pos.denomination).approve(address(leverager), type(uint256).max);
    leverager.liquidatePosition(lp);
    vm.stopPrank();

    // LendingPool should have received at least the full owed amount
    uint256 lpBalAfter = IERC20(pos.denomination).balanceOf(address(lendingPool));
    gte(lpBalAfter, lpBalBefore + owedAmount, "lending pool should receive full repayment");
}

