function property_withdraw_token1_denom_no_underflow() public {
    // Simulates the withdraw path for token1 denomination
    // When amountOut0 > amountOut1 and amountOut1 < owedAmount, underflow occurs
    uint256 amountOut0 = 1e8; // 1 WBTC in token units
    uint256 amountOut1 = 100e6; // 100 USDC
    uint256 owedAmount = 200e6; // 200 USDC owed

    // Replicate the buggy logic: borrowed == token1
    bool condition = amountOut1 < owedAmount; // true: 100 < 200
    uint256 repayFromWithdraw = condition ? amountOut0 : owedAmount; // BUG: uses amountOut0

    // This will underflow if amountOut0 > amountOut1
    bool wouldUnderflow = repayFromWithdraw > amountOut1;
    t(!wouldUnderflow, "DOS-02: withdraw underflows when token1 is denomination and amountOut0 > amountOut1");
}

function property_liquidation_fee_math_correct() public {
    // Verify borrowedValue uses 10**decimals not raw decimals
    // Check that for WETH denomination, borrowedValue is in same scale as totalValueUSD
    // We check the ratio: borrowedValue should be ~owedAmount * price / 1e18 (for 18 dec token)
    // not ~owedAmount * price / 18
    uint256 owedAmount = 1e18; // 1 WETH
    uint256 bPrice = PRICE_WETH; // 2500e18
    uint8 dec = ERC20(WETH_ADDR).decimals(); // 18

    uint256 buggyBorrowedValue = owedAmount * bPrice / dec; // divides by 18, not 1e18
    uint256 correctBorrowedValue = owedAmount * bPrice / (10 ** uint256(dec));

    // If buggy value is used, it is ~5.5e16x larger than correct value
    // Any realistic totalValueUSD < buggyBorrowedValue → fee never taken
    t(buggyBorrowedValue == correctBorrowedValue, "DOS-03: borrowedValue uses raw decimals instead of 10**decimals");
}

function property_partial_withdraw_not_locked_by_minborrow_raise() public {
    // A position opened with initBorrowedUsd just above the OLD minBorrow
    // should remain partially withdrawable if owner doesn't raise minBorrow
    // We check that a 99% partial withdrawal always succeeds (modulo oracle/slippage)
    // when the position's remaining value > minBorrow at open time
    uint256 initialMinBorrow = leverager.minBorrow();
    uint256 positionBorrowedUSD = initialMinBorrow + 1e18; // just above threshold
    uint256 pctWithdraw = 0.5e18; // 50%

    uint256 remaining = positionBorrowedUSD * (1e18 - pctWithdraw) / 1e18;
    // remaining = 50% of (minBorrow + $1) — should be > minBorrow/2 but not > minBorrow
    // If minBorrow was raised after open, this would fail
    t(remaining > 0, "DOS-04: partial withdraw remaining is zero after pct calc");
}

function property_liquidation_not_gated_on_collectfees() public {
