function property_getTokenIn_terminates_multihop() public {
    // Build a 2-hop path: WETH -> 3000 -> USDC -> 500 -> WBTC
    // encoded as: tokenIn(20) fee(3) tokenMid(20) fee(3) tokenOut(20) = 66 bytes
    bytes memory twoHopPath = abi.encodePacked(
        WETH_ADDR, uint24(3000), USDC_ADDR, uint24(500), WBTC_ADDR
    );
    // If _getTokenIn is broken (infinite loop), this call will OOG.
    // We gate this as a view call to detect the hang.
    // A correct implementation returns WETH_ADDR.
    // We wrap in a low-level call with limited gas to catch OOG.
    (bool ok, bytes memory ret) = address(leverager).staticcall{gas: 100_000}(
        abi.encodeWithSignature("_getTokenInTest(bytes)", twoHopPath)
    );
    // If the call OOGs, ok == false — that is the bug.
    // This property will only pass when the library returns correctly.
    t(ok, "LIB-01: _getTokenIn OOGs on multi-hop path — skipToken return ignored");
}

function property_withdraw_token1_denom_accounting() public {
    // Pre-condition: open a position denominated in token1 (USDC is not directly
    // supported as denom in this setup; skip if no position exists)
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.denomination != address(usdc)) return; // only test token1 denom case

    uint256 sharesBefore = pos.shares;
    uint256 borrowedBefore = pos.borrowedAmount;

    // Record lender pool balance before
    uint256 poolBefore = usdc.balanceOf(address(lendingPool));

    // Attempt 50% withdraw — should not revert with wrong-variable underflow
    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.5e18;
    wp.minAmount0 = 0;
    wp.minAmount1 = 0;
    wp.hasToSwap = false;

    vm.prank(positionOwner[posId]);
    try leverager.withdraw(wp) {
        ILeverager.Position memory posAfter = leverager.getPosition(posId);
        // Shares should have decreased by ~50%
        gte(sharesBefore, posAfter.shares, "LIB-02: shares should decrease after partial withdraw");
    } catch {
        // Revert due to wrong variable is the bug
        t(false, "LIB-02: withdraw reverted due to amountOut0 used instead of amountOut1 in token1 branch");
    }
