function property_liquidation_fee_collected_when_solvent() public {
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    if (!leverager.isLiquidateable(posId)) return;

    ILeverager.Position memory pos = leverager.getPosition(posId);

    // feeRecipient is address(0xA0003) from Setup
    uint256 feeRecipientBal0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1Before = usdc.balanceOf(feeRecipient);

    ILeverager.LiquidateParams memory lp;
    lp.id = posId;
    lp.minAmount0 = 0;
    lp.minAmount1 = 0;
    lp.hasToSwap = false;

    // liquidator pulls needed denomination from pool
    deal(address(usdc), liquidator, 1_000_000e6);
    vm.startPrank(liquidator);
    usdc.approve(address(leverager), type(uint256).max);
    leverager.liquidatePosition(lp);
    vm.stopPrank();

    // If position had surplus, fee should have been collected.
    // With the bug, borrowedValue is inflated so the surplus check fails
    // and feeRecipient gets nothing even when there IS a profit.
    uint256 feeRecipientBal0After = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1After = usdc.balanceOf(feeRecipient);

    // This property checks that at least one of the balances increased
    // (i.e. fee was collected), which fails due to the decimals bug.
    bool feeCollected = feeRecipientBal0After > feeRecipientBal0Before
        || feeRecipientBal1After > feeRecipientBal1Before;
    t(feeCollected, "LIB-03: liquidation fee not collected — decimals() used instead of 10**decimals()");
}

function property_withdraw_swap_amountIn_bounded() public {
    if (openPositionIds.length == 0) return;
