    uint256 totalPositionDebt = 0;
    for (uint256 i = 0; i < openPositionIds.length; i++) {
        ILeverager.Position memory pos = leverager.getPosition(openPositionIds[i]);
        if (pos.borrowedAmount > 0) {
            uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
            totalPositionDebt += pos.borrowedAmount * bIndex / pos.borrowedIndex;
        }
    }
    uint256 poolBorrows = lendingPool.totalBorrowsOfReserve(address(weth));
    // totalPositionDebt should be <= poolBorrows (pool may have other rounding)
    lte(
        totalPositionDebt,
        poolBorrows + 1e15,
        "sum of position debts exceeds pool total borrows"
    );
}

function invariant_withdraw_token1_denom_no_underflow() internal returns (bool) {
    if (openPositionIds.length == 0) return true;

    for (uint256 i = 0; i < openPositionIds.length; i++) {
        uint256 posId = openPositionIds[i];
        ILeverager.Position memory pos = leverager.getPosition(posId);
        if (pos.denomination != USDC_ADDR) continue;  // only USDC-denomination positions
        if (pos.shares == 0) continue;

        // Simulate 50% withdraw amounts from vault
        uint256 vaultSupply = vault.totalSupply();
        if (vaultSupply == 0) continue;
        (uint256 vaultBal0, uint256 vaultBal1) = vault.balances();
        uint256 halfShares = pos.shares / 2;
        uint256 simOut0 = halfShares * vaultBal0 / vaultSupply; // WBTC raw units
        uint256 simOut1 = halfShares * vaultBal1 / vaultSupply; // USDC raw units

        // Compute owed amount for this half
        uint256 bIndex = lendingPool.getCurrentBorrowingIndex(USDC_ADDR);
        uint256 halfOwed = (pos.borrowedAmount * bIndex / pos.borrowedIndex) / 2;

        // Trigger condition: amountOut1 < owedAmount → repayFromWithdraw = amountOut0
        if (simOut1 < halfOwed && simOut0 > simOut1) {
            // BUG: amountOut1 -= amountOut0 where amountOut0 > amountOut1 → underflow
            // This invariant catches the state where the bug would fire
            return t(
                simOut0 <= simOut1,
                "DDH-L-01: withdraw() amountOut0 > amountOut1 when token1=denom — underflow revert on withdrawal"
            );
        }
    }
    return true;
}

function invariant_liquidation_decimal_formula_correct() internal returns (bool) {
    // Verify that decimals() vs 10**decimals() distinction is correctly applied.
    // The Leverager uses `/ ERC20(denomination).decimals()` at line 318.
    // For USDC: decimals() = 6, but 10**decimals() = 1_000_000
    // The invariant fires if these are different (they always are for real tokens).
    address[3] memory tokens = [WBTC_ADDR, USDC_ADDR, WETH_ADDR];
    for (uint256 i = 0; i < 3; i++) {
        uint256 decimals = uint256(ERC20(tokens[i]).decimals());
        uint256 correctDivisor = 10 ** decimals;
        // If decimals > 1, buggy divisor (decimals) != correct divisor (10**decimals)
        if (decimals > 1) {
            return t(
                correctDivisor == decimals,
                "DDH-L-02: ERC20.decimals() != 10**decimals() — liquidatePosition borrowedValue formula wrong"
            );
        }
    }
    return true;
}

function invariant_fee_recipient_not_zero_when_fee_nonzero() internal returns (bool) {
    // We cannot read feeRecipient directly (no getter for a plain address state var)
