function property_liquidation_fee_accounting_correct() public {
    // Reproduce the exact calculation from liquidatePosition line 318
    // and compare with the correct formula used in isLiquidateable line 401.
    // For any denomination token, the two formulas should produce the same scaling.

    // Use WETH as denomination (18 decimals) as the most extreme case
    address denom = WETH_ADDR;
    uint256 owedAmount = 1e18; // 1 WETH
    uint256 bPrice = PRICE_WETH; // 2500e18

    // WRONG formula (as in liquidatePosition line 318):
    uint256 borrowedValueWrong = owedAmount * bPrice / ERC20(denom).decimals();

    // CORRECT formula (consistent with isLiquidateable line 401):
    uint256 borrowedValueCorrect = owedAmount * bPrice / (10 ** ERC20(denom).decimals());

    // The wrong formula inflates borrowedValue by decimals() / 1 relative to correct.
    // For WETH: wrong = correct * 1e18 / 18 — a ~5.5e16x inflation.
    // Property: correct borrowedValue should equal wrong divided by (10^decimals / decimals).
    // We assert they are NOT equal to document the bug:
    t(
        borrowedValueWrong != borrowedValueCorrect,
        "MATH-01: wrong formula matches correct — decimals bug fixed or token has 1 decimal"
    );

    // The wrong value should be much larger than the correct value (for any normal token).
    // 10 ** decimals() / decimals() > 1 for all standard tokens (6, 8, 18 dec).
    t(
        borrowedValueWrong > borrowedValueCorrect,
        "MATH-01: wrong borrowedValue should be > correct for standard tokens"
    );
}

function property_withdraw_repayFromWithdraw_uses_correct_token() public {
    // Verify: when borrowed==token1, repayFromWithdraw must be min(amountOut1, owedAmount)
    // NOT min(amountOut0, owedAmount).
    // We simulate the arithmetic to detect the mismatch.

    // Hypothetical scenario: borrowed=token1, amountOut1 < owedAmount
    uint256 amountOut0_sim = 5e8;   // 5 WBTC
    uint256 amountOut1_sim = 100e6; // 100 USDC (token1)
    uint256 owedAmount_sim = 500e6; // 500 USDC (owed)

    // WRONG (as coded line 232):
    uint256 repayWrong = amountOut1_sim < owedAmount_sim ? amountOut0_sim : owedAmount_sim;
    uint256 owedAfterWrong = owedAmount_sim - repayWrong;
    // amountOut1_sim unchanged (not decremented) = 100e6 sent to user

    // CORRECT:
    uint256 repayCorrect = amountOut1_sim < owedAmount_sim ? amountOut1_sim : owedAmount_sim;
    uint256 owedAfterCorrect = owedAmount_sim - repayCorrect;
    uint256 amountOut1After = amountOut1_sim - repayCorrect;

    // With wrong formula: owedAmount becomes 500e6 - 5e8 (underflow if 5e8 > 500e6)
    // OR owedAmount becomes negative (underflow protected by arithmetic check)
    // In this case 5e8 = 500_000_000 >> 500e6 = 500_000_000 → equal.
    // Let's use a case where amountOut0 > owedAmount to prove user escapes payment:
    uint256 amountOut0_large = 600e6;
    uint256 repayWrong2 = amountOut1_sim < owedAmount_sim ? amountOut0_large : owedAmount_sim;
    // repayWrong2 = 600e6 > owedAmount_sim=500e6 → owedAmount becomes 0 (capped at 500e6 by subtraction)
    // Wait — no capping in code. 500e6 - 600e6 would UNDERFLOW (revert in checked math).
    // So the actual bug direction: when amountOut0 < owedAmount:
    // repayWrong = amountOut0, owedAfter = owedAmount - amountOut0 (too little subtracted)
    // amountOut1 not decremented → user receives full amountOut1

    t(repayWrong != repayCorrect || owedAfterWrong != owedAfterCorrect,
      "MATH-02: wrong and correct repay are unexpectedly equal");
}

function property_borrowedValue_scaling_correct() public {
    // Verify that the borrowedValue formula in liquidatePosition is consistent
    // with the totalValueUSD formula. Both should produce values in 1e18 USD scale.

    // Simulate with WBTC denomination
    address denom = WBTC_ADDR;
    uint256 owedAmount = ONE_WBTC; // 1 WBTC = 1e8
    uint256 bPrice = PRICE_WBTC;  // 100_000e18

    // Wrong formula (as coded):
    uint256 borrowedValueWrong = owedAmount * bPrice / ERC20(denom).decimals();
    // = 1e8 * 1e23 / 8 = 1.25e30

    // Correct formula:
    uint256 borrowedValueCorrect = owedAmount * bPrice / (10 ** ERC20(denom).decimals());
    // = 1e8 * 1e23 / 1e8 = 1e23? No: 1e8 * 100000e18 / 1e8 = 100000e18

    // totalValueUSD of 1 WBTC via _calculateTokenValues would be:
    // amount0=1e8, chPrice0=100000e18, decimals0=1e8
    // usdValue = 1e8 * 100000e18 / 1e8 = 100000e18

    // So borrowedValueCorrect = 100000e18 == totalValueUSD(1 WBTC) ✓
    // borrowedValueWrong = 1.25e30 >> 100000e18 ✗

    t(borrowedValueWrong > borrowedValueCorrect,
      "MATH-06: wrong borrowedValue should exceed correct for WBTC");

    // A solvent position would have totalValueUSD > borrowedValueCorrect
    // but NEVER totalValueUSD > borrowedValueWrong for any realistic position.
    uint256 totalValueUSD_example = 100001e18; // 1 WBTC + small profit
    t(totalValueUSD_example > borrowedValueCorrect,
      "MATH-06: correct formula: solvent position detectable");
    t(totalValueUSD_example < borrowedValueWrong,
      "MATH-06: wrong formula: solvent position UNDETECTABLE — fee always zero");
}

function property_sig02_withdraw_token1_repay_uses_correct_amount() public {
    // Si denomination es token1 (usdc), el repago debe venir de amountOut1
    // no de amountOut0. Verificar que tras un withdraw parcial con denom=token1,
    // el lending pool no pierde fondos.
    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.denomination != USDC_ADDR) return;
    if (pos.borrowedAmount == 0) return;

    uint256 lpLiqBefore = lendingPool.totalLiquidityOfReserve(USDC_ADDR);
    uint256 lpBorrowsBefore = lendingPool.totalBorrowsOfReserve(USDC_ADDR);

    // El invariante: liquidez_antes - borrows_antes == liquidez_despues - borrows_despues
    // (los intereses pueden variar, pero la relación neta no debe degradarse)
    // Tras un withdraw, el repago correcto mantiene la solvencia del lending pool
    uint256 netBefore = lpLiqBefore > lpBorrowsBefore ? lpLiqBefore - lpBorrowsBefore : 0;
    uint256 lpLiqAfter = lendingPool.totalLiquidityOfReserve(USDC_ADDR);
    uint256 lpBorrowsAfter = lendingPool.totalBorrowsOfReserve(USDC_ADDR);
    uint256 netAfter = lpLiqAfter > lpBorrowsAfter ? lpLiqAfter - lpBorrowsAfter : 0;

    // La liquidez neta no debe decrecer debido a un repago incorrecto
    gte(netAfter, netBefore > 1e6 ? netBefore - 1e6 : 0, "SIG-02: lending pool net liquidity decreased unexpectedly");
}

function property_sig03_liquidation_borrowedValue_uses_correct_decimals() public {
    // Verificar que tras una liquidación, el feeRecipient recibe tokens
    // si había profit (totalValueUSD > borrowedValue real).
    // El bug hace que borrowedValue sea artificialmente enorme, bloqueando fees.

    if (openPositionIds.length == 0) return;
    uint256 posId = openPositionIds[0];
    ILeverager.Position memory pos = leverager.getPosition(posId);
    if (pos.denomination == address(0)) return;

    // Propiedad: si hay profit real en la liquidación, feeRecipient debe recibir algo
    // Esto se verifica comprobando que el cálculo de decimals es correcto:
    // borrowedValue debería usar 10**decimals, no decimals directamente
    uint256 decimals = ERC20(pos.denomination).decimals();
    uint256 correctDivisor = 10 ** decimals;
    uint256 wrongDivisor = decimals; // el bug

    // Con el bug, borrowedValue es correctDivisor/wrongDivisor veces más grande
    // Para USDC: 1e6/6 ≈ 166666x más grande
    uint256 inflationFactor = correctDivisor / wrongDivisor;

    // Si inflationFactor > 1, el protocolo tiene el bug
    // La propiedad: feeRecipient debe tener balance > 0 tras liquidaciones con profit
    // (esto fallará con el bug porque fees nunca se envían)
    uint256 feeRecipBalance0 = IERC20(pos.token0).balanceOf(address(0xA0003)); // feeRecipient
    uint256 feeRecipBalance1 = IERC20(pos.token1).balanceOf(address(0xA0003));

    // Si hay posiciones y el protocolo tiene liquidationFee > 0 y hubo liquidaciones,
    // el feeRecipient debería tener algún balance
    t(inflationFactor == 1 || inflationFactor == 0,
      "SIG-03: decimals divisor is inflated - missing 10** exponentiation in borrowedValue");
}

