function property_liquidation_borrowed_value_correct() public {
    // Deploy a position and force it underwater, then check the borrowedValue calculation.
    // We verify the arithmetic is consistent: borrowedValue should use 10**decimals, not decimals().
    // Simulate: owedAmount=1e18 WETH, bPrice=2500e18, decimals()=18
    // correct: 1e18 * 2500e18 / 1e18 = 2500e18 (USD)
    // buggy:   1e18 * 2500e18 / 18   = 1.388...e35 (nonsense)
    uint256 owedAmount = 1e18; // 1 WETH
    uint256 bPrice = priceFeed.getPrice(WETH_ADDR); // e.g. 2500e18
    uint8 decs = ERC20(WETH_ADDR).decimals(); // 18
    uint256 buggyBorrowedValue = owedAmount * bPrice / decs; // WRONG
    uint256 correctBorrowedValue = owedAmount * bPrice / (10 ** uint256(decs)); // RIGHT
    // buggyBorrowedValue should equal correctBorrowedValue — it does NOT
    t(buggyBorrowedValue == correctBorrowedValue, "borrowedValue decimal mismatch in liquidatePosition");
}

function property_price_feed_decimal_consistent() public view {
    // Verify that getPrice returns a value in 1e18 scale as expected by _calculateTokenValues.
    // MockOracle is set to PRICE_WBTC = 100_000e18.
    uint256 p = priceFeed.getPrice(WBTC_ADDR);
    // The system expects p to be in 1e18 (as per Setup constants PRICE_WBTC = 100_000e18)
    // If real Chainlink is used with 1e8 decimals, this would be ~6.5e10 — off by 1e10.
    // Check that price is plausibly in 1e18 scale (>= 1e15 and <= 1e25).
    gte(p, 1e15, "price too low - possible decimal mismatch");
    lte(p, 1e25, "price too high - possible decimal mismatch");
}

function property_liquidation_uses_twap_not_spot() public view {
