    // Verify: if spot price deviates from TWAP, liquidation outcome should not change.
    // We check: for an open position, isLiquidateable should be consistent regardless
    // of small spot price changes (which it is NOT — it uses spot in balances()).
    if (openPositionIds.length == 0) return;
