    bool liqBefore = leverager.isLiquidateable(posId);

    // The position should not be liquidateable right after opening
    // (enforced by openLeveragedPosition's final check).
    // If it IS liquidateable, that means spot manipulation already affected it.
    t(!liqBefore, "position liquidateable right after open - spot price used in balances()");
}

