function property_deposit_no_rounding_loss() public {
    // Depositor deposits exactly the current ratio; should not lose value
    (uint256 bal0, uint256 bal1) = _getVaultBalances();
    if (bal0 == 0 || bal1 == 0) return;

    uint256 totalSup = _getTotalSupply();
    if (totalSup == 0) return;

    // Compute expected shares for a round-number deposit
    uint256 dep0 = bal0; // deposit equal to current holdings
    uint256 dep1 = bal1;

    deal(address(wbtc), depositor, dep0);
    deal(address(usdc), depositor, dep1);

    uint256 sharesBefore = _getShareBalance(depositor);
    (uint256 shares, uint256 used0, uint256 used1) = _depositAs(depositor, dep0, dep1);

    // The shares received should correspond exactly to the tokens used
    // i.e., used0 / bal0 == shares / totalSup  (proportionally)
    // If used0 > shares * bal0 / totalSup, depositor overpaid
    uint256 fairAmount0 = shares * bal0 / totalSup;
    uint256 fairAmount1 = shares * bal1 / totalSup;

    // Allow 1 wei tolerance for rounding
    t(used0 <= fairAmount0 + 1, "Depositor overpaid token0 beyond 1 wei");
    t(used1 <= fairAmount1 + 1, "Depositor overpaid token1 beyond 1 wei");
}

function property_assert_not_reachable() public {
    // Invariant: if totalSupply > 0, at least one balance must be > 0
    // If violated, the assert in _calcDeposit will DOS all future deposits (consumes all gas)
    uint256 totalSup = _getTotalSupply();
    if (totalSup == 0) return;

    (uint256 bal0, uint256 bal1) = _getVaultBalances();
    // This invariant must hold to prevent permanent deposit DOS
    t(bal0 > 0 || bal1 > 0, "Both balances are zero with non-zero totalSupply: deposit DOS risk");
}

function property_collectFees_uses_correct_vesting_ticks() public {
    // The vesting position is created at mainPosition ticks at the time
    // of addVestingPosition. After a rebalance, mainPosition ticks change
    // but vestPosition still holds the OLD ticks. Demonstrate that
    // collectFees uses wrong upper tick.
    //
    // Check: vesting position tickUpper stored in vestPosition equals
    // what collectFees would use (mainPosition.tickUpper).
    // If they differ, the fees are collected from the wrong range.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If the vest position tickUpper != main position tickUpper,
    // collectFees is collecting from the wrong range.
    t(
        vp.tickUpper == mp.tickUpper,
        "collectFees uses mainPosition.tickUpper instead of vestPosition.tickUpper"
    );
}

function property_vesting_does_not_overdrain() public {
