function property_deposit_exchange_rate_uses_real_liquidity() public {
    address asset = address(token0);
    uint256 depositAmt = 100 * ONE_TOKEN0;

    // Snapshot exchange rate before any pull
    uint256 rateBefore = _getExchangeRate(asset);

    // pullFunds corrupts underlyingBalance
    _pullFundsAsLeverager(asset, 500 * ONE_TOKEN0);

    // deposit sees stale (inflated) underlyingBalance
    uint256 yReceived = _depositAs(user, asset, depositAmt);

    // push back
    _pushFundsAsLeverager(asset, 500 * ONE_TOKEN0);

    // yTokens received should be consistent with rateBefore (real liquidity)
    // If underlyingBalance was wrong, user got fewer yTokens
    uint256 expectedY = depositAmt * PRECISION / _getExchangeRate(asset);
    // They should be approximately equal — if grossly different, underlyingBalance was stale
    gte(yReceived * 110 / 100, expectedY, "depositor received fewer yTokens due to stale underlyingBalance");
}

function property_pullFunds_storage_reference_correctness() public {
    address asset = address(token0);
    uint256 amt = 10 * ONE_TOKEN0;
    uint256 physBefore = token0.balanceOf(yToken0Addr);
    uint256 availBefore = _getAvailableLiquidity(asset);

    _pullFundsAsLeverager(asset, amt);

    uint256 physAfter = token0.balanceOf(yToken0Addr);
    uint256 availAfter = _getAvailableLiquidity(asset);

    // Physical balance decreased
    eq(physAfter, physBefore - amt, "physical yToken balance did not decrease after pullFunds");
