    eq(availAfter, availBefore - amt, "underlyingBalance not updated after pullFunds — memory vs storage bug");
}

function property_yToken_physical_balance_covers_redeemable() public {
    address asset = address(token0);
    // Total redeemable = totalYTokens * exchangeRate / PRECISION
    uint256 totalYT = _getYTokenTotalSupply(asset);
    uint256 exchRate = _getExchangeRate(asset);
    uint256 totalRedeemable = totalYT * exchRate / PRECISION;
    // Physical balance of yToken must cover all redemptions
    uint256 physBal = token0.balanceOf(yToken0Addr);
    uint256 borrows = _getTotalBorrows(asset);
    // physBal + borrows should cover totalRedeemable
    gte(physBal + borrows, totalRedeemable, "yToken physical balance + borrows cannot cover all redemptions");
}

