function property_vesting_fee_collection_uses_correct_ticks() public {
    // Only meaningful when there is an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The vesting position tickUpper must differ from mainPosition tickUpper
    // after a rebalance for the bug to manifest.
    // We assert that collectFees does NOT revert and actually uses vestPosition.tickUpper.
    // We check this indirectly: the vesting position's tickUpper should equal
    // what was stored at vesting creation, NOT the current mainPosition.tickUpper.
    // If they differ, collectFees silently collects from the wrong range.
    t(
        vp.tickUpper == mp.tickUpper,
        "TBH-001: vestPosition.tickUpper diverged from mainPosition.tickUpper after rebalance — collectFees uses wrong tick range"
    );
}

function property_collectFees_caller_independence() public {
    // collectFees should not allow non-privileged callers to affect share accounting
    // We verify that calling collectFees as attacker doesn't extract value
    uint256 sharesBefore = vault.balanceOf(user);
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();

    // attacker calls collectFees
    vm.prank(attacker);
    strategy.collectFees();

    uint256 sharesAfter = vault.balanceOf(user);
    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    uint256 supplyAfter = vault.totalSupply();

    // User's proportional claim should not decrease due to attacker calling collectFees
    // (fees go to feeRecipient, reducing everyone's claim equally)
    // This property verifies share count is unchanged
    eq(sharesBefore, sharesAfter, "TBH-002: user shares changed after attacker called collectFees");
    eq(supplyBefore, supplyAfter, "TBH-002: total supply changed after attacker called collectFees");
}

function property_positionWidth_requires_owner() public {
    uint24 widthBefore = strategy.positionWidth();

    // Attacker (non-rebalancer, non-owner) tries to change positionWidth
    // This should revert because changePositionWidth calls rebalance() which has onlyRebalancer
    bool reverted = false;
    vm.prank(attacker);
    try strategy.changePositionWidth(uint24(strategy.tickSpacing()) * 8) {
        // If it didn't revert, attacker changed the position width — bug
    } catch {
        reverted = true;
    }
    t(reverted, "TBH-003: attacker was able to call changePositionWidth");

    // Also verify positionWidth unchanged
    eq(uint256(strategy.positionWidth()), uint256(widthBefore), "TBH-003: positionWidth changed by attacker");
}

function property_withdraw_returns_full_removed_amount() public {
    // Setup: ensure there are accrued fees in positions
    // Simulate time passing and trades generating fees
    skip(1 days);

    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 totalSupply = vault.totalSupply();
    (uint256 stratBal0Before, uint256 stratBal1Before) = strategy.balances();

    uint256 expectedOut0 = stratBal0Before * userShares / totalSupply;
    uint256 expectedOut1 = stratBal1Before * userShares / totalSupply;

    uint256 wbtcBefore = wbtc.balanceOf(user);
    uint256 usdcBefore = usdc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    uint256 wbtcAfter = wbtc.balanceOf(user);
    uint256 usdcAfter = usdc.balanceOf(user);

    uint256 received0 = wbtcAfter - wbtcBefore;
    uint256 received1 = usdcAfter - usdcBefore;

    // User should receive approximately their proportional share (within 1% tolerance for rounding)
    gte(received0 * 100, expectedOut0 * 99, "TBH-004: user received significantly less token0 than expected");
    gte(received1 * 100, expectedOut1 * 99, "TBH-004: user received significantly less token1 than expected");
}

function property_secondary_position_direction_matches_balances() public {
    // After rebalance, check secondary position direction is consistent with actual balances
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();

    // Get amounts for secondary position at current price
    (uint256 s0, uint256 s1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(sp.tickLower),
        TickMath.getSqrtRatioAtTick(sp.tickUpper),
        sp.liquidity
    );

    // Secondary position should be OOR — only one of s0 or s1 should be non-zero
    // If both are non-zero, secondary position is in-range which violates design intent
    t(s0 == 0 || s1 == 0, "TBH-005: secondary position is in-range (should be OOR) — possible price manipulation during rebalance");
}

function property_collectFees_no_double_fee() public {
    // Verify that calling collectFees twice in the same block doesn't double-charge fees
    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();

    strategy.collectFees();
    (uint256 idle0Mid, uint256 idle1Mid) = strategy.idleBalances();

    strategy.collectFees(); // second call same block
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // Second collectFees should not reduce idle balances further (no new fees since same block)
    gte(idle0After, idle0Mid, "TBH-006: second collectFees in same block reduced idle0");
    gte(idle1After, idle1Mid, "TBH-006: second collectFees in same block reduced idle1");
}

function property_withdraw_transfers_match_computed_amounts() public {
