function property_first_deposit_shares_nonzero_both_tokens() public {
    // After the initial seed deposit in setUp, check that the first depositor
    // received shares proportional to BOTH tokens deposited.
    // If the formula only uses max(amount0, amount1), it ignores the other
    // token's value entirely.
    uint256 userShares = vault.balanceOf(user);
    uint256 ts = vault.totalSupply();
    // User deposited 1e8 WBTC and 100_000e6 USDC.
    // shares = max(1e8, 100_000e6) - 1000 = 100_000e6 - 1000
    // This means user's share of token0 (WBTC=1e8) is only
    // userShares/ts of total WBTC.
    // Check: userShares should reflect BOTH tokens proportionally.
    // The 1 WBTC was worth ~80,000 USDC but only contributes
    // if max(amount0,amount1) == amount0. Here amount1 > amount0 so WBTC is ignored.
    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 userBal0 = bal0 * userShares / ts;
    uint256 userBal1 = bal1 * userShares / ts;
    // User deposited 1e8 WBTC but their share of WBTC should be proportional.
    // Shares were computed from amount1 only, so WBTC value is locked for burn addr.
    // The burn addr (1000 shares) holds significant WBTC value.
    uint256 burnShares = vault.balanceOf(BURN);
    uint256 burnBal0 = bal0 * burnShares / ts;
    // The burn address should only hold a tiny fraction (1000 shares out of ~100_000e6)
    // but due to the formula bug, if amounts differ in scale, burn addr's WBTC
    // fraction might be significant.
    // Property: burn address fraction of total shares should be negligible
    t(burnShares * 10_000 / ts < 10, "burn address holds excessive share of vault");
}

function property_deposit_shares_not_zero_for_nonzero_deposit() public {
    // After the initial setup, depositor deposits a small but nonzero amount.
    // Due to the sequential division bug, shares can round to 0 for small deposits
    // even when the user contributes nonzero value.
    uint256 smallAmt0 = 1; // 1 sat of WBTC
    uint256 smallAmt1 = 1; // 1 unit of USDC (but we need meaningful amount)
    deal(address(wbtc), depositor, ONE_TOKEN0);
    deal(address(usdc), depositor, ONE_TOKEN1);
    vm.startPrank(depositor);
    (uint256 shares,,) = vault.deposit(ONE_TOKEN0, ONE_TOKEN1, 0, 0);
    vm.stopPrank();
    // Shares must be > 0 when depositing non-trivial amounts
    t(shares > 0, "depositor received 0 shares for nonzero deposit");
    // Now verify proportionality: depositor's shares should be proportional to deposit
    uint256 ts = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();
    // depositor's entitlement should be at least as much as one tick of precision
    uint256 depositorBal0 = bal0 * vault.balanceOf(depositor) / ts;
    t(depositorBal0 > 0, "depositor gets 0 token0 on withdrawal due to rounding");
}

