function property_pullFunds_updates_underlyingBalance() public {
    // Record state before pull
    uint256 balBefore = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 available = _getAvailableLiquidity(address(token0));
    uint256 pullAmt = available / 2;
    if (pullAmt == 0) return;

    // leverager pulls funds — this does NOT update underlyingBalance in buggy code
    _pullFundsAsLeverager(address(token0), pullAmt);

    // After pull, the real token balance in yToken dropped by pullAmt
    uint256 realBalance = token0.balanceOf(yToken0Addr);
    // But totalLiquidity (which reads underlyingBalance) should also have dropped
    uint256 balAfter = lendingPool.totalLiquidityOfReserve(address(token0));

    // The invariant: totalLiquidity should equal realBalance + borrowedLiquidity
    uint256 borrowed = lendingPool.totalBorrowsOfReserve(address(token0));
    // realBalance + borrowed should equal reported totalLiquidity
    // If pullFunds doesn't update underlyingBalance, balAfter == balBefore (bug)
    t(balAfter < balBefore, "pullFunds must reduce reported totalLiquidity");
}

function property_pushFunds_updates_underlyingBalance() public {
    uint256 pushAmt = 1_000 * ONE_TOKEN0;
    token0.mint(leveragerActor, pushAmt);

    uint256 liquidityBefore = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 yTokenBalBefore = token0.balanceOf(yToken0Addr);

    _pushFundsAsLeverager(address(token0), pushAmt);

    uint256 liquidityAfter = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 yTokenBalAfter = token0.balanceOf(yToken0Addr);

    // Real tokens increased
    t(yTokenBalAfter == yTokenBalBefore + pushAmt, "yToken balance should increase by pushAmt");
    // Reported liquidity should also increase
    t(liquidityAfter == liquidityBefore + pushAmt, "totalLiquidity must reflect pushed funds");
}

function property_pullFunds_memory_not_storage() public {
    // Demonstrate: pullFunds reads reserve as memory, so underlyingBalance in storage is never updated
    // After pullFunds, underlyingBalance in storage == underlyingBalance before pull
    uint256 available = _getAvailableLiquidity(address(token0));
    uint256 pullAmt = available / 4;
    if (pullAmt == 0) return;

    uint256 liquidityBefore = lendingPool.totalLiquidityOfReserve(address(token0));
    _pullFundsAsLeverager(address(token0), pullAmt);
    uint256 liquidityAfter = lendingPool.totalLiquidityOfReserve(address(token0));

    // Bug: liquidity is unchanged because underlyingBalance was never written to storage
    // This property FAILS (demonstrates the bug): liquidity should have decreased
    t(liquidityAfter == liquidityBefore - pullAmt, "underlyingBalance in storage must be updated by pullFunds");
}

function property_no_inflation_after_full_redeem() public {
    // user redeems everything they can
    uint256 userYBal = _getYTokenBalance(address(token0), user);
    if (userYBal > 0) {
        _redeemAs(user, address(token0), userYBal, user);
    }
    uint256 depositorYBal = _getYTokenBalance(address(token0), depositor);
    if (depositorYBal > 0) {
        _redeemAs(depositor, address(token0), depositorYBal, depositor);
    }

    // Now only DEAD_ADDRESS holds yTokens (the burned minimum)
    uint256 deadYBal = IERC20(yToken0Addr).balanceOf(DEAD_ADDRESS);
    uint256 totalSupply = _getYTokenTotalSupply(address(token0));
    t(totalSupply == deadYBal, "only dead address yTokens should remain");

    // A new depositor should get a fair exchange rate, not be front-run
    uint256 depositAmt = 1 * ONE_TOKEN0;
    uint256 yReceived = _depositAs(attacker, address(token0), depositAmt);

    // yReceived should be proportional to depositAmt / totalLiquidity * totalSupply
    // Not zero (attacker shouldn't be drained)
    t(yReceived > 0, "attacker deposit should yield nonzero yTokens");
}

function property_borrow_interest_rate_updated_after_borrow() public {
