    uint256 rateBefore = _getBorrowingRate(address(token0));
    _borrowAsLeverager(address(token0), borrow1);
    uint256 rateAfter = _getBorrowingRate(address(token0));

    // After borrowing, utilization increased, so rate should be >= before
