function property_WC001_fullmath_correctness() public {
    // mulDiv(a, b, denominator) should equal a*b/denominator for small values
    // where 512-bit path is NOT taken (prod1==0). Verify basic correctness.
    uint256 a = ONE_TOKEN0 * 1e10; // large but not overflowing
    uint256 b = ONE_TOKEN1 * 1e10;
    uint256 denom = 1e18;
    // If a*b overflows (prod1 != 0), the 512-bit path is taken with wrong seed
    // We can detect: result * denom should approx equal a * b (mod 2^256)
    // Instead, property: mulDiv result should be >= a/denom (when b>=1) if denom <= b
    // The key invariant: mulDiv(a, b, b) == a exactly
    uint256 result = FullMath.mulDiv(a, b, b);
    eq(result, a, "WC-001: mulDiv(a,b,b) must equal a — XOR seed corrupts 512-bit path");
}

