    // Attacker withdraws immediately — should recover close to what they put in
    vm.prank(attacker);
    (uint256 got0, uint256 got1) = vault.withdraw(shares, 0, 0);

    // Allow up to 1% slippage — if attacker loses >1% something is wrong
    // (not the inflation attack direction, but validates share math integrity)
    t(got0 + got1 > 0, "WC-002: attacker received nothing on withdraw");
}

function property_WC003_deposit_rounding_symmetry() public {
    // Deposit and immediately withdraw should return close to deposited amounts
    // Small deposit to expose rounding: deposit exactly 1 WBTC + proportional USDC
    uint256 amt0 = ONE_TOKEN0;
    (uint256 bal0, uint256 bal1) = strategy.balances();

    // Calculate proportional amt1
    uint256 amt1 = bal1 > 0 && bal0 > 0 ? amt0 * bal1 / bal0 : ONE_TOKEN1 * 100_000;

    deal(address(token0), depositor, amt0);
    deal(address(token1), depositor, amt1 + 2); // +2 for rounding

    vm.startPrank(depositor);
    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amt0, amt1 + 2, 0, 0);
    vm.stopPrank();

    t(shares > 0, "WC-003: shares must be nonzero");

    vm.prank(depositor);
    (uint256 got0, uint256 got1) = vault.withdraw(shares, 0, 0);

    // Depositor should get back at least 99% of deposited tokens (1% tolerance for fees/rounding)
    uint256 deposited0 = dep0;
    uint256 deposited1 = dep1;
    // got0 + got1 (in token0 terms) >= 99% of dep0 + dep1
    t(got0 * 100 >= deposited0 * 99, "WC-003: excessive token0 loss on deposit/withdraw round trip");
    t(got1 * 100 >= deposited1 * 99, "WC-003: excessive token1 loss on deposit/withdraw round trip");
}

function property_WC004_no_share_inflation_during_withdraw() public {
    // Invariant: totalSupply * pricePerShare should be constant throughout a withdraw
    // Proxy: depositor's shares + attacker's shares should not increase after a withdraw by user
    uint256 userShares = vault.balanceOf(user);
    uint256 depositorShares = vault.balanceOf(depositor);
    uint256 totalSupplyBefore = vault.totalSupply();

    if (userShares == 0) return;

    vm.prank(user);
    vault.withdraw(userShares / 2 + 1, 0, 0);

    uint256 totalSupplyAfter = vault.totalSupply();
    uint256 depositorSharesAfter = vault.balanceOf(depositor);

    // depositor's shares should not have increased
    lte(depositorSharesAfter, depositorShares, "WC-004: depositor shares inflated during withdraw");
    // totalSupply should have decreased by exactly the burned shares
    t(totalSupplyAfter < totalSupplyBefore, "WC-004: totalSupply should decrease after withdraw");
}

function property_WC005_withdraw_always_executable() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 allowance0 = token0.allowance(address(strategy), address(vault));
    uint256 allowance1 = token1.allowance(address(strategy), address(vault));

    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 ts = vault.totalSupply();
    uint256 needed0 = bal0 * userShares / ts;
    uint256 needed1 = bal1 * userShares / ts;

    // Vault must have sufficient allowance from strategy to cover a full withdraw
    gte(allowance0, needed0, "WC-005: strategy allowance for token0 insufficient for withdraw");
    gte(allowance1, needed1, "WC-005: strategy allowance for token1 insufficient for withdraw");
}

function property_WC006_deposit_fee_bounded() public {
