function property_WC008_shares_nonzero_on_valid_deposit() public {
    // After a price movement making one balance tiny, deposits should still work
    // Simulate by checking current balances
    (uint256 b0, uint256 b1) = strategy.balances();
    if (b0 == 0 || b1 == 0) return; // handled by other branches

    uint256 ts = vault.totalSupply();
    if (ts == 0) return;

    // Compute expected shares for a 1-WBTC deposit
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = amt0 * b1 / b0; // proportional
    if (amt1 == 0) return;

    uint256 cross0 = amt0 * b1;
    uint256 cross1 = amt1 * b0;
    uint256 cross = cross0 < cross1 ? cross0 : cross1;
    if (cross == 0) return;

    uint256 expectedShares = cross * ts / b0 / b1;
    t(expectedShares > 0, "WC-008: deposit would yield 0 shares due to division ordering");
}

function property_getTokenIn_multiHop_terminates() public {
    // Build a two-hop path: weth -> 3000 -> usdc -> 500 -> wbtc
    // For exactOutput encoding: tokenOut first, then fee, then tokenIn
    bytes memory twoHopPath = abi.encodePacked(
        address(wbtc),
        uint24(3000),
        address(usdc),
        uint24(3000),
        address(weth)
    );
    // This call should return weth (the tokenIn) and NOT infinite-loop.
    // We wrap in a try to detect OOG / revert from infinite loop.
    // If it reverts, the property is violated.
    // We test via a low-level call with limited gas.
    (bool success,) = address(leverager).call{gas: 500_000}(
        abi.encodeWithSignature("_getTokenIn(bytes)", twoHopPath)
    );
    // If success is false due to OOG, the property is violated.
    // The call should succeed and return weth.
    t(success, "multiHop _getTokenIn infinite loop / OOG");
}

