    uint256 available = _getAvailableLiquidity(address(token0));
    if (available == 0) return;

    uint256 pullAmt = available / 2;

    // Leverager pulls funds — this does NOT update underlyingBalance
    _pullFundsAsLeverager(address(token0), pullAmt);

    // Now try to redeem a small amount — should not revert if
    // underlyingBalance is honest, but will revert because yToken
    // has fewer tokens than underlyingBalance implies.
    uint256 yBal = _getYTokenBalance(address(token0), user);
    if (yBal == 0) return;

