/// @notice If there is an ongoing vesting position, the tick range used in
///         collectFees for fee collection must form a valid Uniswap range
///         (tickLower < tickUpper). The bug uses mainPosition.tickUpper,
///         which can be < vestPosition.tickLower after significant price moves.
function property_collectFees_vesting_tick_range_valid() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses (vestPosition.tickLower, mainPosition.tickUpper).
    // If this range is invalid (lower >= upper), collectFees will revert,
    // permanently bricking deposit() and withdraw().
    t(
        vp.tickLower < mp.tickUpper,
        "DDH-V-001: vestPosition.tickLower >= mainPosition.tickUpper; collectFees will revert and brick vault"
    );
    return true;
}

/// @notice Depositing and immediately withdrawing should not yield a profit.
///         If spot-price manipulation inflates shares, an attacker extracts value.
///         This property detects the invariant violation without simulating manipulation:
///         after any deposit, the depositor's proportional claim on vault assets
///         must not exceed what they deposited (plus 2 wei rounding tolerance).
function property_deposit_withdraw_no_profit_DDH_V_002(uint256 amt1) public returns (bool) {
    amt1 = _clampBetween(amt1, ONE_TOKEN1, 10_000 * ONE_TOKEN1);

    deal(address(token1), attacker, amt1);
    uint256 pre1 = token1.balanceOf(attacker);

    vm.startPrank(attacker);
    token1.approve(address(vault), amt1);
    (uint256 shares,,) = vault.deposit(0, amt1, 0, 0);
    (uint256 w0, uint256 w1) = vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    uint256 post0 = token0.balanceOf(attacker);
    uint256 post1 = token1.balanceOf(attacker);

    // Convert any token0 gain to token1 equivalents using vault price
    uint256 spotPrice = vault.price(); // token0/token1 in 1e30
    uint256 got0InToken1 = post0 * spotPrice / 1e30;
    uint256 got1 = w1 + post1 > pre1 ? post1 - pre1 : 0;
    uint256 totalExtracted = w1 + got0InToken1;

    t(
        totalExtracted <= amt1 + 2,
        "DDH-V-002: deposit+withdraw yields profit — spot-price manipulation possible"
    );
    return true;
}

/// @notice After withdrawing shares, the user should receive at least
///         their proportional share of vault assets minus 1% rounding tolerance.
///         This catches the case where idle-check causes underdelivery.
function property_withdraw_delivers_fair_amount_DDH_V_003(uint256 sharePct) public returns (bool) {
    sharePct = _clampBetween(sharePct, 1, 50);

    uint256 userShares = _getShareBalance(user);
    if (userShares == 0) return true;

    uint256 sharesToWithdraw = userShares * sharePct / 100;
    if (sharesToWithdraw == 0) return true;

    // Capture balances BEFORE withdrawal (using same spot-price as vault will use)
    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 ts = vault.totalSupply();

    uint256 expectedW0 = bal0 * sharesToWithdraw / ts;
    uint256 expectedW1 = bal1 * sharesToWithdraw / ts;

    (uint256 actual0, uint256 actual1) = _withdrawAs(user, sharesToWithdraw);

    // User should receive at least 99% of what balances() implied
    if (expectedW0 > 100) {
        t(
            actual0 >= expectedW0 * 99 / 100,
            "DDH-V-003: withdraw delivered <99% of expected token0 — idle-check underdelivery"
        );
    }
    if (expectedW1 > 100) {
        t(
            actual1 >= expectedW1 * 99 / 100,
            "DDH-V-003: withdraw delivered <99% of expected token1 — idle-check underdelivery"
        );
    }
    return true;
}

/// @notice When an ongoing vesting position exists, new depositors should not
///         receive a windfall at the expense of existing holders.
///         Property: if vestPosition value > 5% of reported vault NAV, warn.
function property_vesting_not_captured_by_new_depositors_DDH_V_004() public returns (bool) {
    if (!_isOngoingVestingPosition()) return true;

    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 ts = vault.totalSupply();
    if (ts == 0 || (bal0 == 0 && bal1 == 0)) return true;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return true;

    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
    (uint256 v0, uint256 v1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    // If vesting position value exceeds 50% of reported vault NAV, dilution is severe
    // Use token1 as common denomination
    uint256 spotPrice = vault.price(); // token0 per token1 in 1e30
    uint256 vestValue1 = v1 + (spotPrice > 0 ? v0 * 1e30 / spotPrice : 0);
    uint256 vaultValue1 = bal1 + (spotPrice > 0 ? bal0 * 1e30 / spotPrice : 0);

    t(
        vestValue1 <= vaultValue1 * 2,
        "DDH-V-004: vesting position value > 2x reported vault NAV; new depositors capture extreme vesting yield"
    );
    return true;
}

/// @notice After deposit, shares received should be within depositFee tolerance
///         of what pure _calcDeposit math would give. The user cannot protect
///         against fee changes, so we verify fee is not applied to devalue shares
///         beyond the advertised maximum (0.1% = 10 bps).
function property_deposit_fee_capped_DDH_V_005(uint256 amt0, uint256 amt1) public returns (bool) {
    amt0 = _clampBetween(amt0, ONE_TOKEN0 / 10, ONE_TOKEN0);
    amt1 = _clampBetween(amt1, ONE_TOKEN1, 10_000 * ONE_TOKEN1);

    deal(address(token0), depositor, amt0);
    deal(address(token1), depositor, amt1);

    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 ts = vault.totalSupply();
    if (ts == 0 || bal0 == 0 || bal1 == 0) return true;

    uint256 feeBps = vault.depositFee();

    vm.startPrank(depositor);
    token0.approve(address(vault), amt0);
    token1.approve(address(vault), amt1);
    (uint256 shares, uint256 d0, uint256 d1) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    // Compute gross shares (before fee) using the same formula as _calcDeposit
    uint256 cross0 = d0 * bal1;
    uint256 cross1 = d1 * bal0;
    uint256 cross = cross0 < cross1 ? cross0 : cross1;
    if (cross == 0) return true;
    uint256 grossShares = cross * ts / bal0 / bal1;

    // Net shares after fee should be at least grossShares * (10000 - maxFee) / 10000
    uint256 expectedMin = grossShares * (10_000 - 10) / 10_000; // max fee = 10 bps
    t(
        shares >= expectedMin,
        "DDH-V-005: shares received below minimum after maximum depositFee application"
    );
    return true;
}

/// @notice Depositor should receive at most 2 fewer shares than mathematical ideal.
///         Catching cases where sequential division loses more than expected.
function property_calcDeposit_precision_loss_bounded_DDH_V_006(
    uint256 amt0,
    uint256 amt1
) public returns (bool) {
    amt0 = _clampBetween(amt0, ONE_TOKEN0 / 100, ONE_TOKEN0 * 10);
    amt1 = _clampBetween(amt1, ONE_TOKEN1, 100_000 * ONE_TOKEN1);

    (uint256 bal0, uint256 bal1) = vault.balances();
    uint256 ts = vault.totalSupply();
    if (ts == 0 || bal0 == 0 || bal1 == 0) return true;

    deal(address(token0), depositor, amt0);
    deal(address(token1), depositor, amt1);

    vm.startPrank(depositor);
    token0.approve(address(vault), amt0);
    token1.approve(address(vault), amt1);
    (uint256 shares, uint256 d0, uint256 d1) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    if (d0 == 0 || d1 == 0) return true; // single-sided deposit branch, skip

    uint256 cross0 = d0 * bal1;
    uint256 cross1 = d1 * bal0;
    uint256 cross = cross0 < cross1 ? cross0 : cross1;
    if (cross == 0) return true;

    // Ideal: cross * ts / (bal0 * bal1), but avoid overflow check
    // Lower bound: shares should be >= ideal - 2
    uint256 sharesIdeal = cross * ts / bal0 / bal1;

    // Allow 2 units of precision loss from sequential division
    // But if more than 2 shares lost, it indicates a deeper bug
    t(
        shares + 2 >= sharesIdeal,
        "DDH-V-006: depositor lost more than 2 shares to sequential division precision loss"
    );
    return true;
}

