    leverager.setLiquidationFee(500); // 5%

    // Open a WBTC-denominated position
    uint256 posId = _openWbtcPosition(user, ONE_WBTC, 100_000e6, ONE_WBTC, 100_000e6, ONE_WBTC / 2);

    // Drop WBTC price so position becomes liquidatable
    vm.prank(owner);
    wbtcOracle.setPrice(1e18); // crash price to $1

    require(leverager.isLiquidateable(posId), "position should be liquidateable");

    uint256 feeRecipientBal0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1Before = usdc.balanceOf(feeRecipient);

