    uint256 feeRecipientBal0After = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1After = usdc.balanceOf(feeRecipient);

    // With a 5% fee and a profitable liquidation, feeRecipient should have gained tokens
    t(
        feeRecipientBal0After > feeRecipientBal0Before || feeRecipientBal1After > feeRecipientBal1Before,
        "feeRecipient received no liquidation fee"
