function property_AH006_fullmath_correctness() public {
    // mulDiv(a, b, denom) should match a naive calculation for small values
    // where overflow is not possible.
    uint256 a = ONE_TOKEN0; // 1e8
    uint256 b = ONE_TOKEN1; // 1e6
    uint256 denom = 1e7;

    // Naive: a * b / denom = 1e8 * 1e6 / 1e7 = 1e7
    uint256 expected = 1e7;
    uint256 actual = FullMath.mulDiv(a, b, denom);

    eq(actual, expected, "AH-006: FullMath.mulDiv incorrect result");

    // Test with a denominator where (3*d) ^ 2 may give bad seed
    uint256 denom2 = 0xFFFFFFFFFFFFFFFF; // large odd denominator
    uint256 a2 = denom2; // a * b = denom^2, result should be denom
    uint256 actual2 = FullMath.mulDiv(a2, denom2, denom2);
    eq(actual2, denom2, "AH-006: FullMath.mulDiv incorrect for large odd denominator");
}

