/// @dev After a profitable liquidation the protocol should have collected fees
/// to feeRecipient (if non-zero).  This property shows that the borrowedValue
/// formula is wrong: even when collateral clearly exceeds debt, the fee branch
/// (totalValueUSD > borrowedValue) is never entered.
///
/// Strategy: open a 1.1× leveraged USDC position so collateral >> debt,
/// then liquidate immediately (by dropping the price) and check that the
/// fee path was reached.  The property FAILS because borrowedValue is
/// inflated ~166,666× and so totalValueUSD is never greater.
function property_DDH_LEV_003_liquidation_fee_collected_when_profitable() public returns (bool) {
    // ── 1. Open a tiny USDC-denominated position (nearly no leverage) ──────
    uint256 amount0In  = 0.1e8;
    uint256 maxBorrow  = 50e6;

    deal(address(wbtc), user, amount0In);
    vm.startPrank(user);
    wbtc.approve(address(leverager), type(uint256).max);
    usdc.approve(address(leverager), type(uint256).max);

    ILeverager.LeverageParams memory lp;
    lp.amount0In       = amount0In;
    lp.amount1In       = 0;
    lp.vault0In        = amount0In;
    lp.vault1In        = 0;
    lp.vault           = address(vault);
    lp.denomination    = address(usdc);
    lp.maxBorrowAmount = maxBorrow;
    IMainnetRouter.ExactOutputParams memory ep;
    ep.path            = abi.encodePacked(address(wbtc), uint24(3000), address(usdc));
    ep.deadline        = block.timestamp + 600;
    ep.amountInMaximum = type(uint256).max;
    ep.recipient       = address(leverager);
    lp.swapParams1     = abi.encode(ep);

    uint256 posId;
    try ILeverager(address(leverager)).openLeveragedPosition(lp) returns (uint256 _id) {
        posId = _id;
    } catch {
        vm.stopPrank();
        return true;
    }
    vm.stopPrank();

    // ── 2. Set a non-zero liquidation fee via owner ──────────────────────
    vm.prank(owner);
    ILeverager(address(leverager)).setLiquidationFee(500); // 5 %

    // ── 3. Crash WBTC price to make position liquidateable ────────────────
    vm.prank(owner);
    wbtcOracle.setPrice(1_000e18); // 99 % drop

    // skip enough time for TWAP to catch up (if applicable)
    skip(30 minutes);

    if (!leverager.isLiquidateable(posId)) {
        return true; // not liquidateable yet, skip
    }

    // ── 4. Liquidate and check that feeRecipient received tokens ──────────
    // NOTE: feeRecipient is address(0) (DDH-LEV-001), but we can check the
    // fee logic branching via balance of address(0) before vs after.
    uint256 usdc0Before = usdc.balanceOf(address(0));
    uint256 wbtc0Before = wbtc.balanceOf(address(0));

    vm.startPrank(liquidator);
    deal(address(usdc), liquidator, 10_000e6);
    usdc.approve(address(leverager), type(uint256).max);

    ILeverager.LiquidateParams memory liqP;
    liqP.id = posId;
    try ILeverager(address(leverager)).liquidatePosition(liqP) {} catch {
        vm.stopPrank();
        return true; // liquidation reverted — separate issue
    }
    vm.stopPrank();

    uint256 usdc0After = usdc.balanceOf(address(0));
    uint256 wbtc0After = wbtc.balanceOf(address(0));

    // If the fee branch were correctly entered, address(0) would have received
    // fee tokens.  Because borrowedValue is inflated 166,666×, the branch is
    // never entered and balances of address(0) do not change.
    // Property FAILS when fees should have been collected but weren't.
    bool feeWasCollected = (usdc0After > usdc0Before) || (wbtc0After > wbtc0Before);
    // For a profitable liquidation (collateral >> debt at 99% price drop relative
    // to borrow), fee MUST be collected.  Returning false demonstrates the bug.
    return feeWasCollected;
}

