    // ── 2. Snapshot borrow index and position state ──────────────────────
    ILeverager.Position memory before = leverager.getPosition(posId);
    uint256 bIndexBefore = ILendingPool(address(lendingPool)).getCurrentBorrowingIndex(address(usdc));
    uint256 totalOwedBefore = before.borrowedAmount * bIndexBefore / before.borrowedIndex;

    // ── 3. Partial withdrawal (50 %) ─────────────────────────────────────
