function property_pullFunds_decrements_underlyingBalance() public {
    // Snapshot underlyingBalance before pull
    uint256 avail0 = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 borrows0 = lendingPool.totalBorrowsOfReserve(address(token0));
    uint256 underlyingBefore = avail0 >= borrows0 ? avail0 - borrows0 : 0;

    uint256 pullAmt = underlyingBefore / 4;
    if (pullAmt == 0) return;

    // Pull funds as leverager — no borrow accounting changes
    vm.prank(leveragerActor);
    lendingPool.pullFunds(address(token0), pullAmt);

    // After pull: actual yToken ERC20 balance should match what pool thinks is available
    uint256 avail1 = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 borrows1 = lendingPool.totalBorrowsOfReserve(address(token0));
    uint256 claimedAvail = avail1 >= borrows1 ? avail1 - borrows1 : 0;

    uint256 actualBal = token0.balanceOf(yToken0Addr);

    // The pool's claimed available liquidity must equal the actual ERC20 balance
    // in the yToken (since nothing else holds underlying between pool and yToken).
    // This will FAIL because underlyingBalance was not decremented.
    eq(claimedAvail, actualBal, "pullFunds: underlyingBalance not decremented");
}

