function property_calculate_token_values_no_precision_loss() public {
    // Simulate a case where token1 has no pricefeed and we use TWAP
    // The two orderings should give the same result
    // We check that small amounts of token1 still produce nonzero USD value
    // when the TWAP price is set and token0 has a pricefeed

    // With wbtcOracle set at 100_000e18 and usdc oracle set, both have feeds.
    // We rely on the fact that initCollateralUsd is computed correctly.
    uint256 posId = _openWbtcPosition(user, 0.01e8, 1000e6, 0.01e8, 1000e6, 0.005e8);
    ILeverager.Position memory pos = leverager.getPosition(posId);

    // initCollateralUsd should be > 0 (it's deposited value in USD 1e18)
    gte(pos.initCollateralUsd, 1e18, "collateral USD value should be at least $1");

    // initCollateralValue (in denomination token units) should match
    // roughly: initCollateralUsd * 1e8 / wbtcPrice
    uint256 bPrice = priceFeed.getPrice(address(wbtc));
    uint256 expectedCollatValue = pos.initCollateralUsd * ONE_WBTC / bPrice;
    uint256 tolerance = expectedCollatValue / 10; // 10% tolerance
    gte(pos.initCollateralValue + tolerance, expectedCollatValue, "collateral value precision loss");
}

function property_liquidation_threshold_reasonable() public {
    // Open a position at near-max leverage
    uint256 posId = _openWbtcPosition(user, 0.1e8, 10_000e6, 0.1e8, 10_000e6, 0.08e8);

    ILeverager.Position memory pos = leverager.getPosition(posId);
    // position should not be immediately liquidatable
    t(!leverager.isLiquidateable(posId), "freshly opened position should not be liquidatable");

    // After a 3% price drop, should still not be liquidatable (has >10% collateral buffer)
    vm.prank(owner);
    wbtcOracle.setPrice(97_000e18); // 3% drop
    usdcOracle.setPrice(1e18);

    // With such tight liquidation threshold, a 3% drop might already trigger liquidation
    // which would be a problem if it causes bad debt
    bool liqAfter3pctDrop = leverager.isLiquidateable(posId);
    // This property checks: if liquidatable at 3% drop, that's too aggressive
    t(!liqAfter3pctDrop, "3% price drop should not liquidate a healthy position");
}

function property_partial_withdraw_borrow_accounting_consistent() public {
    uint256 posId = _openWbtcPosition(user, 0.1e8, 10_000e6, 0.1e8, 10_000e6, 0.05e8);
    ILeverager.Position memory posBefore = leverager.getPosition(posId);

    // Advance time to accrue interest
    skip(30 days);

    uint256 bIndexBefore = lendingPool.getCurrentBorrowingIndex(address(wbtc));
    uint256 totalOwed = posBefore.borrowedAmount * bIndexBefore / posBefore.borrowedIndex;

    _partialWithdraw(user, posId, 0.5e18);

    ILeverager.Position memory posAfter = leverager.getPosition(posId);
    uint256 bIndexAfter = lendingPool.getCurrentBorrowingIndex(address(wbtc));

    // borrowedIndex should be updated to current
    eq(posAfter.borrowedIndex, bIndexAfter, "borrowedIndex should be updated to current bIndex");

    // borrowedAmount should represent ~50% of totalOwed
    uint256 expectedRemaining = totalOwed - (totalOwed * 0.5e18 / 1e18);
    uint256 tolerance = expectedRemaining / 100; // 1%
    gte(posAfter.borrowedAmount + tolerance, expectedRemaining, "borrowedAmount too low after partial withdraw");
    lte(posAfter.borrowedAmount, expectedRemaining + tolerance, "borrowedAmount too high after partial withdraw");
}

