/// @notice After a rebalance, mainPosition ticks change but vestPosition ticks
///         do not. If collectFees uses mainPosition.tickUpper for the vesting
///         position it targets the wrong Uniswap position.
///         Property: while a vesting position is active, vestPosition.tickUpper
///         must equal the tickUpper actually used in collectPositionFees — which
///         the code wrongly sets to mainPosition.tickUpper.
function property_collectFees_uses_correct_vesting_tickUpper() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp    = strategy.getMainPosition();

    // If main-position ticks have diverged from vesting-position ticks (i.e.
    // after a rebalance), the bug is live: collectFees targets the wrong range.
    // The invariant is that they must still match for correctness.
    return t(
        vp.tickUpper == mp.tickUpper,
        "DDH-001: collectFees uses mainPosition.tickUpper for vesting fees; should use vestPosition.tickUpper"
    );
}

/// @notice When a vesting position is active, balances() should include the
///         vesting position's token contribution. If it does not, new depositors
///         get surplus shares at the expense of existing LPs.
///
///         Property: balances().amount0 >= vestPosition token0 equivalent when
///         ongoingVestingPosition is true and remainingLiquidity > 0.
///         (Fails because vesting contribution is omitted.)
function property_balances_includes_vesting_position() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return true;

    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();

    (uint256 vest0, uint256 vest1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    (uint256 reported0, uint256 reported1) = strategy.balances();

    // The reported balances should at least cover the vesting position value.
    // The bug: they don't — vest0 and vest1 are silently excluded.
    if (vest0 > 0) {
        return t(
            reported0 >= vest0,
            "DDH-002: balances() understates token0 — vesting position omitted"
        );
    }
    if (vest1 > 0) {
        return t(
            reported1 >= vest1,
            "DDH-002: balances() understates token1 — vesting position omitted"
        );
    }
    return true;
}

/// @notice changePositionWidth should be restricted to the owner, not the
///         rebalancer. Property: if the caller is the rebalancer (not owner),
///         changePositionWidth must revert.
function property_only_owner_can_change_position_width() public returns (bool) {
    uint24 widthBefore = strategy.positionWidth();

    // Valid width that satisfies the divisibility check
    uint24 newWidth = uint24(uint24(strategy.tickSpacing()) * 8);

    // The rebalancer is NOT the owner — this call should revert
    vm.prank(rebalancer);
    try strategy.changePositionWidth(newWidth) {
        // If execution reaches here, rebalancer changed positionWidth — bug confirmed
        return t(
            strategy.positionWidth() == widthBefore,
            "DDH-003: rebalancer must not change positionWidth without owner approval"
        );
    } catch {
        // Correctly reverted
        return true;
    }
}

/// @notice positionWidth = 0 passes the divisibility check and causes
///         mainPosition.tickLower == mainPosition.tickUpper (zero-width), bricking mints.
function property_position_width_cannot_be_zero() public returns (bool) {
    return t(
        strategy.positionWidth() > 0,
        "DDH-003: positionWidth must be > 0 to ensure valid tick ranges"
    );
}

/// @notice checkPoolActivity() must not revert regardless of pool cardinality.
///         When cardinality == 1 the loop reads the same observation twice,
///         producing a zero time-delta and a division-by-zero panic.
function property_checkPoolActivity_never_reverts() public returns (bool) {
    (,, uint16 currentIndex, uint16 observationCardinality,,,) = pool.slot0();

    // Only interesting to test when cardinality is exactly 1
    if (observationCardinality != 1) return true;

    try strategy.checkPoolActivity() returns (bool) {
        return true; // did not revert — acceptable
    } catch {
        return t(false, "DDH-004: checkPoolActivity() reverted (div/0) for cardinality == 1");
    }
}

/// @notice After a rebalance, the secondary position must be Out-Of-Range
///         (either entirely above or entirely below current pool price).
///         For negative ticks, the missing modulo correction causes it to
///         straddle the current price instead.
function property_secondary_position_is_out_of_range() public returns (bool) {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return true;

    (, int24 currentTick,,,,,) = pool.slot0();

    // OOR above: tickLower >= currentTick (all token0)
    bool oorAbove = sp.tickLower >= currentTick;
    // OOR below: tickUpper <= currentTick (all token1)
    bool oorBelow = sp.tickUpper <= currentTick;

    return t(
        oorAbove || oorBelow,
        "DDH-005: secondary position is NOT out-of-range — spans current price due to missing negative-modulo fix"
    );
}

/// @notice The secondary position tick range must always be valid (tickLower < tickUpper).
///         With positionWidth = 2*tickSpacing and an !isLowerSided tick, tickLower
///         can equal tickUpper — an invalid Uniswap range that causes mint to revert.
function property_secondary_position_tick_range_valid() public returns (bool) {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();

    return t(
        sp.tickLower < sp.tickUpper,
        "DDH-006: secondary position has invalid tick range (tickLower >= tickUpper)"
    );
}

/// @notice The liquidity removed per collectFees() call should be proportional to
///         elapsed time out of REMAINING duration, not total duration.
///         Property: after each partial withdrawal, remainingLiquidity should
///         decrease by approximately (elapsed / remainingDuration) * remainingLiquidity.
///         Bug: it actually decreases by (elapsed / totalDuration) * initialLiquidity,
///         which differs once any previous vesting has occurred.
function property_vesting_removal_proportional_to_remaining() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    if (vpBefore.remainingLiquidity == 0) return true;
    if (vpBefore.endTs <= block.timestamp) return true; // final release handled separately
    if (vpBefore.lastUpdate == block.timestamp) return true; // same block guard

    uint256 elapsedSinceUpdate = block.timestamp - vpBefore.lastUpdate;
    uint256 remainingDuration  = vpBefore.endTs - vpBefore.lastUpdate;

    // Expected: proportional to remaining
    uint128 expectedRemoval = uint128(
        uint256(vpBefore.remainingLiquidity) * elapsedSinceUpdate / remainingDuration
    );
    // Actual (buggy): proportional to initial over total duration
    uint128 actualRemoval = uint128(
        uint256(vpBefore.initialLiquidity) * elapsedSinceUpdate / (vpBefore.endTs - vpBefore.startTs)
    );

    // They diverge once any prior vesting has occurred (remainingLiquidity < initialLiquidity)
    // and the denominator differs (remainingDuration != totalDuration).
    // Property: they must be equal (or within 1 for rounding) for correct linear vesting.
    uint128 diff = actualRemoval > expectedRemoval
        ? actualRemoval - expectedRemoval
        : expectedRemoval - actualRemoval;

    return t(
        diff <= 1,
        "DDH-007: vesting removal rate uses initialLiquidity/totalDuration instead of remainingLiquidity/remainingDuration"
    );
}

function property_deposit_amount_not_over_requested() public {
    (uint256 bal0, uint256 bal1) = _getVaultBalances();
    if (bal0 == 0 || bal1 == 0 || _getTotalSupply() == 0) return;

    uint256 requested0 = ONE_TOKEN0;
    uint256 requested1 = ONE_TOKEN1 * 80000; // approximate BTC price in USDC

    deal(address(token0), depositor, requested0);
    deal(address(token1), depositor, requested1);

    uint256 bal0Before = token0.balanceOf(depositor);
    uint256 bal1Before = token1.balanceOf(depositor);

    vm.startPrank(depositor);
    token0.approve(address(vault), requested0);
    token1.approve(address(vault), requested1);
    (, uint256 dep0, uint256 dep1) = vault.deposit(requested0, requested1, 0, 0);
    vm.stopPrank();

    // Deposited amounts should not exceed what was requested
    lte(dep0, requested0, "deposited token0 exceeds requested");
    lte(dep1, requested1, "deposited token1 exceeds requested");
}

function property_pullFunds_respects_freeze() public {
    // Freeze token0 reserve
    vm.prank(owner);
    lendingPool.freezeReserve(address(token0));

    uint256 yTokenBefore = token0.balanceOf(yToken0Addr);
    // leveragerActor attempts pullFunds on frozen reserve
    vm.prank(leveragerActor);
    try lendingPool.pullFunds(address(token0), 1e18) {
        // If pullFunds did NOT revert, check that no tokens left
        uint256 yTokenAfter = token0.balanceOf(yToken0Addr);
        t(yTokenAfter == yTokenBefore, "pullFunds drained frozen reserve");
    } catch {
        // pullFunds reverted — correct behavior
    }
}

function property_pullFunds_accounting_integrity() public {
    uint256 pullAmt = 100 * ONE_TOKEN0;

    // Record pre-pull state
    uint256 underlyingBalBefore = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 yTokenActualBefore  = token0.balanceOf(yToken0Addr);

    // leverager pulls funds
    vm.prank(leveragerActor);
    lendingPool.pullFunds(address(token0), pullAmt);

    // After pull: yToken actual balance should have decreased
    uint256 yTokenActualAfter = token0.balanceOf(yToken0Addr);
    t(yTokenActualAfter == yTokenActualBefore - pullAmt, "yToken balance should have decreased");

    // The pool's reported liquidity MUST also decrease proportionally
    // (because underlyingBalance should have been decremented)
    uint256 underlyingBalAfter = lendingPool.totalLiquidityOfReserve(address(token0));
    // If accounting is correct, totalLiquidity should decrease (or totalBorrows should increase)
    // Currently this property FAILS: underlyingBalAfter == underlyingBalBefore
    t(underlyingBalAfter < underlyingBalBefore, "pullFunds did not update accounting");
}

function property_pushFunds_accounting_integrity() public {
    uint256 pushAmt = 100 * ONE_TOKEN0;

    // Simulate: give leverager tokens, have them call pushFunds
    token0.mint(leveragerActor, pushAmt);
    vm.startPrank(leveragerActor);
    token0.approve(address(lendingPool), pushAmt);
    lendingPool.pushFunds(address(token0), pushAmt);
    vm.stopPrank();

    // After push: yToken actual balance increased
    uint256 yTokenActual = token0.balanceOf(yToken0Addr);

    // Pool's reported total liquidity should also have increased
    uint256 reportedLiquidity = lendingPool.totalLiquidityOfReserve(address(token0));

    // The yToken actual balance should equal underlyingBalance + any borrowed amount
    // If pushFunds doesn't update accounting, reportedLiquidity is stale (too low)
    // This property checks the invariant: yToken actual balance <= reported total liquidity
    // (it should be exactly equal when no borrows are outstanding)
    uint256 borrows = lendingPool.totalBorrowsOfReserve(address(token0));
    t(yTokenActual + borrows <= reportedLiquidity + 1, "pushFunds inflated real balance without updating accounting");
}

