function property_redeem_to_not_ytoken_contract() public {
    uint256 yBal = IERC20(yToken0Addr).balanceOf(user);
    if (yBal == 0) return;

    uint256 underlyingBefore = token0.balanceOf(yToken0Addr);

    // Redeem with to = yToken0Addr (the yToken contract itself)
    vm.startPrank(user);
    IERC20(yToken0Addr).approve(address(lendingPool), yBal);
    try lendingPool.redeem(address(token0), yBal, yToken0Addr) returns (uint256 got) {
        // If it succeeded, the yToken contract received underlying tokens
        // This creates an accounting mismatch
        uint256 underlyingAfter = token0.balanceOf(yToken0Addr);
        // The yToken contract's balance should NOT have increased
        // (tokens should have gone to a real recipient)
        t(underlyingAfter <= underlyingBefore, "redeem to yToken contract inflated its balance");
    } catch {}
    vm.stopPrank();
}

function property_ytoken_real_balance_matches_accounting() public {
    // This property checks the core solvency invariant BEFORE any pullFunds
    // to establish baseline
    uint256 realBalance   = token0.balanceOf(yToken0Addr);
    uint256 totalLiq      = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 totalBorrows  = lendingPool.totalBorrowsOfReserve(address(token0));

    // underlyingBalance = totalLiq - totalBorrows
    // real ERC20 balance of yToken should equal underlyingBalance (no pullFunds happened)
    uint256 accountedAvailable = totalLiq >= totalBorrows ? totalLiq - totalBorrows : 0;

    // allow 1 wei rounding tolerance
    t(
        realBalance <= accountedAvailable + 1 && realBalance + 1 >= accountedAvailable,
        "yToken real balance diverges from reserve accounting"
    );
}

