function property_liquidatable_when_overcollateralized() public {
    uint256 posId = _openWbtcPosition(user, 1e7, 10_000e6, 1e7, 50_000e6, 5e6);

    // Fast-forward time to accrue interest
    skip(365 days);

    ILeverager.Position memory pos = leverager.getPosition(posId);
    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(address(wbtc));
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;

    // If owed amount has grown, the position may be undercollateralized
    // but isLiquidateable might return false due to the base cap
    bool liquidatable = leverager.isLiquidateable(posId);

    // We can't assert the exact outcome without knowing exact interest,
    // but we verify the owed amount grew (interest accrued)
    t(owedAmount >= pos.borrowedAmount, "owed amount should be >= original borrow");

    // If owed > initCollateralValue * (maxTimesLeverage - 1e18) / 1e18,
    // the position should certainly be liquidatable
    (,, uint256 maxTimesLeverage,,,) = leverager.vaultParams(address(vault));
    uint256 threshold = pos.initCollateralValue * (maxTimesLeverage - 1e18) / 1e18;
    if (owedAmount > threshold) {
        t(liquidatable, "position should be liquidatable when owed exceeds threshold");
    }
}

