    vm.stopPrank();

    // Now try a partial withdraw — should NOT revert with underflow
    vm.startPrank(user);
    usdc.approve(address(leverager), type(uint256).max);
    wbtc.approve(address(leverager), type(uint256).max);
    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.5e18; // 50%

    bool success = true;
    try leverager.withdraw(wp) {
        // success
    } catch {
        success = false;
    }
    vm.stopPrank();

    // The withdraw should not revert; if it does, that indicates the bug
    t(success, "token1-denom withdraw should not revert");
}

function property_liquidation_fee_collected() public {
    // Seed a position
    uint256 posId;
    {
        deal(address(wbtc), user, 2e8);
        deal(address(usdc), user, 0);
        vm.startPrank(user);
        wbtc.approve(address(leverager), type(uint256).max);
        usdc.approve(address(leverager), type(uint256).max);

        ILeverager.LeverageParams memory lp;
        lp.amount0In = 2e8;
        lp.amount1In = 0;
        lp.vault0In = 2e8;
        lp.vault1In = 50_000e6;
        lp.vault = address(vault);
        lp.denomination = address(usdc);
        lp.maxBorrowAmount = 50_000e6;
        IMainnetRouter.ExactOutputParams memory ep;
        ep.path = abi.encodePacked(address(wbtc), uint24(3000), address(usdc));
        ep.deadline = block.timestamp + 3600;
        ep.amountInMaximum = type(uint256).max;
        ep.recipient = address(leverager);
        lp.swapParams1 = abi.encode(ep);

        try leverager.openLeveragedPosition(lp) returns (uint256 _id) {
            posId = _id;
        } catch {
            t(true, "skip open");
            return;
        }
        vm.stopPrank();
    }

    // Set owner-controlled liquidation fee > 0
    vm.prank(owner);
    leverager.setLiquidationFee(500); // 5%

    // Drop USDC price to make position liquidatable
    vm.prank(owner);
    wbtcOracle.setPrice(1000e18); // crash WBTC price

    // Verify it's now liquidatable
    if (!leverager.isLiquidateable(posId)) {
        t(true, "not liquidatable in this scenario");
        return;
    }

    address feeAddr = leverager.feeRecipient();
    uint256 feeBalBefore0 = wbtc.balanceOf(feeAddr);
    uint256 feeBalBefore1 = usdc.balanceOf(feeAddr);

    // Liquidate
    vm.startPrank(liquidator);
    deal(address(usdc), liquidator, 1_000_000e6);
    usdc.approve(address(leverager), type(uint256).max);
    ILeverager.LiquidateParams memory liqParams;
    liqParams.id = posId;
    try leverager.liquidatePosition(liqParams) {} catch {
        t(true, "liquidation reverted");
        return;
    }
    vm.stopPrank();

    // If liquidationFee > 0 and there was profit, feeRecipient should have received tokens
    uint256 feeBalAfter0 = wbtc.balanceOf(feeAddr);
    uint256 feeBalAfter1 = usdc.balanceOf(feeAddr);

    // Protocol should collect fees when liquidationFee is set and there's surplus
    // Due to the bug, this will fail (feeRecipient == address(0) and fee calc uses wrong decimals)
    t(feeBalAfter0 > feeBalBefore0 || feeBalAfter1 > feeBalBefore1, "protocol fee should be collected on profitable liquidation");
}

function property_borrow_amount_matches_actual_debt() public {
    // Attacker pre-seeds Leverager with USDC to distort borrowedAmount
    uint256 seedAmount = 1000e6; // 1000 USDC
    deal(address(usdc), attacker, seedAmount);
    vm.prank(attacker);
    usdc.transfer(address(leverager), seedAmount);

    // Now user opens a USDC-denominated position
    uint256 amount0In = 1e8;
    uint256 maxBorrow = 50_000e6;

    deal(address(wbtc), user, amount0In);
    vm.startPrank(user);
    wbtc.approve(address(leverager), type(uint256).max);
    usdc.approve(address(leverager), type(uint256).max);

    ILeverager.LeverageParams memory lp;
    lp.amount0In = amount0In;
    lp.amount1In = 0;
    lp.vault0In = amount0In;
    lp.vault1In = 51_000e6;
    lp.vault = address(vault);
    lp.denomination = address(usdc);
    lp.maxBorrowAmount = maxBorrow;
    IMainnetRouter.ExactOutputParams memory ep;
    ep.path = abi.encodePacked(address(wbtc), uint24(3000), address(usdc));
    ep.deadline = block.timestamp + 3600;
    ep.amountInMaximum = type(uint256).max;
    ep.recipient = address(leverager);
    lp.swapParams1 = abi.encode(ep);

    uint256 posId;
    try leverager.openLeveragedPosition(lp) returns (uint256 _id) {
        posId = _id;
    } catch {
        t(true, "skip");
        return;
    }
    vm.stopPrank();

    // The position's borrowedAmount should equal what was actually borrowed from lending pool
    // i.e. borrowedAmount should NOT be reduced by the attacker's seed
    ILeverager.Position memory pos = leverager.getPosition(posId);

    // Check: the recorded borrowed amount should be >= 0 (trivially true) and reflect real borrow
    // The lending pool's total borrows should match what was borrowed
    // If attacker's seed reduced borrowedAmount, the position is undercounting debt
    uint256 recordedBorrow = pos.borrowedAmount;

    // The seed reduces denomBalance, so borrowedAmount = maxBorrow - (swapLeftover + seedAmount)
    // Without the seed: borrowedAmount = maxBorrow - swapLeftover
    // Difference = seedAmount. This is the undercounted debt.
    // We verify borrowedAmount is within reasonable range of maxBorrow
    // (swap leftover should be small relative to the seed)
    t(recordedBorrow + seedAmount >= maxBorrow * 9 / 10, "borrowedAmount should reflect actual debt, not be reduced by attacker donation");
}

