function property_deposit_withdraw_no_profit_spot_manipulation() public {
    // Capture attacker balance before
    uint256 atkBal0Before = token0.balanceOf(attacker);
    uint256 atkBal1Before = token1.balanceOf(attacker);

    // Attacker deposits a small amount
    deal(address(token0), attacker, ONE_TOKEN0);
    deal(address(token1), attacker, ONE_TOKEN1 * 100_000);
    vm.startPrank(attacker);
    token0.approve(address(vault), type(uint256).max);
    token1.approve(address(vault), type(uint256).max);
    (uint256 shares,,) = vault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 100_000, 0, 0);
    vm.stopPrank();

    // Attacker withdraws immediately
    vm.prank(attacker);
    (uint256 w0, uint256 w1) = vault.withdraw(shares, 0, 0);

    uint256 atkBal0After = token0.balanceOf(attacker);
    uint256 atkBal1After = token1.balanceOf(attacker);

    // Attacker should not have more than they deposited (in combined spot value)
    // using spot price from vault
    uint256 spotPrice = vault.price(); // 1e30 precision, token1 per token0
    uint256 valueBefore = atkBal0Before * spotPrice / 1e30 + atkBal1Before;
    uint256 valueAfter  = atkBal0After  * spotPrice / 1e30 + atkBal1After;
    lte(valueAfter, valueBefore + valueBefore / 1000, "attacker profited from deposit/withdraw round-trip");
}

function property_secondary_position_uses_twap_not_spot() public {
    // After a rebalance, verify secondary position ticks make sense relative to TWAP tick
    // The secondary position should be OOR relative to main, not contradictory to TWAP direction
    uint256 twapP = vault.twapPrice();
    uint256 spotP = vault.price();
    // If they diverge by more than 5%, secondary position assignment may be wrong
    uint256 diff = twapP > spotP ? twapP - spotP : spotP - twapP;
    uint256 threshold = twapP / 20; // 5%
    t(diff <= threshold, "spot and TWAP price diverge: secondary position may be mis-set");
}

function property_pricefeed_staleness_is_checked() public {
    // This is a code-level check — the staleness guard is commented out in PriceFeed.sol
    // We verify the vault's TWAP price vs spot don't diverge absurdly
    // (proxy for whether the oracle system is functioning)
    uint256 twapP = vault.twapPrice();
    uint256 spotP = vault.price();
    uint256 ratio = twapP > spotP
        ? (twapP * 1e4) / spotP
        : (spotP * 1e4) / twapP;
    // Ratio should be within 10% of each other under normal conditions
    lte(ratio, 11000, "TWAP and spot price diverge more than 10% — oracle may be stale or manipulated");
}

function property_twap_window_sufficient() public {
    // TWAP should be long enough to prevent cheap manipulation
    // Minimum acceptable: 15 minutes (900 seconds) for a major pool
    uint32 twapInterval = strategy.twap();
