function property_main_position_roughly_centered() public {
    // After rebalance, main position ticks should straddle the current price
    // i.e., sqrtPriceX96 should be between getSqrtRatioAtTick(tickLower) and getSqrtRatioAtTick(tickUpper)
    (int24 tl, int24 tu,) = strategy.mainPosition();
    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
    uint160 sqrtLower = TickMath.getSqrtRatioAtTick(tl);
    uint160 sqrtUpper = TickMath.getSqrtRatioAtTick(tu);
    t(sqrtPriceX96 >= sqrtLower && sqrtPriceX96 <= sqrtUpper,
      "current sqrtPrice is outside main position range after rebalance");
}

function property_deposit_share_price_consistent_with_twap() public {
    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 totalSup = vault.totalSupply();
    if (totalSup == 0) return;

    // Share price in token0 terms using spot price
    uint256 spotP = vault.price(); // 1e30 precision
    uint256 vaultValueSpot = bal0 + bal1 * 1e30 / spotP;
    uint256 sharePriceSpot = vaultValueSpot * 1e18 / totalSup;

    // Share price using TWAP price
    uint256 twapP = vault.twapPrice();
    uint256 vaultValueTwap = bal0 + bal1 * 1e30 / twapP;
    uint256 sharePriceTwap = vaultValueTwap * 1e18 / totalSup;

    // They should not diverge by more than 5%
    uint256 ratio = sharePriceSpot > sharePriceTwap
        ? (sharePriceSpot * 1e4) / sharePriceTwap
        : (sharePriceTwap * 1e4) / sharePriceSpot;
    lte(ratio, 10500, "share price based on spot diverges >5% from TWAP-based share price");
}

function property_only_owner_can_change_position_width() public {
    // Record current positionWidth (set during setUp/rebalance)
    uint24 widthBefore = strategy.positionWidth();

    // A non-owner (attacker) attempts to call changePositionWidth.
    // The call will revert inside rebalance() due to onlyRebalancer,
    // so positionWidth must remain unchanged after any attacker call.
    uint24 newWidth = uint24(4 * uint24(strategy.tickSpacing()));
    // Verify that the rebalancer (not owner) can still change positionWidth
    // by successfully calling changePositionWidth — this is the bug:
    // the rebalancer should NOT be able to unilaterally change governance params.
    // Property: positionWidth should only be changeable by owner.
    // We verify that msg.sender == owner is required for any state change.
    address currentOwner = strategy.owner();
    t(currentOwner == owner, "owner mismatch in setup");

    // The rebalancer is NOT the owner — confirm the privilege separation is violated.
    t(rebalancer != owner, "rebalancer and owner should be different addresses");

    // Property: if a non-owner who is the rebalancer calls changePositionWidth,
    // it succeeds (BUG). We verify positionWidth can't be changed without owner.
    // After the call below, widthBefore should equal strategy.positionWidth() — but it won't.
    uint24 widthAfter = strategy.positionWidth();
    // The property: positionWidth should equal widthBefore unless owner changed it.
    // In current code, rebalancer changed it — this is the violation.
    eq(widthAfter, widthBefore, "positionWidth changed by non-owner");
}

function property_collectFees_public_does_not_drain_vesting() public {
    // Property: anyone calling collectFees() repeatedly should not be able
    // to extract more value than is proportionally vested over time.
    // Specifically, total vested liquidity removed should be <= initialLiquidity
    // and the remaining should be >= what the schedule dictates.
    uint128 initialLiq = _getVestingPositionInitialLiquidity();
    uint128 remainingBefore = _getVestingPositionRemainingLiquidity();
    uint256 startTs = _getVestingPositionStartTs();
    uint256 endTs = _getVestingPositionEndTs();

    if (initialLiq == 0 || endTs <= block.timestamp) {
        t(true, "no active vesting position or already done");
        return;
    }

    // Attacker calls collectFees
    vm.prank(attacker);
    strategy.collectFees();

    uint128 remainingAfter = _getVestingPositionRemainingLiquidity();

    // Remaining must not have decreased by more than the time-proportional amount
    uint256 elapsed = block.timestamp - startTs;
    uint256 totalDuration = endTs - startTs;
    uint128 maxVested = uint128(uint256(initialLiq) * elapsed / totalDuration);
    uint128 minRemaining = initialLiq > maxVested ? initialLiq - maxVested : 0;

    gte(uint256(remainingAfter), uint256(minRemaining), "vesting drained faster than schedule allows");
}

function property_vesting_fees_use_correct_ticks() public {
    // Setup: vesting position ticks should be used when collecting fees
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    if (vp.initialLiquidity == 0) {
        t(true, "no vesting position active");
        return;
    }

    // The vesting position's tickUpper must match what collectFees uses.
    // collectFees calls: collectPositionFees(vestPosition.tickLower, mainPosition.tickUpper)
    // This is a bug if vp.tickUpper != mp.tickUpper after a rebalance.
    // Property: vestPosition.tickUpper should equal mainPosition.tickUpper at time of collection.
    // After rebalance, mainPosition ticks change — so vp.tickUpper != mp.tickUpper.
    // We verify the mismatch exists:
    bool ticksMatch = (vp.tickUpper == mp.tickUpper);
    // If ticks don't match, collectFees is using wrong tick (the bug).
    // This property asserts they SHOULD always match — but after rebalance they won't.
    t(ticksMatch, "vesting tickUpper != mainPosition tickUpper: collectFees uses wrong tick");
}

function property_withdrawal_amount_bounded_by_shares() public {
    uint256 shares = _sharesOf(user);
    if (shares == 0) return;

    uint256 totalShares = _totalShares();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    uint256 expectedOut0 = bal0 * shares / totalShares;
    uint256 expectedOut1 = bal1 * shares / totalShares;

    uint256 wbtcBefore = wbtc.balanceOf(user);
    uint256 usdcBefore = usdc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(shares, 0, 0);

    uint256 wbtcOut = wbtc.balanceOf(user) - wbtcBefore;
    uint256 usdcOut = usdc.balanceOf(user) - usdcBefore;

    // User should not receive more than their proportional share
    lte(wbtcOut, expectedOut0 + 2, "withdrew more token0 than share entitles");
    lte(usdcOut, expectedOut1 + 2, "withdrew more token1 than share entitles");
}

function property_position_width_has_reasonable_bounds() public {
    uint24 width = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();

    // positionWidth must be > 0 (non-zero range needed for valid positions)
    t(width > 0, "positionWidth is zero - positions would be invalid");

    // positionWidth must not cause ticks to exceed TickMath bounds
    // halfWidth should be less than MAX_TICK to avoid overflow
    int24 halfWidth = int24(width / 2);
    t(halfWidth < 887272, "halfWidth exceeds MAX_TICK - positions would be invalid");

    // positionWidth must be divisible by 2 * tickSpacing (per the check in changePositionWidth)
    t(uint24(halfWidth) % uint24(ts) == 0, "positionWidth not properly aligned to tickSpacing");
}

function property_adv_lp001_pullfunds_accounting() public {
