function property_adv_lp009_total_liquidity_matches_physical() public {
    address asset = address(token0);
    address yTokAddr = yToken0Addr;

    // Physical tokens in yToken + physically-borrowed tokens (lent out via borrow())
    // must equal reported totalLiquidity.
    // Borrowed tokens physically left yToken, so physical = underlyingBalance.
    // totalLiquidity = underlyingBalance + borrowedLiquidity.
    // Physical balance of yToken = underlyingBalance (tokens still in yToken).
    // After pullFunds without accounting: physical < underlyingBalance.

    uint256 physicalBalance = IERC20(asset).balanceOf(yTokAddr);
    uint256 availLiq = _getAvailableLiquidity(asset);

    // Without any pullFunds, physicalBalance must equal availLiq
    // (all "available" liquidity is physically in the yToken contract)
    eq(physicalBalance, availLiq,
       "Physical yToken balance != reported availableLiquidity — accounting mismatch");
}

function property_adv_lp010_capacity_physical_consistency() public {
    address asset = address(token0);
    address yTokAddr = yToken0Addr;

    // Reserve capacity is max totalLiquidity.
    // Physical capacity should be tracked consistently.
    // After any operation, totalLiquidity must not exceed reserveCapacity.
    uint256 totalLiq = _getTotalLiquidity(asset);

    // reserveCapacity is type(uint256).max in setup, so just check totalLiq is sane
    uint256 physicalBal = IERC20(asset).balanceOf(yTokAddr);
    uint256 totalBorrows = _getTotalBorrows(asset);

    // totalLiquidity == physicalInYToken + borrowedOut
    uint256 expected = physicalBal + totalBorrows;
    eq(totalLiq, expected,
       "totalLiquidity != physicalBalance + totalBorrows — capacity accounting corrupted");
}

function property_collectFees_vesting_correct_ticks() public {
    // Setup: get the vesting position's upper tick
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If there is an ongoing vesting position AND main position has shifted,
    // the tickUpper used in collectFees must match vestPosition.tickUpper, not mainPosition.tickUpper
    if (strategy.ongoingVestingPosition()) {
        // After a rebalance, main position might have different ticks
        // The vesting position's tickUpper is captured at addVestingPosition time
        // collectFees uses mainPosition.tickUpper — if they differ, it's a bug
        // We detect the inconsistency by checking the stored fields
        // (In a real scenario we'd rebalance to shift ticks, then verify)
        t(vp.tickUpper == mp.tickUpper || !strategy.ongoingVestingPosition(),
          "VESTING BUG: collectFees uses mainPosition.tickUpper not vestPosition.tickUpper");
    }
}

function property_secondary_position_uses_twap_not_spot() public {
    // The spot price() and twapPrice() should be used for secondary position direction.
    // If they diverge significantly, secondary position direction may be wrong.
    uint256 spotP = strategy.price();
    uint256 twapP = strategy.twapPrice();

    // Allow 5% relative deviation as "within normal range"
    uint256 deviation;
    if (spotP > twapP) {
        deviation = (spotP - twapP) * 10000 / twapP;
    } else {
        deviation = (twapP - spotP) * 10000 / spotP;
    }

    // If spot deviates from TWAP, secondary position direction may be set incorrectly
    // This is informational — the bug is that spot is used instead of TWAP
    t(deviation < 500, "Spot vs TWAP divergence >5%: secondary position direction may be wrong");
}

function property_twap_minimum_window() public {
