}

function property_price_not_manipulable_spot() public {
    // price() uses slot0 sqrtPriceX96 (manipulable)
    // twapPrice() uses TWAP (not manipulable within one block)
    // These should be close; large divergence means spot is being manipulated
    uint256 spotP  = strategy.price();
    uint256 twapP  = strategy.twapPrice();

    uint256 ratio;
    if (spotP >= twapP) {
        ratio = (spotP - twapP) * 10000 / (twapP == 0 ? 1 : twapP);
    } else {
        ratio = (twapP - spotP) * 10000 / (twapP == 0 ? 1 : twapP);
    }
    // If divergence > 2% (200 bps), the spot-based secondary-position logic is unsafe
    lte(ratio, 200, "spot price diverges from TWAP >2%, secondary position direction manipulable");
}

function property_main_position_contains_current_price() public {
