    uint160 sqrtLower = TickMath.getSqrtRatioAtTick(mp.tickLower);
    uint160 sqrtUpper = TickMath.getSqrtRatioAtTick(mp.tickUpper);
    t(sqrtPriceX96 >= sqrtLower && sqrtPriceX96 <= sqrtUpper,
      "Current price outside main position range after rebalance");
}

