function property_balances_not_manipulable() public {
    // Spot-based balances() should not diverge significantly from TWAP-based valuation
    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 spotPrice  = strategy.price();
    uint256 twapPrice_ = strategy.twapPrice();

    // total value in token1 using spot vs TWAP
    uint256 totalSpot = bal0 * spotPrice / 1e30 + bal1;
    uint256 totalTwap = bal0 * twapPrice_ / 1e30 + bal1;

    // Allow 5% divergence
    uint256 diff;
    if (totalSpot > totalTwap) diff = (totalSpot - totalTwap) * 10000 / (totalTwap == 0 ? 1 : totalTwap);
    else diff = (totalTwap - totalSpot) * 10000 / (totalTwap == 0 ? 1 : totalTwap);

    lte(diff, 500, "balances() spot vs TWAP total value diverges >5%: share price manipulable");
}

function property_initial_positions_within_range() public {
    // Right after construction and first rebalance, main position should contain current price
    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
    IStrategy.Position memory mp = strategy.getMainPosition();
    uint160 sqrtLower = TickMath.getSqrtRatioAtTick(mp.tickLower);
    uint160 sqrtUpper = TickMath.getSqrtRatioAtTick(mp.tickUpper);
    t(sqrtPriceX96 >= sqrtLower && sqrtPriceX96 <= sqrtUpper,
      "main position does not contain current price");
}

function property_chainlink_staleness_check_exists() public {
    // This property documents that the staleness check is missing.
    // In PriceFeed._getChainlinkPrice, updatedAt is discarded and the heartbeat
    // check is commented out. We verify the consequence: the lending pool's
    // exchangeRate does not reflect any price-feed sanity.
    // Proxy test: after a deposit and borrow, the exchange rate must remain
    // >= PRECISION (1 underlying per yToken is the floor at initialization).
    uint256 rate0 = lendingPool.exchangeRateOfReserve(address(token0));
    uint256 rate1 = lendingPool.exchangeRateOfReserve(address(token1));
    gte(rate0, PRECISION, "token0 exchange rate below initial PRECISION");
    gte(rate1, PRECISION, "token1 exchange rate below initial PRECISION");
}

function property_borrow_repay_accounting() public {
    // After a full repay, totalBorrows should be zero and
    // totalLiquidity should equal underlyingBalance (no borrowed-out funds).
    uint256 borrowAmt = 100 * ONE_TOKEN0;
    _borrowAsLeverager(address(token0), borrowAmt);
    _repayAsLeverager(address(token0), borrowAmt);
    uint256 borrows = lendingPool.totalBorrowsOfReserve(address(token0));
    lte(borrows, 1, "total borrows should be ~0 after full repay");
}

function property_withdraw_repay_correctness() public {
    // Borrow token1, then repay — totalBorrows should not increase above initial
    uint256 initBorrows = lendingPool.totalBorrowsOfReserve(address(token1));
    uint256 borrowAmt = 50 * ONE_TOKEN1;
    _borrowAsLeverager(address(token1), borrowAmt);
    uint256 afterBorrow = lendingPool.totalBorrowsOfReserve(address(token1));
    gte(afterBorrow, initBorrows + borrowAmt - 1, "borrow should increase totalBorrows");
    _repayAsLeverager(address(token1), borrowAmt);
    uint256 afterRepay = lendingPool.totalBorrowsOfReserve(address(token1));
    lte(afterRepay, initBorrows + 1, "repay should restore totalBorrows");
}

function property_exchange_rate_monotonic_with_borrows() public {
    // Exchange rate should not decrease when interest accrues
    uint256 rateBefore = lendingPool.exchangeRateOfReserve(address(token0));
    uint256 borrowAmt = 100 * ONE_TOKEN0;
    _borrowAsLeverager(address(token0), borrowAmt);
    vm.warp(block.timestamp + 365 days);
    uint256 rateAfter = lendingPool.exchangeRateOfReserve(address(token0));
    gte(rateAfter, rateBefore, "exchange rate should not decrease when interest accrues");
}

function property_underlying_balance_matches_actual() public {
    // After a pullFunds + pushFunds round-trip, the yToken actual balance
    // should equal what the reserve thinks it has (underlyingBalance).
    uint256 pullAmt = 10 * ONE_TOKEN0;
    _pullFundsAsLeverager(address(token0), pullAmt);
    _pushFundsAsLeverager(address(token0), pullAmt);
    uint256 yTokenActualBal = token0.balanceOf(yToken0Addr);
    uint256 availLiq = lendingPool.totalLiquidityOfReserve(address(token0)) -
                       lendingPool.totalBorrowsOfReserve(address(token0));
    // The yToken actual balance should match available liquidity
    lte(yTokenActualBal, availLiq + 1, "yToken actual balance exceeds reserve availableLiquidity");
    gte(yTokenActualBal + 1, availLiq, "yToken actual balance below reserve availableLiquidity");
}

function property_total_liquidity_never_decreases_without_redeem() public {
    // Total liquidity should only decrease when users redeem (withdraw).
    // It should grow or stay flat from interest accrual.
    uint256 liquidityBefore = lendingPool.totalLiquidityOfReserve(address(token0));
    uint256 borrowAmt = 500 * ONE_TOKEN0;
    _borrowAsLeverager(address(token0), borrowAmt);
    vm.warp(block.timestamp + 30 days);
    // Trigger state update via a view that calls updateState path
    uint256 liquidityAfter = lendingPool.totalLiquidityOfReserve(address(token0));
    gte(liquidityAfter, liquidityBefore, "total liquidity decreased without redeem (interest leak)");
