    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();

    // Simulate a large swap moving spot price
    _swapUsdcForWbtc(10_000_000e6); // $10M USDC swap

    uint256 amt0 = ONE_TOKEN0;
    deal(address(token0), attacker, amt0);
    vm.startPrank(attacker);
    (uint256 shares,,) = vault.deposit(amt0, 0, 0, 0);
    vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    (uint256 bal0After, uint256 bal1After) = strategy.balances();

    // Vault balances should not decrease after a deposit+withdraw by attacker
    // (attacker should not profit from price manipulation)
    gte(bal0After + ONE_TOKEN0 / 100, bal0Before, "vault token0 drained by price manip");
    gte(bal1After, bal1Before - ONE_TOKEN1, "vault token1 drained by price manip");
}

function property_first_deposit_share_price_reasonable() public {
    // After the initial setup deposit (done in setUp), verify share price is reasonable
    uint256 supply = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    // Share price in token1 units: bal1 * supply / supply = bal1 per share conceptually
    // i.e., each share should represent roughly (bal1 / supply) units of token1
    // With 1 WBTC + 100000 USDC first deposit: supply ≈ 1e11, bal1 ≈ 1e11
    // So price per share ≈ 1 token1-wei, which is $0.000001 — very low precision for WBTC.
    // Check: at least 1e4 shares per unit of token0 at minimum (sanity check)
    // If supply < 1e6 and bal0 > 1e8, something is wrong with first deposit math.
    t(supply > 1000, "total supply too low after first deposit");
    // Check share price is not zero in token1 terms
    t(bal0 > 0 || bal1 > 0, "vault should not be empty after first deposit");
}

function property_withdraw_returns_fair_share() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 totalS = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    uint256 expectedAmount0 = bal0 * userShares / totalS;
    uint256 expectedAmount1 = bal1 * userShares / totalS;

    vm.prank(user);
    (uint256 out0, uint256 out1) = vault.withdraw(userShares, 0, 0);

    // The user should get at least 99% of their expected share (1% tolerance for price movement)
    gte(out0 * 100, expectedAmount0 * 99, "user got less than 99% of token0 share");
    gte(out1 * 100, expectedAmount1 * 99, "user got less than 99% of token1 share");
}

function property_vesting_position_fully_withdrawn_at_end() public {
    // After the vesting period ends, all liquidity should be removed
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    (,, uint128 initLiq, uint128 remainLiq, uint256 startTs, uint256 endTs, uint256 lastUpdate)
        = strategy.vestPosition();

    // If we are past endTs, calling collectFees should fully vest and end it
    if (block.timestamp >= endTs) {
        strategy.collectFees();
        bool stillOngoing = strategy.ongoingVestingPosition();
        t(!stillOngoing, "vesting position should be cleared after endTs");
    }
}

