    t(fee == 0, "deposit fee is non-zero: tokens transferred but shares reduced");
}

function property_single_token_deposit_credited_correctly() public {
    // When vault has only token1 (bal0==0 branch), depositing token1 should give fair shares.
    // We test: shares received * bal1 / totalSupply >= amount1_deposited - 1 (rounding tolerance)

    // Simulate extreme price: push all liquidity to token1 side
    _swapWbtcForUsdc(10 * ONE_TOKEN0); // large WBTC->USDC swap

    (uint256 bal0, uint256 bal1) = strategy.balances();
    if (bal0 != 0) return; // only test if we achieved bal0==0 state

    uint256 amt1 = ONE_TOKEN1 * 10000;
