    vm.startPrank(attacker);
    try vault.deposit(amt0, amt1, 0, 0) returns (uint256, uint256, uint256) {
        // success is fine
    } catch Error(string memory reason) {
        // revert with reason is fine (slippage etc.)
    } catch {
