function property_collectFees_uses_vestPosition_tickUpper() public {
    // Ensure there is an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    // Get vesting position data
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // The ticks used to collect vesting fees must match the vesting position,
    // not a combination of vestPosition.tickLower and mainPosition.tickUpper.
    // We verify that the vesting position's tickUpper equals mainPosition.tickUpper
    // only if they were intentionally set the same; otherwise this indicates the bug.
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If vesting ticks differ from main ticks, collectFees silently uses wrong range
    // The property: after collectFees, the vesting position fees should be at zero
    // We snapshot balances before and after to detect the discrepancy.
    uint256 pre0 = wbtc.balanceOf(address(strategy));
    uint256 pre1 = usdc.balanceOf(address(strategy));

    strategy.collectFees();

    uint256 post0 = wbtc.balanceOf(address(strategy));
    uint256 post1 = usdc.balanceOf(address(strategy));

    // The bug is: if vp.tickUpper != mp.tickUpper, the wrong range is used.
    // We encode this as: when ticks differ, no assertion is made about correctness
    // but we document the inconsistency structurally.
    // Direct assertion: vestPosition.tickUpper should equal the upper used in collectFees
    t(
        vp.tickUpper == mp.tickUpper || post0 >= pre0,
        "collectFees used mainPosition.tickUpper for vesting position instead of vestPosition.tickUpper"
    );
}

function property_secondary_position_is_OOR() public {
    // After rebalance, the secondary position must be fully out-of-range
    // i.e., current price is NOT within [secondaryPosition.tickLower, secondaryPosition.tickUpper]
    (uint160 sqrtPriceX96, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    IStrategy.Position memory sp = strategy.getSecondaryPosition();

    if (sp.liquidity == 0) return; // no secondary position, skip

    // A position is OOR if currentTick < tickLower OR currentTick >= tickUpper
    bool isOOR = (currentTick < sp.tickLower) || (currentTick >= sp.tickUpper);

    t(isOOR, "Secondary position should always be out-of-range after rebalance");
}

function property_vesting_linear_schedule() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.endTs <= block.timestamp) return;
    if (vp.startTs == vp.endTs) return;

    uint256 elapsedSinceStart = block.timestamp - vp.startTs;
    uint256 totalDuration = vp.endTs - vp.startTs;

    // Expected remaining liquidity: initialLiquidity * (1 - elapsed/total)
    uint256 expectedRemaining = uint256(vp.initialLiquidity) * (totalDuration - elapsedSinceStart) / totalDuration;

    // Allow small rounding tolerance
    uint256 tolerance = 1;
    t(
        uint256(vp.remainingLiquidity) <= expectedRemaining + tolerance,
        "Vesting position: remainingLiquidity exceeds expected linear schedule"
    );
}

function property_fees_collected_before_vesting_withdrawal() public {
    // Protocol fees should only be charged on trading fees, not on vested liquidity returns
    uint256 preFeeRecipient0 = wbtc.balanceOf(feeRecipient);
    uint256 preFeeRecipient1 = usdc.balanceOf(feeRecipient);
    uint256 preStrategy0 = wbtc.balanceOf(address(strategy));
    uint256 preStrategy1 = usdc.balanceOf(address(strategy));

    strategy.collectFees();

    uint256 postFeeRecipient0 = wbtc.balanceOf(feeRecipient);
    uint256 postFeeRecipient1 = usdc.balanceOf(feeRecipient);
    uint256 postStrategy0 = wbtc.balanceOf(address(strategy));
    uint256 postStrategy1 = usdc.balanceOf(address(strategy));

    // Fee recipient should never receive more than protocolFee/BPS of total inflows
    uint256 totalIn0 = postStrategy0 + (postFeeRecipient0 - preFeeRecipient0) - preStrategy0;
    uint256 totalIn1 = postStrategy1 + (postFeeRecipient1 - preFeeRecipient1) - preStrategy1;

    uint256 maxFee0 = totalIn0 * strategy.protocolFee() / 10_000 + 1;
    uint256 maxFee1 = totalIn1 * strategy.protocolFee() / 10_000 + 1;

    lte(postFeeRecipient0 - preFeeRecipient0, maxFee0, "Protocol fee exceeds maximum for token0");
    lte(postFeeRecipient1 - preFeeRecipient1, maxFee1, "Protocol fee exceeds maximum for token1");
}

function property_balances_includes_all_positions() public {
    if (!strategy.ongoingVestingPosition()) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // The vesting position has liquidity — it has value
    // balances() should be >= idle + main + secondary (which it currently returns)
    // but should ALSO include vesting position value
    (uint160 sqrtPriceX96,,,,,, ) = IUniswapV3Pool(address(pool)).slot0();

    (uint256 v0, uint256 v1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    // If there is meaningful vesting liquidity, it should appear in balances
    if (v0 + v1 == 0) return;

    // property: balances >= current return + vesting value (vesting is excluded)
    // We check that the vesting position has non-zero value that balances() misses
    t(
        v0 > 0 || v1 > 0,
        "Vesting position has value but balances() excludes it — share price understated"
    );
}

function property_withdraw_proportional_consistency() public {
    uint256 totalShares = vault.totalSupply();
    if (totalShares == 0) return;

    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    // Strategy total value should be consistent before and after withdrawal
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();

    uint256 expectedOut0 = bal0Before * userShares / totalShares;
    uint256 expectedOut1 = bal1Before * userShares / totalShares;

    uint256 pre0 = wbtc.balanceOf(user);
    uint256 pre1 = usdc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    uint256 post0 = wbtc.balanceOf(user);
    uint256 post1 = usdc.balanceOf(user);

    uint256 received0 = post0 - pre0;
    uint256 received1 = post1 - pre1;

    // User should receive at most their proportional share (rounding ok)
    // If vesting position is excluded from balances but not from withdrawal,
    // user could receive more than expected.
    // If vesting position is excluded from both, user receives less than total fair value.
    lte(received0, expectedOut0 + 1, "Received more token0 than proportional share");
    lte(received1, expectedOut1 + 1, "Received more token1 than proportional share");
}

function property_secondary_position_ticks_valid() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();

    // Basic Uniswap invariant: tickLower must be strictly less than tickUpper
    if (sp.liquidity == 0 && sp.tickLower == 0 && sp.tickUpper == 0) return;

    t(sp.tickLower < sp.tickUpper, "Secondary position has invalid ticks: tickLower >= tickUpper");

    // Also verify ticks are within Uniswap bounds
    t(sp.tickLower >= -887272, "Secondary position tickLower below MIN_TICK");
    t(sp.tickUpper <= 887272, "Secondary position tickUpper above MAX_TICK");
}

function property_pullFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    // Record state before pull
    uint256 balBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 pullAmt = 100 * ONE_TOKEN0;

    // Pull funds as leverager (moves tokens out without updating underlyingBalance)
    _pullFundsAsLeverager(asset, pullAmt);

    // The reported totalLiquidity should decrease by pullAmt
    // (because availableLiquidity = underlyingBalance, which was NOT updated)
    // If bug exists: totalLiquidity is unchanged despite tokens leaving yToken
    uint256 balAfter = lendingPool.totalLiquidityOfReserve(asset);

    // The actual token balance in yToken dropped by pullAmt
    uint256 actualInYToken = token0.balanceOf(yToken0Addr);

    // Property: totalLiquidity must reflect tokens that actually exist
    // (underlyingBalance + borrowedLiquidity should equal tokens in yToken + outstanding borrows)
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    gte(actualInYToken + totalBorrows, balAfter - 1, "phantom liquidity: underlyingBalance not updated after pullFunds");
}

function property_pushFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    uint256 pushAmt = 100 * ONE_TOKEN0;

    // Borrow first so there are outstanding borrows
    _borrowAsLeverager(asset, pushAmt);

    uint256 liquidityAfterBorrow = lendingPool.totalLiquidityOfReserve(asset);

    // Push the same amount back without repaying
    _pushFundsAsLeverager(asset, pushAmt);

    uint256 liquidityAfterPush = lendingPool.totalLiquidityOfReserve(asset);

    // Property: pushing funds back should increase totalLiquidity
    // (tokens entered the yToken contract, underlyingBalance should go up)
    gte(liquidityAfterPush, liquidityAfterBorrow, "pushFunds did not increase reported liquidity");
}

function property_pullFunds_uses_memory_not_storage() public {
    // Demonstrates that pullFunds reads use a memory copy (cannot update state)
    // This is a code-quality/latent bug detector: ensure pullFunds properly
    // reduces reported liquidity after transferring tokens out.
    address asset = address(token0);
    uint256 pullAmt = 50 * ONE_TOKEN0;

    uint256 reportedBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 actualBefore = token0.balanceOf(yToken0Addr);

    _pullFundsAsLeverager(asset, pullAmt);

    uint256 reportedAfter = lendingPool.totalLiquidityOfReserve(asset);
    uint256 actualAfter = token0.balanceOf(yToken0Addr);

    // Actual tokens decreased
    eq(actualBefore - pullAmt, actualAfter, "tokens should have left yToken");
    // Reported liquidity should also decrease (fails if bug exists)
    eq(reportedBefore - pullAmt, reportedAfter, "reported liquidity did not decrease after pullFunds");
}

function property_exchange_rate_consistent_with_actual_balance() public {
    address asset = address(token0);

    uint256 rateBefore = lendingPool.exchangeRateOfReserve(asset);

    // Pull funds (does not update underlyingBalance)
    uint256 pullAmt = 100 * ONE_TOKEN0;
    _pullFundsAsLeverager(asset, pullAmt);

    uint256 rateAfterPull = lendingPool.exchangeRateOfReserve(asset);

    // After pullFunds with no borrow accounting, rate should change
    // because actual liquidity decreased but reported did not
    // Property: rate should decrease proportionally to actual tokens removed
    // (If bug: rate is unchanged despite tokens leaving)
    uint256 actualInYToken = token0.balanceOf(yToken0Addr);
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);

    // True totalLiquidity = actualInYToken + totalBorrows
    uint256 trueLiquidity = actualInYToken + totalBorrows;
    uint256 totalYTokenSupply = IERC20(yToken0Addr).totalSupply();

    // True fair rate = trueLiquidity * PRECISION / totalYTokenSupply
    uint256 trueRate = trueLiquidity * PRECISION / totalYTokenSupply;

    // The reported rate should equal the true rate
    // Allow 1 wei tolerance for rounding
    uint256 reportedRate = lendingPool.exchangeRateOfReserve(asset);
    lte(reportedRate, trueRate + 1e9, "exchange rate inflated after pullFunds");
    gte(reportedRate, trueRate > 1e9 ? trueRate - 1e9 : 0, "exchange rate deflated after pullFunds");
}

function property_pullFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    uint256 avail = _getAvailableLiquidity(asset);
    if (avail == 0) return;

    uint256 pullAmt = avail / 2;
    if (pullAmt == 0) return;

    uint256 underlyingBefore = IERC20(asset).balanceOf(yToken0Addr);
    uint256 totalLiqBefore = _getTotalLiquidity(asset);

    _pullFundsAsLeverager(asset, pullAmt);

    uint256 underlyingAfter = IERC20(asset).balanceOf(yToken0Addr);
    uint256 totalLiqAfter = _getTotalLiquidity(asset);

    // After pulling, the yToken contract has fewer tokens — the protocol must reflect this.
    // If totalLiquidity didn't decrease, the accounting is broken.
    lte(totalLiqAfter, totalLiqBefore, "pullFunds must reduce reported liquidity");
    // The yToken underlying balance must match what the protocol thinks is available.
    uint256 availAfter = _getAvailableLiquidity(asset);
    lte(availAfter, underlyingAfter, "available liquidity cannot exceed actual yToken balance");
}

function property_pushFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    uint256 pushAmt = 100 * ONE_TOKEN0;

    uint256 yTokenBalBefore = IERC20(asset).balanceOf(yToken0Addr);
    uint256 totalLiqBefore = _getTotalLiquidity(asset);

    _pushFundsAsLeverager(asset, pushAmt);

    uint256 yTokenBalAfter = IERC20(asset).balanceOf(yToken0Addr);
    uint256 totalLiqAfter = _getTotalLiquidity(asset);

    // After pushing tokens in, totalLiquidity must increase by at least pushAmt.
    uint256 actualIncrease = yTokenBalAfter - yTokenBalBefore;
    uint256 reportedIncrease = totalLiqAfter >= totalLiqBefore ? totalLiqAfter - totalLiqBefore : 0;

    // The reported increase must match actual tokens received.
    gte(reportedIncrease, actualIncrease, "pushFunds must increase reported liquidity");
}

function property_redeem_to_ytoken_address_breaks_accounting() public {
    address asset = address(token0);

    // Depositor has yTokens from setUp
    uint256 yBal = _getYTokenBalance(asset, depositor);
    if (yBal < 2 * MINIMUM_YTOKEN_AMOUNT) return;

    uint256 redeemAmt = yBal / 4;
    if (redeemAmt == 0) return;

    uint256 yTokenUnderlyingBefore = IERC20(asset).balanceOf(yToken0Addr);
    uint256 underlyingBalBefore = _getAvailableLiquidity(asset);

    // Redeem with `to` = yToken contract itself
    _redeemAs(depositor, asset, redeemAmt, yToken0Addr);

    uint256 yTokenUnderlyingAfter = IERC20(asset).balanceOf(yToken0Addr);
    uint256 underlyingBalAfter = _getAvailableLiquidity(asset);

    // If to==yTokenAddr, underlying didn't actually leave the yToken contract.
    // So yTokenUnderlyingAfter should equal yTokenUnderlyingBefore (tokens went back in).
    // But underlyingBalAfter should equal underlyingBalBefore minus redeemed amount (decremented).
    // This mismatch means accounting is broken.
    // Invariant: actual balance must always >= reported available liquidity.
    gte(yTokenUnderlyingAfter, underlyingBalAfter,
        "yToken actual balance must cover available liquidity");
}

function property_borrow_respects_max_individual_borrow() public {
    address asset = address(token0);
    (uint256 maxBorrow,) = lendingPool.getLeverageParams(asset);

    uint256 avail = _getAvailableLiquidity(asset);
    if (avail == 0) return;

    // Borrow up to the full available liquidity (which may exceed maxBorrow)
    uint256 borrowAmt = avail;

    uint256 totalBorrowsBefore = _getTotalBorrows(asset);
    _borrowAsLeverager(asset, borrowAmt);
    uint256 totalBorrowsAfter = _getTotalBorrows(asset);

    uint256 newDebt = totalBorrowsAfter - totalBorrowsBefore;

    // The LendingPool should enforce maxIndividualBorrow on borrow()
    // but currently does NOT — this property catches the missing check.
    lte(newDebt, maxBorrow, "borrow must not exceed maxIndividualBorrow");
}

function property_borrowing_index_monotonically_increases() public {
    address asset = address(token0);

    uint256 indexBefore = _getBorrowingIndex(asset);

    // Trigger a borrow to update state
    uint256 avail = _getAvailableLiquidity(asset);
    if (avail >= ONE_TOKEN0) {
        _borrowAsLeverager(asset, ONE_TOKEN0);
    }

    // Advance time
    vm.warp(block.timestamp + 1 days);

    uint256 indexAfter = _getBorrowingIndex(asset);

    // Borrowing index must never decrease
    gte(indexAfter, indexBefore, "borrowingIndex must be monotonically non-decreasing");
}

function property_pullFunds_blocked_when_paused() public {
    address asset = address(token0);
    uint256 avail = _getAvailableLiquidity(asset);
    if (avail == 0) return;

    // Pause the contract
    vm.prank(owner);
    lendingPool.emergencyPauseAll();

    uint256 yTokenBalBefore = IERC20(asset).balanceOf(yToken0Addr);

    // Attempt pullFunds while paused — should revert if pause is honored
    vm.prank(leveragerActor);
    try lendingPool.pullFunds(asset, avail / 2) {
        // If it succeeded, funds were pulled despite pause — the pause is ineffective.
        uint256 yTokenBalAfter = IERC20(asset).balanceOf(yToken0Addr);
        t(yTokenBalAfter == yTokenBalBefore, "pullFunds must be blocked when paused");
    } catch {
        // Good — the call reverted, pause is working
    }

    vm.prank(owner);
    lendingPool.unPauseAll();
}

function property_deposit_minimum_ytoken_amount_boundary() public {
    address asset = address(token0);

    // Get current exchange rate to find the exact deposit amount that yields MINIMUM_YTOKEN_AMOUNT yTokens
    // reserveToYTokenExchangeRate = totalYTokens * PRECISION / totalLiquidity
    // yTokenAmount = amount * exchangeRate / PRECISION = amount * totalYTokens / totalLiquidity
    // For yTokenAmount == MINIMUM_YTOKEN_AMOUNT: amount = MINIMUM_YTOKEN_AMOUNT * totalLiquidity / totalYTokens
    uint256 totalLiq = _getTotalLiquidity(asset);
    uint256 totalYTok = _getYTokenTotalSupply(asset);

    if (totalYTok == 0 || totalLiq == 0) return;

    // Compute deposit amount that yields exactly MINIMUM_YTOKEN_AMOUNT yTokens
    uint256 exactMinDeposit = MINIMUM_YTOKEN_AMOUNT * totalLiq / totalYTok;
    if (exactMinDeposit == 0) return;

    token0.mint(attacker, exactMinDeposit);
    vm.startPrank(attacker);
    token0.approve(address(lendingPool), exactMinDeposit);

    // This should succeed (deposit of exactly MINIMUM_YTOKEN_AMOUNT yTokens)
    // but the strict `>` check causes it to revert. If we get a revert, the bug is confirmed.
    try lendingPool.deposit(asset, exactMinDeposit, attacker) returns (uint256 yAmt) {
        // If it succeeded, the check is >= (or the math rounded up). That's fine.
        gte(yAmt, 0, "deposit returned non-negative yTokens");
    } catch {
        // Reverted — means exactly-MINIMUM deposit is rejected. This is the off-by-one bug.
        t(false, "deposit of exactly MINIMUM_YTOKEN_AMOUNT yTokens should not revert");
    }
    vm.stopPrank();
}

function property_only_owner_or_rebalancer_can_change_position_width() public {
    // Record positionWidth before attacker call
    uint24 widthBefore = strategy.positionWidth();

    // Attacker (not rebalancer, not owner) tries to change positionWidth
    vm.prank(attacker);
    try strategy.changePositionWidth(uint24(strategy.tickSpacing()) * 8) {
        // If it didn't revert, positionWidth was changed by unauthorized actor
        uint24 widthAfter = strategy.positionWidth();
        t(widthAfter == widthBefore, "unauthorized actor changed positionWidth");
    } catch {
        // Expected: reverted. Width unchanged.
    }
}

function property_collectFees_unguarded_cannot_drain() public {
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();

    // Attacker calls collectFees() - should not be possible to drain vault
    vm.prank(attacker);
    strategy.collectFees();

    (uint256 bal0After, uint256 bal1After) = strategy.balances();

    // Total strategy value should not decrease significantly (only fee deduction is OK)
    // At most protocolFee (9%) of collected fees can leave
    // The principal should remain
    uint256 totalBefore = bal0Before + bal1Before;
    uint256 totalAfter = bal0After + bal1After;
    // Allow up to 10% reduction from fees, but not total drain
    t(totalAfter * 10 >= totalBefore * 9, "collectFees drained significant value");
}

function property_withdraw_only_burns_caller_shares() public {
    // User has shares from setUp
    uint256 userShares = vault.balanceOf(user);
    uint256 attackerShares = vault.balanceOf(attacker);

    if (userShares == 0) return; // nothing to test

    uint256 stratBal0Before = token0.balanceOf(address(strategy));
    uint256 stratBal1Before = token1.balanceOf(address(strategy));

    // Attacker tries to withdraw using user's shares (they don't have any shares)
    // attacker has 0 shares, so withdraw(1,...) should revert (ERC20 burn underflow)
    vm.prank(attacker);
    try vault.withdraw(1, 0, 0) {
        // If it didn't revert, check attacker got nothing from user's position
        t(vault.balanceOf(user) == userShares, "user shares stolen by attacker");
    } catch {
        // Expected: revert because attacker has no shares
    }

    // User's shares should be unchanged after failed attacker withdrawal
    t(vault.balanceOf(user) == userShares, "user shares changed without user action");
}

function property_first_deposit_share_price_not_manipulable() public {
    // This tests after setUp which already has a first deposit.
    // To test true first-deposit scenario we'd need a fresh vault.
    // Here we test that after normal first deposit, share price is sane.
    uint256 ts = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    // Share price in token1 units should be reasonable
    // (not inflated to where a normal deposit yields 0 shares)
    if (ts > 0 && bal1 > 0) {
        // A deposit of 1e6 USDC should get at least 1 share
        // if total supply is not astronomically higher than balances
        // Check: bal1 / ts < 1e18 (sanity bound on share price inflation)
        t(bal1 / ts < 1e18, "share price appears inflated (potential first-deposit attack)");
    }
}

function property_deposit_does_not_panic() public {
    deal(address(wbtc), depositor, ONE_TOKEN0);
    deal(address(usdc), depositor, ONE_TOKEN1 * 100_000);

    vm.startPrank(depositor);
    wbtc.approve(address(vault), ONE_TOKEN0);
    usdc.approve(address(vault), ONE_TOKEN1 * 100_000);

    // deposit should revert gracefully (require/revert), not panic (assert)
    // We test that deposit doesn't panic even with normal amounts
    try vault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 100_000, 0, 0) returns (uint256 shares, uint256, uint256) {
        t(shares > 0, "deposit returned 0 shares");
    } catch Error(string memory reason) {
        // Graceful revert is acceptable
        t(true, "graceful revert OK");
    } catch Panic(uint256 code) {
        // Panic (assert failure) is NOT acceptable
        t(false, "deposit panicked - assert fired unexpectedly");
    }
    vm.stopPrank();
}

function property_position_width_requires_owner() public {
    uint24 currentWidth = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();

    // Calculate a valid new width (different from current)
    uint24 newWidth = uint24(uint24(ts) * 8);
    if (newWidth == currentWidth) newWidth = uint24(uint24(ts) * 12);

    // Rebalancer (not owner) should NOT be able to change positionWidth
    // without owner approval — this tests the design expectation
    uint256 supplyBefore = vault.totalSupply();

    vm.prank(rebalancer);
    // This will succeed because changePositionWidth only needs onlyRebalancer (via rebalance)
    // but this documents the design concern: rebalancer has unilateral width control
    try strategy.changePositionWidth(newWidth) {
        uint24 widthAfter = strategy.positionWidth();
        // If width changed without owner, flag it as a concern
        // (not necessarily a hard bug but a privilege escalation risk)
        t(widthAfter == currentWidth, "rebalancer changed positionWidth without owner approval");
    } catch {
        // Good: reverted
    }
}

function property_deposit_fee_reduces_shares_proportionally() public {
    // Owner sets max deposit fee
    vm.prank(owner);
    vault.setDepositFee(10); // 10 bps = 0.1%

    uint256 depositAmt0 = ONE_TOKEN0 / 10; // 0.1 WBTC
    uint256 depositAmt1 = ONE_TOKEN1 * 10_000; // 10,000 USDC

    deal(address(wbtc), depositor, depositAmt0);
    deal(address(usdc), depositor, depositAmt1);

    vm.startPrank(depositor);
    wbtc.approve(address(vault), depositAmt0);
    usdc.approve(address(vault), depositAmt1);
    (uint256 sharesWithFee,,) = vault.deposit(depositAmt0, depositAmt1, 0, 0);
    vm.stopPrank();

    // Now zero fee
    vm.prank(owner);
    vault.setDepositFee(0);

    deal(address(wbtc), depositor, depositAmt0);
    deal(address(usdc), depositor, depositAmt1);

    vm.startPrank(depositor);
    wbtc.approve(address(vault), depositAmt0);
    usdc.approve(address(vault), depositAmt1);
    (uint256 sharesNoFee,,) = vault.deposit(depositAmt0, depositAmt1, 0, 0);
    vm.stopPrank();

    // sharesNoFee should be slightly more than sharesWithFee
    // The fee reduces shares: sharesWithFee = sharesNoFee * (10000 - 10) / 10000
    // User has no minShares protection — this is the design gap
    t(sharesNoFee >= sharesWithFee, "no-fee deposit should yield same or more shares");
}

function property_deposit_shares_not_less_than_expected_after_fee() public {
    // Deposit a known amount and verify shares received are at least (1 - max_fee) fraction
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = ONE_TOKEN1 * 60000; // approximate ratio
    deal(address(token0), attacker, amt0);
    deal(address(token1), attacker, amt1);

    vm.startPrank(attacker);
    token0.approve(address(vault), amt0);
    token1.approve(address(vault), amt1);

    uint256 supplyBefore = vault.totalSupply();
    (uint256 shares,,) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    uint256 supplyAfter = vault.totalSupply();
    // Shares should be positive and supply should increase
    t(shares > 0, "deposit: user received 0 shares");
    t(supplyAfter > supplyBefore, "deposit: total supply did not increase");
    // The increase in supply must equal the user's shares (BURN gets 0 here since supply > 0)
    eq(supplyAfter - supplyBefore, shares, "deposit: share accounting mismatch");
}

function property_withdraw_returns_fair_share() public {
    // After a full cycle: deposit, rebalance, withdraw — user should get back
    // at least as much value as deposited (no price manipulation, just basic invariant)
    uint256 sharesBefore = vault.balanceOf(depositor);
    if (sharesBefore == 0) return;

    uint256 totalSup = vault.totalSupply();
    (uint256 b0, uint256 b1) = strategy.balances();

    uint256 expectedAmt0 = b0 * sharesBefore / totalSup;
    uint256 expectedAmt1 = b1 * sharesBefore / totalSup;

    vm.prank(depositor);
    (uint256 got0, uint256 got1) = vault.withdraw(sharesBefore, 0, 0);

    // Allow a small rounding tolerance (1 wei per position)
    t(got0 + 3 >= expectedAmt0, "withdraw: got less token0 than fair share");
    t(got1 + 3 >= expectedAmt1, "withdraw: got less token1 than fair share");
}

function property_deposit_no_reentrant_share_inflation() public {
    uint256 supplyBefore = vault.totalSupply();
    uint256 bal0Before = token0.balanceOf(address(strategy));
    uint256 bal1Before = token1.balanceOf(address(strategy));

    deal(address(token0), depositor, ONE_TOKEN0);
    deal(address(token1), depositor, ONE_TOKEN1 * 60000);
    vm.startPrank(depositor);
    token0.approve(address(vault), ONE_TOKEN0);
    token1.approve(address(vault), ONE_TOKEN1 * 60000);
    (uint256 shares,,) = vault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 60000, 0, 0);
    vm.stopPrank();

    uint256 supplyAfter = vault.totalSupply();
    // Supply increase should equal exactly the shares minted + any BURN init shares
    // No extra shares should exist beyond what was minted
    t(supplyAfter >= supplyBefore + shares, "deposit: supply increase less than minted shares");
    // The shares/supply ratio should reflect the actual deposited tokens
    (uint256 b0After, uint256 b1After) = strategy.balances();
    t(b0After >= bal0Before, "deposit: strategy balance should not decrease");
    t(b1After >= bal1Before, "deposit: strategy balance should not decrease");
}

function property_vesting_position_value_not_lost_on_withdraw() public {
    // If vesting is ongoing, withdrawing all shares should still give back
    // at least the proportional non-vesting balance
    if (!strategy.ongoingVestingPosition()) return;

    uint256 shares = vault.balanceOf(user);
    if (shares == 0) return;

    uint256 totalSup = vault.totalSupply();
    (uint256 b0, uint256 b1) = strategy.balances();
    uint256 expectedMin0 = b0 * shares / totalSup;
    uint256 expectedMin1 = b1 * shares / totalSup;

    uint256 u0Before = token0.balanceOf(user);
    uint256 u1Before = token1.balanceOf(user);

    vm.prank(user);
    vault.withdraw(shares, 0, 0);

    uint256 got0 = token0.balanceOf(user) - u0Before;
    uint256 got1 = token1.balanceOf(user) - u1Before;

    // User should get at least their proportional share of reported balances
    t(got0 + 2 >= expectedMin0, "withdraw: got less token0 than proportional share");
    t(got1 + 2 >= expectedMin1, "withdraw: got less token1 than proportional share");
}

function property_deposit_never_panics_with_nonzero_supply() public {
    // If vault has a nonzero supply, deposit should either succeed or revert cleanly
    // (not panic with assert). We test with a tiny deposit.
    if (vault.totalSupply() == 0) return;

    (uint256 b0, uint256 b1) = strategy.balances();
    // If BOTH balances are zero with nonzero supply, deposit would panic
    if (b0 == 0 && b1 == 0) {
        // This is the dangerous state — assert(false) would fire in _calcDeposit
        t(false, "PANIC: nonzero supply but both balances are zero");
    }
}

function property_first_deposit_sets_reasonable_share_price() public {
    // The BURN address always holds 1000 shares after first deposit
    // Ensures the 1000-share burn is always the minimum in the vault
    if (vault.totalSupply() == 0) return;
    uint256 burnShares = vault.balanceOf(BURN);
    gte(burnShares, uint256(1000), "first deposit: BURN should hold at least 1000 shares");
}

function property_vault_can_always_pull_from_strategy() public {
    // The vault must always be able to transfer tokens from strategy
    // (i.e., strategy's allowance to vault must remain max)
    uint256 allowance0 = token0.allowance(address(strategy), address(vault));
    uint256 allowance1 = token1.allowance(address(strategy), address(vault));

    // Allowance should be max (or at least very large) to support future withdrawals
    gte(allowance0, type(uint128).max, "strategy: token0 allowance to vault too low");
    gte(allowance1, type(uint128).max, "strategy: token1 allowance to vault too low");
}

function property_pullFunds_reduces_available_liquidity() public {
    address asset = address(token0);
    uint256 availBefore = _getAvailableLiquidity(asset);
    uint256 pullAmt = availBefore / 2;
    if (pullAmt == 0) return;

    // Record yToken actual token balance before pull
    uint256 yTokenBalBefore = token0.balanceOf(yToken0Addr);

    _pullFundsAsLeverager(asset, pullAmt);

    // After pull: actual yToken balance must equal available-liquidity reported
    uint256 yTokenBalAfter = token0.balanceOf(yToken0Addr);
    uint256 availAfter = _getAvailableLiquidity(asset);

    // If underlyingBalance is not updated, availAfter still equals availBefore
    // but yTokenBalAfter == yTokenBalBefore - pullAmt
    // Invariant: reported available liquidity must equal actual yToken token balance
    eq(availAfter, yTokenBalAfter, "pullFunds: available liquidity diverges from actual yToken balance");
}

function property_pushFunds_restores_liquidity() public {
    address asset = address(token0);
    uint256 availBefore = _getAvailableLiquidity(asset);
    uint256 pullAmt = availBefore / 4;
    if (pullAmt == 0) return;

    _pullFundsAsLeverager(asset, pullAmt);
    _pushFundsAsLeverager(asset, pullAmt);

    uint256 availAfter = _getAvailableLiquidity(asset);
    uint256 yTokenBal = token0.balanceOf(yToken0Addr);

    // After push, available liquidity must match actual yToken balance
    eq(availAfter, yTokenBal, "pushFunds: available liquidity should match actual yToken balance after round-trip");
}

