description:
In _deposit (LendingPool.sol lines 118-126):
  yTokenAmount = amount * exchangeRate / PRECISION
  require(yTokenAmount > MINIMUM_YTOKEN_AMOUNT, "deposit is dust amount")
  if (totalSupply == 0) {
      mint(DEAD_ADDRESS, MINIMUM_YTOKEN_AMOUNT);
      yTokenAmount -= MINIMUM_YTOKEN_AMOUNT;
  }

The dust check uses strict greater-than (>), so `yTokenAmount = 1001` passes (1001 > 1000) and the depositor receives 1001 - 1000 = 1 yToken.
However, there is a subtle asymmetry in how the exchange rate is computed: - At first deposit, totalYTokens == 0 || totalLiquidity == 0 → rate = PRECISION - So yTokenAmount = amount * PRECISION / PRECISION = amount
For a 6-decimal token, the attacker needs to deposit 1001 wei ($0.001001). They receive 1 yToken, while 1000 yTokens are burned to DEAD_ADDRESS. The pool now has 1001 underlying tokens and 1001 total yTokens.
The share price is 1001/1001 = 1, so subsequent depositors get fair rates. The inflation attack is blocked because: to manipulate the exchange rate via donation, the attacker would need to donate to yToken directly, but `underlyingBalance` is tracked separately and direct token donations do NOT affect the exchange rate. This means the classic ERC4626 inflation attack is NOT possible here.
This is a correct protection — the finding confirms the defense works.

solidity:
function property_inflation_attack_impossible() public {
    address asset = address(token1); // 6-decimal token

    // Attempt inflation attack: deposit minimum, then donate large amount
    uint256 minDeposit = 1001; // just above MINIMUM_YTOKEN_AMOUNT
    token1.mint(attacker, minDeposit + 10_000 * ONE_TOKEN1);

    vm.startPrank(attacker);
    token1.approve(address(lendingPool), type(uint256).max);
    // This will fail on first reserve since it's already initialized in setUp
    // We test with existing reserve that already has deposits
    vm.stopPrank();

    // Second depositor's exchange rate should not be manipulable via donation
    uint256 rateBefore = lendingPool.exchangeRateOfReserve(asset);

    // Attacker donates tokens directly to yToken contract (does NOT go through deposit)
    vm.prank(attacker);
    token1.transfer(yToken1Addr, 10_000 * ONE_TOKEN1);

    uint256 rateAfter = lendingPool.exchangeRateOfReserve(asset);

    // Exchange rate should be unchanged because underlyingBalance is internal accounting
    eq(rateAfter, rateBefore, "direct donation should not change exchange rate");
}

function property_underlyingBalance_matches_realBalance() public {
    address asset = address(token0);

    // Get the reported available liquidity
    uint256 reportedLiquidity = lendingPool.totalLiquidityOfReserve(asset);

    // Get the actual token balance in the yToken contract
    uint256 realBalance = _getYTokenUnderlyingBalance(asset);

    // After any sequence of borrow/repay (no pullFunds/pushFunds),
    // underlyingBalance (available) should equal real ERC20 balance in yToken
    // plus totalBorrows (which are outside yToken)
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);

    // totalLiquidity = underlyingBalance + borrowedLiquidity
    // underlyingBalance = real tokens in yToken (if no pull/push discrepancy)
    // This invariant should hold:
    uint256 reconstructed = realBalance + totalBorrows;
    // Allow 1 wei tolerance for rounding
    lte(reportedLiquidity, reconstructed + 1, "reported liquidity exceeds real backing");
    gte(reportedLiquidity + 1, reconstructed, "reported liquidity understates real backing");
}

function property_borrowingRate_bounded() public {
    address asset = address(token0);

    // Max borrowing rate is set to 15000 bps = 150% = 1.5e26 in ray
    uint256 maxRate = PRECISION * 15000 / 10000; // should be 1.5e26

    uint256 rate = lendingPool.borrowingRateOfReserve(asset);

    // Rate must be >= 0 and <= max configured rate
    lte(rate, maxRate, "borrowing rate exceeds maximum");

    // Create a borrow to get non-zero utilization rate
    uint256 borrowAmt = 500 * ONE_TOKEN0;
    _borrowAsLeverager(asset, borrowAmt);

    uint256 rateWithBorrow = lendingPool.borrowingRateOfReserve(asset);
    lte(rateWithBorrow, maxRate, "borrowing rate exceeds max under utilization");

    // Repay
    _repayAsLeverager(asset, borrowAmt * 2);
}

function property_exchangeRate_geq_precision() public {
    address asset = address(token0);

    // After any deposits, the exchange rate should be >= PRECISION (1:1)
    // if no interest has been earned yet. With interest, it grows.
    uint256 rate = lendingPool.exchangeRateOfReserve(asset);
    gte(rate, PRECISION / 2, "exchange rate should not collapse below 0.5");

    // Create borrows and advance time to accrue interest
    uint256 borrowAmt = 500 * ONE_TOKEN0;
    _borrowAsLeverager(asset, borrowAmt);
    vm.warp(block.timestamp + 30 days);

    uint256 rateAfter = lendingPool.exchangeRateOfReserve(asset);
    // After interest accrues, exchange rate (underlying/yToken) grows
    gte(rateAfter, rate, "exchange rate should grow with interest accrual");

    // Repay
    _repayAsLeverager(asset, borrowAmt * 2);
}

description:
In LendingPool.repay (lines 190-193):
  reserve.updateState();
  if (amount > reserve.totalBorrows) {
      amount = reserve.totalBorrows;
  }

After updateState(), reserve.totalBorrows has been updated to include all accrued interest up to this block. The cap `amount = reserve.totalBorrows` ensures repayment cannot exceed current debt. This is correct.
BUT: the comment at line 183 states "Due to rounding down, totalBorrows might be a few wei less than what the Leverager tries to repay." This acknowledges the truncation in _updateIndexes. The cap gracefully handles this — the leverager can always overpay by passing type(uint256).max and the actual debt is repaid. This is correct behavior.
The `return amount` at line 204 returns the actual repaid amount, which the Leverager can use to correctly account for the position. This is fine.
This is a non-finding: the design handles the truncation correctly through the capping mechanism and the return value.

solidity:
function property_repay_reduces_borrows() public {
    address asset = address(token0);
    uint256 borrowAmt = 100 * ONE_TOKEN0;

    _borrowAsLeverager(asset, borrowAmt);
    vm.warp(block.timestamp + 1 days);

    uint256 borrowsBefore = lendingPool.totalBorrowsOfReserve(asset);

    // Repay more than owed (should be capped at totalBorrows)
    _repayAsLeverager(asset, borrowsBefore * 2);

    uint256 borrowsAfter = lendingPool.totalBorrowsOfReserve(asset);

    // After full repayment, borrows should be 0
    eq(borrowsAfter, 0, "borrows should be 0 after full repayment");
}

function property_checkPoolActivity_no_revert_on_expanded_cardinality() public {
    // After rebalance is set up in setUp(), verify that checkPoolActivity()
    // doesn't revert when cardinality is at its current value.
    // This property verifies the function is callable without revert.
    bool result = strategy.checkPoolActivity();
    // If we reach here without revert, the property passes.
    // The vulnerability manifests when observationCardinality is grown externally.
    t(result || !result, "checkPoolActivity must not revert under normal conditions");
}

function property_collectFees_uses_correct_vesting_ticks() public {
    // Precondition: ongoingVestingPosition must be true.
    // We check that after collectFees(), no revert occurs, and that the vesting
    // position's actual ticks are used (not mainPosition.tickUpper).
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper for the vesting position.
    // If vp.tickUpper != mp.tickUpper, the wrong position is being collected.
    // This property asserts they should be equal only if vestPosition was set
    // from mainPosition at creation time and no rebalance has occurred since.
    // A rebalance changes mp.tickUpper but NOT vp.tickUpper.
    t(
        vp.tickUpper == mp.tickUpper,
        "vesting tickUpper diverged from mainPosition tickUpper after rebalance"
    );
}

function property_rebalance_not_permanently_bricked() public {
    // After setUp() which includes skip(10 minutes) and strategy.rebalance(),
    // verify that after waiting the rebalanceInterval, rebalance can be called again.
    skip(strategy.rebalanceInterval() + 1);
    // If checkPoolActivity() is broken, this reverts.
    vm.prank(rebalancer);
    try strategy.rebalance() {
        t(true, "rebalance succeeded");
    } catch {
        t(false, "rebalance permanently bricked due to pool activity check");
    }
}

function property_secondary_position_ticks_valid() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    t(
        sp.tickLower < sp.tickUpper,
        "secondary position tickLower must be strictly less than tickUpper"
    );
}

function property_vesting_position_ends_correctly() public {
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (block.timestamp < vp.endTs) return;

    // After endTs has passed, call collectFees to trigger _withdrawPartOfVestingPosition
    strategy.collectFees();

    // After endTs, the vesting position should be fully unwound
    t(!strategy.ongoingVestingPosition(), "vesting position should have ended after endTs");

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    t(vpAfter.remainingLiquidity == 0, "remaining liquidity should be 0 after vesting ends");
}

function property_vesting_removal_never_exceeds_initial() public {
    // After any sequence of collectFees calls, remaining <= initial
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (strategy.ongoingVestingPosition()) {
        t(
            vp.remainingLiquidity <= vp.initialLiquidity,
            "remainingLiquidity exceeds initialLiquidity"
        );
    }
}

function property_collectFees_uses_vest_tickUpper() public {
    // After a rebalance changes main ticks, collectFees should still
    // correctly process the vesting position. We verify that if a vesting
    // position exists, its fees are captured (idle balance increases after collect).
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // If vesting tickUpper != main tickUpper, collectFees uses the wrong tick
    t(
        vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
        "vesting position ticks diverged from main: collectFees will miss fees"
    );
}

function property_secondary_position_is_oor() public {
    // The secondary position must be Out-Of-Range (OOR).
    // OOR means current tick is outside [tickLower, tickUpper).
    (, int24 currentTick,,,,,) = pool.slot0();
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return;
    bool isOOR = currentTick < sp.tickLower || currentTick >= sp.tickUpper;
    t(isOOR, "secondary position is in-range — violates OOR invariant");
}

function property_vesting_linear_distribution() public {
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.initialLiquidity == 0) return;
    if (vp.endTs <= vp.startTs) return;
    // If significant time has passed (>1% of duration), some liquidity should
    // have been removed (remainingLiquidity < initialLiquidity)
    uint256 elapsed = block.timestamp > vp.endTs ? vp.endTs - vp.startTs : block.timestamp - vp.startTs;
    uint256 totalDuration = vp.endTs - vp.startTs;
    if (elapsed * 100 / totalDuration >= 1) {
        // At least 1% of duration has elapsed — some liquidity should be gone
        // (unless collectFees was never called — this is a best-effort check)
        t(
            vp.remainingLiquidity <= vp.initialLiquidity,
            "vesting: remainingLiquidity exceeds initial"
        );
    }
}

function property_MH001_first_depositor_inflation() public {
    // After the initial setup deposit, no subsequent depositor should
