function property_MH002_shares_double_division_precision() public {
    // Capture state before deposit
    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();
    if (supplyBefore == 0 || bal0 == 0 || bal1 == 0) return;

    uint256 depositAmt0 = bal0 / 100; // 1% of current bal0
    uint256 depositAmt1 = bal1 / 100; // 1% of current bal1

    if (depositAmt0 == 0 || depositAmt1 == 0) return;

    deal(address(token0), depositor, depositAmt0);
    deal(address(token1), depositor, depositAmt1);

    vm.startPrank(depositor);
    (uint256 shares,,) = vault.deposit(depositAmt0, depositAmt1, 0, 0);
    vm.stopPrank();

    // Depositing 1% of pool should yield approximately 1% of totalSupply shares
    // Allow 2 share tolerance for rounding
    uint256 expectedShares = supplyBefore / 100;
    // shares should be within 2 of expected (not severely undercount)
    t(shares + 2 >= expectedShares, "MH-002: double-division undervalues shares by more than 2");
}

function property_MH003_fee_not_evadeable_by_splitting() public {
    // If depositFee > 0, a deposit should always pay some fee
    uint256 fee = vault.depositFee();
    if (fee == 0) return;

    // Deposit a tiny but non-zero amount that yields > 0 shares
    uint256 amt0 = ONE_TOKEN0 / 1000; // 0.001 WBTC (100000 satoshi)
    uint256 amt1 = ONE_TOKEN1 * 100;  // 100 USDC

    deal(address(token0), depositor, amt0);
    deal(address(token1), depositor, amt1);

    uint256 supplyBefore = vault.totalSupply();

    vm.startPrank(depositor);
    (uint256 shares,,) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    uint256 supplyAfter = vault.totalSupply();
    uint256 sharesActuallyMinted = supplyAfter - supplyBefore;

    // If fee > 0, shares received by user should be less than shares minted
    // i.e., some fee must have been deducted when shares >= 10000/fee
    if (shares >= 10_000 / fee) {
        t(shares < sharesActuallyMinted, "MH-003: fee was not charged on deposit");
