    uint256 bal1Before = token1.balanceOf(depositor);

    vm.startPrank(depositor);
    (uint256 shares, uint256 amt0, uint256 amt1) = vault.deposit(depositAmt0, depositAmt1, 0, 0);
    vm.stopPrank();

    uint256 bal0After = token0.balanceOf(depositor);
    uint256 bal1After = token1.balanceOf(depositor);

    uint256 actualPaid0 = bal0Before - bal0After;
    uint256 actualPaid1 = bal1Before - bal1After;

    // Depositor should not have paid MORE than amt0 and amt1 returned
    eq(actualPaid0, amt0, "MH-006: depositor paid more token0 than reported");
    eq(actualPaid1, amt1, "MH-006: depositor paid more token1 than reported");

    // Shares minted should represent at least the deposited proportion
    // shares / (supply + shares) >= min(amt0/bal0, amt1/bal1) approximately
    uint256 newSupply = vault.totalSupply();
    t(shares > 0, "MH-006: shares must be > 0");
    // Cross-check: shares * bal0 / newSupply approximately equals amt0 (proportional)
    uint256 impliedAmt0 = bal0 * shares / newSupply;
    t(impliedAmt0 <= amt0 + 2, "MH-006: shares imply more token0 than deposited");
}

function property_MH007_withdraw_total_value_preserved() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;
    uint256 withdrawShares = userShares / 4;
    if (withdrawShares == 0) return;

    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();
    if (supplyBefore == 0) return;

    vm.prank(user);
    (uint256 got0, uint256 got1) = vault.withdraw(withdrawShares, 0, 0);

    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    uint256 supplyAfter = vault.totalSupply();

    // After withdrawal, remaining shares should still represent
    // their proportional claim on the remaining pool
    // i.e., bal0After / supplyAfter == bal0Before / supplyBefore (approx)
    // This ensures the withdrawer didn't take more than their share
    if (supplyAfter > 0 && bal0Before > 0) {
        // Cross multiply: bal0After * supplyBefore <= bal0Before * supplyAfter + tolerance
        // (remaining balance per share should not exceed pre-withdrawal per-share)
        uint256 lhs = bal0After * supplyBefore;
        uint256 rhs = bal0Before * supplyAfter;
        // Allow 2 wei tolerance per share for rounding
        t(lhs <= rhs + 2 * supplyBefore, "MH-007: post-withdrawal per-share value inflated for token0");
    }
}

function property_chainlink_price_uses_updatedAt() public {
    // The PriceFeed contract should revert when Chainlink data is stale.
    // We simulate staleness by warping time far past the heartbeat (604800 = 7 days).
    // If price is still returned without revert, the staleness check is missing.

    // Set a known wbtc price
    wbtcOracle.setPrice(100_000e18);

    // Advance time well beyond the 604800s heartbeat
    skip(604800 + 1);

    // getPrice should revert due to staleness, but it doesn't — this property detects the bug
    bool reverted = false;
    try priceFeed.getPrice(address(wbtc)) returns (uint256 p) {
        // Price was returned without revert — staleness check is NOT enforced
        reverted = false;
    } catch {
        reverted = true;
    }
    // The property FAILS (bug present) when price is returned despite staleness
    t(reverted, "stale chainlink price accepted: heartbeat check commented out");
}

function property_liquidation_borrowed_value_decimal_correct() public {
    // Open a WBTC-denomination position
    uint256 posId = _openWbtcPosition(user, ONE_WBTC / 2, 0, ONE_WBTC / 2, 0, ONE_WBTC / 10);

    // Make position liquidatable by crashing WBTC price
    wbtcOracle.setPrice(1e18); // $1 per WBTC — extreme crash

    // Verify the two computations give different results (detecting the bug)
    ILeverager.Position memory pos = leverager.getPosition(posId);
    uint256 bPrice = priceFeed.getPrice(pos.denomination);

    uint256 decimalsRaw = ERC20(pos.denomination).decimals(); // returns 8, not 1e8
    uint256 decimalsCorrect = 10 ** ERC20(pos.denomination).decimals(); // 1e8

    // borrowedValue as computed in code (WRONG):
    uint256 bIndex = lendingPool.getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;
    uint256 borrowedValueBuggy = owedAmount * bPrice / decimalsRaw;
    uint256 borrowedValueCorrect = owedAmount * bPrice / decimalsCorrect;

    // The bug: buggy value is orders of magnitude larger
    t(borrowedValueBuggy == borrowedValueCorrect, "decimal error in liquidation borrowedValue: .decimals() used instead of 10**decimals()");
}

