function property_DH01_vesting_fees_collected_from_correct_ticks() public {
    // Only meaningful when there's an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // After rebalance, mainPosition ticks change. The collectFees call
    // uses mainPosition.tickUpper for the vesting position, which is WRONG.
    // The vesting position's tickUpper is stored in vp.tickUpper.
    // This invariant fires when the two diverge (post-rebalance scenario).
    // If they differ, the fees being collected are for a non-existent position.
    t(
        vp.tickUpper == mp.tickUpper,
        "DH-01: vesting tickUpper diverged from mainPosition.tickUpper — collectFees uses wrong range"
    );
}

function property_DH02_balances_includes_vesting_position() public {
    if (!strategy.ongoingVestingPosition()) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // Vesting position has remaining liquidity — its tokens should be reflected in balances.
    // We just assert that balances are > 0 and vesting liquidity is > 0,
    // then verify deposit/withdraw round-trip doesn't extract value.
    if (vp.remainingLiquidity == 0) return;

    uint256 totalSupply = vault.totalSupply();
    if (totalSupply == 0) return;

    // A depositor who deposits exactly proportional to balances should get back the same,
    // not MORE. If balances() underreports, they get more shares for same tokens → can extract.
    uint256 sharesBefore = vault.balanceOf(depositor);
    uint256 wbtcBefore = wbtc.balanceOf(depositor);
    uint256 usdcBefore = usdc.balanceOf(depositor);

    // depositor deposits a small amount
    uint256 dep0 = ONE_TOKEN0 / 100; // 0.01 WBTC
    uint256 dep1 = 1000 * ONE_TOKEN1; // 1000 USDC
    deal(address(wbtc), depositor, dep0);
    deal(address(usdc), depositor, dep1);

    vm.startPrank(depositor);
    wbtc.approve(address(vault), dep0);
    usdc.approve(address(vault), dep1);
    (uint256 shares,,) = vault.deposit(dep0, dep1, 0, 0);
    (uint256 out0, uint256 out1) = vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    // Should not extract more than deposited (allow small rounding tolerance)
    t(out0 <= dep0 + 2, "DH-02: depositor extracted more token0 than deposited via vesting undercount");
    t(out1 <= dep1 + 2, "DH-02: depositor extracted more token1 than deposited via vesting undercount");
}

function property_DH03_vesting_linear_distribution() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.endTs <= block.timestamp) return;
    if (vp.endTs == vp.startTs) return;

    uint256 elapsed = block.timestamp - vp.startTs;
    uint256 totalDuration = vp.endTs - vp.startTs;

    // Expected remaining: initialLiquidity * (totalDuration - elapsed) / totalDuration
    // i.e., proportion of time remaining
    uint256 expectedRemaining = uint256(vp.initialLiquidity) * (totalDuration - elapsed) / totalDuration;

    // Allow 1% tolerance for rounding
    uint256 tolerance = uint256(vp.initialLiquidity) / 100 + 1;

    lte(
        vp.remainingLiquidity,
        uint128(expectedRemaining + tolerance),
        "DH-03: vesting remainingLiquidity higher than linear schedule predicts"
    );
}

