    (uint256 bal0, uint256 bal1) = strategy.balances();

    // Shares per unit of token0 should be within reasonable bounds of shares per unit of token1
    // Using a loose bound: ratio should be within 1000x of each other
    // (accounts for WBTC=8dec vs USDC=6dec, price ~$80k/BTC -> ~1e13 USDC per WBTC)
