        uint256 sharesPerToken1 = supply * ONE_TOKEN1 / bal1;
        // These should be within 10x of each other at market price ~80k USDC/WBTC
        // At $80k/BTC: 1 WBTC = 80000 USDC. So shares should reflect ~80000x more
        // token1 units per WBTC unit. If sharesPerToken0 >> sharesPerToken1 * 80000 * 100,
        // the ratio is pathologically skewed
        t(sharesPerToken0 < sharesPerToken1 * 80000 * 10000,
          "Share ratio is pathologically skewed vs price");
    }
}

function property_deposit_no_excess_token_extraction() public {
    uint256 amt0 = ONE_TOKEN0;      // 1 WBTC
    uint256 amt1 = ONE_TOKEN1 * 80000; // 80000 USDC

    deal(address(token0), depositor, amt0);
    deal(address(token1), depositor, amt1);

    uint256 token0Before = token0.balanceOf(depositor);
