    uint256 token1After = token1.balanceOf(depositor);

    // Depositor should not have paid more than depositAmount0/1
    eq(token0Before - token0After, dep0, "paid more token0 than dep0");
    eq(token1Before - token1After, dep1, "paid more token1 than dep1");

    // Neither dep0 nor dep1 should exceed the requested amounts by more than 1 wei
    t(dep0 <= amt0, "dep0 exceeds requested amount0");
    t(dep1 <= amt1, "dep1 exceeds requested amount1");
}

function property_withdraw_always_succeeds_with_sufficient_shares() public {
