    // Expected withdraw proportional to shares
    uint256 expected0 = bal0 * userShares / totalSup;
    uint256 expected1 = bal1 * userShares / totalSup;

    uint256 wbtcBefore = wbtc.balanceOf(user);
    uint256 usdcBefore = usdc.balanceOf(user);

