    t(out1 <= expected1 + 1, "withdraw1 exceeds proportional share");
}

function property_positionWidth_only_changed_by_authorized() public {
    uint24 widthBefore = strategy.positionWidth();

    // Attempt attacker-initiated width change
    uint24 newWidth = widthBefore * 2;
    // Ensure divisibility requirement is met
    if ((newWidth / 2) % uint24(uint24(int24(strategy.tickSpacing()))) != 0) {
        newWidth = uint24(uint24(int24(strategy.tickSpacing())) * 8);
    }

    vm.prank(attacker); // attacker is not the rebalancer
    try strategy.changePositionWidth(newWidth) {
        // If this succeeded without reverting: attacker changed width — BUG
        t(false, "attacker changed positionWidth");
    } catch {
        // Expected: revert. Verify width is unchanged.
        eq(uint256(strategy.positionWidth()), uint256(widthBefore), "positionWidth changed despite revert");
    }
}

