function property_first_deposit_share_price_fair() public {
    // After first deposit, the share price should reflect both tokens fairly
    // Verify that a second deposit of the same ratio gives proportional shares
    uint256 totalSupplyAfterFirst = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = vault.balances();

    // Second depositor deposits same ratio
    uint256 dep0 = 1e7;
    uint256 dep1 = 10_000e6;
    (uint256 shares2, uint256 a0, uint256 a1) = _dealAndDeposit(depositor, dep0, dep1);

    // shares2 / totalSupplyAfterFirst should ≈ a0 / bal0 ≈ a1 / bal1
    // i.e. depositor gets proportional shares
    uint256 expectedSharesFromBal0 = bal0 > 0 ? a0 * totalSupplyAfterFirst / bal0 : 0;
    uint256 expectedSharesFromBal1 = bal1 > 0 ? a1 * totalSupplyAfterFirst / bal1 : 0;

    // shares2 should be within 1% of expected (allow rounding)
    if (bal0 > 0 && bal1 > 0) {
        uint256 minExpected = expectedSharesFromBal0 < expectedSharesFromBal1
            ? expectedSharesFromBal0 : expectedSharesFromBal1;
        // shares2 >= 99% of expected (rounding down is allowed but not by more than 1%)
        gte(shares2 * 100, minExpected * 99, "second depositor got significantly fewer shares than expected");
    }
}

function property_deposit_rounding_does_not_steal_from_user() public {
    // User deposits tokens; the actual tokens taken should not significantly exceed
    // what their share entitlement justifies
    uint256 dep0 = 1e6; // small amount to stress rounding
    uint256 dep1 = 1_000e6;
    (uint256 shares, uint256 actual0, uint256 actual1) = _dealAndDeposit(depositor, dep0, dep1);

    // After deposit, verify value paid vs shares received is proportional
    (uint256 bal0After, uint256 bal1After) = vault.balances();
    uint256 totalSupplyAfter = vault.totalSupply();

    // The depositor should be able to withdraw at least (actual0 - dust) and (actual1 - dust)
    // i.e. they shouldn't lose more than dust (2 wei per token) to rounding
    if (shares > 0) {
        uint256 withdrawable0 = bal0After * shares / totalSupplyAfter;
        uint256 withdrawable1 = bal1After * shares / totalSupplyAfter;

        // withdrawable should be within 2 of actual (1 wei rounding per amount)
        // actual0 - withdrawable0 <= 2 (rounding loss bounded)
        if (actual0 > withdrawable0) {
            lte(actual0 - withdrawable0, 2, "depositor lost more than 2 wei of token0 to rounding");
        }
        if (actual1 > withdrawable1) {
            lte(actual1 - withdrawable1, 2, "depositor lost more than 2 wei of token1 to rounding");
        }
    }
}

