function property_deposit_share_price_reflects_true_vault_value() public {
    // Verify that shares minted to a depositor represent fair value
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();
    uint256 tsBefore = vault.totalSupply();

    uint256 dep0 = 1e7;
    uint256 dep1 = 10_000e6;
    (uint256 shares, uint256 actual0, uint256 actual1) = _dealAndDeposit(depositor, dep0, dep1);

    (uint256 bal0After, uint256 bal1After) = vault.balances();
    uint256 tsAfter = vault.totalSupply();

    // The fraction of total supply gained should equal the fraction of total value contributed
    // shares / tsAfter ≈ (actual0 contributed as fraction of bal0After)
    // i.e. shares * bal0After ≈ actual0 * tsAfter (within rounding)
    if (bal0After > 0 && actual0 > 0) {
        uint256 lhs = shares * bal0After;
        uint256 rhs = actual0 * tsAfter;
        // Allow 1% tolerance for rounding
        gte(lhs * 100, rhs * 99, "depositor received disproportionately few shares vs token0 contributed");
        lte(lhs * 100, rhs * 101, "depositor received disproportionately many shares vs token0 contributed");
    }
}

function property_withdraw_amounts_bounded_by_fair_price() public {
    // Deposit as depositor first
    (uint256 shares,,) = _dealAndDeposit(depositor, 1e7, 10_000e6);

    // Record pre-swap balances
    (uint256 fairBal0, uint256 fairBal1) = vault.balances();
    uint256 totalSupply = vault.totalSupply();

    // Simulate a large price-moving swap (attacker front-runs with a swap)
    _swapUsdcForWbtc(1_000_000e6); // large USDC→WBTC swap to move price

    // Now withdraw — balances() will use new (potentially manipulated) spot price
    (uint256 got0, uint256 got1) = _withdrawAs(depositor, shares);

    // Restore price somewhat
    // The property: amounts received should not dramatically exceed fair proportional value
    // Fair value: fairBal0 * shares / totalSupply and fairBal1 * shares / totalSupply
    uint256 expectedFair0 = fairBal0 * shares / totalSupply;
    uint256 expectedFair1 = fairBal1 * shares / totalSupply;

    // Allow 10% deviation from fair value for normal price movement; flag if much more
    // This detects if spot-price-dependent balances inflate withdrawal amounts significantly
    lte(got1, expectedFair1 * 120 / 100, "withdrew significantly more token1 than fair share (possible price manipulation)");
    lte(got0, expectedFair0 * 120 / 100, "withdrew significantly more token0 than fair share (possible price manipulation)");
}

description:
Vault constructor at line 34 swaps token0 and token1 if _token0 > _token1 (address ordering):
  if (_token0 > _token1) (_token0, _token1) = (_token1, _token0);
This ensures token0 < token1 to match Uniswap's ordering convention. However, the caller (e.g. a deployer or integration) might pass tokens in the wrong order and not realize the swap occurred. If the deployer then calls setStrategy() with a Strategy whose token0/token1 ordering was determined by the pool's own token0/token1 (which already follows Uniswap ordering), the Vault's token0/token1 will correctly match the Strategy's token0/token1. BUT: the Setup.sol deploys Vault(wbtc, usdc) where wbtc = 0x2260FAC5 < usdc = 0xA0b86991, so token0 = wbtc and token1 = usdc (no swap needed, wbtc < usdc). If a user deploys with swapped order (usdc, wbtc), the vault internally corrects it. The risk: if an ERC20 token's address ordering doesn't match the pool's token ordering, and a deployer provides the wrong order expecting no swap, the vault will silently swap them. A deployer who checks token0/token1 after deployment expecting them to match their input will be surprised — their approve flows, off-chain integrations, and UI assumptions about which is token0 and which is token1 may break silently. This is an implicit interface contract violation that can lead to incorrect approve amounts, wrong slippage parameters, and deposit accounting errors in off-chain systems.

solidity:
function property_token_ordering_matches_pool_ordering() public view {
    // Vault's token0/token1 should match the pool's token0/token1
    address poolToken0 = pool.token0();
    address poolToken1 = pool.token1();
    address vaultToken0 = vault.token0();
    address vaultToken1 = vault.token1();

    // Vault and pool should agree on token ordering
    t(vaultToken0 == poolToken0, "vault token0 should match pool token0");
    t(vaultToken1 == poolToken1, "vault token1 should match pool token1");

    // Also verify strategy token ordering matches
    address stratToken0 = strategy.token0();
    address stratToken1 = strategy.token1();
    t(stratToken0 == vaultToken0, "strategy token0 should match vault token0");
    t(stratToken1 == vaultToken1, "strategy token1 should match vault token1");
}

description:
Vault.withdraw() determines whether to call strategy.withdrawPartial() based on:
  if (idle0 < withdrawAmount0 || idle1 < withdrawAmount1)
But withdrawAmount0 and withdrawAmount1 are computed from strategy.balances() BEFORE checking idle balances. The strategy.balances() function includes liquidity in Uniswap positions converted at SPOT price. If the spot price moves between the balances() call and the idle check, or if there is a position that is entirely out-of-range (holding only one token), the computed withdrawAmount0/withdrawAmount1 may be unachievable. Specifically: if the vault has a secondary position entirely in token1 (OOR) and balances() accounts for it as token1, but withdrawPartial divides liquidity proportionally (by shares/totalSupply), the actual token amounts returned by withdrawPartial may differ from withdrawAmount0/withdrawAmount1. The return values of withdrawPartial are used to update the final withdrawal amounts, but the slippage check uses these updated amounts — this is correct behavior. The deeper issue: if idle0 >= withdrawAmount0 AND idle1 >= withdrawAmount1 but the strategy's balances() overstated the values due to spot price, the user receives only idle tokens (no Uniswap removal) which may be LESS than their fair proportional share of the total vault including LP positions.

solidity:
function property_withdraw_returns_proportional_total_value() public {
    // Depositor deposited some funds; now withdraws all shares
    (uint256 shares,,) = _dealAndDeposit(depositor, 1e7, 10_000e6);

    (uint256 totalBal0, uint256 totalBal1) = vault.balances();
    uint256 totalSupply = vault.totalSupply();

    uint256 expectedMin0 = totalBal0 * shares / totalSupply;
    uint256 expectedMin1 = totalBal1 * shares / totalSupply;

    // Withdraw all shares
    (uint256 got0, uint256 got1) = _withdrawAs(depositor, shares);

    // User should receive at least 98% of their expected proportional share
    // (allowing 2% for rounding and minor price movement during the tx)
    gte(got0 * 100, expectedMin0 * 98, "received significantly less token0 than proportional share");
    gte(got1 * 100, expectedMin1 * 98, "received significantly less token1 than proportional share");
}

function property_vesting_fees_collected_from_correct_range() public {
    // Only meaningful when there is an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The vesting position ticks must differ from main position ticks
    // after a rebalance — this is when the bug manifests
    // We check: if tickUpper differs, collectFees should still collect
    // from the vesting position's real range

    uint256 preBal0 = wbtc.balanceOf(address(strategy));
    uint256 preBal1 = usdc.balanceOf(address(strategy));

    strategy.collectFees();

    // If vestPosition.tickUpper != mainPosition.tickUpper, fees from vesting
    // position were NOT collected (bug manifests). We cannot directly measure
    // pool-level fees, but we can assert the vesting position ticks are used:
    // The property fails to compile a direct invariant here because we cannot
    // query uncollected fees from the pool in-test. Instead, assert the ticks match.
    t(
        vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
        "Vesting position ticks diverged from main: fees are silently skipped"
    );
}

function property_collect_fees_uses_vesting_ticks() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // Simulate a fee-generating scenario: make a swap to generate fees in the pool,
    // then verify that collectFees picks up fees from the vesting position's range.
    // The vesting position ticks should be used, not main position ticks.
    IStrategy.Position memory mp = strategy.getMainPosition();

    // After rebalance, if tickUppers diverge, the bug is live
    // Property: vestPosition.tickUpper must equal what collectPositionFees uses.
    // We can only check this statically from the code — the invariant is:
    t(
        vp.tickUpper == mp.tickUpper,
        "LIB-02: vesting tickUpper != main tickUpper; collectFees will use wrong range"
    );
}

function property_secondary_position_is_oor() public {
    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();

    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return;

    uint160 sqrtLower = TickMath.getSqrtRatioAtTick(sp.tickLower);
    uint160 sqrtUpper = TickMath.getSqrtRatioAtTick(sp.tickUpper);

    // Secondary position should be Out-Of-Range:
    // either current price is below the range (all token0) or above (all token1)
    bool isOOR = sqrtPriceX96 <= sqrtLower || sqrtPriceX96 >= sqrtUpper;
    t(isOOR, "LIB-03: secondary position is in-range, should always be OOR");
}

function property_secondary_ticks_valid() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();

    // tickLower must be strictly less than tickUpper for a valid Uniswap V3 position
    if (sp.liquidity > 0) {
        t(sp.tickLower < sp.tickUpper, "LIB-04: secondary position has invalid tick range (tickLower >= tickUpper)");
    }

    // Also verify ticks are aligned to tickSpacing
    int24 ts = strategy.tickSpacing();
    t(sp.tickLower % ts == 0, "LIB-04: secondary tickLower not aligned to tickSpacing");
    t(sp.tickUpper % ts == 0, "LIB-04: secondary tickUpper not aligned to tickSpacing");
}

function property_check_pool_activity_no_revert() public {
    // checkPoolActivity should not revert under normal conditions
    bool result = strategy.checkPoolActivity();
    // If we got here without revert, the property holds
    t(true, "LIB-05: checkPoolActivity reverted due to division by zero");
}

function property_vesting_position_fees_not_stuck() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If the vesting and main positions have different tickUpper values,
    // the collectFees call on line 167 is silently a no-op for the vesting position.
    // This is the same root cause as LIB-01.
    t(
        vp.tickUpper == mp.tickUpper,
        "LIB-06: vesting tickUpper diverged from main; vesting position fees never collected via collectPositionFees"
    );
}

function property_pullFunds_updates_underlying_balance() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    uint256 balBefore = IERC20(asset).balanceOf(yAddr);
    // get underlyingBalance via totalLiquidity - borrows
    uint256 totalLiqBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrowsBefore = lendingPool.totalBorrowsOfReserve(asset);
    uint256 underlyingBefore = totalLiqBefore - totalBorrowsBefore;

    uint256 pullAmount = balBefore / 4;
    if (pullAmount == 0) return;

    _pullFunds(asset, pullAmount);

    uint256 balAfter = IERC20(asset).balanceOf(yAddr);
    uint256 totalLiqAfter = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrowsAfter = lendingPool.totalBorrowsOfReserve(asset);
    uint256 underlyingAfter = totalLiqAfter - totalBorrowsAfter;

    // After pullFunds, available underlying tracked should decrease by pullAmount
    // If this assertion fails, underlyingBalance was NOT updated, meaning accounting is broken
    lte(underlyingAfter, underlyingBefore - pullAmount, "pullFunds must reduce tracked underlyingBalance");
    eq(balAfter, balBefore - pullAmount, "yToken token balance must decrease by pullAmount");
}

function property_pushFunds_updates_underlying_balance() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    uint256 totalLiqBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrowsBefore = lendingPool.totalBorrowsOfReserve(asset);
    uint256 underlyingBefore = totalLiqBefore - totalBorrowsBefore;

    uint256 pushAmount = 1000 * ONE_TOKEN0;

    _pushFunds(asset, pushAmount);

    uint256 balAfter = IERC20(asset).balanceOf(yAddr);
    uint256 totalLiqAfter = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrowsAfter = lendingPool.totalBorrowsOfReserve(asset);
    uint256 underlyingAfter = totalLiqAfter - totalBorrowsAfter;

    // underlyingBalance should increase by pushAmount
    gte(underlyingAfter, underlyingBefore + pushAmount, "pushFunds must increase tracked underlyingBalance");
}

function property_exchange_rate_consistent_with_token_balance() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    uint256 pullAmount = IERC20(asset).balanceOf(yAddr) / 4;
    if (pullAmount == 0) return;

    // Pull funds (leverager temporarily takes tokens for swap)
    _pullFunds(asset, pullAmount);

    // Exchange rate should reflect reduced liquidity
    uint256 rate = lendingPool.exchangeRateOfReserve(asset);
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    uint256 trackedAvailable = totalLiq - totalBorrows;
    uint256 actualBalance = IERC20(asset).balanceOf(yAddr);

    // The tracked available liquidity must match actual token balance
    // (no borrows active in this scenario)
    lte(trackedAvailable, actualBalance + 1, "tracked available must not exceed actual balance");
}

function property_first_deposit_minimum_ytoken_protection() public {
    address asset = address(token1);
    // Use a fresh reserve concept by checking: first depositor gets protected
    // In the existing setup, token1 reserve already has deposits.
    // Verify: after deposit of exactly MINIMUM_YTOKEN_AMOUNT + 1 (in underlying units),
    // a new depositor must receive > 0 yTokens
    uint256 depositAmt = (MINIMUM_YTOKEN_AMOUNT + 1) * ONE_TOKEN1;
    uint256 yBefore = _getYTokenBalance(asset, user2);
    uint256 yAmt = _depositToken1As(user2, depositAmt);
    uint256 yAfter = _getYTokenBalance(asset, user2);
    gte(yAfter, yBefore, "depositor must not lose yTokens from deposit");
    t(yAmt > 0, "depositor must receive at least 1 yToken");
}

function property_repay_totalBorrows_consistent() public {
    address asset = address(token0);

    // Setup: borrow some tokens
    uint256 borrowAmt = 10_000 * ONE_TOKEN0;
    _borrow(asset, borrowAmt);

    uint256 borrowsBefore = lendingPool.totalBorrowsOfReserve(asset);
    uint256 liqBefore = lendingPool.totalLiquidityOfReserve(asset);

    // Repay half
    uint256 repayAmt = borrowAmt / 2;
    _repay(asset, repayAmt);

    uint256 borrowsAfter = lendingPool.totalBorrowsOfReserve(asset);
    uint256 liqAfter = lendingPool.totalLiquidityOfReserve(asset);

    // totalBorrows should have decreased
    lte(borrowsAfter, borrowsBefore, "totalBorrows must not increase after repay");
    // totalLiquidity should be conserved (approximately — interest may accrue)
    gte(liqAfter, liqBefore - 1, "totalLiquidity must not decrease on repay");
}

function property_total_redeemable_leq_actual_balance() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    // Simulate leverager pull-then-partial-push
    uint256 availBal = IERC20(asset).balanceOf(yAddr);
    if (availBal < 2) return;

    uint256 pullAmt = availBal / 2;
    uint256 pushAmt = pullAmt / 2; // push back only half

    _pullFunds(asset, pullAmt);
    _pushFunds(asset, pushAmt);

    // Now actual balance = availBal - pullAmt + pushAmt
    uint256 actualBal = IERC20(asset).balanceOf(yAddr);
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(asset);
    uint256 reportedAvailable = totalLiq - totalBorrows;

    // Reported available must not exceed actual balance (otherwise redemptions will fail)
    lte(reportedAvailable, actualBal, "reported available liquidity exceeds actual token balance — redemptions will fail");
}

function property_feeRecipient_never_zero_when_fee_set() public {
    // If a liquidation fee is configured, the feeRecipient must be a non-zero address
    // to avoid burning protocol fees. This verifies that feeRecipient was properly set.
    // In the current code there is no setter, so feeRecipient is always address(0).
    address fr = leverager.feeRecipient();
    // The invariant: if liquidationFee > 0, feeRecipient must not be address(0)
    // We cannot read liquidationFee directly (it is internal), but we can verify
    // that feeRecipient is not address(0) since it should have been set during setup.
    t(fr != address(0), "feeRecipient is address(0): protocol fees are burned on liquidation");
}

function property_withdraw_denom_token1_correct_repay() public {
