    vm.prank(owner);
    leverager.setLiquidationFee(500); // 5%

    uint256 frBalBefore0 = wbtc.balanceOf(feeRecipient);
    uint256 frBalBefore1 = usdc.balanceOf(feeRecipient);

    _liquidatePosition(liquidator, posId);

    // If the liquidation was profitable (collateral > debt), feeRecipient should have received tokens
    // This will FAIL because: (a) feeRecipient is address(0) and (b) borrowedValue calc uses raw decimals
    uint256 frGain0 = wbtc.balanceOf(feeRecipient) - frBalBefore0;
    uint256 frGain1 = usdc.balanceOf(feeRecipient) - frBalBefore1;
    t(frGain0 > 0 || frGain1 > 0, "protocol fee recipient received nothing despite profitable liquidation");
