    uint256 poolBalBefore = usdc.balanceOf(address(lendingPool));
    _liquidatePosition(liquidator, posId);
    uint256 poolBalAfter = usdc.balanceOf(address(lendingPool));

    // LendingPool balance should not have decreased (no fraudulent repay drain)
