function property_withdraw_repay_matches_stored_borrow() public {
    uint256 posId = _openLeveragedPositionDenomWbtc(user, 50_000e6, 0.5e8, 0.6e8);
    if (posId == 0) return;

    uint256 borrowBefore = leverager.getPosition(posId).borrowedAmount;
    uint256 indexBefore = leverager.getPosition(posId).borrowedIndex;

    skip(1 days);

    _withdrawPosition(user, posId, 0.5e18);

    if (!_positionExists(posId)) return;

    ILeverager.Position memory pos = leverager.getPosition(posId);
    uint256 currIndex = lendingPool.getCurrentBorrowingIndex(address(wbtc));

    // Remaining owed: pos.borrowedAmount * currIndex / pos.borrowedIndex
    uint256 remainingOwed = pos.borrowedAmount * currIndex / pos.borrowedIndex;
    // Should be roughly half of original owed (within rounding)
    uint256 origOwed = borrowBefore * currIndex / indexBefore;
    // remainingOwed should be <= origOwed (never MORE than original after partial repayment)
    lte(remainingOwed, origOwed, "remaining owed after partial withdraw exceeds original");
}

function property_pullFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    // record underlyingBalance before pull
    uint256 avail = lendingPool.totalLiquidityOfReserve(asset);
    // ensure there is something to pull
    if (avail == 0) return;
    uint256 pullAmt = avail / 2;
    if (pullAmt == 0) return;

    // Capture real token balance of yToken before
    address yAddr = lendingPool.getYTokenAddress(asset);
    uint256 realBefore = token0.balanceOf(yAddr);

    // pull funds (leverager role)
    _pullFunds(asset, pullAmt);

    uint256 realAfter = token0.balanceOf(yAddr);
    uint256 availAfter = lendingPool.totalLiquidityOfReserve(asset);

    // The real balance should have decreased by pullAmt
    // The accounting should reflect the same decrease
    // If bug exists: availAfter == avail (unchanged), realAfter == realBefore - pullAmt
    // Invariant: the difference in real balance should match the difference in accounting
    uint256 realDelta = realBefore - realAfter;
    uint256 accountingDelta = avail > availAfter ? avail - availAfter : 0;

    // They must match within rounding
    t(realDelta == accountingDelta, "pullFunds: underlyingBalance not updated - phantom liquidity");
}

function property_pushFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    uint256 avail = lendingPool.totalLiquidityOfReserve(asset);
    if (avail < 2) return;
    uint256 pullAmt = avail / 4;
    if (pullAmt == 0) return;

    address yAddr = lendingPool.getYTokenAddress(asset);

    // Pull then immediately push back the same amount
    _pullFunds(asset, pullAmt);
    _pushFunds(asset, pullAmt);

    // After round-trip, real balance should be unchanged
    uint256 realBalance = token0.balanceOf(yAddr);
    uint256 accountingBalance = lendingPool.totalLiquidityOfReserve(asset);

    // Accounting should match actual token balance of yToken
    // (ignoring borrowed-out portion which is not in yToken)
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    // availableLiquidity = underlyingBalance = realBalance (when no borrow accounting mismatch)
    uint256 availAccounting = accountingBalance > totalBorrows ? accountingBalance - totalBorrows : 0;

    t(availAccounting == realBalance, "pushFunds: underlyingBalance not updated after round-trip");
}

