function property_liquidation_borrowedValue_correct() public {
    // Open a USDC-denomination position
    uint256 posId = _openLeveragedPositionDenomUsdc(
        user,
        1e7,
        50_000e6,
        60_000e6
    );
    if (posId == 0) return;

    // Drop USDC price to force liquidatability (make collateral value fall)
    // by bumping WBTC price down dramatically
    vm.prank(owner);
    wbtcOracle.setPrice(1_000e18); // WBTC crashes to $1k

    if (!leverager.isLiquidateable(posId)) return;

    // Liquidate: record balances before and after to check liquidator profits
    deal(address(usdc), liquidator, 10_000_000e6);
    vm.startPrank(liquidator);
    usdc.approve(address(leverager), type(uint256).max);

    uint256 usdcBefore = usdc.balanceOf(liquidator);
    uint256 wbtcBefore = wbtc.balanceOf(liquidator);

    ILeverager.LiquidateParams memory lp;
    lp.id        = posId;
    lp.hasToSwap = false;
    try leverager.liquidatePosition(lp) {} catch { vm.stopPrank(); return; }
    vm.stopPrank();

    uint256 usdcAfter = usdc.balanceOf(liquidator);
    uint256 wbtcAfter = wbtc.balanceOf(liquidator);

    // Property: if collateral value exceeds debt, liquidator must end up
    // with at least as many tokens as they started (net profitable)
    // A correct borrowedValue would enable the profitability check branch.
    // With the bug, borrowedValue is ~166k times too large so the fee
    // branch is never triggered. We verify the feeRecipient gets nothing
    // when it should if borrowedValue were correct.
    uint256 feeRecipientWbtc = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientUsdc = usdc.balanceOf(feeRecipient);
    // feeRecipient is address(0x9999) in Setup, liquidationFee defaults to 0
    // so even with correct code no fee — but the accounting branch is exercised.
    // The key invariant: liquidator net outcome should be non-negative.
    int256 netUsdc = int256(usdcAfter) - int256(usdcBefore);
    int256 netWbtc = int256(wbtcAfter) - int256(wbtcBefore);
    // At minimum the liquidator should not lose tokens when position was solvent-enough
    t(netUsdc + int256(netWbtc * int256(INIT_WBTC_PRICE) / int256(1e18)) >= 0,
      "liquidator lost money on liquidation — borrowedValue wrong decimals makes profit calc incorrect");
}

