function property_pull_push_balance_consistency() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    // record state before pull
    uint256 underlyingBefore = IERC20(asset).balanceOf(yAddr);

    // pull a small amount
    uint256 pullAmt = underlyingBefore / 10;
    if (pullAmt == 0) return;

    _pullFunds(asset, pullAmt);

    // After pull: actual balance should have decreased, but underlyingBalance may not match
    uint256 underlyingAfter = IERC20(asset).balanceOf(yAddr);

    // The tracked availableLiquidity must equal actual token balance
    uint256 tracked = lendingPool.totalLiquidityOfReserve(asset) - lendingPool.totalBorrowsOfReserve(asset);

    // push back to restore
    deal(asset, address(mockLeverager), pullAmt);
    _pushFunds(asset, pullAmt);

    // Property: tracked available liquidity must always equal real token balance in yToken
    t(
        underlyingAfter <= underlyingBefore,
        "pullFunds: real balance did not decrease"
    );
    t(
        tracked == underlyingAfter,
        "pullFunds: underlyingBalance not decremented, tracked != actual"
    );
