function property_no_double_spend_via_pull_then_borrow_token0() public {
    // After any sequence of operations, the leverager (mockLeverager) should not hold
    // more token0 than was ever explicitly tracked as borrowed (totalBorrows).
    // Tokens obtained through pullFunds are untracked — combining pullFunds + borrow
    // allows the leverager to hold totalBorrows + pullAmount simultaneously while the
    // pool's accounting only sees totalBorrows.
    //
    // This property checks the combined solvency: all tokens not in the yToken contract
    // should be accounted for in totalBorrows. If the leverager holds extra untracked
    // tokens (from pullFunds), realAssets < reportedLiabilities.
    uint256 realAssets   = _yTokenUnderlyingBalance(address(token0))
                         + _getTotalBorrows(address(token0));
    uint256 totalLiab    = _getTotalLiquidity(address(token0));
    eq(realAssets, totalLiab,
        "token0: real assets != liabilities — possible pullFunds+borrow double-spend");
}

function property_pull_funds_respects_pause_token0() public {
    // When the contract is paused, no token extraction should be possible.
    // If paused == true, the actual yToken balance should not be reducible via pullFunds.
    // We check: after any operation sequence, if paused, yToken balance must not have
    // decreased from the value recorded at the start of this check.
    //
    // Since we cannot snapshot across calls in a single property function, we instead
    // verify that the accounting is consistent (a necessary condition for correctness)
    // which would catch post-pause pullFunds corruption.
    if (lendingPool.paused()) {
        uint256 actualBalance     = _yTokenUnderlyingBalance(address(token0));
        uint256 underlyingBalance = _getTotalLiquidity(address(token0))
                                  - _getTotalBorrows(address(token0));
        eq(actualBalance, underlyingBalance,
            "token0: accounting desync while paused — pullFunds called during pause?");
    }
}

function property_exchange_rate_not_inflated_beyond_real_backing_token0() public {
    uint256 totalYTokens = _getYTokenTotalSupply(address(token0));
    if (totalYTokens == 0) return;

    // Real backing per yToken (in PRECISION units):
    uint256 realAssets  = _yTokenUnderlyingBalance(address(token0))
                        + _getTotalBorrows(address(token0));
    uint256 realRate    = realAssets * PRECISION / totalYTokens;

    // Reported exchange rate (uses underlyingBalance which may be inflated):
    uint256 reportedRate = _getExchangeRate(address(token0));

    // Reported rate must not exceed real rate by more than 1 wei (rounding tolerance).
    // If pullFunds inflated underlyingBalance, reportedRate > realRate.
    gte(realRate + 1, reportedRate,
        "token0: exchange rate inflated beyond real asset backing");
}

function property_exchange_rate_not_inflated_beyond_real_backing_token1() public {
    uint256 totalYTokens = _getYTokenTotalSupply(address(token1));
