}

function property_utilization_rate_bounded_token0() public {
    uint256 uRate = _getUtilizationRate(address(token0));
    // Utilization rate must be in [0, PRECISION] (i.e., [0%, 100%]).
    gte(PRECISION, uRate, "token0: utilization rate exceeds 100%");

    // Additionally, utilization should reflect real borrows vs real assets.
    // If underlyingBalance is inflated, uRate is artificially low, masking true utilization.
    uint256 realAssets  = _yTokenUnderlyingBalance(address(token0))
                        + _getTotalBorrows(address(token0));
    if (realAssets > 0) {
        uint256 realURate = _getTotalBorrows(address(token0)) * PRECISION / realAssets;
        // Reported utilization must not be lower than real utilization by more than
        // a rounding tolerance. If pullFunds inflated underlyingBalance, uRate << realURate.
        gte(uRate + PRECISION / 10_000, realURate,
            "token0: reported utilization is materially lower than real utilization");
    }
}

