function property_deposit_no_rounding_loss() public {
    // Depositor deposits tokens proportional to current balances
    (uint256 bal0Before, uint256 bal1Before) = _vaultBalances();
    uint256 totalSupplyBefore = _vaultTotalSupply();

    if (totalSupplyBefore == 0 || bal0Before == 0 || bal1Before == 0) return;

    // Compute what a fair deposit should yield (floor division = shares formula)
    // Depositor provides exactly proportional amounts
    uint256 amount0In = ONE_TOKEN0;
    uint256 amount1In = (ONE_TOKEN0 * bal1Before) / bal0Before;

    (uint256 shares, uint256 dep0, uint256 dep1) = _dealAndDeposit(attacker, amount0In, amount1In * 2);

    // Check: depositor should not have paid more than the pro-rata amount
    // dep0/dep1 are what was actually taken; shares * bal0Before / totalSupplyBefore is fair amount
    uint256 fairAmount0 = bal0Before * shares / totalSupplyBefore;
    uint256 fairAmount1 = bal1Before * shares / totalSupplyBefore;

    // Allow 1 wei tolerance per token — more than 1 wei overpay is extraction
    t(dep0 <= fairAmount0 + 1, "depositor overpaid token0 by more than 1 wei");
    t(dep1 <= fairAmount1 + 1, "depositor overpaid token1 by more than 1 wei");
}

function property_first_deposit_share_ratio_sane() public {
    // After the initial deposit in setUp, the vault should have a
    // reasonable share-to-balance ratio for both tokens.
    // If price() = token1/token0, then a share should be worth
    // approximately equal amounts of each token at current price.
    uint256 supply = _vaultTotalSupply();
    (uint256 bal0, uint256 bal1) = _vaultBalances();

    if (supply == 0 || bal0 == 0 || bal1 == 0) return;

    // Cross-check: bal0/supply * price ≈ bal1/supply
    // i.e., value per share in token0 ≈ value per share in token1 (in USD terms)
    // Use vault's own price: price() returns token1/token0 in 1e30 precision
    uint256 p = _vaultPrice();

    // token0 value per share (in token1 terms) = (bal0 * p / 1e30) / supply
    // token1 value per share = bal1 / supply
    // These need not be equal but both should be nonzero
    uint256 value0PerShare = bal0 * p / 1e30 / supply;
    uint256 value1PerShare = bal1 / supply;

    // Both should be nonzero — if either is 0, the vault is entirely single-sided
    // after rebalance, which is unusual
    t(value0PerShare > 0 || value1PerShare > 0, "all share value is in one token");
}

