function property_skipToken_advances_path() public {
    // Construct a 2-pool path: tokenA (20) + fee (3) + tokenB (20) + fee (3) + tokenC (20) = 66 bytes
    // MULTIPLE_POOLS_MIN_LENGTH = 20 + 3 + 20 + 3 + 20 = 66
    bytes memory multiHopPath = abi.encodePacked(
        address(wbtc),   // 20 bytes
        uint24(3000),    // 3 bytes
        address(weth),   // 20 bytes
        uint24(3000),    // 3 bytes
        address(usdc)    // 20 bytes
    );
    // After one skipToken, path should advance by NEXT_OFFSET = 23 bytes
    // and hasMultiplePools() should return false (remaining = 43 bytes < 66)
    // The loop in _getTokenIn should terminate.
    // We verify by checking that calling _getTokenIn does NOT run out of gas.
    // If the loop is infinite, this call will OOG; property fails by exception.
    // We call with a gas limit proxy: just calling any internal function that uses _getTokenIn.
    // Since _getTokenIn is internal, we test path.skipToken() behavior directly:
    bytes memory path = multiHopPath;
    bool hadMultiple = path.hasMultiplePools();
    t(hadMultiple, "path should have multiple pools");
    bytes memory after1 = path.skipToken();
    bool stillMultiple = after1.hasMultiplePools();
    // After skipping one token+fee (23 bytes), 66-23=43 bytes remain, < 66 => false
    t(!stillMultiple, "path should NOT have multiple pools after one skip");
    // The BUG: if caller does `path.skipToken()` (ignoring return), path.length stays 66
    // This property verifies the skip actually shrinks the path
    t(after1.length == multiHopPath.length - 23, "skipped path must be 23 bytes shorter");
}

