function property_DDH001_vesting_fees_use_correct_ticks() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If ticks have diverged after a rebalance, the bug is active
    if (vp.tickUpper == mp.tickUpper) return; // ticks still match, skip

    // The vesting position at its REAL ticks should have accumulated fees
    // collectFees currently uses mainPosition.tickUpper (wrong) which hits
    // a phantom range and returns 0 fees.
    // A correct collectFees would use vestPosition.tickUpper.

    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // After collectFees with WRONG ticks, the vesting position's own fees
    // are NOT included. We document this by checking that idle didn't increase
    // from vesting fees — but because we can't know the expected fee amount,
    // we use the structural check: vestPosition.tickUpper != mainPosition.tickUpper
    // means fees were collected from wrong range.
    // The correct invariant: collectFees should NEVER use mainPosition.tickUpper
    // for the vesting position when ticks have diverged.
    t(
        vp.tickUpper == mp.tickUpper,
        "DDH-001: collectFees uses mainPosition.tickUpper for vesting position fee collection - wrong ticks after rebalance cause permanent fee loss"
    );
}

function property_DDH002_depositor_cannot_profit_from_vesting_dilution() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return;

    // Record state before attacker deposits
    uint256 supplyBefore = vault.totalSupply();
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();

    // Attacker deposits amount proportional to current (understated) TVL
    uint256 dep0 = bal0Before; // match current TVL exactly to get 50% shares
    uint256 dep1 = bal1Before;
    deal(address(wbtc), attacker, dep0);
    deal(address(usdc), attacker, dep1);
    vm.startPrank(attacker);
    (uint256 shares,,) = vault.deposit(dep0, dep1, 0, 0);
    vm.stopPrank();

    // Advance time to partially vest
    skip(1 days);

    // Collect fees to release vested liquidity
    strategy.collectFees();

    uint256 totalSupplyAfter = vault.totalSupply();
    (uint256 bal0After, uint256 bal1After) = vault.balances();

    // Attacker's proportional claim should not exceed what they deposited
    uint256 attackerClaim0 = bal0After * shares / totalSupplyAfter;
    uint256 attackerClaim1 = bal1After * shares / totalSupplyAfter;

    // Allow up to 1% tolerance for swap fees/rounding
    lte(attackerClaim0, dep0 * 101 / 100, "DDH-002: attacker extracted excess WBTC from vesting dilution");
    lte(attackerClaim1, dep1 * 101 / 100, "DDH-002: attacker extracted excess USDC from vesting dilution");
}

function property_DDH003_position_width_requires_owner_approval() public {
    uint24 widthBefore = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();

    // Try the MINIMUM valid width (2 * tickSpacing): halfWidth = tickSpacing, divisible by tickSpacing
    uint24 minValidWidth = uint24(2 * uint24(ts));
    require(minValidWidth != widthBefore, "skip: already at min width");

    // Rebalancer (not owner) can change positionWidth unilaterally
    // This documents the access control gap: rebalancer has more power than intended
    skip(10 minutes); // ensure rebalanceInterval has passed
    vm.prank(rebalancer);
    try strategy.changePositionWidth(minValidWidth) {
        // If we reach here: rebalancer changed positionWidth without owner consent
        // This is the vulnerable path — rebalancer now controls vault risk geometry
        uint24 widthAfter = strategy.positionWidth();
        // Document: owner did NOT approve this change
        // The invariant that ONLY the owner should control position parameters is violated
        t(
            widthAfter == widthBefore,
            "DDH-003: rebalancer changed positionWidth without owner approval - privilege escalation"
        );
    } catch {
        // Revert means interval not elapsed or price out of range — skip
    }
}

function property_DDH004_withdrawal_accounts_for_vesting_position() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return;

    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 totalSupply = vault.totalSupply();

    // Compute fair withdrawal value including vesting position
    (uint256 bal0, uint256 bal1) = vault.balances(); // excludes vesting

    // Get vesting position value at current spot price
    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
    (uint256 vest0, uint256 vest1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    uint256 trueTotal0 = bal0 + vest0;
    uint256 trueTotal1 = bal1 + vest1;

    uint256 fairWithdraw0 = trueTotal0 * userShares / totalSupply;
    uint256 fairWithdraw1 = trueTotal1 * userShares / totalSupply;

    uint256 wbtcBefore = wbtc.balanceOf(user);
    uint256 usdcBefore = usdc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    uint256 received0 = wbtc.balanceOf(user) - wbtcBefore;
    uint256 received1 = usdc.balanceOf(user) - usdcBefore;

    // User should receive at least 95% of fair value (allowing some slippage)
    // If this fails, user was cheated out of their vesting position share
    gte(
        received0 * 100,
        fairWithdraw0 * 95,
        "DDH-004: withdrawal returned less than fair share of vault value (vesting position excluded)"
    );
    gte(
        received1 * 100,
        fairWithdraw1 * 95,
        "DDH-004: withdrawal returned less than fair share of vault value (vesting position excluded)"
    );
}

function property_DDH005_no_panic_on_deposit_same_block_as_vesting() public {
    // Check: after a first deposit when balances are (0,0), subsequent same-block
    // deposit should not panic (but may revert gracefully with require).

    // Set up: Deploy fresh vault+strategy where no rebalance has happened yet
    // so main/secondary have 0 liquidity.
    vm.startPrank(owner);
    Vault freshVault = new Vault(address(wbtc), address(usdc));
    Strategy freshStrategy = new Strategy(
        address(pool), address(freshVault), rebalancer, feeRecipient
    );
    freshVault.setStrategy(address(freshStrategy));
    vm.stopPrank();

    // First deposit (totalSupply == 0, balances == 0,0 since no rebalance)
    deal(address(wbtc), user, ONE_TOKEN0);
    deal(address(usdc), user, ONE_TOKEN1 * 100_000);
    vm.startPrank(user);
    wbtc.approve(address(freshVault), ONE_TOKEN0);
    usdc.approve(address(freshVault), ONE_TOKEN1 * 100_000);
    freshVault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 100_000, 0, 0);
    vm.stopPrank();

    // Now totalSupply > 0 but balances() = (0,0) because no positions exist yet
    // Same block, second deposit — should get a require revert, NOT a panic
    deal(address(wbtc), depositor, ONE_TOKEN0);
    deal(address(usdc), depositor, ONE_TOKEN1 * 100_000);
    vm.startPrank(depositor);
    wbtc.approve(address(freshVault), ONE_TOKEN0);
    usdc.approve(address(freshVault), ONE_TOKEN1 * 100_000);

    // The assert on line 127 will PANIC here, burning all gas
    // This property documents that it should revert gracefully instead
    try freshVault.deposit(ONE_TOKEN0, ONE_TOKEN1 * 100_000, 0, 0) returns (uint256 s, uint256, uint256) {
        t(s > 0, "DDH-005: deposit should succeed with non-zero shares if it doesn't panic");
    } catch (bytes memory revertData) {
        // A graceful require revert is OK (e.g., "shares cant be 0")
        // A Panic(0x01) from assert is NOT OK — it burns all gas
        // We check: if revertData starts with Panic selector 0x4e487b71, the assert fired
        if (revertData.length >= 4) {
            bytes4 selector = bytes4(revertData[0]) | (bytes4(revertData[1]) >> 8) |
                              (bytes4(revertData[2]) >> 16) | (bytes4(revertData[3]) >> 24);
            // Panic selector = 0x4e487b71
            t(
                bytes4(revertData) != bytes4(0x4e487b71),
                "DDH-005: deposit triggered assert PANIC instead of graceful require revert"
            );
        }
    }
    vm.stopPrank();
}

function property_DDH006_no_reentrancy_on_withdraw() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    // Record pre-state
    uint256 totalSupplyBefore = vault.totalSupply();
    uint256 userSharesBefore = vault.balanceOf(user);
    uint256 wbtcBefore = wbtc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    // Post-state invariants:
    // 1. User shares are zero (burned)
    eq(vault.balanceOf(user), 0, "DDH-006: user shares not burned after withdraw");

    // 2. Total supply decreased by exactly userShares
    eq(
        totalSupplyBefore - vault.totalSupply(),
        userSharesBefore,
        "DDH-006: totalSupply decrease does not match burned shares"
    );

    // 3. User received tokens (non-zero if vault had balance)
    (uint256 bal0,) = vault.balances();
    if (bal0 > 0 && totalSupplyBefore > userShares) {
        // Vault still has balance for remaining holders
        t(wbtc.balanceOf(user) > wbtcBefore, "DDH-006: user received no WBTC after withdraw");
    }
}

