    // collectFees should distribute all remaining liquidity
    if (!strategy.ongoingVestingPosition()) return;

    (,,,, uint256 startTs, uint256 endTs,) = strategy.vestPosition();
    if (block.timestamp < endTs) return;

    // Vesting has ended but may not be collected yet
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();
    strategy.collectFees();
    (uint256 bal0After, uint256 bal1After) = vault.balances();

    // After collectFees at or after endTs, ongoingVestingPosition should be false
    t(!strategy.ongoingVestingPosition(), "vesting position not cleared after end");

