/// @notice After a full withdraw of a USDC-denomination position, the lending
///         pool's totalBorrows for USDC must decrease by the full owed amount.
///         The bug causes an undercount: protocol receives less repayment than owed.
function prop_withdrawUsdcDenomRepaysFullDebt(uint256 seed) public {
    uint256 posId = _pickPositionId(seed);
    if (posId == 0) return;

    ILeverager.Position memory pos = _getPosition(posId);
    if (pos.denomination != address(usdc)) return;
    if (pos.borrowedAmount == 0) return;

    // snapshot lending-pool borrows before withdrawal
    uint256 borrowsBefore = _getTotalBorrows(address(usdc));
    uint256 bIndex        = _getCurrentBorrowingIndex(address(usdc));
    uint256 owedAmount    = pos.borrowedAmount * bIndex / pos.borrowedIndex;

    address posOwner = leverager.ownerOf(posId);

    // deal the owner extra USDC so it can cover any shortfall (repay from wallet)
    deal(address(usdc), posOwner, usdc.balanceOf(posOwner) + owedAmount * 2);

    vm.startPrank(posOwner);
    usdc.approve(address(leverager), type(uint256).max);
    wbtc.approve(address(leverager), type(uint256).max);

    ILeverager.WithdrawParams memory wp;
    wp.id          = posId;
    wp.pctWithdraw = 1e18; // 100%
    wp.minAmount0  = 0;
    wp.minAmount1  = 0;
    wp.hasToSwap   = false;

    try leverager.withdraw(wp) {
        // If withdraw succeeded, position must be gone and borrows must have fallen
        uint256 borrowsAfter = _getTotalBorrows(address(usdc));
        // borrows should have decreased by at least owedAmount (minus any rounding)
        t(borrowsBefore >= borrowsAfter, "DDH-LEV-002: USDC borrows did not decrease after full withdraw");
        // Difference should be close to owedAmount; if the bug fires, repayment is short
        uint256 repaid = borrowsBefore - borrowsAfter;
        gte(repaid, owedAmount * 99 / 100, "DDH-LEV-002: repaid amount < 99% of owed — underpayment due to wrong variable");
    } catch {
        // revert is also a manifestation of the bug (underflow path)
    }
    vm.stopPrank();

    _removePositionId(posId);
}

/// @notice Demonstrates the wrong-variable bug by showing that the formula
///         used in the token1 branch is NOT equivalent to the token0 branch's formula.
///         For token0: repayFromWithdraw = amountOut0 < owedAmount ? amountOut0 : owedAmount  (correct)
///         For token1: repayFromWithdraw = amountOut1 < owedAmount ? amountOut0 : owedAmount  (WRONG)
///         The two branches should be symmetric; this property flags the asymmetry.
function prop_withdrawRepayBranchSymmetry() public pure {
    // Symbolic check: for a0=50, a1=30, owed=100
    // token0 branch: repay = min(50,100) = 50   -> owedAmount=50, amountOut0=0   (correct)
    // token1 branch (buggy): repay = (30<100)?50:100 = 50  -> owedAmount=50, amountOut1=30-50 UNDERFLOW
    uint256 a0 = 50e6;
    uint256 a1 = 30e6;
    uint256 owed = 100e6;

    // Correct token1 logic
    uint256 correctRepay = a1 < owed ? a1 : owed; // 30
    // Buggy token1 logic (as coded)
    uint256 buggyRepay   = a1 < owed ? a0 : owed; // 50

    t(correctRepay == buggyRepay,
      "DDH-LEV-002: token1 withdraw branch uses amountOut0 (buggy) instead of amountOut1 (correct)");
}

/// @notice The liquidation borrowedValue calculation must use 10**decimals,
///         not the raw decimals() return value.
///         We verify this by reconstructing both computations and asserting equality.
function prop_liquidationBorrowedValueCorrectDecimals(uint256 seed) public view {
    uint256 posId = _pickPositionId(seed);
    if (posId == 0) return;

    ILeverager.Position memory pos = _getPosition(posId);
    if (pos.denomination == address(0)) return;

    uint256 bPrice     = priceFeed.getPrice(pos.denomination);
    uint256 bIndex     = _getCurrentBorrowingIndex(pos.denomination);
    uint256 owedAmount = pos.borrowedAmount * bIndex / pos.borrowedIndex;
    if (owedAmount == 0) return;

    uint8  rawDec     = ERC20(pos.denomination).decimals();
    uint256 scaledDec = 10 ** uint256(rawDec);

    // Buggy calculation (as coded in liquidatePosition line 318)
    uint256 buggyBorrowedValue   = owedAmount * bPrice / uint256(rawDec);
    // Correct calculation (matches isLiquidateable approach)
    uint256 correctBorrowedValue = owedAmount * bPrice / scaledDec;

    // These must be equal; they aren't unless decimals == 1
    eq(buggyBorrowedValue, correctBorrowedValue,
       "DDH-LEV-003: liquidatePosition uses raw decimals() instead of 10**decimals() — borrowedValue massively inflated");
}

/// @notice After a liquidation, if the collateral value exceeds the debt, feeRecipient
///         should have received protocol fees (liquidationFee > 0).
///         Because the decimals bug inflates borrowedValue, the profit branch is never
///         entered and fees are always zero — even for deeply profitable liquidations.
function prop_liquidationFeesCollectedOnProfitableLiquidation(uint256 seed) public {
    uint256 posId = _pickPositionId(seed);
    if (posId == 0) return;
    if (!leverager.isLiquidateable(posId)) return;

    ILeverager.Position memory pos = _getPosition(posId);
    address fr = leverager.feeRecipient();

    uint256 fr0Before = IERC20(pos.token0).balanceOf(fr);
    uint256 fr1Before = IERC20(pos.token1).balanceOf(fr);

    _liquidatePosition(liquidator, posId);

    // If liquidation succeeded and feeRecipient is non-zero, check fees
    if (fr == address(0)) return; // DDH-LEV-001 would fire first

    uint256 fr0After = IERC20(pos.token0).balanceOf(fr);
    uint256 fr1After = IERC20(pos.token1).balanceOf(fr);

    // Fees MIGHT be 0 if liquidationFee==0, but with any nonzero fee and
    // profitable liquidation the bug (DDH-LEV-003) always produces 0 fees.
    // We record the observation; a fuzzer finding fr0After==fr0Before AND
    // fr1After==fr1Before for profitable liquidations confirms the bug.
    // (This property intentionally does NOT assert to allow state exploration.)
    _ = fr0After >= fr0Before; // fees can only increase
    _ = fr1After >= fr1Before;
    t(fr0After >= fr0Before, "DDH-LEV-003: feeRecipient token0 balance decreased after liquidation");
    t(fr1After >= fr1Before, "DDH-LEV-003: feeRecipient token1 balance decreased after liquidation");

    _removePositionId(posId);
}

/// @notice No position in positionIds that was just opened should be liquidateable
///         before any time passes or price changes occur.
///         We verify the global invariant: isLiquidateable should be false
///         immediately after openLeveragedPosition returns.
function prop_noImmediateLiquidation(uint256 seed) public {
    // Open a small WBTC-denomination position
    uint256 posId = _openLeveragedPositionDenomWbtc(
