        0.4e8,       // 0.4 WBTC vault deposit (flashloaned)
        0.8e8        // borrow 0.8 WBTC; net borrow ≈ 0.4 WBTC
    );
    if (posId == 0) return; // open failed (valid for many fuzzer inputs)

    bool liq = leverager.isLiquidateable(posId);
    t(!liq, "DDH-LEV-005: position liquidateable immediately after opening");

    _removePositionId(posId);
}

/// @notice LendingPool.totalBorrows for WBTC and USDC must each be >=
///         the sum of owed amounts across all tracked positions denominated in that asset.
function prop_totalBorrowsGeqSumOwed() public view {
    uint256 sumOwedWbtc;
    uint256 sumOwedUsdc;

    uint256 wbtcIndex = _getCurrentBorrowingIndex(address(wbtc));
    uint256 usdcIndex = _getCurrentBorrowingIndex(address(usdc));

    for (uint256 i = 0; i < positionIds.length; i++) {
        uint256 pid = positionIds[i];
        ILeverager.Position memory pos = _getPosition(pid);
        if (pos.borrowedIndex == 0) continue;

        uint256 owed = pos.borrowedAmount * (pos.denomination == address(wbtc) ? wbtcIndex : usdcIndex)
                       / pos.borrowedIndex;

        if (pos.denomination == address(wbtc)) {
            sumOwedWbtc += owed;
        } else if (pos.denomination == address(usdc)) {
            sumOwedUsdc += owed;
        }
    }

    uint256 totalWbtcBorrows = _getTotalBorrows(address(wbtc));
    uint256 totalUsdcBorrows = _getTotalBorrows(address(usdc));

    gte(totalWbtcBorrows, sumOwedWbtc,
        "DDH-LEV-006: totalBorrows(WBTC) < sum of owed WBTC across positions — bad debt");
    gte(totalUsdcBorrows, sumOwedUsdc,
        "DDH-LEV-006: totalBorrows(USDC) < sum of owed USDC across positions — bad debt");
}

function property_collect_fees_uses_correct_vest_ticks() public {
    // Set up a vesting position and then rebalance to shift main ticks
    _addVestingPosition(1e7, 10_000e6, 7 days);

    // Rebalance to move main position ticks away from vest position ticks
    skip(rebalanceInterval + 1);
    // Swap to move the price slightly so ticks shift
    _swapWbtc(1e6);
    _rebalance();

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If the ticks differ (they should after rebalance), collectFees will use wrong upper tick
    // The vest position upper tick must NOT be the main position upper tick (they diverged)
    // Property: after rebalance the fee collection should still work correctly
    // We verify that vest tickUpper is unchanged (it should remain at old main tickUpper)
    // while mainPosition tickUpper has moved
    if (vp.tickUpper != mp.tickUpper) {
        // Collect fees — this should not revert and should actually collect from vestPosition
        // The bug: it collects from (vestPosition.tickLower, mainPosition.tickUpper) instead
        // of (vestPosition.tickLower, vestPosition.tickUpper)
        uint256 pre0 = wbtc.balanceOf(address(strategy));
        uint256 pre1 = usdc.balanceOf(address(strategy));
        strategy.collectFees();
        // After collecting, ongoing vesting should still be true if time hasn't elapsed
        t(strategy.ongoingVestingPosition(), "vesting position should still be ongoing");
    }
}

function property_secondary_position_ticks_valid() public {
    // After rebalance, secondary position should have tickLower < tickUpper
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    t(sp.tickLower < sp.tickUpper, "secondary tickLower must be < tickUpper");

    // Secondary position should be OOR (out of range)
    // Either entirely below or above current tick
    (, int24 currentTick,,,,,) = pool.slot0();
    bool belowRange = sp.tickUpper <= currentTick;
    bool aboveRange = sp.tickLower >= currentTick;
    t(belowRange || aboveRange, "secondary position should be out of range");
}

function property_vesting_position_fully_released_over_time() public {
    uint256 duration = 7 days;
    _addVestingPosition(1e7, 10_000e6, duration);

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    uint128 initialLiquidity = vp.initialLiquidity;

