    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(uint256(vpAfter.remainingLiquidity), 0, "all vesting liquidity should be released");
}

function property_protocol_fee_not_charged_on_vesting_withdrawal() public {
    _addVestingPosition(1e7, 10_000e6, 7 days);

    skip(1 days); // Let some vesting pass

    uint256 feeRecipient0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipient1Before = usdc.balanceOf(feeRecipient);

    uint256 strat0Before = wbtc.balanceOf(address(strategy));
    uint256 strat1Before = usdc.balanceOf(address(strategy));

    strategy.collectFees();

    uint256 feeRecipient0After = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipient1After = usdc.balanceOf(feeRecipient);
    uint256 strat0After = wbtc.balanceOf(address(strategy));
    uint256 strat1After = usdc.balanceOf(address(strategy));

    // Protocol fee should be <= 15% of the new tokens collected (excluding vested tokens)
    uint256 gained0 = strat0After > strat0Before ? strat0After - strat0Before : 0;
    uint256 gained1 = strat1After > strat1Before ? strat1After - strat1Before : 0;
    uint256 fees0 = feeRecipient0After - feeRecipient0Before;
    uint256 fees1 = feeRecipient1After - feeRecipient1Before;

    lte(fees0, gained0 * 1500 / 10000, "protocol fee for token0 should not exceed 15%");
    lte(fees1, gained1 * 1500 / 10000, "protocol fee for token1 should not exceed 15%");
}

