function property_collectFees_usesCorrectVestingTickUpper() public returns (bool) {
    // This property captures the code's implicit assumption: collectFees uses
    // mainPosition.tickUpper for the vesting position, which is only valid when
    // vestPosition.tickUpper == mainPosition.tickUpper.
    // After any rebalance, these diverge — violation confirmed.
    if (!strategy.ongoingVestingPosition()) return true;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // collectFees at line 167 passes mainPosition.tickUpper as the upper tick for
    // the vesting position. The vesting position was minted at vestPosition.tickUpper.
    // These must be equal, otherwise the wrong pool position is targeted.
    return vp.tickUpper == mp.tickUpper;
}

function property_onlyOwnerCanChangePositionWidth() public returns (bool) {
    uint24 originalWidth = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();
    // Compute a valid new width: half-width must be divisible by tickSpacing
    uint24 newWidth = uint24(ts) * 6; // halfWidth = 3*tickSpacing, divisible by tickSpacing
    if (newWidth == originalWidth) newWidth = uint24(ts) * 8;

    // Advance time past rebalance interval so rebalance() won't revert on timing
    skip(strategy.rebalanceInterval() + 1);

    // Attempt changePositionWidth as the rebalancer (not owner) — this should revert
    vm.prank(rebalancer);
    try strategy.changePositionWidth(newWidth) {
        // If execution reaches here, rebalancer changed positionWidth — access control violated
        return strategy.positionWidth() == originalWidth; // false → confirms violation
    } catch {
        // Correctly reverted — access control is working
        return true;
    }
}

function property_secondaryPositionTicksAlwaysValid() public returns (bool) {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    // A valid Uniswap V3 position requires tickLower < tickUpper strictly.
    // If secondaryPosition.liquidity == 0, ticks may not matter, but they should still
    // be structurally valid for future use.
    if (sp.liquidity == 0) return true;
    return sp.tickLower < sp.tickUpper;
}

function property_checkPoolActivityNeverReverts() public returns (bool) {
    // checkPoolActivity() should always return a bool, never revert.
    // If it reverts (e.g., "timestamp 0" or division by zero), this property returns false.
    try strategy.checkPoolActivity() returns (bool) {
        return true;
    } catch {
        return false;
    }
}

function property_collectFeesCallerIsRestricted() public returns (bool) {
    // collectFees() should only be callable by trusted parties (vault, rebalancer, or owner).
    // This property demonstrates it is callable by an arbitrary attacker.
    skip(1 hours); // let some time pass so _withdrawPartOfVestingPosition does something

    vm.prank(attacker);
    try strategy.collectFees() {
        // Attacker successfully executed fee collection — access control absent
        return false;
    } catch {
        // Correctly reverted — would indicate access control present
        return true;
    }
}

function property_secondaryPositionIsFullyOOR() public returns (bool) {
    // After a rebalance, the secondary position must be entirely Out-Of-Range.
    // OOR means the current tick is either below tickLower or >= tickUpper.
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return true;

    (, int24 currentTick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    // Fully OOR: currentTick must be strictly outside [tickLower, tickUpper)
    bool belowRange = currentTick < sp.tickLower;
    bool aboveRange = currentTick >= sp.tickUpper;
    return belowRange || aboveRange;
}

function property_vestedLiquidityMonotonicallyIncreases() public returns (bool) {
    if (!strategy.ongoingVestingPosition()) return true;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    uint128 remainingBefore = vpBefore.remainingLiquidity;

    // Advance 1 second and collect once
    skip(1);
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    uint128 remainingAfter = vpAfter.remainingLiquidity;

    // Advance another 1 second and collect once more
    skip(1);
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter2 = strategy.getVestingPosition();
    uint128 remainingAfter2 = vpAfter2.remainingLiquidity;

    // remainingLiquidity must strictly decrease over time (never stay the same or increase)
    // Violation: if two consecutive calls with time passage don't reduce remaining liquidity,
    // truncation caused a zero-liquidity-removed call
    if (vpAfter.lastUpdate != vpBefore.lastUpdate && remainingAfter == remainingBefore) {
        return false; // Expected removal but got zero — truncation to zero
    }
    if (vpAfter2.lastUpdate != vpAfter.lastUpdate && remainingAfter2 == remainingAfter) {
        return false;
    }
    return true;
}

function property_vesting_fees_collected_correctly() public {
    // Setup: call collectFees, then check that vest position's own tick range
    // was actually hit. We verify indirectly: after collectFees, if we manually
    // call collect on the correct vesting position range, there should be nothing left.
    // This property checks that collectFees uses vestPosition.tickUpper, not mainPosition.tickUpper.
    (int24 vestLower, int24 vestUpper, , , , , ) = strategy.getVestingPosition();
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    // Record idle balances before
    (uint256 idleBefore0, uint256 idleBefore1) = strategy.idleBalances();

    // Trigger collectFees
    strategy.collectFees();

    // After collectFees, manually collect the correct vesting position range
    // If collectFees used the wrong tickUpper, there will still be uncollected fees
    // in the real vest position range. We check: main and vest ticks must differ
    // after a rebalance.
    (int24 mainLower, int24 mainUpper, ) = strategy.getMainPosition();
    // The bug: if mainUpper != vestUpper, collectFees used wrong range
    t(mainUpper == vestUpper || vestLower == mainLower,
      "collectFees used wrong tick range for vesting position");
}

function property_balances_includes_vesting_position() public {
    // When there is an ongoing vesting position with remaining liquidity,
    // the vault's reported total balances should account for it.
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    // The strategy balances include main + secondary + idle, but NOT the vesting position.
    // bal0 and bal1 should be strictly greater than idle if vesting position has liquidity,
    // but they could still miss the vesting position entirely.
    // We check: vesting position has remaining liquidity, so balances must be > idle alone.
    ( , , uint128 initLiq, uint128 remainLiq, , , ) = strategy.getVestingPosition();
    if (remainLiq > 0) {
        // If balances == idle, the vesting position is completely omitted
        t(bal0 > idle0 || bal1 > idle1 || remainLiq == 0,
          "balances() omits vesting position entirely when there is remaining liquidity");
    }
}

function property_deposit_no_excess_charge() public {
    // After deposit, the depositor's share of balances should be >= what they deposited
    uint256 amount0In = ONE_TOKEN0;
    uint256 amount1In = ONE_TOKEN1 * 50_000; // 50k USDC

    deal(address(wbtc), attacker, amount0In);
    deal(address(usdc), attacker, amount1In);

    (uint256 bal0Before, uint256 bal1Before) = vault.balances();
    uint256 supplyBefore = vault.totalSupply();

    vm.startPrank(attacker);
    wbtc.approve(address(vault), amount0In);
    usdc.approve(address(vault), amount1In);
    (uint256 shares, uint256 deposited0, uint256 deposited1) = vault.deposit(amount0In, amount1In, 0, 0);
    vm.stopPrank();

    uint256 supplyAfter = vault.totalSupply();
    (uint256 bal0After, uint256 bal1After) = vault.balances();

    // Depositor's fair share of new balances
    uint256 fairBal0 = bal0After * shares / supplyAfter;
    uint256 fairBal1 = bal1After * shares / supplyAfter;

    // Depositor should not pay more than their fair share (allow 1 wei rounding)
    lte(deposited0, fairBal0 + 2, "depositor over-charged on token0");
    lte(deposited1, fairBal1 + 2, "depositor over-charged on token1");
}

function property_withdraw_includes_vesting_share() public {
    // When vesting position exists and user has shares, withdrawn value should
    // approximate user's pro-rata of total vault value including vesting position.
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 totalSupply = vault.totalSupply();

    // Get real balances including vesting
    (uint256 mainBal0, uint256 mainBal1) = vault.balances(); // omits vesting - this is the bug
    // Vest position liquidity
    ( , , , uint128 remainLiq, , , ) = strategy.getVestingPosition();

    // If there's remaining vesting liquidity > 0, withdrawing user loses that share
    if (remainLiq > 0) {
        // The amount withdrawn should reflect a proportional share of total value
        // Since balances() omits vesting position, withdrawals are less than fair share
        // We flag this as a property violation
        (uint256 w0, uint256 w1) = _withdrawAs(user, userShares);
        // User got w0, w1. Fair would include vesting share.
        // Check: if remainLiq > 0 and user had non-zero shares, they got shortchanged
        // We can only check indirectly: the vault should be empty if user was sole depositor
        if (totalSupply == userShares + 1000) { // user was essentially all of supply (minus burn)
            // After full withdrawal, vault should be nearly empty
            (uint256 left0, uint256 left1) = vault.balances();
            // But vesting position still has liquidity — user got less than they should
            t(remainLiq == 0 || left0 == 0, "vesting position value not returned on withdraw");
        }
    }
}

function property_pullpush_preserves_underlying_balance() public {
    address asset = address(token0);
    uint256 pullAmount = 1_000 * ONE_TOKEN0;

    // record underlyingBalance before
    address yAddr = lendingPool.getYTokenAddress(asset);
    uint256 yTokenBalBefore = IERC20(asset).balanceOf(yAddr);

    // pull funds via leverager
    _pullFunds(asset, pullAmount);

    // underlyingBalance should have decreased by pullAmount
    uint256 yTokenBalAfter = IERC20(asset).balanceOf(yAddr);
    // The actual token balance in yToken decreased
    lte(yTokenBalAfter, yTokenBalBefore - pullAmount, "yToken underlying did not decrease after pullFunds");

    // But availableLiquidity should also decrease
    // If underlyingBalance was not updated, availableLiquidity > actual balance
    uint256 availLiq = lendingPool.utilizationRateOfReserve(asset); // proxy: use totalLiquidity
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(asset);
    // After pull, totalLiquidity should equal actual token in yToken + borrows
    // If underlyingBalance not decremented, totalLiq > yTokenBal + borrows
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    // push funds back
    _pushFunds(asset, pullAmount);
    uint256 yTokenBalFinal = IERC20(asset).balanceOf(yAddr);
    uint256 totalLiqFinal = lendingPool.totalLiquidityOfReserve(asset);
    // After roundtrip, totalLiquidity must equal actual yToken balance + totalBorrows
    eq(totalLiqFinal, yTokenBalFinal + lendingPool.totalBorrowsOfReserve(asset), "totalLiquidity inconsistent after pull+push roundtrip");
}

function property_pushfunds_updates_underlyingbalance() public {
    address asset = address(token0);
    uint256 pushAmount = 1_000 * ONE_TOKEN0;

    address yAddr = lendingPool.getYTokenAddress(asset);
    uint256 totalLiqBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 yTokenBalBefore = IERC20(asset).balanceOf(yAddr);

