    if (!leverager.isLiquidateable(posId)) return;

    _liquidatePosition(liquidator, posId);

    // After liquidation, position must be fully deleted
    ILeverager.Position memory pos = leverager.getPosition(posId);
    eq(pos.borrowedAmount, 0, "liquidated position must have 0 borrowedAmount");
    eq(pos.shares, 0, "liquidated position must have 0 shares");
    t(!_positionExists(posId), "liquidated position NFT must be burned");
}

function property_withdraw_swap_no_double_spend_token1() public {
    uint256 posId = _openLeveragedPositionDenomUsdc(
        user,
        1e7,
        50_000e6,
        60_000e6
    );
    if (posId == 0) return;

