    _withdrawPosition(user, posId, 0.5e18);

    uint256 usdcAfter = usdc.balanceOf(user);
    uint256 wbtcAfter = wbtc.balanceOf(user);

    // User should receive non-negative net value from partial withdraw
    // (may have paid some USDC to cover interest, but got WBTC back)
    // Net USD value should be >= 0
    // Simplified: after partial withdraw, WBTC received or USDC net is reasonable
    t(
        wbtcAfter >= wbtcBefore || usdcAfter >= usdcBefore,
        "user should not lose both tokens in a partial withdraw"
    );
}

function property_fee_recipient_not_zero_when_fee_set() public {
    // If liquidationFee > 0, feeRecipient must not be address(0)
    // Otherwise liquidation fees are permanently burned
    // We check this as an invariant
    uint256 liqFee = 0;
    // liquidationFee is private, we infer it from behavior
    // The feeRecipient is public
    address fr = leverager.feeRecipient();
    // If protocol intends to charge fees (non-zero fee), feeRecipient must be set
    // Since feeRecipient is never initialized, this will always be address(0)
    // making all fee collection a burn
    // Property: feeRecipient should never be address(0) in production
    // (this will always fail as-is, demonstrating the bug)
    t(fr != address(0), "feeRecipient is address(0): liquidation fees will be burned");
}

function property_token_value_calculation_consistent() public {
    // If both tokens have price feeds, collateral USD value should be
    // approximately consistent with direct oracle pricing.
    // We open a position and check that initCollateralUsd is reasonable.
    uint256 posId = _openLeveragedPositionDenomWbtc(
        user,
        80_000e6,    // 80k USDC collateral
        0.5e8,       // 0.5 WBTC to vault
        0.3e8        // borrow 0.3 WBTC
    );
    if (posId == 0) return;

    ILeverager.Position memory pos = leverager.getPosition(posId);

    // At WBTC=$100k and USDC=$1:
    // 0.5 WBTC ≈ $50k, 80k USDC ≈ $80k, total ≈ $130k
    // initCollateralUsd should be in that ballpark (within 20%)
    // If price inversion bug: value would be wildly off
    uint256 expectedMin = 50_000e18;   // at least $50k
    uint256 expectedMax = 200_000e18;  // at most $200k

    gte(pos.initCollateralUsd, expectedMin, "initCollateralUsd too low: possible price inversion");
    lte(pos.initCollateralUsd, expectedMax, "initCollateralUsd too high: possible price inversion");
}

function property_deposit_withdraw_no_profit_from_price_manipulation() public {
    // Attacker baseline: deal tokens, record initial vault share supply
    uint256 initialSupply = vault.totalSupply();

    // Step 1: large swap to move price (simulate manipulation)
    _swapUsdcForWbtc(10_000_000e6); // $10M USDC → WBTC, moves price significantly

    // Step 2: attacker deposits at manipulated price
    uint256 attackAmount0 = 1e8; // 1 WBTC
    uint256 attackAmount1 = 10_000e6; // 10k USDC
    deal(address(wbtc), attacker, attackAmount0);
    deal(address(usdc), attacker, attackAmount1);
    vm.startPrank(attacker);
    wbtc.approve(address(vault), attackAmount0);
    usdc.approve(address(vault), attackAmount1);
    (uint256 shares,,) = vault.deposit(attackAmount0, attackAmount1, 0, 0);
    vm.stopPrank();

    // Step 3: swap back to restore price
    _swapWbtcForUsdc(wbtc.balanceOf(depositor));

    // Step 4: attacker withdraws
    (uint256 out0, uint256 out1) = _withdrawAs(attacker, shares);

    // Property: attacker should not profit in token1 terms
    uint256 spotPrice = vault.price(); // 1e30 precision
    uint256 costIn1 = attackAmount0 * spotPrice / 1e30 + attackAmount1;
    uint256 recvIn1 = out0 * spotPrice / 1e30 + out1;

    // Attacker should not have received more than deposited (allow 1% slippage buffer)
    t(recvIn1 <= costIn1 * 101 / 100, "attacker profited from price manipulation on deposit");
}

function property_secondary_position_direction_stable() public {
    // After a rebalance, secondary position should be OOR on the correct side
    // given that we haven't swapped anything

    // Capture secondary position ticks before rebalance
    IStrategy.Position memory secBefore = strategy.getSecondaryPosition();

    // Do a rebalance (enough time has passed in setUp)
    skip(400);
    _rebalance();

    IStrategy.Position memory secAfter = strategy.getSecondaryPosition();
    IStrategy.Position memory mainAfter = strategy.getMainPosition();

    // Secondary position should not overlap the main range on both sides simultaneously
    // i.e. it should be either fully below tickLower or fully above tickUpper of main position
    bool fullyBelow = secAfter.tickUpper <= mainAfter.tickLower;
    bool fullyAbove = secAfter.tickLower >= mainAfter.tickUpper;
    t(fullyBelow || fullyAbove, "secondary position overlaps main position range");
}

function property_deposit_shares_proportional() public {
    // Two depositors deposit the same amounts at different times (price may move)
    uint256 amt0 = 1e7; // 0.1 WBTC
    uint256 amt1 = 5_000e6; // 5000 USDC

    (uint256 shares1,,) = _dealAndDeposit(depositor, amt0, amt1);

    // Simulate small price movement (natural, not attack)
    _swapWbtcForUsdc(1e6); // small swap

    (uint256 shares2,,) = _dealAndDeposit(attacker, amt0, amt1);

    // Both depositors deposited same token amounts. Shares should be within 2% of each other
    // (allowing for normal price impact). If they differ by more, spot oracle is causing unfairness.
    uint256 diff = shares1 > shares2 ? shares1 - shares2 : shares2 - shares1;
    uint256 maxDiff = shares1 * 2 / 100;
    t(diff <= maxDiff, "share allocation unfair due to spot price oracle in balances()");
}

