function property_rebalancer_cannot_change_position_width() public {
    uint24 originalWidth = strategy.positionWidth();

    // tickSpacing for 0.3% WBTC/USDC pool is 60
    // 2 * 60 = 120; halfWidth = 60; 60 % 60 == 0 → passes divisibility check
    uint24 maliciousWidth = uint24(uint24(strategy.tickSpacing()) * 2);

    skip(strategy.rebalanceInterval() + 1);

    vm.prank(rebalancer);
    try strategy.changePositionWidth(maliciousWidth) {
        // If we get here, the rebalancer changed positionWidth — this is the bug
        uint24 newWidth = strategy.positionWidth();
        t(newWidth == originalWidth, "rebalancer changed positionWidth without owner approval");
    } catch {
        // This would be the safe behavior
    }
}

function property_pullFunds_updates_underlyingBalance() public {
    // Record state before pullFunds
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);
    uint256 balBefore = IERC20(asset).balanceOf(yAddr);

    // Pull a small amount
    uint256 pullAmt = 1000 * ONE_TOKEN0;
    _pullFunds(asset, pullAmt);

    // After pullFunds, real balance of yToken should have decreased
    uint256 balAfter = IERC20(asset).balanceOf(yAddr);
    // And underlyingBalance (== availableLiquidity) should also decrease
    uint256 availAfter = lendingPool.totalLiquidityOfReserve(asset)
                         - lendingPool.totalBorrowsOfReserve(asset);

    // INVARIANT: accounting available liquidity must not exceed actual yToken ERC20 balance
    lte(availAfter, balAfter, "pullFunds: underlyingBalance not decremented, phantom liquidity");
}

function property_pushFunds_updates_underlyingBalance() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    // Get accounting available liquidity before
    uint256 totalBefore = lendingPool.totalLiquidityOfReserve(asset);
    uint256 balBefore = IERC20(asset).balanceOf(yAddr);

    uint256 pushAmt = 1000 * ONE_TOKEN0;
    _pushFunds(asset, pushAmt);

    uint256 totalAfter = lendingPool.totalLiquidityOfReserve(asset);
    uint256 balAfter = IERC20(asset).balanceOf(yAddr);

    // INVARIANT: change in accounting total liquidity must equal change in real balance
    // (when no borrows are outstanding)
    uint256 borrows = lendingPool.totalBorrowsOfReserve(asset);
    if (borrows == 0) {
        eq(balAfter - balBefore, totalAfter - totalBefore,
           "pushFunds: underlyingBalance not incremented, accounting desync");
    }
}

function property_first_deposit_antidust_invariant() public {
    // After any deposit sequence, dead address yToken balance should be MINIMUM_YTOKEN_AMOUNT
    // if totalSupply was ever 0 (i.e., first deposit happened)
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);
    uint256 deadBal = IERC20(yAddr).balanceOf(DEAD_ADDRESS);

    // After setup (which calls deposit), dead address must hold exactly MINIMUM_YTOKEN_AMOUNT
    // This validates the burn happened exactly once
    address DEAD_ADDRESS = address(0x000000000000000000000000000000000000dEaD);
    eq(deadBal, MINIMUM_YTOKEN_AMOUNT,
       "First deposit: dead address does not hold exactly MINIMUM_YTOKEN_AMOUNT yTokens");
}

function property_available_liquidity_le_actual_balance() public {
    address asset = address(token0);
    address yAddr = lendingPool.getYTokenAddress(asset);

    // Available liquidity from accounting
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(asset);
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(asset);
    uint256 accountingAvailable = totalLiq > totalBorrows ? totalLiq - totalBorrows : 0;

    // Actual ERC20 balance held by yToken
    uint256 actualBalance = IERC20(asset).balanceOf(yAddr);

    // INVARIANT: accounting available must not exceed actual balance
    // (actual balance can exceed accounting if pushFunds was called with excess,
    //  but accounting must never exceed actual)
    lte(accountingAvailable, actualBalance,
        "accounting available liquidity exceeds actual yToken ERC20 balance");
}

