    uint256 idxAfter = lendingPool.getCurrentBorrowingIndex(address(token0));

    // borrowing index must never decrease
    gte(idxAfter, idxBefore, "borrowing index decreased — accrual error");

    // cleanup
    _repay(address(token0), 10_000 * ONE_TOKEN0);
}

function property_interest_rate_reflects_utilization() public {
    // At high utilization, borrowing rate must be high
    _borrow(address(token0), 140_000 * ONE_TOKEN0);

    uint256 rate = lendingPool.borrowingRateOfReserve(address(token0));
    uint256 util = lendingPool.utilizationRateOfReserve(address(token0));

    // At > 80% utilization, rate must be > borrowingRateA (20% APR = 0.2e27)
    if (util > PRECISION * 8 / 10) {
        gte(rate, PRECISION * 2000 / 10_000, "borrowing rate too low for high utilization");
    }

    _repay(address(token0), 140_000 * ONE_TOKEN0);
}

function property_capacityCheck_consistent_with_actual_balance() public {
    address yAddr = lendingPool.getYTokenAddress(address(token0));
    uint256 actualBalance = token0.balanceOf(yAddr);
    uint256 reportedLiquidity = lendingPool.totalLiquidityOfReserve(address(token0));

    // The reported total liquidity should account for at least the actual token balance.
    // (totalBorrows may be > 0, so reportedLiquidity >= actualBalance)
    gte(reportedLiquidity, actualBalance, "reported liquidity less than actual yToken balance");
}

function property_vesting_fees_collected_from_correct_ticks() public {
    // Set up a vesting position, then deliberately move main ticks via rebalance
    // so vestPosition.tickUpper != mainPosition.tickUpper.
    // After collectFees, the vesting position in the pool should have 0 uncollected fees.
    // We verify this indirectly: total idle balance after collectFees should be >=
    // balance before (fees only go up, never down).
    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();
    // After collecting fees (net of protocol fee sent out), idle should not decrease
    // if no vesting withdrawal happened.
    // The real check: vesting position tickUpper used in collectFees must match vestPosition.tickUpper
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // If ongoingVestingPosition is true and ticks diverged, the bug manifests silently.
    // We can only assert the ticks should match at time of addVestingPosition.
    if (strategy.ongoingVestingPosition()) {
        t(vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
          "vesting position ticks diverged from main — collectFees uses wrong key");
    }
}

function property_secondary_position_valid_ticks() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    t(sp.tickLower < sp.tickUpper, "secondary position has invalid tick range: tickLower >= tickUpper");
}

function property_withdraw_amount_consistent() public {
    uint256 shares = vault.balanceOf(user);
    if (shares == 0) return;
    uint256 halfShares = shares / 2;
    if (halfShares == 0) return;

    strategy.collectFees();
    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 ts = vault.totalSupply();
    uint256 expected0 = bal0 * halfShares / ts;
    uint256 expected1 = bal1 * halfShares / ts;

    uint256 pre0 = wbtc.balanceOf(user);
    uint256 pre1 = usdc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(halfShares, 0, 0);

    uint256 got0 = wbtc.balanceOf(user) - pre0;
    uint256 got1 = usdc.balanceOf(user) - pre1;

    // User should not receive MORE than their proportional share
    lte(got0, expected0 + 2, "user withdrew more token0 than proportional share");
    lte(got1, expected1 + 2, "user withdrew more token1 than proportional share");
}

function property_checkPoolActivity_no_division_by_zero() public {
