    // We check it returns a bool without reverting.
    bool result = strategy.checkPoolActivity();
    // If we get here without revert, the property holds.
    t(true, "checkPoolActivity reverted unexpectedly");
}

function property_vesting_fully_withdraws_by_end() public {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (!strategy.ongoingVestingPosition()) return;
    if (block.timestamp < vp.endTs) return;
    // After end time, calling collectFees should clear the vesting position
    strategy.collectFees();
    t(!strategy.ongoingVestingPosition(), "vesting position not cleared after endTs");
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(uint256(vpAfter.remainingLiquidity), 0, "remaining liquidity not zero after vesting ended");
}

function property_secondary_ticks_never_equal() public {
