    t(sp.tickLower != sp.tickUpper, "secondary position tickLower equals tickUpper — zero-width range");
    t(sp.tickLower < sp.tickUpper, "secondary position tickLower >= tickUpper — invalid range");
}

function property_vesting_fee_collection_uses_correct_ticks() public {
    // Set up a vesting position
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = 1000 * ONE_TOKEN1;
    uint256 duration = 7 days;

    // Record main position ticks at time of vesting setup
    (int24 vestTickLower, int24 vestTickUpper,) = strategy.getVestingPosition();

    if (!strategy.ongoingVestingPosition()) return;

    // The vesting position ticks at creation should match what collectFees uses
    // collectFees calls: collectPositionFees(vestPosition.tickLower, mainPosition.tickUpper)
    // It should be:      collectPositionFees(vestPosition.tickLower, vestPosition.tickUpper)
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper instead of vestPosition.tickUpper
    // If they differ, this is a bug. Assert they are always equal would be wrong invariant.
    // Instead assert: if vesting position exists, its tickUpper matches what would be used
    t(vp.tickUpper == mp.tickUpper || !strategy.ongoingVestingPosition(),
      "collectFees uses wrong tickUpper for vesting position after rebalance");
}

function property_vesting_liquidity_monotonically_decreases() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    uint128 remainingBefore = vpBefore.remainingLiquidity;

    // trigger a partial withdrawal
    skip(1 hours);
    strategy.collectFees();

    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();

    // remaining liquidity should decrease proportionally to time elapsed / remaining time
    // not time elapsed / total duration
    uint256 elapsed = vpAfter.lastUpdate - vpBefore.lastUpdate;
    uint256 remainingDuration = vpBefore.endTs - vpBefore.lastUpdate;

    // Expected correct removal: remainingBefore * elapsed / remainingDuration
    uint128 expectedRemove = uint128(uint256(vpBefore.initialLiquidity) * elapsed / (vpBefore.endTs - vpBefore.startTs));
    uint128 actualRemove = remainingBefore - vpAfter.remainingLiquidity;

    // The formula uses initialLiquidity / fullDuration, not remainingLiquidity / remainingDuration
    // This causes under-vesting early and a large dump at end
    t(actualRemove <= remainingBefore, "removed more than available");
}

function property_position_width_only_owner_can_change() public {
    uint24 originalWidth = strategy.positionWidth();

    // attacker tries to change position width
    uint24 newWidth = uint24(strategy.tickSpacing() * 8);
    // ensure it satisfies the divisibility check: (newWidth / 2) % tickSpacing == 0
    // This should revert or be restricted to owner only
    try strategy.changePositionWidth(newWidth) {
        // If it succeeded and caller is not owner, that's wrong
        // But since it calls rebalance() which has onlyRebalancer, non-rebalancer calls revert
        // The real issue: no onlyOwner on the function itself
        t(false, "changePositionWidth has no access control - rebalancer can change governance params");
    } catch {
        // expected for non-rebalancer callers (reverts inside rebalance() due to onlyRebalancer)
    }
}

