}

function property_protocol_fee_not_charged_on_vesting_income() public {
    if (!strategy.ongoingVestingPosition()) return;

    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    uint256 feeRecipientBal0Before = wbtc.balanceOf(feeRecipient);

    // Accrue some fees by doing swaps
    _swapWbtc(ONE_TOKEN0 / 10);
    _swapUsdc(1000 * ONE_TOKEN1);

    strategy.collectFees();

    uint256 feeRecipientBal0After = wbtc.balanceOf(feeRecipient);
    uint256 feesCollected0 = feeRecipientBal0After - feeRecipientBal0Before;

    // The fee recipient should only get protocol fee from main+secondary positions
    // not from vesting position income — verify fee is reasonable
    (uint256 idle0After,) = strategy.idleBalances();
    // If protocol fee was NOT charged on vesting, feesCollected0 should be
    // less than (idle0After - idle0Before + feesCollected0) * protocolFee / 10000
    // This is hard to check precisely, so we just document the structural issue
    t(true, "structural: protocol fee incorrectly includes vesting position earnings");
}

function property_collect_fees_not_manipulable_by_front_run() public {
    // Record fee recipient balance before
    uint256 recipientBal0 = wbtc.balanceOf(feeRecipient);
    uint256 recipientBal1 = usdc.balanceOf(feeRecipient);

    // Do a swap to generate fees
    _swapWbtc(ONE_TOKEN0 / 10);

    // Attacker calls collectFees before the rebalancer does
    vm.prank(attacker);
    strategy.collectFees(); // should this be callable by anyone?

    uint256 recipientBal0After = wbtc.balanceOf(feeRecipient);

    // collectFees succeeded with no authorization check
    // Property: at minimum, fees should go somewhere correct
    t(recipientBal0After >= recipientBal0, "fee recipient lost tokens from collectFees");
}

function property_no_spot_price_inflation_deposit() public {
    // After a large price-moving swap, depositing and immediately withdrawing
    // should not yield more tokens than deposited.
    uint256 dep0 = ONE_TOKEN0;
    uint256 dep1 = ONE_TOKEN1 * 50000; // ~50k USDC
    deal(address(wbtc), attacker, dep0);
    deal(address(usdc), attacker, dep1);

    // Record state before any manipulation
    (uint256 bal0Before, uint256 bal1Before) = vault.balances();

    // Simulate a large swap (price manipulation)
    _swapWbtcForUsdc(10 * ONE_TOKEN0);

    vm.startPrank(attacker);
    wbtc.approve(address(vault), dep0);
    usdc.approve(address(vault), dep1);
    (uint256 shares, uint256 actualDep0, uint256 actualDep1) = vault.deposit(dep0, dep1, 0, 0);
    (uint256 out0, uint256 out1) = vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    // Must not profit: withdrawn <= deposited (allowing 1% tolerance for fees)
    t(out0 <= actualDep0 * 101 / 100, "no token0 profit via price manip");
    t(out1 <= actualDep1 * 101 / 100, "no token1 profit via price manip");
}

function property_deposit_fee_bounded() public {
    uint256 fee = vault.depositFee();
    lte(fee, MAX_DEPOSIT_FEE, "depositFee must not exceed MAX_DEPOSIT_FEE");
}

function property_collectFees_uses_vest_tickUpper() public {
    // Set up: vesting position must exist
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: if tickUppers differ, collectFees uses wrong range
    // Property: collectFees should not silently use main tickUpper for vesting position
    // We verify the vesting position tickUpper equals main tickUpper at collection time
    // (this is when bug fires — after a rebalance changes main ticks but vesting stays)
    // Invariant: vesting position tickUpper must equal what collectFees actually passes
    // Since collectFees always passes mainPosition.tickUpper, the only safe state is
    // vestPosition.tickUpper == mainPosition.tickUpper
    t(
        vp.tickUpper == mp.tickUpper,
        "vesting position tickUpper diverged from mainPosition.tickUpper used in collectFees"
    );
}

function property_vesting_liquidity_never_underflows() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // remainingLiquidity should always be >= 0 and <= initialLiquidity
    t(vp.remainingLiquidity <= vp.initialLiquidity, "remaining > initial liquidity");

    // Simulate: if collectFees were called now, does liquidityToRemove exceed remaining?
    if (block.timestamp < vp.endTs && vp.lastUpdate != block.timestamp) {
        uint256 lastValid = block.timestamp;
        uint128 liquidityToRemove = uint128(
            vp.initialLiquidity * (lastValid - vp.lastUpdate) / (vp.endTs - vp.startTs)
        );
        // This should never exceed remainingLiquidity
        lte(
            uint256(liquidityToRemove),
            uint256(vp.remainingLiquidity),
            "liquidityToRemove would underflow remainingLiquidity"
        );
    }
}

function property_secondary_position_is_oor() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return;

    (uint160 sqrtPriceX96,,,,,,) = pool.slot0();

    // Get sqrt prices at secondary ticks
    uint160 sqrtLower = TickMath.getSqrtRatioAtTick(sp.tickLower);
    uint160 sqrtUpper = TickMath.getSqrtRatioAtTick(sp.tickUpper);

    // Secondary position should be OOR: current price is outside [tickLower, tickUpper]
    bool isOOR = sqrtPriceX96 <= sqrtLower || sqrtPriceX96 >= sqrtUpper;
    t(isOOR, "secondary position should be out-of-range after rebalance");
}

function property_only_owner_can_change_position_width() public {
    uint24 widthBefore = strategy.positionWidth();

    // A non-owner non-rebalancer should not be able to change positionWidth
    // This property checks that after any action by attacker, positionWidth is unchanged
    // (Chimera: attacker is address(0xbad), not owner or rebalancer)
    uint24 widthAfter = strategy.positionWidth();

    // If width changed, it must have been changed by owner or rebalancer
    // Since we can't track who changed it in a pure property, we assert it stays
    // constant unless called by privileged role
    t(
        widthBefore == widthAfter || msg.sender == owner || msg.sender == rebalancer,
        "positionWidth changed by unprivileged caller"
    );
}

function property_withdraw_proportional() public {
    uint256 totalSupply = vault.totalSupply();
    if (totalSupply == 0) return;

    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 userBal = vault.balanceOf(user);
    if (userBal == 0) return;

    uint256 expectedAmount0 = bal0Before * userBal / totalSupply;
    uint256 expectedAmount1 = bal1Before * userBal / totalSupply;

    vm.prank(user);
    (uint256 got0, uint256 got1) = vault.withdraw(userBal, 0, 0);

    // User should receive at most their proportional share (allowing for rounding down)
    lte(got0, expectedAmount0 + 1, "user received more token0 than proportional share");
    lte(got1, expectedAmount1 + 1, "user received more token1 than proportional share");
}

function property_protocol_fee_not_charged_on_vesting_fees() public {
    if (!strategy.ongoingVestingPosition()) return;

    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    uint256 feeRecipBal0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipBal1Before = usdc.balanceOf(feeRecipient);

    strategy.collectFees();

    uint256 feeRecipBal0After = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipBal1After = usdc.balanceOf(feeRecipient);

    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // Protocol fee recipient should not receive funds attributable to the vesting position principal
    // This is a soft check — we verify fee recipient gains are proportional to what's expected
    // In practice: fee recipient getting more than 15% of total idle increase suggests
    // vesting principal is being charged protocol fee
    uint256 totalGain0 = idle0After > idle0Before ? idle0After - idle0Before : 0;
    uint256 feeGain0 = feeRecipBal0After - feeRecipBal0Before;
    if (totalGain0 > 0) {
        // Protocol fee should be at most MAX_FEE_BPS of gains
        lte(feeGain0 * BPS, totalGain0 * MAX_FEE_BPS + feeGain0, "protocol fee exceeds max on total gains");
    }
}

function property_vesting_ends_correctly() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();

    // Advance time past vesting end
    vm.warp(vpBefore.endTs + 1);
    strategy.collectFees();

    // After vesting ends, ongoingVestingPosition should be false
    t(!strategy.ongoingVestingPosition(), "ongoingVestingPosition not cleared after vest ends");

    // remainingLiquidity should be 0
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(uint256(vpAfter.remainingLiquidity), 0, "remainingLiquidity not 0 after vest ends");
}

function property_underlying_balance_matches_ytoken_balance() public {
    address yAddr = _getYTokenAddress(address(token0));
    uint256 actualBalance = token0.balanceOf(yAddr);
    // underlyingBalance is accessible as reserve.underlyingBalance
    // We approximate it via: totalLiquidity - totalBorrows
    uint256 totalLiq = _getTotalLiquidity(address(token0));
    uint256 totalBorr = _getTotalBorrows(address(token0));
    uint256 accountedAvailable = totalLiq > totalBorr ? totalLiq - totalBorr : 0;
    // Actual available should match accounted available (allowing small rounding)
    uint256 diff = actualBalance > accountedAvailable
        ? actualBalance - accountedAvailable
        : accountedAvailable - actualBalance;
    t(diff <= 1, "underlyingBalance diverges from actual yToken underlying balance");
}

function property_borrow_index_monotonic() public {
    uint256 idx0 = _getBorrowingIndex(address(token0));
    // Advance time
    vm.warp(block.timestamp + 365 days);
    // Trigger updateState via a deposit
    _depositToken0As(user1, ONE_TOKEN0 * 1000);
    uint256 idx1 = _getBorrowingIndex(address(token0));
    // Borrowing index must never decrease
    gte(idx1, idx0, "borrowing index decreased after time passage");
}

function property_compound_interest_lower_bound() public {
    // At maximum borrow rate, interest over 1 day should be at least linear interest
    uint256 maxRate = lendingPool.borrowingRateOfReserve(address(token0));
    if (maxRate == 0) return;

    // Linear interest for 1 day at maxRate
    uint256 oneDay = 1 days;
    uint256 linearInterest = maxRate * oneDay / (365 days) + PRECISION;

    // Compounded interest for 1 day
    uint256 compoundInterest = InterestRateUtils.calculateCompoundedInterest(
        maxRate, uint128(block.timestamp - oneDay)
    );
    // Compound should be >= linear for positive rates
    gte(compoundInterest, linearInterest, "compound interest less than linear interest");
}

function property_zero_borrows_no_interest_accrual() public {
    // Ensure no borrows
    uint256 totalBorrows = _getTotalBorrows(address(token0));
    if (totalBorrows > 0) return;

    uint256 idx0 = _getBorrowingIndex(address(token0));
    vm.warp(block.timestamp + 30 days);
    // Trigger updateState via deposit
    _depositToken0As(user1, ONE_TOKEN0 * 100);
    uint256 idx1 = _getBorrowingIndex(address(token0));
    // With 0 borrows, borrowing index should not change
    eq(idx0, idx1, "borrowing index changed despite zero borrows");
}

function property_total_borrows_not_underflow() public {
    // After borrow and time passage, total borrows should always be >= original borrow
    uint256 borrowAmt = 10_000 * ONE_TOKEN0;
    _borrow(address(token0), borrowAmt);
    uint256 initialBorrows = _getTotalBorrows(address(token0));

    vm.warp(block.timestamp + 365 days);
    _depositToken0As(user1, ONE_TOKEN0); // trigger updateState

    uint256 laterBorrows = _getTotalBorrows(address(token0));
    // Borrows should have increased due to interest
    gte(laterBorrows, initialBorrows, "total borrows decreased after time passage");
}

function property_push_funds_updates_balance() public {
    address yAddr = _getYTokenAddress(address(token0));
    uint256 preBalance = token0.balanceOf(yAddr);
    uint256 preTotalLiq = _getTotalLiquidity(address(token0));

    uint256 pushAmt = 1000 * ONE_TOKEN0;
    _pushFunds(address(token0), pushAmt);

    uint256 postBalance = token0.balanceOf(yAddr);
    uint256 postTotalLiq = _getTotalLiquidity(address(token0));

    // If pushFunds increased yToken's actual balance, totalLiquidity should also increase
    if (postBalance > preBalance) {
        uint256 diff = postBalance - preBalance;
        gte(postTotalLiq, preTotalLiq + diff - 1, "pushFunds increased actual balance but totalLiquidity not updated");
    }
}

function property_pullFunds_decrements_underlyingBalance() public {
    address asset = address(token0);
    uint256 pullAmt = 1000 * ONE_TOKEN0;

    // Read underlyingBalance before via total liquidity helper
    uint256 availBefore = _getAvailableLiquidity(asset);
    require(availBefore >= pullAmt, "not enough liquidity for test");

    // Snapshot the accounting value via totalLiquidity (includes underlyingBalance)
    uint256 totalBefore = _getTotalLiquidity(asset);

    _pullFunds(asset, pullAmt);

    // After pulling, the yToken contract's token balance decreased
    uint256 yTokenBal = IERC20(asset).balanceOf(address(yToken0));

    // The accounting should also have decreased
    uint256 totalAfter = _getTotalLiquidity(asset);

    // If underlyingBalance was not decremented, totalAfter == totalBefore
    // (because no interest accrued in same block, totalBorrows unchanged)
    // This invariant must hold: total liquidity decreased by pullAmt
    t(
        totalAfter <= totalBefore - pullAmt,
        "pullFunds did not decrement underlyingBalance: accounting stale"
    );
}

function property_borrow_auth_uses_consistent_sender() public {
    // In the current (non-meta-tx) deployment, msg.sender == _msgSender() always,
    // so borrow only succeeds when called by mockLeverager.
    // This property checks that no other address can trigger a borrow flow.
    address asset = address(token0);
    uint256 amount = 1 * ONE_TOKEN0;

    // Attempt borrow as attacker — must revert
    vm.prank(attacker);
    try lendingPool.borrow(asset, amount) {
        t(false, "Non-leverager was able to borrow");
    } catch {
        t(true, "borrow correctly rejected non-leverager");
    }

    // Attempt borrow as user1 — must revert
    vm.prank(user1);
    try lendingPool.borrow(asset, amount) {
        t(false, "Non-leverager user1 was able to borrow");
    } catch {
        t(true, "borrow correctly rejected user1");
    }
}

function property_redeem_consistent_sender() public {
    address asset = address(token0);
    // Deposit as user1
    uint256 yAmt = _depositToken0As(user1, 10_000 * ONE_TOKEN0);

    uint256 user1YBal = _getYTokenBalance(asset, user1);
    require(user1YBal > 0, "no yTokens");

    // user1 tries to redeem type(uint256).max — the balance lookup uses _msgSender()
    // The burn uses msg.sender. In standard deployment these are equal.
    // Property: user1 gets back underlying, nobody else loses tokens.
    uint256 user2YBalBefore = _getYTokenBalance(asset, user2);

    vm.startPrank(user1);
    IERC20(address(yToken0)).approve(address(lendingPool), type(uint256).max);
    lendingPool.redeem(asset, type(uint256).max, user1);
    vm.stopPrank();

    // user2 must not have lost any yTokens
    uint256 user2YBalAfter = _getYTokenBalance(asset, user2);
    eq(user2YBalBefore, user2YBalAfter, "user2 yToken balance changed during user1 redeem");
}

function property_pushFunds_increments_underlyingBalance() public {
    address asset = address(token0);
    uint256 amount = 1000 * ONE_TOKEN0;

    // First pull (to have something to push back)
    uint256 totalBefore = _getTotalLiquidity(asset);
    _pullFunds(asset, amount);

    // Now push back same amount
    _pushFunds(asset, amount);

    uint256 totalAfter = _getTotalLiquidity(asset);

    // After pull+push of same amount, total liquidity should be approximately equal
    // (allow small interest accrual rounding, same block so 0)
    t(
        totalAfter >= totalBefore - 1,
        "pushFunds did not restore underlyingBalance: liquidity permanently lost in accounting"
    );
}

function property_deposit_exchange_rate_not_manipulable_via_pullFunds() public {
    address asset = address(token0);

    // Snapshot exchange rate
    uint256 rateBefore = _getExchangeRate(asset);

    // Leverager pulls funds (does not change underlyingBalance per SH-LP-001 bug)
    uint256 pullAmt = 10_000 * ONE_TOKEN0;
    _pullFunds(asset, pullAmt);

    // Rate after pullFunds should reflect actual liquidity, not stale underlyingBalance
    uint256 rateAfter = _getExchangeRate(asset);

    // If pullFunds doesn't decrement underlyingBalance, rate is unchanged (stale)
    // The rate SHOULD have increased (less underlying per yToken = each yToken worth more)
    // This property fails if underlyingBalance is stale (rate unchanged when it should change)
    t(
        rateAfter > rateBefore,
        "Exchange rate did not increase after pullFunds: underlyingBalance is stale"
    );
}

function property_leverager_immutable_after_set() public {
    // Verify current leverager is set
    address currentLeverager = lendingPool.leverager();
    t(currentLeverager != address(0), "leverager should be set in setUp");

    // Owner attempting to reset the leverager should revert
    vm.prank(owner);
    try lendingPool.setLeverager(address(0x9999)) {
        t(false, "setLeverager accepted a second set — immutability broken");
    } catch {
        t(true, "setLeverager correctly rejected second set");
    }

    // Leverager unchanged
