function property_borrowing_rate_within_bounds() public {
    address asset = address(token0);

    // Borrow at various utilizations and check rate is within expected bounds
    uint256 availLiq = _getAvailableLiquidity(asset);
    if (availLiq < 2) return;

    // Borrow to ~85% utilization
    uint256 totalLiq = _getTotalLiquidity(asset);
    uint256 target85pct = totalLiq * 85 / 100;
    uint256 currentBorrows = _getTotalBorrows(asset);
    if (target85pct <= currentBorrows) return;
    uint256 toBorrow = target85pct - currentBorrows;
    if (toBorrow > availLiq) toBorrow = availLiq;
    if (toBorrow == 0) return;

    _borrow(asset, toBorrow);

    uint256 rate = _getBorrowingRate(asset);

    // Rate must be in [0, maxBorrowingRate]. maxBorrowingRate = 150% = 15000 bps
    // In PRECISION: 15000 * 1e27 / 10000 = 1.5e27
    uint256 maxRate = PRECISION * 15000 / 10000;
    lte(rate, maxRate, "borrowing rate exceeds max configured rate");
    t(rate > 0, "borrowing rate should be positive at 85% utilization");
}

