        // vestPosition.tickUpper should be used, not mainPosition.tickUpper
        IStrategy.Position memory mp = strategy.getMainPosition();
        // If mainPosition.tickUpper < vestPosition.tickLower, collectFees will revert
        t(
            mp.tickUpper >= vp.tickLower,
