function property_checkPoolActivity_consistent_initial_tick() public {
    // After setup the activity check should pass in normal market conditions.
    // If it fails due to spot-vs-twap mismatch in the first iteration, rebalance is incorrectly blocked.
    bool active = strategy.checkPoolActivity();
    (, int24 spotTick,,,,,) = pool.slot0();
    int24 twapT = strategy.twapTick();
    int24 delta = spotTick - twapT;
    if (delta < 0) delta = -delta;
    // If spot and twap are close, checkPoolActivity should return true
    int24 maxDev = strategy.maxObservationDeviation();
    if (delta <= maxDev) {
        t(active, "checkPoolActivity returned false despite spot/twap within maxObservationDeviation");
    } else {
        t(true, "spot and twap diverged, deviation check is expected");
    }
}

function property_vesting_fees_collected_at_correct_ticks() public {
    // Setup: add a vesting position, then rebalance to change main ticks
    uint256 amt0 = 1e7;
    uint256 amt1 = 10_000e6;
    _addVestingPosition(amt0, amt1, 7 days);

    // Snapshot vesting position ticks right after creation
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    int24 vestLower = vp.tickLower;
    int24 vestUpper = vp.tickUpper;

    // Trigger a rebalance (changes mainPosition ticks)
    skip(strategy.rebalanceInterval() + 1);
    _rebalance();

    // After rebalance, main ticks differ from vest ticks
    IStrategy.Position memory main = strategy.getMainPosition();

    // The vesting position tickUpper should still match what was recorded
    // If mainPosition.tickUpper changed, collectFees used the wrong range
    // We check that the vesting position ticks are still valid and match
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    t(vpAfter.tickUpper == vestUpper, "vesting tickUpper changed unexpectedly");

    // collectFees must not revert and should acknowledge correct ticks
    // If collectFees uses mainPosition.tickUpper instead of vestPosition.tickUpper,
    // we lose fees silently. This property checks they match post-rebalance.
    t(main.tickUpper == vestUpper || vpAfter.tickUpper == main.tickUpper,
      "after rebalance: vesting tickUpper != mainPosition.tickUpper, fees will be lost");
}

function property_vesting_no_underflow_on_many_collects() public {
    // Add a vesting position with 30-day duration
    uint256 dur = 30 days;
    _addVestingPosition(1e7, 10_000e6, dur);

    IStrategy.VestingPosition memory vpStart = strategy.getVestingPosition();
    uint128 initLiq = vpStart.initialLiquidity;

    // Call collectFees daily for 29 days — should never underflow
    for (uint256 i = 0; i < 29; i++) {
        skip(1 days);
        // collectFees calls _withdrawPartOfVestingPosition internally
        strategy.collectFees();
        IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
        // remainingLiquidity must never exceed initialLiquidity
        t(vp.remainingLiquidity <= initLiq, "remainingLiquidity exceeded initial");
    }

    // Final collect at end
    skip(2 days);
    strategy.collectFees();
    IStrategy.VestingPosition memory vpEnd = strategy.getVestingPosition();
    t(!strategy.ongoingVestingPosition(), "vesting should be complete");
    t(vpEnd.remainingLiquidity == 0, "remaining liquidity should be 0 at end");
}

function property_secondary_position_is_oor() public {
    // After rebalance the secondary position must be entirely OOR
    _rebalance();

    (uint160 sqrtPriceX96, int24 tick,,,,,) = IUniswapV3Pool(address(pool)).slot0();

    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    int24 secLower = sec.tickLower;
    int24 secUpper = sec.tickUpper;

    // Secondary must be OOR: either entirely below or entirely above current tick
    bool allBelow = secUpper <= tick;   // entirely below: all token1
    bool allAbove = secLower >= tick;   // entirely above: all token0
    t(allBelow || allAbove, "secondary position is in-range, not OOR");
}

