function property_check_pool_activity_consistent() public {
    // If spot tick equals the most recent observed tick average, checkPoolActivity
    // should not return false due to the first delta check
    (, int24 spotTick, uint16 currentIndex, uint16 cardinality,,,) =
        IUniswapV3Pool(address(pool)).slot0();

    (uint32 t1, int56 c1,,) = IUniswapV3Pool(address(pool)).observations(currentIndex);
    uint256 prevIdx = (uint256(cardinality) + currentIndex - 1) % cardinality;
    (uint32 t0, int56 c0,,) = IUniswapV3Pool(address(pool)).observations(prevIdx);

    int24 lastIntervalAvg = t1 > t0
        ? int24((c1 - c0) / int56(uint56(t1 - t0)))
        : spotTick;

    int24 firstDelta = spotTick - lastIntervalAvg;
    if (firstDelta < 0) firstDelta = -firstDelta;

    // If the first delta exceeds maxObservationDeviation, pool activity check
    // fails even with no manipulation — the spot vs avg comparison is the bug
    bool wouldPassFirstCheck = firstDelta <= strategy.maxObservationDeviation();
    bool actualResult = strategy.checkPoolActivity();

    // If first check fails, actualResult is false even if truly safe
    // (This property documents the inconsistency)
    t(wouldPassFirstCheck == actualResult || actualResult == false,
      "checkPoolActivity may block due to spot vs avg tick comparison on first iteration");
}

