function property_get_token_in_multihop_terminates() public {
    // Construct a 2-pool path: WETH -> (fee) -> USDC -> (fee) -> WBTC
    // Each address is 20 bytes, each fee is 3 bytes
    // path encoding: [token0 20b][fee 3b][token1 20b][fee 3b][token2 20b]
    bytes memory multiHopPath = abi.encodePacked(
        address(weth),   // tokenIn
        uint24(3000),    // fee tier 1
        address(usdc),   // intermediate token
        uint24(3000),    // fee tier 2
        address(wbtc)    // tokenOut
    );

    // If _getTokenIn doesn't infinite loop, it should return weth (the final tokenIn)
    // We test via a mock openLeveragedPosition that exercises this path.
    // Instead, we test directly that the path library skipToken works correctly.
    // If the while loop is infinite, any call using multi-hop exactOutput will OOG.

    // We verify property: if hasMultiplePools is true on a 2-pool path,
    // after one skipToken call on the RETURN value, it should have 1 pool.
    // The bug: path.skipToken() return is discarded, path doesn't shrink.

    // Check: encoded 2-pool path length = 20+3+20+3+20 = 66 bytes
    t(multiHopPath.length == 66, "multi-hop path encoding incorrect");

    // After skipToken, the result should have length 66-23 = 43 (single pool)
    bytes memory afterSkip = Path.skipToken(multiHopPath);
    t(afterSkip.length == 43, "skipToken result should be 43 bytes for single pool");

    // But calling path.skipToken() without reassignment leaves path unchanged
    // This is the bug: the loop never terminates
    t(multiHopPath.length == 66, "original path unchanged after skipToken (bug: loop will be infinite)");
}

function property_vesting_fee_collection_uses_correct_ticks() public {
    // Setup: ensure there's an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    // Get vesting position ticks
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The vesting position was created at main position ticks.
    // After a rebalance, mainPosition ticks change. collectFees() wrongly uses
    // mainPosition.tickUpper for the vesting position fee collection.
    // Property: if a rebalance has occurred since vestingPosition was added,
    // the ticks used in collectFees for vesting are WRONG.
    // We verify the bug exists: vestPosition.tickUpper != mainPosition.tickUpper
    // after rebalance (they were equal at creation).
    // If they differ, calling collectFees will collect from wrong ticks.
    (uint256 bal0Before, uint256 bal1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 bal0After, uint256 bal1After) = strategy.idleBalances();

    // After collecting with wrong ticks, vesting position fees not reflected.
    // The test checks that the tick mismatch constitutes a real bug:
    t(vp.tickUpper == mp.tickUpper || !strategy.ongoingVestingPosition(),
      "vesting fee collection uses wrong tickUpper after rebalance");
}

