function property_vesting_monotone_rate() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    if (vpBefore.remainingLiquidity == 0) return;
    if (block.timestamp >= vpBefore.endTs) return;

    uint256 totalDuration = vpBefore.endTs - vpBefore.startTs;
    uint256 elapsed = block.timestamp - vpBefore.lastUpdate;
    if (elapsed == 0) return;

    // Expected liquidity to vest this period based on formula
    uint128 expectedVest = uint128(uint256(vpBefore.initialLiquidity) * elapsed / totalDuration);

    // Collect fees which triggers _withdrawPartOfVestingPosition
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    uint128 actualVested = vpBefore.remainingLiquidity - vpAfter.remainingLiquidity;

    // The actually vested amount should equal expectedVest (within 1 unit rounding)
    t(actualVested <= expectedVest + 1, "vesting withdrew more than formula allows");
}

