function property_balances_includes_vesting_position() public {
    // If there is an ongoing vesting position, balances() should account for it
    // (or at least not let new depositors profit at existing holders' expense).
    // We verify that after a deposit, the depositor cannot immediately withdraw for profit
    // when a vesting position exists.
    bool hasVesting = strategy.ongoingVestingPosition();
    if (!hasVesting) return;

    (uint256 bal0Before, uint256 bal1Before) = vault.balances();
    uint256 supplyBefore = vault.totalSupply();

    uint256 depositAmt0 = ONE_TOKEN0;
    uint256 depositAmt1 = ONE_TOKEN1 * 60_000; // ~$60k USDC

    deal(address(wbtc), attacker, depositAmt0);
    deal(address(usdc), attacker, depositAmt1);

    vm.startPrank(attacker);
    wbtc.approve(address(vault), depositAmt0);
    usdc.approve(address(vault), depositAmt1);
    (uint256 shares,,) = vault.deposit(depositAmt0, depositAmt1, 0, 0);

    // Immediate withdrawal — should not profit
    (uint256 got0, uint256 got1) = vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    // Depositor should not receive more than they deposited (allowing small rounding)
    // Compute value in token1 terms using vault price
    uint256 _price = vault.price(); // 1e30 precision
    uint256 valueIn = depositAmt0 * _price / 1e30 + depositAmt1;
    uint256 valueOut = got0 * _price / 1e30 + got1;

    // After deposit+fee and immediate withdraw, should not profit
    lte(valueOut, valueIn, "attacker profited from vesting position undervaluation");
}

function property_vesting_fees_collected_correctly() public {
    bool hasVesting = strategy.ongoingVestingPosition();
    if (!hasVesting) return;

    // Get vesting position tick range
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // After a rebalance, mainPosition.tickUpper may differ from vestPosition.tickUpper
    // If they differ, collectFees uses wrong range for vesting position
    if (vp.tickUpper == mp.tickUpper) return; // not yet diverged — skip

    // Record balances before collectFees
    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();

    // Trigger collectFees via deposit of 1 wei (so it won't fail on 0 amounts)
    // We can call strategy.collectFees directly since it's public
    vm.prank(rebalancer);
    strategy.collectFees();

    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // If vesting position fees were collected correctly, idle balances should increase
    // We can't easily measure the exact amount but we verify the ticks are consistent
    // The real bug: vp.tickUpper != mp.tickUpper => wrong range used
    t(vp.tickUpper == mp.tickUpper,
      "vesting position tickUpper diverges from mainPosition after rebalance: fees lost");
}

