function property_fullmath_muldiv_correctness() public pure {
    // Test that mulDiv(a, b, d) == a*b/d for known values where the 512-bit path is used
    // Use values where a*b > 2^256 to force the slow path
    // Example: a = 2^200, b = 2^100, d = 2^50 -> result = 2^250
    // This tests the Newton-Raphson convergence with the buggy XOR seed
    uint256 a = type(uint256).max / 3; // large non-power-of-2
    uint256 b = type(uint256).max / 7;
    uint256 d = type(uint256).max / 5; // odd denominator forces Newton-Raphson path
    // If mulDiv is correct: result should equal floor(a*b/d)
    // We can verify using a reference computation
    uint256 result = FullMath.mulDiv(a, b, d);
    // Cross-check: result * d <= a * b < (result+1) * d
    // Can't directly compute a*b due to overflow, but we can check consistency:
    // result * d should be approximately a * b, i.e. result ~= a/d * b
    uint256 approx = (a / d) * b;
    // The result should be within a factor-of-d of the approximation
    t(result >= approx, "mulDiv underestimates due to XOR bug in Newton-Raphson seed");
}

