function property_vesting_fees_correctly_attributed() public {
    // Setup: ensure there is an ongoing vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper for vesting position collect
    // If vestPosition.tickUpper != mainPosition.tickUpper, fees go to wrong position
    // After a rebalance, main position ticks change but vesting ticks stay the same
    // So vestPosition.tickUpper should equal the ticks AT TIME OF VESTING CREATION

    // Invariant: vesting position ticks must be non-zero and valid
    t(vp.tickLower < vp.tickUpper, "vesting position ticks invalid");
    // If main position has been rebalanced, tickUpper may differ
    // We just verify the bug path: collect using vestPosition.tickUpper not mainPosition.tickUpper
    // We can observe: if they differ, fees are never collected for vesting
    // Property: after collecting fees, strategy idle balance should increase
    // (fees from vesting position captured)
    uint256 bal0Before = wbtc.balanceOf(address(strategy));
    uint256 bal1Before = usdc.balanceOf(address(strategy));

    strategy.collectFees();

    uint256 bal0After = wbtc.balanceOf(address(strategy));
    uint256 bal1After = usdc.balanceOf(address(strategy));

    // If mainPosition ticks differ from vestPosition ticks, fees may not be collected
    // This property just ensures the call doesn't silently operate on wrong position
    // The real invariant: vesting collect must use the STORED vesting ticks
    if (vp.tickUpper != mp.tickUpper) {
        // After rebalance diverged the ticks, vesting fees are stranded
        // collectFees should still increase balances from actual vesting fees
        // This will fail because it uses wrong tickUpper (mainPosition.tickUpper)
        t(bal0After >= bal0Before || bal1After >= bal1Before, "vesting fees not collected after rebalance diverged ticks");
    }
}

function property_vesting_linear_schedule_respected() public {
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.initialLiquidity == 0) return;
    if (vp.endTs <= vp.startTs) return;

    uint256 elapsed = block.timestamp >= vp.endTs
        ? vp.endTs - vp.startTs
        : block.timestamp - vp.startTs;
    uint256 totalDuration = vp.endTs - vp.startTs;

    // Expected vested fraction: elapsed / totalDuration of initialLiquidity
    uint256 expectedVested = uint256(vp.initialLiquidity) * elapsed / totalDuration;
    uint256 actualVested = uint256(vp.initialLiquidity) - uint256(vp.remainingLiquidity);

    // remainingLiquidity should never exceed initialLiquidity minus what's been vested
    // actualVested should be >= expectedVested (we should have given out at least the elapsed share)
    // With rounding down, actualVested may be slightly below expectedVested — that's the bug
    lte(expectedVested, uint256(vp.initialLiquidity), "expected vested exceeds initial");
    // The invariant that should hold: actualVested >= expectedVested - tolerance
    // In practice rounding causes actualVested < expectedVested
    t(
        actualVested + 1 >= expectedVested || block.timestamp < vp.startTs,
        "vesting underpays: actualVested far below expectedVested"
    );
}

