function property_vesting_fee_collection_uses_correct_ticks() public {
    // Only meaningful when a vesting position exists
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper for the vesting position,
    // not vestPosition.tickUpper. If they differ after a rebalance, the wrong
    // position is targeted.
    // This property checks that IF the ticks differ, collectFees still works
    // without reverting and correctly increments strategy idle balances.
    if (vp.tickUpper != mp.tickUpper) {
        (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
        strategy.collectFees();
        (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();
        // If the bug is present, no fees are collected from vesting position —
        // idle balances may not increase even though fees should exist.
        // We assert that collecting fees doesn't silently fail (no revert).
        // The actual invariant is that vp.tickUpper is used, not mp.tickUpper.
        t(vp.tickUpper == mp.tickUpper || idle0After >= idle0Before, "vesting fee collection used wrong tick");
    }
}

function property_vesting_withdrawal_no_underflow(uint256 timeElapsed1, uint256 timeElapsed2) public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.endTs <= vp.startTs || vp.endTs <= block.timestamp) return;

    uint256 duration = vp.endTs - vp.startTs;

    // First partial withdrawal after timeElapsed1
    timeElapsed1 = _clampBetween(timeElapsed1, 1, duration / 2);
    skip(timeElapsed1);
    if (block.timestamp >= vp.endTs) return;

    // This calls _withdrawPartOfVestingPosition internally
    strategy.collectFees();

    // Second partial withdrawal after timeElapsed2
    timeElapsed2 = _clampBetween(timeElapsed2, 1, duration / 2);
    skip(timeElapsed2);
    if (block.timestamp >= vp.endTs) return;

    // If bug exists: liquidityToRemove may exceed remainingLiquidity -> underflow -> revert
    strategy.collectFees();

    // If we reach here without revert, no underflow occurred
    t(true, "no underflow in vesting withdrawal");
}

function property_initial_ticks_near_twap() public view {
    // The initial position ticks should be within tickTwapDeviation of TWAP
    int24 twapT = strategy.twapTick();
    int24 mainLower = strategy.getMainPosition().tickLower;
    int24 mainUpper = strategy.getMainPosition().tickUpper;
    int24 midTick = (mainLower + mainUpper) / 2;
    int24 deviation = strategy.tickTwapDeviation();

    // If construction used spot price instead of TWAP, midTick may deviate
    int24 diff = midTick - twapT;
    if (diff < 0) diff = -diff;
    t(diff <= deviation, "initial main position ticks deviate excessively from TWAP");
}

function property_collectFees_never_reverts_with_valid_recipient() public {
