    // Test that collectFees succeeds with the current feeRecipient
    uint256 bal0Before = wbtc.balanceOf(feeRecipient);
    uint256 bal1Before = usdc.balanceOf(feeRecipient);

    // Should not revert
    strategy.collectFees();

    uint256 bal0After = wbtc.balanceOf(feeRecipient);
    uint256 bal1After = usdc.balanceOf(feeRecipient);

    // feeRecipient should have received at least as many tokens
    gte(bal0After, bal0Before, "fee recipient token0 balance should not decrease");
    gte(bal1After, bal1Before, "fee recipient token1 balance should not decrease");
}

function property_positionWidth_consistent_with_position_range() public view {
    uint24 width = strategy.positionWidth();
    IStrategy.Position memory mp = strategy.getMainPosition();
    int24 tickLower = mp.tickLower;
    int24 tickUpper = mp.tickUpper;
