function property_swap_amount_in_bounded_by_amountout() public {
    // swapParams.amountIn for token0 swap must not exceed amountOut0
    // swapParams.amountIn for token1 swap must not exceed amountOut1
    // This is a conceptual property; in practice the contract does not enforce this,
    // relying instead on underflow revert in Solidity 0.8
    uint256 amountOut0 = 50e18;
    uint256 swapAmountIn = 100e18; // user-provided, exceeds balance
    // This would underflow: amountOut0 -= swapAmountIn
    t(swapAmountIn <= amountOut0, "swapParams.amountIn exceeds amountOut0: underflow risk");
}

function property_withdraw_token1_denomination_does_not_revert() public {
    // Simulate the buggy withdraw calculation for token1 denomination
    uint256 amountOut0 = 100e6;   // e.g. WBTC amount (larger)
    uint256 amountOut1 = 80e6;    // e.g. USDC amount (smaller)
    uint256 owedAmount = 90e6;    // debt in USDC
    // Buggy code: amountOut1 < owedAmount ? amountOut0 : owedAmount
    // 80 < 90 is true, so repayFromWithdraw = amountOut0 = 100
    uint256 repayFromWithdraw = amountOut1 < owedAmount ? amountOut0 : owedAmount;
    // amountOut1 -= repayFromWithdraw → 80 - 100 → UNDERFLOW
    // This would revert in production
    t(repayFromWithdraw <= amountOut1, "withdraw token1 branch: repayFromWithdraw > amountOut1 causes underflow");
}

function property_pullFunds_accounting_consistent() public {
    // Setup: leverager pulls some funds without borrow accounting
    uint256 availBefore = lendingPool.totalLiquidityOfReserve(address(asset));
    uint256 yTokenBal = asset.balanceOf(address(yAsset));

    // After pullFunds, underlyingBalance should decrease to match actual balance
    // The protocol invariant: reserve.underlyingBalance == asset.balanceOf(yAsset)
    // (when no funds are currently borrowed via borrow())
    // If leverager has never called borrow(), totalBorrows == 0, so:
    // totalLiquidity = underlyingBalance + borrowedLiquidity (= 0)
    // Therefore totalLiquidity should equal yToken's actual balance

    // Simulate: leverager pulls half the liquidity
    uint256 pullAmount = yTokenBal / 2;
    if (pullAmount == 0) return;

    _pullFundsAsLeverager(pullAmount);

    uint256 actualBalance = asset.balanceOf(address(yAsset));
    uint256 reportedLiquidity = lendingPool.totalLiquidityOfReserve(address(asset));

    // After pullFunds (with no prior borrows), reported liquidity should
    // equal actual token balance held by yToken
    // Bug: reportedLiquidity still shows pre-pull value
    t(
        reportedLiquidity <= actualBalance + 1,
        "pullFunds: reported liquidity exceeds actual yToken balance — accounting diverged"
    );
}

function property_borrow_respects_actual_balance() public {
    // After pullFunds + borrow, total outflow should not exceed initial balance
    uint256 initialBalance = asset.balanceOf(address(yAsset));
    if (initialBalance < 2) return;

    uint256 pullAmount = initialBalance / 2;
    uint256 borrowAmount = initialBalance / 4;

    _pullFundsAsLeverager(pullAmount);
    _borrowAsLeverager(borrowAmount);

    // Total tokens removed from yToken = pullAmount + borrowAmount
    // yToken actual balance should be initialBalance - pullAmount - borrowAmount
    uint256 expectedBalance = initialBalance - pullAmount - borrowAmount;
    uint256 actualBalance = asset.balanceOf(address(yAsset));

    eq(
        actualBalance,
        expectedBalance,
        "borrow after pullFunds: actual yToken balance does not match expected"
    );

    // And underlyingBalance (= availableLiquidity) should reflect reality
    uint256 reportedAvailable = lendingPool.totalLiquidityOfReserve(address(asset));
    t(
        reportedAvailable <= actualBalance + lendingPool.totalBorrowsOfReserve(address(asset)) + 1,
        "borrow: totalLiquidity exceeds actual held + recorded borrows"
    );
}

function property_first_deposit_no_dust_ytokens() public {
    // Only meaningful when yToken totalSupply is 0
    // We need a fresh reserve; use a new asset to simulate first deposit
    // In the existing setup, user already deposited INITIAL_DEPOSIT, so
    // totalSupply > 0. We test using a scenario where depositor gets just
    // above MINIMUM_YTOKEN_AMOUNT yTokens.
    // On first deposit: yTokenAmount = amount * PRECISION / PRECISION = amount
    // (rate is PRECISION when totalSupply==0 or totalLiquidity==0)
    // So minting exactly 1001 yTokens requires depositing 1001 wei (18 dec asset)
    // But initial deposit already happened. We check the net-to-depositor invariant:
    // For any successful deposit when totalSupply WAS 0:
    //   depositor_yTokens_received >= MINIMUM_YTOKEN_AMOUNT + 1
    // We can't replay first deposit in current state, so check the current exchange
    // rate invariant: yToken total supply should always be >= MINIMUM_YTOKEN_AMOUNT
    // (the dead address holds at least that many)
    uint256 supply = _getYTokenTotalSupply();
    t(
        supply == 0 || supply > MINIMUM_YTOKEN_AMOUNT,
        "first deposit: yToken supply should be > MINIMUM_YTOKEN_AMOUNT after first deposit"
    );

    // More directly: after first deposit passes, depositor yToken balance must be > 0
    // Check that if yToken supply = MINIMUM_YTOKEN_AMOUNT (only dead address holds it),
    // depositor received nothing — which would be a bug
    uint256 deadBalance = IERC20(address(yAsset)).balanceOf(
        address(0x000000000000000000000000000000000000dEaD)
    );
    if (deadBalance > 0) {
        // Dead address received the burn; check depositor got meaningful amount
        t(
            supply > deadBalance,
            "first deposit: depositor received zero yTokens (all burned to dead address)"
        );
    }
}

function property_pause_blocks_pullFunds() public {
    _pauseAsOwner();
    t(_isPaused(), "should be paused");

    uint256 yTokenBalBefore = asset.balanceOf(address(yAsset));
    if (yTokenBalBefore == 0) {
        _unpauseAsOwner();
        return;
    }

    // pullFunds should be blocked when paused if the invariant holds
    // Bug: pullFunds has no notPaused modifier
    // We verify: after pause, yToken balance should not decrease via leverager actions
    // This property checks that leverager cannot pull funds while paused
    // (it will NOT revert currently — this is the bug)
    uint256 pullAmount = yTokenBalBefore / 2;
    if (pullAmount == 0) {
        _unpauseAsOwner();
        return;
    }

    _pullFundsAsLeverager(pullAmount);

    uint256 yTokenBalAfter = asset.balanceOf(address(yAsset));

    // After pause, yToken balance should NOT have decreased
    t(
        yTokenBalAfter >= yTokenBalBefore,
        "pullFunds: leverager drained yToken funds while contract was paused"
    );

    _unpauseAsOwner();
}

function property_leverager_is_changeable_by_owner() public {
    // The leverager address as set in setup
    address currentLeverager = lendingPool.leverager();
    t(currentLeverager != address(0), "leverager should be set");

    // Attempt to change leverager to a new safe address (as owner)
    // This should succeed if the protocol allows recovery from compromised leverager
    // Bug: it will revert because setLeverager can only be called once
    address newLeverager = address(0x99999);
    vm.prank(owner);
    try lendingPool.setLeverager(newLeverager) {
        // If it succeeds: no bug for recoverability
        t(lendingPool.leverager() == newLeverager, "leverager should have changed");
    } catch {
        // If it reverts: the owner cannot recover from a compromised leverager
        // This is the bug: no recoverability path exists
        t(false, "owner cannot change leverager after initial set — no recovery path");
    }
}

function property_total_liquidity_backed_by_assets() public {
    // Core solvency invariant: totalLiquidity should not exceed actual assets
    // backing the pool (yToken balance + totalBorrows principal)
    uint256 totalLiquidity = lendingPool.totalLiquidityOfReserve(address(asset));
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(address(asset));
    uint256 yTokenAssetBal = asset.balanceOf(address(yAsset));

    // yTokenAssetBal + totalBorrows should equal totalLiquidity
    // (totalBorrows includes accrued interest in the reporting function)
    // If pullFunds has been used without pushFunds, yTokenAssetBal is lower than expected
    // giving: yTokenAssetBal + totalBorrows < totalLiquidity  => insolvency signal

    // Allow 1 wei tolerance for rounding
    t(
        yTokenAssetBal + totalBorrows + 1 >= totalLiquidity,
        "solvency: yToken balance + totalBorrows < reported totalLiquidity (pullFunds divergence)"
    );
}

function property_getTokenIn_bounded_gas() public {
    // Construct a malicious path with many hops: 200 hops = 200*23 + 20 bytes
    // Each hop = 20 (addr) + 3 (fee)
    uint256 numHops = 200;
    uint256 pathLen = 20 + numHops * 23; // tokenA + numHops*(fee+tokenB)
    bytes memory maliciousPath = new bytes(pathLen);
    // Fill with non-zero data to simulate real addresses
    for (uint256 i = 0; i < pathLen; i++) {
        maliciousPath[i] = 0x01;
    }
    // If the loop is unbounded, this call should OOG revert
    // The property asserts that it must complete within reasonable gas
    uint256 gasBefore = gasleft();
    // Simulate what _getTokenIn does
    bytes memory path = maliciousPath;
    uint256 iterations = 0;
    while (path.length >= 20 + 23 + 23) { // MULTIPLE_POOLS_MIN_LENGTH = 20+3+20+23 = 66
        path = path.length >= 23 ? new bytes(path.length - 23) : new bytes(0);
        iterations++;
        if (iterations > 50) break; // property: should not need > 50 iterations
    }
    uint256 gasUsed = gasBefore - gasleft();
    t(gasUsed < 5_000_000, "getTokenIn loop consumes excessive gas");
}

