description:
In `liquidatePosition()` the denomination repayment branches are:

  if (up.denomination == up.token0) {
      uint256 repayFromWithdraw = amount0 < owedAmount ? amount0 : owedAmount;
      owedAmount -= repayFromWithdraw;
      amount0 -= repayFromWithdraw;
  }

  if (up.denomination == up.token1) {   // ← second `if`, not `else if`
      uint256 repayFromWithdraw = amount1 < owedAmount ? amount1 : owedAmount;
      owedAmount -= repayFromWithdraw;
      amount1 -= repayFromWithdraw;
  }

Compare with `withdraw()` which correctly uses `else if` for the token1 branch.

In practice, for normal ERC20 vaults, token0 != token1 is guaranteed by pool construction.
However if a vault were ever initialised with token0 == token1 (malformed vault, governance
error, or future edge case), denomination could match BOTH conditions. The first branch
would correctly drain owedAmount from amount0; the second branch would then see
owedAmount == 0, repayFromWithdraw = 0, and is a no-op — so no double-charge occurs.

The risk is LOW for normal operation but represents a structural inconsistency with
`withdraw()`. If a future code path allows denomination == token0 == token1 in some
wrapped-token scenario, the double-if could silently produce unexpected state. The
`withdraw()` pattern (`else if`) is the safer idiom and should be consistent.

solidity:
function prop_liquidation_denomination_not_double_counted() public {
    t(false, "placeholder — Chimera setup required");
}

function property_vesting_fees_collected_correctly() public {
    // Setup: ensure there is an ongoing vesting position
    if (!_isOngoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // The bug: collectFees uses mainPosition.tickUpper for the vesting position
    // vest position should use its own tickUpper, not mainPosition.tickUpper
    // If a rebalance happened after addVestingPosition, ticks diverge
    // Check that vestPosition ticks match what collectFees actually uses
    // If vp.tickUpper != mp.tickUpper, the collectFees call targets wrong range
    // This is the invariant that should hold: vesting collect uses vp ticks
    t(vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
      "vesting position ticks should match main at creation");
}

function property_vesting_remaining_never_underflows() public {
    if (!_isOngoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    // remainingLiquidity should never exceed initialLiquidity
    gte(uint256(vp.initialLiquidity), uint256(vp.remainingLiquidity),
        "remainingLiquidity cannot exceed initialLiquidity");
    // Also verify collectFees can always complete without revert
    // by checking the formula won't compute more than remaining
    uint256 lastValid = block.timestamp < vp.endTs ? block.timestamp : vp.endTs;
    if (lastValid != vp.endTs && vp.lastUpdate != block.timestamp) {
        uint128 wouldRemove = uint128(
            uint256(vp.initialLiquidity) * (lastValid - vp.lastUpdate) / (vp.endTs - vp.startTs)
        );
        gte(uint256(vp.remainingLiquidity), uint256(wouldRemove),
            "formula would not underflow remainingLiquidity");
    }
}

function property_collectFees_anyone_callable() public {
    // Verify collectFees has no auth check by calling as attacker
    uint256 preBal0 = _getWbtcBalance(feeRecipient);
    uint256 preBal1 = _getUsdcBalance(feeRecipient);
    vm.prank(attacker);
    strategy.collectFees(); // should NOT revert - it's public with no auth
    // If we get here, the function is callable by anyone
    t(true, "collectFees callable by anyone - no auth check");
}

function property_mint_callback_only_pool() public {
    // uniswapV3MintCallback should revert when called by non-pool
    uint256 bal0Before = _getWbtcBalance(address(strategy));
    uint256 bal1Before = _getUsdcBalance(address(strategy));
    // Attacker tries to call uniswapV3MintCallback directly
    vm.prank(attacker);
    try strategy.uniswapV3MintCallback(1, 1, "") {
        // If it didn't revert, check no tokens were sent
        uint256 bal0After = _getWbtcBalance(address(strategy));
        uint256 bal1After = _getUsdcBalance(address(strategy));
        // Should have reverted - if not, tokens may have been drained
        t(bal0After >= bal0Before, "token0 not drained by callback");
        t(bal1After >= bal1Before, "token1 not drained by callback");
    } catch {
        t(true, "callback correctly reverted for non-pool caller");
    }
}

function property_collectFees_uses_correct_vesting_ticks() public {
    if (!_isOngoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // After a rebalance, main position ticks change but vesting ticks are fixed
    // If they differ, collectFees will call collectPositionFees with wrong tickUpper
    // This invariant captures the bug: if ticks diverge, collectFees is broken
    // The correct behavior is to use vp.tickUpper, not mp.tickUpper
    bool ticksMatch = (vp.tickUpper == mp.tickUpper);
    // If ticks don't match, collectFees will target wrong position
    // We check collectFees doesn't revert even when ticks diverge
    if (!ticksMatch) {
        try strategy.collectFees() {
            t(false, "collectFees should fail when vesting ticks diverge from main");
        } catch {
            t(true, "collectFees correctly fails - bug confirmed: wrong tick reference");
        }
    } else {
        strategy.collectFees();
        t(true, "collectFees succeeded when ticks match");
    }
}

function property_twap_cast_no_overflow() public {
    uint32 currentTwap = _getTwap();
    // int32 max is 2^31 - 1 = 2147483647
    // If twap > int32 max, cast overflows
    t(currentTwap <= uint32(type(int32).max),
      "twap must fit in int32 to avoid overflow in twapTick division");
    // Also verify setTwap has no upper bound (owner can set arbitrarily high)
    // The vulnerability: no upper bound in setTwap allows overflow
    int24 twapTickVal = strategy.twapTick();
    // twapTick should be within valid tick range
    t(twapTickVal >= TickMath.MIN_TICK && twapTickVal <= TickMath.MAX_TICK,
      "TWAP tick should be within valid range");
}

function property_checkPoolActivity_does_not_oog() public {
    // Verify the pool's observation cardinality stays within a safe gas budget.
    // A very high cardinality means checkPoolActivity() will OOG and permanently
    // block rebalance/compound/addVestingPosition.
    (,, , uint16 cardinality,,,) = IUniswapV3Pool(POOL_ADDR).slot0();
    // If cardinality is above ~1000, the loop in checkPoolActivity() can exceed
    // practical gas limits when called inside a transaction.
    t(cardinality <= 1000, "pool observation cardinality is too large: checkPoolActivity will OOG");
}

function property_checkPoolActivity_no_zero_timestamp_revert() public {
    // Attempt to call checkPoolActivity; it should never revert under normal conditions.
    // If it reverts with "timestamp 0", the rebalance/compound path is permanently broken.
    (bool ok,) = address(strategy).call(abi.encodeWithSignature("checkPoolActivity()"));
    t(ok, "checkPoolActivity reverted: timestamp 0 DoS bricks rebalance and compound");
}

function property_vesting_fee_collection_uses_correct_ticks() public {
    // After a rebalance, if there is an ongoing vesting position, verify that
    // the ticks used by collectFees for the vesting position match vestPosition.tickUpper,
    // not mainPosition.tickUpper.
    (,, uint128 initLiq, uint128 remLiq,,, uint256 lastUpdate) = strategy.vestPosition();
    bool hasVesting = strategy.ongoingVestingPosition();
    if (!hasVesting) return;

    (int24 vestTickLower, int24 vestTickUpper,) = (0, 0, 0); // placeholder
    // Use getVestingPosition() which returns the struct
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If main ticks have changed since vesting was set up, collectFees will
    // use wrong tickUpper, silently losing fees.
    t(
        vp.tickUpper == mp.tickUpper,
        "vestPosition.tickUpper diverged from mainPosition.tickUpper: collectFees uses wrong ticks, vesting fees lost"
    );
}

function property_withdraw_not_blocked_by_collectFees() public {
    uint256 shares = vault.balanceOf(user);
    if (shares == 0) return;
    uint256 halfShares = shares / 2;
    if (halfShares == 0) return;
    (bool ok,) = address(vault).call(
        abi.encodeWithSelector(vault.withdraw.selector, halfShares, 0, 0)
    );
    t(ok, "withdraw blocked: collectFees reverted, all withdrawals permanently DoSed");
}

function property_small_deposit_gets_nonzero_shares() public {
    // A small but nonzero deposit should always yield nonzero shares.
    // If donation inflates balances, small deposits get 0 shares and revert.
    uint256 smallAmt0 = ONE_TOKEN0 / 1000; // 0.001 WBTC
    uint256 smallAmt1 = ONE_TOKEN1 * 100;  // 100 USDC
    deal(WBTC_ADDR, depositor, smallAmt0);
    deal(USDC_ADDR, depositor, smallAmt1);
    vm.prank(depositor);
    (bool ok, bytes memory ret) = address(vault).call(
        abi.encodeWithSelector(vault.deposit.selector, smallAmt0, smallAmt1, 0, 0)
    );
    // We don't assert ok==true always (slippage can fail), but if it fails with
    // "shares cant be 0" that indicates share-inflation DoS.
    if (!ok) {
        // Check the revert reason is not "shares cant be 0"
        t(keccak256(ret) != keccak256(abi.encodeWithSignature("Error(string)", "shares cant be 0")),
          "small deposit DoSed by share inflation: shares computed as 0");
    }
}

function property_checkPoolActivity_returns_true_after_setup() public {
    // After the setup rebalance and 10-minute skip, checkPoolActivity should return true.
    // If it returns false, all rebalance/compound calls are blocked.
    bool active = strategy.checkPoolActivity();
