function property_withdraw_token1_repay_correct() public {
    // The withdraw function has a copy-paste bug on line 232:
    // `repayFromWithdraw = amountOut1 < owedAmount ? amountOut0 : owedAmount`
    // It should be `amountOut1 : owedAmount`.
    // This property checks that after a withdraw where denomination == token1,
    // the amounts are consistent (not testing the actual execution, but the
    // static code path logic).
    // In a Chimera fuzzing context: if this property is violated, the bug is triggered.
    // We document the code invariant that should hold:
    // repayFromWithdraw must be <= amountOut1 when borrowed == token1
    // The bug makes it = amountOut0 in the true branch, which may be >> amountOut1.
    uint256 amountOut1 = 500e6;  // example: 500 USDC
    uint256 owedAmount = 700e6;  // owed more than withdrawn
    uint256 amountOut0 = 1e8;    // 1 WBTC = 100_000_000 raw units
    // buggy code:
    uint256 repayFromWithdraw = amountOut1 < owedAmount ? amountOut0 : owedAmount;
    // should be: amountOut1 < owedAmount ? amountOut1 : owedAmount
    // The bug: repayFromWithdraw = amountOut0 (wrong token!)
    t(repayFromWithdraw <= amountOut1, "repayFromWithdraw must not exceed token1 withdrawn");
}

function property_liquidation_borrow_value_denominator() public {
    // Demonstrate the decimals() vs 10**decimals() bug.
    // For USDC (6 decimals): denominator should be 1_000_000 but is 6.
    uint8 dec = 6; // USDC decimals
    uint256 owedAmount = 5000e6;
    uint256 bPrice = 1e18; // $1 per USDC in 1e18
    // correct:
    uint256 correctBorrowedValue = owedAmount * bPrice / (10 ** uint256(dec));
    // buggy (as coded):
    uint256 buggyBorrowedValue = owedAmount * bPrice / uint256(dec);
    // buggyBorrowedValue is ~166666x larger than correctBorrowedValue
    t(buggyBorrowedValue == correctBorrowedValue, "borrowedValue denominator must use 10**decimals not raw decimals");
}

function property_fee_recipient_not_zero() public {
