    // In the actual contract, feeRecipient is never initialized.
    // This property would be tested by checking the storage slot directly,
    // but since we cannot call Leverager internals, we use the public getter.
    // address fr = leverager.feeRecipient();
    // t(fr != address(0), "feeRecipient must not be zero address");
    // Static check: the constructor does not set feeRecipient, and no setter exists.
    // Any profitable liquidation that takes a fee will safeTransfer to address(0).
    t(false, "feeRecipient is never initialized - profitable liquidations will DoS or burn fees");
}

function property_borrow_amount_not_manipulable_by_donation() public {
