description:
After repaying the denomination token, if any balance remains in the Leverager, the code at line 171-172 repays it:
  uint256 denomBalance = IERC20(lp.denomination).balanceOf(address(this));
  ILendingPool(lendingPool).repay(lp.denomination, denomBalance);
Then _sweepTokens sweeps token0 and token1 to msg.sender. However, if denomination == token0 or denomination == token1, _sweepTokens will send any remaining denomination balance to the caller. The repay at line 172 should consume all denomination tokens, but if the denomination is also token0 or token1, the sweep will send those tokens too. More dangerously: if a previous failed transaction left denomination tokens in the contract (as the comment acknowledges), the next user's transaction sweeps those stuck tokens. This is an intentional design decision per the comment, but it creates a MEV/griefing vector where an attacker can grief future users by pre-depositing dust denomination tokens.

solidity:
function property_open_borrow_amount_non_negative() public {
    // Invariant: borrowedAmount stored in position must equal
    // maxBorrowAmount - denomBalance at time of opening.
    // If an external actor inflates denomBalance beyond maxBorrowAmount,
    // this underflows and reverts (Solidity 0.8+).
    // We verify: no position has borrowedAmount == 0 after a legitimate open.
    uint256 posId = 1;
    (,uint256 borrowedAmount,,,,,,,,, ) = leverager.getPosition(posId);
    if (borrowedAmount == 0) {
        t(false, "open position must have non-zero borrowedAmount");
    }
}

description:
In the hasToSwap block of withdraw(), after the exactInput swap for token0:
  amountOut0 -= swapParams.amountIn;
And for token1:
  amountOut1 -= swapParams.amountIn;
There is no check that swapParams.amountIn <= amountOut0 (resp. amountOut1). If the user (or attacker if they can set swapParams) specifies an amountIn larger than the actual amountOut, this underflows in Solidity 0.8+ and reverts. While the caller controls swapParams, this means a user error (or carefully crafted params) causes permanent DoS on their withdrawal for that specific call. More critically, the forceApprove grants the router access to amountIn tokens, but the Leverager might not hold that many tokens (amountOut was reduced by repayFromWithdraw). A malicious router could drain more tokens than intended if forceApprove > actual balance.

solidity:
function property_withdraw_swap_amount_bounded() public {
    // After withdraw with swap, no token0 or token1 balance should be negative.
    // The invariant: amountOut0/1 >= swapParams.amountIn for each swap.
    // We check that Leverager's balance of vault tokens doesn't decrease unexpectedly.
    uint256 posId = 1;
    (,uint256 borrowedAmount,,,,, uint256 shares, address vault, address token0, address token1, ) = leverager.getPosition(posId);
    if (shares > 0) {
        uint256 bal0Before = IERC20(token0).balanceOf(address(leverager));
        uint256 bal1Before = IERC20(token1).balanceOf(address(leverager));
        // Leverager should hold no token balances outside of active operations
        t(bal0Before == 0, "Leverager should hold zero token0 between txs");
        t(bal1Before == 0, "Leverager should hold zero token1 between txs");
    }
}

function property_OH001_deposit_shares_not_inflated_by_spot_price() public {
    // Record state before manipulation attempt
    uint256 spotPrice = strategy.price();
    uint256 twapPriceVal = strategy.twapPrice();

    // If spot and TWAP prices diverge significantly (>5%), deposit should not benefit attacker
    // Property: shares minted per unit deposited should not exceed TWAP-based fair value by >5%
    // We check: if prices are diverged, the vault's share price should stay bounded

    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 totalSup = vault.totalSupply();

    if (totalSup > 0 && bal0 > 0 && bal1 > 0) {
        // price() is spot (slot0), twapPrice() is TWAP — they should not diverge >10%
        // 1e30 precision; 10% tolerance = 1e29
        uint256 diff = spotPrice > twapPriceVal ? spotPrice - twapPriceVal : twapPriceVal - spotPrice;
        uint256 tenPct = twapPriceVal / 10;
        // If spot diverges >10% from TWAP, balances() is using a manipulated price for share math
        t(diff <= tenPct, "OH-001: spot price diverges >10% from TWAP — balances() is manipulable");
    }
}

function property_OH002_withdraw_amount_bounded_by_pro_rata() public {
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;

    uint256 totalSup = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    // Compute expected pro-rata
    uint256 expectedAmt0 = bal0 * userShares / totalSup;
    uint256 expectedAmt1 = bal1 * userShares / totalSup;

    // Withdraw
    vm.prank(user);
    (uint256 got0, uint256 got1) = vault.withdraw(userShares, 0, 0);

    // The withdrawn amounts should not exceed pro-rata by more than 1% (rounding)
    // If spot is manipulated, got0/got1 could be inflated
    uint256 maxAllowed0 = expectedAmt0 + expectedAmt0 / 100 + 1;
    uint256 maxAllowed1 = expectedAmt1 + expectedAmt1 / 100 + 1;

    lte(got0, maxAllowed0, "OH-002: withdraw token0 exceeds pro-rata share");
    lte(got1, maxAllowed1, "OH-002: withdraw token1 exceeds pro-rata share");
}

function property_OH004_secondary_position_is_oor_on_correct_side() public {
    (, int24 currentTick,,,,,) = IUniswapV3Pool(POOL_ADDR).slot0();

    (int24 secTickLower, int24 secTickUpper,) = strategy.secondaryPosition();

    // Secondary position must be fully out-of-range — either entirely above or below current tick
    bool aboveRange = currentTick >= secTickUpper;
    bool belowRange = currentTick < secTickLower;

    t(aboveRange || belowRange, "OH-004: secondary position is not out-of-range");
}

function property_OH006_balances_includes_vesting_position() public {
    // If there's an ongoing vesting position, balances() should reflect it
    bool hasVesting = strategy.ongoingVestingPosition();
    if (!hasVesting) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    // Vesting position should contribute to balances beyond idle + main + secondary
    // We check: bal0 or bal1 must exceed idle alone by some amount
    // (crude check — in practice we'd compare before/after vesting is added)
    // If vesting has liquidity, reported balances should be > idle
    uint128 vestLiq = strategy.getVestingPosition().remainingLiquidity;
    if (vestLiq > 0) {
        // Vesting position has liquidity but balances() may not include it
        // Get sqrtPrice to compute approximate value
        (uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(POOL_ADDR).slot0();
        (int24 vTickLower, int24 vTickUpper,,,,,,) = strategy.vestPosition();
        (uint256 vest0, uint256 vest1) = LiquidityAmounts.getAmountsForLiquidity(
            sqrtPriceX96,
            TickMath.getSqrtRatioAtTick(vTickLower),
            TickMath.getSqrtRatioAtTick(vTickUpper),
            vestLiq
        );
        // balances() should include this vesting value
        // If vest0 > 0, total bal0 should be > idle0 + main0 + sec0 (which excludes vesting)
        // We flag: if vesting contributes significant value but is missing from balances
        uint256 vestValue0 = vest0;
        uint256 vestValue1 = vest1;
        // The following will trigger if vesting position has meaningful value not in balances()
        t(
            vestValue0 == 0 && vestValue1 == 0,
            "OH-006: vesting position has value not reflected in balances() — share price wrong"
        );
    }
}

