function property_compound_no_interval_restriction() public {
    // compound() has no rebalanceInterval check unlike rebalance()
    // It can be called back-to-back by the rebalancer
    uint256 feeRecipientBal0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1Before = usdc.balanceOf(feeRecipient);

    // First compound
    vm.prank(rebalancer);
    strategy.compound();

    // Second compound immediately (no time check)
    vm.prank(rebalancer);
    strategy.compound();

    // Third compound immediately
    vm.prank(rebalancer);
    strategy.compound();

    // All three succeeded — compound can be called without time restriction
    // This is fine on its own, but enables griefing via repeated fee extraction
    uint256 feeRecipientBal0After = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1After = usdc.balanceOf(feeRecipient);
    // The test just verifies repeated compound() does not revert
    t(true, "compound has no interval restriction, can be called repeatedly");
}

function property_vesting_fees_collected_correctly() public {
    // Add a vesting position
    _addVestingPosition(1e7, 10_000e6, 30 days);

    // Record vesting position ticks
    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();

    // Force a rebalance to shift mainPosition ticks
    skip(strategy.rebalanceInterval() + 1);
    _rebalance();

    IStrategy.Position memory mpAfter = strategy.getMainPosition();
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();

    // After rebalance: mainPosition.tickUpper likely differs from vestPosition.tickUpper
    // The bug: collectFees uses mainPosition.tickUpper for vesting position collection
    // Invariant: vestPosition tickUpper must remain what it was set to (independent of mainPosition)
    eq(
        int256(vpAfter.tickUpper),
        int256(vpBefore.tickUpper),
        "vestPosition.tickUpper should be stable and independent of mainPosition ticks"
    );

    // Additionally, mainPosition ticks changed, proving the mismatch exists
    t(
        mpAfter.tickUpper != vpBefore.tickUpper || mpAfter.tickLower != vpBefore.tickLower,
        "After rebalance, main position ticks should differ from original vesting ticks"
    );
}

function property_pullFunds_does_not_brick_withdrawals() public {
    // Setup: ensure there is a deposit and pull all available funds
    uint256 available = _getUnderlyingBalance();
    if (available == 0) return;

    // Leverager pulls all available funds (no accounting change)
    _pullFundsAsLeverager(available);

    // After pulling, the accounting still says available = old value
    // but actual token balance of yToken is zero.
    // A user trying to redeem even 1 yToken should not cause a protocol
    // state where their withdrawal permanently reverts.
    // Property: underlyingBalance should equal actual yToken asset balance
    uint256 accountingBalance = _getUnderlyingBalance(); // reserve.underlyingBalance
    uint256 actualBalance     = _getYTokenAssetBalance(); // IERC20(asset).balanceOf(yToken)

    // After pullFunds, these two must remain consistent.
    // If they diverge, any redeem that passes the accounting check will revert on transfer.
    eq(accountingBalance, actualBalance, "underlyingBalance diverges from actual yToken balance after pullFunds");
}

function property_pushFunds_accounting_consistent() public {
    // Push extra funds without any prior pullFunds
    uint256 pushAmount = ONE_ASSET * 1000;
    deal(address(asset), leverager, asset.balanceOf(leverager) + pushAmount);

    vm.startPrank(leverager);
    asset.approve(address(lendingPool), type(uint256).max);
    lendingPool.pushFunds(address(asset), pushAmount);
    vm.stopPrank();

    // After pushFunds, underlyingBalance should match actual balance
    uint256 accountingBalance = _getUnderlyingBalance();
    uint256 actualBalance     = _getYTokenAssetBalance();

    // If these diverge, the pushed tokens are silently lost
    eq(accountingBalance, actualBalance, "pushFunds creates irrecoverable token surplus in yToken");
}

function property_pause_prevents_fund_extraction() public {
    uint256 available = _getUnderlyingBalance();
    if (available == 0) return;

    // Owner pauses
    _pauseAsOwner();
    t(_isPaused(), "pool should be paused");

    // Attempt to pull funds during pause
    // This should revert if pause properly blocks leverager extraction
    uint256 balanceBefore = _getYTokenAssetBalance();
    try lendingPool.pullFunds(address(asset), available) {
        // If pullFunds succeeds during pause, check that balance is unchanged
        uint256 balanceAfter = _getYTokenAssetBalance();
        eq(balanceBefore, balanceAfter, "pullFunds drained tokens during emergency pause");
    } catch {
        // Correctly reverted
    }
}

function property_repay_zero_no_state_change() public {
    uint256 borrowsBefore          = _getTotalBorrows();
    uint256 liquidityBefore        = _getTotalLiquidity();
    uint256 yTokenBalanceBefore    = _getYTokenAssetBalance();

    // Repay zero — should be a no-op
    _repayAsLeverager(0);

    uint256 borrowsAfter           = _getTotalBorrows();
    uint256 liquidityAfter         = _getTotalLiquidity();
    uint256 yTokenBalanceAfter     = _getYTokenAssetBalance();

    // No state should change
    eq(borrowsBefore,       borrowsAfter,       "repay(0) changed totalBorrows");
    eq(liquidityBefore,     liquidityAfter,     "repay(0) changed totalLiquidity");
    eq(yTokenBalanceBefore, yTokenBalanceAfter, "repay(0) moved tokens");
}

function property_exchange_rate_reflects_actual_backing() public {
    // After any leverager operation, exchange rate should reflect actual tokens
    uint256 available = _getUnderlyingBalance();
    if (available < ONE_ASSET) return;

    uint256 rateBefore = _getExchangeRate();

    // Leverager pulls half the funds
    uint256 pullAmount = available / 2;
    _pullFundsAsLeverager(pullAmount);

    uint256 rateAfterPull = _getExchangeRate();

    // After pulling half the tokens, the exchange rate must decrease
    // (each yToken now backs fewer actual tokens)
    // If rate doesn't change, accounting divergence is confirmed
    t(rateAfterPull < rateBefore, "exchange rate unchanged after removing half the tokens via pullFunds");
}

function property_leverager_can_be_updated_in_emergency() public {
    // Verify that leverager immutability does not create permanent risk
    // This property checks that if leverager pulls all funds,
    // users can still eventually withdraw (system is not permanently bricked)

    uint256 available = _getUnderlyingBalance();
    if (available == 0) return;

    // Leverager extracts all funds
    _pullFundsAsLeverager(available);

    // Owner cannot set a new leverager to restore funds
    address newLeverager = address(0x99999);
    vm.prank(owner);
    try lendingPool.setLeverager(newLeverager) {
        // If this succeeds, owner has a recovery path
    } catch {
        // Leverager update blocked — system permanently bricked if leverager is malicious
        // Property: user should still be able to redeem their yTokens
        uint256 userYTokens = _getYTokenBalance(user);
        if (userYTokens > 0) {
            vm.prank(user);
            try lendingPool.redeem(address(asset), userYTokens / 2, user) {
                // Redeem succeeded despite leverager extraction
            } catch {
                t(false, "user cannot redeem after leverager extracts funds and leverager is immutable");
            }
        }
    }
}

function property_deposit_value_preserved_around_leverager_ops() public {
    uint256 depositAmount = ONE_ASSET * 10_000;
    deal(address(asset), attacker, depositAmount);

    // Record state before deposit
    uint256 attackerAssetBefore = _getAssetBalance(attacker);

    // Leverager pulls funds (simulating front-run)
    uint256 available = _getUnderlyingBalance();
    uint256 pullAmount = available / 2;
    if (pullAmount == 0) return;
    _pullFundsAsLeverager(pullAmount);

    // Victim deposits
    uint256 yTokensReceived = _depositAs(attacker, depositAmount);

    // Leverager pushes back (simulating back-run)
    _pushFundsAsLeverager(pullAmount);

    // Victim redeems immediately
    vm.prank(attacker);
    uint256 receivedBack = lendingPool.redeem(address(asset), yTokensReceived, attacker);

    // Value should be approximately preserved (allowing for rounding)
    // If receivedBack < depositAmount - 1, value was extracted
    t(receivedBack >= depositAmount - ONE_ASSET, "depositor lost value due to pullFunds/pushFunds sandwich");
}

function property_balances_not_manipulable_by_spot_price() public {
    // Record balances at current spot price
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 totalBefore = bal0Before + bal1Before * strategy.price() / 1e30;

    // Simulate a large price manipulation: swap WBTC → USDC to push price
    _swapWbtcForUsdc(attacker, 50 * ONE_TOKEN0); // 50 WBTC

    // balances() will now reflect the manipulated spot price
    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    uint256 priceAfter = strategy.price();
    uint256 totalAfter = bal0After + bal1After * priceAfter / 1e30;

    // The true underlying liquidity hasn't changed, but spot-price-based
    // valuation may have shifted significantly — flag large deviations
    uint256 diff = totalBefore > totalAfter ? totalBefore - totalAfter : totalAfter - totalBefore;
    // Allow up to 5% deviation; anything larger indicates manipulation susceptibility
    t(diff * 100 / totalBefore <= 5, "balances() manipulable by spot price");
}

function property_rebalance_uses_twap_price() public {
    // After rebalance, the main position should be centered near the TWAP tick
    // not the potentially-manipulated spot tick
    int24 twapT = strategy.twapTick();
    IStrategy.Position memory main = strategy.getMainPosition();
    int24 midTick = (main.tickLower + main.tickUpper) / 2;
    int24 deviation = midTick - twapT;
    if (deviation < 0) deviation = -deviation;
    // The center of the main position should be within tickSpacing of TWAP
    t(deviation <= strategy.tickSpacing() * 2,
      "rebalance centers position far from TWAP tick");
}

function property_secondary_position_is_out_of_range() public {
    // The secondary position should always be OOR after a rebalance
    (, int24 currentTick,,,,,) = pool.slot0();
    IStrategy.Position memory sec = strategy.getSecondaryPosition();
    // OOR means: currentTick < tickLower OR currentTick >= tickUpper
    bool isOOR = currentTick < sec.tickLower || currentTick >= sec.tickUpper;
    // Only check if secondary has liquidity
    if (sec.liquidity > 0) {
        t(isOOR, "secondary position is not out-of-range after rebalance");
    }
}

function property_vesting_fee_collection_uses_correct_ticks() public {
    // After collectFees, the vesting position fees should be collected
    // from its own tick range, not mainPosition.tickUpper
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory main = strategy.getMainPosition();

    if (strategy.ongoingVestingPosition()) {
        // The vesting position's tickUpper should equal what was stored
        // (it should NOT use mainPosition.tickUpper unless they happen to match)
        // We detect the bug by checking if vestPosition.tickUpper != mainPosition.tickUpper
        // and then verifying fees are not being undercollected by checking balances
        (uint256 bal0Before, uint256 bal1Before) = strategy.idleBalances();
        strategy.collectFees();
        (uint256 bal0After, uint256 bal1After) = strategy.idleBalances();

        // If vesting position has accrued fees and tickUpper differs, collectFees
        // using wrong ticks would miss them — flag if nothing was collected
        // but time has passed since lastUpdate
        bool timePassedSinceUpdate = vp.lastUpdate < block.timestamp;
        bool noFeesCollected = (bal0After == bal0Before) && (bal1After == bal1Before);

        // If significant time has passed (>= 1 day), we expect some fee accretion
        if (timePassedSinceUpdate && vp.tickUpper != main.tickUpper) {
            // Wrong tick range used — this is the bug. Just document the mismatch.
            t(vp.tickUpper == main.tickUpper ||
              vp.tickLower == vp.tickUpper,
              "collectFees uses mainPosition.tickUpper for vesting, not vestPosition.tickUpper");
        }
    }
}

function property_twap_window_is_sufficient() public {
    // The TWAP window should be at least 30 minutes (1800 seconds)
    // for meaningful manipulation resistance on a volatile pair
    uint32 currentTwap = strategy.twap();
    t(currentTwap >= 1800, "TWAP window is too short for manipulation resistance");
}

function property_initial_position_near_twap() public {
    // After deployment and initial rebalance, position center should be
    // near the TWAP tick (rebalance does check TWAP, so this should hold
    // after the first rebalance)
    int24 twapT = strategy.twapTick();
    IStrategy.Position memory main = strategy.getMainPosition();
    int24 midTick = (main.tickLower + main.tickUpper) / 2;
    int24 deviation = midTick - twapT;
    if (deviation < 0) deviation = -deviation;
    // After rebalance, main position should be centered within 2 * tickSpacing of TWAP
    t(deviation <= int24(strategy.positionWidth()),
      "main position not centered near TWAP after initialization");
}

function property_vesting_position_uses_full_deposit() public {
    uint256 amt0 = 1 * ONE_TOKEN0;
    uint256 amt1 = 50_000 * ONE_TOKEN1;

    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();

    _addVestingPosition(amt0, amt1, 7 days);

    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // If vesting position was created, liquidity should be > 0
    t(vp.initialLiquidity > 0, "vesting position created with 0 liquidity");

    // The idle balance increase after addVestingPosition should be minimal
    // (any idle increase means tokens weren't put into liquidity)
    uint256 idleDelta0 = idle0After > idle0Before ? idle0After - idle0Before : 0;
    uint256 idleDelta1 = idle1After > idle1Before ? idle1After - idle1Before : 0;

    // Less than 1% of deposited amount should remain idle (due to spot price slippage)
    t(idleDelta0 <= amt0 / 100, "too many token0 left idle in addVestingPosition");
    t(idleDelta1 <= amt1 / 100, "too many token1 left idle in addVestingPosition");
}

function property_price_decimal_consistency() public {
    uint256 p = strategy.price();
    uint256 twapP = strategy.twapPrice();

    // Price should be in reasonable range for WBTC/USDC
    // ~60,000-100,000 USDC per WBTC, in 1e30 precision
    // = 60_000e6 * 1e30 / 1e8 = 60_000 * 1e28 = 6e32
    // Actually: price() = (sqrtPrice * 1e15 / 2^96)^2
    // For WBTC@~60000 USDC, sqrtPrice encodes token1/token0 ratio
    // token1 = USDC (6 dec), token0 = WBTC (8 dec)
    // ratio = 60000e6 / 1e8 = 600 (in raw units)
    // sqrtPrice = sqrt(600) * 2^96 ≈ 24.49 * 2^96
    // price() = (24.49 * 1e15 / 2^96 * 2^96)^2... need sqrtPriceX96
    // Just verify spot and twap prices are within 5% of each other
    uint256 diff = p > twapP ? p - twapP : twapP - p;
    uint256 pctDiff = diff * 100 / twapP;
    t(pctDiff <= 5, "spot price deviates more than 5% from TWAP price");
}

function property_oracle_staleness_check() public {
    // This property verifies that the exchange rate computed by the pool
    // (which depends on interest accrual, not directly on Chainlink)
    // does not revert on a fresh pool. We test that exchange rate is
    // sensible (>= PRECISION) since the pool has no external oracle dependency.
    // The actual staleness issue is in PriceFeed which is outside Setup scope.
    // We assert the lending pool invariant that exchange rate is always >= PRECISION
    // when totalBorrows == 0 (no interest accrued, 1:1 ratio or better).
    uint256 rate = _getExchangeRate();
    uint256 totalBorrows = _getTotalBorrows();
    if (totalBorrows == 0) {
        gte(rate, PRECISION, "exchange rate below 1:1 with no borrows");
    }
}

function property_liquidation_decimal_consistency() public {
    // Verify that borrow accounting uses 10**decimals consistently.
    // We check that totalBorrows and totalLiquidity relationships hold.
    // The actual decimal bug is in Leverager (not in LendingPool Setup scope)
    // but we verify the lending pool's interest index is sane.
    uint256 idx = _getCurrentBorrowingIndex();
    gte(idx, PRECISION, "borrowing index should never decrease below PRECISION");
}

function property_exchange_rate_monotonic_with_borrows() public {
    // When funds are borrowed and time passes, interest accrues.
    // The exchange rate (yToken -> underlying) should be >= PRECISION always.
    // This tests that the oracle-free lending pool math remains correct.
    uint256 rate = _getExchangeRate();
    gte(rate, PRECISION, "exchange rate below PRECISION");
}

function property_redeem_repays_full_underlying() public {
    // After deposit and redeem of same yToken amount, user should get back
    // at least the underlying they put in (modulo rounding).
    uint256 depositAmount = 10_000 * ONE_ASSET;
    uint256 yMinted = _depositAs(depositor, depositAmount);
    uint256 underlyingBack = _redeemAs(depositor, yMinted);
    // With no borrows and no time passing, underlying back should be <= depositAmount
    // (due to MINIMUM_YTOKEN_AMOUNT burn on first deposit, depositor should get slightly less)
    lte(underlyingBack, depositAmount, "cannot get more underlying than deposited");
}

function property_exchange_rate_consistent_deposit() public {
    // The exchange rate before deposit should be consistent with yTokens minted.
    // rate = yTokens per underlying (scaled by PRECISION).
    // yTokensMinted = depositAmount * rate / PRECISION
    uint256 depositAmount = 1_000 * ONE_ASSET;

    // Pre-deposit state
    uint256 rateBefore = _getExchangeRate();
    uint256 supplyBefore = _getYTokenTotalSupply();

    uint256 yMinted = _depositAs(attacker, depositAmount);

    // Check that the minted amount is consistent with what the exchange rate predicted
    // (accounting for rounding down, so yMinted should be <= predicted)
    uint256 predicted = depositAmount * rateBefore / PRECISION;
    lte(yMinted, predicted + 1, "minted more yTokens than exchange rate predicted");
}

function property_borrowing_rate_increases_with_utilization() public {
    // After a borrow that increases utilization, borrowing rate should
    // be >= the rate before (interest rate curves are non-decreasing).
    uint256 rateBefore = _getBorrowingRate();

    // Borrow a large amount to increase utilization
    uint256 poolLiq = _getUnderlyingBalance();
    uint256 borrowAmt = poolLiq / 2;
    if (borrowAmt > 0) {
        _borrowAsLeverager(borrowAmt);
        uint256 rateAfter = _getBorrowingRate();
        gte(rateAfter, rateBefore, "borrow rate decreased after increasing utilization");
        _repayAsLeverager(borrowAmt);
    }
}

function property_total_liquidity_gte_borrows() public {
    // Total liquidity (available + borrows) should always be >= total borrows.
    uint256 totalLiq = _getTotalLiquidity();
    uint256 totalBorrows = _getTotalBorrows();
    gte(totalLiq, totalBorrows, "total liquidity less than total borrows");
}

function property_redeem_never_reverts_with_sufficient_liquidity() public {
    // If there is available liquidity, redeem should not revert.
    uint256 yBal = _getYTokenBalance(user);
    if (yBal > 0) {
        uint256 availLiq = _getUnderlyingBalance();
        uint256 rate = _getExchangeRate();
        uint256 underlyingNeeded = yBal * rate / PRECISION;
        if (underlyingNeeded <= availLiq) {
            uint256 underlyingBack = _redeemAs(user, yBal);
            gte(underlyingBack, 0, "redeem returned negative");
        }
    }
}

function property_vesting_fees_collected_with_correct_ticks() public {
    // After a rebalance the main ticks change; if a vesting position exists,
    // the vesting position's tickUpper must be different from mainPosition.tickUpper
    // after a rebalance. collectFees uses mainPosition.tickUpper instead of
    // vestPosition.tickUpper — verify that the ticks used internally match.
    // We detect the bug by observing that vesting position fees are NOT credited.

    // Setup: add vesting position, then rebalance to shift ticks
    _addVestingPosition(1e7, 50_000e6, 7 days);

    IStrategy.Position memory mainBefore = strategy.getMainPosition();
    IStrategy.VestingPosition memory vestPos = strategy.getVestingPosition();

    // Generate some fees by doing swaps
    _swapWbtcForUsdc(attacker, 5e7);
    _swapUsdcForWbtc(attacker, 200_000e6);

    // Trigger rebalance to shift main position ticks
    skip(strategy.rebalanceInterval() + 1);
    _rebalance();

    IStrategy.Position memory mainAfter = strategy.getMainPosition();

    // After rebalance, the bug is manifest if mainPosition.tickUpper != vestPosition.tickUpper
    // collectFees now collects from wrong range
    if (mainAfter.tickUpper != vestPos.tickUpper) {
        // Collect fees — if using wrong ticks, actual vest position fees are NOT collected
        uint256 idle0Before = wbtc.balanceOf(address(strategy));
        uint256 idle1Before = usdc.balanceOf(address(strategy));
        strategy.collectFees();
        uint256 idle0After = wbtc.balanceOf(address(strategy));
        uint256 idle1After = usdc.balanceOf(address(strategy));

        // The vesting position should have generated fees; if ticks are wrong,
        // the incremental balance increase from vesting position fees is 0.
        // We cannot assert exact amounts but the position SHOULD have accrued fees.
        // Property: after collecting fees with ongoing vesting and price movement,
        // at least some tokens should have been collected.
        // (This is a soft canary; the hard invariant tested by the bug is tick mismatch.)
        t(
            mainAfter.tickUpper == vestPos.tickUpper || idle0After >= idle0Before || idle1After >= idle1Before,
            "Vesting fees lost: wrong tick range in collectFees"
        );
    }
}

function property_vesting_withdrawal_never_exceeds_remaining() public {
    // Invariant: liquidityToRemove in each _withdrawPartOfVestingPosition call
    // must never exceed vestPosition.remainingLiquidity.
    // We test this by checking the vesting position state remains consistent.

    _addVestingPosition(1e7, 50_000e6, 30 days);

    // Advance time partially and collect fees multiple times
    skip(10 days);
    strategy.collectFees();

    IStrategy.VestingPosition memory vp1 = strategy.getVestingPosition();

    skip(10 days);
    strategy.collectFees();

    IStrategy.VestingPosition memory vp2 = strategy.getVestingPosition();

    // remainingLiquidity must be monotonically non-increasing
    t(vp2.remainingLiquidity <= vp1.remainingLiquidity, "remaining liquidity increased");

    // remainingLiquidity must never go negative (underflow would revert, but check state)
    t(vp2.remainingLiquidity <= vp2.initialLiquidity, "remaining > initial");

    skip(15 days); // now past endTs
    strategy.collectFees(); // should handle final vesting cleanly

    IStrategy.VestingPosition memory vpFinal = strategy.getVestingPosition();
    t(!strategy.ongoingVestingPosition(), "vesting not ended after full duration");
    t(vpFinal.remainingLiquidity == 0, "liquidity not fully vested");
}

function property_withdraw_amount_matches_share_proportion() public {
    // After a withdrawal, remaining depositors' share value must not have decreased.
    // i.e., the withdrawn amounts must be exactly proportional to shares burned.

    deal(address(wbtc), depositor, 1e8);
    deal(address(usdc), depositor, 100_000e6);
    (uint256 shares,,) = _dealAndDeposit(depositor, 1e8, 100_000e6);

    skip(1 days);
    strategy.collectFees();

    (uint256 totalBal0Before, uint256 totalBal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();

    // Withdraw half of depositor shares
    uint256 halfShares = shares / 2;
    (uint256 out0, uint256 out1) = _withdrawAs(depositor, halfShares);

    (uint256 totalBal0After, uint256 totalBal1After) = strategy.balances();
    uint256 supplyAfter = vault.totalSupply();

    // After withdrawal: remaining balance / remaining supply ratio should be >= before
    // (or at worst equal, allowing for rounding). Never should remaining depositors
    // receive less per share after one depositor withdraws their fair share.
    if (supplyAfter > 0 && totalBal0Before > 0) {
        // Per-share value of token0 must not decrease for remaining holders
        // (totalBal0Before / supplyBefore) should be >= (totalBal0After / supplyAfter)
        // Cross-multiply to avoid division: totalBal0Before * supplyAfter <= totalBal0After * supplyBefore + epsilon
        // Note: collectFees runs again inside withdraw, may collect more, so after can be >= before per share
        t(
            totalBal0After * supplyBefore >= totalBal0Before * supplyAfter - (totalBal0Before * supplyAfter / 1e6),
            "Per-share token0 value decreased after fair withdrawal"
        );
    }
}

function property_secondary_position_ticks_valid() public {
    // After any rebalance, secondary position must have tickLower < tickUpper
    IStrategy.Position memory secondary = strategy.getSecondaryPosition();

    t(secondary.tickLower < secondary.tickUpper,
