function property_collectFees_idempotent_within_block() public {
    // Calling collectFees() twice in the same block should not change balances
    // (fees collected once; vesting withdrawal returns early if lastUpdate == block.timestamp)

    strategy.collectFees();
    (uint256 idle0After1, uint256 idle1After1) = strategy.idleBalances();

    strategy.collectFees();
    (uint256 idle0After2, uint256 idle1After2) = strategy.idleBalances();

    // Second call should not change idle balances (already collected this block)
    eq(idle0After2, idle0After1, "collectFees not idempotent for token0 within block");
    eq(idle1After2, idle1After1, "collectFees not idempotent for token1 within block");
}

function property_WC01_collectFees_uses_correct_vesting_ticks() public {
    // Only meaningful when there is an active vesting position
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees hard-codes mainPosition.tickUpper for the vesting fee collection.
    // After a rebalance the main position ticks may differ from the vesting position ticks.
    // We assert that the vesting position ticks match the main position ticks only if no
    // rebalance has happened since the vesting position was created — but in general they
    // could differ, exposing the stale-tick bug.
    //
    // Property: if a rebalance occurred after the vesting position was added,
    // vestPosition.tickUpper should still equal the tick used in collectFees.
    // The contract uses mainPosition.tickUpper, so we check whether they still agree.
    // If they don't agree, the contract's collectFees is operating on the wrong tick.
    bool ticksMatch = (vp.tickUpper == mp.tickUpper);

    // Simulate a rebalance to expose disagreement
    vm.prank(rebalancer);
    try strategy.rebalance() {} catch {}

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    IStrategy.Position memory mpAfter = strategy.getMainPosition();

    // After rebalance, main ticks may shift; vesting ticks are fixed.
    // If they differ, calling collectFees will silently collect from the wrong position.
    if (vpAfter.tickUpper != mpAfter.tickUpper) {
        // Collect fees — should not revert but will operate on wrong position
        strategy.collectFees();
        // The vesting position should still have its ticks intact
        IStrategy.VestingPosition memory vpFinal = strategy.getVestingPosition();
        t(vpFinal.tickLower == vpAfter.tickLower, "WC01: vesting tickLower mutated");
        t(vpFinal.tickUpper == vpAfter.tickUpper, "WC01: vesting tickUpper mutated");
    }
}

function property_WC02_vesting_fully_distributed() public {
    // Setup: add a vesting position
    uint256 amt0 = 1e7; // 0.1 WBTC
    uint256 amt1 = 5_000e6; // 5000 USDC
    uint256 duration = 7 days;
    _addVestingPosition(amt0, amt1, duration);

    uint128 initialLiq = _getVestingInitialLiquidity();
    if (initialLiq == 0) return;

    // Advance through vesting in many small steps (exposes rounding loss)
    uint256 steps = 100;
    uint256 stepSize = duration / steps;
    for (uint256 i = 0; i < steps; i++) {
        skip(stepSize);
        strategy.collectFees();
    }

    // Advance past end to ensure full vesting
    skip(duration + 1);
    strategy.collectFees();

    // After full vesting, ongoingVestingPosition should be false
    t(!strategy.ongoingVestingPosition(), "WC02: vesting position not ended");

    // remainingLiquidity should be 0
    uint128 remaining = _getVestingRemainingLiquidity();
    t(remaining == 0, "WC02: liquidity left in vesting position after full duration");
}

function property_WC03_changePositionWidth_only_rebalancer() public {
    // Any address other than rebalancer should not be able to cause
    // a rebalance via changePositionWidth
    uint24 currentWidth = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();

    // Compute a valid new width
    uint24 newWidth = currentWidth + uint24(ts) * 2;

    // Attacker attempts to trigger rebalance via changePositionWidth
    // This should revert because rebalance() has onlyRebalancer
    vm.prank(attacker);
    (bool success,) = address(strategy).call(
        abi.encodeWithSignature("changePositionWidth(uint24)", newWidth)
    );
    // Should fail since rebalance() enforces onlyRebalancer
    t(!success, "WC03: attacker triggered changePositionWidth successfully");

    // positionWidth should not have changed
    t(strategy.positionWidth() == currentWidth, "WC03: positionWidth changed by attacker");
}

function property_WC04_checkPoolActivity_no_unexpected_revert() public {
    // checkPoolActivity should return a bool, not revert, under normal conditions.
    // We check that the current pool state does not cause a revert.
    (bool ok, bytes memory retdata) = address(strategy).staticcall(
        abi.encodeWithSignature("checkPoolActivity()")
    );
    // If it reverts with "timestamp 0", that is the bug
    if (!ok) {
        // Decode revert reason
        // A revert here means rebalance() and compound() are also DOSed
        t(false, "WC04: checkPoolActivity reverted - strategy is DOSed");
    }
    // If it didn't revert, decode the bool result
    bool result = abi.decode(retdata, (bool));
    // No assertion on result value; just ensure no revert
    t(true, "WC04: checkPoolActivity returned without revert");
}

function property_WC05_secondary_position_valid_ticks() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    // Secondary position must have tickLower < tickUpper (Uniswap V3 invariant)
    t(sp.tickLower < sp.tickUpper, "WC05: secondary position has tickLower >= tickUpper");
}

function property_WC06_vesting_fees_collected_from_correct_ticks() public {
    // Setup: create vesting position
    _addVestingPosition(1e7, 5_000e6, 30 days);
    if (!strategy.ongoingVestingPosition()) return;

    // Record vesting position ticks
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    int24 vestTickLower = vp.tickLower;
    int24 vestTickUpper = vp.tickUpper;

    // Generate fees by doing swaps
    _swapWbtcForUsdc(attacker, 1e7);
    _swapUsdcForWbtc(attacker, 5_000_000e6);

    // Trigger rebalance to shift main position ticks
    skip(strategy.rebalanceInterval() + 1);
    vm.prank(rebalancer);
    try strategy.rebalance() {} catch {}

    IStrategy.Position memory mp = strategy.getMainPosition();

    // If ticks shifted, bug is exposed
    if (mp.tickUpper != vestTickUpper) {
        // collectFees will use wrong tick upper for vesting position
        // Vesting position fees should accumulate in the pool but never be collected
        (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
        strategy.collectFees();
        (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

        // The strategy balance should have increased by any earned fees
        // If WC-06 is triggered, vesting position fees are NOT collected,
        // so the balance increase may be less than expected
        // We just verify that collectFees doesn't silently drop the vesting fees
        // by checking that subsequent liquidity removal correctly uses vestPosition ticks
        IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
        t(vpAfter.tickLower == vestTickLower, "WC06: vesting tickLower changed");
        t(vpAfter.tickUpper == vestTickUpper, "WC06: vesting tickUpper changed");
    }
}

description:
In _withdrawPartOfVestingPosition(), the final check reads from storage AFTER updating it:
  vestPosition = vp;
  if (lastValid == vestPosition.endTs) ongoingVestingPosition = false;
The local variable vp has vp.endTs unchanged (it was never modified in the function), and vestPosition was just set to vp, so vestPosition.endTs == vp.endTs. The condition `lastValid == vestPosition.endTs` is therefore equivalent to `lastValid == vp.endTs`. This is semantically correct. However, if lastValid != vp.endTs but the vesting is technically over (e.g., block.timestamp > vp.endTs but the condition `lastValid = block.timestamp < vp.endTs ? block.timestamp : vp.endTs` would set lastValid = vp.endTs), the logic holds. The actual bug is subtler: when lastValid == vp.endTs (vesting ended), remainingLiquidity is set to 0 correctly, but ongoingVestingPosition is set to false. Then vestPosition.remainingLiquidity and vestPosition.lastUpdate in storage are updated. A future call to collectFees when ongoingVestingPosition is false will skip the vesting block correctly. This logic appears correct on close reading. Marking as low confidence. REAL BUG: The vesting formula uses (vp.endTs - vp.startTs) as denominator — the TOTAL duration — not the remaining duration. This means even after 99% of the vest period, the per-epoch rate is still computed against the original total duration, not the remaining time. This is the same as WC-02 but looking at it from a different angle: in the partial withdraw formula, using initialLiquidity*(elapsed)/(totalDuration) is correct for linear vesting only if cumulative. But after any partial withdrawal, the accumulated removes don't sum to initialLiquidity at the end because of integer rounding.

solidity:
function property_WC08_vesting_no_stuck_liquidity() public {
    // Add vesting position
    _addVestingPosition(1e7, 5_000e6, 10 days);
    if (!strategy.ongoingVestingPosition()) return;

    uint128 initialLiq = _getVestingInitialLiquidity();
    if (initialLiq == 0) return;

    // Run many small steps
    for (uint256 i = 0; i < 50; i++) {
        skip(10 days / 50);
        strategy.collectFees();
    }

    // Advance past end
    skip(10 days + 1);
    strategy.collectFees();

    t(!strategy.ongoingVestingPosition(), "WC08: vesting still ongoing after end");
    uint128 remaining = _getVestingRemainingLiquidity();
    t(remaining == 0, "WC08: non-zero remainingLiquidity after vesting ended");
}

function property_vesting_deposit_no_dilution() public {
    // Snapshot balances before a deposit when vesting is active
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();

    // Skip if no supply or no vesting
    if (supplyBefore == 0) return;
    if (!strategy.ongoingVestingPosition()) return;

    // The vestingPosition liquidity should be part of vault value pricing
    // Property: if vestPosition has remainingLiquidity > 0, balances() should reflect
    // some value from it (i.e., balances() >= what it would be without vesting).
    // We detect the gap: total assets from Uniswap positions vs what balances() says.
    // Simplified invariant: share price should be monotonically non-decreasing for
    // long-term holders, so withdrawing all shares should return >= deposited value.

    // Check that a new deposit doesn't get shares priced below true asset ratio.
    // We use the ratio: if sharePrice = (bal0 * price + bal1) / totalSupply,
    // and vesting adds to true value but not balances(), new deposits are mispriced.
    uint256 _price = strategy.price();
    uint256 priceInTermsOf1 = _price; // 1e30 precision

    // Compute total value in token1 units (rough, using strategy.price())
    // price = token0/token1 in 1e30, so bal0_in_1 = bal0 * price / 1e30
    uint256 totalValue1 = bal0Before * priceInTermsOf1 / 1e30 + bal1Before;

    // Value per share (scaled by 1e18 for precision)
    uint256 valuePerShareBefore = supplyBefore > 0 ? totalValue1 * 1e18 / supplyBefore : 0;

    // Do a deposit as depositor
    deal(WBTC_ADDR, depositor, ONE_TOKEN0);
    deal(USDC_ADDR, depositor, 100_000 * ONE_TOKEN1);
    vm.startPrank(depositor);
    token0.approve(address(vault), type(uint256).max);
    token1.approve(address(vault), type(uint256).max);
    (uint256 newShares, uint256 dep0, uint256 dep1) = vault.deposit(ONE_TOKEN0, 100_000 * ONE_TOKEN1, 0, 0);
    vm.stopPrank();

    // After deposit, compute new value per share
    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    uint256 supplyAfter = vault.totalSupply();
    uint256 totalValue1After = bal0After * priceInTermsOf1 / 1e30 + bal1After;
    uint256 valuePerShareAfter = supplyAfter > 0 ? totalValue1After * 1e18 / supplyAfter : 0;

    // Existing shareholders should not be diluted by the new deposit
    // (value per share should not decrease after a deposit at fair price)
    // Allowing 1% tolerance for rounding
    t(
        valuePerShareAfter * 100 >= valuePerShareBefore * 99,
        "DH-V-01: existing shareholders diluted by deposit when vesting active"
    );
}

function property_deposit_fee_accounting() public {
    uint256 fee = vault.depositFee();
    if (fee == 0) return; // nothing to check

    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();

    deal(WBTC_ADDR, depositor, ONE_TOKEN0);
    deal(USDC_ADDR, depositor, 100_000 * ONE_TOKEN1);
    vm.startPrank(depositor);
    token0.approve(address(vault), type(uint256).max);
    token1.approve(address(vault), type(uint256).max);
    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(ONE_TOKEN0, 100_000 * ONE_TOKEN1, 0, 0);
    vm.stopPrank();

    uint256 supplyAfter = vault.totalSupply();
    uint256 newShares = supplyAfter - supplyBefore;

    // Property: shares received should equal shares - floor(shares*fee/10000)
    // The fee must be at least as much as stated (no fee bypass)
    // newShares = shares_minted_to_user (after fee deduction)
    // shares_before_fee = shares + floor(shares_before_fee * fee / 10_000)
    // We check: newShares * 10_000 <= shares_before_fee * (10_000 - fee)
    // Approximation: effective fee rate >= stated fee rate
    // effective_fee_rate = (total_new_shares_with_fee - user_shares) / total_new_shares_with_fee
    // i.e., fee_shares / (fee_shares + user_shares) >= fee / 10_000

    // Simpler: the actual supply increase should be bounded
    // If fee is 10 BPS, user gets at most 99.9% of their gross shares
    uint256 grossShares = newShares * 10_000 / (10_000 - fee); // approximate gross
    uint256 impliedFeeShares = grossShares - newShares;
    // Fee shares should be at most grossShares * fee / 10_000 (no over-charging)
    t(
        impliedFeeShares * 10_000 <= grossShares * fee + grossShares, // allow 1 rounding unit
        "DH-V-02: deposit fee over-charges user"
    );
}

function property_deposit_withdraw_conservation() public {
    // Property: deposit then immediate withdraw should return approximately same value
    // (allowing for rounding and fees, not allowing for price manipulation benefit)
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    if (bal0Before == 0 && bal1Before == 0) return;

    uint256 supplyBefore = vault.totalSupply();
    if (supplyBefore == 0) return;

    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = 100_000 * ONE_TOKEN1;

    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    vm.startPrank(depositor);
    token0.approve(address(vault), type(uint256).max);
    token1.approve(address(vault), type(uint256).max);
    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    // Immediately withdraw
    vm.startPrank(depositor);
    (uint256 out0, uint256 out1) = vault.withdraw(shares, 0, 0);
    vm.stopPrank();

    // User should not gain tokens (allowing 1% rounding tolerance)
    t(out0 * 101 / 100 >= dep0, "DH-V-03a: withdrew less token0 than deposited (excluding fees)");
    t(out1 * 101 / 100 >= dep1, "DH-V-03b: withdrew less token1 than deposited (excluding fees)");
    // Also user should not gain more than deposited + 1% (no value extraction via round-trip)
    t(out0 <= dep0 * 101 / 100, "DH-V-03c: withdrew more token0 than deposited");
    t(out1 <= dep1 * 101 / 100, "DH-V-03d: withdrew more token1 than deposited");
}

description:
In Strategy.collectFees() (lines 159-181):
  (uint256 preBal0, uint256 preBal1) = idleBalances();
  // collect position fees...
  if (ongoingVestingPosition) collectPositionFees(vestPosition.tickLower, mainPosition.tickUpper); // BUG from DH-01
  (uint256 afterBal0, uint256 afterBal1) = idleBalances();
  uint256 protocolFees0 = (afterBal0 - preBal0) * protocolFee / 10_000;
  // send protocol fees...
  if (ongoingVestingPosition) _withdrawPartOfVestingPosition(); // releases vested liq into idle
The protocol fee is applied to ALL balance increases: trading fees from positions AND the vested liquidity being released. When _withdrawPartOfVestingPosition releases tokens, those tokens were owner-donated. The owner pays protocol fee on their own donation to the protocol. More importantly, the _withdrawPartOfVestingPosition() runs AFTER protocolFees are sent (line 179), so the protocol fee is NOT charged on the vested tokens in the same call — but it IS charged on the TRADING FEES collected from the vesting position (via collectPositionFees at line 167). Since line 167 uses wrong ticks (mainPosition.tickUpper instead of vestPosition.tickUpper, per DH-01 from Strategy), fees from the vesting position may never be collected at all.

solidity:
function property_total_supply_nonzero_means_assets_nonzero() public {
    // Core solvency invariant: if totalSupply > 0, strategy must hold some assets
    uint256 supply = vault.totalSupply();
    if (supply == 0) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();

    // At least one of the two balances must be nonzero if shares exist
    t(
        bal0 > 0 || bal1 > 0,
        "DH-V-06: shares outstanding but strategy has zero assets"
    );
}

description:
In _calcDeposit's main branch (lines 141-149):
  uint256 cross = cross0 > cross1 ? cross1 : cross0;
  require(cross > 0, "cross");
  shares = cross * totalSupply / bal0 / bal1;
If cross is very small relative to bal0*bal1, integer division can produce shares=0. The `require(shares > 0)` check in deposit() (line 63) guards against this. However: the tokens ARE transferred BEFORE this check (lines 58-59). If shares rounds to 0, the deposit reverts but the tokens are already sent — but since the whole function reverts, the transfer is rolled back. So no permanent loss. More concerning: the round-up amounts (lines 147-148) can charge MORE tokens than the exact ratio warrants. If the user passes `amount0=X, amount1=Y` but the rounding causes `amount0_charged > X` or `amount1_charged > Y`, the safeTransferFrom will revert (insufficient balance/allowance). This is a subtle DoS on deposits with exact amounts.

solidity:
function property_deposit_charged_amounts_within_requested() public {
    // Property: deposited amounts should never exceed the amounts requested
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = 100_000 * ONE_TOKEN1;

    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    // Only approve exactly the requested amounts
    vm.startPrank(depositor);
    token0.approve(address(vault), amt0);
    token1.approve(address(vault), amt1);

    uint256 tok0Before = token0.balanceOf(depositor);
    uint256 tok1Before = token1.balanceOf(depositor);

    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amt0, amt1, 0, 0);
    vm.stopPrank();

    uint256 tok0After = token0.balanceOf(depositor);
    uint256 tok1After = token1.balanceOf(depositor);

    uint256 actual0 = tok0Before - tok0After;
    uint256 actual1 = tok1Before - tok1After;

    // Actually transferred amounts must not exceed requested
    t(actual0 <= amt0, "DH-V-07: more token0 taken than requested");
    t(actual1 <= amt1, "DH-V-07: more token1 taken than requested");

    // And must match the returned dep amounts
    eq(actual0, dep0, "DH-V-07: dep0 mismatch with actual token0 taken");
    eq(actual1, dep1, "DH-V-07: dep1 mismatch with actual token1 taken");
}

description:
The fundamental solvency invariant of the vault is that the sum of all users' proportional claims on strategy assets equals the total strategy assets. This must hold continuously. Any rounding in share calculations (round-up deposit amounts, round-down shares) creates small surpluses that accrue to the BURN address, which is benign. But if the invariant breaks significantly — e.g., totalAssets < sum(userClaims) — the vault is insolvent. This can happen if: (a) withdrawPartial returns LESS than the proportional share (it may undercount due to
    using integer division of liquidity, which rounds down, then re-estimates amounts),
(b) fees are double-charged on vested position releases, (c) a rebalance increases total assets beyond what share math expects.

solidity:
function property_solvency_total_claims_leq_assets() public {
    // Sum of ALL holder claims should not exceed total assets
    uint256 totalSupply = vault.totalSupply();
    if (totalSupply == 0) return;

    (uint256 totalBal0, uint256 totalBal1) = strategy.balances();

    // For each known actor, compute their claim
    address[4] memory _actors = actors;
    uint256 sumClaims0 = 0;
    uint256 sumClaims1 = 0;

    for (uint256 i = 0; i < _actors.length; i++) {
        uint256 shares = vault.balanceOf(_actors[i]);
        sumClaims0 += totalBal0 * shares / totalSupply;
        sumClaims1 += totalBal1 * shares / totalSupply;
    }
    // Add user and BURN shares
    uint256 userShares = vault.balanceOf(user);
    uint256 burnShares = vault.balanceOf(address(1337));
    sumClaims0 += totalBal0 * userShares / totalSupply;
    sumClaims1 += totalBal1 * userShares / totalSupply;
    sumClaims0 += totalBal0 * burnShares / totalSupply;
    sumClaims1 += totalBal1 * burnShares / totalSupply;

    // All claims (rounded down) should not exceed total assets
    t(sumClaims0 <= totalBal0, "DH-V-08: sum of token0 claims exceeds total assets");
    t(sumClaims1 <= totalBal1, "DH-V-08: sum of token1 claims exceeds total assets");
}

function property_vest_fees_collected_correctly() public {
    // Setup: after a rebalance, vesting ticks diverge from main ticks.
    // collectFees should collect from vestPosition's actual ticks.
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // If there's an ongoing vesting position AND main ticks differ from vest ticks,
    // the bug is triggered: collectFees uses wrong tickUpper for vest position.
    if (strategy.ongoingVestingPosition()) {
        // After rebalance, main ticks may differ from vest ticks.
        // The vesting position's tickUpper in strategy.vestPosition should equal
        // what was passed to collectPositionFees — but the code uses mainPosition.tickUpper.
        // We verify that vestPosition.tickUpper is used, not mainPosition.tickUpper.
        // In a correct implementation, these should match only at creation time.
        // After rebalance they diverge, revealing the bug.
        bool ticksMatch = (vp.tickUpper == mp.tickUpper);
        // If ticks don't match, the wrong position is being fee-collected.
        // We assert the vesting position has its own consistent tickUpper used.
        t(
            vp.tickLower < vp.tickUpper,
            "vestPosition has invalid tick range"
        );
    }
}

function property_balances_includes_all_positions() public {
    (uint256 bal0, uint256 bal1) = strategy.balances();
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    if (strategy.ongoingVestingPosition() && vp.remainingLiquidity > 0) {
        // Balances should include vesting position value.
        // We can check that balances() + vesting liquidity value > balances() alone.
        // As a proxy: if vesting position has liquidity, strategy holds real assets
        // that balances() doesn't report.
        // The real pool position at (vp.tickLower, vp.tickUpper) with vp.remainingLiquidity
        // has non-zero token value, but balances() doesn't include it.
        (uint160 sqrtPriceX96,,,,,,) = pool.slot0();
        (uint256 v0, uint256 v1) = LiquidityAmounts.getAmountsForLiquidity(
            sqrtPriceX96,
            TickMath.getSqrtRatioAtTick(vp.tickLower),
            TickMath.getSqrtRatioAtTick(vp.tickUpper),
            vp.remainingLiquidity
        );
        // If vesting has value, then balances() understates total assets
        // New depositors get diluted-existing-holder shares => invariant:
        // balances should include ALL liquidity held by strategy including vesting.
        t(
            v0 == 0 && v1 == 0,
            "balances() excludes non-zero vesting position value, diluting depositors"
        );
    }
}

function property_withdraw_proportional_to_all_assets() public {
    // Ensure there is a vesting position active
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return;

    uint256 userShares = vault.balanceOf(user);
    uint256 totalShares = vault.totalSupply();
    if (userShares == 0 || totalShares == 0) return;

    // Record balances before withdrawal
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 userWbtcBefore = wbtc.balanceOf(user);
    uint256 userUsdcBefore = usdc.balanceOf(user);

    // User withdraws
    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    uint256 received0 = wbtc.balanceOf(user) - userWbtcBefore;
    uint256 received1 = usdc.balanceOf(user) - userUsdcBefore;

    // User should receive at least their proportional share of reported balances.
    uint256 expected0 = bal0Before * userShares / totalShares;
    uint256 expected1 = bal1Before * userShares / totalShares;

    // This will fail if vesting is included in expected but not in received.
    // Here we just verify received >= expected (proportional to reported balances).
    gte(received0, expected0 > 2 ? expected0 - 2 : 0, "received less token0 than proportional share");
    gte(received1, expected1 > 2 ? expected1 - 2 : 0, "received less token1 than proportional share");
}

function property_secondary_position_valid_ticks() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    if (sp.liquidity > 0 || (sp.tickLower != 0 || sp.tickUpper != 0)) {
        // Secondary position ticks must be valid: lower < upper
        t(sp.tickLower < sp.tickUpper, "secondary position: tickLower >= tickUpper");

        // Secondary position should be fully OOR (not overlapping current price range)
        // It should not overlap the main position in a problematic way
        // The secondary upper tick should not be > main lower tick (for token1 secondary)
        // OR secondary lower tick should not be < main upper tick (for token0 secondary)
        (, int24 currentTick,,,,,) = pool.slot0();

        bool secondaryBelowPrice = sp.tickUpper <= currentTick;
        bool secondaryAbovePrice = sp.tickLower >= currentTick;
        t(
            secondaryBelowPrice || secondaryAbovePrice,
            "secondary position is not fully out-of-range"
        );
    }
}

function property_vesting_withdrawal_never_exceeds_remaining() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    uint256 lastValid = block.timestamp < vp.endTs ? block.timestamp : vp.endTs;

    if (lastValid == vp.endTs) return; // safe path always uses remainingLiquidity

    // Simulate what liquidityToRemove would be
    if (vp.lastUpdate == block.timestamp) return; // early exit in real code

    uint256 duration = vp.endTs - vp.startTs;
    uint256 elapsed = lastValid - vp.lastUpdate;

    uint128 liquidityToRemove = uint128(uint256(vp.initialLiquidity) * elapsed / duration);

    // This should never exceed remainingLiquidity
    lte(
        uint256(liquidityToRemove),
        uint256(vp.remainingLiquidity),
        "liquidityToRemove exceeds remainingLiquidity: potential underflow/lockup"
    );
}

function property_interest_accrual_monotonic() public {
    // After a borrow, waiting and then calling updateState should INCREASE totalBorrows
    // relative to the borrowed principal. This validates that interest accrues.
    uint256 borrowAmount = INITIAL_DEPOSIT / 2;
    _borrowAsLeverager(borrowAmount);
    uint256 borrowsBefore = _getTotalBorrows();
    // advance time
    vm.warp(block.timestamp + 365 days);
    // trigger state update via deposit
    uint256 smallDeposit = 1000 * ONE_ASSET;
    _depositAs(depositor, smallDeposit);
    uint256 borrowsAfter = _getTotalBorrows();
    // borrows must have grown (interest accrued)
    gte(borrowsAfter, borrowsBefore, "totalBorrows did not grow after time passed with open borrow");
}

function property_underlying_balance_matches_actual() public {
    // After any sequence of pull/push/borrow/repay, reserve.underlyingBalance
    // should match the actual token balance held by yToken.
    // We test: after pullFunds without pushFunds, the accounting is broken.
    uint256 pullAmount = INITIAL_DEPOSIT / 4;
    _pullFundsAsLeverager(pullAmount);
    // Now check: actual yToken token balance vs reserve.underlyingBalance
    // reserve.underlyingBalance is accessible via reserves() tuple
    (
        uint256 borrowingIndex_,
        uint256 currentBorrowingRate_,
        uint256 totalBorrows_,
        address yTokenAddress_,
        address stakingAddress_,
        uint256 reserveCapacity_,
        ,
        ,
        uint256 underlyingBalance_,
        ,
    ) = lendingPool.reserves(address(asset));
    uint256 actualBalance = asset.balanceOf(yTokenAddress_);
    // underlyingBalance_ should equal actualBalance after pullFunds (it won't — it's too high)
    eq(underlyingBalance_, actualBalance, "underlyingBalance diverges from actual yToken balance after pullFunds");
}

function property_view_exchange_rate_consistent_with_deposit() public {
    // The exchange rate used during deposit should equal what the view function returns
    // (both computed after updateState in the same block).
    uint256 viewRate = lendingPool.exchangeRateOfReserve(address(asset));
    // deposit triggers updateState then computes same rate
    uint256 depositAmount = 1000 * ONE_ASSET;
    uint256 yTokensBefore = _getYTokenBalance(depositor);
    _depositAs(depositor, depositAmount);
    uint256 yTokensReceived = _getYTokenBalance(depositor) - yTokensBefore;
    // yTokensReceived = depositAmount * reserveToYTokenRate / PRECISION
    // viewRate is yTokenToReserveRate = PRECISION / reserveToYTokenRate (inverse)
    // So yTokensReceived ≈ depositAmount * PRECISION / viewRate (within rounding)
    uint256 expected = depositAmount * PRECISION / viewRate;
    // allow 1 wei rounding difference
    t(
        yTokensReceived == expected || yTokensReceived + 1 == expected || expected + 1 == yTokensReceived,
        "deposit yToken amount inconsistent with view exchange rate"
    );
}

function property_interest_charged_after_new_borrow() public {
    // After repaying all borrows, then re-borrowing, interest should still accrue correctly.
    uint256 borrowAmount = INITIAL_DEPOSIT / 2;
    _borrowAsLeverager(borrowAmount);
    // repay everything
    vm.warp(block.timestamp + 30 days);
    uint256 currentBorrows = _getTotalBorrows();
    _repayAsLeverager(currentBorrows + 1e18); // repay with extra to cover interest
    // verify fully repaid
    uint256 borrowsAfterRepay = _getTotalBorrows();
    // now borrow again
    _borrowAsLeverager(borrowAmount);
    uint256 borrowsAfterReborrow = _getTotalBorrows();
    // advance time
    vm.warp(block.timestamp + 365 days);
    // trigger accrual
    _depositAs(depositor, 1000 * ONE_ASSET);
    uint256 borrowsAfterYear = _getTotalBorrows();
    // borrows must have grown (interest accrued on the new borrow)
    gte(borrowsAfterYear, borrowsAfterReborrow, "interest not accrued after re-borrow");
}

function property_pull_funds_blocked_when_paused() public {
    // pullFunds should revert when the contract is paused
    _pauseAsOwner();
    t(_isPaused(), "contract should be paused");
    uint256 pullAmount = INITIAL_DEPOSIT / 4;
    // attempt pullFunds while paused — should revert
    vm.prank(leverager);
    bool succeeded = false;
    try lendingPool.pullFunds(address(asset), pullAmount) {
        succeeded = true;
    } catch {}
    t(!succeeded, "pullFunds should be blocked when contract is paused");
}

function property_compounded_interest_minimum_after_long_period() public {
    uint256 borrowAmount = (INITIAL_DEPOSIT * 9) / 10;
    _borrowAsLeverager(borrowAmount);
    uint256 totalBorrowsBefore = _getTotalBorrows();
    uint256 liquidityBefore = _getTotalLiquidity();
    // advance 2 years
    vm.warp(block.timestamp + 730 days);
    // trigger state update
    _depositAs(depositor, 1000 * ONE_ASSET);
    uint256 totalBorrowsAfter = _getTotalBorrows();
    // At max borrowing rate 150% APR, over 2 years, true compound ≈ borrowAmount * (1.5)^2 = 2.25x
    // The 3-term approximation should give at least 1.5x growth (just the linear term is 3.0 over 2yr)
    // We just verify monotonic growth is substantial
    gte(totalBorrowsAfter, totalBorrowsBefore + borrowAmount / 2, "insufficient interest accrued over long period — approximation may be too lossy");
}

function property_push_funds_updates_accounting() public {
    // pushFunds should not silently discard any accounting
    uint256 pushAmount = INITIAL_DEPOSIT / 4;
    uint256 yTokenBalanceBefore = asset.balanceOf(address(yAsset));
    _pushFundsAsLeverager(pushAmount);
    uint256 yTokenBalanceAfter = asset.balanceOf(address(yAsset));
    // Token balance of yToken should increase by exactly pushAmount
    eq(yTokenBalanceAfter, yTokenBalanceBefore + pushAmount, "pushFunds did not increase yToken token balance");
}

function property_underlying_balance_invariant() public {
    // Core invariant: reserve.underlyingBalance == actual token balance of yToken
    // This must hold at all times (outside of pullFunds/pushFunds windows)
    (
        ,
        ,
        ,
        address yTokenAddress_,
        ,
        ,
        ,
        ,
        uint256 underlyingBalance_,
        ,
    ) = lendingPool.reserves(address(asset));
    uint256 actualBalance = asset.balanceOf(yTokenAddress_);
    eq(underlyingBalance_, actualBalance, "reserve.underlyingBalance != actual yToken token balance");
}

function property_pull_funds_updates_underlying_balance() public {
    // Setup: leverager pulls half of available funds
    uint256 available = lendingPool.totalLiquidityOfReserve(address(asset));
    uint256 pullAmount = available / 4;
    if (pullAmount == 0) return;

    uint256 underlyingBefore = asset.balanceOf(address(yAsset));
    _pullFundsAsLeverager(pullAmount);
    uint256 underlyingAfter = asset.balanceOf(address(yAsset));

    // The actual token balance decreased
    // The reserve's tracked underlyingBalance should also have decreased
    // (or at least not be greater than actual balance)
    uint256 reserveAvailable = lendingPool.totalLiquidityOfReserve(address(asset))
        - lendingPool.totalBorrowsOfReserve(address(asset));

    // After pullFunds, availableLiquidity() should not exceed actual yToken asset balance
    lte(reserveAvailable, asset.balanceOf(address(yAsset)),
        "availableLiquidity exceeds actual yToken balance after pullFunds");
}

function property_underlying_balance_equals_ytokens_asset_balance() public {
    // After any sequence of deposit/redeem/borrow/repay without pullFunds,
    // underlyingBalance (= availableLiquidity) should match actual yToken asset balance
    // This checks that the base invariant holds after normal operations
    uint256 actualBalance = asset.balanceOf(address(yAsset));
    uint256 totalLiq = lendingPool.totalLiquidityOfReserve(address(asset));
    uint256 totalBorrows = lendingPool.totalBorrowsOfReserve(address(asset));
    uint256 reportedAvailable = totalLiq - totalBorrows;

    // Available liquidity tracked by reserve must equal actual token balance in yToken
    eq(reportedAvailable, actualBalance,
        "underlyingBalance desync: reserve.underlyingBalance != yToken asset balance");
}

function property_borrow_sends_to_msg_sender_not_third_party() public {
    // Borrow must only send tokens to leverager (msg.sender at time of borrow call)
    uint256 leveragerBalBefore = asset.balanceOf(leverager);
    uint256 poolBalBefore = asset.balanceOf(address(yAsset));

    uint256 borrowAmount = 1 * ONE_ASSET;
    _borrowAsLeverager(borrowAmount);

    uint256 leveragerBalAfter = asset.balanceOf(leverager);
    uint256 poolBalAfter = asset.balanceOf(address(yAsset));

    // All borrowed tokens should have gone to leverager, not anywhere else
    eq(leveragerBalAfter - leveragerBalBefore, borrowAmount,
        "borrow did not send exactly borrowAmount to leverager");
    eq(poolBalBefore - poolBalAfter, borrowAmount,
        "yToken balance did not decrease by borrowAmount");
}

function property_leverager_immutable_risk() public {
    // Once set, leverager cannot be changed
    // If leverager address is set, confirm the owner cannot update it
    address currentLeverager = lendingPool.leverager();
    t(currentLeverager != address(0), "leverager should be set after setup");

    // Attempt to set leverager again as owner should revert
    // (We test the invariant: leverager remains constant)
    address leveragerAfter = lendingPool.leverager();
    eq(uint256(uint160(leveragerAfter)), uint256(uint160(currentLeverager)),
        "leverager address changed unexpectedly");
}

function property_exchange_rate_consistent_after_pull_push() public {
    // Get rate before any pull/push
    uint256 rateBefore = lendingPool.exchangeRateOfReserve(address(asset));

    // Pull and immediately push back same amount
    uint256 pullAmount = INITIAL_DEPOSIT / 10;
    _pullFundsAsLeverager(pullAmount);
    _pushFundsAsLeverager(pullAmount);

    uint256 rateAfter = lendingPool.exchangeRateOfReserve(address(asset));

    // Exchange rate should be unchanged after pull+push of same amount
    eq(rateBefore, rateAfter,
        "exchange rate changed after pull+push of equal amounts");
}

function property_first_depositor_not_severely_diluted() public {
    // Deploy a fresh pool with a new asset to test first-deposit behavior
    MockERC20 freshAsset = new MockERC20("Fresh", "FRH", 18);
    LendingPool freshPool = new LendingPool();

    vm.prank(owner);
    freshPool.initReserve(address(freshAsset));

    address freshYToken = freshPool.getYTokenAddress(address(freshAsset));

    // First depositor deposits just above minimum
    uint256 firstDeposit = MINIMUM_YTOKEN_AMOUNT + 1; // 1001 wei
    deal(address(freshAsset), user, firstDeposit);

    vm.startPrank(user);
    freshAsset.approve(address(freshPool), type(uint256).max);
    uint256 yReceived = freshPool.deposit(address(freshAsset), firstDeposit, user);
    vm.stopPrank();

    // User should have received at least 1 yToken
    // But 1000 were burned — user gets only 1 yToken for 1001 underlying
    // This is the dilution: 1 yToken out of 1001+1000=2001 total represents 50% not 100%
    uint256 userYBal = IERC20(freshYToken).balanceOf(user);
    uint256 totalSupply = IERC20(freshYToken).totalSupply();

    // Invariant: first depositor's yToken share should represent close to their deposit
    // If yReceived << firstDeposit, the depositor was heavily diluted
    gte(yReceived, firstDeposit / 2,
        "first depositor severely diluted: received far fewer yTokens than deposited");
}

function property_changePositionWidth_only_owner_or_rebalancer() public {
    // If attacker (not owner, not rebalancer) calls changePositionWidth, tx must revert
    // We test this by verifying that positionWidth cannot be changed by attacker
    uint24 widthBefore = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();
    uint24 newWidth = uint24(int24(widthBefore) + 2 * ts); // valid: halfWidth divisible by tickSpacing
    vm.prank(attacker);
    // changePositionWidth has no access control; it will only revert if rebalance() reverts
    // If attacker == rebalancer this would succeed — we assert attacker != rebalancer
    try strategy.changePositionWidth(newWidth) {
        // If this succeeds, attacker changed positionWidth — should never happen
        uint24 widthAfter = strategy.positionWidth();
        t(widthAfter == widthBefore, "attacker must not be able to change positionWidth");
    } catch {
        // expected: revert because attacker is not rebalancer
        t(true, "ok");
    }
}

function property_collectFees_public_no_vesting_manipulation() public {
    // Ensure that publicly calling collectFees does not give attacker an advantage
    // Setup: record attacker shares and total balances before
    uint256 attackerShares = vault.balanceOf(attacker);
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();

    // Attacker calls collectFees directly (public, no restriction)
    vm.prank(attacker);
    strategy.collectFees();

    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    uint256 supplyAfter = vault.totalSupply();

    // Supply must not change (no mint/burn)
    eq(supplyBefore, supplyAfter, "supply must not change from collectFees");

    // Attacker shares must not change
    eq(attackerShares, vault.balanceOf(attacker), "attacker shares unchanged");

    // Balances may increase (fees collected) but must not decrease
    gte(bal0After, bal0Before, "bal0 must not decrease from collectFees");
    gte(bal1After, bal1Before, "bal1 must not decrease from collectFees");
}

function property_deposit_shares_not_less_than_expected() public {
    // Depositor deposits tokens; verify share count is consistent with fee
    uint256 fee = vault.depositFee();
    (uint256 bal0, uint256 bal1) = strategy.balances();
    uint256 supply = vault.totalSupply();

    uint256 dep0 = ONE_TOKEN0;
    uint256 dep1 = ONE_TOKEN1 * 1000;

    deal(WBTC_ADDR, depositor, dep0);
    deal(USDC_ADDR, depositor, dep1);

    vm.prank(depositor);
    (uint256 shares, uint256 used0, uint256 used1) = vault.deposit(dep0, dep1, 0, 0);

    // Shares must be > 0
    t(shares > 0, "shares must be positive");

    // If fee is 0, shares should equal gross shares exactly
    if (fee == 0 && supply > 0 && bal0 > 0 && bal1 > 0) {
        uint256 cross0 = used0 * bal1;
        uint256 cross1 = used1 * bal0;
        uint256 cross = cross0 < cross1 ? cross0 : cross1;
        uint256 expectedShares = cross * supply / bal0 / bal1;
        // allow 1 wei rounding
        gte(shares + 1, expectedShares, "shares should match expected (no fee)");
    }
}

function property_balances_includes_vesting_liquidity() public {
    // If a vesting position exists with nonzero remainingLiquidity,
    // balances() should account for it (or at least not be less than idle+main+secondary alone)
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) {
        t(true, "no ongoing vesting position, skip");
        return;
    }

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) {
        t(true, "no remaining vesting liquidity, skip");
        return;
    }

    (uint256 idle0, uint256 idle1) = strategy.idleBalances();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    // balances() should be >= idle balances (this is always true, just the vesting delta)
    gte(bal0, idle0, "balances0 must include at least idle0");
    gte(bal1, idle1, "balances1 must include at least idle1");

    // The key invariant: if vesting has remaining liquidity, balances() understates true assets
    // We cannot enforce it as a strict gte here since vesting is excluded by design,
    // but we document: the difference is vestPosition liquidity value
    // Property: total shares * (bal per share) should approximate full asset value
    uint256 totalSupply = vault.totalSupply();
    t(totalSupply > 0, "supply must be nonzero");
    // Just verify balances are consistent (non-zero when positions exist)
    t(bal0 > 0 || bal1 > 0, "strategy must hold some assets");
}

function property_withdraw_no_more_than_deposited_value() public {
    // A depositor should not be able to withdraw more value (in token1 terms) than they deposited
    // This tests that spot-price manipulation cannot inflate withdrawals
    uint256 dep0 = ONE_TOKEN0;
    uint256 dep1 = ONE_TOKEN1 * 50000;

    deal(WBTC_ADDR, depositor, dep0);
    deal(USDC_ADDR, depositor, dep1);

    vm.startPrank(depositor);
    (uint256 shares,,) = vault.deposit(dep0, dep1, 0, 0);
    vm.stopPrank();

    // Record value deposited (approximate, using strategy price)
    uint256 priceAtDeposit = strategy.price(); // 1e30 precision

    // Immediately withdraw
    vm.prank(depositor);
    (uint256 got0, uint256 got1) = vault.withdraw(shares, 0, 0);

    // got0 + got1 in token1 terms should be <= dep0 + dep1 in token1 terms (with small rounding)
    // Using priceAtDeposit: value0in1 = got0 * price / STRATEGY_PRECISION
    uint256 valueOut0in1 = got0 * priceAtDeposit / STRATEGY_PRECISION;
    uint256 valueIn0in1  = dep0 * priceAtDeposit / STRATEGY_PRECISION;

    // total value out <= total value in (ignoring rounding, fees improve LPs not hurt them)
    uint256 totalValueOut = valueOut0in1 + got1;
    uint256 totalValueIn  = valueIn0in1 + dep1;

    lte(totalValueOut, totalValueIn + 2, "cannot withdraw more value than deposited");
}

function property_checkPoolActivity_is_view_only() public {
    // checkPoolActivity should not change any observable state
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    uint256 supplyBefore = vault.totalSupply();

    // Anyone can call checkPoolActivity
    vm.prank(attacker);
    vault.checkPoolActivity();

    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    uint256 supplyAfter = vault.totalSupply();

    eq(bal0Before, bal0After, "checkPoolActivity must not change bal0");
    eq(bal1Before, bal1After, "checkPoolActivity must not change bal1");
    eq(supplyBefore, supplyAfter, "checkPoolActivity must not change supply");
}

function property_strategy_approval_bounded_by_shares() public {
    // The strategy has pre-approved vault for unlimited tokens.
    // Verify that an attacker with 0 shares cannot cause any token transfer from strategy.
    uint256 stratBal0Before = token0.balanceOf(address(strategy));
    uint256 stratBal1Before = token1.balanceOf(address(strategy));

    // Attacker has 0 shares — any withdraw call should revert
    vm.prank(attacker);
    try vault.withdraw(1, 0, 0) {
        // If this succeeds, attacker stole from strategy
        t(false, "attacker with 0 shares must not withdraw");
    } catch {
        t(true, "correctly reverted");
    }

    // Strategy balance must be unchanged
    eq(token0.balanceOf(address(strategy)), stratBal0Before, "strategy token0 unchanged");
    eq(token1.balanceOf(address(strategy)), stratBal1Before, "strategy token1 unchanged");
}

function property_withdraw_shares_not_burned_without_tokens() public {
    // Setup: user deposits and gets shares
    uint256 sharesBefore = vault.balanceOf(user);
    if (sharesBefore == 0) return;

    uint256 token0Before = token0.balanceOf(user);
    uint256 token1Before = token1.balanceOf(user);

    // Record total supply before
    uint256 supplyBefore = vault.totalSupply();

    vm.prank(user);
    try vault.withdraw(sharesBefore / 2, 0, 0) returns (uint256 a0, uint256 a1) {
        // If withdraw succeeds, user must have received tokens
        uint256 token0After = token0.balanceOf(user);
        uint256 token1After = token1.balanceOf(user);
        // At least one token should have increased
        t(
            token0After >= token0Before || token1After >= token1Before,
            "TBH-001: shares burned but no tokens received"
        );
    } catch {
        // If withdraw reverted, shares must still be intact
        uint256 sharesAfter = vault.balanceOf(user);
        eq(sharesAfter, sharesBefore, "TBH-001: shares lost on failed withdraw");
    }
}

function property_withdraw_no_strategy_overdrain() public {
    // After any withdraw, the strategy's remaining balances should be
    // proportional to remaining shares outstanding
    uint256 sharesBefore = vault.balanceOf(user);
    if (sharesBefore == 0) return;

    uint256 totalSupplyBefore = vault.totalSupply();
    (uint256 stratBal0Before, uint256 stratBal1Before) = strategy.balances();

    vm.prank(user);
    (uint256 got0, uint256 got1) = vault.withdraw(sharesBefore, 0, 0);

    uint256 totalSupplyAfter = vault.totalSupply();
    (uint256 stratBal0After, uint256 stratBal1After) = strategy.balances();

    // Remaining strategy balance should be >= remaining proportional share
    if (totalSupplyAfter > 0 && totalSupplyBefore > 0) {
        uint256 expectedRemaining0 = stratBal0Before * totalSupplyAfter / totalSupplyBefore;
        uint256 expectedRemaining1 = stratBal1Before * totalSupplyAfter / totalSupplyBefore;
        // Allow small rounding tolerance (1 wei per token)
        gte(stratBal0After + 1, expectedRemaining0, "TBH-002: strategy overdrained token0");
        gte(stratBal1After + 1, expectedRemaining1, "TBH-002: strategy overdrained token1");
    }
}

description:
In _calcDeposit(), the cross-product calculation on line 141-143 is:
  uint256 cross0 = depositAmount0 * bal1;
  uint256 cross1 = depositAmount1 * bal0;
  uint256 cross = cross0 > cross1 ? cross1 : cross0;
Both multiplications are performed in Solidity 0.8 with checked arithmetic. If depositAmount0 is large (up to type(uint256).max / 2) and bal1 is also large, the multiplication overflows and reverts with a panic. Users who want to deposit very large amounts (or during a strategy state where balances are large) will find deposits DOSed by arithmetic overflow — permanently if the protocol becomes large enough. This is a trust boundary issue because the Vault trusts the Strategy's `balances()` return without bounding it.

solidity:
function property_deposit_never_reverts_with_valid_inputs() public {
    // Deposit with reasonable amounts should not overflow
    uint256 amt0 = _clampBetween(ONE_TOKEN0, 1, 100 * ONE_TOKEN0);
    uint256 amt1 = _clampBetween(ONE_TOKEN1, 1, 1_000_000 * ONE_TOKEN1);

    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    vm.prank(depositor);
    try vault.deposit(amt0, amt1, 0, 0) returns (uint256 shares, uint256, uint256) {
        t(shares > 0 || (amt0 == 0 && amt1 == 0), "TBH-005: deposit returned 0 shares");
    } catch Error(string memory reason) {
        // Only acceptable revert is slippage or cross==0
        // Overflow panic is NOT acceptable
        t(
            keccak256(bytes(reason)) == keccak256(bytes("cross")) ||
            keccak256(bytes(reason)) == keccak256(bytes("shares cant be 0")) ||
            keccak256(bytes(reason)) == keccak256(bytes("slippage0")) ||
            keccak256(bytes(reason)) == keccak256(bytes("slippage1")),
            "TBH-005: unexpected deposit revert"
        );
    } catch {
        // Panic (overflow) should not happen with reasonable inputs
        t(false, "TBH-005: deposit panicked (possible overflow)");
    }
}

function property_withdraw_proportional_to_shares() public {
    // Two depositors with equal shares should receive equal amounts
    uint256 amt0 = ONE_TOKEN0;
    uint256 amt1 = 100_000 * ONE_TOKEN1;
    deal(WBTC_ADDR, user, amt0);
    deal(USDC_ADDR, user, amt1);
    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    vm.prank(user);
    (uint256 sharesUser,,) = vault.deposit(amt0, amt1, 0, 0);

    vm.prank(depositor);
    (uint256 sharesDepositor,,) = vault.deposit(amt0, amt1, 0, 0);

    // Both deposited the same, so shares should be equal (within rounding)
    // Now both withdraw
    vm.prank(user);
    (uint256 u0, uint256 u1) = vault.withdraw(sharesUser, 0, 0);

    vm.prank(depositor);
    (uint256 d0, uint256 d1) = vault.withdraw(sharesDepositor, 0, 0);

    // Both should receive approximately equal amounts (within 1 wei)
    // If shares were equal, returns should be within 1 wei
    uint256 diff0 = u0 > d0 ? u0 - d0 : d0 - u0;
    uint256 diff1 = u1 > d1 ? u1 - d1 : d1 - u1;
    lte(diff0, 1, "TBH-007: unequal token0 withdrawal for equal shares");
    lte(diff1, 1, "TBH-007: unequal token1 withdrawal for equal shares");
}

function property_fullmath_muldiv_correct() public pure {
    // Verify FullMath.mulDiv produces correct results for known values
    // 1 * 1 / 1 = 1
    uint256 r1 = FullMath.mulDiv(1, 1, 1);
    eq(r1, 1, "TBH-008: mulDiv(1,1,1) != 1");

    // 2^128 * 2^128 / 2^128 = 2^128
    uint256 r2 = FullMath.mulDiv(2**128, 2**128, 2**128);
    eq(r2, 2**128, "TBH-008: mulDiv(2^128,2^128,2^128) != 2^128");

    // 3 * 7 / 3 = 7
    uint256 r3 = FullMath.mulDiv(3, 7, 3);
    eq(r3, 7, "TBH-008: mulDiv(3,7,3) != 7");
}

function property_pullFunds_underlyingBalance_invariant() public {
    // After pullFunds, actual token balance should equal underlyingBalance
    // (no borrows in this test, so all underlyingBalance should be real)
    uint256 poolBalance = _getUnderlyingBalance(); // asset.balanceOf(yToken)
    (uint256 totalLiq,) = lendingPool.totalLiquidityOfReserve(address(asset));
    // Ignore borrows for this simplified check: underlyingBalance tracks available liquidity
    // The invariant: available (underlyingBalance) <= actual token balance
    uint256 available = lendingPool.totalLiquidityOfReserve(address(asset))
        - lendingPool.totalBorrowsOfReserve(address(asset));
    lte(available, poolBalance, "underlyingBalance exceeds actual token balance: solvency broken");
}

function property_total_claims_le_total_assets() public {
    // Total underlying redeemable by all yToken holders must not exceed actual token balance
    uint256 totalYTokenSupply = _getYTokenTotalSupply();
    uint256 exchangeRate = _getExchangeRate(); // yToken -> underlying, scaled by PRECISION
    uint256 totalClaims = totalYTokenSupply * exchangeRate / PRECISION;
    uint256 totalLiquidity = _getTotalLiquidity(); // underlyingBalance + accrued borrows
    // Claims are backed by totalLiquidity which includes unbacked accrued interest
    // The actual tokens in yToken contract is just underlyingBalance
    uint256 actualTokens = _getUnderlyingBalance();
    uint256 totalBorrows = _getTotalBorrows();
    // Depositors' claims on available liquidity should not exceed available liquidity
    // i.e., the exchange rate should be consistent with real assets + outstanding borrows
    lte(totalClaims, totalLiquidity, "total yToken claims exceed reported total liquidity");
}

function property_pullFunds_cannot_drain_deposits() public {
    // After pullFunds followed by pushFunds (net zero), balance should be restored
    uint256 balanceBefore = _getUnderlyingBalance();
    uint256 pullAmount = balanceBefore / 2;

    if (pullAmount == 0) return;

    // Pull then push same amount
    vm.prank(leverager);
    lendingPool.pullFunds(address(asset), pullAmount);

    vm.startPrank(leverager);
    asset.approve(address(lendingPool), pullAmount);
    lendingPool.pushFunds(address(asset), pullAmount);
    vm.stopPrank();

    uint256 balanceAfter = _getUnderlyingBalance();
    eq(balanceBefore, balanceAfter, "pull+push should restore exact token balance");
}

function property_underlyingBalance_equals_actual_balance() public {
    // underlyingBalance (accessed via availableLiquidity) should equal actual token balance
    // when there are no outstanding pullFunds (i.e., after clean deposit/borrow/repay/redeem only)
    uint256 actualBalance = _getUnderlyingBalance(); // asset.balanceOf(yToken)
    uint256 totalLiq = _getTotalLiquidity();
    uint256 totalBorrows = _getTotalBorrows();
    uint256 reportedAvailable = totalLiq - totalBorrows; // = underlyingBalance

    // Core invariant: reported available == actual available
    eq(reportedAvailable, actualBalance, "underlyingBalance diverged from actual token balance");
}

function property_deposit_redeem_roundtrip_no_loss() public {
    // For a non-first deposit with no borrows and no time elapsed:
    // depositing X and immediately redeeming the received yTokens should return >= X - 1
    uint256 depositAmount = 1000 * ONE_ASSET;
    uint256 yTokensBefore = _getYTokenBalance(user);

    vm.prank(user);
    uint256 yReceived = lendingPool.deposit(address(asset), depositAmount, user);

    uint256 assetBefore = _getAssetBalance(user);

    vm.prank(user);
    uint256 underlyingReceived = lendingPool.redeem(address(asset), yReceived, user);

    uint256 assetAfter = _getAssetBalance(user);

    // Should get back at most 1 wei less than deposited (rounding)
    gte(underlyingReceived + 1, depositAmount, "deposit-redeem roundtrip lost more than 1 wei");
}

function property_pullFunds_updates_underlyingBalance() public {
    // Capture state before pull
    uint256 balBefore = _getUnderlyingBalance();
    uint256 pullAmt = balBefore / 2;
    if (pullAmt == 0) return;

    // Pull funds (no borrow accounting, just raw transfer)
    _pullFundsAsLeverager(pullAmt);

    // After pull: actual token balance of yToken must equal reported underlyingBalance
    // (which is used as availableLiquidity). If they diverge, depositors can be bricked.
    (uint256 totalLiq,) = lendingPool.totalLiquidityOfReserve(address(asset));
    // totalLiq = underlyingBalance + borrows. Since no borrows here, underlyingBalance = totalLiq.
    uint256 actualTokens = asset.balanceOf(address(yAsset));
    // If underlyingBalance was not decremented, actualTokens < reportedAvailable
    // which means the system is insolvent from an accounting perspective.
    // Property: reported available liquidity must not exceed actual tokens held.
    uint256 reportedAvailable = lendingPool.totalLiquidityOfReserve(address(asset));
    gte(actualTokens, reportedAvailable, "underlyingBalance not decremented: pool appears solvent but isn't");
}

function property_deposit_redeem_no_loss_small_amount() public {
    // Verify that a depositor who deposits and immediately redeems loses at most 1 wei
    // per division operation (2 divisions max = at most 2 wei loss).
    uint256 depositAmount = 1000 * ONE_ASSET;
    uint256 assetBefore = asset.balanceOf(depositor);

    uint256 yTokensReceived = _depositAs(depositor, depositAmount);
    if (yTokensReceived == 0) return;

    uint256 underlyingReceived = _redeemAs(depositor, yTokensReceived);
    uint256 assetAfter = asset.balanceOf(depositor);

    // Loss must not exceed 2 units (2 floor divisions, each loses at most 1 unit)
    uint256 loss = assetBefore - assetAfter;
    lte(loss, 2, "deposit-redeem round trip loses more than 2 units: excessive precision loss");
}

function property_exchange_rate_inverse_consistency() public {
    // The two exchange rates must be consistent inverses of each other within 1 PRECISION unit
    uint256 toYToken = lendingPool.utilizationRateOfReserve(address(asset)); // just to trigger state
    uint256 rateDeposit = 0;
    uint256 ratRedeem = lendingPool.exchangeRateOfReserve(address(asset));

    // Compute reserveToYToken rate manually
    uint256 totalLiq = _getTotalLiquidity();
    uint256 totalYT = _getYTokenTotalSupply();
    if (totalYT == 0 || totalLiq == 0) return;

    rateDeposit = totalYT * PRECISION / totalLiq;  // reserveToYTokenExchangeRate

    // Product of both rates should be close to PRECISION
    // rateDeposit * ratRedeem / PRECISION should equal PRECISION (within rounding)
    uint256 product = rateDeposit * ratRedeem / PRECISION;
    // Allow at most 1 unit deviation in either direction
    gte(product, PRECISION - 1, "exchange rate product is too low: excessive asymmetry");
    lte(product, PRECISION + 1, "exchange rate product is too high: rate inconsistency");
}

function property_first_depositor_minimum_ytoken_consistency() public {
    // After first deposit with minimum viable amount, user must receive at least 1 yToken
    // The first deposit burns 1000 yTokens to DEAD_ADDRESS
    // So user needs to deposit > 1000 tokens (in 1:1 rate scenario) to get any yTokens

    // Setup: this test only applies if yToken supply is currently 0
    if (_getYTokenTotalSupply() > 0) return;

    // Try depositing exactly MINIMUM_YTOKEN_AMOUNT + 1 (= 1001 tokens)
    uint256 dustDeposit = MINIMUM_YTOKEN_AMOUNT + 1;
    deal(address(asset), attacker, dustDeposit);
    vm.prank(attacker);
    asset.approve(address(lendingPool), dustDeposit);

    // This should succeed but attacker only gets 1 yToken for 1001 tokens deposited
    // That's 1000 tokens effectively burned, which is the intended behavior
    // But verify the return value is correct
    vm.prank(attacker);
    uint256 yReceived = lendingPool.deposit(address(asset), dustDeposit, attacker);
    // yReceived should be 1 (1001 - 1000 burned)
    eq(yReceived, 1, "first depositor with minimum viable amount should receive exactly 1 yToken");
    eq(_getYTokenBalance(attacker), 1, "attacker yToken balance should be 1");
}

function property_interest_accrues_over_time() public {
    // If there are borrows and time passes, the borrowing index must increase
    uint256 borrowAmount = INITIAL_DEPOSIT / 2;
    _borrowAsLeverager(borrowAmount);

    uint256 indexBefore = lendingPool.getCurrentBorrowingIndex(address(asset));
    uint256 borrowsBefore = _getTotalBorrows();

    // Skip 1 year
    skip(365 days);

    uint256 indexAfter = lendingPool.getCurrentBorrowingIndex(address(asset));
    uint256 borrowsAfter = _getTotalBorrows();

    // Index must have grown
    gte(indexAfter, indexBefore, "borrowing index must not decrease");
    // Borrows must reflect interest (borrowsAfter > borrowsBefore)
    gte(borrowsAfter, borrowsBefore, "total borrows must not decrease over time when borrowed");
    // With 50% utilization the rate is non-trivial, interest must be positive
    t(borrowsAfter > borrowsBefore, "no interest accrued despite active borrows and time passing");
}

function property_total_liquidity_grows_with_interest() public {
    uint256 borrowAmount = INITIAL_DEPOSIT / 2;
    _borrowAsLeverager(borrowAmount);

    uint256 liquidityBefore = _getTotalLiquidity();

    // Skip time to accrue interest
    skip(30 days);

    // Trigger state update
    vm.prank(user);
    lendingPool.deposit(address(asset), ONE_ASSET, user);

    uint256 liquidityAfter = _getTotalLiquidity();

    // Total liquidity must grow (interest accrued to lenders)
    t(liquidityAfter > liquidityBefore, "total liquidity did not grow despite interest accrual");
}

function property_deposit_no_slippage_without_state_change() public {
    // If no external state changes occur between computing expected yTokens and the deposit,
    // the user should receive exactly the computed amount.
    uint256 depositAmount = 10_000 * ONE_ASSET;

    // Compute expected yTokens (simulate what deposit() will compute)
    uint256 totalLiq = _getTotalLiquidity();
    uint256 totalYT = _getYTokenTotalSupply();
    uint256 expectedRate;
    if (totalYT == 0 || totalLiq == 0) {
        expectedRate = PRECISION;
    } else {
        expectedRate = totalYT * PRECISION / totalLiq;
    }
    uint256 expectedYTokens = depositAmount * expectedRate / PRECISION;

    if (expectedYTokens <= MINIMUM_YTOKEN_AMOUNT) return;

    uint256 actualYTokens = _depositAs(depositor, depositAmount);

    // Since no state changed between our calculation and the deposit,
    // actualYTokens should match expectedYTokens
    eq(actualYTokens, expectedYTokens, "deposit returned different yTokens than expected: slippage");
}

function property_exchange_rate_monotonically_increases() public {
    // With active borrows, exchange rate must never decrease over time
    uint256 borrowAmount = INITIAL_DEPOSIT / 2;
    _borrowAsLeverager(borrowAmount);

    uint256 rateBefore = _getExchangeRate();

    skip(30 days);

    // Trigger state update (deposit a tiny amount)
    vm.prank(depositor);
    // Note: need depositor to have enough. They have ACTOR_INITIAL_BALANCE.
    uint256 tiny = MINIMUM_YTOKEN_AMOUNT + 1;
    lendingPool.deposit(address(asset), tiny, depositor);

    uint256 rateAfter = _getExchangeRate();

    gte(rateAfter, rateBefore, "exchange rate decreased: lenders lost value");
}

function property_pool_solvency_after_full_repay() public {
    uint256 borrowAmount = INITIAL_DEPOSIT / 2;
    _borrowAsLeverager(borrowAmount);

    // Let interest accrue
    skip(30 days);

    // Repay all borrows (repay() caps at totalBorrows internally)
    uint256 repayAmount = _getTotalBorrows() + 1; // repay more than owed to test cap
    _repayAsLeverager(repayAmount);

    // After full repay, total borrows should be 0
    uint256 remainingBorrows = _getTotalBorrows();
    eq(remainingBorrows, 0, "total borrows not zero after full repay");

    // Total liquidity should equal underlyingBalance (no borrows)
    uint256 totalLiq = _getTotalLiquidity();
    uint256 underlyingBal = _getUnderlyingBalance();
    eq(totalLiq, underlyingBal, "total liquidity != underlyingBalance after full repay");

    // The pool must be able to satisfy all yToken redemptions
    // yToken total supply * exchange rate / PRECISION <= totalLiquidity
    uint256 totalYT = _getYTokenTotalSupply();
    uint256 rate = _getExchangeRate();
    uint256 totalClaims = totalYT * rate / PRECISION;
    lte(totalClaims, totalLiq, "pool insolvent: yToken claims exceed available liquidity");
}

function property_borrowing_rate_at_full_utilization() public {
    // At 100% utilization, the borrowing rate should be the maximum borrowing rate
    // Borrow everything available
    uint256 available = _getUnderlyingBalance();
    if (available == 0) return;

    _borrowAsLeverager(available);

    // Now utilization = 100%
    uint256 utilization = _getUtilizationRate();
    // utilization should be close to PRECISION (1e27)
    if (utilization < PRECISION * 99 / 100) return; // not at full utilization

    uint256 borrowRate = _getBorrowingRate();

    // At full utilization, the borrowing rate should be the max (15000 bps = 150%)
    // maxBorrowingRate = PRECISION * 15000 / 10000 = 1.5e27
    uint256 expectedMaxRate = PRECISION * 15000 / 10000;
    gte(borrowRate, expectedMaxRate * 99 / 100, "borrowing rate at full utilization is below max: rate discontinuity");
}

function property_inflation_attack_neutralized() public {
    // Verify that a new pool cannot be griefed via the inflation attack
    // (because underlyingBalance != token.balanceOf(yToken), donations don't help attacker)

    // Setup: deploy fresh pool (we use existing pool which has INITIAL_DEPOSIT already)
    // Instead, verify that direct token donations to yToken don't change exchange rate
    uint256 rateBefore = _getExchangeRate();

    // Attacker donates 1000x INITIAL_DEPOSIT directly to yToken (bypassing lendingPool)
    deal(address(asset), attacker, INITIAL_DEPOSIT * 1000);
    vm.prank(attacker);
    asset.transfer(address(yAsset), INITIAL_DEPOSIT * 1000);

    uint256 rateAfter = _getExchangeRate();

    // Exchange rate must be unchanged: donations don't affect underlyingBalance
    eq(rateBefore, rateAfter, "direct donation to yToken changed exchange rate: inflation attack possible");
}

function property_rebalance_not_dos_by_observation_cardinality() public {
    // After enough time passes, rebalance should be callable without OOG.
    // We test this by checking that checkPoolActivity() doesn't revert
    // (gas DoS would manifest as revert in fuzzing environment).
    // Property: if block.timestamp - lastRebalance >= rebalanceInterval,
    // and price is in range, rebalance should not revert.
    uint256 lastReb = strategy.lastRebalance();
    uint256 interval = strategy.rebalanceInterval();
    if (block.timestamp < lastReb + interval) return; // not yet time
    // Check that checkPoolActivity does not revert (gas DoS test)
    bool active = strategy.checkPoolActivity();
    // If the pool has reasonable cardinality and all observations are initialized,
    // this should return true (pool is active).
    t(active, "checkPoolActivity reverted or returned false: possible gas DoS via observation cardinality");
}

function property_checkPoolActivity_never_reverts() public {
    // checkPoolActivity() is a view function called from _priceWithinRange(),
    // which guards rebalance/compound/addVestingPosition.
    // It must not revert — only return true or false.
    // A revert here permanently bricks price-gated operations.
    // Note: In fuzzing we can observe if a call to checkPoolActivity reverts.
    bool ok;
    bool result;
    (ok, result) = _tryCheckPoolActivity();
    t(ok, "checkPoolActivity() reverted: DoS on price-gated functions");
}

function _tryCheckPoolActivity() internal view returns (bool ok, bool result) {
    // Use low-level call to catch revert
    bytes memory data = abi.encodeWithSelector(strategy.checkPoolActivity.selector);
    bytes memory ret;
    (ok, ret) = address(strategy).staticcall(data);
    if (ok && ret.length == 32) {
        result = abi.decode(ret, (bool));
    }
}

function property_collectFees_succeeds_after_rebalance_with_vesting() public {
    // If there is an ongoing vesting position and we rebalance (changing main ticks),
    // collectFees() must still succeed without reverting.
    if (!strategy.ongoingVestingPosition()) return; // only test when vesting is active
    // Attempt collectFees — must not revert
    bool ok;
    bytes memory data = abi.encodeWithSelector(strategy.collectFees.selector);
    (ok,) = address(strategy).call(data);
    t(ok, "collectFees() reverted after rebalance with ongoing vesting position: wrong tick bug");
}

function property_rebalance_possible_after_interval() public {
    // After the rebalance interval has passed and price is stable,
    // rebalance() should succeed (not revert due to checkPoolActivity).
    uint256 lastReb = strategy.lastRebalance();
    uint256 interval = strategy.rebalanceInterval();
    if (block.timestamp < lastReb + interval) return;
    // Try to call checkPoolActivity — it should return true for a live pool
    // that has had activity for at least twap seconds.
    bool active = strategy.checkPoolActivity();
    // On a mainnet fork with real pool activity, this should be true.
    t(active, "checkPoolActivity returned false: rebalance permanently blocked");
}

function property_addVestingPosition_zero_duration_safe() public {
    // Adding a vesting position with duration = 0 should not permanently
    // brick collectFees(). Either addVestingPosition reverts immediately,
    // or collectFees() continues to work after.
    if (strategy.ongoingVestingPosition()) return; // need no active position

    // Try adding a vesting position with 0 duration
    deal(address(wbtc), owner, 1e6);
    deal(address(usdc), owner, 1000e6);
    vm.startPrank(owner);
    wbtc.approve(address(vault), 1e6);
    usdc.approve(address(vault), 1000e6);
    bool addOk;
    (addOk,) = address(vault).call(
        abi.encodeWithSignature("addVestingPosition(uint256,uint256,uint256)", 1e6, 1000e6, 0)
    );
    vm.stopPrank();

    if (!addOk) return; // addVestingPosition reverted — safe

    // If it succeeded, collectFees must still work
    bool collectOk;
    (collectOk,) = address(strategy).call(abi.encodeWithSelector(strategy.collectFees.selector));
    t(collectOk, "collectFees reverted after zero-duration vesting position: division by zero DoS");
}

function property_checkPoolActivity_no_division_by_zero() public {
    // checkPoolActivity should never revert with division-by-zero.
    // The last loop iteration wraps the index to currentIndex,
    // causing nextTimestamp == timestamp => div by zero.
    bool ok;
    bytes memory data = abi.encodeWithSelector(strategy.checkPoolActivity.selector);
    (ok,) = address(strategy).staticcall(data);
    t(ok, "checkPoolActivity reverted: likely division by zero in last loop iteration");
}

function property_vesting_no_underflow() public {
    // Simulate multiple collectFees calls across the vesting duration
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (!strategy.ongoingVestingPosition()) return;
    if (vp.initialLiquidity == 0) return;

    // After collecting fees (advancing time partially), remainingLiquidity
    // must never exceed initialLiquidity (no underflow wrap)
    t(vp.remainingLiquidity <= vp.initialLiquidity,
      "remainingLiquidity exceeded initialLiquidity — underflow");
}

function property_vesting_collectfees_uses_correct_ticks() public {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    if (!strategy.ongoingVestingPosition()) return;

    // The vesting position tickUpper must equal vestPosition.tickUpper
    // collectFees internally uses mainPosition.tickUpper — if they diverged after rebalance,
    // the wrong position is touched. We assert they match as a safety invariant.
    // After a rebalance the main ticks change but vesting ticks do NOT.
    // This property verifies vesting ticks are self-consistent (stored correctly).
    t(vp.tickLower < vp.tickUpper, "vesting position has invalid tick range");
    // Trigger collectFees and check strategy balances didn't decrease
    (uint256 bal0Before, uint256 bal1Before) = strategy.balances();
    strategy.collectFees();
    (uint256 bal0After, uint256 bal1After) = strategy.balances();
    // Balances should not decrease from fee collection (fees add value)
    t(bal0After >= bal0Before || bal1After >= bal1Before,
      "collectFees decreased both token balances — wrong ticks used");
}

function property_withdraw_returns_nonzero_for_meaningful_shares() public {
    // After initial setup, user has shares and strategy has balances
    uint256 userShares = vault.balanceOf(user);
    if (userShares == 0) return;
    uint256 totalSupply = vault.totalSupply();
    (uint256 bal0, uint256 bal1) = strategy.balances();

    // If user holds >= 1% of supply, they should receive something non-trivial
    if (userShares * 100 < totalSupply) return; // less than 1%, skip

    uint256 wbtcBefore = wbtc.balanceOf(user);
    uint256 usdcBefore = usdc.balanceOf(user);

    vm.prank(user);
    vault.withdraw(userShares / 2, 0, 0);

    uint256 wbtcAfter = wbtc.balanceOf(user);
    uint256 usdcAfter = usdc.balanceOf(user);

    // At least one token balance should increase
    t(wbtcAfter > wbtcBefore || usdcAfter > usdcBefore,
      "Withdrawal of meaningful shares returned zero of both tokens");
}

function property_secondary_ticks_valid() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    t(sp.tickLower < sp.tickUpper,
      "Secondary position has invalid tick range: tickLower >= tickUpper");
}

function property_vesting_eventually_completes() public {
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // If we are past endTs, vesting should have been cleared
    if (block.timestamp >= vp.endTs) {
        // collectFees should clear it
        strategy.collectFees();
        t(!strategy.ongoingVestingPosition(),
          "Vesting position not cleared after endTs passed and collectFees called");
    }
}

function property_shares_not_undercounted() public {
    // Deposit as depositor and record shares received
    uint256 amt0 = ONE_TOKEN0;       // 1 WBTC
    uint256 amt1 = ONE_TOKEN1 * 10;  // 10 USDC
    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    (uint256 bal0Before, uint256 bal1Before) = _getVaultBalances();
    uint256 supplyBefore = _getTotalSupply();

    vm.prank(depositor);
    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amt0, amt1, 0, 0);

    // Expected shares: dep0 * supplyBefore / bal0Before (simplified for single-token case)
    // General: shares >= dep0 * supplyBefore / bal0Before - 1  (allow 1 wei rounding)
    if (bal0Before > 0 && bal1Before > 0 && supplyBefore > 0) {
        uint256 cross0 = dep0 * bal1Before;
        uint256 cross1 = dep1 * bal0Before;
        uint256 cross = cross0 < cross1 ? cross0 : cross1;
        // Reference: what mulDiv would give (no double truncation)
        // shares_expected = cross * supplyBefore / (bal0Before * bal1Before)  [exact]
        // Actual: cross * supplyBefore / bal0Before / bal1Before              [truncated twice]
        uint256 sharesExpected = FullMath.mulDiv(
            FullMath.mulDiv(cross, supplyBefore, bal0Before),
            1,
            bal1Before
        );
        // shares should be at least sharesExpected (double div can only decrease)
        // This property checks that no value is silently destroyed
        uint256 valueDestroyed = sharesExpected > shares ? sharesExpected - shares : 0;
        // Allow 1 wei rounding tolerance
        t(valueDestroyed <= 1, "double-division destroys more than 1 wei of shares");
    }
}

function property_depositor_not_overcharged() public {
    // Depositor deposits proportional amount into existing vault
    uint256 amt0 = ONE_TOKEN0 / 2;
    uint256 amt1 = ONE_TOKEN1 * 50_000;
    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    (uint256 bal0, uint256 bal1) = _getVaultBalances();
    uint256 supply = _getTotalSupply();

    vm.prank(depositor);
    (uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amt0, amt1, 0, 0);

    // After deposit, depositor's pro-rata share of vault should be >= tokens contributed
    // i.e., shares / newTotalSupply >= (dep0/newBal0) approximately
    if (supply > 0 && bal0 > 0 && bal1 > 0 && shares > 0) {
        (uint256 newBal0, uint256 newBal1) = _getVaultBalances();
        uint256 newSupply = _getTotalSupply();
        // Depositor's entitlement based on shares
        uint256 entitlement0 = newBal0 * shares / newSupply;
        uint256 entitlement1 = newBal1 * shares / newSupply;
        // Depositor should get back at least what they put in (minus 1 wei rounding)
        t(entitlement0 + 1 >= dep0, "depositor overcharged token0");
        t(entitlement1 + 1 >= dep1, "depositor overcharged token1");
    }
}

function property_equal_deposits_equal_shares() public {
    // Two deposits of equal value should produce equal shares
    uint256 amt0 = ONE_TOKEN0;          // 1 WBTC
    uint256 amt1 = ONE_TOKEN1 * 100_000; // 100k USDC

    deal(WBTC_ADDR, user, amt0);
    deal(USDC_ADDR, user, amt1);
    vm.prank(user);
    (uint256 shares1,,) = vault.deposit(amt0, amt1, 0, 0);

    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);
    vm.prank(depositor);
    (uint256 shares2,,) = vault.deposit(amt0, amt1, 0, 0);

    // Second depositor's shares should be proportional to first's
    // Specifically: shares2 / shares1 should equal (supply_after / supply_before) approximately
    // Allow 1 wei tolerance for rounding
    uint256 diff = shares1 > shares2 ? shares1 - shares2 : shares2 - shares1;
    t(diff <= 1, "equal deposits produce disproportionate shares");
}

function property_withdraw_not_more_than_pro_rata() public {
    uint256 shares = _getShareBalance(user);
    if (shares == 0) return;

    (uint256 bal0Before, uint256 bal1Before) = _getVaultBalances();
    uint256 supplyBefore = _getTotalSupply();

    // Maximum entitlement using floor division (protocol-correct)
    uint256 maxEntitlement0 = bal0Before * shares / supplyBefore;
    uint256 maxEntitlement1 = bal1Before * shares / supplyBefore;

    vm.prank(user);
    (uint256 got0, uint256 got1) = vault.withdraw(shares, 0, 0);

    // User must not receive more than floor pro-rata
    // Allow 1 wei tolerance for rounding in withdrawPartial path
    t(got0 <= maxEntitlement0 + 1, "withdraw returns more than pro-rata token0");
    t(got1 <= maxEntitlement1 + 1, "withdraw returns more than pro-rata token1");
}

function property_deposit_fee_nonzero_when_set() public {
    uint256 fee = _getDepositFee();
    if (fee == 0) return;

    // Small deposit expected to be below fee threshold
    uint256 smallAmt0 = 999; // 999 satoshi WBTC
    uint256 smallAmt1 = 0;
    deal(WBTC_ADDR, depositor, smallAmt0);

    (uint256 bal0, uint256 bal1) = _getVaultBalances();
    uint256 supply = _getTotalSupply();

    vm.prank(depositor);
    (uint256 shares,,) = vault.deposit(smallAmt0, smallAmt1, 0, 0);

    // If fee > 0, minted shares must be strictly less than raw computed shares
    // Raw shares for single-token path: smallAmt0 * supply / bal0
    if (bal0 > 0 && supply > 0) {
        uint256 rawShares = smallAmt0 * supply / bal0;
        uint256 expectedFee = rawShares * fee / 10_000;
        if (expectedFee == 0) {
            // Fee truncated to zero — this is the bug scenario
            // shares == rawShares (no fee actually applied)
            t(shares < rawShares || rawShares == 0,
              "fee truncates to 0: small deposit pays no fee despite fee being set");
        }
    }
}

function property_deposit_amount_not_exceed_input() public {
    uint256 amt0 = ONE_TOKEN0 * 2;
    uint256 amt1 = ONE_TOKEN1 * 200_000;
    deal(WBTC_ADDR, depositor, amt0);
    deal(USDC_ADDR, depositor, amt1);

    vm.prank(depositor);
    (, uint256 dep0, uint256 dep1) = vault.deposit(amt0, amt1, 0, 0);

    // Actual deposit amounts must not exceed the user's stated maximum inputs
    t(dep0 <= amt0, "deposit took more token0 than requested");
    t(dep1 <= amt1, "deposit took more token1 than requested");
}

function property_orc01_chainlink_freshness_check() public view {
    // There is no way to assert staleness directly in a property test without
    // mocking, but we can document that the pricefeed must always return a
    // fresh price. The following checks that if pricefeed is set, it does not
    // return a suspiciously old answer by verifying the feed's updatedAt.
    // NOTE: this expresses the invariant that SHOULD hold but currently doesn't
    // because the staleness check is commented out.
    address feed = leverager.pricefeed();
    // If pricefeed returns 0, something went wrong
    // We can't call internal functions; test via interface
    t(feed != address(0), "pricefeed must be set");
}

