function property_mm_sig_01_nonce_monotonic() public {
  // Nonce for any address must only increase
  // Ghost: ghost_nonce_before[addr] tracked before permit calls
  address user = address(0xBEEF);
  uint256 nonceBefore = vault.nonces(user);
  // After any state-changing operation:
  uint256 nonceAfter = vault.nonces(user);
  t(nonceAfter >= nonceBefore, "SIG-01: nonce must never decrease");
}

function property_mm_sig_02_nonce_increments_by_one() public {
  address user = address(0xBEEF);
  uint256 nonceBefore = vault.nonces(user);
  // After a SUCCESSFUL permit call for `user`:
  // (in handler: try vault.permit(user, spender, value, deadline, v, r, s))
  uint256 nonceAfter = vault.nonces(user);
  if (nonceAfter != nonceBefore) {
    // If nonce changed, it must have changed by exactly 1
    t(nonceAfter == nonceBefore + 1, "SIG-02: nonce must increment by exactly 1");
  }
}

function property_mm_sig_03_multicall_permit_reverts_if_nonce_used() public {
  // After permit is called for a user, a subsequent permit with the
  // same nonce must revert — this tests the griefing precondition
  address user = address(0xBEEF);
  uint256 nonce = vault.nonces(user);
  // If permit was already successfully called consuming `nonce`,
  // then nonces(user) > nonce
  // A multicall bundling permit would fail if nonce already consumed
  t(vault.nonces(user) >= nonce, "SIG-03: nonce state consistent");
}

function property_mm_sig_04_domain_separator_includes_chain() public view {
  // Domain separator must change if chainId changes
  // In Foundry we can't easily fork-switch, but we verify the domain
  // separator is non-zero and consistent
  bytes32 ds = vault.DOMAIN_SEPARATOR();
  t(ds != bytes32(0), "SIG-04: domain separator must be non-zero");
}

function property_mm_sig_05_permit_sets_exact_allowance() public {
  // After permit(owner, spender, value, ...), allowance == value
  // Ghost: ghost_last_permit_value[owner][spender]
  address owner_ = address(0xBEEF);
  address spender_ = address(0xCAFE);
  uint256 allowanceNow = vault.allowance(owner_, spender_);
  // If permit was just called successfully:
  // t(allowanceNow == ghost_last_permit_value[owner_][spender_],
  //   "SIG-05: allowance must match permitted value");
  t(true, "SIG-05: placeholder — needs handler integration");
}

function property_mm_sig_06_expired_deadline_reverts() public {
  // A permit with deadline < block.timestamp must always revert
  // This is enforced by OZ ERC20Permit — no need to test in invariant
  // but we verify nonce is NOT consumed on revert
  address user = address(0xBEEF);
  uint256 nonceBefore = vault.nonces(user);
  // After a REVERTED permit call (expired deadline):
  uint256 nonceAfter = vault.nonces(user);
  t(nonceAfter == nonceBefore, "SIG-06: failed permit must not consume nonce");
}

function property_mm_sig_07_withdraw_spends_share_allowance() public {
  // After withdraw(assets, receiver, owner) by caller != owner:
  // allowance(owner, caller) must decrease by exactly shares burned
  address owner_ = address(0xBEEF);
  address caller_ = address(0xCAFE);
  uint256 allowanceBefore = vault.allowance(owner_, caller_);
  // Ghost: ghost_shares_burned tracks shares from last _withdraw
  // t(vault.allowance(owner_, caller_) == allowanceBefore - ghost_shares_burned,
  //   "SIG-07: allowance must decrease by shares burned");
  t(true, "SIG-07: placeholder — needs handler integration");
