function property_mm_sig_08_no_malleable_signatures() public view {
  // OZ ECDSA enforces s <= secp256k1n/2
  // This is enforced at the library level, not at MetaMorpho level
  // No runtime invariant needed — it's a constant property of ECDSA.recover
  // Documenting for completeness
}

function property_mm_sig_09_no_permit_for_zero_address() public view {
  // address(0) should have 0 allowance to any address at all times
