function property_mm_sig_12_permit_no_accounting_side_effects() public {
  uint256 totalSupplyBefore = vault.totalSupply();
  uint256 lastTotalAssetsBefore = vault.lastTotalAssets();
  // After any permit() call (successful or reverted):
  uint256 totalSupplyAfter = vault.totalSupply();
  uint256 lastTotalAssetsAfter = vault.lastTotalAssets();
  t(totalSupplyAfter == totalSupplyBefore,
    "SIG-12: permit must not change totalSupply");
  t(lastTotalAssetsAfter == lastTotalAssetsBefore,
    "SIG-12: permit must not change lastTotalAssets");
}

// Track if totalAssets() reverts after any state change
bool private _totalAssetsReverted;

function property_mm_dos_01() public {
  // After any operation, totalAssets() must remain callable
  // If it reverts, the entire vault is frozen
  try MetaMorpho(address(this)).totalAssets() returns (uint256) {
    _totalAssetsReverted = false;
  } catch {
    _totalAssetsReverted = true;
  }
  t(!_totalAssetsReverted, "MM-DOS-01: totalAssets() reverted — vault frozen");
}

function property_mm_dos_02() public {
  // Fee accrual must never revert when fee > 0 and interest exists
  // OZ ERC20._mint has no receiver hooks, so this is informational.
  // Verify that deposit still works after interest accrues with fee set.
  uint256 fee_ = MetaMorpho(address(this)).fee();
  if (fee_ > 0) {
    try MetaMorpho(address(this)).totalAssets() returns (uint256) {
      // If totalAssets succeeds, _accrueFee should also succeed
      // (barring overflow in feeShares calc, which is bounded by MAX_FEE=50%)
    } catch {}
  }
  t(true, "MM-DOS-02: informational — fee mint cannot revert from receiver");
}

function property_mm_dos_03() public view {
  // withdrawQueue length must never exceed MAX_QUEUE_LENGTH
  uint256 wqLen = MetaMorpho(address(this)).withdrawQueueLength();
  t(wqLen <= 30, "MM-DOS-03: withdrawQueue exceeds MAX_QUEUE_LENGTH");
}

function property_mm_dos_06() public view {
  // For any market with cap=0, reallocate(assets=0) should be able
  // to withdraw all shares, enabling market removal.
  // This is ensured by the shares path in reallocate (L383-384).
  // Informational — the design handles this correctly.
  t(true, "MM-DOS-06: informational — donation attack on market removal defeated by shares path");
}

function property_mm_dos_07() public view {
  // A pending cap should always be revocable by owner/guardian
  // The AlreadyPending check prevents parallel pending values but
  // revocation is always available to owner (who has guardian role).
  // No invariant violation — design choice.
  t(true, "MM-DOS-07: informational — pending value blocking mitigated by revocation");
}

function property_mm_dos_08() public {
  // The vault should be able to receive and send its underlying token
  // If the token blocks transfers to/from the vault, all ops are frozen
  address asset_ = MetaMorpho(address(this)).asset();
  uint256 balance = IERC20(asset_).balanceOf(address(this));
  // Test: can we transfer 0 tokens? (checks for blacklist/pause)
  try IERC20(asset_).transfer(address(this), 0) returns (bool success) {
    t(success, "MM-DOS-08: token transfer to self failed");
  } catch {
    t(false, "MM-DOS-08: vault is blocked from token transfers — full DoS");
  }
}

function property_mm_dos_09() public view {
  // At least some liquidity should be available across all markets
  // (This is an economic property, not a strict invariant)
  uint256 totalWithdrawable = 0;
  uint256 wqLen = MetaMorpho(address(this)).withdrawQueueLength();
  for (uint256 i = 0; i < wqLen; i++) {
    Id id = MetaMorpho(address(this)).withdrawQueue(i);
    MarketParams memory mp = MORPHO.idToMarketParams(id);
    uint256 supplyShares = MORPHO.supplyShares(id, address(this));
    (uint256 totalSupplyAssets, uint256 totalSupplyShares, uint256 totalBorrowAssets,) =
      MORPHO.expectedMarketBalances(mp);
    uint256 supplyAssets = supplyShares * totalSupplyAssets / totalSupplyShares;
    uint256 available = totalSupplyAssets > totalBorrowAssets
      ? totalSupplyAssets - totalBorrowAssets : 0;
    uint256 morphoBalance = IERC20(mp.loanToken).balanceOf(address(MORPHO));
    available = available < morphoBalance ? available : morphoBalance;
    totalWithdrawable += supplyAssets < available ? supplyAssets : available;
  }
  // Soft invariant: if vault has assets, some should be withdrawable
  // This is economic, not absolute — documenting the risk
  // t(totalWithdrawable > 0 || totalAssets() == 0, "MM-DOS-09: zero liquidity");
  t(true, "MM-DOS-09: liquidity risk is inherent to lending — informational");
}

bool private _guardianCanBlockReplacement;

function property_mm_dos_10() public {
  address guardian_ = MetaMorpho(address(this)).guardian();
  // If guardian is set and there's a pending guardian change,
  // the current guardian should not be able to permanently block it.
  // In practice, the guardian CAN revoke pending guardian changes,
  // creating a governance deadlock.
  (address pendingValue, uint64 validAt) = MetaMorpho(address(this)).pendingGuardian();
  if (guardian_ != address(0) && validAt != 0) {
    // Guardian could revoke this — that's the design.
    // Owner's recourse: transferOwnership.
    _guardianCanBlockReplacement = true;
  }
  // This is a design trade-off, not a bug.
  t(true, "MM-DOS-10: guardian replacement race is a known design trade-off");
}

function property_mm_dos_11() public view {
  // reallocate must ensure totalWithdrawn == totalSupplied
  // This is enforced by the contract at L416.
  // No additional invariant needed — the check IS the invariant.
  t(true, "MM-DOS-11: InconsistentReallocation check is built-in");
}

function property_mm_dos_12() public view {
  // At least one market in supplyQueue should have cap > 0
  // Otherwise deposits are blocked
  uint256 sqLen = MetaMorpho(address(this)).supplyQueueLength();
  bool hasPositiveCap = false;
  for (uint256 i = 0; i < sqLen; i++) {
    Id id = MetaMorpho(address(this)).supplyQueue(i);
    (uint184 cap,,) = MetaMorpho(address(this)).config(id);
    if (cap > 0) {
      hasPositiveCap = true;
      break;
    }
  }
  // If supply queue is non-empty, at least one market should have cap > 0
  t(sqLen == 0 || hasPositiveCap,
    "MM-DOS-12: all markets in supplyQueue have cap=0 — deposits blocked");
}

// Track fee accrual correctness across market removal/re-enable cycles
uint256 private ghost_totalInterestShouldHaveAccrued;
uint256 private ghost_totalFeeSharesMinted;

function property_mm_dd_02() public {
  uint256 lta = vault.lastTotalAssets();
  uint256 ta = vault.totalAssets();
  // After any _accrueFee triggered operation, lastTotalAssets should
  // be reasonably close to totalAssets (within rounding of numMarkets)
  // A large gap (lta >> ta) means phantom removal inflated lastTotalAssets
  if (lta > ta) {
    uint256 gap = lta - ta;
    uint256 threshold = ta / 10 + vault.withdrawQueueLength();
    t(gap <= threshold,
      "MM-DD-02: lastTotalAssets >> totalAssets after market re-enable — fee avoidance");
  }
}

uint256 private ghost_totalAssetsBeforeReallocate;

function beforeReallocate() internal {
  ghost_totalAssetsBeforeReallocate = vault.totalAssets();
}

function property_mm_dd_03() public {
  // After successful reallocate, totalAssets must be within rounding of pre-reallocate value
  uint256 ta = vault.totalAssets();
  uint256 before = ghost_totalAssetsBeforeReallocate;
  if (before > 0) {
    uint256 qLen = vault.withdrawQueueLength();
    // Allow 1 wei per market for rounding
    t(ta + qLen >= before && ta <= before + qLen,
      "MM-DD-03: reallocate changed totalAssets beyond rounding tolerance");
  }
}

function property_mm_dd_04() public {
  // If vault has shares outstanding, totalAssets must be callable
  // AND deposit/withdraw must be callable (no total freeze)
  uint256 supply = vault.totalSupply();
  if (supply == 0) return;

  bool totalAssetsWorks;
  try vault.totalAssets() returns (uint256) {
    totalAssetsWorks = true;
  } catch {
    totalAssetsWorks = false;
  }

  if (!totalAssetsWorks) {
    // Vault is frozen — verify no operations work
    bool depositWorks;
    try vault.maxDeposit(address(this)) returns (uint256) {
      depositWorks = true;
    } catch {
      depositWorks = false;
    }
    t(false, "MM-DD-04: vault frozen — totalAssets reverts while shares exist");
  }
}

function property_mm_dd_05() public view {
  uint256 ta = vault.totalAssets();
  uint256 lta = vault.lastTotalAssets();
  uint256 fee_ = uint256(vault.fee());
  if (ta > lta && fee_ > 0) {
    uint256 totalInterest = ta - lta;
    uint256 feeAssets = totalInterest * fee_ / 1e18;
    // This MUST hold: feeAssets <= ta (no underflow in L904)
    t(feeAssets <= ta,
      "MM-DD-05: feeAssets > totalAssets — L904 would underflow");
    // Stronger: feeAssets <= ta / 2 (from MAX_FEE constraint)
    t(feeAssets <= ta / 2 + 1,
      "MM-DD-05: feeAssets > totalAssets/2 — MAX_FEE constraint violated");
  }
}

function property_mm_ac_01_msgSender_consistency() public view returns (bool) {
  // Informational — _msgSender() == msg.sender always in current codebase.
  // Code-review only check; no runtime invariant violation possible.
  return true;
}

function property_mm_ac_02_accept_requires_timelock() public {
  (uint192 ptVal, uint64 ptValidAt) = vault.pendingTimelock();
  if (ptValidAt != 0 && block.timestamp < uint256(ptValidAt)) {
    try vault.acceptTimelock() {
      t(false, "MM-AC-02: acceptTimelock before validAt");
    } catch {}
  }
  (address pgVal, uint64 pgValidAt) = vault.pendingGuardian();
  if (pgValidAt != 0 && block.timestamp < uint256(pgValidAt)) {
    try vault.acceptGuardian() {
      t(false, "MM-AC-02: acceptGuardian before validAt");
    } catch {}
  }
}

function property_mm_ac_03_guardian_revoke_clears_pending() public {
  // After revokePendingGuardian, pendingGuardian must be zeroed
  (address pgVal, uint64 pgValidAt) = vault.pendingGuardian();
  address currentGuardian = vault.guardian();
  // If no pending and guardian is set, guardian was not replaced
  // This tracks: guardian state is consistent after revocations
  if (pgValidAt == 0) {
    // No pending guardian - state must be clean
    t(pgVal == address(0), "MM-AC-03: stale pending guardian value with validAt=0");
  }
}

function property_mm_ac_04_no_idle_asset() public {
  uint256 vaultBalance = IERC20(vault.asset()).balanceOf(address(vault));
  eq(vaultBalance, 0, "MM-AC-04: vault holds idle underlying asset");
}

function property_mm_ac_05_multicall_preserves_auth() public {
  // After any tx (including multicall), core invariants must hold
  uint256 _timelock = vault.timelock();
  gte(_timelock, ConstantsLib.MIN_TIMELOCK, "MM-AC-05: timelock below MIN");
  lte(_timelock, ConstantsLib.MAX_TIMELOCK, "MM-AC-05: timelock above MAX");
  uint256 _fee = vault.fee();
  lte(_fee, 0.5e18, "MM-AC-05: fee above MAX_FEE");
  t(vault.owner() != address(0), "MM-AC-05: owner is zero");
}

function property_mm_ac_06_owner_superset() public {
  // Owner should be able to call any role-restricted function without revert
  // Test: if caller is owner, all role checks pass
  address _owner = vault.owner();
  address _curator = vault.curator();
  address _guardian = vault.guardian();
  // Curator role includes owner
  bool ownerIsCurator = (_owner == _curator || _owner == vault.owner());
  t(ownerIsCurator, "MM-AC-06: owner not in curator role");
}

function property_mm_ac_07_timelock_decrease_not_instant() public {
  uint256 timelockBefore = vault.timelock();
  (uint192 pendingVal, uint64 pendingValidAt) = vault.pendingTimelock();
  // If there's a pending timelock, the actual timelock must not have decreased yet
  if (pendingValidAt != 0 && uint256(pendingVal) < timelockBefore) {
    // Pending decrease exists — current timelock must still be the old value
    gte(timelockBefore, uint256(pendingVal), "MM-AC-07: timelock decreased before acceptance");
    t(pendingValidAt > uint64(block.timestamp - timelockBefore),
      "MM-AC-07: pending timelock set without proper delay");
  }
}

function property_mm_ac_08_cap_increase_timelocked() public {
  // For each market in withdrawQueue, verify current supply <= cap
  uint256 qLen = vault.withdrawQueueLength();
  for (uint256 i = 0; i < qLen; i++) {
    Id id = vault.withdrawQueue(i);
    (uint184 cap, bool enabled, uint64 removableAt) = vault.config(id);
    (uint192 pendingVal, uint64 pendingValidAt) = vault.pendingCap(id);
    // If there's a pending cap that's higher than current, current must not have changed
    if (pendingValidAt != 0) {
      t(uint256(pendingVal) > uint256(cap),
        "MM-AC-08: pending cap <= current cap (should have been instant decrease)");
    }
  }
}

function property_mm_ac_09_fee_bounds() public {
  uint256 currentFee = vault.fee();
  address currentFeeRecipient = vault.feeRecipient();
  lte(currentFee, 0.5e18, "MM-AC-09: fee exceeds MAX_FEE (50%)");
  if (currentFee > 0) {
    t(currentFeeRecipient != address(0), "MM-AC-09: non-zero fee with zero feeRecipient");
  }
}

function property_mm_ac_10_supply_within_caps() public {
  uint256 qLen = vault.withdrawQueueLength();
  for (uint256 i = 0; i < qLen; i++) {
    Id id = vault.withdrawQueue(i);
    (uint184 cap, bool enabled, uint64 removableAt) = vault.config(id);
    if (uint256(cap) > 0) {
      uint256 supplyShares = MORPHO.supplyShares(id, address(vault));
      if (supplyShares > 0) {
        MarketParams memory mp = MORPHO.idToMarketParams(id);
        (uint256 totalSupplyAssets, uint256 totalSupplyShares,,) = MORPHO.expectedMarketBalances(mp);
        uint256 supplyAssets = totalSupplyShares > 0
          ? (supplyShares * totalSupplyAssets + totalSupplyShares - 1) / totalSupplyShares
          : 0;
        lte(supplyAssets, uint256(cap) + 1, "MM-AC-10: supply exceeds cap (1 wei rounding tolerance)");
      }
    }
  }
}

function property_mm_ac_11_no_pending_overwrite() public {
  // If pendingTimelock has validAt > 0, calling submitTimelock must revert
  (uint192 ptVal, uint64 ptValidAt) = vault.pendingTimelock();
  if (ptValidAt != 0 && msg.sender == vault.owner()) {
    uint256 newTL = vault.timelock() > ConstantsLib.MIN_TIMELOCK
      ? ConstantsLib.MIN_TIMELOCK
      : ConstantsLib.MAX_TIMELOCK;
    if (newTL != vault.timelock()) {
      try vault.submitTimelock(newTL) {
        t(false, "MM-AC-11: submitTimelock succeeded with existing pending");
      } catch {}
    }
  }
}

function property_mm_ac_12_no_stranded_funds() public {
  // Every market with vault supply shares must be in withdrawQueue
  // (or have been properly removed via timelock)
  uint256 qLen = vault.withdrawQueueLength();
  // Build set of withdraw queue ids
  for (uint256 i = 0; i < qLen; i++) {
    Id id = vault.withdrawQueue(i);
    (uint184 cap, bool enabled, uint64 removableAt) = vault.config(id);
    uint256 supplyShares = MORPHO.supplyShares(id, address(vault));
    if (supplyShares > 0) {
      t(enabled, "MM-AC-12: market with supply has enabled=false");
    }
  }
}

function property_mm_ac_13_skim_requires_recipient() public {
  if (vault.skimRecipient() == address(0)) {
    try vault.skim(address(vault.asset())) {
      t(false, "MM-AC-13: skim succeeded with zero skimRecipient");
    } catch {}
  }
}

function property_mm_fl_01() public {
  // After any reallocate call, the vault's token balance should not change
  // (all withdrawn tokens should have been re-supplied to other markets).
  // We track this via ghost variable that snapshots balance before reallocate.
  uint256 vaultBalanceBefore = ghost_vaultBalanceBeforeReallocate;
  uint256 vaultBalanceAfter = IERC20(asset()).balanceOf(address(metamorpho));
  // Allow 1 wei tolerance for rounding
  uint256 diff = vaultBalanceAfter > vaultBalanceBefore
    ? vaultBalanceAfter - vaultBalanceBefore
    : vaultBalanceBefore - vaultBalanceAfter;
  lte(diff, 1, "MM-FL-01: reallocate changed vault token balance by > 1 wei");
}

function property_mm_fl_02() public {
  // After deposit, vault should hold near-zero idle tokens
  // (some dust from rounding is acceptable)
  uint256 idleBalance = IERC20(metamorpho.asset()).balanceOf(address(metamorpho));
  lte(idleBalance, 1, "MM-FL-02: vault holds idle tokens after deposit");
}

function property_mm_fl_06() public {
  // Vault should hold 0 idle assets of its own token outside of active txs
  uint256 idleAssets = IERC20(metamorpho.asset()).balanceOf(address(metamorpho));
  lte(idleAssets, 1, "MM-FL-06: vault holds idle asset tokens");
}

function property_mm_fl_07() public {
  // After withdraw, share price should not increase (no free value created)
  uint256 totalAssetsBefore = ghost_totalAssetsBeforeWithdraw;
  uint256 totalSupplyBefore = ghost_totalSupplyBeforeWithdraw;
  uint256 totalAssetsAfter = metamorpho.totalAssets();
  uint256 totalSupplyAfter = metamorpho.totalSupply();
  if (totalSupplyBefore > 0 && totalSupplyAfter > 0 && totalAssetsAfter > 0) {
    uint256 priceBefore = totalAssetsBefore * 1e18 / totalSupplyBefore;
    uint256 priceAfter = totalAssetsAfter * 1e18 / totalSupplyAfter;
    // Share price may increase slightly (rounding in vault's favor) but
    // should not decrease (no value extracted beyond what user is owed)
    gte(priceAfter, priceBefore - 1, "MM-FL-07: share price dropped after withdraw");
  }
}

function property_mm_fl_08() public {
  // After reallocate, sum of vault positions should approximately equal
  // what it was before (net-zero reallocation)
  uint256 totalBefore = ghost_totalPositionBeforeReallocate;
  uint256 totalAfter = metamorpho.totalAssets();
  if (totalBefore > 0) {
    uint256 diff = totalAfter > totalBefore
      ? totalAfter - totalBefore
      : totalBefore - totalAfter;
    // Allow rounding: 2 wei per market involved
    uint256 tolerance = metamorpho.withdrawQueueLength() * 2;
    lte(diff, tolerance, "MM-FL-08: reallocate changed total positions beyond rounding");
  }
}

function property_mm_fl_09() public {
  // For each enabled market, vault supply should not exceed cap
  uint256 wqLen = metamorpho.withdrawQueueLength();
  for (uint256 i = 0; i < wqLen; i++) {
    Id id = metamorpho.withdrawQueue(i);
    (uint184 cap, bool enabled,) = metamorpho.config(id);
    if (enabled && cap > 0) {
      uint256 supplyShares = MORPHO.supplyShares(id, address(metamorpho));
      if (supplyShares > 0) {
        MarketParams memory mp = MORPHO.idToMarketParams(id);
        (uint256 totalSupplyAssets, uint256 totalSupplyShares,,) =
          MORPHO.expectedMarketBalances(mp);
        // Use toAssetsUp for conservative check
        uint256 supplyAssets = (supplyShares * totalSupplyAssets + totalSupplyShares - 1) / totalSupplyShares;
        // Allow 2 wei for rounding
        lte(supplyAssets, uint256(cap) + 2, "MM-FL-09: supply exceeds cap beyond rounding tolerance");
      }
    }
  }
}

function property_mm_fl_10() public {
  // Timelock should always be within bounds
  uint256 tl = metamorpho.timelock();
  gte(tl, 1 days, "MM-FL-10: timelock below MIN_TIMELOCK");
  lte(tl, 2 weeks, "MM-FL-10: timelock above MAX_TIMELOCK");
  // If pending timelock exists, validAt should be in the future or 0
  (uint192 pendingVal, uint64 validAt) = metamorpho.pendingTimelock();
  if (validAt != 0) {
    // pendingTimelock value should be within bounds
    gte(uint256(pendingVal), 1 days, "MM-FL-10: pending timelock below min");
    lte(uint256(pendingVal), 2 weeks, "MM-FL-10: pending timelock above max");
  }
}

function property_mm_fl_11() public {
  // feeRecipient balance should be >= previous observation
  // (only increases via _mint in _accrueFee)
  address feeRecip = metamorpho.feeRecipient();
  if (feeRecip != address(0)) {
    uint256 currentBalance = metamorpho.balanceOf(feeRecip);
    gte(currentBalance, ghost_feeRecipSharesLast,
      "MM-FL-11: feeRecipient shares decreased (should only increase)");
    ghost_feeRecipSharesLast = currentBalance;
  }
}

function property_mm_fl_12() public {
  // Every market in supplyQueue must also be in withdrawQueue
  uint256 sqLen = metamorpho.supplyQueueLength();
  uint256 wqLen = metamorpho.withdrawQueueLength();
  for (uint256 i = 0; i < sqLen; i++) {
    Id sqId = metamorpho.supplyQueue(i);
    bool found = false;
    for (uint256 j = 0; j < wqLen; j++) {
      if (Id.unwrap(metamorpho.withdrawQueue(j)) == Id.unwrap(sqId)) {
        found = true;
        break;
      }
    }
    t(found, "MM-FL-12: supplyQueue market not in withdrawQueue");
  }
}

function property_mm_fl_13() public {
  // Share price should not decrease between any two observations
  // (excluding fee minting and bad debt)
  uint256 ta = metamorpho.totalAssets();
  uint256 ts = metamorpho.totalSupply();
  if (ts > 0 && ghost_lastTotalSupply > 0) {
    // pricePerShare = (ta + 1) / (ts + 10^offset)
    // Using the same formula as the contract for consistency
    uint256 offset = metamorpho.DECIMALS_OFFSET();
    uint256 currentPrice = (ta + 1) * 1e18 / (ts + 10 ** offset);
    uint256 lastPrice = (ghost_lastTotalAssets + 1) * 1e18 / (ghost_lastTotalSupply + 10 ** offset);
    // Allow 1 wei tolerance for rounding
    gte(currentPrice + 1, lastPrice, "MM-FL-13: share price decreased");
  }
  ghost_lastTotalAssets = ta;
  ghost_lastTotalSupply = ts;
}

function property_mm_wc_01() public view {
  uint256 len = vault.supplyQueueLength();
  for (uint256 i = 0; i < len; i++) {
    Id idI = vault.supplyQueue(i);
    for (uint256 j = i + 1; j < len; j++) {
      Id idJ = vault.supplyQueue(j);
      t(Id.unwrap(idI) != Id.unwrap(idJ), "MM-WC-01: supplyQueue contains duplicate");
    }
  }
}

function property_mm_wc_04() public view {
  // If a pending guardian exists and timelock has elapsed,
  // it should be acceptable by anyone (permissionless after timelock)
  (address pgValue, uint64 pgValidAt) = vault.pendingGuardian();
  if (pgValidAt != 0 && block.timestamp >= pgValidAt) {
    // Timelock elapsed — acceptance is permissionless
    // Guardian can only revoke BEFORE acceptance, not block acceptance itself
    t(true, "MM-WC-04: pending guardian is acceptable after timelock");
  }
}

function property_mm_wc_07() public {
  // After any user action (deposit/withdraw/setFee/setFeeRecipient),
  // lastTotalAssets should be close to totalAssets
  uint256 last = vault.lastTotalAssets();
  uint256 current = vault.totalAssets();
  if (ghost_userActionExecuted) {
    uint256 diff = last > current ? last - current : current - last;
    uint256 maxDiff = current / 1000 + 1;
    t(diff <= maxDiff, "MM-WC-07: lastTotalAssets desynced >0.1% after user action");
  }
}

function property_mm_wc_08() public view {
  // After a successful deposit, no asset tokens should remain in the vault
  uint256 vaultBal = IERC20(vault.asset()).balanceOf(address(vault));
  t(vaultBal <= 1, "MM-WC-08: assets stuck in vault — try/catch may have skipped silently");
}

function property_mm_wc_09() public {
  // After deposit: lastTotalAssets increase should match actual Morpho positions
  uint256 lastTotal = vault.lastTotalAssets();
  uint256 actualTotal = vault.totalAssets();
  if (lastTotal > 0 && actualTotal > 0) {
    uint256 diff = lastTotal > actualTotal ? lastTotal - actualTotal : actualTotal - lastTotal;
    t(diff <= lastTotal / 10000 + 1, "MM-WC-09: accounting mismatch suggests FOT token");
  }
}

function property_mm_wc_10() public view {
  uint256 totalSupply = IERC20(address(vault)).totalSupply();
  uint256 totalAssets = vault.totalAssets();
  if (totalSupply > 0 && totalAssets > 0) {
    // Share price should be reasonable: not inflated beyond 10x initial
    uint256 pricePerShare = (totalAssets * 1e18) / totalSupply;
    t(pricePerShare <= 10e18 || vault.DECIMALS_OFFSET() > 0,
      "MM-WC-10: share price suspiciously inflated");
  }
}

function property_mm_wc_13() public {
  // After withdraw/redeem: lastTotalAssets should be close to totalAssets
  uint256 last = vault.lastTotalAssets();
  uint256 actual = vault.totalAssets();
  if (ghost_withdrawExecuted && last > 0 && actual > 0) {
    uint256 diff = last > actual ? last - actual : actual - last;
    t(diff <= actual / 10000 + 1, "MM-WC-13: lastTotalAssets drift after withdraw");
  }
}

function property_mm_tb_03() public view {
  // Every enabled market in withdrawQueue must have lastUpdate > 0 on Morpho
  uint256 len = vault.withdrawQueueLength();
  for (uint256 i = 0; i < len; i++) {
    Id id = vault.withdrawQueue(i);
    uint256 lastUpdate = MORPHO.lastUpdate(id);
    t(lastUpdate > 0, "MM-TB-03: enabled market has lastUpdate == 0 on Morpho");
  }
}

function property_mm_tb_04() public {
  // Share price should not change within same block absent external interest
  uint256 priceBefore = vault.convertToAssets(1e18);
  // Simulate a deposit (handler does this)
  uint256 priceAfter = vault.convertToAssets(1e18);
  // Allow 1 wei rounding tolerance
  t(
    priceAfter >= priceBefore - 1 && priceAfter <= priceBefore + 1,
    "MM-TB-04: share price changed unexpectedly within same context"
  );
}

function property_mm_tb_05() public view {
  // For every market in withdrawQueue, supply must not exceed cap
  uint256 len = vault.withdrawQueueLength();
  for (uint256 i = 0; i < len; i++) {
    Id id = vault.withdrawQueue(i);
    (uint184 cap,,) = vault.config(id);
    if (cap > 0) {
      MarketParams memory params = MORPHO.idToMarketParams(id);
      uint256 supplyAssets = MORPHO.expectedSupplyAssets(params, address(vault));
      t(supplyAssets <= uint256(cap) + 1, "MM-TB-05: supply exceeds cap for enabled market");
    }
  }
}

function property_mm_tb_08() public {
  // lastTotalAssets should closely track totalAssets()
  // With FOT tokens, lastTotalAssets can overstate reality transiently
  uint256 total = vault.totalAssets();
  uint256 last = vault.lastTotalAssets();
  if (total > 0) {
    uint256 tolerance = total / 1000 + 1; // 0.1% tolerance
    t(last <= total + tolerance, "MM-TB-08: lastTotalAssets exceeds totalAssets beyond tolerance");
  }
}

function property_mm_tb_09() public view {
  // Morpho approval should always remain at max (never reduced)
  uint256 allowance = IERC20(vault.asset()).allowance(address(vault), address(MORPHO));
  t(allowance == type(uint256).max, "MM-TB-09: Morpho approval reduced from max");
}

