// Invariant: remoteAmount * scalar must not overflow uint256
// For safe operation, scalarExponent should be <= 57
function invariant_scalar_no_overflow(uint64 remoteAmount, uint8 scalarExponent) external pure {
    if (scalarExponent > 77) return; // would revert at registration
    uint256 scalar = 10 ** uint256(scalarExponent);
    // This should not overflow for practical scalarExponent values
    if (scalarExponent <= 57) {
        uint256 result = uint256(remoteAmount) * scalar;
        assert(result / scalar == remoteAmount); // no overflow
    }
}

// Invariant: deposits are always exact multiples of scalar
// deposits[localToken][remoteToken] % scalars[localToken][remoteToken] == 0
function invariant_deposits_exact_multiple(address localToken, bytes32 remoteToken) external view {
    uint256 deposits = tokenLibStorage.deposits[localToken][remoteToken];
    uint256 scalar = tokenLibStorage.scalars[localToken][remoteToken];
    if (scalar > 0) {
        assert(deposits % scalar == 0);
    }
}

// Invariant: dust is always less than scalar and is refunded
function invariant_dust_less_than_scalar(uint256 receivedLocalAmount, uint256 scalar) external pure {
    require(scalar > 0);
    uint256 receivedRemoteAmount = receivedLocalAmount / scalar;
    uint256 localAmount = receivedRemoteAmount * scalar;
    uint256 dust = receivedLocalAmount - localAmount;
    assert(dust < scalar);
    assert(localAmount + dust == receivedLocalAmount);
}

// Invariant: finalize never pays more than deposited
// (enforced by Solidity checked arithmetic on subtraction)
function invariant_deposits_never_negative(
    address localToken, bytes32 remoteToken, uint64 remoteAmount
) external view {
    uint256 scalar = tokenLibStorage.scalars[localToken][remoteToken];
    uint256 localAmount = uint256(remoteAmount) * scalar;
    uint256 currentDeposits = tokenLibStorage.deposits[localToken][remoteToken];
    // If localAmount > currentDeposits, the real code reverts.
    // This invariant documents that behavior.
    assert(currentDeposits >= localAmount); // must hold for successful finalize
}

// Invariant: nonce is monotonically increasing (until wrap)
// In practice, nonce < 2^63 for the lifetime of the bridge
function invariant_nonce_not_wrapped(uint64 nextNonce) external pure {
    // If nonce reaches a dangerously high value, something is wrong
    assert(nextNonce < type(uint64).max - 1e15); // 1 quadrillion safety margin
}

// Invariant: tree size is always 2^(h+1) - 1
function invariant_tree_size_correct(uint256 height) external pure {
    require(height < 64); // bounded by uint64 leaf count
    uint256 treeSize = (1 << (height + 1)) - 1;
    assert(treeSize == 2 ** (height + 1) - 1);
    // Verify node count: leaves = 2^h, internals = 2^h - 1, total = 2^(h+1) - 1
    uint256 leaves = 1 << height;
    uint256 internals = leaves - 1;
    assert(treeSize == leaves + internals);
}

// Invariant: localNodePos formula is correct for first few cases
function invariant_mmr_leaf_position() external pure {
    // Leaf 0: node 0
    assert(2 * 0 - _popcount(0) == 0);
    // Leaf 1: node 1
    assert(2 * 1 - _popcount(1) == 1);
    // Leaf 2: node 3
    assert(2 * 2 - _popcount(2) == 3);
    // Leaf 3: node 4
    assert(2 * 3 - _popcount(3) == 4);
    // Leaf 4: node 7
    assert(2 * 4 - _popcount(4) == 7);
}

// Invariant: receivedRemoteAmount always fits in uint64 given deposit cap
function invariant_remote_amount_fits_uint64(uint256 receivedLocalAmount, uint256 scalar) external pure {
    require(scalar > 0);
    uint256 receivedRemoteAmount = receivedLocalAmount / scalar;
    // If cumulative deposits / scalar <= type(uint64).max, then individual
    // receivedRemoteAmount <= type(uint64).max
    if (receivedLocalAmount / scalar <= type(uint64).max) {
        assert(receivedRemoteAmount <= type(uint64).max);
    }
}

// Invariant: left sibling index is always valid (< nodes.length)
// This is structural — tested via MMR append correctness
function invariant_left_sibling_valid(uint256 currentNodeIndex, uint256 height) external pure {
    require(height < 64);
    uint256 leftSubtreeSize = (1 << (height + 1)) - 1;
    // In valid MMR construction, currentNodeIndex >= leftSubtreeSize
    if (currentNodeIndex >= leftSubtreeSize) {
        uint256 leftSiblingIndex = currentNodeIndex - leftSubtreeSize;
        assert(leftSiblingIndex < currentNodeIndex); // always true
    }
}

