// Invariant: total minted in any interval-length window <= maxAllowances
// Test: configure caller, wait, mint max, immediately mint max again
function crytic_rate_limit_holds() public returns (bool) {
    uint256 mintedInWindow = totalMintedSince[caller][windowStart];
    return mintedInWindow <= maxAllowances[caller];
}

// Invariant: replenishment should be proportional to elapsed time
function crytic_replenish_proportional() public returns (bool) {
    uint256 before = allowances[caller];
    uint256 timeBefore = block.timestamp;
    _replenishAllowance(caller);
    uint256 after_val = allowances[caller];
    uint256 elapsed = block.timestamp - timeBefore;
    uint256 expected = (elapsed * maxAllowances[caller]) / intervals[caller];
    return (after_val - before) <= expected + 1; // +1 for rounding
}

// Invariant: sum of mints per caller per interval <= maxAllowance
function crytic_atomic_rate_limit() public returns (bool) {
    uint256 balBefore = token.balanceOf(recipient);
    // Call mint twice atomically
    mintForwarder.mint(recipient, maxAllowances[caller]);
    mintForwarder.mint(recipient, maxAllowances[caller]);
    uint256 balAfter = token.balanceOf(recipient);
    return (balAfter - balBefore) <= maxAllowances[caller]; // SHOULD hold, WILL fail
}

