    lte(currentTotalAssets, maxGrowth + 1,
      "OR-01: totalAssets grew faster than maxRate allows");
  }
  ghost_lastTotalAssets = currentTotalAssets;
  ghost_lastTotalSupply = currentTotalSupply;
