function check_VV2_DOM_04_stale_rate_within_tx() public {
  // After accrueInterest, firstTotalAssets is set
  uint256 fta = vault.firstTotalAssets();
  uint256 ta = vault._totalAssets();
  if (fta != 0) {
    // Any subsequent deposit/withdraw uses _totalAssets not realAssets
    // Check that _totalAssets still reflects reality
    uint256 realTotal = IERC20(vault.asset()).balanceOf(address(vault));
    // Add adapter balances...
    // If realTotal significantly differs from ta, pricing is stale
    t(realTotal >= ta * 95 / 100 && realTotal <= ta * 105 / 100,
      "VV2-DOM-04: stale pricing within tx, >5% deviation");
  }
}

