function check_VV2_DOM_08_fee_on_capped_interest() public {
  uint256 ta = vault._totalAssets();
  uint256 lastUpd = vault.lastUpdate();
  uint256 elapsed = block.timestamp - lastUpd;
  uint256 maxRateVal = vault.maxRate();
  if (ta > 0 && elapsed > 0 && maxRateVal > 0) {
    uint256 maxTotalAssets = ta + (ta * elapsed * maxRateVal) / 1e18;
    uint256 realAssets = IERC20(vault.asset()).balanceOf(address(vault));
    // Add adapter assets...
    if (realAssets > maxTotalAssets) {
      uint256 lostInterest = realAssets - maxTotalAssets;
      // Fee recipient misses fee on lostInterest
      t(lostInterest < ta / 100, "VV2-DOM-08: >1% interest capped, fee loss");
    }
  }
}

