function crytic_nonzero_deposit_mints_nonzero_shares() public returns (bool) {
  uint256 supply = vault.totalSupply();
  uint256 ta = vault.totalAssets();
  if (supply == 0 || ta == 0) return true;
  uint256 meaningfulAmount = 10 ** (vault.decimals() / 2);
  uint256 shares = vault.previewDeposit(meaningfulAmount);
  return t(shares > 0, "MATH-03: meaningful deposit gives zero shares");
}

function crytic_roundtrip_deposit_redeem_no_profit() public returns (bool) {
  uint256 ta = vault.totalAssets();
  if (ta == 0) return true;
  uint256 depositAmount = 1e18;
  uint256 sharesGot = vault.previewDeposit(depositAmount);
  if (sharesGot == 0) return true;
  uint256 assetsBack = vault.previewRedeem(sharesGot);
  return t(assetsBack <= depositAmount, "MATH-04: deposit-redeem roundtrip profits user");
}

function crytic_force_deallocate_penalty_bounded() public returns (bool) {
  uint256 assets = 1e18;
  address adapter = vault.liquidityAdapter();
  if (adapter == address(0)) return true;
  uint256 penaltyRate = vault.forceDeallocatePenalty(adapter);
  if (penaltyRate == 0) return true;
  uint256 expectedPenalty = (assets * penaltyRate) / 1e18;
  uint256 actualPenalty = (assets * penaltyRate + 1e18 - 1) / 1e18;
  return t(actualPenalty <= expectedPenalty + 1, "MATH-09: penalty rounding exceeds 1 wei tolerance");
}

function crytic_preview_deposit_mint_consistent() public returns (bool) {
  uint256 ta = vault.totalAssets();
  if (ta == 0) return true;
  uint256 assets = 1e18;
  uint256 shares = vault.previewDeposit(assets);
  if (shares == 0) return true;
  uint256 assetsForMint = vault.previewMint(shares);
  return t(assetsForMint >= assets, "MATH-13: previewMint(previewDeposit(X)) < X — vault leaks value");
}

function property_sig_01() public {
  // Verify DOMAIN_SEPARATOR is computed with chainId and address only
  bytes32 expected = keccak256(abi.encode(
    keccak256("EIP712Domain(uint256 chainId,address verifyingContract)"),
    block.chainid,
    address(vault)
  ));
  eq(vault.DOMAIN_SEPARATOR(), expected, "SIG-01: DOMAIN_SEPARATOR mismatch");
}

function property_sig_02() public {
  // Nonce must only increment on successful permit calls
  uint256 nonceBefore = vault.nonces(address(0x1234));
  // After a failed permit (invalid sig), nonce should remain unchanged
  // We track via ghost that any nonce change corresponds to a valid permit
  if (ghost_permitCalled && !ghost_permitSucceeded) {
    eq(vault.nonces(ghost_permitOwner), ghost_nonceBeforePermit,
       "SIG-02: nonce incremented on failed permit");
  }
}

function property_sig_03() public {
  // DOMAIN_SEPARATOR must always use current block.chainid
  bytes32 domainSep = vault.DOMAIN_SEPARATOR();
  bytes32 expected = keccak256(abi.encode(
    keccak256("EIP712Domain(uint256 chainId,address verifyingContract)"),
    block.chainid,
    address(vault)
  ));
  eq(domainSep, expected, "SIG-03: DOMAIN_SEPARATOR not using current chainId");
}

function property_sig_04() public {
  // After a permit, the total shares drained by spender in one tx block
  // should never exceed the max of old and new allowance
  if (ghost_permitExecuted) {
    uint256 maxAllowed = ghost_oldAllowance > ghost_newPermitAllowance
      ? ghost_oldAllowance
      : ghost_newPermitAllowance;
    lte(ghost_totalDrainedBySpender, maxAllowed,
        "SIG-04: spender drained more than max(old, new) allowance via permit front-run");
  }
}

function property_sig_06() public {
  // Verify allowance is consistently consumed in shares across all paths
  if (ghost_exitCalled && ghost_exitSender != ghost_exitOnBehalf) {
    // The allowance decrease must equal the shares burned, not the assets withdrawn
    uint256 allowanceDecrease = ghost_allowanceBeforeExit - vault.allowance(ghost_exitOnBehalf, ghost_exitSender);
    eq(allowanceDecrease, ghost_sharesBurnedInExit,
       "SIG-06: allowance decrease != shares burned in exit");
  }
}

function property_sig_07() public {
  // Verify the PERMIT_TYPEHASH matches the expected EIP-2612 format
  bytes32 expected = keccak256(
    "Permit(address owner,address spender,uint256 value,uint256 nonce,uint256 deadline)"
  );
  // This is a compile-time constant check — always true if ConstantsLib is correct
  // The real invariant: the hash used in permit() matches PERMIT_TYPEHASH
  bytes32 hashStruct = keccak256(abi.encode(
    expected, address(0x1), address(0x2), uint256(100), uint256(0), uint256(block.timestamp + 1)
  ));
  // Verify structure is consistent
  t(hashStruct != bytes32(0), "SIG-07: PERMIT_TYPEHASH produces zero hash");
}

function property_sig_08() public {
  // If forceDeallocate was called with onBehalf != msg.sender,
  // allowance must have been consumed, and the consumed amount must equal
  // the penalty shares, not the deallocated amount
  if (ghost_forceDeallocateCalled && ghost_fdSender != ghost_fdOnBehalf) {
    uint256 allowanceConsumed = ghost_allowanceBeforeFD -
      vault.allowance(ghost_fdOnBehalf, ghost_fdSender);
    // Allowance consumed should equal penalty shares, not full amount
    eq(allowanceConsumed, ghost_penaltySharesBurned,
       "SIG-08: forceDeallocate consumed wrong allowance amount");
    // Penalty shares should be bounded by MAX_FORCE_DEALLOCATE_PENALTY
    lte(ghost_penaltySharesBurned, ghost_fdOnBehalfBalanceBefore * 2 / 100,
        "SIG-08: penalty shares exceed 2% cap");
  }
}

