function property_sig_11() public {
  // Gates must be checked at execution time (transfer/withdraw), not at permit time
  // Verify: if a gate blocks an operation, it blocks regardless of existing allowance
  if (ghost_gateActive && ghost_userGated) {
    // Even with max allowance, gated user should not be able to have shares sent
    uint256 balanceBefore = vault.balanceOf(ghost_gatedUser);
    // If gated user's balance decreased, gate was bypassed
    if (ghost_operationAttempted) {
      gte(vault.balanceOf(ghost_gatedUser), balanceBefore,
          "SIG-11: gated user's shares were sent despite active gate");
