// Track gas cost of accrueInterestView to detect DoS threshold
uint256 internal ghost_maxAccrueGas;

function property_dos_01() public {
  uint256 gasBefore = gasleft();
  try vault.accrueInterest() {
    uint256 gasUsed = gasBefore - gasleft();
    if (gasUsed > ghost_maxAccrueGas) ghost_maxAccrueGas = gasUsed;
    // accrueInterest should never consume more than 50% of block gas limit
    t(gasUsed < 15_000_000, "DOS-01: accrueInterest exceeds 50% block gas limit");
  } catch {
    // If accrueInterest reverts, vault is DoS'd
    t(false, "DOS-01: accrueInterest reverted — vault is DoS'd");
  }
}

