  uint256 totalAssets;
  try vault.totalAssets() returns (uint256 ta) {
    totalAssets = ta;
  } catch {
    return;
  }
  // If realBalance significantly exceeds totalAssets, donation may have occurred
  // This is bounded by maxRate, but the gap represents DoS of proper accounting
  if (totalAssets > 0) {
    uint256 gap = realBalance > totalAssets ? realBalance - totalAssets : 0;
    // Gap should not exceed 100% of totalAssets (extreme donation)
    t(gap <= totalAssets,
      "DOS-08: realBalance exceeds 2x totalAssets — extreme donation detected");
