// Track share price before and after a direct donation + accrual
uint256 totalAssetsBefore = vault._totalAssets();
uint256 totalSupplyBefore = vault.totalSupply();
uint256 maxRateVal = vault.maxRate();

// After accrueInterest, the price increase should be bounded
(uint256 newTotalAssets,,) = vault.accrueInterestView();
uint256 elapsed = block.timestamp - vault.lastUpdate();

// maxTotalAssets = _totalAssets + (_totalAssets * elapsed * maxRate / WAD)
uint256 maxIncrease = (totalAssetsBefore * elapsed * maxRateVal) / 1e18;

// The actual increase must not exceed maxRate bound
uint256 actualIncrease = newTotalAssets > totalAssetsBefore ? newTotalAssets - totalAssetsBefore : 0;
lte(actualIncrease, maxIncrease + 1, "VV-W-01: donation exceeded maxRate bound");

// After any allocate, the allocation must respect relative cap vs firstTotalAssets
// Track ghost: allocation vs what firstTotalAssets was when relative cap was checked
uint256 fta = vault.firstTotalAssets();
if (fta > 0) {
  // For each id, check allocation <= firstTotalAssets * relativeCap / WAD
  // This is already checked in code, but the question is whether fta can be manipulated
  // Ghost tracks if fta was artificially inflated by a same-block deposit
  t(fta <= ghost_totalAssetsBeforeDeposit * 120 / 100, "VV-W-02: firstTotalAssets inflated >20% by single deposit");
}

// Verify multicall doesn't allow transient maxRate manipulation
uint256 maxRateBefore = vault.maxRate();
// After multicall completes, maxRate should not have changed if no legitimate setMaxRate
uint256 maxRateAfter = vault.maxRate();
eq(maxRateAfter, maxRateBefore, "VV-W-03: maxRate changed during multicall batch");

// Management fee assets must never exceed newTotalAssets
(uint256 newTotalAssets,,) = vault.accrueInterestView();
uint256 elapsed = block.timestamp - vault.lastUpdate();
uint256 mgmtFee = vault.managementFee();

uint256 mgmtFeeAssets = (newTotalAssets * elapsed * mgmtFee) / 1e18;
uint256 perfFee = vault.performanceFee();
uint256 interest = newTotalAssets > uint256(vault._totalAssets()) ? newTotalAssets - uint256(vault._totalAssets()) : 0;
uint256 perfFeeAssets = (interest * perfFee) / 1e18;

// This must hold or accrueInterest will revert
t(newTotalAssets >= perfFeeAssets + mgmtFeeAssets, "VV-W-04: fees exceed totalAssets, vault will brick");

// After forceDeallocate, track the accounting gap
uint256 totalAssetsBefore = uint256(vault._totalAssets());
uint256 realBalanceBefore = IERC20(vault.asset()).balanceOf(address(vault));

// ... forceDeallocate happens ...

uint256 totalAssetsAfter = uint256(vault._totalAssets());
uint256 realBalanceAfter = IERC20(vault.asset()).balanceOf(address(vault));

// The penalty assets remain in vault balance but _totalAssets decreased
// This gap becomes phantom interest on next accrueInterest
(uint256 viewTotal,,) = vault.accrueInterestView();
uint256 gap = viewTotal > totalAssetsAfter ? viewTotal - totalAssetsAfter : 0;
eq(gap, 0, "VV-W-05: forceDeallocate created phantom interest gap");

// Zero deposit should not change any meaningful state
uint256 supplyBefore = vault.totalSupply();
uint256 totalAssetsBefore = uint256(vault._totalAssets());

try vault.deposit(0, address(this)) returns (uint256 shares) {
  eq(shares, 0, "VV-W-06a: zero deposit minted non-zero shares");
  eq(vault.totalSupply(), supplyBefore, "VV-W-06b: totalSupply changed on zero deposit");
  eq(uint256(vault._totalAssets()), totalAssetsBefore, "VV-W-06c: totalAssets changed on zero deposit");
} catch {}

// After accrueInterest, newTotalAssets must be <= maxTotalAssets
uint256 oldTotalAssets = uint256(vault._totalAssets());
uint256 elapsed = block.timestamp - vault.lastUpdate();
uint256 maxRateVal = vault.maxRate();

(uint256 newTotalAssets,,) = vault.accrueInterestView();

uint256 maxTotalAssets = oldTotalAssets + (oldTotalAssets * elapsed * maxRateVal) / 1e18;
lte(newTotalAssets, maxTotalAssets, "VV-W-07: totalAssets exceeded maxRate cap");

// If user has shares, they must be able to exit (no gate DoS)
if (vault.balanceOf(address(this)) > 0) {
  // Verify canSendShares doesn't revert
  try vault.canSendShares(address(this)) returns (bool result) {
    t(true, "VV-W-08: canSendShares did not revert");
  } catch {
    t(false, "VV-W-08: canSendShares reverted — gate DoS detected");
  }
  // Verify canReceiveAssets doesn't revert
  try vault.canReceiveAssets(address(this)) returns (bool result) {
    t(true, "VV-W-08: canReceiveAssets did not revert");
  } catch {
    t(false, "VV-W-08: canReceiveAssets reverted — gate DoS detected");
  }
}

// Track that no re-entrant state changes occur during deallocateInternal
// Ghost variable: set to true if re-entry detected
uint256 supplyBefore = vault.totalSupply();
uint256 totalBefore = uint256(vault._totalAssets());

// After a deallocate call, verify consistency
uint256 supplyAfter = vault.totalSupply();
uint256 totalAfter = uint256(vault._totalAssets());

// If re-entry occurred via deposit during deallocate, supply would have changed
// unexpectedly relative to totalAssets
t(!ghost_reentrancyDetected, "VV-W-09: reentrancy detected during deallocateInternal");

// After allocate, if assets > 0, change must be > 0
// Ghost: track last allocate call parameters
uint256 assetsSent = ghost_lastAllocateAssets;
int256 changeReported = ghost_lastAllocateChange;

if (assetsSent > 0) {
  t(changeReported > 0, "VV-W-10: allocate sent assets but adapter reported zero change");
}

// Roundtrip: deposit X assets, immediately redeem all shares, should get back <= X
uint256 depositAmount = 1000e18;
uint256 balBefore = IERC20(vault.asset()).balanceOf(address(this));
uint256 shares = vault.deposit(depositAmount, address(this));
uint256 assetsBack = vault.redeem(shares, address(this), address(this));
uint256 balAfter = IERC20(vault.asset()).balanceOf(address(this));

lte(assetsBack, depositAmount, "VV-W-11: roundtrip extracted profit");

// If any gate-setting function is abdicated, verify current gate is non-reverting
bytes4 setSendGateSel = bytes4(keccak256("setSendSharesGate(address)"));
if (vault.abdicated(setSendGateSel)) {
  address gate = vault.sendSharesGate();
  if (gate != address(0)) {
    try vault.canSendShares(address(this)) returns (bool) {
      t(true, "VV-W-12: abdicated sendSharesGate is non-reverting");
    } catch {
      t(false, "VV-W-12: CRITICAL — abdicated gate reverts, funds locked forever");
    }
  }
}

// Track that share price monotonically relates to actual assets
uint256 totalAssets1 = uint256(vault._totalAssets());
uint256 totalSupply1 = vault.totalSupply();

if (totalSupply1 > 0 && totalAssets1 > 0) {
  uint256 pricePerShare = (totalAssets1 * 1e18) / totalSupply1;
  // Track min price and ensure deposits during low price don't create excess profit
  if (pricePerShare < ghost_minPricePerShare) {
    ghost_minPricePerShare = pricePerShare;
  }
  gte(pricePerShare, 1, "VV-W-13: share price collapsed to dust");
}

// If fees are configured, fee recipients must be able to receive shares
uint256 perfFee = vault.performanceFee();
address perfRecipient = vault.performanceFeeRecipient();
uint256 mgmtFee = vault.managementFee();
address mgmtRecipient = vault.managementFeeRecipient();

if (perfFee > 0 && perfRecipient != address(0)) {
  t(vault.canReceiveShares(perfRecipient), "VV-W-14a: perf fee recipient blocked by gate");
}
if (mgmtFee > 0 && mgmtRecipient != address(0)) {
  t(vault.canReceiveShares(mgmtRecipient), "VV-W-14b: mgmt fee recipient blocked by gate");
}

// Ghost: track curator at time of submit and whether curator changed
address internal ghost_curatorAtLastSubmit;
bool internal ghost_curatorChanged;
bytes internal ghost_pendingData;

function property_ac_01_stale_pending_survives_curator_change() public {
  // After setCurator changes the curator, no pending submissions from
  // old curator should remain executable without explicit re-approval
  if (ghost_curatorChanged && ghost_pendingData.length > 0) {
    uint256 execAt = vault.executableAt(ghost_pendingData);
    eq(execAt, 0, "AC-01: stale pending submission survives curator change");
  }
}

function property_ac_03_no_unauthorized_share_burn() public {
  // forceDeallocate should NOT burn shares of onBehalf
  // without onBehalf's explicit approval
  address victim = address(0xBEEF);
  uint256 victimBalBefore = vault.balanceOf(victim);
  // After any forceDeallocate called by non-victim without allowance:
  uint256 victimBalAfter = vault.balanceOf(victim);
  gte(victimBalAfter, victimBalBefore, "AC-03: victim shares burned without allowance");
}

// Ghost: track if multicall attempted to bypass timelock
bool internal ghost_multicallUsed;
bytes4 internal ghost_lastSubmitSelector;
uint256 internal ghost_timelockAtSubmit;

function property_ac_04_multicall_no_timelock_bypass() public {
  if (ghost_multicallUsed && ghost_timelockAtSubmit > 0) {
    // If timelock > 0 was set, the function should NOT have been executed
    // in the same tx as submit (same block.timestamp)
    bytes4 sel = ghost_lastSubmitSelector;
    uint256 tl = vault.timelock(sel);
    if (tl > 0) {
      // executableAt should be in the future, not already consumed (0)
      t(true, "AC-04: multicall timelock bypass check (manual verification needed)");
    }
  }
}

// Ghost: track who executed timelocked ops
address internal ghost_lastTimelockExecutor;
bool internal ghost_timelockExecuted;

function property_ac_07_timelocked_no_sender_check() public {
  // Verify that timelocked functions can be called by any address
  // (this is by design — the risk is in combination with AC-01)
  if (ghost_timelockExecuted) {
    // The executor doesn't need to be curator — by design
    // This property documents the behavior, real finding is AC-01
    t(ghost_timelockExecuted,
      "AC-07: timelocked function was executed (trustless — by design)");
  }
}

function property_ac_10_owner_not_zero() public {
  // Owner should never be zero address — if it is, governance is permanently frozen
  t(vault.owner() != address(0),
    "AC-10: owner is zero address — governance permanently frozen");
}

function property_ac_11_cap_decrease_asymmetry() public {
  // decreaseAbsoluteCap should always result in cap <= previous cap
  // (monotonically non-increasing without timelock)
  // This is by design — the increase/decrease asymmetry IS the security model
  // Test: after decrease, cap should be <= what it was
  bytes32 testId = keccak256(abi.encodePacked("test"));
  uint256 absCap = vault.absoluteCap(testId);
  uint256 relCap = vault.relativeCap(testId);
  // Caps should be within valid ranges
  lte(relCap, 1e18, "AC-11: relativeCap exceeds WAD");
}

function property_ac_12_permit_rejects_zero_recovery() public {
  // ecrecover(invalid) returns address(0) — permit should always reject this
  // Test: no allowance should be set for address(0) as owner via permit
  uint256 zeroAllowance = vault.allowance(address(0), address(this));
  eq(zeroAllowance, 0,
    "AC-12: address(0) has non-zero allowance — permit may be bypassed");
}

function property_ac_15_gate_blocks_transfer() public {
  // If sendSharesGate blocks an address, that address should not be able
  // to have shares moved from it via transfer OR transferFrom
  address blocked = address(0xBLOC);
  if (!vault.canSendShares(blocked)) {
    // blocked's balance should not decrease (no one can move their shares)
    uint256 bal = vault.balanceOf(blocked);
    // After any transfer/transferFrom attempt:
    uint256 balAfter = vault.balanceOf(blocked);
    gte(balAfter, bal,
      "AC-15: gated user's shares moved despite sendSharesGate blocking");
  }
}

function property_ac_16_owner_never_zero() public {
  // Owner should never become address(0) — permanent governance loss
  t(vault.owner() != address(0),
    "AC-16: owner set to address(0) — governance permanently bricked");
}

function property_ac_17_fee_recipient_can_receive_shares() public {
  // If performanceFee > 0, the recipient should be able to receive shares
  // If managementFee > 0, the recipient should be able to receive shares
  if (vault.performanceFee() > 0) {
    address perfRecipient = vault.performanceFeeRecipient();
    t(vault.canReceiveShares(perfRecipient),
      "AC-17: performanceFeeRecipient blocked by receiveSharesGate — fees silently disabled");
  }
  if (vault.managementFee() > 0) {
    address mgmtRecipient = vault.managementFeeRecipient();
    t(vault.canReceiveShares(mgmtRecipient),
      "AC-17: managementFeeRecipient blocked by receiveSharesGate — fees silently disabled");
  }
}

function property_vv2_dd_01() public {
  uint256 currentTotalAssets = uint256(vault._totalAssets());
  uint256 fta = vault.firstTotalAssets();
  // If firstTotalAssets is set (within a tx), it should not be MORE than
  // 2x the current _totalAssets. A larger gap means caps are stale.
  if (fta > 0 && currentTotalAssets > 0) {
    // After exits, firstTotalAssets can be much larger than _totalAssets
    // which makes relative caps overly permissive
    t(fta <= currentTotalAssets * 2, "DD-01: firstTotalAssets > 2x _totalAssets, caps stale");
  }
}

function property_vv2_dd_02() public {
  // The penalty shares burned from onBehalf should be consistent regardless
  // of whether forceDeallocate is first or second call in a tx
  if (ghost_forceDeallocateCalled && ghost_penaltyShares > 0) {
    uint256 expectedPenaltyAssets = ghost_forceDeallocateAmount * ghost_penalty / 1e18;
    uint256 actualAssetsValue = vault.previewRedeem(ghost_penaltyShares);
    // Penalty shares should represent approximately penaltyAssets worth
    uint256 tolerance = expectedPenaltyAssets / 100; // 1% tolerance
    t(
      actualAssetsValue >= expectedPenaltyAssets - tolerance &&
      actualAssetsValue <= expectedPenaltyAssets + tolerance,
      "DD-02: penalty shares mispriced due to stale accrual"
    );
  }
}

function property_vv2_dd_04() public {
  // After forceDeallocate, the vault's actual balance should not exceed
  // _totalAssets by more than the penalty amount + rounding
  uint256 vaultBalance = IERC20(asset).balanceOf(address(vault));
  uint256 totalAssetsTracked = uint256(vault._totalAssets());
  uint256 adapterAssets = 0;
  for (uint256 i = 0; i < vault.adaptersLength(); i++) {
    adapterAssets += IAdapter(vault.adapters(i)).realAssets();
  }
  uint256 totalReal = vaultBalance + adapterAssets;
  if (totalReal > totalAssetsTracked && totalAssetsTracked > 0) {
    uint256 excess = totalReal - totalAssetsTracked;
    // Excess should be bounded by accumulated penalties + maxRate interest
    t(
      excess <= ghost_accumulatedPenalties + ghost_maxRateInterest + 1e6,
      "DD-04: excess balance beyond penalties + maxRate bounds"
    );
  }
}

function property_vv2_dd_06() public {
  // If performance fee > 0 and interest > 0, fee shares should be minted
  // (unless fee recipient genuinely cannot receive shares)
  uint256 perfFee = vault.performanceFee();
  address perfRecipient = vault.performanceFeeRecipient();
  if (perfFee > 0 && perfRecipient != address(0)) {
    // Track: if interest was earned but no fee shares minted
    uint256 currentAssets = uint256(vault._totalAssets());
    if (currentAssets > ghost_lastKnownTotalAssets && ghost_lastKnownTotalAssets > 0) {
      uint256 interest = currentAssets - ghost_lastKnownTotalAssets;
      uint256 expectedFeeAssets = interest * perfFee / 1e18;
      if (expectedFeeAssets > 0) {
        // Fee recipient balance should have increased
        t(
          vault.balanceOf(perfRecipient) >= ghost_feeRecipientBalanceBefore,
          "DD-06: interest earned but no fee shares minted"
        );
      }
    }
  }
}

function property_vv2_dd_07() public {
  // After any allocate, the allocation should not exceed relativeCap % of
  // CURRENT _totalAssets (not firstTotalAssets)
  uint256 currentAssets = uint256(vault._totalAssets());
  if (currentAssets > 0) {
    for (uint256 i = 0; i < ghost_trackedIds.length; i++) {
      bytes32 id = ghost_trackedIds[i];
      uint256 alloc = vault.allocation(id);
      uint256 relCap = vault.relativeCap(id);
      if (relCap < 1e18 && relCap > 0) {
        uint256 maxAllowed = currentAssets * relCap / 1e18;
        t(
          alloc <= maxAllowed + currentAssets / 10000, // 0.01% tolerance
          "DD-07: allocation exceeds relativeCap of current _totalAssets"
        );
      }
    }
  }
}

function property_vv_dd_01() public {
    // INV: _calculateLiquidation must never revert for any liquidatable position
    // This checks the boundary condition where penalty fraction denominator = 0
    for (uint256 i; i < _tokenIds.length; i++) {
        (uint256 shares) = vault.loans(_tokenIds[i]);
        if (shares > 0) {
            (,,,,uint256 debtX96,) = vault.vaultInfo();
            uint256 debt = shares * debtX96 / (2**96);
            (bool isHealthy, uint256 fullValue, uint256 collateralValue,) =
                vault.loanInfo(_tokenIds[i]);
            if (!isHealthy && collateralValue > 0) {
                uint256 maxPenaltyValue = debt * (2**32 + vault.MAX_LIQUIDATION_PENALTY_X32()) / (2**32);
                if (fullValue >= maxPenaltyValue) {
                    uint256 startLiquidationValue = debt * fullValue / collateralValue;
                    // This denominator must never be zero
                    t(startLiquidationValue != maxPenaltyValue,
                      "VV-DD-01: liquidation penalty denominator = 0 — position unliquidatable");
                }
            }
        }
    }
}

function property_vv_dd_02() public {
    // INV: _sendPositionValue must handle positions where all value is in fees
    for (uint256 i; i < _tokenIds.length; i++) {
        (uint256 shares) = vault.loans(_tokenIds[i]);
        if (shares > 0) {
            (bool isHealthy, uint256 fullValue,, uint256 feeValue) =
                vault.loanInfo(_tokenIds[i]);
            if (!isHealthy && fullValue > 0 && feeValue > 0) {
                // If all value is in fees, liquidation would revert
                t(fullValue != feeValue,
                  "VV-DD-02: fullValue == feeValue — liquidation would div/0 in _sendPositionValue");
            }
        }
    }
}

function property_vv_dd_03() public {
    // INV: Socialized loss must never exceed total lent assets
    // If it does, _handleReserveLiquidation reverts and liquidation is blocked
    (uint256 debt, uint256 lent, uint256 balance, uint256 reserves,,) = vault.vaultInfo();
    // Sum all debt from active loans
    uint256 totalDebt;
    for (uint256 i; i < _tokenIds.length; i++) {
        (uint256 shares) = vault.loans(_tokenIds[i]);
        totalDebt += shares;
    }
    if (totalDebt > 0 && lent > 0) {
        // Worst case: largest single loan socialization
        // If any single debt > reserves + lent, liquidation would revert
        for (uint256 i; i < _tokenIds.length; i++) {
            (uint256 shares) = vault.loans(_tokenIds[i]);
            if (shares > 0) {
                (,,,,uint256 debtX96,) = vault.vaultInfo();
                uint256 loanDebt = shares * debtX96 / (2**96);
                if (loanDebt > reserves) {
                    uint256 missing = loanDebt - reserves;
                    t(missing < lent,
                      "VV-DD-03: socialized loss >= totalLent — liquidation would revert");
                }
            }
        }
    }
}

function property_vv_dd_04() public {
    // INV: Every position with debt must be able to partial repay
    // If minLoanSize prevents partial repay, borrower is trapped
    uint256 minLoan = vault.minLoanSize();
    for (uint256 i; i < _tokenIds.length; i++) {
        (uint256 shares) = vault.loans(_tokenIds[i]);
        if (shares > 0) {
            (,,,,uint256 debtX96,) = vault.vaultInfo();
            uint256 debt = shares * debtX96 / (2**96);
            if (debt > 0 && debt < minLoan) {
                // Position exists with debt below minLoanSize
                // Partial repay is impossible — only full repay works
                // This is a deadlock if borrower can't afford full repay
                t(false,
                  "VV-DD-04: position has debt < minLoanSize — partial repay blocked");
            }
        }
    }
}

function property_vv_dd_05() public {
    // INV: Socialized loss must be bounded relative to totalLent
    // If a single liquidation can cause > 10% haircut, bank run incentive exists
    (uint256 debt,, uint256 balance, uint256 reserves,,) = vault.vaultInfo();
    uint256 totalSupply_ = vault.totalSupply();
    if (totalSupply_ > 0) {
        (,,,,, uint256 lendX96) = vault.vaultInfo();
        uint256 totalLent = totalSupply_ * lendX96 / (2**96);
        // Check: can any single liquidation cause > 10% haircut?
        for (uint256 i; i < _tokenIds.length; i++) {
            (uint256 shares) = vault.loans(_tokenIds[i]);
            if (shares > 0) {
                (,,,,uint256 debtX96,) = vault.vaultInfo();
                uint256 loanDebt = shares * debtX96 / (2**96);
                if (loanDebt > reserves) {
                    uint256 potentialMissing = loanDebt - reserves;
                    // If potential socialized loss > 10% of total lent, bank run risk
                    lte(potentialMissing * 10, totalLent,
                      "VV-DD-05: single liquidation can cause >10% haircut — bank run risk");
                }
            }
        }
    }
}

