// Rates start at Q96 and only grow
gte(debtRate, 2**96, "VV-TB-12: debt exchange rate below Q96");
gte(lendRate, 2**96, "VV-TB-12: lend exchange rate below Q96");
// Rates should not grow more than 100x in any reasonable scenario
lte(debtRate, 100 * 2**96, "VV-TB-12: debt exchange rate unreasonably high");
lte(lendRate, 100 * 2**96, "VV-TB-12: lend exchange rate unreasonably high");
// Debt rate must always be >= lend rate (borrowers pay more than lenders receive)
gte(debtRate, lendRate, "VV-TB-12: debt rate less than lend rate");

// Every position with debt should have non-zero collateral value
for (uint256 i = 0; i < ghost_allTokenIds.length && i < 10; i++) {
