        (uint256 debt, uint256 fullValue, uint256 collateralValue,,) = vault.loanInfo(ghost_allTokenIds[i]);
        if (debt > 0 && collateralValue > 0 && fullValue > 0) {
            uint256 maxPenaltyValue = debt * (Q32 + 429496729) / Q32;
            uint256 startLiquidationValue = debt * fullValue / collateralValue;
            t(startLiquidationValue != maxPenaltyValue || fullValue < maxPenaltyValue, "VV-M-07: liquidation div-by-zero boundary");
