uint256 totalAss = vault.totalAssets();
(,,,,, uint256 lendRate) = vault.vaultInfo();
uint256 totalLent = vault.totalSupply() * lendRate / Q96;
(uint256 debt,,,,) = vault.vaultInfo();
uint256 vaultBalance = usdc.balanceOf(address(vault));
