lte(totalAss, expectedTotal + 1, "VV-M-15: totalAssets exceeds balance + debt");
gte(totalAss + 1, expectedTotal, "VV-M-15: totalAssets below balance + debt");

(,,,, uint256 debtRate, uint256 lendRate) = vault.vaultInfo();
if (debtRate > 0 && lendRate > 0) {
