// Verifica que despues de remove + re-create, approvals viejas no persisten funcionalmente
// Este invariante chequea que transformApprovals se limpia en remove()
// Nota: V3Vault NO limpia transformApprovals en remove() -- stale data persiste
// La proteccion real es que el check en _transform usa tokenOwner[tokenId] actual
// Pero si el MISMO usuario re-deposita, la approval vieja del transformer se reactiva
if (ghost_allTokenIds.length > 0) {
