// Verificamos que el balance de shares no disminuye sin consentimiento
uint256 aliceShares = vault.balanceOf(alice);
uint256 bobShares = vault.balanceOf(bob);
// Los shares solo deben disminuir si el owner hizo withdraw/redeem o dio allowance
