uint256 totalShares = vault.totalSupply();
// total shares debe ser >= 0 (siempre true por uint, pero verificamos no-overflow)
t(totalShares < type(uint256).max / 2, "VV-SIG-08: total shares suspiciously large -- possible overflow");

// Verificar que el vault no tiene balance de ETH inesperado
// (indicaria que alguien envio ETH via Multicall o directamente)
