// V3Vault no deberia manejar ETH directamente
lte(ethBalance, 1 ether, "VV-SIG-09: vault has unexpected ETH balance");

// Verificar que approvals son granulares y no se propagan inesperadamente
// Despues de operaciones, cada token solo debe tener approvals explicitas
for (uint256 i = 0; i < ghost_allTokenIds.length && i < 5; i++) {
