// Track tokens before/after a mint+burn cycle for the same user and bin
lte(ghost_withdrawnX, ghost_depositedX, "BPM-M01: X profit on round-trip");
lte(ghost_withdrawnY, ghost_depositedY, "BPM-M01: Y profit on round-trip");

// After a mint into active bin with composition fee:
