if (ghost_compositionFeeAmt > 0 && ghost_swapFeeBips > 0) {
    uint256 totalFee = uint256(ghost_swapFeeBips) * 1e12;
    uint256 equivalentSwapFee = (uint256(ghost_implicitSwapAmt) * totalFee +
        (1e18 - totalFee) - 1) / (1e18 - totalFee);
