int256 swapCost = int256(uint256(ghost_equivalentSwapFee));
int256 mintBurnCost = int256(uint256(ghost_actualCompositionFee)) +
                      int256(uint256(ghost_mintBurnRoundingLoss));
return swapCost - mintBurnCost;

// Después de cada llamada a updateDynamicLPFee(key, newFee):
