lte(uint256(protocolFee & 0xFFF), 1000, "BPM-AC-08: protocolFee0 exceeds max");
lte(uint256((protocolFee >> 12) & 0xFFF), 1000, "BPM-AC-08: protocolFee1 exceeds max");

// After any swap, verify:
// sum(reserveChange_per_bin) + totalProtocolFee == |inputDelta| - |outputDelta|
// Ghost: track total reserves before/after swap across all traversed bins
// Track protocol fee accrued during this swap
// Track delta returned by swap
if (ghost_lastSwapOccurred) {
