    // the net tokens entering the pool (delta negative = user pays = pool receives)
    int256 poolReceived0 = -ghost_lastSwapDelta0;
    int256 poolReceived1 = -ghost_lastSwapDelta1;
    int256 reserveChange0 = ghost_swapReserveChangeX;
    int256 reserveChange1 = ghost_swapReserveChangeY;
    int256 pFee0 = int256(ghost_swapProtocolFeeX);
    int256 pFee1 = int256(ghost_swapProtocolFeeY);
    eq(reserveChange0 + pFee0, poolReceived0, "BPM-F01: X token conservation violated in swap");
    eq(reserveChange1 + pFee1, poolReceived1, "BPM-F01: Y token conservation violated in swap");
}

// Test: pause the contract, then attempt burn — it should succeed (or revert?)
// This verifies the current behavior matches the design intent.
// If burn SHOULD be blocked during pause, this is a bug.
// If burn is intentionally allowed (emergency exit), this is by design.
try binPoolManager.burn(poolKey, burnParams, hookData) returns (BalanceDelta delta) {
