}

// After swap, verify protocol fee + LP fee in reserves == totalFee
// Per-bin: totalFee[i] = amountsInWithFees[i] - amountIn_net[i]
// pFee[i] = getProtocolFeeAmt(totalFee[i], protocolFee, swapFee)
// LP_fee_in_reserves[i] = totalFee[i] - pFee[i]
// Global: sum(pFee[i]) should equal state.feeAmountToProtocol
// And sum(LP_fee_in_reserves[i]) should be in bin reserves
if (ghost_lastSwapOccurred && ghost_swapProtocolFeeX + ghost_swapProtocolFeeY > 0) {
    // Protocol fee should be <= totalFee (rounding down)
    lte(ghost_swapProtocolFeeX, ghost_swapTotalFeeX, "BPM-F04: protocol fee X exceeds total fee");
    lte(ghost_swapProtocolFeeY, ghost_swapTotalFeeY, "BPM-F04: protocol fee Y exceeds total fee");
}

// After any burn, verify tree consistency:
// If shareOfBin == MINIMUM_SHARE, bin should NOT be in tree
// If shareOfBin > MINIMUM_SHARE, bin SHOULD be in tree
for (uint256 i = 0; i < ghost_burnBinIds.length; i++) {
    uint24 binId = ghost_burnBinIds[i];
    uint256 supply = binPoolManager.pools(poolId).shareOfBin[binId];
    if (supply <= MINIMUM_SHARE) {
        // Bin should be removed from tree — verify via getNextNonEmptyBin
        uint24 nextRight = binPoolManager.getNextNonEmptyBin(poolId, true, binId - 1);
        t(nextRight != binId, "BPM-F07: dead bin still in tree after burn");
    }
