if (ghost_donateOccurred) {
    (uint128 rx, uint128 ry,,) = binPoolManager.getBin(poolId, ghost_donateActiveBinId);
    gte(uint256(rx), ghost_preDonateBinReserveX, "BPM-F08: bin X reserves decreased after donate");
    gte(uint256(ry), ghost_preDonateBinReserveY, "BPM-F08: bin Y reserves decreased after donate");
