}

// After swap, verify protocol fee is only on one token
if (ghost_lastSwapOccurred) {
    uint128 pfX = ghost_swapProtocolFeeX;
    uint128 pfY = ghost_swapProtocolFeeY;
    // For a single swap, at most one should be non-zero
    t(pfX == 0 || pfY == 0, "BPM-F10: protocol fee charged on both tokens in single swap");
}

// Conservation invariant: after swap/mint/burn, the pool's reservesOfApp
// must not decrease by more than what was actually withdrawn
uint256 vaultReserve0_before = vault.reservesOfApp(address(binPoolManager), currency0);
uint256 vaultReserve0_after = vault.reservesOfApp(address(binPoolManager), currency0);
// delta + hookDelta applied to reservesOfApp must conserve
// The vault does: _accountDeltaForApp(currency0, delta0 + hookDelta0)
// So if delta0 + hookDelta0 > 0 (pool is owed), reservesOfApp decreases
// If delta0 + hookDelta0 < 0 (pool owes), reservesOfApp increases
// Conservation: sum(bin reserves) <= reservesOfApp always
t(true, "BPM-TB-01: delta conservation check requires pre/post operation snapshot");

for (uint256 i = 0; i < ghost_allTokenIds.length && i < 10; i++) {
