// Verify that positions with debt have consistent value whether staked or not
// We check that fullValue from loanInfo (which accounts for staking) is reasonable
for (uint256 i = 0; i < ghost_allTokenIds.length && i < 5; i++) {
    uint256 tokenId = ghost_allTokenIds[i];
    (uint256 shares) = vault.loans(tokenId);
    if (shares > 0) {
        (uint256 debt, uint256 fullValue, uint256 collateralValue,,) = vault.loanInfo(tokenId);
        if (debt > 0 && fullValue > 0) {
            // collateral factor is at most 90%, so collateralValue <= 0.9 * fullValue
            // debt should not exceed collateralValue for a healthy loan
            // This checks the invariant that oracle-reported values are consistent
            lte(collateralValue, fullValue, "VV-O-04: staked position collateral > full value");
        }
