}

for (uint256 i = 0; i < ghost_allTokenIds.length && i < 10; i++) {
    uint256 tokenId = ghost_allTokenIds[i];
    (uint256 debt, uint256 fullValue, uint256 collateralValue, uint256 liquidationCost, uint256 liquidationValue) = vault.loanInfo(tokenId);
