// Ghost tracking: record if hook callbacks were actually invoked
// This invariant checks that ANY swap that changes price also triggered hook callbacks
// Test: deploy a hook that calls swap() on itself and verify callbacks are skipped
uint160 priceBefore = poolManager.getSlot0(poolId).sqrtPriceX96;
// Trigger swap via hook contract (msg.sender = hook)
hookContract.executeSwapDirectly(key, swapParams, "");
uint160 priceAfter = poolManager.getSlot0(poolId).sqrtPriceX96;
// If price changed, hook callbacks SHOULD have been called
// but they weren't because shouldCall returned false
t(priceBefore == priceAfter || ghost_hookBeforeSwapCalled, "CLPM-D01: swap changed price without hook callback");

// Track net token balance of attacker across donate + collect cycle
uint256 attackerToken0Before = token0.balanceOf(attacker);
uint256 feeGrowthBefore = poolManager.getFeeGrowthGlobals(poolId);
// Attacker executes: donate -> remove liquidity (collect fees) -> re-add liquidity
// all within one lock callback
attackerContract.executeDonateAndCollectCycle(key, donateAmount);
uint256 attackerToken0After = token0.balanceOf(attacker);
uint256 feeGrowthAfter = poolManager.getFeeGrowthGlobals(poolId);
// Invariant: feeGrowthGlobal should not increase without real external swap volume
// If attacker's balance is roughly unchanged but feeGrowth increased massively, it's inflation
uint256 balanceDelta = attackerToken0Before > attackerToken0After ?
  attackerToken0Before - attackerToken0After : 0;
uint256 feeGrowthDelta = feeGrowthAfter - feeGrowthBefore;
// The cost to inflate should be proportional to the inflation, not dust
t(feeGrowthDelta == 0 || balanceDelta > donateAmount / 2, "CLPM-D02: feeGrowthGlobal inflated for free");

// For every tick in range, verify round-trip consistency
// tick -> sqrtPrice -> tick' must satisfy tick' == tick
int24 tick = ghost_randomTick;
uint160 sqrtPrice = TickMath.getSqrtRatioAtTick(tick);
int24 tickBack = TickMath.getTickAtSqrtRatio(sqrtPrice);
eq(int256(tick), int256(tickBack), "CLPM-D03a: tick round-trip inconsistency");

// Also verify: for sqrtPrice at boundary, zeroForOne swap sets tick = boundary - 1
// This is the KyberSwap-critical check
uint160 boundaryPrice = TickMath.getSqrtRatioAtTick(tick);
int24 expectedTick = tick; // getTickAtSqrtRatio returns greatest tick <= price
int24 actualTick = TickMath.getTickAtSqrtRatio(boundaryPrice);
eq(int256(expectedTick), int256(actualTick), "CLPM-D03b: boundary tick mismatch");

// Test with liquidity = 1 and a swap that generates fees
// Verify that feeGrowthGlobal is calculated correctly (no overflow truncation)
uint128 liquidity = poolManager.getLiquidity(poolId);
if (liquidity > 0 && liquidity <= 10) {
  // Get feeGrowthGlobals before swap
  (uint256 fg0Before, uint256 fg1Before) = poolManager.getFeeGrowthGlobals(poolId);
  // Execute a swap
  // ... swap execution ...
  (uint256 fg0After, uint256 fg1After) = poolManager.getFeeGrowthGlobals(poolId);
  // The feeGrowthGlobal delta should be feeAmount * Q128 / liquidity
  // If this overflowed, fg0After might be LESS than fg0Before (wrapping)
  // For liquidity=1, any feeAmount > 2^128 causes overflow
  // feeAmount is bounded by swap size, so check if swap was large enough
  t(fg0After >= fg0Before, "CLPM-D04: feeGrowthGlobal decreased (overflow)");
}

// After a swap, verify that if delta is non-zero, the swap actually executed
// (price moved or output was generated)
(uint160 sqrtPriceBefore,,,) = poolManager.getSlot0(poolId);
BalanceDelta delta = poolManager.swap(key, params, hookData);
(uint160 sqrtPriceAfter,,,) = poolManager.getSlot0(poolId);
int128 amount0 = delta.amount0();
int128 amount1 = delta.amount1();
// If user paid something (amount0 > 0 or amount1 > 0), price should have moved
// OR output should be non-zero
bool userPaid = (amount0 > 0 || amount1 > 0);
bool userReceived = (amount0 < 0 || amount1 < 0);
bool priceMoved = (sqrtPriceBefore != sqrtPriceAfter);
t(!userPaid || userReceived || priceMoved, "CLPM-D07: user paid but got nothing and price unchanged");

// Verify that donate settles to msg.sender directly (not through hook delta path)
// This is more of a documentation/design invariant than a fuzz target
// The concrete test: after donate, the hook's balance should be unchanged
// (donate delta goes entirely to the caller, not split with hook)
uint256 hookBalance0Before = vault.balanceOf(address(hook), currency0);
poolManager.donate(key, amount0, amount1, "");
uint256 hookBalance0After = vault.balanceOf(address(hook), currency0);
eq(hookBalance0Before, hookBalance0After, "CLPM-D08: donate affected hook balance");

// After any swap, verify that pool.liquidity matches the sum of liquidityNet
// for all initialized ticks <= current tick
(uint160 sqrtPrice, int24 currentTick,,) = poolManager.getSlot0(poolId);
uint128 reportedLiquidity = poolManager.getLiquidity(poolId);
// Calculate expected liquidity by traversing all initialized ticks up to currentTick
// (This requires iterating the tick bitmap - expensive but correct)
int128 cumulativeLiquidityNet = 0;
// Traverse from MIN_TICK to currentTick, summing liquidityNet at each initialized tick
// ... bitmap traversal ...
uint128 expectedLiquidity = uint128(int128(cumulativeLiquidityNet));
eq(uint256(reportedLiquidity), uint256(expectedLiquidity),
   "CLPM-D09: active liquidity != sum of liquidityNet up to current tick");

// For exact input swaps, verify total consumed <= abs(amountSpecified)
int256 amountSpecified = params.amountSpecified; // negative for exact input
BalanceDelta delta = poolManager.swap(key, params, "");
int128 amount0 = delta.amount0();
int128 amount1 = delta.amount1();
if (amountSpecified < 0) {
  // exact input: user pays (positive delta on input side)
  int128 inputConsumed = params.zeroForOne ? amount0 : amount1;
  // inputConsumed should be <= abs(amountSpecified)
  lte(uint256(uint128(inputConsumed)), uint256(uint128(int128(-amountSpecified))),
      "CLPM-D10: swap consumed more input than specified");
}

// Compare UnsafeMath.simpleMulDiv result with FullMath.mulDiv for same inputs
// If they differ, simpleMulDiv has overflowed and truncated
uint256 feeAmount = ghost_lastFeeAmount;
uint128 liquidity = ghost_lastLiquidity;
if (feeAmount > 0 && liquidity > 0) {
  uint256 unsafeResult = UnsafeMath.simpleMulDiv(feeAmount, FixedPoint128.Q128, liquidity);
  uint256 safeResult = FullMath.mulDiv(feeAmount, FixedPoint128.Q128, liquidity);
  eq(unsafeResult, safeResult,
     "CLPM-D11: simpleMulDiv truncated vs FullMath.mulDiv - fee underaccounting");
}

// After each swap call, verify:
// vault.currencyDelta(settler, currency0) + vault.currencyDelta(hookAddr, currency0) == expected pool delta0
// This must be checked across the entire lock() lifecycle
int256 settlerDelta0 = vault.currencyDelta(settler, key.currency0);
int256 settlerDelta1 = vault.currencyDelta(settler, key.currency1);
int256 hookDelta0 = vault.currencyDelta(address(key.hooks), key.currency0);
int256 hookDelta1 = vault.currencyDelta(address(key.hooks), key.currency1);
// The vault must revert on lock() exit if any of these are nonzero
// So after lock() completes: all deltas must be zero
eq(settlerDelta0 + hookDelta0, 0, "CLPM-TB-01: currency0 delta not zero-sum after lock");
eq(settlerDelta1 + hookDelta1, 0, "CLPM-TB-01: currency1 delta not zero-sum after lock");

// Verify that extsload can read pool state
bytes32 slot = keccak256(abi.encode(poolId, uint256(0))); // pools mapping slot
bytes32 data = CLPoolManager(address(clPoolManager)).extsload(slot);
// If data != 0, storage is readable (expected behavior but risk for MEV)
