// Verify that a swap with a modified PoolKey reverts
PoolKey memory fakeKey = key;
fakeKey.parameters = bytes32(uint256(key.parameters) | (1 << HOOKS_BEFORE_SWAP_RETURNS_DELTA_OFFSET));
PoolId fakeId = fakeKey.toId();
// fakeId != original id, so pool lookup fails
