// Verify that donate does not produce any hookDelta
// In the test, call donate on a pool with returnsDelta hooks
// Verify hook's vault delta is unchanged after donate
int256 hookDelta0Before = vault.currencyDelta(address(key.hooks), key.currency0);
// ... donate() ...
int256 hookDelta0After = vault.currencyDelta(address(key.hooks), key.currency0);
eq(hookDelta0Before, hookDelta0After, "CLPM-TB-08: donate should not produce hook delta");

// After any swap, verify that the effective fee was not 100%
// delta.amount0() and delta.amount1() should both not be the same sign
// (user pays one token, receives the other)
int128 amount0 = delta.amount0();
int128 amount1 = delta.amount1();
// In a valid swap, one is positive and one is negative
// If fee is 100%, the output side would be 0 or near-0
if (amount0 < 0) {
    // User paid token0, should receive token1
    gt(amount1, int128(0), "CLPM-TB-09: swap output is zero — possible 100% fee attack");
} else {
    gt(amount0, int128(0), "CLPM-TB-09: swap output is zero — possible 100% fee attack");
}

// Verify protocolFeesAccrued never decreases (monotonically increasing)
uint256 feesBefore = clPoolManager.protocolFeesAccrued(currency);
// ... swap ...
uint256 feesAfter = clPoolManager.protocolFeesAccrued(currency);
gte(feesAfter, feesBefore, "CLPM-TB-10: protocolFeesAccrued decreased");

uint256 sumUsers = 0;
uint256 numF = deal.numFunders();
for (uint256 i = 0; i < numF; i++) {
    (, uint256 amt) = deal.funderAt(i);
    sumUsers += amt;
}
eq(deal.totalFunded(), sumUsers, "D-01: totalFunded != sum of user amounts");

// Para cada funder conocido, su suma por pool == amountFunded total
uint256 numF = deal.numFunders();
for (uint256 i = 0; i < numF; i++) {
    (address funder, uint256 totalAmt) = deal.funderAt(i);
    uint256 sumPools = 0;
    uint256 numPools = deal.numPoolsFundedByFunder(funder);
    for (uint256 j = 0; j < numPools; j++) {
        (, uint256 poolAmt) = deal.amountFundedByFunderAndPoolAt(funder, j);
        sumPools += poolAmt;
    }
    eq(totalAmt, sumPools, "D-02: user total != sum of user pool amounts");
}

uint256 sumPools = 0;
uint256 numP = deal.numFundedPools();
for (uint256 i = 0; i < numP; i++) {
    (, uint256 poolAmt) = deal.poolAt(i);
    sumPools += poolAmt;
}
eq(deal.totalFunded(), sumPools, "D-03: totalFunded != sum of all pool totals");

// feesAmountWithdrawn <= maxFeesAmount del WithdrawalSettings actual
uint256 currentFees = deal.feesAmountWithdrawn();
// No podemos leer _withdrawalSettings directamente pero podemos verificar via withdrawalSettings()
// En el invariante de Chimera necesitamos acceso al contrato
lte(currentFees, ghost_maxFeesAmount, "D-04: feesAmountWithdrawn > maxFeesAmount");

// Este invariante verifica que _reducePoolFundingAmountOnMinRemaining no causa revert
// Se testea indirectamente: si fund() revierte cuando no debería
// Ghost tracking: intentamos fundar con amounts pequeños cerca del límite del pool
// El test real es un fuzz que intenta fundar con amount < minRemainingAmount
// cuando el pool está entre (maxTotalAmount - minRemainingAmount) y maxTotalAmount
t(ghost_fundingDidNotRevertUnexpectedly, "D-05: funding reverted due to underflow in _reducePoolFundingAmountOnMinRemaining");

// El balance del contrato debe ser >= totalFunded (lo que aún no ha sido retirado/refundado)
// Después de withdraw, si totalFunded > 0, quedan fondos de users sin refund
uint256 balance = token.balanceOf(address(deal));
if (ghost_withdrawCalled && deal.totalFunded() > 0) {
    gte(balance, deal.totalFunded() - ghost_totalRefunded, "D-06: balance < pending refunds after withdraw");
}

// Después de withdraw con feesAmount == maxFeesAmount,
// feesAmountWithdrawn debería ser == maxFeesAmount si había suficiente balance
if (ghost_withdrawCalledWithMaxFees && ghost_balanceBeforeWithdraw >= ghost_maxFeesAmount) {
    eq(deal.feesAmountWithdrawn(), ghost_maxFeesAmount, "D-07: fees not fully withdrawn despite sufficient balance");
}

uint256 balance = token.balanceOf(address(deal));
uint256 expectedMin = deal.totalFunded();
// Restamos lo que ya salió
if (expectedMin >= ghost_totalWithdrawn + ghost_totalRefunded) {
    expectedMin -= (ghost_totalWithdrawn + ghost_totalRefunded);
} else {
    expectedMin = 0;
}
gte(balance, expectedMin, "D-08: balance < expected accounting minimum");

// Si un usuario tiene espacio disponible en al menos un pool pero fund() revierte,
// hay un bug de DoS
// Tracking: contar cuándo fund() revierte cuando userAmountAvailable > 0
if (ghost_lastFundReverted && ghost_lastUserAmountAvailable > 0) {
    t(false, "D-09: fund reverted despite available pool space");
}

// Antes y después de refund: la reducción en totalFunded debe ser exactamente
// igual a la suma de los poolRefund amounts
uint256 totalBefore = deal.totalFunded();
// ... después del refund call ...
uint256 totalAfter = deal.totalFunded();
eq(totalBefore - totalAfter, ghost_lastRefundTotalAmount, "D-10: totalFunded reduction != refund amount");

// Profit del atacante: cuánto más sacó de lo que metió
int256 profit = int256(ghost_totalTokensOut) - int256(ghost_totalTokensIn);
return profit;

// Ghost: track token address at fund time
IERC20 tokenAtFund = deal.token();
// After any setToken call, verify consistency
IERC20 currentToken = deal.token();
if (deal.totalFunded() > 0) {
    eq(address(currentToken), address(tokenAtFund), "D-01: token changed while funds deposited");
}

// After a full refund in one deal, check if user still has funds in other deals sharing integrationKey
// This is a cross-contract invariant — needs integration registry state
uint256 userFundedInThisDeal = deal.amountFunded(user);
if (userFundedInThisDeal == 0) {
    // If user was deregistered but still has funds in another deal with same key,
    // the integrated funder count is wrong
    bool isRegistered = funderIntegrationRegistry.isRegistered(integrationKey, user);
    // If user has funds in ANY deal with this key, they MUST be registered
    // t(!isRegistered && userHasFundsElsewhere, "D-02: deregistered user still has funds in sibling deal");
