        sumFunderPools += poolAmount;
    }
    eq(sumFunderPools, totalByUser, "D-12: funder pool sum != total funded by user");
}

// Ghost: track cuantas veces se uso cada signature hash
// Simular: misma firma usada 2 veces en fundFromConduit
// Verificar que la segunda llamada revierte
bytes32 sigHash = keccak256(abi.encode(signature));
uint256 previousCount = ghost_signatureUsageCount[sigHash];
// Despues de fund exitoso:
ghost_signatureUsageCount[sigHash] += 1;
// Invariante: cada signature hash solo puede usarse una vez
lte(ghost_signatureUsageCount[sigHash], 1, "D-01: signature replayed - used more than once");

// Invariante: el digest de un permit debe ser unico por contrato
// Verificar que el digest incluye informacion que identifica univocamente este contrato
DealSignatureLib.DealFundingPermit memory permit;
permit.funder = address(0x1);
permit.isUS = false;
permit.dealUUID = dealUUID;
permit.expireAt = block.timestamp + 1 hours;
// Si dos contratos con mismo dealUUID producen el mismo digest, hay replay
bytes32 digestA = DealSignatureLib.digest(permit);
// digestA == digestB para otro contrato con mismo dealUUID en misma chain
// No podemos testear directamente en un solo contrato, pero el invariante es:
// t(false, "D-02: digest does not include address(this) - cross-contract replay possible");
// Este es un analisis estatico: verificar que address(this) NO esta en el hash
t(true, "D-02: placeholder - verify manually that digest includes address(this)");

// Este es un finding de diseno - no se puede testear con invariante fuzzing
// Verificar que el digest usa EIP-712 domain separator
// Actualmente usa: MessageHashUtils.toEthSignedMessageHash(abi.encode(df, chainId))
// Deberia usar: MessageHashUtils.toTypedDataHash(DOMAIN_SEPARATOR, structHash)
t(true, "D-03: design finding - verify EIP-712 compliance manually");

// Verificar que un permit firmado por un signer removido es rechazado
// Este invariante verifica el comportamiento CORRECTO del contrato
address signer = DealSignatureLib.recoverSigner(permit, signature);
bool signerHasRole = deal.hasRole(deal.SIGNER_ROLE(), signer);
// Si el signer fue removido, la firma debe ser rechazada
// El contrato ya hace esto correctamente en L369
t(true, "D-07: signer revocation correctly invalidates existing permits");

// No se puede verificar on-chain si un usuario es realmente US o no
// Pero podemos verificar que un usuario siempre se registra con el mismo grupo
// (ya implementado en L419: FunderRegisteredUnderDifferentGroup)
// Invariante: un usuario registrado no puede cambiar de grupo
bool isRegistered = funderIntegrationRegistry.isRegistered(integrationKey, user);
if (isRegistered) {
    uint256 regGroup = funderIntegrationRegistry.group(integrationKey, user);
    uint256 permitGroup = fundingPermit.isUS ? 1 : 0;
    eq(regGroup, permitGroup, "D-09: user registered under different group than permit");
}

// Check divergence between the two oracles
uint256 preLiqPrice = IOracle(PRE_LIQUIDATION_ORACLE).price();
uint256 marketPrice = IOracle(ORACLE).price();
if (marketPrice > 0 && preLiqPrice > 0) {
    uint256 ratio = preLiqPrice * WAD / marketPrice;
    // Flag if divergence exceeds 50% in either direction
    t(ratio <= 1.5e18, "PL-O-01: preLiqOracle overvalues collateral >50%");
    t(ratio >= 0.5e18, "PL-O-01: preLiqOracle undervalues collateral >50%");
}

// Property: if position is healthy by market oracle (LTV < PRE_LLTV),
// it should not be pre-liquidatable
uint256 marketPrice = IOracle(ORACLE).price();
uint256 preLiqPrice = IOracle(PRE_LIQUIDATION_ORACLE).price();
Position memory pos = MORPHO.position(ID, borrower);
Market memory mkt = MORPHO.market(ID);
uint256 borrowed = uint256(pos.borrowShares).toAssetsUp(mkt.totalBorrowAssets, mkt.totalBorrowShares);
if (marketPrice > 0 && borrowed > 0) {
    uint256 collateralByMarket = uint256(pos.collateral).mulDivDown(marketPrice, ORACLE_PRICE_SCALE);
    uint256 ltvByMarket = borrowed.wDivUp(collateralByMarket);
    uint256 collateralByPreLiq = uint256(pos.collateral).mulDivDown(preLiqPrice, ORACLE_PRICE_SCALE);
    // If healthy by market oracle, should also be healthy by pre-liq oracle
    if (ltvByMarket <= PRE_LLTV) {
        t(borrowed <= collateralByPreLiq.wMulDown(PRE_LLTV),
          "PL-O-02: healthy position pre-liquidatable via oracle divergence");
    }
}

// Constructor should validate oracle address
address preLiqOracle = PRE_LIQUIDATION_ORACLE;
t(preLiqOracle != address(0), "PL-O-03: PRE_LIQUIDATION_ORACLE is zero address");

// Verify price=0 is handled safely
uint256 collateralPrice = IOracle(PRE_LIQUIDATION_ORACLE).price();
if (collateralPrice == 0) {
    // Should never reach computation code — require statements revert first
    t(false, "PL-O-04: unreachable code reached with price=0");
}

// Cannot directly check staleness with IOracle — use divergence as proxy
uint256 preLiqPrice = IOracle(PRE_LIQUIDATION_ORACLE).price();
uint256 marketPrice = IOracle(ORACLE).price();
if (marketPrice > 0 && preLiqPrice > 0) {
    uint256 divergence;
    if (preLiqPrice > marketPrice) {
        divergence = (preLiqPrice - marketPrice) * WAD / marketPrice;
    } else {
        divergence = (marketPrice - preLiqPrice) * WAD / marketPrice;
    }
    t(divergence <= 0.10e18, "PL-O-05: oracle divergence >10% — possible staleness");
}

// After a successful preLiquidate, verify the position is NOT Morpho-liquidatable
// i.e., the pre-liq didn't push the position over the edge by market oracle
Position memory pos = MORPHO.position(ID, borrower);
Market memory mkt = MORPHO.market(ID);
uint256 marketPrice = IOracle(ORACLE).price();
uint256 collValueMarket = uint256(pos.collateral).mulDivDown(marketPrice, ORACLE_PRICE_SCALE);
uint256 debtAfter = uint256(pos.borrowShares).toAssetsUp(mkt.totalBorrowAssets, mkt.totalBorrowShares);
if (collValueMarket > 0 && debtAfter > 0) {
    uint256 ltvAfterMarket = debtAfter.wDivUp(collValueMarket);
    lte(ltvAfterMarket, LLTV, "PL-DD-02: position became Morpho-liquidatable after pre-liq");
}

// Verify: for any repaidShares where toAssetsDown returns 0,
// the entire preLiquidate call reverts (no partial execution)
Market memory mkt = MORPHO.market(ID);
uint256 assetsDown = uint256(1).toAssetsDown(mkt.totalBorrowAssets, mkt.totalBorrowShares);
if (assetsDown == 0) {
    // preLiquidate with repaidShares=1 should revert
    try preLiquidation.preLiquidate(borrower, 0, 1, "") {
        t(false, "PL-DD-03: preLiquidate succeeded with zero-seizure");
    } catch {
        // Expected: reverts at withdrawCollateral(0) -> ZeroAssets
    }
}

// For any seizedAssets value, verify effective LIF <= preLIF + dust tolerance
if (ghost_lastSeized > 0 && ghost_lastRepaid > 0) {
    uint256 price = IOracle(PRE_LIQUIDATION_ORACLE).price();
    uint256 seizedValue = ghost_lastSeized.mulDivDown(price, ORACLE_PRICE_SCALE);
    uint256 effectiveLIF = seizedValue.wDivUp(ghost_lastRepaid);
    // effectiveLIF should not exceed preLIF by more than rounding dust
    lte(effectiveLIF, ghost_lastPreLIF + 2,
        "PL-DD-04: effective LIF exceeds computed preLIF");
}

// Verify that totalBorrowAssets change during a preLiquidate call
// is bounded by repaidAssets (nothing extra should change)
Market memory mBefore = MORPHO.market(ID);
ghost_tBABefore = mBefore.totalBorrowAssets;
// ... after preLiquidate ...
Market memory mAfter = MORPHO.market(ID);
// Change should be exactly repaidAssets (decrease)
if (ghost_tBABefore >= mAfter.totalBorrowAssets) {
    uint256 delta = ghost_tBABefore - mAfter.totalBorrowAssets;
    eq(delta, ghost_lastRepaidAssets, "PL-DD-05: unexpected totalBorrowAssets change");
}

// Verify preLCF computation doesn't overflow
// quotient.wMulDown(PRE_LCF_2 - PRE_LCF_1) should not overflow
// Since quotient <= WAD: need PRE_LCF_2 - PRE_LCF_1 < type(uint256).max / WAD
uint256 lcfDiff = PRE_LCF_2 - PRE_LCF_1;
uint256 maxSafe = type(uint256).max / WAD;
lte(lcfDiff, maxSafe, "PL-DD-06: preLCF range could overflow in wMulDown");

// Verify effective LIF at market oracle prices
if (ghost_lastSeized > 0 && ghost_lastRepaid > 0) {
    uint256 marketPrice = IOracle(ORACLE).price();
    uint256 seizedValueMarket = ghost_lastSeized.mulDivDown(marketPrice, ORACLE_PRICE_SCALE);
    uint256 effectiveLIF = seizedValueMarket.wDivUp(ghost_lastRepaid);
    // Effective LIF should be close to nominal preLIF
    // Allow 5% deviation for oracle divergence tolerance
    uint256 maxEffectiveLIF = ghost_lastPreLIF + ghost_lastPreLIF / 20;
    lte(effectiveLIF, maxEffectiveLIF,
        "PL-DD-07: effective LIF at market prices exceeds 5% above nominal preLIF");
}

// Test that seizedAssets > 0 when repaidShares > 0 (repaidShares-path)
// Setup: call preLiquidate(borrower, 0, 1, "")
// If seizedAssets == 0 and repaidShares == 1, the liquidator repaid debt but seized nothing
uint256 repaidSharesInput = 1;
// Simulate: toAssetsDown(1, totalBorrowAssets, totalBorrowShares)
// With virtual shares (1e6) and virtual assets (1): 1 * (totalBorrowAssets + 1) / (totalBorrowShares + 1e6)
// If totalBorrowAssets < totalBorrowShares (early market), this rounds to 0
// Then 0.wMulDown(preLIF) = 0, 0.mulDivDown(ORACLE_PRICE_SCALE, price) = 0
// seizedAssets = 0, but repaidShares = 1 is used for MORPHO.repay
gt(seizedAssets, 0, "PL-M01: zero collateral seized for nonzero repaid shares");

// Verify: if true LTV (computed with full precision, no rounding) <= PRE_LLTV,
// then preLiquidate should revert.
// True LTV = (borrowShares * (totalBorrowAssets + 1) / (totalBorrowShares + 1e6))
//            / (collateral * collateralPrice / ORACLE_PRICE_SCALE)
// But the contract uses toAssetsUp, mulDivDown, wDivUp — all rounding against borrower
// This is BY DESIGN for Morpho (conservative = protect lenders), but worth confirming
// the magnitude of the deviation
uint256 borrowedUp = uint256(position.borrowShares).toAssetsUp(market.totalBorrowAssets, market.totalBorrowShares);
uint256 borrowedDown = uint256(position.borrowShares).toAssetsDown(market.totalBorrowAssets, market.totalBorrowShares);
uint256 collateralUp = uint256(position.collateral).mulDivUp(collateralPrice, ORACLE_PRICE_SCALE);
uint256 collateralDown = uint256(position.collateral).mulDivDown(collateralPrice, ORACLE_PRICE_SCALE);
uint256 ltvMax = borrowedUp.wDivUp(collateralDown);
uint256 ltvMin = borrowedDown.wDivDown(collateralUp);
// The gap between ltvMax and ltvMin shows rounding impact
// If ltvMin <= PRE_LLTV < ltvMax, the position is in the "rounding zone"
lte(ltvMax - ltvMin, 1e12, "PL-M02: rounding spread exceeds 1e-6 WAD");

// After computing preLIF in the contract logic:
// preLIF = quotient.wMulDown(PRE_LIF_2 - PRE_LIF_1) + PRE_LIF_1
// Verify it never exceeds PRE_LIF_2
uint256 ltv = borrowed.wDivUp(collateralQuoted);
uint256 quotient = (ltv - PRE_LLTV).wDivDown(LLTV - PRE_LLTV);
uint256 preLIF = quotient.wMulDown(PRE_LIF_2 - PRE_LIF_1) + PRE_LIF_1;
lte(preLIF, PRE_LIF_2, "PL-M03: preLIF exceeds configured maximum PRE_LIF_2");
// Also check preLCF
uint256 preLCF = quotient.wMulDown(PRE_LCF_2 - PRE_LCF_1) + PRE_LCF_1;
lte(preLCF, PRE_LCF_2, "PL-M03b: preLCF exceeds configured maximum PRE_LCF_2");

// Path A: liquidator specifies seizedAssets=X
uint256 seizedAssetsQuotedA = X.mulDivUp(collateralPrice, ORACLE_PRICE_SCALE);
uint256 repaidSharesA = seizedAssetsQuotedA.wDivUp(preLIF).toSharesUp(totalBorrowAssets, totalBorrowShares);

// Path B: liquidator specifies repaidShares=repaidSharesA, expects to get X back
uint256 seizedAssetsB = repaidSharesA.toAssetsDown(totalBorrowAssets, totalBorrowShares)
    .wMulDown(preLIF).mulDivDown(ORACLE_PRICE_SCALE, collateralPrice);

// seizedAssetsB should be <= X (path B rounds down)
lte(seizedAssetsB, X, "PL-M04a: reverse path gives more collateral than forward path");
// The gap should be bounded
uint256 gap = X - seizedAssetsB;
// For 18-decimal tokens, gap of 1-2 wei is acceptable
// For 6-decimal tokens, gap should still be < 1 unit
lte(gap, 2, "PL-M04b: rounding gap between paths exceeds 2 units");

// For any position that passes the pre-liquidation checks,
// collateralQuoted must be > 0
uint256 collateralQuoted = uint256(position.collateral).mulDivDown(collateralPrice, ORACLE_PRICE_SCALE);
gt(collateralQuoted, 0, "PL-M05: collateralQuoted is zero for non-zero collateral");
// If collateralQuoted == 0 and collateral > 0, we have precision loss

// After computing seizedAssets in the repaidShares path:
// seizedAssets must be > 0 whenever repaidShares > 0
if (repaidSharesInput > 0) {
    uint256 repaidAssetsDown = repaidSharesInput.toAssetsDown(
        market.totalBorrowAssets, market.totalBorrowShares
    );
    uint256 afterLIF = repaidAssetsDown.wMulDown(preLIF);
    uint256 seizedAssets = afterLIF.mulDivDown(ORACLE_PRICE_SCALE, collateralPrice);
    gt(seizedAssets, 0, "PL-M06: zero seized assets for nonzero repaid shares");
}

uint256 ltv = borrowed.wDivUp(collateralQuoted);
uint256 quotient = (ltv - PRE_LLTV).wDivDown(LLTV - PRE_LLTV);
uint256 preLCF = quotient.wMulDown(PRE_LCF_2 - PRE_LCF_1) + PRE_LCF_1;
// preLCF should never exceed PRE_LCF_2 + 1 (rounding tolerance)
lte(preLCF, PRE_LCF_2 + 1, "PL-M07: preLCF exceeds max by more than rounding");

// Verify that collateral * collateralPrice does not overflow
// This is implicitly checked by Solidity 0.8.x, but we want to verify
// that realistic values are safe
uint256 maxCollateral = type(uint128).max;
uint256 maxReasonablePrice = 1e54; // way above any real oracle price
// maxCollateral * maxReasonablePrice = 3.4e38 * 1e54 = 3.4e92 < 1.15e77 ... OVERFLOW
// So even moderately high prices can cause overflow with max collateral
// Test: can we find collateral and price values within Morpho's realistic range
// that cause overflow?
bool overflows = false;
if (collateralPrice > 0 && uint256(position.collateral) > type(uint256).max / collateralPrice) {
    overflows = true;
}
t(!overflows, "PL-M09: multiplication overflow in collateralQuoted computation");

// Verificar que solo MORPHO puede llamar onMorphoRepay
// Intentar llamar directamente desde un address != MORPHO
try preLiquidation.onMorphoRepay(1e18, abi.encode(uint256(1e18), borrower, attacker, bytes(""))) {
    t(false, "PL-AC-01: onMorphoRepay accepted non-Morpho caller");
} catch {
    // Expected: should revert with NotMorpho()
}

// Borrower NO ha autorizado al PreLiquidation contract
// Intentar pre-liquidar debe fallar
bool authorized = morpho.isAuthorized(borrower, address(preLiquidation));
if (!authorized) {
    try preLiquidation.preLiquidate(borrower, seizedAmount, 0, bytes("")) {
        t(false, "PL-AC-02: preLiquidate succeeded without borrower authorization");
    } catch {
        // Expected: Morpho.withdrawCollateral reverts UNAUTHORIZED
    }
}

// Verificar que cualquier address puede llamar preLiquidate
// (no hay modifier restrictivo)
// Este es un test que confirma el diseño, no un bug
// Cualquier msg.sender puede ejecutar preLiquidate si el borrower está en rango
// y ha autorizado el contrato
t(true, "PL-AC-04: preLiquidate is permissionless by design");

// Verificar que el factory permite crear PreLiquidation con preLCF2 > WAD
// Esto no es un bug per se, pero es un riesgo para borrowers inocentes
PreLiquidationParams memory params = preLiquidation.preLiquidationParams();
if (params.preLCF2 > WAD) {
    // preLCF2 > 100% — la posición puede ser completamente pre-liquidada
    // Esto es allowed por diseño pero es agresivo
    t(true, "PL-AC-05: preLCF2 > WAD is allowed, borrower must be aware");
}

// Verificar que PRE_LIQUIDATION_ORACLE puede ser cualquier dirección
// y que el constructor no la valida contra el oráculo del mercado
address marketOracle = address(ORACLE);  // from marketParams
address preLiqOracle = PRE_LIQUIDATION_ORACLE;
// Si son diferentes, el pricing puede diverger
// No es un bug per se — es by design (el README dice que puede ser diferente)
// Pero es un trust assumption que el borrower debe verificar
if (marketOracle != preLiqOracle) {
    // Divergent oracle — higher risk
    t(true, "PL-AC-07: different oracle is by design but risky");
}

// Post-condition: si isAuthorized[borrower][preLiquidation] == false,
// entonces preLiquidate(borrower) DEBE revertir
bool authorized = morpho.isAuthorized(borrower, address(preLiquidation));
if (!authorized) {
    try preLiquidation.preLiquidate(borrower, 1e18, 0, bytes("")) {
        t(false, "PL-AC-08: preLiquidate succeeded after authorization revoked");
    } catch {
        // Expected
    }
}

// Constructor should validate preLCF2 <= some reasonable max (e.g. 10 * WAD)
// Currently no upper bound check exists
// Test: create PreLiquidation with preLCF2 = type(uint256).max, try preLiquidate
t(true, "PL-DOS-02: placeholder — test via unit test");

// Dust amounts self-protect via Morpho's ZeroAssets check
// No invariant needed — this is verified behavior
t(true, "PL-DOS-03: dust amounts self-protect");

// Verify that after every preLiquidate call, the borrower's LTV decreases
// (this should ALWAYS hold given preLIF < 1/LTV in the pre-liq zone)
if (ghost_ltv_before > 0 && ghost_was_preliquidated) {
    Position memory pos = MORPHO.position(ID, borrower);
    Market memory mkt = MORPHO.market(ID);
    uint256 price = IOracle(PRE_LIQUIDATION_ORACLE).price();
    uint256 colQuoted = uint256(pos.collateral).mulDivDown(price, ORACLE_PRICE_SCALE);
    uint256 borrowed = uint256(pos.borrowShares).toAssetsUp(mkt.totalBorrowAssets, mkt.totalBorrowShares);
    uint256 ltv_after = colQuoted > 0 ? borrowed.wDivUp(colQuoted) : type(uint256).max;
    // LTV must decrease after pre-liquidation
    lt(ltv_after, ghost_ltv_before, "PL-D-01: LTV did not improve after pre-liquidation");
}

// Verify quotient <= WAD after every pre-liquidation
Market memory mkt = MORPHO.market(ID);
Position memory pos = MORPHO.position(ID, borrower);
uint256 price = IOracle(PRE_LIQUIDATION_ORACLE).price();
uint256 colQuoted = uint256(pos.collateral).mulDivDown(price, ORACLE_PRICE_SCALE);
uint256 bor = uint256(pos.borrowShares).toAssetsUp(mkt.totalBorrowAssets, mkt.totalBorrowShares);
if (bor > colQuoted.wMulDown(PRE_LLTV) && bor <= colQuoted.wMulDown(LLTV) && colQuoted > 0) {
    uint256 ltv = bor.wDivUp(colQuoted);
    uint256 quotient = (ltv - PRE_LLTV).wDivDown(LLTV - PRE_LLTV);
    lte(quotient, WAD, "PL-D-05: quotient exceeds WAD");
}

// Verify rounding consistency: seized collateral value <= repaid debt * preLIF
// (liquidator never gets more than they should)
if (ghost_seized > 0 && ghost_repaid > 0) {
    uint256 price = IOracle(PRE_LIQUIDATION_ORACLE).price();
    uint256 seizedValue = ghost_seized.mulDivUp(price, ORACLE_PRICE_SCALE);
    uint256 maxValue = ghost_repaid.wMulDown(ghost_preLIF);
    lte(seizedValue, maxValue + 2, "PL-D-07: seized value exceeds repaid * preLIF");
}

// Verify self-pre-liquidation is not profitable
// Track attacker's net position value before and after
// netBefore = collateral_value - borrowed_value
// netAfter = (collateral - seized)_value - (borrowed - repaid)_value + loan_received
// The attacker pays repaidAssets in loan token and receives seizedAssets in collateral
// Net change: seizedAssets_value - repaidAssets = repaidAssets * (preLIF - 1)
// But this came from their OWN collateral, so net position change is:
// -seizedAssets_value + repaidAssets (debt reduced) + seizedAssets_value (collateral received) - repaidAssets (loan paid)
// = 0. Self-liquidation is net zero ignoring gas.
// Actually: position loses seizedAssets collateral and borrowShares debt.
// Liquidator gains seizedAssets collateral and pays repaidAssets loan.
// If same person: net = -seizedAssets(position) + seizedAssets(received) - repaidAssets(paid) + repaidAssets(debt gone)
// = 0 exactly. No profit, no loss (ignoring gas).
t(true, "PL-FL-03: self-pre-liquidation check — always passes, documented as not-a-bug");

// After any preLiquidate call, verify that:
// 1. Borrower's collateral decreased by exactly seizedAssets
// 2. Borrower's debt decreased by exactly repaidShares
// 3. PreLiquidation contract has zero loan token balance (pass-through)
uint256 plBalance = ERC20(LOAN_TOKEN).balanceOf(address(preLiquidation));
eq(plBalance, 0, "PL-FL-04: PreLiquidation should not hold loan tokens");

// Verify that if preLiquidate succeeds, the borrower had authorization set
// This is implicitly enforced by Morpho's withdrawCollateral requiring auth
// No additional invariant needed — Morpho handles this
t(true, "PL-FL-05: authorization is enforced by Morpho.withdrawCollateral");

// Track PreLiquidation's loan token balance — should always be 0 after each tx
uint256 plBalance = ERC20(LOAN_TOKEN).balanceOf(address(preLiquidation));
eq(plBalance, 0, "PL-FL-06: PreLiquidation should not hold loan tokens");

// Track cumulative repaidShares across all preLiquidate calls for same borrower
// Compare against what a SINGLE call would have allowed
uint256 originalBorrowShares = ghost_originalBorrowShares[borrower];
uint256 totalRepaid = ghost_cumulativeRepaidShares[borrower];
// preLCF is at most PRE_LCF_2 (when LTV is near LLTV)
uint256 maxSingleCallRepay = uint256(originalBorrowShares).wMulDown(PRE_LCF_2);
lte(totalRepaid, maxSingleCallRepay,
    "PL-TB-01: cumulative repaid shares exceed single-call preLCF limit");

uint256 preLiqPrice = IOracle(PRE_LIQUIDATION_ORACLE).price();
uint256 morphoPrice = IOracle(ORACLE).price();
// Effective LIF at real prices vs nominal LIF
if (ghost_lastSeizedAssets > 0 && ghost_lastRepaidAssets > 0) {
    uint256 seizedValueReal = ghost_lastSeizedAssets.mulDivDown(morphoPrice, ORACLE_PRICE_SCALE);
    uint256 effectiveLIF = seizedValueReal.wDivUp(ghost_lastRepaidAssets);
    // effectiveLIF should not exceed PRE_LIF_2 by more than 5% (oracle tolerance)
    lte(effectiveLIF, PRE_LIF_2 + PRE_LIF_2 / 20,
        "PL-TB-02: effective LIF exceeds PRE_LIF_2 by >5% due to oracle divergence");
}

// This is a design-level issue — hard to express as a Chimera invariant
// Test: if borrower is pre-liquidatable AND authorized, preLiquidate MUST succeed
bool isAuthorized = MORPHO.isAuthorized(borrower, address(preLiquidation));
if (isAuthorized && ghost_isPreLiquidatable[borrower]) {
    // preLiquidate should NOT revert with UNAUTHORIZED
    t(true, "PL-TB-03: authorization griefing check placeholder");
}

// Track oracle divergence and verify pre-liquidation feasibility
uint256 pricePre = IOracle(PRE_LIQUIDATION_ORACLE).price();
uint256 priceMarket = IOracle(ORACLE).price();
// Divergence should be bounded
uint256 maxPrice = pricePre > priceMarket ? pricePre : priceMarket;
uint256 minPrice = pricePre < priceMarket ? pricePre : priceMarket;
if (maxPrice > 0) {
    uint256 divergencePct = (maxPrice - minPrice) * WAD / maxPrice;
    lte(divergencePct, WAD / 10, "PL-W-02: oracle divergence > 10%");
}

// This is an architectural observation, not a fuzzable invariant.
// Test: verify that authorization revocation blocks preLiquidate
bool wasAuthorized = MORPHO.isAuthorized(borrower, address(preLiquidation));
// Simulate revocation
vm.prank(borrower);
MORPHO.setAuthorization(address(preLiquidation), false);
// preLiquidate should now revert
try preLiquidation.preLiquidate(borrower, 0, 1, "") {
    t(false, "PL-W-04: preLiquidate should revert without auth");
} catch {}
// Restore state
if (wasAuthorized) {
    vm.prank(borrower);
    MORPHO.setAuthorization(address(preLiquidation), true);
}

// Property: PreLiquidation loan token balance should always be 0 in steady state
uint256 balance = ERC20(LOAN_TOKEN).balanceOf(address(preLiquidation));
eq(balance, 0, "PL-W-05: loan tokens stuck in PreLiquidation contract");

// Property: any functional PreLiquidation should be registered in factory
// This is NOT enforceable on-chain — it's an off-chain trust assumption
bool registered = factory.isPreLiquidation(address(preLiquidation));
t(registered, "PL-W-08: PreLiquidation not registered in factory");

description:
En MagicSpend._validateRequest() línea 347:
  uint256 maxAllowed = address(this).balance / maxWithdrawDenominator;
Si maxWithdrawDenominator es 0, esta división revierte con panic 0x12
(división por cero) en Solidity 0.8.

La función _setMaxWithdrawDenominator (línea 329) no valida que
newDenominator > 0. El constructor tampoco valida:
  constructor(address owner_, uint256 maxWithdrawDenominator_) {
      _setMaxWithdrawDenominator(maxWithdrawDenominator_);
  }
Si se deploya con denominador=0 o el owner llama setMaxWithdrawDenominator(0),
todas las operaciones de ETH quedan DoS-eadas.

Única escapatoria: ownerWithdraw() no llama _validateRequest, así que el
owner puede recuperar fondos directamente. Pero todos los usuarios quedan bloqueados.

solidity:
// Invariant: maxWithdrawDenominator siempre > 0
function invariant_denominatorNonZero() internal view {
    t(magicSpend.maxWithdrawDenominator() != 0, "CSW-M-03: maxWithdrawDenominator=0 -> DoS");
}

// Test: deploy con denominador=0 y verificar DoS
function test_zeroDenominatorDoS() internal {
    uint256 denom = magicSpend.maxWithdrawDenominator();
    if (denom == 0) {
        // Intentar withdraw debe fallar
        t(false, "CSW-M-03: denominador 0 activo -> DoS en curso");
    }
}

// Invariant: expiry en validationData debe ser consistente con el comportamiento esperado
function invariant_expirySemantics(uint48 expiry) internal view {
    // Si expiry=0, el paymaster acepta pero withdraw directo rechaza
    // Documentar la discrepancia
    if (expiry == 0) {
        // En modo paymaster: válido indefinidamente (validUntil=0 en ERC-4337)
        // En modo withdraw directo: siempre rechaza (Expired)
        t(false, "CSW-M-04: expiry=0 crea comportamiento asimetrico");
    }
}

description:
En _validateRequest() línea 347-350:
  uint256 maxAllowed = address(this).balance / maxWithdrawDenominator;
  if (withdrawRequest.asset == address(0) && withdrawRequest.amount > maxAllowed) {
      revert WithdrawTooLarge(withdrawRequest.amount, maxAllowed);
  }
Si maxWithdrawDenominator es type(uint256).max o cualquier valor > balance,
la división entera trunca a 0. Cualquier request con amount > 0 falla con
WithdrawTooLarge(amount, 0). El paymaster queda efectivamente DoS-eado
para ETH sin causar un revert técnico.

Similar a CSW-M-03 pero vía truncamiento en lugar de division-by-zero.

