// Invariant: maxAllowed debe ser > 0 si el paymaster tiene balance y se espera operativo
function invariant_maxAllowedNonZero() internal view {
    uint256 denom = magicSpend.maxWithdrawDenominator();
    uint256 balance = address(magicSpend).balance;
    if (balance > 0 && denom > 0) {
        uint256 maxAllowed = balance / denom;
        t(maxAllowed > 0, "CSW-M-06: maxAllowed trunca a 0 -> DoS por configuracion extrema");
    }
}

// Verificar bidireccionalidad del nonce encoding/decoding
function invariant_nonceDecomposition(uint256 nonce) internal pure {
    uint256 key = nonce >> 64;
    uint256 seq = nonce & type(uint64).max;
    eq((key << 64) | seq, nonce, "CSW-M-07: nonce decomposition no es bijective");
}

// Replayable calls DEBEN usar key=8453, otras no
function invariant_nonceKeyConsistency(uint256 nonce, bool isReplayable) internal pure {
    uint256 key = nonce >> 64;
    if (isReplayable) {
        eq(key, 8453, "CSW-M-07: replayable call con key != REPLAYABLE_NONCE_KEY");
    } else {
        t(key != 8453, "CSW-M-07: non-replayable call con key == REPLAYABLE_NONCE_KEY");
    }
}

// Ghost: rastrear total comprometido en validaciones del bloque actual
uint256 internal ghost_totalCommittedCurrentBlock;
uint256 internal ghost_currentBlockNumber;

function invariant_rateLimitPerBlock() internal view {
    uint256 maxAllowed = address(magicSpend).balance / magicSpend.maxWithdrawDenominator();
    // El total comprometido en un bloque no debería exceder maxAllowed
    // (esto viola el invariante si hay coordinación multi-usuario)
    lte(ghost_totalCommittedCurrentBlock, maxAllowed,
        "CSW-M-09: total comprometido en bloque excede maxAllowed individual");
}

// Ghost: densidad de owners (ownerCount / nextOwnerIndex)
function invariant_ownerIndexDensity() internal view {
    uint256 next = wallet.nextOwnerIndex();
    uint256 count = wallet.ownerCount();
    uint256 removed = wallet.removedOwnersCount();
    // Consistencia matemática
    eq(count, next - removed, "CSW-M-10: ownerCount no coincide con indices");
    // Densidad informacional (no un bug, solo métrica)
    // Si next > 100 y count < next/10, hay fragmentación severa
}

// Property: si nextOwnerIndex == 0, initialize es callable por cualquiera → VULNERABLE
function invariant_eip7702_init_front_run_window() public view {
    // Si la wallet fue delegada via EIP-7702 con storage virgen:
    // cualquier llamante puede inicializarla ANTES que el dueño legítimo
    if (wallet.nextOwnerIndex() == 0) {
        // Esta condición no debe ocurrir en una wallet deployada via factory
        // pero puede ocurrir en EIP-7702 delegation
        t(false, "CSW-W-01: wallet unitialised — vulnerable to init front-run");
    }
}

// Property: ownerCount debe conservarse después de removeOwnerAtIndex cross-chain
function test_crosschain_remove_consistent(uint256 targetIndex) public {
    uint256 ownerCountBefore = wallet.ownerCount();
    bytes memory ownerAtTarget = wallet.ownerAtIndex(targetIndex);

    if (ownerAtTarget.length > 0 && ownerCountBefore > 1) {
        // Simular removeOwnerAtIndex cross-chain
        vm.prank(address(entryPoint));
        wallet.executeWithoutChainIdValidation(
            _encodeRemoveOwner(targetIndex, ownerAtTarget)
        );
        uint256 ownerCountAfter = wallet.ownerCount();
        eq(ownerCountAfter, ownerCountBefore - 1, "CSW-W-02: owner count mismatch after cross-chain remove");
    }
}

// Track: suma de todos los excess antes y después de un bundle multi-op
function invariant_user_receives_full_excess(address user) public view {
    uint256 totalExcessExpected = ghost_totalExcessExpected[user];
    uint256 actualReceived = ghost_totalReceived[user];
    // El usuario debe recibir al menos el excess total comprometido
    gte(actualReceived, totalExcessExpected, "CSW-W-04: user received less than promised excess");
}

// Verificar que validateUserOp con ownerIndex inválido retorna 1 (no revierte)
function test_removed_owner_index_returns_sigfail_not_revert() public {
    // Remover owner en idx 1
    vm.prank(address(wallet));
    wallet.removeOwnerAtIndex(1, abi.encode(owner1));

    // Intentar validar con ownerIndex=1 (removido)
    bytes memory badSig = abi.encode(
        CoinbaseSmartWallet.SignatureWrapper({ownerIndex: 1, signatureData: bytes("dummy")})
    );
    UserOperation memory op = _buildUserOp(badSig);

    // Debería retornar 1 (sigfail), no revertir
    bool didRevert = false;
    uint256 result;
    try wallet.validateUserOp(op, keccak256("hash"), 0) returns (uint256 r) {
        result = r;
    } catch {
        didRevert = true;
    }
    t(!didRevert, "CSW-W-05: should return 1, not revert for missing owner index");
    eq(result, 1, "CSW-W-05: should return sigfail=1");
}

// Property: el balance del wallet no debe decrementar por más de lo explícitamente
// autorizado en el calldata del UserOp
function invariant_balance_decrease_authorized() public view {
    // Difícil de testear directamente — el firmante debe revisar el calldata completo
    // El invariante es de proceso (UX/social), no de código
    t(true, "CSW-W-06: calldata review required before signing executeBatch");
}

// Verificar que la dirección predicha y la dirección real coinciden
function test_predeployed_eth_is_not_trapped(bytes[] memory owners, uint256 nonce) public {
    address predicted = factory.getAddress(owners, nonce);
    vm.deal(predicted, 10 ether); // pre-fund

    CoinbaseSmartWallet deployed = factory.createAccount{value: 0}(owners, nonce);

    // El ETH pre-enviado debe estar en el wallet desplegado
    eq(address(deployed), predicted, "CSW-W-07: address prediction must match");
    gte(address(deployed).balance, 10 ether, "CSW-W-07: pre-sent ETH must be in wallet");
}

// Invariant crítico: ownerCount nunca debe llegar a 0
function invariant_always_has_owner() public view {
    t(wallet.ownerCount() > 0, "CSW-W-08: wallet has no owners — permanently locked");
}

// Post-upgrade: verificar que los owners del pre-upgrade siguen siendo válidos
function invariant_owners_preserved_after_upgrade() public view {
    // Todos los owners antes del upgrade deben seguir siendo reconocidos
    for (uint256 i = 0; i < ghost_ownerCount; i++) {
        bytes memory expectedOwner = ghost_ownerAtIndex[i];
        if (expectedOwner.length > 0) {
            t(wallet.isOwnerBytes(expectedOwner), "CSW-W-10: owner lost after upgrade");
        }
    }
}

// En la implementación directa (no proxy), address(0) es owner
function test_impl_address_zero_owner() public {
    bool zeroIsOwner = implContract.isOwnerAddress(address(0));
    // Esto es TRUE en la implementación — pero las llamadas desde address(0) son
    // imposibles en condiciones normales
    t(!zeroIsOwner, "CSW-W-12: address(0) should not be owner on impl contract");
}

