// Test: ownerIndex con slot removido causa revert en validateUserOp
function testRemovedOwnerIndexCausesRevertNotReturn1() public {
    // Agregar y luego remover un owner
    vm.prank(address(wallet));
    wallet.addOwnerAddress(bob);  // index 1
    vm.prank(address(wallet));
    wallet.removeOwnerAtIndex(1, abi.encode(bob)); // slot 1 ahora vacio

    bytes memory badSig = abi.encode(
        CoinbaseSmartWallet.SignatureWrapper({
            ownerIndex: 1,  // slot removido -> bytes("")
            signatureData: bytes("arbitrary")
        })
    );

    UserOperation memory userOp;
    userOp.sender = address(wallet);
    userOp.signature = badSig;
    userOp.nonce = 0;
    userOp.callData = abi.encodeCall(wallet.execute, (address(0), 0, ""));

    // Debe REVERTIR con InvalidOwnerBytesLength
    // En lugar de retornar 1 (lo correcto segun ERC-4337)
    vm.expectRevert(
        abi.encodeWithSelector(MultiOwnable.InvalidOwnerBytesLength.selector, bytes(""))
    );
    vm.prank(ENTRY_POINT);
    wallet.validateUserOp(userOp, bytes32(0), 0);
}

// Verificar: firma para ERC-1271 NO puede usarse en validateUserOp
function testERC1271SigNotReusableInValidateUserOp() public {
    bytes32 appHash = keccak256("some_dapp_hash");
    bytes32 replaySafe = wallet.replaySafeHash(appHash);

    (uint8 v, bytes32 r, bytes32 s) = vm.sign(ownerKey, replaySafe);
    bytes memory sig = abi.encodePacked(r, s, v);
    bytes memory wrappedSig = abi.encode(
        CoinbaseSmartWallet.SignatureWrapper({ownerIndex: 0, signatureData: sig})
    );

    // ERC-1271 funciona
    assertEq(wallet.isValidSignature(appHash, wrappedSig), bytes4(0x1626ba7e));

    // Misma firma en validateUserOp con appHash como userOpHash -> debe retornar 1
    UserOperation memory userOp;
    userOp.sender = address(wallet);
    userOp.signature = wrappedSig;
    userOp.callData = abi.encodeCall(wallet.execute, (address(0), 0, ""));

    vm.prank(ENTRY_POINT);
    uint256 result = wallet.validateUserOp(userOp, appHash, 0);
    // La firma fue para replaySafeHash(appHash), NO para appHash
    // -> debe retornar 1 (invalid sig)
    assertEq(result, 1, "CSW-D-05: ERC-1271 sig must not work in validateUserOp");
}

// Verificar: el check de implementacion es suficiente
function testUpgradeCheckCodeLength() public {
    // Deploy de implementacion maliciosa
    address malImpl = address(new MaliciousImpl());

    bytes[] memory calls = new bytes[](1);
    calls[0] = abi.encodeCall(
        UUPSUpgradeable.upgradeToAndCall,
        (malImpl, "")
    );

    UserOperation memory userOp;
    userOp.nonce = uint256(REPLAYABLE_NONCE_KEY) << 64;
    userOp.callData = abi.encodeCall(
        wallet.executeWithoutChainIdValidation,
        (calls)
    );

    // validateUserOp verifica malImpl.code.length > 0
    // Si malImpl tiene codigo (aunque malicioso), la validacion PASA
    // -> Invariante violada: code.length > 0 no garantiza que la impl sea la correcta
    vm.prank(ENTRY_POINT);
    // Esta linea NO deberia revertir con InvalidImplementation
    // (malImpl tiene codigo -> check pasa)
    uint256 result = wallet.validateUserOp(userOp, bytes32(0), 0);
    // La firma sera invalida (return 1) pero el check de implementacion PASO
}

