// isValidWithdrawSignature checks current owner()
function isValidWithdrawSignature(address account, WithdrawRequest memory withdrawRequest)
    public view returns (bool)
{
    return SignatureCheckerLib.isValidSignatureNow(
        owner(), // <-- current owner, changes on transferOwnership
        getHash(account, withdrawRequest),
        withdrawRequest.signature
    );
}

// Un wallet EIP-7702 recien delegado debe ser inicializado atomicamente
// o protegido contra frontrunning de initialize()
// Invariante: si nextOwnerIndex == 0, nadie puede llamar initialize() excepto
// el propio EOA owner (msg.sender == address(this))
if (wallet.nextOwnerIndex() == 0) {
    // VULNERABLE: cualquiera puede inicializar
    t(false, "CSW-TB-01: initialize() callable by anyone when storage is empty (EIP-7702 frontrun)");
}
// La mitigacion correcta seria: require msg.sender == address(this) en initialize()
// O usar un initializer que solo puede ser llamado atomicamente con el set EIP-7702

// En un sistema multi-owner, ningun owner individual deberia poder remover a otro
// sin consenso. Invariante (solo aplicable si el protocolo promete multi-sig):
uint256 ownerCountBefore = wallet.ownerCount();
// ... un owner ejecuta removeOwnerAtIndex via execute() ...
uint256 ownerCountAfter = wallet.ownerCount();
// Si esto pasa con una sola firma de owner, el modelo multi-sig esta roto
t(ownerCountAfter == ownerCountBefore, "CSW-TB-02: single owner removed another owner (multi-sig violated)");

// El rate limiting debe ser efectivo por bundle, no solo por op
// Invariante: despues de cualquier bundle, MagicSpend.balance >= balance_antes * (1 - 1/denom)
uint256 balBefore = address(magicSpend).balance;
uint256 denom = magicSpend.maxWithdrawDenominator();
// ... bundle procesado ...
uint256 balAfter = address(magicSpend).balance;
uint256 maxAllowedDrain = balBefore / denom;
// Esto FALLA si N ops se bundlean — el drain puede ser N * maxAllowedDrain
lte(balBefore - balAfter, maxAllowedDrain * 2, "CSW-TB-03: maxWithdrawDenominator bypassed via multi-op bundle");

// isValidSignature NUNCA debe revertir — debe retornar 0xffffffff para cualquier
// input invalido incluyendo ownerIndex de owners eliminados
bytes memory invalidSig = abi.encode(uint256(9999), bytes(""));
try CoinbaseSmartWallet(payable(wallet)).isValidSignature(bytes32(0), invalidSig) returns (bytes4 result) {
    eq(uint32(result), 0xffffffff, "CSW-TB-04: should return 0xffffffff for invalid owner index");
} catch {
    t(false, "CSW-TB-04: isValidSignature reverted instead of returning 0xffffffff");
}

// Test: passkey owner no puede llamar addOwnerAddress directamente
// Setup: wallet con solo passkey owner (x, y) -- ownerBytes.length == 64
// Un passkey no tiene una direccion Ethereum -- no puede ser msg.sender EOA

// Invariante: si todos los owners son passkeys (length == 64),
// ninguna EOA puede pasar _checkOwner() sin ser address(this)
function check_passkeyOwnerCannotDirectCall(address nonOwnerEOA) external {
    uint256 count = wallet.ownerCount();
    bool hasEOAOwner = false;
    uint256 nextIdx = wallet.nextOwnerIndex();
    for (uint256 i = 0; i < nextIdx; i++) {
        bytes memory ownerBytes = wallet.ownerAtIndex(i);
        if (ownerBytes.length == 32) { hasEOAOwner = true; break; }
    }

    if (!hasEOAOwner && count > 0) {
        // Ninguna EOA es owner -- toda llamada directa a onlyOwner debe revertir
        try wallet.addOwnerAddress{gas: 100000}(nonOwnerEOA) {
            t(false, "CSW-A-01: passkey-only wallet acepta addOwnerAddress sin EntryPoint");
        } catch {}
    }
}

// Invariante: despues de removeOwnerAtIndex, el owner especificado ya no es owner
// y el ownerCount disminuyo exactamente en 1
function check_removeOwnerCrossChainCorrectness(
    uint256 index,
    bytes calldata expectedOwner
) external {
    bytes memory actualOwner = wallet.ownerAtIndex(index);
    if (actualOwner.length == 0) return; // ya removido

    bool wasOwner = wallet.isOwnerBytes(expectedOwner);
    uint256 countBefore = wallet.ownerCount();

    // Si expectedOwner != actualOwner, debe revertir con WrongOwnerAtIndex
    if (keccak256(actualOwner) != keccak256(expectedOwner)) {
        try wallet.removeOwnerAtIndex{gas: 100000}(index, expectedOwner) {
            t(false, "CSW-A-02: removeOwnerAtIndex con owner incorrecto no revertio");
        } catch {}
    }

    // Post-condicion consistencia de contadores
    uint256 calculatedCount = wallet.nextOwnerIndex() - wallet.removedOwnersCount();
    eq(wallet.ownerCount(), calculatedCount,
        "CSW-A-02: ownerCount inconsistente con nextOwnerIndex - removedOwnersCount");
