// Invariant: after any compoundRewards() call, if the position has a loan,
// the vault health check must still pass.
// This is a stateful invariant requiring vault integration.
function invariant_compoundDoesNotDestroyHealth(uint256 tokenId) public view returns (bool) {
    if (vault.loans(tokenId) == 0) return true; // no debt, skip
    (bool isHealthy,,,) = vault.loanInfo(tokenId);
    // After compound, position must still be healthy OR must have been healthy before compound.
    // If isHealthy is false after a direct owner compound call, this is a bug.
    (, uint256 fullValue, uint256 collateralValue,,) = vault.loanInfo(tokenId);
    uint256 debt = vault.loans(tokenId); // debtShares, need exchange rate
    return collateralValue >= debt; // simplified
}

