// Invariant: withdrawer cannot call withdrawBalances() on accumulated protocol fees
// within the same tx as setWithdrawer() was changed.
// This is a timelock/governance issue, not an invariant.
// For fuzzing: track that accumulated protocol reward (rewardAmount0 + rewardAmount1 across
// all compound calls) is only ever claimable by the originally configured withdrawer.
function invariant_protocolFeesIntact() public view returns (bool) {
    // Ghost var: ghost_accumulated_protocol_token0_fees, ghost_accumulated_protocol_token1_fees
    // After all compound calls, GaugeManager must hold AT LEAST these amounts.
    // If balance drops below accumulated fees without a withdrawBalances call, it's a bug.
    return (
        IERC20(trackedToken0).balanceOf(address(gaugeManager)) >= ghost_protocol_fees_token0 &&
        IERC20(trackedToken1).balanceOf(address(gaugeManager)) >= ghost_protocol_fees_token1
    );
}

// Invariant: no allowed transformer can act as msg.sender to pass _requireVaultOrOwner()
// for a position they do not own.
// In practice: transformerAllowList entries are contracts, not user EOAs. Position owners
// are EOAs or contract wallets. The intersection should be empty.
function invariant_transformerCannotImpersonateOwner(uint256 tokenId, address transformer) public view returns (bool) {
    if (!vault.transformerAllowList(transformer)) return true;
    // If transformer is in allowlist, it should NOT equal vault.ownerOf(tokenId)
    // for any active position.
    return transformer != vault.ownerOf(tokenId);
}

