// Property: if tokenIdToGauge[tokenId] != address(0), then vault.ownerOf(tokenId) != address(0).
// An orphaned staked position (staked but no vault owner) is impossible.
function invariant_staked_position_has_vault_owner(uint256 tokenId) public view returns (bool) {
    address gauge = gaugeManager.tokenIdToGauge(tokenId);
    if (gauge == address(0)) return true; // not staked, skip
    address owner = vault.ownerOf(tokenId);
    return owner != address(0);
}

// Property: deadline passed to compoundRewards must be > block.timestamp
