// Invariant: for any staked tokenId, the gauge in tokenIdToGauge must still be
// the canonical gauge for that position's pool
function invariant_staked_gauge_is_current(uint256 tokenId) external view {
    address storedGauge = IGaugeManager(gaugeManager).tokenIdToGauge(tokenId);
    if (storedGauge == address(0)) return;
    (,, address token0, address token1, uint24 feeOrTickSpacing,,,,,,,) =
        nonfungiblePositionManager.positions(tokenId);
    // Get the pool
    IUniswapV3Pool pool = _getPool(token0, token1, feeOrTickSpacing);
    address currentGauge = IGaugeManager(gaugeManager).poolToGauge(address(pool));
    // If gauge has been migrated, staked positions are orphaned
    assert(storedGauge == currentGauge);
}

// Invariant: protocol reward is taken proportional to liquidity actually added
// If no liquidity added, protocol reward = 0 (by design). This is exploitable.
function invariant_compound_protocol_reward_nonnegative(
    uint256 tokenId, uint256 aeroSplitBps
) external {
    uint256 aero = IGauge(tokenIdToGauge[tokenId]).earned(tokenId);
    if (aero == 0) return;
    uint256 protocolToken0Before = IERC20(token0).balanceOf(address(gaugeManager));
    uint256 protocolToken1Before = IERC20(token1).balanceOf(address(gaugeManager));
    vault.compoundRewards(tokenId, 0, aeroSplitBps, block.timestamp);
    uint256 protocolToken0After = IERC20(token0).balanceOf(address(gaugeManager));
    uint256 protocolToken1After = IERC20(token1).balanceOf(address(gaugeManager));
    // Protocol reward can legitimately be 0 if position is out of range
    // so this invariant would only fire if protocol reward is NEGATIVE (impossible)
    assert(protocolToken0After >= protocolToken0Before);
    assert(protocolToken1After >= protocolToken1Before);
}

// Fork PoC structure (pseudocode — needs real Aerodrome gauge on Base fork)
// 1. Create position, stake, wait N blocks for fee accrual
// 2. Drop oracle price to make position unhealthy
// 3. Liquidator calls liquidate()
// 4. Assert: liquidator received value <= liquidationValue + dust
function test_liquidation_overpayment_staked_position() external {
    // Setup: stake position with fees accrued in gauge
    uint256 tokenId = _createAndStakePosition();
    _accrueFees(tokenId, 30 days);
    _dropPrice(10); // make unhealthy

    uint256 liquidatorBalanceBefore = asset.balanceOf(liquidator);
    uint256 liquidatorTokensBefore = _positionValueOf(liquidator);

    vm.prank(liquidator);
    vault.liquidate(LiquidateParams(tokenId, liquidator, 0, 0, block.timestamp));

    uint256 liquidatorCost = liquidatorBalanceBefore - asset.balanceOf(liquidator);
    uint256 liquidatorReceived = _positionValueOf(liquidator) - liquidatorTokensBefore;

    // Invariant: liquidator profit <= MAX_LIQUIDATION_PENALTY * debt
    uint256 maxAllowedProfit = debt * MAX_LIQUIDATION_PENALTY_X32 / Q32;
    assertLe(liquidatorReceived - liquidatorCost, maxAllowedProfit + 1 ether);
}

