function property_collectFees_uses_correct_vesting_ticks() public {
    // Setup: add a vesting position, then rebalance so main ticks shift
    _addVestingPosition(1e7, 50_000e6, 7 days);

    // force time forward and rebalance to shift main ticks
    skip(strategy.rebalanceInterval() + 1);
    _rebalance();

    // Capture vesting position ticks before collectFees
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper for the vesting position.
    // After rebalance, vestPosition.tickUpper may differ from mainPosition.tickUpper.
    // This property asserts they should be equal (they will fail when they diverge).
    // A correct implementation would use vestPosition.tickUpper consistently.
    t(
        vp.tickUpper == mp.tickUpper,
        "vesting tickUpper diverged from main after rebalance — collectFees will use wrong ticks"
    );
}

function property_secondary_position_is_oor() public {
    // After rebalance, secondary position should be out-of-range
    // (i.e., current tick should be outside [secondaryTickLower, secondaryTickUpper])
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    (, int24 currentTick,,,,,) = POOL.slot0();

    bool oor = (currentTick < sp.tickLower) || (currentTick >= sp.tickUpper);
    t(oor, "secondary position is not out of range after rebalance");
}

function property_vesting_terminates_after_duration() public {
    uint256 duration = 7 days;
    _addVestingPosition(1e7, 50_000e6, duration);

    // Skip to end of vesting period
    skip(duration + 1);

    // Call collectFees to trigger _withdrawPartOfVestingPosition
    strategy.collectFees();

    // After end time, vesting should be complete
    t(!strategy.ongoingVestingPosition(), "vesting position not cleared after duration");
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    eq(uint256(vp.remainingLiquidity), 0, "remaining liquidity not zero after vesting end");
}

