    if (!leverager.isLiquidateable(posId)) return;

    address fr = leverager.feeRecipient();
    uint256 frBal0Before = wbtc.balanceOf(fr);
    uint256 frBal1Before = usdc.balanceOf(fr);

    ILeverager.LiquidateParams memory lp;
    lp.id = posId;
    lp.minAmount0 = 0;
    lp.minAmount1 = 0;
    lp.hasToSwap = false;

    vm.prank(liquidator);
    leverager.liquidatePosition(lp);

    uint256 frBal0After = wbtc.balanceOf(fr);
    uint256 frBal1After = usdc.balanceOf(fr);

    // If the liquidation was profitable, at least one fee token should be nonzero
