function property_vesting_releases_proportionally() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    uint256 totalDuration = vp.endTs - vp.startTs;
    uint256 elapsed = block.timestamp > vp.endTs
        ? totalDuration
        : block.timestamp - vp.startTs;

    uint256 expectedReleased = uint256(vp.initialLiquidity) * elapsed / totalDuration;
    uint256 actualReleased = uint256(vp.initialLiquidity) - uint256(vp.remainingLiquidity);

    // Allow 1% tolerance for rounding
    uint256 tolerance = uint256(vp.initialLiquidity) / 100 + 1;
    uint256 diff = actualReleased > expectedReleased
        ? actualReleased - expectedReleased
        : expectedReleased - actualReleased;

    lte(diff, tolerance,
        "TBH-008: vested liquidity released deviates >1% from proportional schedule (accumulation error)");
}

