// Verify compounding accuracy at max rate
function invariant_compound_accuracy_at_max_rate() public {
  uint256 maxRate = reserve.borrowingRateConfig.maxBorrowingRate;
  uint256 oneYear = 365 days;
  uint256 compounded = InterestRateUtils.calculateCompoundedInterest(
    maxRate, uint128(block.timestamp), block.timestamp + oneYear
  );
  // True exponential at 150% = e^1.5 * PRECISION ≈ 4.4817e27
  // Taylor should be within 10% of true value
  uint256 trueExp = 4481689070 * 1e18; // approximate e^1.5 * 1e27
  uint256 error = trueExp > compounded ? trueExp - compounded : compounded - trueExp;
  uint256 errorPct = error * 10000 / trueExp;
  lte(errorPct, 1000, "DD-LP-03: compound interest error > 10% at max rate");
}

// Measure dead share value capture over time
function invariant_dead_share_value() public {
  uint256 deadBalance = IERC20(yTokenAddress).balanceOf(DEAD_ADDRESS);
  uint256 rate = reserve.yTokenToReserveExchangeRate();
  uint256 deadValue = deadBalance * rate / PRECISION;
  // Dead value should be bounded relative to total liquidity
  (uint256 totalLiq,) = reserve.totalLiquidityAndBorrows();
  if (totalLiq > 0) {
    uint256 deadPct = deadValue * 10000 / totalLiq;
    // In a healthy pool, dead shares should be < 1% of total
