function property_getTokenIn_multipool_no_infinite_gas() public {
    // Construct a 2-hop path: wbtc -> fee -> weth -> fee -> usdc
    // _getTokenIn should return wbtc (last tokenIn in ExactOutput = first address in reversed path)
    // But due to the bug it returns weth (second address in first pool decode) and loops infinitely
    // We verify this by attempting to open a position with a 2-hop path and checking it doesn't OOG
    uint256 amount0In = 1 * ONE_WBTC;
    uint256 vault0In  = 2 * ONE_WBTC;
    uint256 amount1In = 100_000 * ONE_USDC;

    deal(address(wbtc), attacker, amount0In);
    deal(address(usdc), attacker, amount1In);

    vm.startPrank(attacker);
    wbtc.approve(address(leverager), type(uint256).max);
    usdc.approve(address(leverager), type(uint256).max);

    // Build a 2-pool ExactOutput path: usdc (out) <- fee3000 <- weth <- fee3000 <- wbtc (in)
    // Reversed encoding for exactOutput: tokenOut, fee, midToken, fee, tokenIn
    bytes memory multiHopPath = abi.encodePacked(
        address(usdc),   uint24(3000),
        address(weth),   uint24(3000),
        address(wbtc)
    );

    IMainnetRouter.ExactOutputParams memory eoParams;
    eoParams.path            = multiHopPath;
    eoParams.recipient       = address(leverager);
    eoParams.deadline        = block.timestamp + 1 hours;
    eoParams.amountOut       = 0;
    eoParams.amountInMaximum = type(uint256).max;

    ILeverager.LeverageParams memory lp;
    lp.amount0In      = amount0In;
    lp.amount1In      = amount1In;
    lp.vault0In       = vault0In;
    lp.vault1In       = amount1In;
    lp.vault          = address(vault);
    lp.denomination   = address(wbtc);
    lp.maxBorrowAmount = ONE_WBTC;
    lp.min0in         = 0;
    lp.min1in         = 0;
    lp.swapParams1    = abi.encode(eoParams);

    // This should revert due to OOG or wrong-tokenIn revert, NOT silently succeed
    // If it succeeds, the denomination check was bypassed
    bool success;
    try leverager.openLeveragedPosition(lp) {
        success = true;
    } catch {
        success = false;
    }
    vm.stopPrank();

    // The property: a multi-hop path with tokenIn != denomination must never succeed
    t(!success, "LIB-01: multi-hop path bypassed denomination tokenIn check");
}

