function property_fullmath_muldiv_correctness() public pure {
    // Test case where a*b > 2^256 (prod1 != 0), requiring the 512-bit path
    // Choose values that cause overflow: a = 2^200, b = 2^200, denom = 2^200 - 1
    // Expected: floor((2^200 * 2^200) / (2^200 - 1)) = 2^200 + 1 (approximately)
    // We use a known-correct reference: mulDiv(2^128, 2^128+1, 2^128) should = 2^128+1
    uint256 a = type(uint128).max; // 2^128 - 1
    uint256 b = type(uint128).max; // 2^128 - 1
    uint256 denom = type(uint128).max / 2 + 1; // odd denominator to trigger 512-bit path

    // This is a pure computation check - we just verify it doesn't revert
    // and produces a result consistent with a/denom * b
    uint256 result;
    bool success = true;
    try this._callMulDiv(a, b, denom) returns (uint256 r) {
        result = r;
    } catch {
        success = false;
    }

    // If it reverted that's also a bug
    t(success, "LIB-04: FullMath.mulDiv reverted on valid large input");

    // Sanity: result should be approximately a (since b ~= denom)
    // result = floor((a * b) / denom). With b == denom, result should = a
    // We check within 0.01% tolerance
    if (success) {
        uint256 expected = a; // since b == denom approximately
        uint256 diff = result > expected ? result - expected : expected - result;
        t(diff * 10000 / expected < 1, "LIB-04: FullMath.mulDiv result deviates more than 0.01%");
    }
}

function _callMulDiv(uint256 a, uint256 b, uint256 denom) external pure returns (uint256) {
    return FullMath.mulDiv(a, b, denom);
}

