        50_000e6,     // 50k USDC collateral
        100_000e6     // 100k USDC total vault deposit (borrow 50k USDC)
    );

    uint256 usdcBefore = usdc.balanceOf(depositor);
    uint256 wbtcBefore = wbtc.balanceOf(depositor);

    // Snapshot what the position owes
    ILeverager.Position memory pos = leverager.getPosition(posId);
    uint256 bIndexBefore = lendingPool.getCurrentBorrowingIndex(address(usdc));
    uint256 owedFull = pos.borrowedAmount * bIndexBefore / pos.borrowedIndex;
    uint256 owedHalf = owedFull / 2;

    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.5e18;
    wp.minAmount0 = 0;
    wp.minAmount1 = 0;
    wp.hasToSwap = false;

    vm.prank(depositor);
    leverager.withdraw(wp);

    uint256 usdcAfter = usdc.balanceOf(depositor);
    uint256 wbtcAfter = wbtc.balanceOf(depositor);

    // Net USDC change for depositor = received - paid
    // If usdcAfter > usdcBefore: depositor received more USDC than they put in net
    // The maximum net USDC the user should ever receive is the vault's USDC share minus owed USDC
    // Conservatively: net USDC gain <= 50,000e6 (half the original collateral portion)
    // The bug would give them ~50,000e6 back WITHOUT deducting ~25,000e6 of debt
    int256 netUsdc = int256(usdcAfter) - int256(usdcBefore);
    // Net USDC to user should be at most ~(vault_usdc_share/2 - owedHalf)
    // If netUsdc > 0 (user gained net USDC) that means the debt wasn't properly deducted
    // Allow up to owedHalf as net gain (e.g., if collateral > debt portion)
    t(netUsdc <= int256(owedHalf), "DH-01: depositor received excess USDC without paying matching debt (token1 branch bug)");
}

