    if (!liq) return; // guard: only run assertion when position is actually liquidatable

    // Record fee recipient balances before liquidation
    uint256 frWbtcBefore = wbtc.balanceOf(feeRecipient);
    uint256 frUsdcBefore = usdc.balanceOf(feeRecipient);

    ILeverager.LiquidateParams memory lp;
    lp.id = posId;
    lp.minAmount0 = 0;
    lp.minAmount1 = 0;
    lp.hasToSwap = false;

    // Liquidator needs USDC to cover any owed remainder
    deal(address(usdc), liquidator, 200_000e6);
