function property_withdraw_with_swap_never_underflows() public {
    uint256 posId = _openSimpleWbtcPosition(
        depositor,
        1e7,
        2e7,
        50_000e6
    );

    ILeverager.Position memory pos = leverager.getPosition(posId);

    // Build withdraw params with amountIn > any possible amountOut0
    // to test whether the contract handles this gracefully (reverts with clear error
    // rather than arithmetic underflow)
    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.5e18;
    wp.minAmount0 = 0;
    wp.minAmount1 = 0;
    wp.hasToSwap = true;

    // Build swap params with amountIn set to type(uint256).max (impossible to satisfy)
    IMainnetRouter.ExactInputParams memory swapP;
    swapP.path = abi.encodePacked(address(wbtc), uint24(3000), address(weth));
    swapP.deadline = block.timestamp + 1 hours;
    swapP.amountIn = type(uint128).max; // far exceeds any possible amountOut0
    swapP.amountOutMinimum = 0;
    swapP.recipient = depositor;
    wp.swapParams1 = abi.encode(swapP);

    IMainnetRouter.ExactInputParams memory swapP2;
    swapP2.amountIn = 0; // skip token1 swap
    wp.swapParams2 = abi.encode(swapP2);

    bool success;
    vm.prank(depositor);
    (success, ) = address(leverager).call(
        abi.encodeWithSelector(leverager.withdraw.selector, wp)
    );
    // Should revert cleanly, not with arithmetic underflow that corrupts state
    // The property: if it reverts, it must revert BEFORE any state changes
    // (position should still exist unchanged)
    if (!success) {
        ILeverager.Position memory posAfter = leverager.getPosition(posId);
        eq(posAfter.shares, pos.shares, "DH-06: position shares changed despite failed withdraw");
    }
}

