function property_SH006_collected_fees_respect_current_rate() public {
    uint256 preRate = strategy.protocolFee();
    uint256 preRecipientBal0 = token0.balanceOf(feeRecipient);
    uint256 preRecipientBal1 = token1.balanceOf(feeRecipient);
    (uint256 preIdle0, uint256 preIdle1) = strategy.idleBalances();

    strategy.collectFees();

    uint256 postRecipientBal0 = token0.balanceOf(feeRecipient);
    uint256 postRecipientBal1 = token1.balanceOf(feeRecipient);
    (uint256 postIdle0, uint256 postIdle1) = strategy.idleBalances();

    uint256 collected0 = postIdle0 > preIdle0 ? postIdle0 - preIdle0 : 0;
    uint256 collected1 = postIdle1 > preIdle1 ? postIdle1 - preIdle1 : 0;
    uint256 sentToRecipient0 = postRecipientBal0 - preRecipientBal0;
    uint256 sentToRecipient1 = postRecipientBal1 - preRecipientBal1;

    // fees sent to recipient must not exceed preRate bps of what was collected
    lte(
        sentToRecipient0 * BPS,
        (collected0 + sentToRecipient0) * preRate + BPS - 1,
        "SH-006: token0 protocol fee exceeds configured protocolFee rate"
    );
    lte(
        sentToRecipient1 * BPS,
        (collected1 + sentToRecipient1) * preRate + BPS - 1,
        "SH-006: token1 protocol fee exceeds configured protocolFee rate"
    );
}

