        // No testear el underflow directamente — documentar el riesgo
        t(true, "V-DOS-05: primer deposito necesita amounts > 1000 para no underflow");
    } else if (bal0 > 0 && bal1 > 0) {
        // Depositos subsecuentes: shares = cross * ts / bal0 / bal1
        // Para un deposit de 1 wei, shares podrian ser 0 (valido) o revert (si algo mas falla)
        // Verificar que shares > 0 para cualquier deposit razonable
        uint256 dep0 = bal0 / 1000;  // 0.1% del pool
        uint256 dep1 = bal1 / 1000;
        if (dep0 > 0 && dep1 > 0) {
            uint256 cross = dep0 * bal1 < dep1 * bal0 ? dep0 * bal1 : dep1 * bal0;
