description:
In liquidatePosition() at line 318:
  uint256 borrowedValue = owedAmount * bPrice / ERC20(up.denomination).decimals();
The method .decimals() returns uint8 (e.g. 6 for USDC, 8 for WBTC, 18 for WETH), NOT 10**decimals. Correct code should be: owedAmount * bPrice / (10 ** ERC20(up.denomination).decimals()). With USDC (6 decimals): divides by 6 instead of 1,000,000 → borrowedValue is 166,666x too large. With WBTC (8 decimals): divides by 8 instead of 1e8 → borrowedValue is 12,500,000x too large. With WETH (18 decimals): divides by 18 instead of 1e18 → borrowedValue is ~5.5e16x too large. Consequence: `totalValueUSD > borrowedValue` is ALWAYS false in practice. The entire if-block (protocol fee charging, pf0/pf1 calculation) is permanently dead code. The protocol NEVER collects liquidation fees. All liquidation profit goes to the liquidator. Compare with the CORRECT usages elsewhere: line 178 uses (10 ** decimals), line 131 uses (10 ** decimals).

solidity:
function property_liquidation_fee_is_collected() public {
    // Open a WBTC-denominated position
    uint256 posId = _openSimpleWbtcPosition(depositor, 1e7, 2e7, 50_000e6);

    // Drop price to make position liquidatable
    wbtcOracle.setPrice(10_000e18);
    skip(1 days);

    // Verify position is liquidatable
    t(leverager.isLiquidateable(posId), "position should be liquidatable");

    uint256 feeRecipientBal0Before = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1Before = usdc.balanceOf(feeRecipient);

    // Build liquidation params (no swap needed for WBTC denomination)
    ILeverager.LiquidateParams memory lp;
    lp.id = posId;
    lp.minAmount0 = 0;
    lp.minAmount1 = 0;
    lp.hasToSwap = false;

    vm.prank(liquidator);
    leverager.liquidatePosition(lp);

    uint256 feeRecipientBal0After = wbtc.balanceOf(feeRecipient);
    uint256 feeRecipientBal1After = usdc.balanceOf(feeRecipient);

    // Protocol should have received fees. If borrowedValue uses .decimals() instead of
    // 10**decimals(), the fee block is never entered and feeRecipient gets nothing.
    // With WBTC denomination: .decimals() = 8, so borrowedValue = owedAmount * bPrice / 8
    // instead of / 1e8 — making borrowedValue ~12,500,000x too large.
    // totalValueUSD can never exceed this, so the fee block is skipped.
    t(
        feeRecipientBal0After > feeRecipientBal0Before || feeRecipientBal1After > feeRecipientBal1Before,
        "L-MATH-01: feeRecipient received no liquidation fees — .decimals() bug makes borrowedValue astronomical"
    );
}

function property_withdraw_token1_denom_does_not_revert() public {
    // Open a USDC-denominated position (token1 = denomination)
    uint256 posId = _openSimpleUsdcPosition(depositor, 5e6, 1000e6, 3000e6);

    skip(1 days);

    ILeverager.Position memory pos = leverager.getPosition(posId);
    t(pos.vault != address(0), "position should exist");
    t(pos.denomination == address(usdc), "denomination should be USDC (token1)");

    // Attempt partial withdraw — this should succeed but may revert due to the bug
    ILeverager.WithdrawParams memory wp;
    wp.id = posId;
    wp.pctWithdraw = 0.5e18; // 50%
    wp.minAmount0 = 0;
    wp.minAmount1 = 0;
    wp.hasToSwap = false;

    uint256 depositorUsdcBefore = usdc.balanceOf(depositor);

    vm.prank(depositor);
    // Bug: if amountOut1 < owedAmount, repayFromWithdraw = amountOut0 (WBTC amount)
    // then owedAmount -= amountOut0 may underflow → revert
    // OR amountOut1 -= amountOut0 underflows → revert
    try leverager.withdraw(wp) {
        // If no revert, check that the repayment was correct
        // After withdraw, user should have received tokens back
        uint256 depositorUsdcAfter = usdc.balanceOf(depositor);
        // The position should have updated correctly — borrowedAmount should be reduced
        ILeverager.Position memory posAfter = leverager.getPosition(posId);
        // Verify position still exists (partial withdraw)
        t(posAfter.vault != address(0), "L-MATH-02: position should still exist after partial withdraw");
    } catch {
        // If it reverted, that is the bug: user cannot withdraw from their own position
        t(false, "L-MATH-02: withdraw reverted for token1-denomination position — amountOut0 used instead of amountOut1");
    }
}

function property_calculate_token_values_precision() public view {
    // Simulate the two fallback paths and verify no catastrophic precision loss
    // Path 1: amount0 * price / PRECISION * chPrice1 / decimals1
    // Path 2: amount1 * PRECISION / price * chPrice0 / decimals0

    uint256 prec = 1e30; // PRECISION in Leverager

    // Test case: amount0=1 wei, price=1e30, chPrice1=100_000e18 (WBTC price), decimals1=1e8
    uint256 amount0 = 1;
    uint256 price = 1e30;
    uint256 chPrice1 = 100_000e18;
    uint256 dec1 = 1e8;

    uint256 buggyPath = (amount0 * price / prec) * chPrice1 / dec1;
    // buggy: (1 * 1e30 / 1e30) * 100_000e18 / 1e8 = 1 * 1e15 = 1e15

    uint256 correctPath = amount0 * price * chPrice1 / prec / dec1;
    // correct: 1 * 1e30 * 100_000e18 / 1e30 / 1e8 = 100_000e18 / 1e8 = 1e15

    // In this case equal. Test where they differ:
    // amount0=1, price=3e30 (non-power-of-2)
    price = 3e30;
    uint256 buggy2 = (amount0 * price / prec) * chPrice1 / dec1;
    // buggy: (1 * 3e30 / 1e30) * chPrice1 / dec1 = 3 * 1e15 = 3e15
    uint256 correct2 = amount0 * price * chPrice1 / prec / dec1;
    // correct: 1 * 3e30 * 1e23 / 1e30 / 1e8 = 3e53 / 1e38 = 3e15 — same here

    // The real precision loss is in path 2: amount1 * PRECISION / price
    // with small amount1 and non-round price
    uint256 amount1 = 100; // 100 wei of a 6-decimal token
    uint256 price2 = 3e30; // non-integer ratio
    uint256 chPrice0 = 100_000e18;
    uint256 dec0 = 1e8;

    uint256 buggyPath2 = (amount1 * prec / price2) * chPrice0 / dec0;
    // 100 * 1e30 / 3e30 = 33 (truncated from 33.33)
    // 33 * 100_000e18 / 1e8 = 33e15

    uint256 correctPath2 = amount1 * prec * chPrice0 / price2 / dec0;
    // 100 * 1e30 * 100_000e18 / 3e30 / 1e8
    // = 100 * 1e53 / 3e30 / 1e8 = 1e55 / 3e38 = 3.33e16... truncated to 3e16
    // Wait: 100 * 1e30 * 1e23 / 3e30 / 1e8 = 1e55 / 3e38 = ~3.33e16 → 3.33e16

    // buggyPath2 = 33e15 = 3.3e16 vs correctPath2 = ~3.33e16 → loss of ~1e15 (~3%)
    // At 3% precision loss on collateral, positions can be forced to appear liquidatable

    lte(buggyPath2, correctPath2, "L-MATH-03: division-before-mult causes collateral under-valuation");
}

description:
In isLiquidateable() at line 408:
  uint256 base = owedAmount * 1e18 / (vp.maxTimesLeverage - 1e18);
If vp.maxTimesLeverage == 1e18, the subtraction produces 0, and the subsequent division by 0 reverts with a Panic(0x12) error. The function changeVaultMaxLeverage() has no minimum value constraint — owner can set maxTimesLeverage to any value including 1e18 or below. Furthermore, if existing positions are open and the owner later reduces maxTimesLeverage to 1e18, ALL calls to isLiquidateable() for that vault revert, permanently blocking: 1) liquidatePosition() — which calls isLiquidateable() 2) openLeveragedPosition() — which calls isLiquidateable() at the end Even without malicious owner action, a misconfiguration (governance error) with maxTimesLeverage = 1e18 (intended to mean 1x leverage) would permanently DoS liquidations.

solidity:
function property_isLiquidateable_does_not_revert_with_valid_maxTimesLeverage() public {
    // Check that isLiquidateable never reverts due to division-by-zero
    // This occurs when maxTimesLeverage <= 1e18 (the denominator becomes 0 or negative)

    uint256 posId = _openSimpleWbtcPosition(depositor, 1e7, 2e7, 50_000e6);

    // Simulate owner reducing maxTimesLeverage to 1e18 (1x, which is the critical threshold)
    vm.prank(owner);
    leverager.changeVaultMaxLeverage(address(vault), 1e18);

    // Now isLiquidateable should NOT revert — but it will due to the division-by-zero bug
    // vp.maxTimesLeverage - 1e18 = 0 → division by 0 → Panic(0x12)
    try leverager.isLiquidateable(posId) returns (bool result) {
        // If it doesn't revert, at least ensure the result is meaningful
        t(true, "no revert is OK");
    } catch {
        // Revert here means liquidations are permanently DoS'd for this vault
        t(false, "L-MATH-04: isLiquidateable reverts with division-by-zero when maxTimesLeverage == 1e18");
    }
}

description:
In openLeveragedPosition() at lines 171-177:
  uint256 denomBalance = IERC20(lp.denomination).balanceOf(address(this));
  ILendingPool(lendingPool).repay(lp.denomination, denomBalance);
  up.borrowedAmount = lp.maxBorrowAmount - denomBalance;
If denomination tokens were previously stuck in the Leverager (from a failed tx or donation), denomBalance includes those stuck tokens. The contract over-repays (using stuck tokens too) but records borrowedAmount = maxBorrowAmount - (actualUnused + stuckAmount). This means borrowedAmount is LESS than the actual outstanding debt for this position. The position passes _checkWithinlimits with an artificially low leverage calculation, potentially bypassing the positionLeverage <= maxTimesLeverage check. When the position is eventually closed, only borrowedAmount (the under-counted amount) is repaid. The actual debt (maxBorrowAmount - actualUnused) was already repaid using stuck tokens — so the lending pool is made whole, but the leverager consumed other users' stuck tokens.

