function property_borrowed_amount_not_reduced_by_donations() public {
    // Record lending pool state before
    uint256 lendingPoolWbtcBefore = wbtc.balanceOf(address(lendingPool));

    // Attacker donates 0.01 WBTC to Leverager (stuck tokens scenario)
    uint256 donation = 1e6; // 0.01 WBTC
    deal(address(wbtc), attacker, donation);
    vm.prank(attacker);
    wbtc.transfer(address(leverager), donation);

    // Depositor opens a WBTC-denominated position
    uint256 posId = _openSimpleWbtcPosition(depositor, 1e7, 2e7, 50_000e6);

    ILeverager.Position memory pos = leverager.getPosition(posId);

    // The borrowedAmount should reflect ONLY what was actually borrowed for this position
    // i.e., it should NOT be reduced by the donated tokens
    // If borrowedAmount is under-counted, the position has more real debt than recorded

    // Invariant: borrowedAmount + unused should equal maxBorrowAmount
    // Since unused was repaid, borrowedAmount == maxBorrowAmount - denomBalanceAfterSwaps (correct)
    // But with a donation: denomBalance includes the donation
    // borrowedAmount = maxBorrowAmount - (actualUnused + donation) = understated

    // Verify lending pool did not receive more than it should (donation was consumed)
    uint256 lendingPoolWbtcAfter = wbtc.balanceOf(address(lendingPool));
    // If donation was used in repay, lendingPool got extra, but borrowedAmount is still wrong
    t(pos.borrowedAmount > 0, "L-MATH-05: borrowedAmount must be positive");

    // The real check: is borrowedAmount consistent with what was repaid?
    // borrowedAmount should equal (actual swap consumption), not be reduced by donations
    // We can't directly verify this without knowing swap amounts, so we check consistency
    // If borrowedAmount < minBorrow, the position should have been rejected
    gte(pos.borrowedAmount * WBTC_PRICE / ONE_WBTC, leverager.minBorrow(),
        "L-MATH-05: borrowedAmount USD value must be at least minBorrow");
}

// After rebalance with active vesting, collectFees must use vesting position's own ticks
function invariant_collectFees_uses_correct_vesting_ticks() public {
  // vestPosition ticks should always be used together, never mixed with mainPosition
  IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
  IStrategy.Position memory mp = strategy.getMainPosition();
  // If vesting is active and rebalance has occurred, mainPosition.tickUpper != vestPosition.tickUpper
  // This invariant documents the bug: after rebalance, the code uses wrong ticks
  if (strategy.ongoingVestingPosition()) {
    // The bug: line 167 uses vestPosition.tickLower with mainPosition.tickUpper
    // After rebalance these diverge, proving the bug
    assert(vp.tickUpper == mp.tickUpper || !_rebalanceOccurredDuringVesting());
  }
}

// The sum of all partial vesting withdrawals must never exceed initialLiquidity
function invariant_vesting_withdrawal_no_underflow() public {
  IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
  // remainingLiquidity must always be >= 0 (uint128 prevents negative, but underflow reverts)
  // Track: initialLiquidity - remainingLiquidity = total withdrawn
  // Each withdrawal chunk: initialLiquidity * timeDelta / totalDuration
  // Sum of chunks can exceed initialLiquidity due to rounding
  assert(vp.remainingLiquidity <= vp.initialLiquidity);
}

// balances() must account for ALL liquidity owned by the strategy
function invariant_balances_includes_all_positions() public {
  (uint256 reported0, uint256 reported1) = strategy.balances();
  // Get vesting position value
  IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
  if (strategy.ongoingVestingPosition() && vp.remainingLiquidity > 0) {
    // reported balances SHOULD include vesting, but they don't
    // This proves the bug: actual TVL > reported TVL during active vesting
    (uint256 actual0, uint256 actual1) = _getTotalValueIncludingVesting();
    assert(reported0 >= actual0 && reported1 >= actual1);
  }
}

// Secondary position must always have tickLower < tickUpper
function invariant_secondary_position_valid_range() public {
  IStrategy.Position memory sp = strategy.getSecondaryPosition();
  if (sp.liquidity > 0) {
    assert(sp.tickLower < sp.tickUpper);
  }
}

// withdrawPartial must return proportional value of ALL positions
function invariant_withdraw_proportional_all_positions() public {
  // After withdrawal of X% shares, user should receive X% of total value
  // Including vesting position value
  uint256 totalShares = vault.totalSupply();
  if (totalShares > 0 && strategy.ongoingVestingPosition()) {
    // The actual withdrawn amount will be less than fair share
    // because vesting position is not included
    (uint256 bal0, uint256 bal1) = strategy.balances();
    // bal0/bal1 already exclude vesting → withdraw based on this is unfair
  }
}

