// Invariant: mainPosition ticks must always be within Uniswap V3 valid range
function invariant_main_ticks_within_bounds() public {
  IStrategy.Position memory mp = strategy.getMainPosition();
  int24 MIN_TICK = -887272;
  int24 MAX_TICK = 887272;
  gte(int256(mp.tickLower), int256(MIN_TICK), "mainPosition.tickLower below MIN_TICK");
  gte(int256(MAX_TICK), int256(mp.tickUpper), "mainPosition.tickUpper above MAX_TICK");
  t(mp.tickLower < mp.tickUpper, "mainPosition tickLower >= tickUpper");
}

// Invariant: after a full withdrawal (all non-burn shares), the strategy should
// have no residual mainPosition.liquidity that exceeds what the BURN shares are entitled to.
// If many idle-path withdrawals occurred (triggered by vesting inflation), this breaks.
function invariant_mainLiquidity_tracks_supply() public {
  uint256 ts = vault.totalSupply();
  if (ts == 0) return;
  IStrategy.Position memory mp = strategy.getMainPosition();
  // mainPosition.liquidity should be proportional to totalSupply relative to initial
  // There is no perfect invariant without tracking history, but we can check
  // that liqToRemove calculation would not revert:
  uint128 liqToRemove = uint128(uint256(mp.liquidity) * (ts - 1000) / ts);
  // If liqToRemove > actual Uniswap position liquidity, next non-idle withdraw reverts
  // (Not directly testable without pool mock, but documents the accounting gap)
  t(mp.liquidity <= type(uint128).max, "mainPosition.liquidity overflow");
}

