    uint256 posId = _openSimpleWbtcPosition(
        depositor,
        1 * ONE_WBTC,
        2 * ONE_WBTC,
        100_000 * ONE_USDC
    );

    ILeverager.Position memory pos = leverager.getPosition(posId);

    // The pool balance should have decreased by exactly borrowedAmount
    // (maxBorrowAmount was repaid in full, only borrowedAmount remains outstanding)
    uint256 lendingPoolUsdcAfter = usdc.balanceOf(lendingPool.getYTokenAddress(address(usdc)));

    // borrowedAmount should reflect real outstanding debt, not deflated by donation
    // If donation inflated denomBalance, borrowedAmount < real debt
    uint256 realDebt = lendingPoolUsdcBefore - lendingPoolUsdcAfter;
    eq(
        pos.borrowedAmount,
        realDebt,
        "SIG-05: borrowedAmount does not match actual debt owed to pool (donation attack)"
    );
}

