function property_positionWidth_only_rebalancer_can_change() public {
    uint24 widthBefore = strategy.positionWidth();
    int24 ts = strategy.tickSpacing();
    // Construct a valid width: must satisfy (_newWidth/2) % tickSpacing == 0
    // Use 2 * tickSpacing (minimum valid value, deliberately narrow)
    uint24 maliciousWidth = uint24(uint24(ts) * 2);

    // Attacker tries to change positionWidth - should revert for non-rebalancer
    vm.prank(attacker);
    try strategy.changePositionWidth(maliciousWidth) {
        // If we reach here, either the rebalance succeeded (wrong) or
        // the storage was mutated and rebalance reverted (still wrong - storage changed)
    } catch {
        // Even if the call reverted, check the storage wasn't mutated
    }

    uint24 widthAfter = strategy.positionWidth();
    t(widthBefore == widthAfter, "S-AC-01: attacker changed positionWidth - no modifier guards the storage write");
}

