function property_vesting_collectfees_correct_ticks() public {
    // Establish: vesting position exists
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // The bug: collectFees uses mainPosition.tickUpper, not vestPosition.tickUpper
    // They must match at collection time for fees to go to the right position
    // After a rebalance they diverge — this property catches that state
    // Property: if vesting is ongoing, vestPosition.tickUpper == mainPosition.tickUpper
    // at the time collectFees is called (as the code assumes)
    t(
        vp.tickUpper == mp.tickUpper,
        "collectFees uses wrong tickUpper for vesting position"
    );
}

function property_balances_includes_vesting() public {
    // If there's an ongoing vesting position, balances() should include its value.
    // We check: total balances >= idle + main + secondary
    // (we can't call balances() on vesting directly, but we can check
    //  that balances don't DECREASE after starting a vesting position)
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    // Vesting position holds real tokens in Uniswap; total balance
    // reported should be at least the idle balance (since vesting adds on top)
    // This can't easily catch the exact delta, but we verify non-regression:
    // at minimum, balances >= idle
    gte(bal0, idle0, "balances() token0 less than idle: vesting not counted");
    gte(bal1, idle1, "balances() token1 less than idle: vesting not counted");
}

function property_vesting_fully_released_at_end() public {
    // After vesting ends, remainingLiquidity should be 0
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    bool ongoing = strategy.ongoingVestingPosition();

    if (!ongoing && vp.endTs > 0) {
        // Vesting ended — remaining liquidity should be zero
        // (any stranded amount is a bug)
        eq(
            uint256(vp.remainingLiquidity),
            0,
            "Vesting ended but remainingLiquidity != 0: tokens stranded"
        );
    }
}

function property_only_rebalancer_changes_width() public {
    // changePositionWidth has no access control; any caller can set positionWidth.
    // We verify that after an attacker calls changePositionWidth, rebalance reverts
    // (so the width change itself is the issue — attacker pre-sets width).
    uint24 currentWidth = strategy.positionWidth();
    // Attacker sets an extreme position width
    vm.prank(attacker);
    // changePositionWidth will call rebalance internally, which will revert
    // for non-rebalancer. But the positionWidth storage IS updated before rebalance.
    // We can't easily test the storage write before revert in a property,
    // so instead we verify the invariant: positionWidth only changes via rebalancer.
    // If positionWidth changed without a rebalancer call, this fires.
    // (This is best tested via a sequence property in stateful fuzzing)
    t(
        msg.sender == rebalancer || strategy.positionWidth() == currentWidth,
        "positionWidth changed by non-rebalancer"
    );
}

function property_deposit_uses_both_tokens() public {
    uint256 supply = vault.totalSupply();
    if (supply == 0) return;

    (uint256 bal0, uint256 bal1) = strategy.balances();

    // If vault holds both tokens, deposits must use both tokens proportionally.
    // If bal0 == 0 but bal1 > 0, new deposits only take token1 — user's token0 desire ignored.
    // This property checks: if both balances are positive, the vault ratio is maintained.
    if (bal0 > 0 && bal1 > 0) {
        // Both tokens should be in use; ratio should be non-zero for both.
        t(bal0 > 0, "token0 balance unexpectedly zero with active positions");
        t(bal1 > 0, "token1 balance unexpectedly zero with active positions");
    }
}

function property_withdraw_respects_vesting_share() public {
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    uint256 supply = vault.totalSupply();
    if (supply == 0) return;

    // Total reported balances should include vesting position value.
    // Since we know vesting position exists but balances() excludes it,
    // we verify: strategy token balances in Uniswap >= balances() reports.
    // Proxy check: balances() is used for share pricing, so shares should
    // be priced at >= actual idle holdings at minimum.
    (uint256 bal0, uint256 bal1) = strategy.balances();
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();

    gte(bal0, idle0, "balances() undercounts: less than idle token0");
    gte(bal1, idle1, "balances() undercounts: less than idle token1");
}

