function property_protocol_fee_not_from_vesting() public {
    if (!strategy.ongoingVestingPosition()) return;

    uint256 feeRecipientBal0 = token0.balanceOf(feeRecipient);
    uint256 feeRecipientBal1 = token1.balanceOf(feeRecipient);

    // Collect fees — if vesting fees were taxed, feeRecipient balance increases
    strategy.collectFees();

    uint256 feeRecipientBal0After = token0.balanceOf(feeRecipient);
    uint256 feeRecipientBal1After = token1.balanceOf(feeRecipient);

    // Protocol fee recipient should not receive funds from vesting position fees
    // (this property would catch if fees are being taken from vesting)
    // Since we can't distinguish sources, we check that idleBalance did not decrease
    // by more than the protocol fee implies
    (uint256 idle0, uint256 idle1) = strategy.idleBalances();
    t(idle0 > 0 || idle1 > 0 || (feeRecipientBal0After == feeRecipientBal0 && feeRecipientBal1After == feeRecipientBal1),
      "WC-06: protocol fee collected but strategy has no idle balance (all from vesting?)");
}

function property_fullmath_muldiv_correct() public {
    // Verify FullMath.mulDiv gives correct results for known inputs
    // 2 * 3 / 1 = 6
    uint256 result = FullMath.mulDiv(2, 3, 1);
    eq(result, 6, "WC-08: FullMath.mulDiv(2,3,1) should equal 6");

    // Large value: (2^128) * (2^128) / (2^128) = 2^128
    uint256 big = 2**128;
    result = FullMath.mulDiv(big, big, big);
    eq(result, big, "WC-08: FullMath.mulDiv large value incorrect");

    // Price calculation sanity: price() should be nonzero
    uint256 p = strategy.price();
    t(p > 0, "WC-08: strategy.price() returned 0 — FullMath broken");
}

function property_vesting_liquidity_decreases_over_time() public {
    if (!strategy.ongoingVestingPosition()) return;
    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    if (vpBefore.lastUpdate == block.timestamp) return;

    uint256 duration = vpBefore.endTs - vpBefore.startTs;
    skip(duration / 5 + 1);

    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    lte(uint256(vpAfter.remainingLiquidity), uint256(vpBefore.remainingLiquidity),
        "WC-09: vesting remainingLiquidity should not increase");
}

function invariant_first_deposit_fairness() public {
    uint256 ts = vault.totalSupply();
    if (ts == 0) return; // no deposits yet
    (uint256 bal0, uint256 bal1) = IStrategy(vault.strategy()).balances();
    // After first deposit, both balances should be non-trivial relative to shares
    // If one balance is near-zero but shares are large, first depositor exploited the max() logic
    if (ts > 1e6) {
        t(bal0 > 0 && bal1 > 0, "DOM-V-01: vault has shares but one balance is zero");
    }
}

function invariant_vesting_fee_collection_correct_ticks() public {
    // Verify that collectFees uses vestPosition's own ticks, not mainPosition's
    // After rebalance, mainPosition.tickUpper may differ from vestPosition.tickUpper
    IStrategy strat = IStrategy(vault.strategy());
    IStrategy.VestingPosition memory vp = strat.getVestingPosition();
    IStrategy.Position memory mp = strat.getMainPosition();
    // If vesting is active and ticks diverge, fee collection is broken
    if (vp.remainingLiquidity > 0) {
        // This should be true but the CODE uses mainPosition.tickUpper instead
        t(vp.tickUpper == mp.tickUpper || vp.remainingLiquidity == 0,
          "DOM-V-03: vesting ticks diverged from main - fee collection broken");
    }
}

function property_collectFees_uses_vest_tickUpper() public {
    // Only meaningful when a vesting position is active
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();

    // After a rebalance the main ticks may differ from vest ticks.
    // Capture idle balances before and after collectFees to see if
    // fees were collected at all from the vesting position range.
    // The real invariant: vestPosition.tickUpper must equal the tickUpper
    // passed to collectPositionFees when ongoingVestingPosition is true.
    // We verify the stored vesting tickUpper is NOT silently replaced by
    // the main position tickUpper in the collection logic.
    // Proxy test: after collectFees the vesting position's tick range
    // should still be accessible (remainingLiquidity consistent).
    (uint256 idleBefore0, uint256 idleBefore1) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 idleAfter0, uint256 idleAfter1) = strategy.idleBalances();

    // If vesting position ticks diverged from main position ticks the
    // wrong range was targeted; the vesting fees would not appear.
    // This property flags the structural divergence directly.
    t(vp.tickUpper == mp.tickUpper || vp.tickLower == mp.tickLower,
      "LH-001: vest ticks diverged from main — collectFees used wrong tickUpper");
}

function property_secondary_position_absorbs_residual() public {
    // After a rebalance the secondary position should have non-zero
    // liquidity if there were residual tokens after the main position.
    // Idle balances should be near-zero after both positions are filled.
    vm.prank(rebalancer);
    try strategy.rebalance() {} catch { return; }

    (uint256 idle0, uint256 idle1) = strategy.idleBalances();
    uint256 _price = strategy.price();
    // Convert idle0 to token1 units for comparison
    uint256 idle0in1 = idle0 * _price / 1e30;

    // After a proper rebalance, total idle should be small (< 1% of
    // either token's value) because the secondary position absorbed the
    // residual. A large idle balance indicates the secondary did not absorb.
    uint256 total1Equiv = idle0in1 + idle1;
    // Allow up to 1 USDC (1e6) worth of idle — rounding tolerance
    t(total1Equiv < 1e6 * 100,
      "LH-002: secondary position did not absorb residual — inverted range assignment");
}

function property_vesting_does_not_overdraw() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    uint128 remainingBefore = vpBefore.remainingLiquidity;

    // Advance time by a fraction of the vesting period
    skip(1 hours);
    strategy.collectFees();

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    uint128 remainingAfter = vpAfter.remainingLiquidity;

    // Remaining liquidity should have decreased but not below zero
    // (underflow would revert, but we also check it didn't decrease by more than was there)
    t(remainingAfter <= remainingBefore,
      "LH-003: vesting released more liquidity than was remaining");

    // The amount released must be <= initialLiquidity * elapsed / totalDuration
    uint256 elapsed = 1 hours;
    uint256 totalDur = vpBefore.endTs - vpBefore.startTs;
    uint128 maxRelease = uint128(uint256(vpBefore.initialLiquidity) * elapsed / totalDur + 1); // +1 rounding
    uint128 actualRelease = remainingBefore - remainingAfter;
    t(actualRelease <= maxRelease,
      "LH-003: vesting released more than formula allows");
}

function property_checkPoolActivity_no_revert_on_normal_pool() public {
    // checkPoolActivity should not revert under normal operating conditions
    // (observation buffer populated up to twap period).
    // We call it and verify it returns a bool without reverting.
    bool result;
    bool success = true;
    try strategy.checkPoolActivity() returns (bool r) {
        result = r;
    } catch {
        success = false;
    }
    t(success, "LH-005: checkPoolActivity reverted — potential DOS on rebalance");
}

function property_protocol_fee_charged_on_vest_fees() public {
    if (!strategy.ongoingVestingPosition()) return;

    address recipient = strategy.feeRecipient();
    uint256 recipBefore0 = token0.balanceOf(recipient);
    uint256 recipBefore1 = token1.balanceOf(recipient);

    // Generate some fees: advance time and do a swap to generate pool fees
    skip(1 days);
    _swapWbtc(1e6); // small swap to generate fees in the vesting position range

    strategy.collectFees();

    uint256 recipAfter0 = token0.balanceOf(recipient);
    uint256 recipAfter1 = token1.balanceOf(recipient);

    // If vest fees were collected, protocol fee recipient should have received tokens.
    // This will fail under LH-001 because the wrong tick range collects 0 fees.
    // When combined with an active vesting position that has accrued fees,
    // at least one token's fee should have been forwarded.
    t(recipAfter0 >= recipBefore0 && recipAfter1 >= recipBefore1,
      "LH-006: fee recipient balance decreased after collectFees");
}

function property_vest_fees_not_lost_after_rebalance() public {
    // Set up: ensure we have a vesting position, do a rebalance to
    // change main ticks, generate fees, then check vest fees are collected.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    IStrategy.Position memory mpBefore = strategy.getMainPosition();

    // If ticks already diverged, the bug is active
    if (vpBefore.tickUpper == mpBefore.tickUpper) return; // no divergence yet

    // Generate fees in the vest position range via a swap
    _swapWbtc(1e5);
    skip(1 minutes);

    (uint256 idle0Before, uint256 idle1Before) = strategy.idleBalances();
    strategy.collectFees();
    (uint256 idle0After, uint256 idle1After) = strategy.idleBalances();

    // After collecting fees the idle balance should have grown
    // (fees from the vesting position must appear here minus protocol fee)
    // If it did NOT grow, vest fees were silently skipped (LH-001/LH-007)
    t(idle0After >= idle0Before || idle1After >= idle1Before,
      "LH-007: vesting position fees not collected after main ticks changed");
}

// Invariant: _msgSender() and msg.sender should be equivalent
function invariant_msgsender_consistent() public {
  // In current implementation without ERC2771Context, these are always equal
  // This invariant documents the assumption
}

// Verificar que el fee siempre esta acotado
uint256 fee = vault.depositFee();
t(fee <= 10, "V-A-02: depositFee excede el maximo de 10 (0.1%)");
// Intentar setear fee > 10 (debe revertir)
try vault.setDepositFee(11) {
    t(false, "V-A-02: se pudo setear depositFee > 10");
} catch {
    // Correcto
}

// Verificar que el assert en _calcDeposit no puede triggear con totalSupply > 0
(uint256 bal0, uint256 bal1) = IStrategy(vault.strategy()).balances();
uint256 ts = vault.totalSupply();
// El assert dice: ts == 0 OR bal0 > 0 OR bal1 > 0
// Si ts > 0 && bal0 == 0 && bal1 == 0, el assert falla -> panic
if (ts > 0) {
    t(bal0 > 0 || bal1 > 0, "V-A-06: vault en estado invalido: totalSupply>0 pero ambos balances=0");
}

// Verificar que una reserva no inicializada no puede bloquear el protocolo
DataTypes.ReserveData memory uninitializedReserve;
// borrowingIndex = 0 por defecto
// Llamar updateState debería revertir (div/0) — documentar como initialization check
try pool.processUninitializedReserve() {
    t(false, "RL-A-03: reserva no inicializada procesada sin error");
} catch {
    // Correcto — revierte. Pero el admin debe asegurar que nunca se llega a este estado.
}

// Verificar que el strategy siempre tiene aprobacion maxima al vault
address strat = vault.strategy();
uint256 allowance0 = IERC20(vault.token0()).allowance(strat, address(vault));
uint256 allowance1 = IERC20(vault.token1()).allowance(strat, address(vault));
// Debe ser max (no puede agotar porque max no se decrementa en ERC20 standard)
t(allowance0 == type(uint256).max, "V-TB-01: strategy no tiene aprobacion max de token0 al vault");
t(allowance1 == type(uint256).max, "V-TB-01: strategy no tiene aprobacion max de token1 al vault");

// Verificar que con fee-on-transfer tokens, el vault no minta shares en exceso
uint256 stratBal0Before = IERC20(vault.token0()).balanceOf(vault.strategy());
uint256 stratBal1Before = IERC20(vault.token1()).balanceOf(vault.strategy());
(uint256 shares, uint256 dep0, uint256 dep1) = vault.deposit(amount0, amount1, 0, 0);
uint256 stratBal0After = IERC20(vault.token0()).balanceOf(vault.strategy());
uint256 stratBal1After = IERC20(vault.token1()).balanceOf(vault.strategy());
// Lo que realmente llego al strategy
uint256 received0 = stratBal0After - stratBal0Before;
uint256 received1 = stratBal1After - stratBal1Before;
// received debe ser igual a dep0/dep1 (sin fee-on-transfer)
t(received0 == dep0, "V-TB-02: token0 es fee-on-transfer, el strategy recibio menos de lo esperado");
t(received1 == dep1, "V-TB-02: token1 es fee-on-transfer, el strategy recibio menos de lo esperado");

// Verificar el invariante del assert en _calcDeposit
(uint256 bal0, uint256 bal1) = IStrategy(vault.strategy()).balances();
uint256 ts = vault.totalSupply();
if (ts > 0) {
    // Si este invariante se rompe, el vault esta en un estado invalido
    // y todos los depositos/withdrawals fallaran con panic
    t(bal0 > 0 || bal1 > 0, "V-TB-03: vault en estado invalido: totalSupply>0 pero ambos balances=0");
}
// Adicionalmente: verificar que idleBalances() no revierte
try IStrategy(vault.strategy()).idleBalances() returns (uint256 idle0, uint256 idle1) {
    t(idle0 <= bal0, "V-TB-03: idleBalances excede totalBalances para token0");
    t(idle1 <= bal1, "V-TB-03: idleBalances excede totalBalances para token1");
} catch {
    t(false, "V-TB-03: idleBalances() revertio");
}

// Invariant: deposit increases underlyingBalance by exact amount
function invariant_deposit_accounting(uint256 amount) public {
  uint256 balBefore = reserve.underlyingBalance;
  _deposit(asset, amount, user);
  uint256 balAfter = reserve.underlyingBalance;
  t(balAfter == balBefore + amount, "deposit accounting mismatch");
}

// Invariant: redeem decreases yToken supply and underlyingBalance atomically
function invariant_redeem_atomic(uint256 yAmount) public {
  uint256 supplyBefore = IERC20(reserve.yTokenAddress).totalSupply();
  uint256 balBefore = reserve.underlyingBalance;
  _redeem(underlying, yAmount, to);
  uint256 supplyAfter = IERC20(reserve.yTokenAddress).totalSupply();
  uint256 balAfter = reserve.underlyingBalance;
  t(supplyAfter == supplyBefore - yAmount, "yToken supply not reduced");
  t(balAfter < balBefore, "underlyingBalance not reduced");
}

// Invariant: no reserve factor means all interest goes to yToken holders
function invariant_no_reserve_factor() public {
  // totalLiquidity = underlyingBalance + borrowedLiquidity
  // No fees extracted between accrual and exchange rate computation
  (uint256 total,) = reserve.totalLiquidityAndBorrows();
  uint256 expected = reserve.underlyingBalance + reserve.borrowedLiquidity();
  t(total == expected, "total liquidity includes unexpected fees");
}

// Invariant: yToken amount is correctly rounded down
function invariant_deposit_rounding(uint256 amount) public {
  uint256 exchangeRate = reserve.reserveToYTokenExchangeRate();
  uint256 yTokens = amount * exchangeRate / PRECISION;
  // Verify: yTokens * PRECISION / exchangeRate <= amount (no overmint)
  uint256 backToUnderlying = yTokens * PRECISION / exchangeRate;
  t(backToUnderlying <= amount, "deposit overmints yTokens");
}

// Invariant: full repay sets totalBorrows to 0
function invariant_full_repay_zeros_borrows() public {
  reserve.updateState();
  uint256 fullAmount = reserve.totalBorrows;
  // simulate full repay
  reserve.totalBorrows -= fullAmount;
  t(reserve.totalBorrows == 0, "full repay did not zero totalBorrows");
}

// Invariant: redeemable value should not exceed actual token balance
function invariant_no_phantom_redemptions() public {
  uint256 totalSupply = IERC20(reserve.yTokenAddress).totalSupply();
  uint256 rate = reserve.yTokenToReserveExchangeRate();
  uint256 totalRedeemable = totalSupply * rate / PRECISION;
  uint256 actualBalance = IERC20(underlying).balanceOf(reserve.yTokenAddress);
  // totalRedeemable can exceed actualBalance (borrows are outstanding)
  // But available redemptions limited by actualBalance
  t(reserve.underlyingBalance <= actualBalance,
    "accounting balance exceeds actual balance");
}

function property_collectFees_uses_correct_vestingPosition_ticks() public {
    // If there is an ongoing vesting position, collectFees must not silently
    // collect from wrong ticks after a rebalance changes mainPosition ticks.
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory main = strategy.getMainPosition();

    // After a rebalance, vestPosition.tickUpper may differ from mainPosition.tickUpper.
    // The bug manifests as fee collection from (vestPosition.tickLower, mainPosition.tickUpper)
    // instead of (vestPosition.tickLower, vestPosition.tickUpper).
    // Property: if ticks diverged, collectFees should not apply the wrong tick pair.
    // We verify by checking that the vesting position's stored ticks are self-consistent
    // and that collectFees does not revert (even if subtly wrong, a revert is definitive DoS).
    uint256 bal0Before = token0.balanceOf(address(strategy));
    uint256 bal1Before = token1.balanceOf(address(strategy));

    strategy.collectFees();

    // Vesting position ticks must remain stable across collectFees calls
    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();
    eq(uint256(int256(vpAfter.tickLower)), uint256(int256(vp.tickLower)),
       "DOS-01: vestPosition.tickLower changed unexpectedly");
    eq(uint256(int256(vpAfter.tickUpper)), uint256(int256(vp.tickUpper)),
       "DOS-01: vestPosition.tickUpper changed unexpectedly");
}

function property_checkPoolActivity_terminates_within_gas_limit() public {
    // checkPoolActivity must complete within reasonable gas bounds.
    // The pool's observationCardinality is externally observable.
    (,, uint16 currentIndex, uint16 observationCardinality,,,) = POOL.slot0();

    uint256 gasBefore = gasleft();
    bool result;
    bool didRevert = false;

    try strategy.checkPoolActivity() returns (bool r) {
        result = r;
    } catch {
        didRevert = true;
    }

    uint256 gasUsed = gasBefore - gasleft();

    // If cardinality is large, gas will exceed block limit — DoS is real.
    // We assert gas used stays under 5M as a conservative property.
    t(!didRevert, "DOS-02: checkPoolActivity reverted (timestamp 0 or OOG) — blocks all rebalance/compound");
    lte(gasUsed, 5_000_000, "DOS-02: checkPoolActivity used excessive gas — unbounded loop DoS risk");
}

function property_checkPoolActivity_no_division_by_zero() public {
    // checkPoolActivity must return a bool without panicking.
    // A division-by-zero in the loop is a definitive DoS.
    bool result;
    bool panicked = false;
    try strategy.checkPoolActivity() returns (bool r) {
        result = r;
    } catch (bytes memory err) {
        // Panic(0x12) = division by zero
        // Any revert here blocks all price-gated operations
        panicked = true;
    }
    t(!panicked, "DOS-03: checkPoolActivity panicked (div-by-zero on last iteration) — permanent rebalance DoS");
}

function property_withdraw_succeeds_when_collectFees_is_operational() public {
    // If collectFees reverts, withdrawal is blocked. We verify the inverse:
    // when collectFees succeeds, withdrawal should also succeed.
    bool feesOk = true;
    try strategy.collectFees() {
        // fees collection is working
    } catch {
        feesOk = false;
    }

    if (!feesOk) {
        // Attempt withdrawal — it should still succeed via some emergency path
        uint256 shares = vault.balanceOf(user);
        if (shares > 0) {
            bool withdrawOk = true;
            try vault.withdraw(shares, 0, 0) {
                // ok
            } catch {
                withdrawOk = false;
            }
            // If collectFees is broken AND withdrawal is also broken, funds are locked.
            t(withdrawOk, "DOS-04: no emergency withdrawal path — user funds permanently locked when collectFees reverts");
        }
    }
}

function property_zero_protocol_fee_bypasses_feeRecipient_dependency() public {
    // With protocolFee = 0, collectFees should not call safeTransfer to feeRecipient.
    // This verifies the DoS bypass is available when fees are zeroed.
    vm.prank(owner);
    strategy.setProtocolFee(0);

    // Even if feeRecipient is broken, zero fee means no transfer
    eq(strategy.protocolFee(), 0, "DOS-06: protocolFee not set to zero");

    // collectFees must succeed with zero protocol fee
    strategy.collectFees();
    t(true, "DOS-06: collectFees succeeded with zero protocol fee — feeRecipient DoS is bypassable by owner");
}

function property_checkPoolActivity_returns_true_when_stable_and_old_enough() public {
    // If pool has observations older than the TWAP window and price has been stable,
    // checkPoolActivity() must return true (not false or revert).
    // The early-exit ordering bug may cause it to return false spuriously.
    // We verify: after 10 minutes with stable price, checkPoolActivity returns true.
    skip(10 minutes);

    // Check pool activity directly
    bool result = strategy.checkPoolActivity();

    // Under normal mainnet conditions (WBTC/USDC pool has many old observations),
    // this should return true.
    t(result, "DOS-08: checkPoolActivity returned false on a stable pool — check ordering bug blocks rebalance");
}

// Invariante: si hay vesting position activa, los ticks de collectFees deben coincidir
// con los ticks de vestPosition, no de mainPosition
if (strategy.ongoingVestingPosition()) {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory mp = strategy.getMainPosition();
    // Después de cualquier rebalance, mainPosition.tickUpper puede divergir
    // de vestPosition.tickUpper. Si divergen, L345 colecta de ticks equivocados.
    eq(vp.tickUpper, mp.tickUpper,
        "S-01: vestPosition.tickUpper != mainPosition.tickUpper tras rebalance — collectFees usa ticks incorrectos");
    // NOTA: Este invariante FALLA intencionalmente post-rebalance — la falla IS el bug
}

// Invariante: después de rebalance con vesting activo, el vesting no pierde su respaldo
bool hasVesting = strategy.ongoingVestingPosition();
if (hasVesting) {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    // El Uniswap pool debe tener suficiente liquidez en los ticks del vest
    // para satisfacer un withdraw completo
    (uint128 poolLiq,,,,,) = IUniswapV3Pool(strategy.pool()).positions(
        keccak256(abi.encodePacked(address(strategy), vp.tickLower, vp.tickUpper))
    );
    gte(poolLiq, vp.remainingLiquidity,
        "S-02: Uniswap pool position < vestPosition.remainingLiquidity — vesting tokens re-invested en rebalance");
}

// Comparar price() vs precio calculado correctamente con mayor precision
uint256 stratPrice = strategy.price();

// Cálculo correcto: evitar truncación antes del cuadrado
(uint160 sqrtPriceX96,,,,,,) = IUniswapV3Pool(strategy.pool()).slot0();
// Método más preciso: mulDiv(sqrtPriceX96^2, 1e30, 2^192)
uint256 correctPrice = FullMath.mulDiv(
    FullMath.mulDiv(sqrtPriceX96, sqrtPriceX96, 2**96),
    1e30,
    2**96
);

// El error relativo no debe ser suficiente para cambiar decisiones de comparación
uint256 diff = stratPrice > correctPrice ? stratPrice - correctPrice : correctPrice - stratPrice;
// Tolerancia: 0.01% (1 BPS) de error relativo
if (correctPrice > 0) {
    lte(diff * 10000 / correctPrice, 1, "S-03: error de precision en price() supera 0.01%");
}

// Invariante post-rebalance: secondary position siempre tiene tick range válido
int24 secTickLower = strategy.secondaryPosition().tickLower;
int24 secTickUpper = strategy.secondaryPosition().tickUpper;

t(secTickLower < secTickUpper,
    "S-04: secondary position tiene tick range invertido o zero-width");
t(secTickLower >= -887272 && secTickUpper <= 887272,
    "S-04: secondary position ticks fuera de Uniswap bounds");
// Los ticks deben ser múltiplos del tickSpacing
int24 spacing = strategy.tickSpacing();
eq(secTickLower % spacing, 0, "S-04: secTickLower no es múltiplo de tickSpacing");
eq(secTickUpper % spacing, 0, "S-04: secTickUpper no es múltiplo de tickSpacing");

// Invariante: bal0 * price() no debe overflow
uint256 _price = strategy.price();
(uint256 bal0,) = strategy.idleBalances();

if (_price > 0 && bal0 > 0) {
    uint256 maxSafeBal0 = type(uint256).max / _price;
    lte(bal0, maxSafeBal0, "S-05: bal0 * price() overflowaria — rebalance DoS");
}

// Invariante: el total devuelto al usuario debe ser >= al valor proporcional menos el dust
// Para shares > DUST_THRESHOLD, el usuario debe recibir algo
uint256 DUST_THRESHOLD = 1000; // mínimo de shares para esperar retorno

if (shares >= DUST_THRESHOLD) {
    (uint256 total0, uint256 total1) = strategy.balances();
    uint256 expected0 = total0 * shares / totalSupply;
    uint256 expected1 = total1 * shares / totalSupply;

    (uint256 out0, uint256 out1) = strategy.withdrawPartial(shares, totalSupply);

    // Las 4 divisiones de rounding pueden quitar hasta 4 wei por token
    gte(out0 + 4, expected0, "S-06: withdrawal devuelve menos de lo proporcional (token0)");
    gte(out1 + 4, expected1, "S-06: withdrawal devuelve menos de lo proporcional (token1)");
}

// Invariante: preBal snapshot en collectFees debe ser pre-toda la lógica, no solo pre-burn
// Si hay tokens idle pre-existentes, no deben contarse como fees generadas
(uint256 preBal0, uint256 preBal1) = strategy.idleBalances();
// Donar tokens directamente
IERC20(strategy.token0()).transfer(address(strategy), 1000e6);
// Llamar collectFees
uint256 feeRecipientBalBefore = IERC20(strategy.token0()).balanceOf(strategy.feeRecipient());
strategy.collectFees();
uint256 feeRecipientBalAfter = IERC20(strategy.token0()).balanceOf(strategy.feeRecipient());
// El feeRecipient NO debería haber recibido fees sobre la donación
uint256 feesOnDonation = feeRecipientBalAfter - feeRecipientBalBefore;
eq(feesOnDonation, 0, "S-08: protocol cobra fees sobre donaciones directas");

// Echidna optimization: maximizar fees perdidas del vestPosition
function optimize_vestFeeLoss() public returns (int256) {
    if (!strategy.ongoingVestingPosition()) return 0;

    // Tomar snapshot antes de collectFees
    uint256 bal0Before = IERC20(strategy.token0()).balanceOf(address(strategy));

    // Llamar collectFees con el bug activo
    strategy.collectFees();

    uint256 bal0After = IERC20(strategy.token0()).balanceOf(address(strategy));

    // Ahora colectar CORRECTAMENTE con los ticks del vestPosition
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    // collectPositionFees(vp.tickLower, vp.tickUpper) -- fees que DEBERÍAN haberse colectado
    // La diferencia es la fee perdida

    // Return negativo para maximizar pérdida
    uint256 collected = bal0After > bal0Before ? bal0After - bal0Before : 0;
    return -int256(collected); // Echidna maximiza -> minimiza fees colectadas
}

