// Verificar que shares emitidas * (bal0 * bal1) == cross * totalSupply (sin perdida)
// Usar ghost para trackear depositos y comparar con valor real
(uint256 bal0, uint256 bal1) = IStrategy(vault.strategy()).balances();
uint256 ts = vault.totalSupply();
if (bal0 > 0 && bal1 > 0 && ts > 0) {
    uint256 dep0 = 1_000_000e6;  // 1M USDC
    uint256 dep1 = 1_000_000e6;  // 1M USDT
    uint256 cross0 = dep0 * bal1;
    uint256 cross1 = dep1 * bal0;
    uint256 cross = cross0 < cross1 ? cross0 : cross1;
    uint256 sharesExpected = cross * ts / bal0 / bal1;
    // Division secuencial: cross/bal0 primero, luego /bal1
    // vs division optima: cross/(bal0*bal1)
    // La diferencia puede ser > 0
    uint256 sharesOptimal = cross * ts / (bal0 * bal1);  // potencial overflow, solo ilustrativo
    // Si sharesExpected > sharesOptimal, hay inflation de shares
    t(sharesExpected <= sharesOptimal + 1, "V-M-01: division secuencial infla shares");
}

// Invariante: shares del primer deposito siempre > 0 sin revert
uint256 amount0 = 999;  // menos de 1000, underflow si amount0 > amount1
uint256 amount1 = 1;
if (vault.totalSupply() == 0) {
    // Si max(amount0, amount1) < 1000, la resta underflowea (Solidity 0.8 = revert)
    // Esto es un DoS del primer deposito
    uint256 maxAmt = amount0 > amount1 ? amount0 : amount1;
    t(maxAmt >= 1000, "V-M-02: primer deposito con max < 1000 revierte por underflow");
}

// Optimizacion: maximizar (withdrawAmount - depositAmount) para el atacante
// Esta funcion la usaria Echidna en modo optimizacion
function optimize_roundTrip(uint256 dep0, uint256 dep1) public returns (int256) {
    dep0 = dep0 % 1e18 + 1;
    dep1 = dep1 % 1e18 + 1;
    uint256 sharesBefore = vault.balanceOf(address(this));
    (uint256 shares, uint256 actual0, uint256 actual1) = vault.deposit(dep0, dep1, 0, 0);
    (uint256 out0, uint256 out1) = vault.withdraw(shares, 0, 0);
    // Positivo = ganancia del atacante (bug), negativo = perdida (correcto)
    return int256(out0) - int256(actual0);
}

