    uint256 bPriceVal = USDC_PRICE; // 1e18 per USDC from Setup
    uint8   dec       = 6;
    // Buggy calculation (as in liquidatePosition line 318)
    uint256 borrowedValueBuggy   = owedAmt * bPriceVal / uint256(dec);
    // Correct calculation
