function property_twap_not_manipulated_during_open() public {
    // The TWAP price and the Chainlink price for the same tokens should agree
    // within a reasonable margin. If they diverge, manipulation may have occurred.
    uint256 twap = vault.twapPrice();  // token0/token1 in PRECISION=1e30
    // Derive implied price from Chainlink: token0price/token1price gives token0-in-token1 terms
    // WBTC price = 100_000e18, USDC price = 1e18
    // implied WBTC/USDC ratio (token0/token1): 100_000e18 / 1e18 = 100_000
    // In 1e30 scale with WBTC=1e8 and USDC=1e6 decimals:
    // price = WBTC_USD_per_unit / USDC_USD_per_unit * (decimals1/decimals0) * PRECISION
    // = 100_000 * (1e6/1e8) * 1e30 = 100_000 * 0.01 * 1e30 = 1000 * 1e30 = 1e33
    uint256 chainlinkImplied = WBTC_PRICE * ONE_USDC * PRECISION_LEVERAGER / (USDC_PRICE * ONE_WBTC);
    // Allow 10% deviation between TWAP and Chainlink-implied price
    uint256 maxDeviation = chainlinkImplied / 10;
    uint256 diff = twap > chainlinkImplied ? twap - chainlinkImplied : chainlinkImplied - twap;
    lte(diff, maxDeviation, "ORH-L-03: TWAP deviates >10% from Chainlink-implied price — possible manipulation");
}

function property_pricefeed_scale_consistent() public {
    // getPrice must return 1e18-scaled USD price to be consistent with
    // how Leverager uses it: initBorrowedUsd = amount * price / (10**decimals)
    // For USDC (6 decimals): 1 USDC = $1 → price = 1e18, amount = 1e6
    // initBorrowedUsd = 1e6 * 1e18 / 1e6 = 1e18 = $1 in 1e18 scale. Correct.
    // For WBTC (8 decimals): 1 WBTC = $100k → price = 100_000e18, amount = 1e8
    // initBorrowedUsd = 1e8 * 100_000e18 / 1e8 = 100_000e18. Correct.
    uint256 usdcPrice = priceFeed.getPrice(address(usdc));
    uint256 wbtcPrice = priceFeed.getPrice(address(wbtc));
    // If price is correct (1e18 scale): 1 USDC = 1e18, 1 WBTC = 100_000e18
    // Check USDC price is in [0.9e18, 1.1e18] (stablecoin range)
    t(usdcPrice >= 9e17 && usdcPrice <= 11e17, "ORH-L-04: USDC price not 1e18-scaled (expected ~1e18)");
    // Check WBTC price is in [1e22, 1e24] (BTC range in 1e18 scale: $10k-$1M)
    t(wbtcPrice >= 1e22 && wbtcPrice <= 1e24, "ORH-L-04: WBTC price not 1e18-scaled (expected ~1e23)");
}

