    // It should NOT panic with arithmetic underflow
    try leverager.withdraw(wp) {
        // OK if it works
    } catch Error(string memory reason) {
        // A named revert is fine
    } catch (bytes memory lowLevelData) {
        // Check it's not an arithmetic panic (0x4e487b71 + 0x11)
        if (lowLevelData.length >= 4) {
            bytes4 sig = bytes4(lowLevelData);
            t(sig != 0x4e487b71, "L-W-05: arithmetic underflow panic in withdraw swap subtraction");
