function property_vesting_fees_use_correct_ticks() public {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;
    // After a rebalance, mainPosition.tickUpper may differ from vestPosition.tickUpper.
    // The bug: collectFees uses mainPosition.tickUpper for the vesting position.
    IStrategy.Position memory mp = strategy.getMainPosition();
    // If they differ, fees from vestPosition are being collected at the wrong range.
    // Property: vestPosition.tickUpper must equal mainPosition.tickUpper OR
    // collectFees must use vestPosition.tickUpper — the current code always uses
    // mainPosition.tickUpper which is wrong after any rebalance.
    t(
        vp.tickUpper == mp.tickUpper,
        "S-DOM-01: vesting tickUpper diverged from mainPosition tickUpper — collectFees will collect from wrong range"
    );
}

function property_balances_includes_vesting() public {
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return;

    (uint256 reported0, uint256 reported1) = strategy.balances();

    (uint160 sqrtPriceX96,,,,,,) = POOL.slot0();
    (uint256 vest0, uint256 vest1) = LiquidityAmounts.getAmountsForLiquidity(
        sqrtPriceX96,
        TickMath.getSqrtRatioAtTick(vp.tickLower),
        TickMath.getSqrtRatioAtTick(vp.tickUpper),
        vp.remainingLiquidity
    );

    // reported balances should be >= the amounts locked in the vesting position
    gte(reported0 + reported1 + 1, vest0 + vest1, "S-DOM-02: balances() understates NAV — vesting position excluded");
}

function property_secondary_always_oor() public {
    IStrategy.Position memory sp = strategy.getSecondaryPosition();
    if (sp.liquidity == 0) return;

    (, int24 currentTick,,,,,) = POOL.slot0();

    // Secondary position must be strictly out-of-range
    bool isOOR = (currentTick < sp.tickLower) || (currentTick >= sp.tickUpper);
    t(isOOR, "S-DOM-03: secondary position is in-range (OOR invariant violated, likely negative tick modulo bug)");
}

function property_withdraw_proportional_including_vesting() public {
    bool ongoing = strategy.ongoingVestingPosition();
    if (!ongoing) return;

    IStrategy.VestingPosition memory vpBefore = strategy.getVestingPosition();
    uint256 supplyBefore = IERC20(address(vault)).totalSupply();
    uint256 userShares = IERC20(address(vault)).balanceOf(user);
    if (userShares == 0 || supplyBefore == 0) return;

    uint256 expectedVestRemoval = uint256(vpBefore.remainingLiquidity) * userShares / supplyBefore;

    vm.prank(user);
    vault.withdraw(userShares, 0, 0);

    IStrategy.VestingPosition memory vpAfter = strategy.getVestingPosition();

    // Vesting remaining liquidity should decrease by approximately user's share
    uint128 actualRemoval = vpBefore.remainingLiquidity - vpAfter.remainingLiquidity;
    // Allow 1 wei rounding
    gte(actualRemoval + 1, uint128(expectedVestRemoval), "S-DOM-04: withdrawPartial did not remove user's vesting share");
}

function property_check_pool_activity_never_reverts() public {
    // checkPoolActivity must never revert — it should return true/false
    // A revert here blocks rebalance, compound, and addVestingPosition
    bool result;
    bool didRevert;
    try strategy.checkPoolActivity() returns (bool r) {
        result = r;
        didRevert = false;
    } catch {
        didRevert = true;
    }
    t(!didRevert, "S-DOM-05: checkPoolActivity() reverted — DoS of all price-gated functions");
}

function property_position_width_only_changed_by_owner() public {
    uint24 widthBefore = strategy.positionWidth();

    // Simulate a rebalancer (non-owner) calling changePositionWidth
    // In a fuzz campaign, if positionWidth changed and caller was not owner, flag it
    uint24 widthAfter = strategy.positionWidth();

    // Ghost-based: track who triggered the last positionWidth change
    // Here we assert the conservative invariant: positionWidth should only
    // be changeable if the transaction originated from owner
    if (widthBefore != widthAfter) {
        // The rebalancer should NOT be able to change this without owner approval
        // This property is violated because changePositionWidth has no onlyOwner
        t(false, "S-DOM-06: positionWidth changed — only owner should be able to do this");
    }
}

function property_protocol_fee_within_bounds() public {
    uint256 feeBps = strategy.protocolFee();
    lte(feeBps, uint256(1500), "S-DOM-07: protocolFee exceeds 15% cap");

    // Additionally: protocol should not be able to charge fee on vesting principal
    // (only on trading fees). This property approximates that by checking the
    // feeRecipient does not receive more than expected.
    uint256 feeRecipient0Before = token0.balanceOf(feeRecipient);
    uint256 feeRecipient1Before = token1.balanceOf(feeRecipient);

    strategy.collectFees();

    uint256 feeRecipient0After = token0.balanceOf(feeRecipient);
    uint256 feeRecipient1After = token1.balanceOf(feeRecipient);

    // Protocol fee should never drain the strategy of all its token0/token1
    uint256 stratBal0 = token0.balanceOf(address(strategy));
    uint256 stratBal1 = token1.balanceOf(address(strategy));

    t(stratBal0 > 0 || stratBal1 > 0, "S-DOM-07: collectFees drained strategy completely");
}

function property_no_funds_stuck_after_full_withdrawal() public {
    uint256 totalSupply = IERC20(address(vault)).totalSupply();
    // Only dust shares remain (the 1000 minted to BURN on first deposit)
    if (totalSupply > 1000) return;

    // After all real shares are redeemed, strategy should hold minimal funds
    uint256 stratBal0 = token0.balanceOf(address(strategy));
    uint256 stratBal1 = token1.balanceOf(address(strategy));

    // Allow some dust (< 1e4 of smallest token unit)
    lte(stratBal0, 1e4, "S-DOM-08: token0 stuck in strategy after full withdrawal");
    lte(stratBal1, 1e4, "S-DOM-08: token1 stuck in strategy after full withdrawal");
}

// Ghost variable to detect reentrancy
bool private _inDeposit;
bool private _inWithdraw;

function invariant_no_reentrancy_deposit_withdraw() public {
    // Before deposit: _inDeposit = false
    // During deposit: _inDeposit = true
    // If withdraw is called while _inDeposit == true, it's reentrancy
    t(!(_inDeposit && _inWithdraw), "FLOW-V-01: reentrancy detected between deposit and withdraw");
}

function property_vesting_fee_tick_consistency() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory main = strategy.getMainPosition();

    // collectFees() uses mainPosition.tickUpper for vesting fee collection.
    // If mainPosition.tickUpper has drifted from vestPosition.tickUpper after a rebalance,
    // the vesting position's fees are collected from the wrong tick range.
    // Property: while vesting is active, mainPosition.tickUpper must equal vestPosition.tickUpper
    // (otherwise collectFees is broken for the vesting position).
    t(
        vp.tickUpper == main.tickUpper,
        "FLOW-01: vestPosition.tickUpper diverged from mainPosition.tickUpper — vesting fee collection targets wrong range"
    );
}

function property_balances_not_understated_during_vesting() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    if (vp.remainingLiquidity == 0) return;

    // balances() should account for ALL strategy assets including vesting position.
    // When remaining vesting liquidity > 0, there are real tokens locked in the pool
    // that balances() does not count.
    // Proxy: after _withdrawPartOfVestingPosition runs (inside collectFees), idle grows.
    // But balances() before collectFees should still reflect the full picture.
    // We check: calling collectFees then balances() produces larger result than
    // calling balances() alone — showing the vesting position was invisible before.
    (uint256 before0, uint256 before1) = strategy.balances();
    strategy.collectFees(); // this drips some vesting into idle
    (uint256 after0, uint256 after1) = strategy.balances();

    // If vesting contributed tokens, after > before
    // (This documents the gap, not necessarily a hard invariant)
    t(
        after0 >= before0 && after1 >= before1,
        "FLOW-02: balances() decreased after collectFees with active vesting — accounting broken"
    );
}

function property_rebalance_preserves_vesting_tick_alignment() public {
    if (!strategy.ongoingVestingPosition()) return;

    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();
    IStrategy.Position memory main = strategy.getMainPosition();

    // After any rebalance, if vesting is still ongoing, the vesting ticks should still
    // align with mainPosition ticks (since collectFees and all fee logic assumes alignment).
    // Violation means the vesting position has been orphaned at old ticks.
    t(
        vp.tickLower == main.tickLower,
        "FLOW-03a: vestPosition.tickLower diverged from mainPosition.tickLower after rebalance"
    );
    t(
        vp.tickUpper == main.tickUpper,
        "FLOW-03b: vestPosition.tickUpper diverged from mainPosition.tickUpper after rebalance"
    );
}

function property_vesting_no_zombie_state() public {
    IStrategy.VestingPosition memory vp = strategy.getVestingPosition();

    // If block.timestamp is past endTs, vesting must be complete
    if (block.timestamp >= vp.endTs && vp.endTs > 0) {
        // After collectFees, should clear
        strategy.collectFees();
        t(!strategy.ongoingVestingPosition(),
          "FLOW-04a: past endTs but ongoingVestingPosition still true after collectFees");
    }

    // If remaining liquidity is 0, the flag must be false
    if (vp.remainingLiquidity == 0 && vp.endTs > 0) {
        strategy.collectFees();
        t(!strategy.ongoingVestingPosition(),
          "FLOW-04b: zombie vesting — remainingLiquidity==0 but ongoingVestingPosition==true");
    }
}

function property_withdraw_receives_proportional_total_assets() public {
    // Deposit as attacker to have 2 users
    deal(address(WBTC), attacker, 1e8);
    deal(address(USDC), attacker, 100_000e6);
    _depositAs(attacker, 1e8, 100_000e6);

    // Add vesting position
    _addVestingPosition(1e8, 100_000e6, 365 days);

    uint256 userShares = _getVaultShares(user);
    uint256 totalSupply = _getVaultTotalSupply();

    // What user SHOULD get: proportional share of ALL strategy assets
    // including vesting position
    (uint256 total0, uint256 total1) = strategy.balances();
    // balances() excludes vesting — this is the reported (understated) total
    uint256 expectedMin0 = total0 * userShares / totalSupply;
    uint256 expectedMin1 = total1 * userShares / totalSupply;

    uint256 pre0 = token0.balanceOf(user);
    uint256 pre1 = token1.balanceOf(user);
    _withdrawAs(user, userShares);
    uint256 got0 = token0.balanceOf(user) - pre0;
    uint256 got1 = token1.balanceOf(user) - pre1;

    // User should get at least the proportional share of reported balances
    gte(got0 + 2, expectedMin0, "FLOW-05: user got less than proportional share of reported balances");
    gte(got1 + 2, expectedMin1, "FLOW-05: user got less than proportional share of reported balances");
}

function property_fee_recipient_receives_cut_of_all_fees() public {
    if (!strategy.ongoingVestingPosition()) return;

    // Cause rebalance to desync vesting ticks
    skip(strategy.rebalanceInterval() + 1);
    vm.prank(rebalancer);
    strategy.rebalance();

    // Generate trading fees via swaps through the vesting position range
    _swapWbtc(1e6);
    _swapUsdc(1_000e6);
    _swapWbtc(1e6);

    uint256 pre0 = token0.balanceOf(feeRecipient);
    uint256 pre1 = token1.balanceOf(feeRecipient);

    strategy.collectFees();

    uint256 got0 = token0.balanceOf(feeRecipient) - pre0;
    uint256 got1 = token1.balanceOf(feeRecipient) - pre1;

    // After swaps, fee recipient should have received something
    // If vesting fees bypass the protocol fee due to wrong tick range, this may be zero
    // even when fees were earned
    t(got0 > 0 || got1 > 0,
      "FLOW-06: fee recipient received nothing after swaps with active vesting position — protocol fees bypassed");
}

