eq(rebaseAmount1, 0, "S-TB-04: token1 is rebasing — idle balance changed without transfer");

// Verify no reentrancy in collectFees via ERC-777 token hook
// _withdrawPartOfVestingPosition has implicit guard: lastUpdate == block.timestamp → return
