int24 mainUpper = strategy.mainPosition().tickUpper;
int24 vestLower = strategy.vestPosition().tickLower;
int24 vestUpper = strategy.vestPosition().tickUpper;
uint128 mainLiq = strategy.mainPosition().liquidity;
uint128 vestLiq = strategy.vestPosition().remainingLiquidity;
