if (strategy.ongoingVestingPosition() && vp.initialLiquidity > 0) {
    uint256 elapsed = block.timestamp - vp.startTs;
    uint256 totalDuration = vp.endTs - vp.startTs;
    uint256 expectedRemaining;
    if (elapsed >= totalDuration) {
        expectedRemaining = 0;
    } else {
        expectedRemaining = uint256(vp.initialLiquidity) * (totalDuration - elapsed) / totalDuration;
    }
    // Allow 1% tolerance for rounding
    uint256 tolerance = uint256(vp.initialLiquidity) / 100;
    gte(uint256(vp.remainingLiquidity) + tolerance, expectedRemaining,
        "S-08: vesting drained faster than linear schedule");
