// INVARIANT: Metadata from domain A must not verify for domain B
function invariant_cross_domain_replay_blocked() public {
    // Setup: two domains with overlapping validators
    bytes memory metadataA = _buildValidMetadata(DOMAIN_A, messageA);
    // Try to verify metadataA against a message from DOMAIN_B
    bytes memory messageB = MessageUtils.build(DOMAIN_B);
    // This should fail because digest is domain-bound
    bool result = routingIsm.verify(metadataA, messageB);
    t(!result, "Cross-domain replay must be rejected");
}

// INVARIANT: Metadata format mismatch should fail-closed (revert or false)
