// INVARIANT: DomainRoutingIsm delegates verify() entirely to child ISM
function invariant_verify_delegates_to_child() public {
    TestIsm childIsm = new TestIsm(abi.encode(bytes32("valid")));
    routingIsm.set(DOMAIN, childIsm);
    bytes memory metadata = abi.encode(bytes32("valid"));
    bytes memory message = MessageUtils.build(DOMAIN);
    // The routing ISM's verify result must match the child's verify result
    bool routingResult = routingIsm.verify(metadata, message);
    bool childResult = childIsm.verify(metadata, message);
    t(routingResult == childResult, "Routing ISM must delegate correctly");
}

// INVARIANT: Circular ISM references must fail-closed (revert), never pass
function invariant_circular_routing_reverts() public {
    DomainRoutingIsm ismA = new DomainRoutingIsm();
    ismA.initialize(address(this));
    DomainRoutingIsm ismB = new DomainRoutingIsm();
    ismB.initialize(address(this));
    ismA.set(DOMAIN, IInterchainSecurityModule(address(ismB)));
    ismB.set(DOMAIN, IInterchainSecurityModule(address(ismA)));
    bytes memory message = MessageUtils.build(DOMAIN);
    // Must revert from infinite recursion
    vm.expectRevert();
    ismA.verify(hex"", message);
}

