function check_ISM_D04_branchRoot_fixed_gas() public {
    // branchRoot always costs the same regardless of inputs
    uint256 gas1 = gasleft();
    MerkleLib.branchRoot(bytes32(0), proof, 0);
    uint256 cost1 = gas1 - gasleft();

    uint256 gas2 = gasleft();
    MerkleLib.branchRoot(bytes32(uint256(1)), proof, type(uint32).max);
    uint256 cost2 = gas2 - gasleft();

    // Gas should be identical (or very close due to memory expansion)
    assert(cost1 == cost2);
}

