function check_ISM_SIG_01() public {
  // With unique validators, duplicate signatures must fail
  // Prepare two identical signatures from validator[0]
  bytes memory sig0 = signDigest(validator0Key, digest);
  bytes memory metadata = abi.encodePacked(
    merkleTreeHook, root, index, sig0, sig0 // same sig twice
  );
  // This should revert because validator0 only appears once
  try ism.verify(metadata, message) returns (bool) {
    t(false, "Duplicate sig with unique validators must fail");
  } catch {
    t(true, "Correctly rejected duplicate signature");
  }
}

function check_ISM_SIG_02() public {
  // OZ ECDSA rejects high-s signatures
  bytes memory malleableSig = createMalleableSig(validSig);
  try ECDSA.recover(digest, malleableSig) returns (address) {
    t(false, "Malleable signature should revert");
  } catch {
    t(true, "OZ ECDSA correctly rejects malleable sig");
  }
}

function check_ISM_SIG_03() public {
  // Metadata with fewer signatures than threshold should revert
  bytes memory shortMetadata = abi.encodePacked(
    merkleTreeHook, root, index, onlySig // only 1 sig, threshold=2
  );
  try ism.verify(shortMetadata, message) returns (bool) {
    t(false, "Short metadata must revert");
  } catch {
    t(true, "Correctly reverted on insufficient signatures");
  }
}

function check_ISM_SIG_04() public {
  // Extra signatures beyond threshold should not affect verification
  bytes memory extraSigMetadata = abi.encodePacked(
    merkleTreeHook, root, index, sig0, sig1, extraSig // 3 sigs, threshold=2
  );
  bool result = ism.verify(extraSigMetadata, message);
  t(result == true, "Extra signatures should not break verification");
}

function check_ISM_SIG_05() public {
  // Same message verified by both ISMs should use compatible but
  // not necessarily identical digests (MerkleRoot adds proof layer)
  bytes32 digestMerkle = AbstractMerkleRootMultisigIsm(mrIsm).digest(metadataMR, message);
  bytes32 digestMsgId = AbstractMessageIdMultisigIsm(miIsm).digest(metadataMI, message);
  // These CAN be equal if the merkle proof resolves to the same root
  // That's by design, not a vulnerability
}

function check_ISM_SIG_06() public {
  // threshold=1 is allowed and is a design choice
  address ism = factory.deploy(validators, 1);
  (address[] memory vals, uint8 thresh) =
    StaticMessageIdMultisigIsm(ism).validatorsAndThreshold(message);
  t(thresh == 1, "Threshold 1 is allowed");
  // Security implication: 1 compromised validator = total compromise
  // But this is by design, not a bug
}

function check_ISM_SIG_07() public {
  // Deploy with duplicate validator
  address[] memory vals = new address[](3);
  vals[0] = ALICE;
  vals[1] = ALICE; // DUPLICATE
  vals[2] = BOB;
  address ism = factory.deploy(vals, 2);

  // Forge message with only Alice's signature (duplicated)
  bytes32 _digest = computeDigest(metadata, message);
  bytes memory aliceSig = sign(ALICE_KEY, _digest);
  bytes memory attackMetadata = buildMetadata(aliceSig, aliceSig); // same sig twice

  // This should NOT pass but DOES pass due to duplicates
  bool result = StaticMessageIdMultisigIsm(ism).verify(attackMetadata, message);
  // If result is true, threshold was effectively reduced from 2 to 1
  t(!result, "Duplicate validators must not allow threshold bypass");
}

// Si revealAndExecute fue llamado, el caller debe ser el router o el ISM
