uint256 routerFeeBalance = feeToken.balanceOf(address(originRouter));
uint256 hookAllowance = feeToken.allowance(address(originRouter), address(originRouter.hook()));
// If router has fee tokens AND hook has unlimited allowance, funds are at risk
