// VV-DD-01: Reserve socialization must not exceed totalLent (prevents liquidation DoS)
uint256 debtRate = vault.lastDebtExchangeRateX96();
uint256 lendRate = vault.lastLendExchangeRateX96();
uint256 Q96_val = 79228162514264337593543950336;
uint256 totalLent = (vault.totalSupply() * lendRate + Q96_val - 1) / Q96_val;
if (totalLent > 0) {
    for (uint256 i = 0; i < ghost_allTokenIds.length; i++) {
