// Invariant: neededAmount computation never silently overflows
// With Solidity 0.8+, this is guaranteed by the compiler
function property_T_M_01() public view returns (bool) {
  // Solidity 0.8 checked arithmetic handles this
  // Any overflow reverts the transaction — no silent wrap
  return true;
}

// Invariant: int256 cast in exactValueSent is safe for practical values
function property_T_M_02(uint256 msgValue, uint256 recipientAmount, uint256 feeAmount) public pure returns (bool) {
  uint256 neededAmount = recipientAmount + feeAmount; // checked
  if (msgValue > neededAmount) {
    uint256 diff = msgValue - neededAmount;
    // This would overflow int256 if diff > type(int256).max
    // But in practice ETH supply << 2^255
    return diff <= uint256(type(int256).max);
  }
  return true;
}

// Invariant: swap return value should equal actual tokens consumed
// amountSwapped = (payerBefore + routerBefore) - (payerAfter + routerAfter)
// This should be <= maxWillingToPay (can't consume more than what was sent)
function property_T_M_03(uint256 amountSwapped, uint256 maxWillingToPay) public pure returns (bool) {
  return amountSwapped <= maxWillingToPay;
}

// Invariant: payerBalanceBefore reconstruction is correct
function property_T_M_04() public view returns (bool) {
  // In a payable function, msg.sender.balance is already reduced by msg.value
  // So balance + msg.value = true pre-tx balance (within same tx)
