function test_DD_T_01_recipient_equals_feeDestination_swap_path() public {
    // Setup: recipient == feeDestination == merchantWallet
    address merchantWallet = makeAddr("merchant");

    vm.prank(operator);
    transfers.registerOperatorWithFeeDestination(merchantWallet);

    // Build intent: recipient = merchantWallet (same as feeDestination)
    TransferIntent memory intent;
    intent.recipientAmount = 100e6;   // 100 USDC
    intent.feeAmount = 5e6;           // 5 USDC
    intent.recipientCurrency = USDC;
    intent.recipient = payable(merchantWallet);  // SAME as feeDestination
    intent.deadline = block.timestamp + 1 hours;
    intent.id = bytes16(uint128(1));
    intent.operator = operator;
    // ... sign intent with operator key ...

    uint256 merchantBefore = IERC20(USDC).balanceOf(merchantWallet);

    // Payer calls swap with ETH → should deliver 105 USDC to merchantWallet
    // But revertIfInexactTransfer will see 105 USDC increase vs expected 5 → REVERT
    vm.expectRevert(abi.encodeWithSelector(ITransfers.InexactTransfer.selector));
    vm.prank(payer);
    transfers.swapAndTransferUniswapV3Native{value: 1 ether}(intent, 500);

    // Verify: no funds moved (tx reverted)
    assertEq(IERC20(USDC).balanceOf(merchantWallet), merchantBefore,
        "DD-T-01: payment should have failed with InexactTransfer");

    // Compare: transferTokenPreApproved (non-swap) WORKS with same recipient==feeDestination
    IERC20(USDC).approve(address(transfers), 105e6);
    transfers.transferTokenPreApproved(intent); // This should succeed
    assertEq(IERC20(USDC).balanceOf(merchantWallet), merchantBefore + 105e6,
        "DD-T-01: non-swap path should work with recipient==feeDestination");
}

function test_DD_T_02_permit_frontrun_grief() public {
    // Setup: Alice wants gasless payment of 105 USDC
    address alice = makeAddr("alice");
    deal(USDC, alice, 200e6);

    // Alice signs EIP-2612 permit
    uint256 aliceNonce = IERC2612(USDC).nonces(alice);
    (uint8 v, bytes32 r, bytes32 s) = vm.sign(
        aliceKey,
        keccak256(abi.encode(
            PERMIT_TYPEHASH, alice, address(transfers),
            105e6, aliceNonce, block.timestamp + 1 hours
        ))
    );
    bytes memory permitSig = abi.encodePacked(r, s, v);

    // Front-runner consumes the permit nonce directly
    address frontRunner = makeAddr("frontRunner");
    vm.prank(frontRunner);
    IERC2612(USDC).permit(alice, address(transfers), 105e6, block.timestamp + 1 hours, v, r, s);

    // Verify nonce incremented
    assertEq(IERC2612(USDC).nonces(alice), aliceNonce + 1, "DD-T-02: nonce should be consumed");

    // Now the relayer tries to execute subsidizedTransferToken
    TransferIntent memory intent = _buildIntentForAlice();
    EIP2612SignatureTransferData memory sigData = EIP2612SignatureTransferData({
        owner: alice,
        signature: permitSig
    });

    // Should revert because permit nonce is already consumed
    vm.expectRevert(); // ERC2612 nonce error
    vm.prank(relayer);
    transfers.subsidizedTransferToken(intent, sigData);

    // Verify Alice's funds are untouched
    assertEq(IERC20(USDC).balanceOf(alice), 200e6, "DD-T-02: Alice funds should be safe");
}

function test_DD_T_03_registerWithZeroFeeDestination() public {
    address operator = makeAddr("operator");

    // Operator registers with address(0) as fee destination
    vm.prank(operator);
    transfers.registerOperatorWithFeeDestination(address(0));

    // OperatorRegistered event was emitted (check in fork test)
    // But the operator is effectively unregistered

    // Build a valid intent signed by this operator
    TransferIntent memory intent = _buildIntent(operator);
    _signIntent(intent, operatorKey);

    // Payment should fail with OperatorNotRegistered despite OperatorRegistered event
    vm.expectRevert(ITransfers.OperatorNotRegistered.selector);
    vm.prank(payer);
    transfers.transferNative{value: 1 ether}(intent);

    // Invariant: if OperatorRegistered was emitted, payments should work
    // VIOLATION: OperatorRegistered(op, address(0)) → payments still fail

    // Compare: unregisterOperator correctly uses OperatorUnregistered event
    vm.prank(operator);
    transfers.registerOperator(); // Fix: register properly
    transfers.unregisterOperator(); // Correctly emits OperatorUnregistered

    // After proper unregister, same revert — but at least event is consistent
    vm.expectRevert(ITransfers.OperatorNotRegistered.selector);
    vm.prank(payer);
    transfers.transferNative{value: 1 ether}(intent);
}

function test_DD_T_04_feeDestination_redirect() public {
    // Setup: operator has 10 USDC fee per payment
    address originalFeeWallet = makeAddr("originalFee");
    address attackerWallet = makeAddr("attacker");

    vm.prank(operator);
    transfers.registerOperatorWithFeeDestination(originalFeeWallet);

    // Operator signs intent (offline simulation)
    TransferIntent memory intent = _buildTokenIntent(
        recipient, 100e6, 10e6, USDC, operator
    );
    _signIntent(intent, operatorKey);

    // Attacker compromises operator key and changes feeDestination
    vm.prank(operator); // attacker using compromised key
    transfers.registerOperatorWithFeeDestination(attackerWallet);

    // Payer executes the original intent (valid signature)
    deal(USDC, payer, 110e6);
    vm.startPrank(payer);
    IERC20(USDC).approve(address(transfers), 110e6);
    transfers.transferTokenPreApproved(intent);
    vm.stopPrank();

    // Fees went to attacker, not original wallet
    assertEq(IERC20(USDC).balanceOf(attackerWallet), 10e6,
        "DD-T-04: fees redirected to attacker");
    assertEq(IERC20(USDC).balanceOf(originalFeeWallet), 0,
        "DD-T-04: original fee wallet received nothing");
    // Recipient still received correctly
    assertEq(IERC20(USDC).balanceOf(recipient), 100e6,
        "DD-T-04: recipient amount unaffected");
}

