function test_DD_T_06_non_ierc7597_token() public {
    // Test with a token that only has EIP-2612 (not IERC7597)
    // USDC uses standard EIP-2612 with v, r, s — not bytes signature

    TransferIntent memory intent = _buildTokenIntent(
        recipient, 100e6, 5e6, USDC, operator  // USDC doesn't support IERC7597
    );
    _signIntent(intent, operatorKey);

    EIP2612SignatureTransferData memory sigData = EIP2612SignatureTransferData({
        owner: payer,
        signature: _buildEIP2612Signature(payer, payerKey, USDC, 105e6)
    });

    // Should revert because USDC doesn't implement IERC7597.permit(bytes)
    vm.expectRevert();
    vm.prank(relayer);
    transfers.subsidizedTransferToken(intent, sigData);

    // Verify no allowance was set (Outcome A protection)
    assertEq(IERC20(USDC).allowance(payer, address(transfers)), 0,
        "DD-T-06: no allowance should be set for non-IERC7597 token");
}
